INSERT INTO `diagnosis_print_templates` (`id`, `modality`, `template_name`, `is_default`, `status`, `page_size`, `page_margin_top_cm`, `page_margin_bottom_cm`, `page_margin_left_cm`, `page_margin_right_cm`, `margin_header_cm`, `margin_footer_cm`, `page_background_image`, `watermark_type`, `watermark_text`, `watermark_image`, `signature_image`, `watermark_alpha`, `header_html`, `first_page_header_html`, `content_prefix_html`, `content_suffix_html`, `footer_html`, `last_page_footer_html`, `patient_info_html`, `mpdf_prefix_html`, `mpdf_suffix_html`, `created_at`, `updated_at`) VALUES
('1', '3', 'Letter Head', '0', '1', 'A4', '1.20', '1.20', '1.00', '1.00', '0.50', '1.50', '', 'none', 'Report', '', NULL, '0.12', '', '', '', 'Doctor Signature', '<div style=\"font-size:11px;border-top:1px solid #333;padding-top:4px;\">Test Footer OK | {PAGENO}/{nbpg} | {{invoice_code}}</div>', '<div style=\"font-size:12px;text-align:right;\"><b>Last Page Signature Area - TEST</b></div>', '', '', '', '2026-03-15 03:51:00', '2026-03-15 04:36:59'),
('2', '5', 'Plain Paper', '1', '1', 'A4', '6.10', '2.50', '0.70', '0.70', '0.50', '1.50', '', 'none', '', '', '', '0.01', '<htmlpageheader name=\"myHeader\">\r\n<table cellspacing=\"0\" style=\"font-size:10px;width:100%;border-style:inset;\">\r\n    <tr>\r\n        <td style=\"width:20%;vertical-align:top;\">\r\n            <img style=\"width:100px;vertical-align:top;\" src=\"{{hospital_logo_url}}\" />\r\n        </td>\r\n        <td style=\"width:60%;vertical-align:top;\">\r\n            <p align=\"center\" style=\"font-size:26px; margin:0;\"><b>{{hospital_name}}</b></p>\r\n            <p align=\"center\" style=\"font-size:14px; margin:0;\">{{hospital_address_1}}<br>{{hospital_phone}}</p>\r\n        </td>\r\n        <td style=\"width:20%;vertical-align:top;text-align:right;\">\r\n            <barcode code=\"{{invoice_code}}\" size=\"0.8\" type=\"QR\" error=\"M\" class=\"barcode\" />\r\n        </td>\r\n    </tr>\r\n</table>\r\n<table cellspacing=\"0\" style=\"width:100%;font-size:10px;border-top:1px solid #999;padding-top:3px;margin-top:3px;\">\r\n    <tr>\r\n        <td style=\"width:50%;vertical-align:top;\">\r\n            <b>Invoice:</b> {{invoice_code}} <br> <b>Patient:</b> {{patient_name}}<br>\r\n            <b>Relative:</b> {{relative}} <br> <b>Age/Sex:</b> {{age_sex}}\r\n        </td>\r\n        <td style=\"width:50%;vertical-align:top;text-align:right;\">\r\n            <b>UHID:</b> {{uhid}}<br>\r\n            <b>Collected:</b> {{collected_time}} <br> <b>Reported:</b> {{reported_time}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n</htmlpageheader>\r\n<sethtmlpageheader name=\"myHeader\" value=\"on\" show-this-page=\"1\" />', '', '', '<p align=\"center\">###################### END OF REPORT ######################</p>', '<htmlpagefooter name=\"myFooter\">\r\n<table width=\"100%\" style=\"font-size:10px;\">\r\n<tr>\r\n    <td width=\"15%\">Page : {PAGENO}/{nbpg}</td>\r\n    <td width=\"85%\" style=\"text-align:right;\">{{report_title}}</td>\r\n</tr>\r\n</table>\r\n</htmlpagefooter>\r\n<sethtmlpagefooter name=\"myFooter\" value=\"on\" />', '<htmlpagefooter name=\"LastPageFooter\">\r\n    <table border=\"0\" style=\"width:100%;font-size:14px;\">\r\n        <tr>\r\n            <td>\r\n            </td>\r\n            <td style=\"text-align:right\"></td>\r\n        </tr>\r\n        <tr>\r\n            <td>\r\n                <b>{{technician_name}}</b>\r\n            </td>\r\n            <td style=\"text-align:right\">\r\n                <b>{{doctor_name}}</b><br/>\r\n                {{doctor_education}}\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"text-align:left;\">\r\n                <br>\r\n                <br>\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n                <br>\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"text-align:left;\">\r\n                Page : {PAGENO}/{nbpg}\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n                {{report_title}}\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</htmlpagefooter>', '', '', '<sethtmlpagefooter name=\"LastPageFooter\" value=\"1\" />', '2026-03-15 04:46:43', '2026-08-03 02:34:15'),
('3', '5', 'Letter Head', '0', '1', 'A4', '6.00', '2.50', '0.70', '0.70', '0.50', '1.50', '', 'none', '', '', '', '0.01', '<htmlpageheader name=\"myHeader\">\r\n\r\n<table cellspacing=\"0\" style=\"width:100%;font-size:10px;border-top:1px solid #999;padding-top:3px;margin-top:3px;\">\r\n    <tr>\r\n        <td style=\"width:50%;vertical-align:top;\">\r\n            <b>Invoice:</b> {{invoice_code}} &nbsp; <b>Patient:</b> {{patient_name}}<br>\r\n            <b>Relative:</b> {{relative}} &nbsp; <b>Age/Sex:</b> {{age_sex}}\r\n        </td>\r\n        <td style=\"width:50%;vertical-align:top;text-align:right;\">\r\n            <b>UHID:</b> {{uhid}}<br>\r\n            <b>Collected:</b> {{collected_time}} &nbsp; <b>Reported:</b> {{reported_time}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n</htmlpageheader>\r\n<sethtmlpageheader name=\"myHeader\" value=\"on\" show-this-page=\"1\" />', '', '', '<p align=\"center\">###################### END OF REPORT ######################</p>', '<htmlpagefooter name=\"myFooter\">\r\n<table width=\"100%\" style=\"font-size:10px;\">\r\n<tr>\r\n    <td width=\"15%\">Page : {PAGENO}/{nbpg}</td>\r\n    <td width=\"85%\" style=\"text-align:right;\">{{report_title}}</td>\r\n</tr>\r\n</table>\r\n</htmlpagefooter>\r\n<sethtmlpagefooter name=\"myFooter\" value=\"on\" />', '<htmlpagefooter name=\"LastPageFooter\">\r\n    <table border=\"0\" style=\"width:100%;font-size:14px;\">\r\n        <tr>\r\n            <td>\r\n            </td>\r\n            <td style=\"text-align:right\"></td>\r\n        </tr>\r\n        <tr>\r\n            <td>\r\n                <b>{{technician_name}}</b>\r\n            </td>\r\n            <td style=\"text-align:right\">\r\n                <b>{{doctor_name}}</b><br/>\r\n                {{doctor_education}}\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"text-align:left;\">\r\n                <br>\r\n                <br>\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n                <br>\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td style=\"text-align:left;\">\r\n                Page : {PAGENO}/{nbpg}\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n                {{report_title}}\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</htmlpagefooter>', '', '', '<sethtmlpagefooter name=\"LastPageFooter\" value=\"1\" />', '2026-08-03 02:19:38', '2026-08-03 02:32:25'),
('4', '3', 'Letter Head', '1', '1', 'A4', '6.10', '2.50', '0.70', '0.70', '0.50', '1.50', '', 'none', '', '', '', '0.12', '', '', '', '', '<p align=\"right\" style=\"font-size: 10px;\">Prescription Generated: {{print_time}}</p>\r\n<p style=\"font-size: 9px;\">Please ensure doctor registration number and signature/stamp are present for regulatory compliance.</p>', '', '', '', '', '2026-08-03 02:40:23', '2026-10-04 11:49:32'),
('5', '3', 'Plain Paper', '0', '1', 'A4', '4.50', '2.50', '0.70', '0.70', '0.50', '1.50', '', 'none', '', '', '', '0.12', '<table cellspacing=\"0\" style=\"font-size: 10px;width:100%;border-style: inset;\">\r\n    <tr>\r\n        <td style=\"width: 120px;vertical-align: top;\">\r\n            <img style=\"width: 100px;vertical-align: top;\" src=\"assets/images/{{H_logo}}\" />\r\n        </td>\r\n        <td style=\"width: 400px;vertical-align: top;text-align: left;\">\r\n            <p align=\"center\" style=\"font-size: 20px;\">{{H_Name}}</p>\r\n            <p align=\"center\" style=\"font-size: 12px\">{{H_address_1}}, {{H_address_2}}<br>\r\n            Phone: {{H_phone_No}}\r\n            </p>\r\n        </td>\r\n        <td style=\"width: 300px;vertical-align: top;text-align: right;\">\r\n            \r\n        </td>\r\n    </tr>\r\n</table>\r\n<hr/>\r\n<table width=\"100%\" style=\"font-size: 12px;font-family: \"freesans\"; border-collapse: collapse;\">\r\n    <tr>\r\n        <td width=\"40%\" valign=\"top\">\r\n            <strong>Name :</strong>  {{patient_name}}<br>{<i>{{relative}}</i>}\r\n            <strong>Gender : </strong>{{gender}}<br>\r\n            <strong>Age :</strong>{{age}}<br>\r\n             <strong>UHID:</strong> {{uhid_no}}<br>\r\n        </td>\r\n        <td width=\"40%\" valign=\"top\">\r\n            <strong>Invoice No.:</strong>  {{invoice_code}}<br/>\r\n            <strong>Image Capture :</strong> {{collected_time}}<br/>\r\n            <strong>Report Time :</strong> {{reported_time}}<br/>\r\n        </td>\r\n        <td width=\"10%\" valign=\"top\">\r\n            \r\n        </td>\r\n    </tr>\r\n</table>', '', '', '', '', '', '', '', '', '2026-08-03 02:40:29', '2026-10-04 11:47:27');
INSERT INTO `disease_master` (`Code`, `Name`, `HCODE`, `Detail1`, `Detail2`, `Familial`, `Congenital`, `Communicable`, `LifeStyle`, `Genetic`, `TypeNotes`, `DiseaseSex`, `DiseaseCategory`, `Notes`, `LastUpdateOn`, `LastUpdateID`, `snomed_concept_id`, `snomed_term`, `is_active`) VALUES
('3', 'ACNE', '0', '', '', '0', '0', '0', '0', '0', '', 'B', '0', '1. TOPICAL AGENTS LIKE :\r\n\r\n- RETINOIC ACID\r\n-BENZOYL PEROXIDE\r\n- SALICYLIC ACID\r\n\r\n2. TOPICAL ANTIBIOTICS :\r\n\r\n- CLINDAMYCIN\r\n- ERYTHROMYCIN\r\n- FUCIDIC ACID\r\n- AZELAIC ACID\r\n- BENZOYL PEROXIDE\r\n\r\n3. SYSTEMIC ANTIBIOTICS :\r\n\r\n- TETRACYCLINES\r\n- MACROLIDES\r\n\r\n4. HORMONAL THERAPY : WOMEN WHO DOES NOT RESPOND TO THESE THERAPIES MAY RESPOND TO ORAL CONTRACEPTIVES CONTAINING ETHINYL ESTRADIOL & NORGESTIMATE\r\n\r\n5. ISOTRETINOIN : SHOULD BE USED WITH CAUTION BY EXPERTS ONLY AS IT IS TERATOGENIC.', NULL, NULL, NULL, NULL, '1'),
('4', 'ADDISON’S DISEASE', '0', 'CAUSES :\r\n\r\n- IDIOPATHIC AUTOIMMUNE ADRENOCORTICAL INSUFFICIENCY DUE  * AUTOIMMUNE ATROPHY\r\n* FIBROSIS\r\n* LYMPHOCYTIC INFILTRATION OF ADRENAL CORTEX\r\n* TUBERCULOSIS\r\n\r\n- HEREDITARY PREDISPOSITION TO AUTOIMMUNE ADDISON DISEASE\r\n\r\n- IDIOPATHIC AUTOIMMUNE ADDISON DISEASE IN ASSOCIATION WITH OTHER AUTOIMMUNE PHENOMENA LIKE\r\n\r\n* SCHMIDT SYNDROME\r\n* POLYGLANDULAR AUTOIMMUNE DISEASE 1 & 2\r\n* IDIOPATHIC HYPOPARATHYROIDISM\r\n* MUCOCUTANEOUS CANDIDIASIS\r\n* TYPE I DIABETES MELLITUS\r\n* HASHIMOTO THYROIDITIS\r\n* GRAVES DISEASE\r\n* VITILIGO\r\n* ALOPECIA AREATA, TOTALIS & UNIVERSALIS\r\n* PREMATURE OVARIAN OR TESTICULAR FAILURE\r\n* PERNICIOUS ANEMIA\r\n* MYASTHENIA GRAVIS\r\n* IDIOPATHIC HYPOPHYSITIS\r\n* CHR ACTIVE HEPATITIS\r\n* PRIMARY BILIARY CIRRHOSIS\r\n\r\n- CHR GRANULOMATOUS DISEASES\r\n\r\n* TUBERCULOSIS\r\n* SARCOIDOSIS\r\n* HISTOPLASMOSIS\r\n* BLASTOMYCOSIS\r\n* CRYPTOCOCCOSIS\r\n\r\n- HEMATOLOGIC MALIGNANCIES\r\n\r\n* MALIGNANT INFILTRATION IN HODGKINS & NON HODGKINS LYMPHOMA, LEUKEMIA\r\n* METASTATIC DISEASE INVOLVEMENT\r\n\r\n- INFILTRATIVE METABOLIC DISORDERS \r\n\r\n* AMYLOIDOSIS\r\n* HEMOCHROMATOSIS\r\n\r\n- ACQUIRED IMMUNE DEFICIENCY SYNDROME\r\n\r\n* AIDS WITH OPPORTUNISTIC BACTERIAL INFECTION\r\n* GLUCOCORTICOID RESISTANCE SYNDROME\r\n* AIDS PATIENT WITH MEGESTROL USE AS APPETITE STIMULANT\r\n\r\n- ALLGROVE SYNDROME\r\n\r\n- ABNORMALITIES OF BETA OXIDATION OF VERY LONG CHAIN FATTY ACIDS LIKE\r\n\r\n* ADRENOLEUKODYSTROPHY\r\n* ADRENOMYELONEUROPATHY\r\n\r\n- CONGENITAL ADRENAL HYPERPLASIA\r\nDUE TO \r\n* 20,22 DESMOLASE ENZYME DEFICIENCY\r\n* 3-BETA HYDROXYSTEROID DEHYDROGENASE DEFICIENCY\r\n* 21-HYDROXYLASE ENZYME DEFICIENCY\r\n\r\n- DRUG INDUCED \r\n\r\n* KETOCONAZOLE\r\n* AMINOGLUTETHIMIDE\r\n* MITOTANE\r\n* BUSULPHAN, ETOMIDATE, TRILOSTANE\r\n* METHADONE\r\n\r\n- IRRADIATION\r\n\r\n--------------------------------------------------------------------------\r\nCAUSES OF ACUTE ADDISON DISEASE\r\n\r\n- STRESS LIKE INFECTION, TRAUMA, SURGERY, EMOTIONAL TURMOIL\r\n- FAILURE TO INCREASE STEROID DOSE IN REPLACEMENT THERAPY\r\n- BILATERAL ADRENAL HAEMORRHAGE\r\n- BILATERAL ADRENAL ARTRY EMBOLI & BILATERAL VEIN THROMBOSIS\r\n- BILATERAL ADRENALECTOMY FOR ANY REASON', 'OTHER TESTS - \r\n* ACTH STIMULATION TEST - POSITIVE ( NORMAL ADRENALS RELEASE 2 - 5 TIMES ITS BASAL PLASMA CORTISOL OUTPUT\r\n* SERUM SOD., CHLORIDE & BICARBONATES - DECREASED\r\n* SERUM POTASSIUM - INCREASED\r\n* PLASMA CORTISOL & ALDOSTERONE - DECREASED & FAIL TO INCREASE ON ACTH STIMULATION\r\n* PLASMA ACTH LEVELS\r\n* SERUM CATECHOLAMINES\r\n* RAPID ACTH TEST - PATIENT WITH CONGENITAL ADRENAL HYPERPLASIA RESPOND WITH MARKED INCREASE IN 17-HYDROXY PROGESTERONE LEVELS & SUBNORMAL CORTISOL RESPONSE\r\n* RANDOM PLASMA CORTISOL LEVELS - >25 MCG/DL  EXCLUDES ADRENAL INSUFFICIENCY \r\n* URINARY & SWEAT SODIUM - MAY BE ELEVATED\r\n* BUN & SERUM CREATININE - ELEVATED DUE TO HYPOVOLEMIA\r\n* ADRENAL AUTOANTIBODIES - MAY BE PRESENT', '0', '0', '0', '0', '0', '', 'B', '0', 'In patients in acute adrenal crisis, IV access should be established urgently, and an infusion of isotonic sodium chloride solution should be begun to restore volume deficit and correct hypotension. Some patients may require glucose supplementation. The precipitating cause should be sought and corrected where possible.\r\n\r\nIn stress situations, the normal adrenal gland output of cortisol is approximately 250-300 mg in 24 hours. This amount of hydrocortisone in soluble form (hydrocortisone sodium succinate or phosphate) should be given, preferably by continuous infusion. \r\n\r\nAdminister 100 mg of hydrocortisone in 100 cc of isotonic sodium chloride solution by continuous IV infusion at a rate of 10-12 cc/h. Infusion may be initiated with 100 mg of hydrocortisone as an IV bolus. \r\n\r\nAn alternative method of hydrocortisone administration is 100 mg as an IV bolus every 6-8 hours. \r\n\r\nThe infusion method maintains plasma cortisol levels more adequately at steady stress levels, especially in the small percentage of patients who are rapid metabolizers and who may have low plasma cortisol levels between the IV boluses. \r\n\r\nClinical improvement, especially blood pressure response, should be evident within 4-6 hours of hydrocortisone infusion. Otherwise, the diagnosis of adrenal insufficiency would be questionable. \r\n\r\nAfter 2-3 days, the stress hydrocortisone dose should be reduced to 100-150 mg, infused over a 24-hour period, irrespective of the patient\'s clinical status. This is to avoid stress gastrointestinal bleeding. \r\n\r\nAs the patient improves and as the clinical situation allows, the hydrocortisone infusion can be gradually tapered over the next 4-5 days to daily replacement doses of approximately 3 mg/h (72-75 mg over 24 h) and eventually to daily oral replacement doses, when oral intake is possible. \r\n\r\nAs long as the patient is receiving 100 mg or more of hydrocortisone in 24 hours, no mineralocorticoid replacement is necessary. The mineralocorticoid activity of hydrocortisone in this dosage is sufficient. \r\n\r\nThereafter, as the hydrocortisone dose is weaned further, mineralocorticoid replacement should be instituted in doses equivalent to the daily adrenal gland aldosterone output of 0.05-0.20 mg every 24 hours. The usual mineralocorticoid used for this purpose is 9-alpha-fludrocortisone, usually in doses of 0.05-0.10 mg per day or every other day. \r\n\r\nPatients may need to be advised to increase salt intake in hot weather. \r\n\r\nSurgical Care\r\n\r\nParenteral steroid coverage should be used in times of major stress, trauma, or surgery and during any major procedure. \r\n\r\nDuring surgical procedures, 100 mg of hydrocortisone should be given, preferably by the IM route, prior to the start of a continuous IV infusion. The IM dose of hydrocortisone assures steroid coverage in case of problems with the IV access. \r\n\r\nWhen continuous IV infusion is not practical, an intermittent IV bolus injection every 6-8 hours may be used. \r\nAfter the procedure, the hydrocortisone may be rapidly tapered within 24-36 hours to the usual replacement doses, or as gradually as the clinical situation dictates. \r\n\r\nMineralocorticoid replacement usually can be withheld until the patient resumes daily replacement steroids. \r\n', NULL, NULL, NULL, NULL, '1'),
('14', 'AMOEBIASIS', '0', '', 'OTHER TESTS :\r\n* SEROLOGICAL TEST FOR AMOEBA > 90% ACCURACY\r\n* IODINE STAINED CONCENTRATES OF STOOL FOR AMOEBA OR CYSTS\r\n* PCR \r\n* STOOL CULTURE FOR AMOEBA', '0', '0', '0', '0', '0', NULL, 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('25', 'ANKYLOSING SPONDYLITIS', '0', 'D.D. :\r\n\r\n- LUMBER DISC DISEASE\r\n- LUMBER SPONDYLOSIS\r\n- PSORIATIC ARTHRITIS\r\n- REACTIVE ARTHRITIS\r\n- REITER SYNDROME', 'OTHER TESTS :\r\n* HLA-B 27 GENE PRESENT IN > 90% OF PATIENTS\r\n* ESR , C-REACTIVE PROTEIN , SERUM IGA LEVELS - RAISED\r\n* IN PATIENTS WITH RESTRICTIVE CHEST MOVEMENTS - VITAL CAPACITY- DECREASED , FUNCTIONAL RESIDUAL CAPACITY - INCREASED, AIRFLOW MEASUREMENTS & VENTILATORY FUNCTION - NORMAL.\r\n* ANA , RA FACTOR - ABSENT\r\n* X-RAY FINDINGS - SACROILITIS ( BLURRING OF THE CORTICAL MARGINS OF THE SUBCHONDRAL BONE ) , STRAIGHTENING OF LUMBER SPINE, REACTIVE SCLEROSIS, SQUARING OF VERTIBRAL BODIES, MARGINAL SYNDESMOPHYTES\r\n* CT SCAN & MRI MAY DETECT EARLIST CHANGES IN THE SPINE OR SACROILIAC JOINT.', '0', '0', '0', '0', '0', 'RISK FACTORS : FIRST DEGREE RELATIVE WITH AS INCREASES A PATIENTS RISK BY 5 TO 16 FOLDS. HLA-27 POSITIVE CHILDREN WHO HAVE SIBLINGS WITH AS HAVE A 10-20% RISK OF GETTING AS. MALES HAVE HIGHER RISK OF AS.', 'B', '0', 'Medical Care: Treatment of ankylosing spondylitis is divided into medical care, physical therapy, and surgical care. Patient education is important in the management of any chronic disease so that the patient is familiar with the symptoms, course, and treatment of the disease. No drugs have been proven to modify the course of the disease, although TNF-  antagonists have potential as disease-modifying agents. \r\n\"	Nonsteroidal anti-inflammatory drugs \r\no	NSAIDs improve the symptoms of the disease. Indomethacin may be more effective than other NSAIDs, although this has not been proven. \r\no	Salicylates seldom give adequate relief. Cyclooxygenase-2 (COX-2) inhibitors appear to be as effective as nonselective NSAIDs. \r\no	Give NSAIDs in full anti-inflammatory doses. Continuous treatment with NSAIDs appears to reduce radiographic progression in ankylosing spondylitis. Common toxicities involve the gastrointestinal (nausea, dyspepsia, ulceration, bleeding), renal, and central nervous systems. \r\n\"	Sulfasalazine \r\no	Sulfasalazine is often used in the treatment of ankylosing spondylitis and other spondyloarthropathies (SpAs), especially for peripheral joint involvement, for which it has demonstrated efficacy. Sulfasalazine has been shown to be effective in ankylosing spondylitis, particularly in reducing spinal stiffness, peripheral arthritis, and reducing the ESR, but no evidence shows that spinal mobility, enthesitis, or physical function is benefited. \r\no	Toxicities include rash, nausea, diarrhea, and agranulocytosis (rarely). \r\n\"	Other medications \r\no	Anecdotal reports suggest that other medications are helpful in the treatment of ankylosing spondylitis, including methotrexate, azathioprine, cyclophosphamide, and cyclosporine. \r\no	Methotrexate may have some benefit in ankylosing spondylitis, although various studies have shown conflicting results. \r\no	The TNF-  antagonists have been shown to be effective in the treatment of ankylosing spondylitis, and etanercept, infliximab, and adalimumab are approved therapies. These agents are very effective with fairly rapid onset of action (2 wk) and have been shown to reduce inflammatory activity of spinal disease as assessed with MRI. \r\no	Bisphosphonates may modestly affect clinical disease activity in ankylosing spondylitis. \r\no	Anakinra, a recombinant human interleukin 1 (IL-1) receptor antagonist, may be effective in treatment-resistant ankylosing spondylitis.\r\n\"	Corticosteroids \r\no	Oral corticosteroids occasionally are helpful in controlling symptoms; however, use them only for short-term management. No evidence exists that corticosteroids alter the outcome of the disease, and they increase the tendency towards spinal osteoporosis. \r\no	Local corticosteroid injections are useful for symptomatic sacroiliitis, peripheral enthesitis, and arthritis, although the response typically is not as rapid as in patients with rheumatoid arthritis. \r\n\"	Treatment of extra-articular manifestations \r\no	Treat extra-articular manifestations as dictated by the clinical setting. \r\no	Acute anterior uveitis presents as a painful, red eye that is associated with photophobia and often recurs. Untreated uveitis may lead to vision loss.\r\no	Evaluation and treatment of uveitis should be delivered under the guidance of an ophthalmologist. Generally, patients respond well to topical corticosteroids, mydriatics, and artificial tears, with resolution of the attack over 2-3 months. Treatment may occasionally require topical NSAIDs, retrobulbar corticosteroid injections, or immunosuppressive drugs. TNF-  antagonists may be helpful in selected cases.\r\nSurgical Care: \r\n\"	Surgery occasionally is useful to correct spinal deformities or repair damaged peripheral joints.\r\n\"	Vertebral osteotomy may be performed to correct spinal deformities, but significant morbidity is related to neurologic complications of this procedure. This procedure should be performed only by surgeons specializing in spine surgery who have experience with this procedure, as the risk of major neurologic morbidity is significant.\r\n\"	Patients may need total hip replacement and, occasionally, total shoulder replacement. These procedures may be very useful to reduce pain and improve function when the hip and shoulder joints become severely damaged. Heterotopic bone formation may occur after total joint replacement, especially around the hip. Heterotopic bone formation can be reduced by using postoperative NSAIDs (eg, indomethacin). In general, outcomes of total joint replacement in patients have been satisfactory.\r\nDiet: \r\n\"	No special diet is required.\r\nActivity: \r\n\"	Physical therapy\r\no	Physical therapy, including an exercise program and postural training, is important to maintain function.\r\no	Spinal extension and deep-breathing exercises help maintain spinal mobility, encourage erect posture, and promote chest expansion. Maintaining an erect posture during daily activities and sleeping on a firm mattress with a thin pillow also tend to reduce the tendency towards thoracic kyphosis.\r\no	Water therapy and swimming are excellent activities to maintain mobility and fitness.\r\n\r\n- ENCOURAGE TO STOP SMOKING DUE TO POSSIBLE LUNG ENVOLVEMENT\r\n- PROPHYLACTIC TREATMENT FOR OSTEOPOROSIS\r\n- ANTIBIOTIC PROPHYLAXIS IN CARDIAC VALVE ENVOLVEMENT PATIENTS.\r\n- PAMIDRONATE & THALIDOMIDE MAY BE OF SOME BENEFIT IN MUSCULOSKELETAL SYMPTOMS.', NULL, NULL, NULL, NULL, '1'),
('36', 'ARRHYTHMIAS, ATRIAL FIBRILLATION', '0', 'CAUSES :\r\n* IN NORMAL SUBJECTS DUE TO \r\n- ADVANCED AGE\r\n- EMOTIONAL STRESS\r\n- FOLLOWING SURGERY, EXERCISE\r\n- AC ALCOHOLIC INTOXICATION\r\n- VASOVAGAL RESPONSE\r\n\r\n* IN PTS. WITH HEART & LUNG DISEASE WHO DEVELOP AC HYPOXIA, HYPERCAPNIA OR METABOLIC OR HAEMODYNAMIC DERANGEMENTS\r\n* RHEU. HEART DISEASE LIKE MITRAL STENOSIS\r\n* NONRHEUMATIC MITRAL VALVE DISEASE\r\n* HYPERTENSION\r\n* CHR LUNG DISEASE\r\n* ATRIAL SEPTAL DEFECT\r\n* THYROTOXICOSIS MAINLY TOXIC GOITER\r\n* FOLLOWING AC M.I.\r\n* CONSTRICTIVE PERICARDITIS\r\n* CARDIOMYOPATHY\r\n* IDEOPATHIC OR LONE ATRIAL FIBRILLATION\r\n* PULMONARY EMBOLISM\r\n* SICK SINUS SYNDROME\r\n* ELECTRIC SHOCK\r\n* HYPOTHERMIA\r\n* ILLICIT NARCOTIC ABUSE\r\n* CHF\r\n* CORONARY ARTRY DISEASE\r\n* INFILTRATIVE HEART DISEASE', '• Ventilation-perfusion scan or pulmonary angiography if pulmonary embolus suspected\r\n• Transesophageal echocardiography may be useful in detecting left atrial appendage thrombus and therefore risk of stroke with cardioversion', '0', '0', '0', '0', '0', 'RISK FACTORS: Hypertension, Diabetes mellitus, Left ventricular hypertrophy, Coronary artery disease, Congestive heart failure, Rheumatic heart disease', 'B', '0', 'STROKE IS MAJOR COMPLICATION OF AF. CLINICAL TRIALS HAVE SHOWN THAT ANTICOAGULATION WITH WARFARIN DECREASES THE RISK BY 50-80%\r\n\r\n\r\nMedical Care: The initial goal in the management of AF is rate control and anticoagulation, with an eventual goal of restoration and maintenance of sinus rhythm. However, few prospective, randomized controlled trial data are available to indicate to the clinician whether patients with symptomatic or asymptomatic AF do better simply with rate control and anticoagulation or with aggressive attempts to maintain sinus rhythm with repeated electrical cardioversion and antiarrhythmic agents. \r\nRestoration of sinus rhythm with regularization of the heart\'s rhythm improves cardiac hemodynamics and quality of life and reduces the risk of thromboembolic complications. Additional benefits include maintaining the appropriate physiologic responses to exercise and the atrial contribution to the cardiac output, thus preventing atrial dilation and possible LV dysfunction. Thus, most clinicians initially focus on rhythm control, and rate control is pursued only when rhythm control fails. \r\nTwo randomized controlled trials have demonstrated that a strategy aimed at restoring (and maintaining) sinus rhythm neither improves the survival rate nor reduces the risk of stroke. In the Atrial Fibrillation Follow-up Investigation of Rhythm Management (AFFIRM) study, 4060 subjects aged 65 years or older whose atrial fibrillation was likely to be recurrent and who were at risk for stroke were randomized to a strategy of rhythm control (cardioversion to sinus rhythm plus drugs to maintain sinus rhythm) versus a strategy of rate control (in which no attempt was made to restore or maintain normal sinus rhythm). An insignificant trend toward increased mortality was noted in the rate-control group, and, importantly, no evidence suggested that the rhythm-control strategy protected patients from stroke. \r\nThe AFFIRM study (and similar findings from the smaller Rate Control Versus Electrical Cardioversion [RACE] trial) has led to the development of consensus guidelines advocating a rate-control strategy for most atrial fibrillation patients. Thus, rhythm control may be a desirable pursuit in patients who become symptomatic during episodes of AF. The importance of anticoagulation with warfarin with a target INR 2-3 was underscored. \r\nWith the goal of maintaining sinus rhythm and preventing AF, new therapies are being actively explored, including single- and dual-site atrial-based pacing to prevent AF and atrial defibrillators to restore sinus rhythm soon after a spontaneous episode. Surgical and catheter-based therapies to compartmentalize the atria and localize focal triggers (in the pulmonary veins) are being evaluated and refined. \r\n\"	Rate control \r\no	Beta-blockers and calcium channel blockers are the drugs of choice for rate control. These drugs can be administered intravenously and orally. They are effective at rest and with exertion. Caution should be exercised in patients with reactive airway disease given beta-blockers. \r\no	Digoxin can be used in the acute setting but does little to control the ventricular rate in active patients. In addition, it has no antiarrhythmic effects and actually may promote AF by shortening atrial refractory periods. Digoxin is indicated in patients with reduced LV function. \r\n\"	Anticoagulation \r\no	AF is recognized as a powerful risk factor for stroke. One of the most important concerns in treating patients is the need for anticoagulation. Effective anticoagulation in patients with AF reduces the risk of stroke 3-fold. Patients with newly diagnosed AF and patients awaiting electrical cardioversion can be started on intravenous heparin (activated partial thromboplastin time [aPTT] of 45-60 seconds). \r\no	Patients can be concomitantly started on warfarin in an inpatient setting while awaiting a therapeutic INR value (2-3). Many practices have developed specialized anticoagulation clinics to closely monitor INR values. \r\no	In the future, low-molecular-weight heparins will be used to facilitate initial outpatient anticoagulation until warfarin is therapeutic. Studies are currently being conducted to assess feasibility and safety.\r\n\"	Long-term prophylaxis \r\no	Patients have a risk of stroke or peripheral embolism that is approximately 5 times that of people in sinus rhythm. This risk can be reduced greatly with warfarin. \r\n\"	Stroke Prevention Using Oral Thrombin Inhibitor in Atrial Fibrillation (SPORTIF) III and V trials were trials performed in Europe (SPORTIF III) and in North America (SPORTIF V). Both were noninferiority trials. By definition, noninferiority trials intend to show that an experimental treatment (ximelagatran) does not produce worse results than those of a known active control (warfarin) by a specified margin (2% per year). \r\n\"	SPORTIF III was reported in The Lancet in November 2003. It was a phase 3, multicenter, randomized, controlled clinical trial that compared warfarin to ximelagatran in the treatment of 3410 subjects with AF and one or more stroke factors. The primary endpoint was stroke or systemic embolism. The primary event rate by intention to treat was 2.3% per year for warfarin and 1.6% for ximelagatran (absolute risk reduction, 0.7%; relative risk reduction, 29%). Rates of disabling or fatal stroke, mortality, and major bleeding were similar, but the rate of combined minor and major hemorrhages was 29.8% per year for warfarin and 25.8% for ximelagatran (relative risk reduction, 14%; P = .007). Raised serum alanine aminotransferase (ALT) levels were more commonly observed in the ximelagatran group. \r\n\"	SPORTIF V was reported in the American Heart Journal in September 2003 and at the American Heart Association Scientific Sessions in November 2003. This study included a double-blinded treatment allocation with 3922 subjects. Again, the primary endpoints were strokes and systemic embolic events with a noninferiority treatment objective compared with warfarin. The study commenced in July 2000 and enrollment ended in December 2001. Data analysis was extensive and included safety monitoring. The primary event rate by intention to treat was 1.2% per year for warfarin and 1.6% for ximelagatran. The ximelagatran rate was identical in the 2 studies, whereas the rate for warfarin in SPORTIF V was half that noted in SPORTIF III. The reasons for this difference in the warfarin groups continue to be evaluated. \r\n\"	In both studies, the rates of intracranial and/or other major bleeding events were insignificant. However, when the event rates for major and minor bleeding are combined, ximelagatran was significantly better than warfarin (P <.001 and P <.007, respectively). Elevated ALT levels were noted in SPORTIF III and V and in all previously conducted long-term ximelagatran trials. These elevations are transient, and the levels return to normal regardless of whether the drug is discontinued. It appears that the ALT elevation is limited to the first 6 months of treatment with ximelagatran.\r\no	Patients with no structural heart disease and patients younger than 65 years have lone AF and an extremely low risk for stroke. Generally, they do not need anticoagulation. Aspirin (ASA) at 325 mg/d is recommended. \r\no	The combination of age and identifiable risk factors compounds the risk of embolization and stroke. Established risk factors include prior stroke or transient ischemic attack, diabetes, hypertension, CAD, mitral stenosis, prosthetic valve, CHF, echocardiographic findings of an enlarged left atrium, and global LV dysfunction. The following is a summary of the current recommendations regarding anticoagulation in the treatment of AF: \r\n\"	Patients younger than 65 years with risk factors receive warfarin therapy with a goal INR of 2-3. \r\n\"	Patients younger than 65 years with no risk factors receive ASA therapy or no treatment. \r\n\"	Patients older than 65 years receive warfarin therapy with a goal INR of 2-3. \r\n\"	Patients older than 75 years with no risk factors receive ASA therapy.\r\n\"	Acute conversion to sinus rhythm \r\no	The decision to restore sinus rhythm acutely depends on the hemodynamic status of the patient. \r\no	Consideration of impending hemodynamic collapse or acute cardiac ischemia may influence the decision to cardiovert immediately. \r\n\"	Elective conversion to sinus rhythm \r\no	Exactly how long AF must be present before the risk of atrial thrombus and subsequent thromboembolism develops is uncertain. Certainly, the longer patients are in AF, the more likely they are to develop atrial thrombus. In general, if the arrhythmia is present for less than 48 hours, cardioversion can be accomplished safely without further need for anticoagulation. If uncertain, a TEE could be performed to exclude left atrial thrombus. In any case, acute conversion must be accompanied by anticoagulation. \r\no	In patients with AF longer than 48 hours in duration or of unknown duration, cardioversion is not recommended until sufficient anticoagulation is achieved. The most conservative route is to anticoagulate with warfarin (INR of 2-3) for 3-4 weeks prior to any attempt to restore sinus rhythm. \r\no	Because embolic events can occur following cardioversion as atrial mechanical function returns, continue anticoagulation for an additional 4-6 weeks. Alternatively, initially perform a TEE, and if no thrombus is present, cardiovert and therapeutically anticoagulate for 4-6 weeks after sinus rhythm is restored. \r\n\"	Pacing to prevent AF \r\no	The fact that ventricular-based pacing (VVI mode) does not prevent AF in patients with sick sinus syndrome is well documented. Retrospective data suggest that atrial-based pacing (AAI, DDD modes) reduces the risk of developing AF and increases the interval between episodes in patients with sick sinus syndrome. \r\no	In addition, biatrial pacing and dual-site atrial pacing may reduce the prevalence of AF. This is currently an active area of research. Which areas are the best for lead placement (ie, high right atrial, coronary sinus, left atrial sites) remain unknown. \r\n\"	Atrial defibrillators\r\no	Early conversion to sinus rhythm is desirable because patients do not require long-term anticoagulation. AF-free intervals have been shown to be prolonged with early AF termination.\r\no	Defibrillation energy requirements can be higher than the patient\'s pain threshold. This can represent a problem in some patients. Painless therapy (eg, atrial burst pacing to extinguish AF) is successful approximately 20% of the time, making this form of therapy desirable in patients with poorly tolerated AF.\r\no	In addition, the next generation of ventricular defibrillators incorporates atrial defibrillation therapies. Patients with reduced LV function and a tendency toward heart failure with episodes of AF will benefit greatly from early conversion to sinus rhythm.\r\nSurgical Care: Since its inception, surgical compartmentalization of the atria, or the Maze procedure, has evolved as an exciting procedure with a potential to cure AF. Quite simply, the atria are transected and resutured to reduce the critical mass required for the maintenance of AF. Early experience shows that atrial transport is restored postoperatively and that long-term anticoagulation is not required. The downside remains the need for an open chest procedure; however, thoracoscopic procedures may reduce hospitalization and recovery times in the future. The surgical Maze procedure remains an attractive procedure for patients with AF who are undergoing concomitant mitral valve procedures. Its role as a primary therapy for AF is doubtful. Catheter ablation has taken the following 3 paths in the attempt to cure or manage AF. \r\n\"	Compartmentalization of the atria with continuous ablation lines of block\r\no	Parallel to the surgical Maze procedure, electrophysiologists are attempting to recreate surgical suture lines with radiofrequency lesions (still investigational).\r\no	The procedures tend to be many hours in duration, and the success rates are somewhat disappointing, with left atrial reentrant tachycardias appearing (requiring further ablation procedures).\r\no	Researchers are unsure which areas of the atria are necessary to sustain AF. Purely right-sided lesions are not sufficient to eliminate AF, making left atrial procedures necessary. In addition, gaps in linear lesions can be difficult to find.\r\no	Research currently focuses on catheter designs to deliver linear continuous lesions in both atria.\r\n\"	Catheter ablation of focal triggers of AF\r\no	In some patients, AF seems to be triggered by foci, usually located within the superior pulmonary veins. These foci can trigger the atria to fibrillate. \r\no	Patients typically have an abundance of ectopic atrial beats noted on 24-hour Holter monitoring. Isolation of the ectopic focus is performed successfully at many centers, and patient selection is key to success. \r\no	Complications are generally in the 5% range and include pulmonary vein stenosis (that can be symptomatic), perforation, thromboembolism, and tamponade. Still, cure rates as high as 70-80% have been reported in properly selected patients (patients with frequent atrial premature beats and episodes of paroxysmal AF).\r\n\"	Atrioventricular node ablation and insertion of a permanent pacemaker\r\no	AV node ablation may represent an alternative in patients with chronic AF and an uncontrolled ventricular response despite aggressive medical therapy.\r\no	Catheter ablation of the AV junction permanently interrupts conduction from the atria to the ventricles. \r\no	Because the result is permanent AV block, a permanent pacemaker is required. AF may still exist, but the pacemaker governs the ventricular response. \r\no	The risk of thromboembolism is unchanged, and patients still require anticoagulation; however, most patients are relieved of their symptoms. \r\no	During the first 1-3 months, the pacing rate must be programmed in the 80- to 90-beat range to prevent TdP, which has been reported in the literature, presumably due to slow ventricular rates and the occurrence of early after-depolarizations. \r\no	Improvements in LV size and function, functional class, and quality-of-life scores have been demonstrated.\r\n\r\nDiet: \r\n\"	Diet restrictions, if any, are as appropriate for the underlying heart disease and any other comorbidities (eg, diabetes mellitus).\r\n\r\nMEDICATION :\r\n\r\nThe goals of medical therapy are to maintain sinus rhythm, avoid the risk of complications (eg, stroke), and minimize patient symptoms. Warfarin represents the cornerstone of anticoagulant therapy for patients in chronic AF or those awaiting conversion to sinus rhythm. The goal of antiarrhythmic drug therapy is reducing the duration and frequency of episodes, thus improving the quality of life and eliminating the need for long-term anticoagulation, which decreases the potential risk of serious bleeding. \r\nAntiarrhythmic agents are commonly used to prevent AF recurrence. Currently, the FDA has approved 5 antiarrhythmic drugs for the treatment of AF (ie, quinidine, flecainide, propafenone, sotalol, dofetilide); however, other antiarrhythmic agents (eg, amiodarone) are used in an off-label fashion with great clinical efficacy. Use antiarrhythmic agents with great caution because they can cause proarrhythmia, exacerbate a preexisting arrhythmia, or provoke a new arrhythmia. Proarrhythmia can be bradycardic or tachycardic, atrial or ventricular. In addition, adverse effects can cause severe comorbidities and even death. Consultation with a cardiac electrophysiologist or knowledgeable physician is recommended prior to antiarrhythmic drug initiation. \r\nFinally, given current hospital constraints and pressure to initiate these agents in an outpatient setting, carefully reconsider specific patient populations at low and acceptable risks for outpatient drug initiation. Whether these agents can be started in an outpatient setting remains controversial. Initiation of drug therapy is generally recommended in a monitored inpatient setting, especially in patients with known structural heart disease or risk factors for toxicity. Proarrhythmia is the most common adverse effect during the loading phase. Proarrhythmic risk is unpredictable; therefore, inpatient loading can lead to a false sense of security regarding future arrhythmic events.\r\n\r\nDRUG CATEGORY :\r\n\r\n1. BETA BLOCKERS :\r\n\r\n- PROPRANOLOL\r\n- ATENOLOL\r\n- METOPROLOL\r\n\r\n2. ATRIOVENTRICULAR NODAL CONDUCTION BLOCKER:\r\n\r\n- DIGOXIN\r\n\r\n3. ANTIARRHYTHMICS, CLASS IA :\r\n\r\n- QUINIDINE\r\n- PROCAINAMIDE\r\n- DISOPYRAMIDE\r\n\r\n4. ANTIARRHYTHMIC, CLASS IC :\r\n\r\n- PROPAFENONE\r\n- FLECAINIDE\r\n\r\n5. ANTIARRHYTHMICS, CLASS III\r\n\r\n- AMIODARONE\r\n- SOTALOL\r\n- DOFETILIDE\r\n- IBUTILIDE\r\n\r\n6. ANTICOAGULANTS TO PREVENT THROMBOEMBOLIC COMPLICATIONS :\r\n\r\n- HEPARIN\r\n- WARFARIN\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('47', 'BREAST ABSCESS', '0', 'CAUSES:\r\n• Puerperal abscesses - blocked lactiferous duct\r\n• Subareolar abscess - squamous epithelial neoplasm with keratin plugs or ductal extension with associated inflammation\r\n• Peripheral abscess - stasis of the duct\r\n\r\n--------------------------------------------------------------------------\r\nDIFFERENTIAL DIAGNOSIS\r\n• Carcinoma (inflammatory)\r\n• Tuberculosis (may be associated with HIV infection)\r\n• Actinomycosis\r\n• Typhoid\r\n• Sarcoid\r\n• Syphilis\r\n• Hydatid cyst\r\n• Sebaceous cyst', '• Leukocytosis\r\n• Elevated sedimentation rate\r\n• Culture and sensitivity of drainage to identify pathogen, usually staphylococci or streptococcus. Non-lactational abscess associated with anaerobic bacteria.\r\nIMAGING:\r\n• Ultrasound\r\n• Mammogram - cannot exclude carcinoma\r\nDIAGNOSTIC PROCEDURES:\r\n• Aspiration for culture\r\n• Fine needle aspiration (FNA) not accurate to exclude carcinoma', '0', '0', '0', '0', '0', 'RISK FACTORS: Puerperal mastitis 5-11% go on to abscess, Diabetes, Rheumatoid arthritis,\r\n Steroids, Silicone/paraffi n implants, Lumpectomy with radiation, Heavy cigarette smoking,\r\n Nipple retraction', 'F', '0', 'GENERAL MEASURES:\r\n• Cold compresses\r\n• Expression of milk\r\n\r\nSURGICAL MEASURES:\r\n• Aspiration possibly under ultrasound guidance\r\n• Incision and drainage with removal of loculations and biopsy of all non-puerperal abscesses to rule out\r\ncarcinoma\r\n• Open all fistulous tracts, especially in nonlactating abscesses\r\n\r\nDRUG(S) OF CHOICE:\r\n. Non-steroidal anti-infl ammatory agents\r\n. Erythromycin 250-500 mg qid\r\n. First generation, oral cephalosporin\r\n. Cephalexin 500 mg bid\r\n. Cefaclor 250 mg tid\r\n. Amoxicillin-clavulanate (Augmentin) 250 mg tid\r\n. Clindamycin 300 mg tid if anaerobes suspected\r\n\r\nPREVENTION/AVOIDANCE\r\n• Early treatment of mastitis with milk expression and\r\ncold compresses\r\n• Early treatment with antibiotics\r\n\r\nPOSSIBLE COMPLICATIONS:  Fistula\r\n\r\nEXPECTED COURSE/PROGNOSIS:\r\nGood. Complete healing expected in 8 to 10 days, particularly if abscess can be incised and drained.', NULL, NULL, NULL, NULL, '1'),
('48', 'BREAST CANCER', '0', 'D.D. :\r\n- ADENOMA BREAST\r\n- BREAST ABSCESS\r\n- FIBROADENOSIS\r\n- SIMPLE CYST\r\n- GALACTOCELE\r\n- LIPOMA\r\n- PLASMA CELL MASTITIS\r\n- FAT NECROSIS ( RARE )\r\n- TUBERCULOSIS ( RARE )\r\n\r\nSWELLINGS THAT ARE NOT OF BREAST\r\n\r\n- RETROMAMMARY ABSCESS FROM EMPYEMA & RIBS\r\n- CHONDROMA OF CHEAST WALL \r\n- DEFORMITY OF THE RIBS\r\n- MONDORS DISEASE', 'OTHER TESTS :\r\n* MRS OF BREAST\r\n* ALWAYS SCREEN FOR OVARIAN CANCER ALSO AS BOTH HAVE THE COMMON ETIOLOGICAL FACTORS & COMMON ONCOGEN & GENETIC FACTOR - BRCA1 & BRCA2 GENES', '1', '0', '0', '0', '1', '* - BRCA1 and BRCA2 GENES ARE RESPONSIBLE FOR BREAST CANCER & OVARIAN CANCER IN SOME PATIENTS. INVESTIGATE FOR ASSOCIATED OVARIAN CANCER ALSO IF THE GENE IS PRESENT.\r\n* - MAMOGRAPHY & FNAC OF THE LUMP IS ADVISED', 'B', '0', 'FACTORS ASSOCIATED WITH INCREASED RISK OF BREAST CANCER :\r\n\r\n- HORMONE REPLACEMENT THERAPY / HORMONE THERAPY\r\n- IONIZING RADIATION\r\n- OBESITY ESPECIALLY IN POST MENOPAUSAL AGE\r\n- ALCOHOL - DOSE DEPENDENT', NULL, NULL, NULL, NULL, '1'),
('49', 'BRONCHIECTASIS', '0', 'CAUSES :\r\n1. PRIMARY INFECTION WITH\r\n\r\n- KLEBSIELLA, STAPHYLOCOCCUS AUREUS, TUBERCULOSIS, MYCOPLASMA PNEUMONIAE, MEASELS, PERTUSSIS, INFLUENZA, HERPES SIMPLEX & ADENO VIRUS, RESPIRATORY SYNCYTIAL VIRUS IN CHILDHOOD\r\n\r\n2. BRONCHIAL OBSTRUCTION : FOCAL LSIONS DUE TO \r\n\r\n- TUMOR\r\n-  FOREIGN BODY\r\n-  BRONCHOLITHIASIS\r\n-  BRONCHIAL STENOSIS\r\n- RT MIDDLE LOBE SYNDROME\r\n\r\n3. CYSTIC FIBROSIS\r\n4. YOUNG SYNDROME\r\n5. PRIMARY CILIARY DYSKINESIA\r\n6. KARTAGENER SYNDROME\r\n7. ALLERGIC BRONCHOPULMONARY ASPERGILLOSIS\r\n8. IMMUNODEFICIENCY STATES\r\n9. CONGENITAL ANATOMIC DEFECTS\r\n\r\n- BRONCHOPULMONARY SEQUESTRATION\r\n- WILLIAMS-CAMPBELL SYNDROME\r\n- MOUNIER-KUHN SYNDROME\r\n- SWYER-JAMES SYNDROME\r\n- YELLOW NAIL SYNDROME\r\n\r\n10. ALPHA 1-ANTITRYPSIN DEFICIENCY\r\n11. AUTOIMMUNE DISEASES LIKE IN\r\n\r\n- RHEUMATOID ARTHRITIS\r\n- SJOGREN SYNDROME\r\n- ANKYLOSING SPONDYLITIS\r\n- ULCERATIVE COLITIS\r\n- CROHN DISEASE\r\n\r\n12. TRACTION BRONCHIACTESIS\r\n13. TOXIC GAS EXPOSURE LIKE \r\n\r\n- CHLORINE\r\n- AMMONIA', 'OTHER TESTS - \r\n* SKIN TEST, SEROLOGY & SPUTUM CULTURE FOR ASPERGILLOSIS.\r\n* CILIARY MOTILITY TEST\r\n* SWEAT CHLORIDE LEVELS- FOR CYSTIC FIBROSIS\r\n* PILOCARPINE IONTOPHORESIS ( SWEAT TEST ) - FOR CYSTIC FIBROSIS', '0', '0', '0', '0', '0', 'BRONCHIACTESIS COULD BE CONGENITAL OR ACQUIRED', 'B', '0', 'CONGENITAL BONCHIACTESIS RESULTS FROM DEVELOPMENTAL ARREST OF THE BRONCHIAL TREE AFFECTING INFANTS & CHILDREN.\r\nBRONCHIACTESIS COULD BE OF FOLLOWING TYPES:\r\n* - CYLINDRICAL BRONCHIACTESIS\r\n* - CYSTIC OR SACCULAR BRONCHIACTESIS\r\n* - VARICOSE BRONCHIACTESIS\r\n\r\n\r\nMedical Care: The goals of therapy are to improve symptoms, to reduce complications, to control exacerbations, and to reduce morbidity and mortality. Early recognition is essential in bronchiectasis and associated conditions. Additionally, management of underlying conditions, which may include the use of intravenous immunoglobulin or intravenous alpha1-antitrypsin therapy, is essential to the overall treatment. \r\nAntibiotics and chest physiotherapy are the mainstay modalities. Other modalities (beyond those for specific associated conditions) may include bronchodilators, corticosteroid therapy, dietary supplementation, and oxygen or surgical therapies. Admitting patients with severe exacerbations of bronchiectasis to the hospital and treating them with intravenous antibiotics, bronchodilators, aggressive physiotherapy, and supplemental nutrition is not uncommon. \r\n\"	General therapy \r\no	Patients should stop smoking. \r\no	Patients should avoid second-hand smoke. \r\no	Patients should have adequate nutritional intake with supplementation, if necessary. \r\no	Immunizations for influenza and pneumococcal pneumonia are recommended. \r\no	Immunizations for measles, rubeola, and pertussis should be confirmed. \r\no	Oxygen therapy is reserved for patients who are hypoxemic with severe disease and end-stage complications, such as cor pulmonale. \r\no	Patients with CF should be cared for at specialized CF treatment centers that address all aspects of the disease, including nutritional and psychologic aspects.\r\n\"	Antibiotics \r\no	Antibiotics have been the mainstay of treatment for more than 40 years. \r\no	Oral, parenteral, and aerosolized antibiotics are used, depending on the clinical situation. \r\no	In acute exacerbation, broad-spectrum antibacterial agents are preferred. \r\no	Acceptable choices for the outpatient who is mild to moderately ill include amoxicillin; tetracycline; trimethoprim-sulfamethoxazole; a newer macrolide, such as azithromycin; a second-generation cephalosporin; or one of the quinolones. In general, the duration is 7-10 days. \r\no	For patients with moderate-to-severe symptoms, parenteral antibiotics, such as an aminoglycoside (gentamicin, tobramycin) and an antipseudomonal synthetic penicillin, a third-generation cephalosporin, or a fluoroquinolone, may be indicated. \r\no	Patients with bronchiectasis from CF are often infected with mucoid Pseudomonas species, and as such, tobramycin is often the drug of choice for acute exacerbation. \r\no	Infection with MAC provides special treatment challenges. For the treatment of MAC in the setting of bronchiectasis, the American Thoracic Society recommends a 3- to 4-drug treatment regimen with clarithromycin, rifampin, ethambutol, and possibly streptomycin that is continued until the patient\'s culture results are negative for 1 year. The typical duration of therapy may be 18-24 months. \r\no	Additionally, some patients with chronic bronchial infections may need regular antibiotic treatment to control the infectious process. Some clinicians prefer to prescribe antibiotics on a regular basis or for a set number of weeks each month. The oral antibiotics of choice are the same as those mentioned previously. Potential regimens include daily antibiotics for 7-14 days of each month, alternating antibiotics for 7-10 days with antibiotic-free periods of 7-10 days, or a long-term daily dose of antibiotics. For patients with severe CF and bronchiectasis, intermittent courses of intravenous antibiotics are sometimes used. \r\no	Recently, the nebulized route of antibiotic administration has received more attention because it is capable of delivering relatively high concentrations of drugs locally with relatively few systemic adverse effects. Currently, inhaled tobramycin is used widely in the treatment of patients with CF, and recent studies suggest efficacy in patients with non-CF bronchiectasis and chronic infection with P aeruginosa. \r\n\"	Bronchial hygiene \r\no	With its tenacious sputum and defects in clearance of mucous, good bronchial hygiene is paramount in the treatment of bronchiectasis. Postural drainage with percussion and vibration is used to loosen and mobilize secretions. Other devices available to assist with mucous clearance include flutter devices, intrapulmonic percussive ventilation devices, and incentive spirometry. However, consistent benefits from these techniques are lacking and vary with patient motivation and knowledge. A new device called the Vest system is a pneumatic compression device worn by the patient periodically throughout the day and is relatively technique independent. \r\no	Nebulization with sodium chloride solutions and mucolytics, such as acetylcysteine, are often tried. While some patients seem to benefit from these techniques, a universal benefit does not exist. However, maintaining adequate general hydration, which may improve the viscidity of secretions, is important. \r\no	Aerosolized recombinant DNase, which breaks down by-product DNA from neutrophils, has been shown to benefit patients with CF. However, improvement has not been shown in patients with bronchiectasis from other causes.\r\n\"	Bronchodilators \r\no	Bronchodilators may help some patients with bronchiectasis, presumably reversing bronchospasm associated with airway hyperreactivity and improving mucociliary clearance. \r\no	Treatment with inhaled bronchodilators may be appropriate, although good, large, randomized clinical trials looking at their use in bronchiectasis have not been performed.\r\n\"	Anti-inflammatory medication\r\no	The rationale is to modify the inflammatory response caused by the microorganisms associated with bronchiectasis and subsequently reduce the amount of tissue damage. Inhaled corticosteroids, oral corticosteroids, and nonsteroidal anti-inflammatory agents have all been examined. Although evidence tends to support some benefit from the use of these agents, findings are not universally definitive. One recent study did find inhaled corticosteroids beneficial to patients with bronchiectasis when compared with a placebo, particularly those with associated P aeruginosa infections. \r\no	A practical approach is to use tapering oral corticosteroids and antibiotics in the acute exacerbation and to consider inhaled corticosteroids for daily use in patients with significant obstructive physiology on pulmonary function testing and evidence of reversibility suggesting airway hyperreactivity.\r\nSurgical Care: \r\n\"	Surgery is an important adjunct to therapy in some patients with advanced or complicated disease. Surgical resection for bronchiectasis can be performed with acceptable morbidity and mortality at any age. In general, surgery should be reserved for patients who have focal disease that is poorly controlled by antibiotics. The involved bronchiectatic sites should be completely resected for optimal symptom control. Other indications for surgical intervention may include the following:\r\no	Reduction of acute infective episodes \r\no	Reduction of excessive sputum production \r\no	Massive hemoptysis (Alternatively, bronchial artery embolization may be attempted for the control of hemoptysis.) \r\no	Foreign body or tumor removal \r\no	Consideration in the treatment of MAC or Aspergillus species infections\r\n\"	Complications of surgical intervention include empyema, hemorrhage, prolonged air leak, and persistent atelectasis.\r\n\"	Patient selection plays an important role in perioperative mortality, which may be as low as 1% in the surgical treatment of segmental or even multisegmental bronchiectasis.\r\n\"	Single or double lung transplantation has been used as treatment of severe bronchiectasis, predominantly when related to CF. In general, consider patients with CF and bronchiectasis for lung transplantation when forced expiratory volume in 1 second (FEV1) falls below 30% of the predicted value. Female patients and younger patients may need to be considered even sooner.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. ANTIBIOTICS\r\n2. INHALED BETA AGONISTS LIKE ALBUTEROL\r\n3. EXPECTORANTS\r\n', NULL, NULL, NULL, NULL, '1'),
('58', 'CARCINOID SYNDROME', '0', 'VARITIES OF CARCINOID TUMORS :\r\n\r\nCLASSIFIED ACCORDING TO THEIR SITE OF ORIGIN :\r\n\r\n1. FOREGUT TUMORS \r\n\r\n- BRONCHUS\r\n- STOMACH\r\n- DUODENUM\r\n- BILE DUCTS\r\n- PANCREAS\r\n\r\n2. MIDGUT TUMORS\r\n\r\n- JEJUNUM\r\n- ILEUM\r\n- APPENDIX\r\n- ASENDING COLON\r\n\r\n3. HINDGUT TUMORS\r\n\r\n- TRANSVERSE & DESENDING COLON\r\n- RECTUM\r\n\r\nIT CAN OCCASIONALLY OCCUR IN THE \r\n\r\n- OVARIES\r\n- TESTES\r\n- PROSTATE\r\n- KIDNEYS\r\n- BREAST\r\n- THYMUS\r\n- SKIN\r\n- METASTATIC CARCIBNOID TUMORS IN LIVER', 'OTHER TESTS :\r\n* URINARY 5-HIAA ( 5-HYDROXYINDOLEACETIC ACID ) ESTIMATION - HIGH\r\n* PLASMA SEROTONIN OR PLATELET SEROTONIN LEVELS - HIGH\r\n* OTHER URINARY METABOLITES OF TRYPTOPHAN, LIKE 5-HTP OR 5-HT -   HIGH\r\n* SERUM NEUROTENSIN, SUBSTANCE P  LEVELS - HIGH\r\n* SERUM CHROMOGRANIN- A LEVELS - ELEVATED IN 50 - 100% PATIENTS', '0', '0', '0', '0', '0', '', 'B', '0', 'TT OF CARCINOID TUMOR : If metastasis occurs and surgical excision is not suitable, consider treatment with currently recommended adjunctive chemotherapy.\r\n\r\nChemotherapeutic agents currently used in clinical trials to palliate metastatic carcinoid disease include the following:\r\nAlkylating agents\r\nDoxorubicin\r\n5-Fluorouracil \r\nDacarbazine \r\nActinomycin D \r\nCisplatin \r\nEtoposide \r\nStreptozotocin \r\nInterferon alfa \r\nSomatostatin analogs with a radioactive load\r\n\r\nA combination of the agents listed above is typically used. \r\n\r\nIn 1 study, 8 adults with carcinoid tumor metastatic to liver were treated with intra-arterial 5-fluorouracil and embolization of hepatic tumors with bovine collagen fiber admixed with iohexol, cisplatin, mitomycin C, and doxorubicin. This treatment resulted in symptomatic relief and in tumoral regression in 4 patients, and it stabilized the disease in the rest of the patients. \r\n\r\nOctreotide, a somatostatin analog, is highly effective in reducing symptoms; however, in the pediatric age group, stunt linear growth is of concern. \r\nOctreotide reduces the amount of the growth factor produced and thus theoretically impairs growth. \r\nIntermittent and continuous infusion of octreotide administration are reported, with superior results obtained with the latter. \r\nSuch treatment can result in near-normalization of the plasma insulin-like growth factor I and partial suppression of plasma growth hormone-releasing hormone (GHRH) (Lefebvre, 1995). \r\n\r\nThe availability of a long-acting somatostatin analog that can be given once a month has eliminated the need for injections 2-3 times per day injections, with equal efficacy (Rubin, 1999). \r\nAt present, no formal, well-designed study has been performed to systematically measure the effects of this modality of therapy. Although experience is limited, adverse effects in children have been similar to those in adults with the disease. Adverse effects include gallstones and steatorrhea, which may sometimes require pancreatic enzyme replacement. Local irritation at the injection site is a common complaint. These adverse effects must be weighted against the potential benefits.\r\n\r\nIn situ targeted therapy with somatostatin analogs (eg, octreotide attached to a radioactive load using yttrium-90 or 111In-labeling agents) can provide promising therapy for patients with unresectable tumors.\r\nThis therapy is currently used on an experimental basis in adults and children. \r\n\r\nSurgical Care: The treatment of choice is surgical excision, if feasible. The surgical technique may vary according to the type or location of the tumor.\r\n\r\nIn most appendiceal tumors, simple appendectomy is sufficient for treatment. In intestinal carcinoids, block resection of the tumor with adjacent lymph nodes must be attempted. In the bronchial location, aggressive surgical resection, and not bronchoscopic removal, is recommended (Fink, 2001; Fauroux, 2005).\r\nIn localized tumors, surgical resection can result in a cure with 70-90% survival rate.\r\nWhen total resection is not possible, debulking may provide symptomatic relief.\r\nSurgical ligation of the hepatic artery can potentially deprive blood supply to the tumor cells and cause necrosis while preserving most of the normal live cells. However, new blood vessels develop over time and restore circulation.\r\nIntra-arterial infusion of chemotherapeutic agents with chemoembolization of the hepatic artery may also provide effective, albeit short term, relief of symptoms due to hepatic metastasis in cases of carcinoid tumors.\r\nIf hepatic metastasis is present but resectable, surgical resection is preferred.\r\n', NULL, NULL, NULL, NULL, '1'),
('76', 'CHOLECYSTITIS,ACUTE', '0', 'CAUSES :\r\n• Gallstones in 90-95% of cases. May obstruct the cystic duct, leading to acute cholecystitis; obstruction of the common bile duct, causing jaundice, or obstruction of the pancreatic duct, causing pancreatitis.\r\n• Gallbladder sludge, a viscous material, insoluble in bile, that layers on sonogram, and occasionally produces cholecystitis, common duct obstruction or pancreatitis. Occurs in most pregnant women, most total parenteral nutrition, and most patients with rapid weight loss\r\n• Acalculous cholecystitis in 5% of cases. Associated with severe stressful situations including cardiac surgery, multiple trauma. May be associated with ischemic damage to the gallbladder wall.\r\n• Bacteria. Usually do not initiate the inflammation but important in the complications of empyema and ascending cholangitis. In emphysematous cholecystitis, Clostridia are probably responsible for both initiation and complications.\r\n• Neoplasms and strictures of common bile duct. Usually associated with cholangitis and pancreatitis.\r\n\r\n--------------------------------------------------------------------------\r\nD.D. :\r\n\r\n- ACALCULOUS CHOLECYSTITIS\r\n- BILE DUCT STRICTURES\r\n- BILIARY COLIC\r\n- BILIARY DISEASE\r\n- BILIARY OBSTRUCTION\r\n- CHOLEDOCHOLITHIASIS\r\n- CHOLELITHIASIS\r\n- DUODENAL ULCER\r\n- GALL BLADDER CANCER\r\n- GASTRIC ULCER\r\n- GASTRITIS, ACUTE\r\n- GASTRITIS, CHRONIC\r\n- HELICOBACTER PYLORI INFECTION\r\n- HEPATITIS, VIRAL\r\n- IRRITABLE BOWEL SYNDROME\r\n- PANCREATITIS, ACUTE \r\n- PANCREATITIS, CHRONIC', '* Acute cholecystitis :\r\n. Leukocytosis - 12,000-15,000\r\n. Liver tests usually abnormal; ALT, AST slightly elevated, alkaline phosphatase, GGT elevated with common duct obstruction\r\n*  Common duct stone :\r\n. High bilirubin in 50%, in 100% after 10 days\r\n. Elevated alkaline phosphatase and gamma glutamyl transpeptidase (GGT) in 85%\r\n. Positive blood culture in 15%\r\n. Barely abnormal ALT, AST\r\n. Elevated fasting bile salts\r\n. Elevated WBC if infection\r\n. Serum amylase may be elevated. If > 1000 units, concomitant pancreatitis should be considered.\r\nSPECIAL TESTS:\r\n* 99mTc Imino diacetic acid (HIDA) scan - highly sensitive (97%) for diagnosis of acute cholecystitis. HIDA derivatives are taken up by hepatocytes and excreted in bile and concentrated in gallbladder. Failure to see gallbladder in 1 hour is highly suspicious for acute cholecystitis. Usually abnormal in acalculous cholecystitis.\r\nIMAGING :\r\n*  Plain radiographs (upright) . 20% of gallstones are radiopaque\r\n*  Air cholangiogram if there is gallbladder-gut fistula\r\n*  Emphysematous cholecystitis - air in the gallbladder wall or in lumen\r\n*  Ultrasonography :\r\n. Best technique to diagnose gallstones (high sensitivity - 95%, and specificity - 98%)\r\n. Best noninvasive imaging technique to diagnose acute cholecystitis. Findings include thick gall bladder wall (> 3 mm), gallbladder distension, sludge in lumen, pericholecystic fluid.\r\n* CT scan :\r\n. No advantage over ultrasonography in gallstone/acute cholecystitis diagnosis\r\n. Better than ultrasonography to detect enlargement of pancreas. Helpful in the diagnosis of abscess formation. Shows thickened gall bladder wall in cancer.\r\n. Better than US for dilated common bile duct\r\nDIAGNOSTIC PROCEDURES:\r\n. Ultrasound or CT scan often diagnostic\r\n. Tc HIDA test during acute pain\r\n. Endoscopic retrograde cholangiopancreatography (ERCP) - to see status of biliary and pancreatic ducts\r\n. Percutaneous transhepatic cholangiography test (PTC) - gives more information about intrahepatic biliary system\r\n. Magnetic resonance almost as sensitive as ERCP to detect common bile duct stones. Endoscopic ultrasound is superior to ERCP in detecting common duct stones and has fewer complications.\r\n. Laparotomy - if unable to make diagnosis by less invasive means', '0', '0', '0', '0', '0', 'RISK FACTORS:\r\n• Cardiac surgery\r\n• Trauma\r\n• Biliary parasites\r\n• Gallstones\r\n• Rapid weight loss\r\n• Prolonged parenteral alimentation\r\n• Pregnancy', 'B', '0', 'Medical Care: For acute cholecystitis, initial treatment includes bowel rest, intravenous hydration, analgesia, and intravenous antibiotics. For mild cases of acute cholecystitis, antibiotic therapy with a single broad-spectrum antibiotic is adequate. Some options include the following: \r\n\"	Current Sanford guide recommendations include ampicillin (4-6 g/d), ampicillin/sulbactam (Unasyn, 3 g IV/IM q6h), or piperacillin/tazobactam (Zosyn, 3.375 g IV q6h). (In severe life-threatening cases, the Sanford Guide also recommends Primaxin or meropenem.)\r\n\"	For severe cases of acute cholecystitis, gentamicin (3-5 mg/kg/d) with clindamycin (1.8-2.7 g/d) or metronidazole with a third-generation cephalosporin provides adequate coverage.\r\n\"	Bacteria that are commonly associated with cholecystitis include E coli and Bacteroides fragilis and Klebsiella, Enterococcus, and Pseudomonas species.\r\n\"	Emesis can be treated with antiemetics and nasogastric suction.\r\n\"	Because of the rapid progression of acute acalculous cholecystitis to gangrene and perforation, early recognition and intervention are required.\r\n\"	Supportive medical care should include restoration of hemodynamic stability and antibiotic coverage for gram-negative enteric flora and anaerobes if biliary tract infection is suspected. \r\n\"	Daily stimulation of gallbladder contraction with intravenous CCK has been shown by some to effectively prevent the formation of gallbladder sludge in patients receiving TPN.\r\nSurgical Care: Laparoscopic cholecystectomy is the standard of care for the surgical treatment of cholecystitis. Surgery is usually performed after symptoms have subsided but during the hospitalization for acute illness. For elective laparoscopic cholecystectomy, the rate of conversion from a laparoscopic procedure to an open surgical procedure is approximately 5%. The conversion rate for emergency cholecystectomy where perforation or gangrene is present may be as high as 30%. \r\n\"	Immediate cholecystectomy or cholecystotomy is usually reserved for complicated cases in which the patient has gangrene or perforation.\r\n\"	Early operation within 72 hours of admission has both medical and socioeconomic benefits and is the preferred approach for patients treated by surgeons with adequate experience in laparoscopic cholecystectomy.\r\n\"	For patients at high surgical risk, placement of a sonographically guided, percutaneous, transhepatic cholecystostomy drainage tube coupled with the administration of antibiotics may provide definitive therapy.\r\n\"	Results of studies suggest that most patients with acute acalculous cholecystitis can be treated with percutaneous drainage alone.\r\n\"	Contraindications for laparoscopic cholecystectomy include the following:\r\no	High risk for general anesthesia\r\no	Morbid obesity\r\no	Signs of gallbladder perforation such as abscess, peritonitis, or fistula\r\no	Giant gallstones or suspected malignancy\r\no	End-stage liver disease with portal hypertension and severe coagulopathy\r\nDiet: Patients admitted for cholecystitis should receive nothing by mouth (NPO) because of expectant surgery. However, in uncomplicated cholecystitis, a liquid or low-fat diet may be appropriate until the time of surgery.\r\n \r\nPATIENT MONITORING : Post cholecystectomy - follow through postoperative period\r\n\r\nPREVENTION/AVOIDANCE:\r\n• Avoid risk factors when possible \r\n• During rapid weight loss following bariatric surgery or very low calorie diets, ursodeoxycholic acid (ursodiol)10\r\nmg/kg/day\r\n• During total parenteral alimentation for more than one month, daily ingestion of 100 kcal, or injection of\r\ncholecystokinin\r\n\r\nPOSSIBLE COMPLICATIONS :\r\nOccur in about 5% cases of acute cholecystitis and include - perforation, abscess formation, fistula\r\nformation (intestine, colon, cutaneous), gangrene, empyema, cholangitis, hepatitis, pancreatitis, gallstone\r\nileus, carcinoma\r\n\r\nEXPECTED COURSE/PROGNOSIS :\r\n• In general the prognosis is good for gallbladder disease. Those who die during acute episodes are mainly\r\ndue to other conditions, especially coronary artery disease.\r\n• Symptomatic gallstones usually have recurrent symptoms in 3 to 6 months indicating need for future action\r\n• After cholecystectomy, stones may recur in bile ducts\r\n', NULL, NULL, NULL, NULL, '1'),
('83', 'COR-PULMONALE', '0', 'CAUSES :\r\n\r\n1. ACUTE COR PULMONALE :\r\n\r\n- PULMONARY ARTRY EMBOLI, LARGE OR MULTIPLE\r\n\r\n2. SUB ACUTE COR PULMONALE\r\n\r\n- PULMONARY ARTRY EMBOLI, SMALL\r\n- VASCULITIS\r\n- WIDESPREAD LUNG DAMAGE ( ARDS )\r\n\r\n3. CHRONIC COR PULMONALE\r\n\r\n- EMBOLI, MEDIUM & RECCURENT\r\n- PRIMARY PUL HYPERTENSION\r\n- DIET OR DRUG VASOPATHY\r\n- OBSTRUCTIVE LUNG DISEASES LIKE CHR BRONCHITIS WITH EMPHYSEMA , CHR ASTHMA\r\n- RESTRICTIVE LUNG DISEASES LIKE \r\n* INTERSTITIAL FIBROSIS\r\n* CYSTIC FIBROSIS\r\n* LUNG RESECTION\r\n* OBESITY\r\n* MYXEDEMA\r\n* MUSCLE WEAKNESS\r\n*  KYPHOSCOLIOSIS\r\n* UPPER AIRWAY OBSTRUCTION\r\n* DIMINISHED RESPIRATORY DRIVE\r\n* HIGH ALTITUDE\r\n- NEUROMUSCULAR DISORDERS LIKE MYASTHENIA GRAVIS, POLIOMYELITIS, AMYOTROPHIC LATERAL SCLEROSIS\r\n- OBSTRUCTIVE & CENTRAL SLEEP APNEA\r\n\r\n--------------------------------------------------------------------------\r\n2-ND CLASSIFICATION OF CAUSES :\r\n\r\n. Disease affecting pulmonary air spaces\r\n. Diffuse interstitial lung diseases: idiopathic pulmonary fibrosis, radiation induced fibrosis\r\n. Pulmonary resection\r\n. Chronic obstructive pulmonary diseases (chronic bronchitis, emphysema, asthma)\r\n. Granulomatous and connective tissue diseases: sarcoidosis, rheumatoid arthritis, systemic lupus erythematosus, eosinophilic granuloma, mixed connective tissue disease\r\n. Bronchiectasis\r\n. Cystic fibrosis\r\n. Malignant infiltration\r\n. Chronic hypoxia at high altitude\r\n. Congenital structural defects\r\n. Diseases affecting the pulmonary vasculature\r\n. Primary pulmonary hypertension\r\n. Pulmonary embolism\r\n. CREST\r\n. Tumor embolism\r\n. Amniotic fluid embolism\r\n. Schistosomiasis\r\n. Sickle cell disease\r\n. Pulmonary vascular disease secondary to systemic illness\r\n. Human immunodeficiency virus\r\n. Granulomatous pulmonary arteritis\r\n. Chronic liver disease\r\n. Intravenous drug abuse\r\n. Diseases affecting thoracic cage function\r\n. Obesity\r\n. Kyphoscoliosis\r\n. Neuromuscular diseases\r\n. Sleep apnea\r\n. Pleural fibrosis\r\n. Idiopathic hypoventilation\r\n. Pharmacologic induction\r\n. Appetite suppressants, including aminorex, fenfluramine, dexfenfluramine\r\n\r\n\r\n--------------------------------------------------------------------------\r\nDIFFERENTIAL DIAGNOSIS\r\n• Primary disease of the left side of the heart\r\n• Congenital heart disease with left-to-right shunting\r\n• Pulmonary arterial dissection', '• Acute cor pulmonale: ventilation/perfusion mismatch with hypoxia and hypocarbia\r\n• Chronic cor pulmonale: pulmonary function testing shows airfl ow obstruction with reduced pO2 and possibly elevated hematocrit\r\nSPECIAL TESTS :\r\nECG: often normal, but findings can include: . RVH: most common in primary pulmonary hypertension. Indicated by clockwise rotation of electrical axis, right axis deviation, and P pulmonale (increased P wave amplitude in II, III, and AVF)\r\n. Right-sided heart failure suggested by: \r\n. R/S in V1>1\r\n. R/S in V6<1\r\n. R wave in V1>5mm\r\n. P wave in II>2.5 mm, consistent with right atrial enlargement\r\n. Transient changes with hypoxia (arterial O2 saturation <85% and mean pulmonary arterial pressure >25 mm Hg) which may include:\r\n. Rightward mean QRS axis (shift of 30 or more from former position)\r\n. Biphasic, flattened, or inverted T waves in the precordial leads\r\n. ST segment depression in II, III and aVF\r\n. Incomplete or complete (rare) right bundle-branch block\r\nIMAGING :\r\n. Chest x-ray:  Heart size may be normal in mild to moderate disease\r\n. There may be counter-clockwise cardiac rotation and loss of aortic knob prominence with severe disease\r\n. In the PA view, the left heart border is mostly comprised of the right ventricle\r\n. Pulmonary hypertension gives rise to dilatation of the pulmonary trunk and hilar vessels\r\n. Echocardiography estimates right ventricular dimensions, right atrial pressure, systolic pulmonary artery pressure, and the severity of tricuspid regurgitation.\r\nIn patients with chronic cor pulmonale secondary to COPD, there may also be late diastolic LV filling secondary to RV pressure/volume overload-induced\r\nstructural distortion of the left ventricle.\r\n. Thallium-201 myocardial scintigraphy and MRI can be used to diagnose right ventricular hypertrophy\r\n. MRI can be used more specifically to characterize right ventricular ejection fraction and ventricular volume, including end-systolic and end-diastolic wall sizes\r\n. CT angiography - aid in diagnosis of pulmonary arterial dissection\r\nDIAGNOSTIC PROCEDURES :\r\n. Right heart catheterization for quantitation of ventricular and pulmonary pressures and exclusion of congenital heart disease as etiology of right heart failure. Lung biopsy also helpful in discriminating among granulomatous and collagen-vascular diseases.', '0', '0', '0', '0', '0', 'RISK FACTORS : Tobacco abuse, Living at high altitudes, Industrial exposures', 'B', '0', 'Medical Care: Medical therapy for chronic cor pulmonale is generally focused on treatment of the underlying pulmonary disease and improving oxygenation and RV function by increasing RV contractility and decreasing pulmonary vasoconstriction. However, the approach might be different to some degree in an acute setting with priority given to stabilizing the patient. \r\nCardiopulmonary support for patients experiencing acute cor pulmonale with resultant acute RV failure includes fluid loading and vasoconstrictor (eg, epinephrin) administration to maintain adequate blood pressure. Of course, the primary problem should be corrected, if possible. For example, for massive pulmonary embolism, consider administration of anticoagulation, thrombolytic agents or surgical embolectomy, especially if circulatory collapse is impending, consider bronchodilation and infection treatment in patients with COPD and consider steroid and immunosuppressive agents in infiltrative and fibrotic lung diseases. \r\nOxygen therapy, diuretics, vasodilators, digitalis, theophylline, and anticoagulation therapy are all different modalities used in the long-term management of chronic cor pulmonale. \r\n\"	Oxygen therapy is of great importance in patients with underlying COPD, particularly when administered on a continuous basis. With cor pulmonale, the partial pressure of oxygen (PO2) is likely to be below 55 mm Hg and decreases further with exercise and during sleep. \r\nOxygen therapy relieves hypoxemic pulmonary vasoconstriction, which then improves cardiac output, lessens sympathetic vasoconstriction, alleviates tissue hypoxemia, and improves renal perfusion. The Nocturnal Oxygen Therapy Trial (NOTT), a multicenter randomized trial, showed that continuous low-flow oxygen therapy for patients with severe COPD resulted in significant reduction in the mortality rate. In general, in patients with COPD, long-term oxygen therapy is recommended when PaO2 is less than 55 mm Hg or O2 saturation is less than 88%. However, in the presence of cor pulmonale or impaired mental or cognitive function, long-term oxygen therapy can be considered even if PaO2 is greater than 55 mm Hgor O2 saturation is greater than 88%. \r\nAlthough it is not clear whether oxygen therapy has a mortality rate benefit in patients with cor pulmonale due to pulmonary disorders other than COPD, it may provide some degree of symptomatic relief and improvement in functional status. Therefore, oxygen therapy plays an important role in both the immediate setting and long-term management, especially in patients who are hypoxic and have COPD.\r\n\"	Diuretics are used in the management of chronic cor pulmonale, particularly when the right ventricular filling volume is markedly elevated and in the management of associated peripheral edema. Diuretics may result in improvement of the function of both the right and left ventricles; however, diuretics may produce hemodynamic adverse effects if they are not used cautiously. Excessive volume depletion can lead to a decline in cardiac output. Another potential complication of diuresis is the production of a hypokalemic metabolic alkalosis, which diminishes the effectiveness of carbon dioxide stimulation on the respiratory centers and lessens ventilatory drive. The adverse electrolyte and acid-base effect of diuretic use can also lead to cardiac arrhythmia, which can diminish cardiac output. Therefore, diuresis, while recommended in the management of chronic cor pulmonale, needs to be used with great caution.\r\n\"	Vasodilator drugs have been advocated in the long-term management of chronic cor pulmonale with modest results. Calcium channel blockers, particularly oral sustained-release nifedipine and diltiazem, can lower pulmonary pressures, although they appear more effective in primary rather than secondary pulmonary hypertension. Other classes of vasodilators, such as beta agonists, nitrates, and angiotensin-converting enzyme (ACE) inhibitors have been tried but, in general, vasodilators have failed to show sustained benefit in patients with COPD and they are not routinely used. A trial of vasodilator therapy may be considered only in patients with COPD with disproportionately high pulmonary blood pressure. \r\nBeta-selective agonists have an additional advantage of bronchodilator and mucociliary clearance effect. Right heart catheterization has been recommended during initial administration of vasodilators to objectively assess the efficacy and detect the possible adverse hemodynamic consequences of vasodilators. The Food and DrugAdministration (FDA) has approved epoprostenol, treprostinil, bosentan, and iloprost for treatment of primary pulmonary hypertension. Epoprostenol, treprostinil, and iloprost are prostacyclin PGI2 analogues and have potent vasodilatory properties. Epoprostenol and treprostinil are administered intravenously and iloprost is an inhaler. Bosentan is a mixed endothelin-A and endothelin-B receptor antagonist indicated for pulmonary arterial hypertension (PAH), including primary pulmonary hypertension (PPH). In clinical trials, it improved exercise capacity, decreased rate of clinical deterioration, and improved hemodynamics. PDE5 inhibitor sildenafil has also been intensively studied and recently approved by the FDA for treatment of pulmonary hypertension based on a large randomized study. Sildenafil promotes selective smooth muscle relaxation in lung vasculature. Not enough data are available regarding the efficacy of these drugs in patients with secondary pulmonary hypertension such as in patients with COPD.\r\n\"	The use of cardiac glycosides, such as digitalis, in patients with cor pulmonale has been controversial, and the beneficial effect of these drugs is not as obvious as in the setting of left heart failure. Nevertheless, studies have confirmed a modest effect of digitalis on the failing right ventricle in patients with chronic cor pulmonale. It must be used cautiously, however, and should not be used during the acute phases of respiratory insufficiency when large fluctuations in levels of hypoxia and acidosis may occur. Patients with hypoxemia or acidosis are at increased risk of developing arrhythmias due to digitalis through different mechanisms including sympathoadrenal stimulation.\r\n\"	In addition to bronchodilatory effect, theophylline has been reported to reduce pulmonary vascular resistance and pulmonary arterial pressures acutely in patients with chronic cor pulmonale secondary to COPD. Theophylline has a weak inotropic effect and thus may improve right and left ventricular ejection. As a result, considering the use of theophylline as adjunctive therapy in the management of chronic or decompensated cor pulmonale is reasonable in patients with underlying COPD.\r\n\"	Anticoagulation with warfarin is recommended in patients at high risk for thromboembolism. The beneficial role of anticoagulation in improving the symptoms and mortality in patients with primary pulmonary arterial hypertension clearly was demonstrated in a variety of clinical trials. The evidence of benefit, however, has not been established in patients with secondary pulmonary arterial hypertension. Therefore, anticoagulation therapy may be used in patients with cor pulmonale secondary to thromboembolic phenomena and with underlying primary pulmonary arterial hypertension.\r\nSurgical Care: \r\n\"	Phlebotomy is indicated in patients with chronic cor pulmonale and chronic hypoxia causing severe polycythemia, defined as hematocrit of 65 or more. Phlebotomy results in a decrease in mean pulmonary artery pressure, a decrease in mean pulmonary vascular resistance, and an improvement in exercise performance in such patients. There is, however, no evidence of improvement in survival. Generally, phlebotomy should be reserved as an adjunctive therapy for patients with acute decompensation of cor pulmonale and patients who remain significantly polycythemic despite appropriate long-term oxygen therapy. Replacement of the acute volume loss with a saline infusion may be necessary to avoid important decreases in systemic blood pressure.\r\n\"	No surgical treatment exists for most diseases that cause chronic cor pulmonale. Pulmonary embolectomy is efficacious for unresolved pulmonary emboli, which contribute to pulmonary hypertension. Uvulopalatopharyngoplasty in selected patients with sleep apnea and hypoventilation may relieve cor pulmonale. Single-lung, double-lung, and heart-lung transplantation are all used to salvage the terminal phases of several diseases (eg, primary pulmonary hypertension, emphysema, idiopathic pulmonary fibrosis, cystic fibrosis) complicated by cor pulmonale. Apparently, lung transplantation will lead to a reversal of right ventricular dysfunction from the chronic stress of pulmonary hypertension. Strict selection criteria for lung transplant recipients must be met, however, because of the limited availability of organ donors.\r\n\r\nMEDICATION :\r\n\r\n1. DIURETICS\r\n\r\n- FRUSEMIDE\r\n\r\n2. CALCIUM CHANNEL BLOCKERS :\r\n\r\n- NIFEDIPINE\r\n\r\n3. CARDIAC GLYCOSIDES :\r\n\r\n- DIGOXIN\r\n\r\n4. ANTICOAGULANTS : TO REDUCE INCIDENCE OF EMBOLI FORMATION\r\n\r\n- WARFARIN\r\n\r\n5. METHYL XANTHINES ( BRONCHODILATORS ) :\r\n\r\n- THEOPHYLLINE\r\n\r\n6. ENDOTHELIN RECEPTOR ANTAGONISTS : COMPETITIVELY BIND TO ENDOTHELIN-1 RECEPTORS CAUSING REDUCTION IN PULMONARY ARTRY PRESSURE, PULMNARY VASCULAR RESISTANCE & MEAN RT. ATRIAL PRESSURE\r\n\r\n- BOSENTAN\r\n', NULL, NULL, NULL, NULL, '1'),
('86', 'CORONARY ARTERY DISEASE', '0', 'CAUSES :\r\n\r\n- FAMILY H/O PREMATURE CAD\r\n- HYPERCHOLESTEROLEMIA\r\n- HYPERTENSION\r\n- CIGARETTE SMOKING\r\n- DIABETES MELLITUS\r\n- HYPOALPHALIPOPROTEINEMIA\r\n- DYSMETABOLIC SYNDROME\r\n- OBESITY\r\n- PHYSICAL INACTIVITY\r\n- NONTRADITIONAL RISK FACTORS LIKE\r\n\r\n* HYPERHOMOCYSTINEMIA\r\n* HIGH LIPOPROTEIN LEVELS\r\n* HIGH IRON LEVELS\r\n\r\n- SYNDROMES OF ACCELERATED ATHEROSCLEROSIS LIKE\r\n\r\n* GRAFT ATHEROSCLEROSIS\r\n* CAD AFTER CARDIAC TRANSPLANTATION\r\n\r\n- RESTENOSIS\r\n- INFECTION LIKE\r\n\r\n* C PNEUMONIA\r\n* H PYLORI\r\n* HERPES SIMPLEX VIRUS\r\n* CYTOMEGALOVIRUS', 'CORONARY RISK FACTORS :\r\n\r\n* C-REACTIVE PROTEIN - INCREASED LEVELS HAVE HIGH PREDICTABLE VALUE FOR IMPENDING MYOCARDIAL INFARCTION IN ASSOCIATION WITH OTHER RISK FACTORS', '1', '0', '0', '1', '0', 'DISEASE INFLUENCING FACTORS : DIET, LIFE STYLE, ENVIRONMENT, SMOKING, ALCOHOL, DRUG ABUSE & LACK OF EXERCISE', 'B', '0', 'DIABETES, HYPERTENSION, SMOKING ARE IMPORTANT RISK FACTORS WHICH ACCELERATE ATHEROSCLEROSIS, AGGAVATING CORONARY ARTRY DISEASE.\r\n\r\nMedical Care: The goals of management of myocardial ischemia are to relieve symptoms and to prevent future fatal and nonfatal acute coronary syndromes such as UA/NSTEMI, STEMI, and sudden cardiac death. \r\n\"	Current understanding of myocardial ischemia suggests that the favored management approach is to appropriately and aggressively pursue all causes of myocardial ischemia and to appropriately treat all reversible causes until clinical and/or perfusion studies confirm that the myocardial ischemia is maximally reduced or eliminated. \r\n\"	Risk-factor modification is extremely important in the reduction and alleviation of myocardial ischemia. Indeed, medical therapy for risk factor reduction-particularly the use of statins, angiotensin-converting enzyme (ACE) inhibitors, aspirin, and beta-blockers (see below)-may reduce the risk of future cardiac events to an even greater degree than revascularization approaches. Elimination of preventable risk factors of CAD, such as smoking, obesity, and sedentary lifestyle-as well as satisfactory control of risk factors such as hypertension, diabetes, and hyperlipidemia-are key to the management of myocardial ischemia. All evidence suggests that the antianginal medications used in treatment of angina pectoris are equally effective in treatment of both symptomatic and asymptomatic myocardial ischemia. \r\n\"	Pharmacologic treatment of CAD can be divided into agents that prolong survival (eg, aspirin, statin drugs, ACE inhibitors, beta-blockers) and those that treat symptoms (eg, calcium channel blockers, nitrates). \r\n\"	Hypertension\r\no	Treatment of hypertension to satisfactory endpoints of systolic blood pressure of less than 130 mm Hg and diastolic blood pressure of less than 85 mm Hg is strongly recommended. \r\no	In patients with angina pectoris, the first-line agents are beta-adrenergic blocking agents such as metoprolol (Toprol, Lopressor), atenolol (Tenormin), or propranolol (Inderal), since they also reduce myocardial oxygen demand by reducing heart rate, contractility, and wall stress, and/or ACE inhibitors, since they retard progression of CAD. \r\no	Other antihypertensive agents may be employed to achieve blood pressure goals in addition to beta-blockers or ACE inhibitors (or in place of beta-blockers or ACE inhibitors if contraindication or intolerance). \r\no	ACE inhibitors and beta-blockers are particularly useful in treating hypertension in patients with CAD, although guidelines from the Joint National Committee for the Treatment of Hypertension also advocate the use of diuretics and other agents.\r\n\"	Hyperlipidemia\r\no	The statins, such as atorvastatin (Lipitor), simvastatin (Zocor), pravastatin (Pravachol), lovastatin (Mevacor, Altocor), and fluvastatin (Lescol) are the first-line (and most popular) agents in the treatment of hyperlipidemias. Their use has led to rapid and significant improvement in endothelium-dependent dilation of coronary and peripheral arteries in patients with hyperlipidemia. \r\no	The statins have the advantage of stabilizing atheromatous plaques in coronary arteries and reduce acute coronary syndromes by this mechanism. Growing evidence also indicates that they may contribute to regression of coronary atherosclerosis, thereby reducing the frequency of and/or propensity for myocardial ischemia in patients with CAD. \r\no	Numerous studies have demonstrated that statins are effective in both secondary and primary prevention of MI and cardiac death, even in individuals with only minimally elevated LDL cholesterol (>100 mg/dL). \r\no	Cholesterol-lowering agents markedly reduce evidence of myocardial ischemia on ambulatory ECG monitoring in patients with stable coronary disease and hypercholesterolemia over a period of 4-6 months.\r\n\"	Antianginal therapy is the cornerstone of medical treatment in both patients with symptomatic and those with asymptomatic myocardial ischemia. Beta-blockers, as a single agent, are the preferred agents, provided no absolute contraindication to their use exists. Calcium channel antagonists are suitable alternatives, as well as effective agents in combination with beta-blockers, particularly such dihydropyridine agents as nifedipine, felodipine, and amlodipine. Care must be taken in the use of nondihydropyridine calcium channel antagonists. Avoid their use in patients with depressed LV function. Long-acting nitrates are effective in treatment of myocardial ischemia and are frequently used in combination with both beta-blockers and calcium channel antagonists. Short-acting nitroglycerin is the agent of choice in treatment of acute symptomatic myocardial ischemia. \r\n\"	Antiplatelet therapy, with aspirin, clopidogrel (Plavix), ticlopidine (Ticlid), or dipyridamole (Persantine), is useful in both prevention and treatment of acute coronary syndromes from ruptured coronary plaques and subsequent thrombus formation. Of these, aspirin is most effective in reducing risk for MI, stroke, and cardiac death, while combinations of aspirin and clopidogrel are useful after coronary stenting and in other circumstances. Intravenous glycoprotein IIb/IIIa inhibitors, such as abciximab (ReoPro) and eptifibatide (Integrillin), are useful in patients with recurrent UA/NSTEMI, particularly in the subset of patients who undergo immediate PCI such as coronary angioplasty. \r\n\"	Antithrombin therapy with standard or low molecular weight heparin is useful in patients with UA/NSTEMI as well.\r\n\"	Treatment of reversible noncardiac causes of myocardial ischemia is important in improving myocardial oxygen supply (eg, anemia) and in reducing myocardial oxygen demand (eg, thyrotoxicosis).\r\nSurgical Care: \r\n\"	Percutaneous coronary interventions\r\no	Percutaneous transluminal coronary angioplasty (PTCA), with or without stenting \r\no	Brachytherapy - Intracoronary radiation therapy with either gamma- or beta-ray devices \r\no	Coronary atherectomy \r\no	Ablative laser-assisted angioplasty \r\no	Catheter-based thrombolysis and mechanical thrombectomy \r\no	Percutaneous valvuloplasty - For patients with mitral or aortic stenosis as the cause of myocardial ischemia/heart failure\r\n\"	Coronary artery bypass surgery\r\no	Open heart surgery with use of bypass pump \r\no	Beating heart surgery \r\no	Keyhole or minimal incision coronary bypass (MIDCAB) \r\no	Bypasses using arterial conduits \r\no	Surgical transmyocardial laser revascularization (TMLR)/percutaneous transmyocardial laser revascularization (PTMLR) \r\no	Ileal bypass surgery \r\no	Miscellaneous therapies - Chelation therapy, EDTA, hydrogen peroxide \r\no	Plethysmography/extracorporeal counterpulsation (ECCP) for angina pectoris\r\n\"	Intraaortic balloon counterpulsation\r\no	Since the 1980s, intraaortic balloon counterpulsation (IABCP) has been increasingly used in various clinical situations as a lifesaving intervention to attain hemodynamic stabilization prior to definite therapy. \r\no	Diastolic augmentation enhances perfusion of the coronary circulation and carotid arteries. The reduction in end-diastolic pressure decreases aortic impedance (afterload) and augments systole. \r\no	IABCP reduces aortic impedance and systolic pressure, leading to a 15-25% reduction in LV wall stress. This level of afterload reduction improves LV volume, LV emptying, and myocardial oxygen consumption.\r\no	Diastolic aortic pressure augmentation increases myocardial perfusion and coronary blood flow. The effects on coronary blood flow are variable, but the boost generally ranges from 10-20% in ischemic territories.\r\no	IABCP can decrease LV filling pressures by 20-25% and can improve cardiac output by 20% in patients with cardiogenic shock; therefore, IABCP reduces myocardial oxygen demand significantly, although the additional beneficial effect of increased oxygen supply to the myocardium may occur in some clinical situations.\r\no	Indications \r\n\"	IABCP is effective in providing temporary support to patients in cardiogenic shock while definitive therapies such as angioplasty or cardiac bypass surgery are undertaken. At most institutions, IABCP is considered to be a bridge to a definitive revascularization procedure or to implementation of an LV assist device. \r\n\"	IABCP is effective in hemodynamically stabilizing patients with UA refractory to medical therapy prior to a definitive revascularization procedure. \r\n\"	IABCP may be a lifesaving intervention in patients with acute mitral regurgitation secondary to papillary muscle ischemia, infarction, and other causes such as infectious endocarditis or myxomatous degeneration. IABCP reduces afterload (thereby reducing severity of mitral regurgitation), enhances forward cardiac output, reduces left atrial pressure, and improves pulmonary edema. \r\n\"	IABCP is used to stabilize patients who are hemodynamically unstable, which allows time to plan the definitive surgical procedure. \r\n\"	IABCP can provide hemodynamic support in the perioperative and postoperative periods.\r\no	Contraindications \r\n\"	The absolute contraindications for IABCP are aortic dissection, severe aortic regurgitation, presence of a large arteriovenous shunt, and severe coagulopathy. \r\n\"	The relative contraindications are severe peripheral vascular disease, recent thrombolytic therapy, and bleeding diathesis. \r\no	Complications \r\n\"	IABCP can cause several complications that should be monitored while the patient is maintained on IABCP support. Generally, platelet count is reduced mildly; however, it usually does not fall below 100 X 103/ L. \r\n\"	Complications may occur during cannulation of the femoral artery, including perforation, laceration, or dissection of the artery (1-6%). Thrombosis of the iliofemoral artery and distal emboli may occur (1-7%), and limb ischemia has been reported in as many as 40% of patients. The limb ischemia is reversible upon removal of the intraaortic balloon pump unless thrombosis develops, which requires embolectomy to save the limb. \r\n\"	Other complications are localized bleeding (3-5%), infection (2-4%), thrombocytopenia (<1%), and intestinal ischemia (<1%). \r\n\"	The risk of these complications can be lessened by avoiding long-term use of IABCP. In most patients with myocardial ischemia, limit use of IABCP to the time necessary to perform definitive (percutaneous or surgical) revascularization.\r\nDiet: The Third Report of the Expert Panel on Detection, Evaluation, and Treatment of High Blood Cholesterol in Adults (Adult Treatment Panel III [ATP III]) recommends a multifaceted lifestyle approach to reduce risk for CHD. This approach is designated therapeutic lifestyle changes (TLC). Its essential features are as follows: \r\n\"	Reduced intakes of saturated fats (<7% of total energy intake) and cholesterol (<200 mg/d). \r\n\"	Therapeutic options for enhancing LDL lowering such as plant stanols/sterols (2 g/d) and increased viscous (soluble) fiber (10-25 g/d) \r\n\"	Weight reduction \r\n\"	Increased physical activity\r\nThe following describes components of the TLC approach: \r\n\"	To initiate TLC, intakes of saturated fats and cholesterol are reduced first to lower LDL cholesterol.\r\n\"	To improve overall health, ATP III\'s TLC diet generally contains the recommendations embodied in the Dietary Guidelines for Americans 2000. One exception is that total fat is allowed to range from 25-35% of total energy intake, provided saturated fat and trans fatty acid intakes are kept low. A higher intake of total fat, mostly in the form of unsaturated fat, can help to reduce triglycerides and to raise HDL cholesterol in persons with the metabolic syndrome.\r\n\"	In accord with the Dietary Guidelines, moderate physical activity is encouraged. The LDL response is determined after 6 weeks; if the LDL cholesterol goal has not been achieved, other therapeutic options for LDL lowering (eg, plant stanol/sterols, viscous fiber) can be added. \r\n\"	After maximum reduction of LDL cholesterol with dietary therapy, emphasis shifts to management of the metabolic syndrome and associated lipid risk factors. Most persons with these latter abnormalities are overweight or obese and sedentary.\r\n\"	Weight-reduction therapy for patients who are overweight or obese enhances LDL lowering and provides other health benefits, including modifying other lipid and nonlipid risk factors. Additional risk reduction can be achieved by simultaneously increasing physical activity.\r\n\"	At all stages of dietary therapy, physicians are encouraged to refer patients to registered dietitians or other qualified nutritionists for medical nutrition therapy, which is the term for the nutritional intervention and guidance provided by a nutrition professional.\r\nActivity: Increased physical activity is part of the management of underlying causes of the metabolic syndrome. \r\n\"	First-line therapies for all lipid and nonlipid risk factors associated with the metabolic syndrome are weight reduction and increased physical activity, which effectively reduce all of these risk factors. Therefore, after appropriate control of LDL cholesterol, TLC should stress weight reduction and physical activity if the metabolic syndrome is present.\r\no	Weight reduction and control \r\n\"	In ATP III, overweight and obese conditions are recognized as major underlying risk factors for CHD and are identified as direct targets of intervention. Weight reduction enhances LDL lowering and reduces all of the risk factors of the metabolic syndrome. \r\n\"	The recommended approaches for reducing overweight and obese conditions are contained in the clinical guidelines for obesity.\r\no	Physical activity \r\n\"	Physical inactivity is likewise a major underlying risk factor for CHD. Inactivity augments the lipid and nonlipid risk factors of the metabolic syndrome and may increase risk by impairing cardiovascular fitness and coronary blood flow. Regular physical activity reduces very-low-density lipoprotein (VLDL) levels, raises HDL cholesterol, and, in some persons, lowers LDL levels. Activity can also lower blood pressure, reduce insulin resistance, and favorably influence cardiovascular function. \r\n\"	Thus, ATP III recommends that regular physical activity become a routine component in management of high serum cholesterol. \r\n\r\n\r\nDRUG TREATMENT :\r\n\r\n1. HMG-COA REDUCTASE INHIBITORS :\r\n\r\n- ATORVASTATIN\r\n- PRAVASTATIN\r\n- SIMVASTATIN\r\n- ROSUVASTATIN\r\n\r\n2. ACE INHIBITORS :\r\n\r\n- RAMIPRIL\r\n- QUINAPRIL\r\n\r\n\r\n3. CALCIUM CHANNEL BLOCKERS :\r\n\r\n- AMLODIPINE\r\n\r\n4. PLATELET AGGREGATION INHIBITORS :\r\n\r\n- CLOPIDOGREL\r\n- ABCIXIMAB\r\n- ASPIRIN\r\n\r\n5. POLYUNSATURATED FTTY ACIDS :\r\n\r\n- OMEGA-3 FATTY ACIDS\r\n\r\n6.ANTIOXIDANTS :\r\n\r\n- VIT E\r\n\r\n7. VITAMINS :\r\n\r\n- FOLIC AICD\r\n\r\n8. HORMONE REPLACEMENT : USE IN IMPROVING ENDOTHELIAL FUNCTION IN POSTMENOPAUSAL WOMEN\r\n\r\n- OESTROGEN ( PREMARIN )\r\n\r\n9. ANTIBIOTICS :\r\n\r\n- GATIFLOXACIN', NULL, NULL, NULL, NULL, '1'),
('89', 'CUSHING SYNDROME', '0', 'CAUSES : -\r\n\r\n1. ADRENAL HYPERPLASIA\r\n\r\nA. SECONDARY TO PITITARY ACTH OVERPRODUCTION\r\n* PITUITARY-HYPOTHALAMIC DYSFUNCTION\r\n* PITUITARY ACTH PRODUCING MICRO OR MACROADENOMAS\r\nB. SECONADARY TO ACTH OR CRH PRODUCING NON ENDOCRINE TUMOURS\r\n( BRONCHOGENIC CARCINOMA, CARCINOID OF THYMUS, PANCREATIC CARCINOMA, BRONCHIAL ADENOMA )\r\n\r\n2. ADRENAL MACRONODULAR HYPERPLASIA ( INCLUDING ECTOPIC EXPRESSION OF GIP RECEPTORS IN THE ADRENAL CORTEX )\r\n\r\n3. ADRENAL MICRONODULAR DYSPLASIA\r\n* SPORADIC \r\n* FAMILIAL ( CARNEYS SYNDROME )\r\n\r\n4. ADRENAL NEOPLASIA\r\n* ADENOMA \r\n* CARCINOMA\r\n\r\n5. EXOGENOUS, IATROGENIC CAUSES\r\n* PROLONGED USE OF GLUCOCORTICOIDS\r\n* PROLONGED USE OF ACTH\r\n\r\n--------------------------------------------------------------------------D.D. :\r\n\r\n- ALCOHOLISM\r\n- ANOREXIA NERVOSA\r\n- BULIMIA\r\n- DEPRESSION\r\n- OBESITY', 'OTHER TESTS :\r\n* PLASMA & URINE CORTISOL LEVELS - HIGH\r\n* OCCASIONALLY HYPOKALEMIA, HYPOCHLOREMIA & METABOLIC ACIDOSIS\r\n* 24 HRS URINE CORTISOL LEVELS IN OBESE PTS - > 140 NMOL / DAY\r\n* DEXAMETHASONE TEST - 1 MG OF DEXAMETHASONE AT BED TIME, FOLLOWED BY MEASUREMENT OF PLASMA CORTISOL AT 7 - 10 A.M. IS BEST SCREENING TEST. A URINE CORTISOL LEVEL OF < 2750 NMOL OR SUPPRESSION OF PLASMA CORTISOL TO < 140 NMOL / L RULES OUT CUSHING SYNDROME\r\n* DEXAMETHASONE - CRH TEST - INTENDED TO DISTINGUISH PATIENTS WITH CUSHING SYNDROME FROM THOSE WITH PSEUDO-CUSHING STATES. DEXAMETHASONE 0.5 MG IS GIVEN EVERY 6 HRS FOR 8 TIMES, CRH ( CORTICOTROPHIN RELEASING HORMONE ) IS THEN ADMINISTERED I.V. & PLASMA CORTISOL & ACTH LEVELS ARE MEASURES AT 15 MTS INTERVAL FOR 1 HR. CORTISOL VALUE > 50 NMOL/L IDENTIFIES CUSHING SYNDROME.\r\n* CT SCAN, THIN SECTION OR MRI OF ADRENAL GLAND SHOULD BE PERFORMED IF THE PT. HAS ACTH INDEPENDENT CUSHING SYNDROME\r\n* IF PT. HAS ACTH DEPENDENT CUSHING SYNDROME WITH ACTH SECRETION THAT CANT BE SUPPRESSED WITH DEXAMETHASONE, CHEST CT OR MRI SHOULD BE PERFORMED.\r\n* CT OR MRI SELLA TURCICA - TO DETERMINE LOCATION OF ADENOMA\r\n* BILATERAL INFERIOR PETROSAL SINUS SAMPLING - MOST PRECISE & DIRECT WAY OF MEASURING ACTH LEVELS FROM REGION PROXIMAL TO PITUITARY; MAY BE THE MOST SENSITIVE/SPECIFIC TEST FOR CUSHING DISEASE\r\n* LIPID PROFILE - ELEVATED TRIGLYCERIDES, LDL & HDL LEVELS\r\n* TSH, LH & FSH LEVELS - DECREASED\r\n* BONE X-RAYS - SHOW OSTEOPENIA OR OSTEOPOROSIS\r\n* SALIVERY CORTISOL LEVELS AT BED TIME( 11 PM ) - SPECIFICITY 95%\r\n* 24 HR URINE FOR FREE CORTISOL LEVELS - GENERALLY ON 2-3 COSECUTIVE DAYS; 50% SENSITIVITY IMPROVES WITH SUCCESSIVE DAYS OF TESTING TO 100%.\r\n---------------------------------------------------------------------------------------------------------------------------\r\nTEST FOR CUSHING SYNDROME VS PSEUDO-CUSHING SYNDROME\r\n\r\n* INSULIN TOLERANCE TEST - PLASMA CORTISOL LEVELS INCREASE IN RESPONSE TO INSULIN INDUCED HYPOGLYCEMIA IN PTS WITH PSEUDO-CS BUT NOT IN PTS WITH CS.\r\n* ADMINISTRATION OF NALOXONE RELEASES LESS CRH & THEREFORE LESS ACTH & CORTISOL IN PTS WITH CS THAN IN THOSE WITH PSEUDO-CS\r\n---------------------------------------------------------------------------------------------------------------------------\r\nDISTINGUISH SUBTYPE OF CUSHING SYNDROME :\r\n\r\n* MEASUREMENT OF ACTH BY RADIOIMMUNOASSAY : \r\nLEVELS <5 TO 10 PG/ML SUGGEST ACTH-INDEPENDENT CS( PRIMARY ADRENAL ) & LEVELS > 15 TO 20 SUGGEST ACTH DEPENDENT CS\r\n* IF ACTH DEPENDENT, DETERMINE THE SOURCE OF EXCESS ACTH SECRETION :\r\n- HIGH DOSE DEXAMETHASONE SUPRESSION TEST : ADMINISTER 2 MG DEXAMETHASONE EVERY 6 HRLY FOR 8 DOSES WITH MEASUREMENT OF UFC OR URINE CORTISOL METABOLITES. SUPPRESSION OF UFC BY >90% OF MEAN BASAL VALUES OR SUPPRESSION OF 17-HYDROXYSTEROID EXCRETION BY >64% IS SUGGESTIVE OF A PITUITARY SOURCE OF EXCESSIVE ACTH SECRETION ( CD ).            OR\r\n*  DEXAMETHASONE 8 MG IS ADMINISTERED AT 11 PM & PLASMA CORTISOL LEVEL IS MEASURED BETWEEN 7 & 8 AM. THAT MORNING & NEXT MORNING. A DECREASE IN PLASMA CORTISOL BY >50% IS SUGGESTIVE OF CD. SENSITIVITY - 70% & SPECIFICITY 100% FOR CD\r\n*  METYRAPONE STIMULATION TEST - METYRAPONE BLOCKS THE CONVERSION OF 11-DEOXYCORTISOL TO CORTISOL, LEADING TO A DECREASE IN PLASMA COTISOL, INCREASE IN ACTH SECRETION BY THE PITUITARY, INCREASE IN PLASMA 11-DEOXYCORTISOL & URINARY 17-HYDROXYCORTICOSTEROID CONCENTRATIONS.\r\n* CRH STIMULATION TEST - CORTICOTROPIN SECRETING TUMORS RETAIN SENSITIVITY TO CRH, WHEREAS NONCORTICOTROPH TUMORS DO NOT RESPOND TO CRH.', '0', '0', '0', '0', '0', 'DUE TO HYPERCOAGULABLE STATE OF CS PATIENTS, ALL SHOULD BE TREATED WITH HEPARIN PROPHYLAXIS WHILE IN HOSPITAL TO PREVENT THROMBOSIS COMPLICATIONS. PT SHOULD BE AWARE OF THE NEED TO INCREASE THE DOSE OF STEROIDS IN CASE OF FEVER, VOMITINGS, DIARRHOEA.', 'B', '0', 'Treatment of Cushing syndrome is directed by the primary cause of the syndrome.\r\n\r\nIn general, therapy should reduce the cortisol secretion to normal to reduce the risk of comorbidities associated with hypercortisolism. A culprit tumor should be removed if possible. The treatment of choice for endogenous Cushing syndrome is surgical resection of the causative tumor. The primary therapy for Cushing disease is transsphenoidal surgery, and the primary therapy for adrenal tumors is adrenalectomy.\r\n\r\nWhen surgery is not successful or cannot be used, as often occurs with ectopic ACTH or metastatic adrenal carcinoma, control of hypercortisolism may be attempted with medication. However, medication failures are common, and adrenalectomy may be indicated in ACTH-mediated Cushing syndrome.\r\n\r\nPituitary radiation may be useful if surgery fails for Cushing disease.\r\n\r\nThe treatment for exogenous Cushing syndrome is gradual withdrawal of glucocorticoid.\r\n \r\nCushing syndrome\r\n\r\nAgents that inhibit steroidogenesis, such as mitotane, ketoconazole, metyrapone, aminoglutethimide, trilostane, and etomidate, have been used to cause medical adrenalectomy. These medications are used rarely and often are toxic at the doses required to reduce cortisol secretion. Thus, medical treatment should be initiated cautiously and, ideally, in conjunction with a specialist. Efficacy of these medical interventions can be assessed with serial measurements of 24-hour urinary free cortisol.\r\n\r\nPatients receiving these medications may require glucocorticoid replacement to avoid adrenal insufficiency. Patients should be counseled on the signs and symptoms of adrenal insufficiency when starting these drugs.\r\n\r\nMetyrapone and trilostane are agents that competitively inhibit a single steroidogenic enzyme. Ketoconazole and aminoglutethimide act at several sites. If enzymatic blockade is not complete, ACTH secretion overcomes the blockade so that hypercortisolism persists.\r\n\r\nBecause ACTH production may persist or increase in patients with Cushing disease, radiation therapy of the pituitary often is required after unsuccessful initial therapy, either surgical or medical. These agents have higher efficacy when used in combination because they may act synergistically.\r\n\r\nKetoconazole probably is the most popular and effective of these agents for long-term use and usually is the agent of choice. It acts on several of the P450 enzymes, including the first step in cortisol synthesis, cholesterol side-chain cleavage, and conversion of 11-deoxycortisol to cortisol.\r\n\r\nAdverse effects of ketoconazole include headache, sedation, nausea, irregular menses, decreased libido, impotence, gynecomastia, and elevated liver function tests. The drug is contraindicated during pregnancy.\r\n\r\nKetoconazole is ineffective in patients on H2 blockers or proton-pump inhibitors because gastric acidity is required for metabolism. If this agent is ineffective at controlling hypercortisolism, the dose may be maintained while another steroid enzyme inhibitor, typically metyrapone, is initiated.\r\n\r\nMetyrapone blocks 11-beta-hydroxylase activity, the final step in cortisol synthesis. Therapy is begun at 1 g/d divided into 4 doses and increased to a maximum dose of 4.5 g/d. Adverse effects are from increases in androgen and mineralocorticoid precursors, including hypertension, acne, and hirsutism.\r\n\r\nAminoglutethimide is an anticonvulsant agent that blocks cholesterol side-chain cleavage to pregnenolone. It is a relatively weak adrenal enzyme inhibitor at doses that patients can tolerate. Aminoglutethimide typically is initiated at 250 mg twice daily, and increased to 2 g 4 times daily.\r\n\r\nAdverse effects of aminoglutethimide include somnolence, headache, a generalized pruritic rash, hypothyroidism, and goiter. In rare cases, it may cause bone marrow suppression. Aminoglutethimide increases the metabolism of dexamethasone but not cortisol.\r\n\r\nTrilostane is not widely available and is not as well studied. Trilostane inhibits the conversion of pregnenolone to progesterone, which decreases the synthesis of cortisol, aldosterone, and androstenedione. It is not a first-choice agent because it is a weak inhibitor of steroidogenesis. In addition, trilostane interacts with some assays, causing a false elevation of cortisol measurements.\r\n\r\nEtomidate, an imidazole-derivative anesthetic agent, blocks 11-beta-hydroxylase. It is used intravenously at 0.3 mg/kg/h. Its use is limited by the requirement for chronic administration by the intravenous route.\r\n\r\nMitotane is an adrenolytic agent that acts by inhibiting 11-beta hydroxylase and cholesterol side-chain cleavage enzymes. This drug also leads to mitochondrial destruction and necrosis of adrenocortical cells in the zona fasciculata and reticularis. For this reason, it is used in treatment of adrenal cancer. Its survival benefit is unclear. It can be used in addition to radiation therapy for treatment of Cushing disease and in combination with metyrapone or aminoglutethimide for treatment of ectopic ACTH secretion.\r\n\r\nUnfortunately, mitotane is expensive, and its utility is limited by adverse gastrointestinal and neurologic effects, including nausea, diarrhea, dizziness, and ataxia. Other adverse effects include rash, arthralgias, and leukopenia. It is taken up by adipose tissues and persists in the circulation long after discontinuation. It is a potential teratogen and can cause abortion; therefore, it is relatively contraindicated in women interested in remaining fertile.\r\n\r\nMifepristone (RU 486) is an antiprogestational agent, which, at high doses, competitively binds to the glucocorticoid and progesterone receptors. It currently is used only on an investigational basis for treatment of Cushing syndrome.\r\n\r\nAgents that decrease CRH or ACTH release have been studied for the treatment of Cushing disease. Such agents include bromocriptine, cyproheptadine, valproic acid, and octreotide. Currently, use of these agents is investigational.\r\n\r\nSurgical Care\r\n\r\nCushing disease\r\n\r\nTreatment of choice for classic Cushing disease is transsphenoidal surgery by an experienced neurosurgeon. The goal of surgery is to remove the adenoma, preserving as much pituitary function as possible.\r\n\r\nThe more extensive the mass and the resulting resection, the greater the risk for loss of pituitary function. Successful amelioration of hypercortisolism occurs in 60-80% of cases. Both open and laparoscopic techniques are possible. If unsuccessful, MRI-guided pituitary surgery, a new procedure, may be indicated. Lateralization of ACTH secretion via IPS catheterization and sampling sometimes is helpful in difficult cases.\r\n\r\nPituitary irradiation is employed when transsphenoidal surgery is not successful or not possible. The procedure is less successful than surgery in adults, with a 45% cure rate in adults and 85% cure rate in children. Late-onset adverse effects include hypopituitarism.\r\n\r\nBilateral adrenalectomy is an option if transsphenoidal surgery, pituitary irradiation, and medical therapy fail or if rapid normalization of cortisol levels is required. The patient then requires lifelong glucocorticoid and mineralocorticoid therapy.\r\n\r\nIn individuals who undergo bilateral adrenalectomy, Nelson syndrome, ie, symptomatic enlargement of the pituitary gland and adenoma, may occur in one quarter to one half of adults not treated with pituitary irradiation and in as many as one quarter of patients pretreated with radiation therapy.\r\n \r\nEctopic adrenocorticotropic production\r\n\r\nSurgical resection of the source of ACTH production may not always be possible. Ectopic ACTH-producing tumors often are difficult to locate.\r\n\r\nMedical therapy or bilateral adrenalectomy may be required.\r\n \r\nAdrenal source\r\n\r\nAdenomas may be removed with unilateral adrenalectomy, often with a laparoscopic approach.\r\n\r\nCarcinomas should be resected for possible cure and palliation.\r\n\r\nMicronodular or macronodular hyperplasia causing Cushing syndrome may be treated effectively by bilateral adrenalectomy. Unilateral or subtotal adrenalectomy may lead to recurrence.\r\n \r\nHormone replacement\r\n\r\nPatients with endogenous Cushing syndrome who undergo resection of pituitary, adrenal, or ectopic tumors should receive stress doses of glucocorticoid in the intraoperative and immediate postoperative period.\r\n\r\nTypically, hydrocortisone is infused intravenously, either continuously (10 mg/h) or in boluses (80-100 mg q8h) starting prior to surgery and for the first 24 hours afterward.\r\n\r\nIf the patient does well, intravenous glucocorticoid replacement may be tapered over 1-2 days and replaced with an oral formulation. The rate of steroid taper may be slowed if severe preoperative hypercortisolism was present.\r\n\r\nIn the event of pituitary destruction or bilateral adrenalectomy, lifelong steroid replacement is necessary.\r\n', NULL, NULL, NULL, NULL, '1'),
('156', 'GLOMERULONEPHRITIS,ACUTE ( POST STREPTOCOCCAL )', '0', '', 'OTHER TESTS :\r\n* SERUM C3 LEVELS & CH-50 LEVELS - DEPRESSED IN 90% CASES\r\n* ANTI GLOMERULAR BASEMENT MEMBRANE ANTIBODY - PRESENT\r\n* ANTI NEUTROPHIL CYTOPLASMIC ANTIBODY - PRESENT\r\n* URINE - HAEMATURIA, RED BLOOD CELL CAST, PROTEINURIA, WBCS & OCCASIONALLY WBC CAST.\r\n* SERUM CREATININE - NEAR NORMAL', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: Treatment of acute PSGN is mainly supportive because there is no specific therapy for renal disease. Treat the underlying infections when acute GN is associated with chronic infections. \r\n\"	Antimicrobial therapy\r\no	Antibiotics (eg, penicillin) are used to control local symptoms and to prevent spread of infection to close contacts.\r\no	Antimicrobial therapy does not appear to prevent the development of GN, except if given within the first 36 hours.\r\n\"	Loop diuretic therapy\r\no	Loop diuretics may be required in patients who are edematous and hypertensive in order to remove excess fluid and to correct hypertension. \r\no	Relieves edema and controls volume, thereby helping to control volume-related elevation in BP. \r\no	Vasodilator drugs (eg, nitroprusside, nifedipine, hydralazine, diazoxide) may be used if severe hypertension or encephalopathy is present.\r\no	Glucocorticoids and cytotoxic agents are of no value, except in severe cases of PSGN.\r\nDiet: \r\n\"	Sodium and fluid restriction - For treatment of signs and symptoms of fluid retention (eg, edema, pulmonary edema)\r\n\"	Protein restriction for azotemic patients - If no evidence of malnutrition\r\nActivity: Recommend bed rest until signs of glomerular inflammation and circulatory congestion subside. Prolonged inactivity does not benefit in the patient recovery process.\r\n\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('159', 'GOUT', '0', 'D.D. :\r\n\r\n- ACUTE SEPTIC ARTHRITIS\r\n- PALINDROMIC RHEUMATISM\r\n- PSORIATIC ARTHRITIS\r\n\r\n\r\n--------------------------------------------------------------------------\r\n\r\nCAUSES :\r\n\r\n1. OVERPRODUCTION OF URIC ACID CRYSTALS \r\n\r\n- GENITIC DISORDER LIKE LESCH-NYHAN SYNDROME, VON GIERKE DISEASE, FRUCTOSE 1-PHOSPHATE ALDOLASE DEFICIENCY, PP-RIBOSE-P SYNTHETASE VARIANT\r\n\r\n- SECONDARY TO DISORDERS CAUSING HIGH CELL TURNOVER LIKE MYELOPROLIFERATIVE & LYMPHOPROLIFERATIVE DISORDERS, PSORIASIS, CHEMOTHERAPY, HEMOLYTIC ANEMIAS, EXCESSIVE EXERCISE & OBESITY\r\n\r\n2. UNDEREXCRETION OF CRYSTALS LIKE :\r\n\r\n- RENAL INSUFFICIENCY\r\n- LEAD NEPHROPATHY(SATURNINE GOUT)\r\n- STARVATION OF DEHYDRATION\r\n- HYPOTHYROIDISM\r\n- HYPERPARATHYROIDISM\r\n- DRUGS LIKE DIURETICS, CYCLOSPORINE A )\r\n- ALCOHOL ABUSE', 'OTHER TESTS :\r\n* SERUM URIC ACID - HIGH OR NORMAL SOMETIMES, ESPECIALLY IF SEMITREATED.\r\n* SYNOVIAL FLUID EXAM - CELL COUNT 2000 - 60,000 / ML , NEEDLE SHAPED CRYSTALS\r\n* X-RAY - CYSTIC CHANGES, WELL DEINED EROSIONS ( PUNCHED OUT LYTIC LESIONS WITH OVERHANGING BONY EDGES), ASSOCIATED WITH SOFT TISSUE CALCIFIED MASSES ARE CHARACTERISTIC. SIMILAR CHANGES ARE SEEN IN EROSIVE OSTEOARTHRITIS, DESTRUCTIVE APATITE ARTHROPATHIES & RHEUMATOID ARTHRITIS.', '0', '0', '0', '0', '0', '', 'B', '0', '* - GOUT IS OFTEN CLUSTERED WITH INSULIN RESISTANCE SYNDROME KNOWN AS METABOLIC SYNDROME OR SYNDROME X, DIABETES MELLITUS, HYPERTENSION, HYPERTRIGLYCERIDEMIA, ABDOMINAL OBESITY & LOW HDL WHICH MAY INCREASE CHANCES OF CORONARY ARTRY DISEASE, WHICH ALREADY IS MORE COMMON IN GOUT.\r\n* - PODAGRA ( INFLAMMATION OF FIRST METATARSOPHALANGEAL JOINT ) IS ALSO SEEN IN PSEUDOGOUT, SARCOIDOSIS, GONOCOCCAL ARTHRITIS, PSORIATIC ARTHRITIS & REACTIVE ARTHRITIS.\r\n* - ATTACKS OF GOUT MAY PRECIPITATE DUE TO INFECTION, ALCOHOL INTAKE(INCLUDING BEAR), DRUGS LIKE THIAZIDE DIURETICS, ANTICANCER DRUGS, CERTAIN FOODS, TRAUMA, HAEMORRHAGE.\r\n* - GOUT PATIENTS MAY HAVE HIGHER INCIDENCE OF RENAL STONES. \r\n\r\nMedical Care: There are 3 stages in the management of gout: (1) treating the acute attack, (2) providing prophylaxis to prevent acute flares, and (3) lowering excess stores of uric acid to prevent flares of gouty arthritis and to prevent tissue deposition of uric crystals. \r\n\"	Management of acute gout: Options for treatment of acute gout include nonsteroidal anti-inflammatory drugs (NSAIDs), corticosteroids, or colchicine (a classic treatment but now rarely indicated). The choice is based primarily on the patient\'s other health problems, such as renal insufficiency and peptic ulcer disease.\r\no	Nonsteroidal anti-inflammatory drugs \r\n\"	NSAIDs are the drugs of choice in most patients without underlying health problems. \r\n\"	Indomethacin is the traditional choice unless the patient is elderly, because of the potential for adverse CNS effects in this age group. However, most NSAIDs can be used. Select an agent with a quick onset of action, but do not use aspirin because it can alter uric acid levels and potentially prolong and intensify an acute attack. Cyclooxygenase-2 (COX-2) inhibitors have been used with success. \r\n\"	Start with the highest dose for 2-3 days and taper down over approximately 2 weeks. Patients should be asymptomatic for at least 2 days before discontinuing the NSAID. \r\n\"	Avoid NSAIDs in patients who have a history of peptic ulcer disease or GI bleeding, patients with renal insufficiency, patients with abnormal hepatic function, patients taking coumadin (selective COX-2 inhibitors can be used), and patients in the intensive care unit who are predisposed to gastritis.\r\no	Corticosteroids \r\n\"	Corticosteroids can be given to those patients who cannot use NSAIDs or colchicine. Some rheumatologists recommend corticosteroids over NSAIDs as the preferred choice for treatment of acute gout. Steroids can be given orally, intravenously, intramuscularly, intra-articularly, or indirectly via adrenocorticotropic hormone (ACTH). \r\n\"	Prednisone can be given at a dose of approximately 40 mg for 1-3 days and then tapered over approximately 2 weeks. Tapering more rapidly can result in a rebound flare. \r\n\"	Using parenteral corticosteroids confers no advantage unless the patient cannot take oral medications. \r\n\"	Intra-articular corticosteroids are particularly useful in patients with a monoarticular flare to help reduce the systemic effect of oral steroids. Ensuring that the joint is not infected prior to injecting intra-articular corticosteroids is particularly important. \r\n\"	ACTH at 40 IU IM can be given to induce corticosteroid production by the patient\'s own adrenal glands. Such a regimen does not depend on the patient to taper prednisone properly.\r\no	Colchicine \r\n\"	Colchicine is the classic medication for gout but is not the preferred medication for the treatment of acute gout. It is most effective during the first 12-24 hours of an attack, but its effectiveness declines with the duration of inflammation. Moreover, when used to treat an acute attack, colchicine causes adverse GI effects, particularly diarrhea and vomiting, in 80% of patients. \r\n\"	To treat an acute attack colchicine is given orally at 0.5-0.6 mg every hour until the patient has relief, has adverse GI effects, or takes 6 mg (ten 0.6-mg tabs). The total dose and the frequency need to be reduced in patients with renal or hepatic insufficiency, and colchicine generally is not recommended in these situations. \r\n\"	Patients may be able to abort an attack by taking a single colchicine tablet at the first twinge of an attack. \r\n\"	Colchicine should not be used if the glomerular filtration rate (GFR) is less than 10 mL/min, and the dose should be decreased by at least half if the GFR is less than 50 mL/min. \r\n\"	Colchicine also should be avoided in patients with hepatic dysfunction, biliary obstruction, or an inability to tolerate diarrhea. \r\n\"	A clinical response to colchicine is not pathognomonic for gout and can be seen with pseudogout, sarcoid arthropathy, psoriatic arthritis, and calcific tendonitis. \r\n\"	Colchicine also can be administered intravenously. While this route of therapy can quickly abort an attack of gout, it should be employed only in unusual circumstances because it is potentially toxic. Indeed, this therapy is banned in some countries due to a 2% fatality rate. IV colchicine should be used cautiously, if at all, in patients with renal insufficiency or hepatic dysfunction. \r\n\"	When given intravenously, 1 mg of colchicine is diluted in 20 mL of isotonic sodium chloride solution without glucose and pushed over 10-20 minutes in a secure IV line. A maximum of 4 mg is given over 24 hours, and no further colchicine should be given for the next week. \r\n\"	If the medication extravasates, it can cause tissue necrosis. Within the vessels, it also can cause thrombophlebitis. \r\n\"	Granulocytopenia is a prime complication of IV colchicine. The WBC count should be measured before infusion. \r\n\"	Other complications include disseminated intravascular coagulopathy, renal failure, hepatocellular toxicity, seizures, and shock.\r\n\"	Prophylaxis to prevent acute flares\r\no	Lowering uric acid with either allopurinol or probenecid can precipitate attacks of gout. When used prophylactically, colchicine can reduce such flares by 85%. \r\no	The standard dose for prophylaxis is colchicine at 0.6 mg bid. In patients with renal insufficiency, this dose may need to be decreased to daily or every-other-day administration. \r\no	Compared with the 80% risk of adverse GI effects in patients using colchicine for the treatment of acute gout, the prophylactic dose of colchicine induces adverse GI effects in only 4% of patients. \r\no	Long-term use of colchicine can lead to a muscle weakness associated with elevated levels of creatine kinase due to a drug-induced neuromyopathy, particularly in patients with renal insufficiency. \r\no	In patients who cannot take colchicine, NSAIDs can be used for prophylaxis, such as indomethacin at 25 mg bid. \r\no	Prophylaxis with colchicine can be started during the acute attack.\r\n\"	Lowering uric acid levels\r\no	In many cases, patients who have a first attack of gout should undergo therapy with agents that lower uric acid, given the high risk for further inflammatory attacks and the potential for destructive tophaceous deposition in the bone and synovium, even without episodes of acute inflammation. \r\no	Some rheumatologists advocate waiting for the second attack to begin therapy to lower uric acid levels because not all patients have a second attack and because some patients may need to be convinced they need life-long therapy. This decision is partly dependent on the baseline serum uric acid levels (a level >9 mg/dL denoting higher risk for recurrent gouty arthritis and tophi). \r\no	In all cases, the risks and benefits need to be judged based on the individual patient. For instance, in an elderly patient with multiple medical problems and renal insufficiency, the risks of therapy to lower uric acid levels may outweigh the benefits. \r\no	The goal of therapy is to lower serum uric acid levels to approximately 5-6 mg/dL. \r\no	The risk of a second attack of gout after the first attack is 62% after 1 year, 78% after 2 years, and 93% after 10 years. \r\no	Treating patients with colchicine alone may help prevent flares of inflammatory arthritis but does not prevent the accumulation of uric acid in the joints, which can lead to further joint destruction. \r\no	While using agents that lower uric acid is important, they should not be started during an acute attack. This may lead to a more intense and prolonged attack. Typically, they should be started a few weeks after the attack has resolved and with the protection of colchicine to prevent another attack. \r\no	If the patient develops a flare of gout when starting on agents that lower uric acid, do not discontinue the agent because this will only cause another flux in the uric acid level that may prolong and intensify the attack. \r\no	Probenecid \r\n\"	Some rheumatologists prefer probenecid whenever possible because it has fewer significant adverse effects than allopurinol. Probenecid can be used in the majority of middle-aged, otherwise healthy men with gout. \r\n\"	Indications for the use of allopurinol instead of probenecid include renal insufficiency (GFR <50 mL/min), renal stones, use of aspirin (blocks the effect of probenecid), overproduction of uric acid, and unresponsiveness to probenecid. \r\n\"	Drug interactions may occur with probenecid.\r\n\"	Patients using probenecid need to drink 2 L of fluid daily at the inception of therapy to ensure adequate diuresis to decrease the risk of renal stones.\r\no	Sulfinpyrazone: Sulfinpyrazone is an alternative uricosuric agent that has antiplatelet activity but is seldom used because of the added risk of bone marrow suppression. \r\no	Allopurinol \r\n\"	Allopurinol blocks xanthine oxidase and thus reduces the generation of uric acid. Therefore, it should be used in patients who are overproducers of uric acid and in patients at risk of tumor lysis syndrome to prevent renal toxicity during therapy for malignancies. It is the most effective agent to lower serum uric acid levels. However, alcohol can interfere with the effectiveness of allopurinol. \r\n\"	Approximately 3-10% of patients taking allopurinol develop dyspepsia, headache, diarrhea, or pruritic maculopapular rash. More infrequently, patients can develop allopurinol hypersensitivity, which has a mortality rate of 20-30%. Features of allopurinol hypersensitivity include fever, toxic epidermal necrolysis, bone marrow suppression, eosinophilia, leukocytosis, renal failure, hepatic failure, and vasculitis. Corticosteroids often are used to treat allopurinol hypersensitivity. Allopurinol hypersensitivity is more likely to occur in patients with renal insufficiency, patients who are taking a diuretic, and patients begun on 300 mg of allopurinol. \r\n\"	Allopurinol should be discontinued in patients who develop a rash. In patients with a history of drug eruptions due to allopurinol, both an oral (Fam, 2001) and IV (Walz-LeBlanc, 1991) desensitization regimen are available that can be considered. \r\n\"	In most patients, start at 100 mg per day and adjust the dose monthly according to the uric acid level until the goal of a uric acid level of 5-6 mg/dL is achieved. \r\n\"	Beware of drug interactions. For example, allopurinol prolongs the half-life of azathioprine and 6-mercaptopurine. It enhances the toxicity of cyclophosphamide. Patients taking concomitant ampicillin have an increased incidence of rash. \r\n\"	Once the target level is achieved and maintained for 6 months, discontinue colchicine prophylaxis. \r\n\"	Avoiding the use of medications that elevate uric acid in patients with gout is prudent. Thus, other agents are preferable to a thiazide diuretic to treat hypertension. However, if such a medication is needed, it can be used with appropriate adjustments of allopurinol or probenecid. \r\n\"	Allopurinol can be used in combination with probenecid. However, note that allopurinol increases the half-life of probenecid, whereas probenecid increases the excretion of allopurinol.\r\no	Other potential therapeutic options include the following: \r\n\"	Nonrecombinant urate-oxidase (uricase) is used in Europe to prevent severe hyperuricemia induced by chemotherapy in malignant patients, as well as for selected patients with treatment-refractory gout. Recently, the Food and Drug Administration (FDA) approved recombinant Aspergillus flavus uricase for the prevention of tumor lysis syndrome. However, it is highly immunogenic and may cause anaphylaxis. \r\n\"	Patients with allopurinol hypersensitivity can often tolerate oxypurinol, which is a metabolite of allopurinol. \r\n\"	Benzbromarone is an effective uricosuric agent that may eventually become available. However, it can cause fulminant hepatotoxicity. \r\n\"	Febuxostat, a nonpurine selective inhibitor of xanthine oxidase, is a potential alternative to allopurinol for patients with gout. It is orally administered and metabolized mainly in the liver. In contrast, allopurinol and its metabolites are excreted primarily by the kidney. Therefore, febuxostat can be administered in patents with renal insufficiency, with no dosage adjustment. Its efficacy and side-effect profile otherwise appears similar to that of allopurinol. \r\n\"	The angiotensin receptor blocker losartan and the triglyceride-lowering agent micronized fenofibrate have moderately potent uricosuric effects. They should therefore be considered in patients with gout who also require treatment for hypertension and hypertriglyceridemia. \r\n\"	Vitamin C, with its uricosuric effect, may reduce the serum concentration of uric acid.\r\nSurgical Care: \r\n\"	If diagnosed and treated early, patients should not need orthopedic surgery. In patients who are untreated or in those who are treated late in the course of their disease, orthopedic repair may be necessary.\r\n\"	Tophi should not be surgically removed unless they are in a critical location or drain chronically.\r\n\"	In patients undergoing arthroscopy, the presence of white lesions, sometimes on an erythematous base, should prompt consideration for gout.\r\nDiet: \r\n\"	Diet modifications can only improve the serum uric acid levels by 1 mg/dL and rarely are able to lower uric acid levels sufficiently to prevent further attacks and accumulation of uric acid.\r\n\"	Patients should avoid alcohol because it elevates levels of uric acid and therefore can precipitate attacks of gout. Indeed, heavy drinkers are much more likely to have recurrent gout attacks, even with allopurinol therapy.\r\n\"	Particularly because of the association of gout with atherosclerosis, the diagnosis of gout may be a good time to advise a low-cholesterol, low-fat diet if otherwise appropriate for the patient. While such a diet may help uric acid levels, such advice should be given primarily to help prevent atherosclerosis.\r\n\"	Weight reduction in patients who are obese can improve hyperuricemia.\r\nActivity: Patients should avoid using the inflamed joint during the acute attack. Otherwise, they should be active.\r\n', NULL, NULL, NULL, NULL, '1'),
('179', 'HYPERPARATHYROIDISM', '0', 'CAUSES :\r\n\r\n1. PRIMARY HYPERPARATHYROIDISM \r\n\r\n- SINGLE ADENOMA ( 85%) & MULTIPLE GLANDS OR HYPERPLASIA  ( 15% ) \r\n- RARELY CARCINOMA\r\n- FAMILIAL CASES LIKE :\r\n* MULTIPLE ENDOCRINE NEOPLASIA SYNDROMES ( MEN 1 OR MEN 2A )\r\n* HYPERPARATHYROID-JAW TUMOR SYNDROME\r\n* FAMILIAL ISOLATED HYPERPARATHYROIDISM\r\n* FAMILIAL HYPOCALCIURIC HYPERCALCEMIA\r\n- NEONATAL SEVERE HYPERPARATHYROIDISM\r\n\r\n2. SECONDARY HYPERPARATHYROIDISM\r\n\r\n- RENAL FAILURE\r\n- RENAL CALCIUM LEAK\r\n- DIETARY CALCIUM MALABSORPTION\r\n- VIT D DEFICIENCY\r\n\r\n3. TERTIARY HYPERPARATHYROIDISM\r\n\r\n- SECONDARY HYPERPARATHYROIDISM PROGRESSING TO TERTIARY LEVEL, MAIN CAUSE RENAL FAILURE\r\n\r\n--------------------------------------------------------------------------\r\nD.D. : ALL CAUSES OF HYPERCALCEMIA\r\n\r\n1. PARATHYROID RELATED\r\n\r\nA. PRIMARY HYPERPARATHYROIDISM\r\n- SOLITARY ADENOMAS\r\n- MULTIPLE  ENDOCRINE NEOPLASIA\r\n\r\nB. LITHIUM THERAPY\r\nC. FAMILIAL HYPOCALCIURIC HYPERCALCEMIA\r\n\r\n2. MALIGNANCY RELATED\r\n\r\n- SOLID TUMOR WITH METASTASES ( BREAST )\r\n- SOLID TUMOR WITH HUMORAL MEDIATION OF HYPERCALCEMIA ( LUNG , KIDNEY )\r\n- HEMATOLOGIC MALIGNANCIES ( MULTIPLE MYELOMA , LYMPHOMA , LEUKEMIA )\r\n\r\n3. VITAMIN D RELATED \r\n- VITAMIN D INTOXICATION\r\n- HIGH 1,25 ( OH )2D ; SARCOIDOSIS & OTHER GRANULOMATOUS DISEASES\r\n- IDIOPATHIC HYPERCALCEMIA OF INFANCY\r\n\r\n4. ASSOCIATED WITH HIGH BONE TURNOVER\r\n- HYPERTHYROIDISM\r\n- IMMOBILIZATION\r\n- THIAZIDES\r\n- VIT A INTOXICATION\r\n\r\n5. ASSOCIATED WITH RENAL FAILURE\r\n- SEVERE SECONDARY HYPERPARATHYROIDISM\r\n- ALUMINUM INTOXICATION\r\n- MILK ALKALI SYNDROME', 'OTHER TESTS : \r\n* SERUM PARATHYROID HORMONE - INCREASED\r\n* SERUM CALCIUM - INCREASED\r\n* SERUM PHOSPHATE - USUALLY LOW BUT MAY BE NORMAL, ESPECIALLY IF RENAL FAILURE HAS DEVELOPED\r\n* 24 HRS URINE CALCIUM - INCREASED\r\n* VIT D ASSAY OR 25-HYDROXYVITAMIN D LEVELS - TO EXCLUDE VIT D DEFICIENCY LEVELS SHOULD BE > 20 NG / ML\r\n* SESTAMIBI SCAN - MOST USEFUL IN PARATHYROID ADENOMA( SENSITIVITY >90% ) BUT LESS SENSITIVE IN PARATHYROID HYPERPLASIA & MULTIGLANDULAR DISEASE ( SENSITIVITY < 50% ). WHEN COMBINED WITH SINGLE-PHOTON EMMISION COMPUTED TOMOGRAPHY SCANNING, IT CAN BE USED EFFECTIVELY TO LOCALIZE ECTOPIC & USUAL PARATHYROID ADENOMAS & IS STUDY OF CHOICE.\r\n* ICMA ( IMMUNOCHEMILUMINESCENT ASSAY ) OF CIRCULATING INTACT PTH\r\n* IRMA ( IMMUNORADIOMETRIC ASSAY ) OF CIRCULATING INTACT PTH\r\n* C.T. ( CERVICAL COMPUTED TOMOGRAPHY ) SCAN \r\n* SINGLE PHOTON DENSITOMETRY OF EXTREMITIES BONES FOR OSTEOPOROSIS.\r\n* INTRA OPERATIVE GUIDANCE WITH GAMA PROBE\r\n* MRI\r\n* PET ( POSITRON EMMISION TOMOGRAPHY )\r\n* INTRAVENOUS DIGITAL SUBTRACTION ANGIOGRAPHY\r\n* ARTERIOGRAPHY\r\n* SELECTIVE VENOUS SAMPLING\r\n\r\nOTHER LESS SPECIFIC TESTS :\r\n\r\n* INCREASED CLORIDE & DECREASED PHOSPHATE WITH CL/PO4 RATIO OF >33\r\n*  ELEVATED URINARY PH ( >6 )\r\n* SERUM ALK PHOSPHATASE LEVELS - INCREASED\r\nTHESE ALL SUPPORT THE DIAGNOSIS BUT ARE NOT SPECIFIC.\r\n* X-RAY FINDINGS - OSTEOPENIA & CLASSIC BUT LATE FINDINGS ARE SUBPERIOSTEAL BONE RESORPTION ALONG THE RADIAL ASPECT OF MIDDLE & DISTAL PHALYNGES & DISTAL CLAVICLE. SALT & PEPPER SKULL.\r\n\r\nPRIMARY HYPERPARATHYROIDISM : PTH IS NORMAL OR HIGH WITH HIGH SERUM CALCIUM\r\n\r\nSECONDARY HYPERPARATHYROIDISM : HIGH PTH WITH NORMAL OR LOW CALCIUM, HYPERPHOSPHATEMIA & LOW SERUM CALCITRIOL\r\n\r\nTERTIARY HYPERPARATHYROIDISM : PTH > 10-20 TIMES OF NORMAL, HYPERCALCEMIA', '0', '0', '0', '0', '0', '', 'B', '0', '* - IN FOLLOW UP MAINTAIN ADEQUATE HYDRATION, EXERCISE & NORMAL CALCIUM DIET. AVOID THIAZIDE DIURETICS, LITHIUM & EXCESSIVE CALCIUM INPUT.\r\n\r\n* - MEASURE S. CALCIUM, CREATININE, PTH, 24 HRS URINE CALCIUM, CREATININE CLEARANCE, FRACTIONAL EXCRETION OF CALCIUM, ABDOMINAL X-RAY & DEXA BONE DENSITOMETRY ( LUMBER SPINE, FEMER, FOREARM ) ANUALLY.\r\n\r\nHYPERPARATHYROIDISM IS SUBDEVIDED INTO THREE TYPES :\r\n1. PRIMARY CAUSED BY\r\n- SINGLE ADENOMA ( 85%) & MULTIPLE GLANDS ARE INVOLVED IN ( 15%) & RARELY PARATHYROID CANCER\r\n- FAMILIAL : AS PART OF MEN 1 OR MEN 2A, HYPERTHYROID-JAW TUMOR SYNDROME, FAMILIAL ISOLATED HYPERPARATHYROIDISM, FAMILIAL HYPOCALCIURIC HYPERCALCEMIA & NEONATAL SEVERE HYPERPARATHYROIDISM\r\n2. SECONDARY\r\n3. TERTIARY\r\n\r\nMedical care\r\n\r\nThe diet of individuals with primary hyperparathyroidism should include around 1200-1500 mg of calcium per day. Also, 400 IU of vitamin D per day is reasonable. Estrogen therapy in postmenopausal women has been shown to cause a small reduction in serum calcium and increases in BMD, with stable PTH. However, risks are associated with estrogen replacement. Raloxifene may be an alternative. Alendronate has also been shown to increase the spine BMD in patients with primary hyperparathyroidism. Calcimimetic drugs may be an alternative in the future.\r\n\r\nOther medical therapy is limited to the treatment of hypercalcemia itself. In the acute setting, this can be accomplished by the use of intravascular volume expansion with sodium chloride and loop diuretics such as furosemide once the intravascular volume is restored. In rare cases, hypercalcemia has been treated with bisphosphonate therapy as a temporary measure prior to surgical treatment.\r\n\r\nSurgical care\r\n\r\nIndications for surgery\r\n\r\n\r\nSymptomatic hyperparathyroidism should be treated by surgical excision of the abnormal glands.\r\n\r\n\r\nSome clinicians advocate surgical therapy in all patients with primary hyperparathyroidism, modified only for those patients who are not able to tolerate surgery. They argue that the operation is generally well tolerated and such treatment prevents complications (eg, osteoporosis) and may reverse symptoms that patients often do not realize they have (eg, fatigue, depression). Others advocate a nonsurgical approach whenever possible, such as in patients with a calcium level less than 11.5 mg/dL, patients with no apparent symptoms, and patients who have normal 24-hour urine calcium excretion and no osteoporosis.\r\n\r\n\r\nA National Institutes of Health (NIH) Workshop on Asymptomatic Primary Hyperparathyroidism in 2002 revisited the key management issues addressed at the 1990 NIH Consensus Development Conference. They recommended new guidelines for surgery and the conservative approach of monitoring patients who do not meet the criteria for surgery. The indications for surgery as per the 2002 guidelines are as follows:\r\n\r\n\r\n1.0 mg/dL above the upper limit of the reference range for serum calcium\r\n\r\n\r\n24-hour urinary calcium excretion greater than 400 mg\r\n\r\n\r\nA 30% reduction in creatinine clearance\r\n\r\n\r\nBone mineral density T-score below -2.5 at any site\r\n\r\n\r\nAge less than 50 years\r\n \r\nFor monitoring of patients with asymptomatic hyperparathyroidism who do not undergo surgery, the following are recommended: serum calcium and creatinine levels every 6 months and annual bone mineral density (all 3 sites).\r\n\r\nChoice of surgical treatment\r\n\r\n\r\nThe standard operative approach is complete neck exploration with identification of all parathyroid glands and removal of all abnormal glands. In the case of 4-gland hyperplasia, a 3.5-gland (subtotal) parathyroidectomy is performed. Approximately 50-70 mg of the most normal-appearing tissue is left behind. A nonabsorbable suture is left as a tag to identify the gland should reoperation be necessary.\r\n\r\n\r\nApproximately 85% of cases of primary hyperparathyroidism are caused by a single adenoma. Therefore, most patients who undergo full neck exploration to evaluate all parathyroids endure some unnecessary dissection. Rather than explore all parathyroid glands, a newer technique, directed parathyroidectomy, has evolved. This technique relies on preoperative imaging studies to localize the abnormal gland. The surgeon then removes only that gland, without visualizing the other glands.\r\n\r\n\r\nWith either sestamibi scanning or ultrasonography, an abnormal parathyroid may be detected preoperatively in 70-80% of cases. However, neither technique is reliable for detecting multiple abnormal glands. Therefore, an additional method is required to confirm that no other abnormal glands are present after excision of the imaged lesion.\r\n\r\n\r\nFor this purpose, many centers have begun to use the intraoperative PTH assay. Because the plasma half-life of PTH is only approximately 4 minutes, the level falls quickly after resection of the source. If the level fails to fall after resection of the identified abnormal gland, the procedure is extended to allow for further exploration. However, the intraoperative PTH assay is expensive and is usually available only in centers that perform a high volume of parathyroidectomies.\r\n\r\n\r\nA few authors have advocated radio-guided parathyroidectomy, detecting the labeled sestamibi in the abnormal gland using a handheld probe. The excised radioactivity in the abnormal parathyroid is then compared with the remaining background to confirm excision of all affected glands. However, most centers have abandoned this technique because (1) if the gland labels well with sestamibi, use of the handheld probe intraoperatively is unnecessary in most cases and (2) the use of background counts to confirm complete excision of all abnormal tissue has not been well validated.\r\n\r\n\r\nUse of directed parathyroidectomy results in a more limited operation for most patients, resulting in a more rapid recovery. However, it may yield a higher persistence rate than complete neck exploration, and it probably should be performed only in centers with the capability to perform the intraoperative PTH assay.\r\n\r\n\r\nFor familial disease, such as MEN 1, total parathyroidectomy is performed with autotransplantation to the forearm and cryopreservation of some parathyroid tissue.\r\n \r\nPreoperative care\r\n\r\n\r\nParathyroidectomy is usually well tolerated. The main risks are those associated with anesthesia. Although local anesthesia has been used successfully for this procedure, especially in the directed approaches where a single adenoma is localized preoperatively, general anesthesia is used most commonly.\r\n\r\n\r\nIn patients in whom hypercalcemia (and, therefore, dehydration) has been severe, special attention must be directed to perioperatively restoring the fluid balance.\r\n\r\n\r\nNeck mobility must be assessed to ensure proper positioning in the operating room.\r\n\r\n\r\nIf the patient\'s voice is normal, preoperative documentation of vocal cord function is not necessary.\r\n \r\nIntraoperative details\r\n\r\n\r\nComplete parathyroid exploration\r\n\r\n\r\nThe most critical aspect to ensure success in this operation is identification of all 4 parathyroid glands and removal of all abnormal glands.\r\n\r\n\r\nThe patient is placed in the lawn-chair position with the neck extended over a transversely placed shoulder roll. This position allows full exposure of anterior neck structures and improves venous drainage.\r\n\r\n\r\nA low transverse incision placed within the skin creases provides the best cosmetic result. The length of the incision must be adequate to allow thorough exploration of all potential locations of the parathyroid glands; however, given the elasticity of the neck skin flaps, a 3- to 5-cm incision allows safe identification of important structures.\r\n\r\n\r\nAfter hemostasis of the skin incision is obtained, subplatysmal flaps are developed superiorly to the notch of the thyroid cartilage and inferiorly to the flat portion of the manubrium. The sternohyoid and sternothyroid (strap) muscles are separated in the midline to expose the thyroid gland. If preoperative localization studies suggest a parathyroid adenoma, that side is approached first.\r\n\r\n\r\nFrequently, a middle thyroid vein may require ligation to ensure adequate mobilization of the thyroid lobe. The thyroid lobe is elevated off the common carotid artery and retracted medially. The inferior thyroid artery is identified after blunt and sharp dissection of the areolar tissue anteriorly and medially to the common carotid artery and posteromedially to the thyroid lobe. The recurrent laryngeal nerve is identified next, inferior and lateral to the lower lobe of the thyroid gland.\r\n\r\n\r\nThe intersection of the inferior thyroid artery and the recurrent laryngeal nerve is an important landmark because most parathyroid glands, superior and inferior, are located within 2 cm of this area. The superior parathyroid glands are located dorsal to the upper two thirds of the thyroid lobe and posterior to the recurrent laryngeal nerve. The inferior glands, which are less consistent in location, can usually be found inferior to the inferior thyroid artery and ventral to the recurrent laryngeal nerve. They are usually within 1 cm of the inferior lobe of the thyroid gland.\r\n\r\n\r\nAbnormally enlarged glands are excised after confirmation of the normal size of other glands. During excision, avoiding capsular rupture of the abnormal gland is important because this may be associated with implantation of parathyroid cells in the operative site and subsequent parathyromatosis. Parathyroids may be identified by highly experienced surgeons based on appearance and location. In most cases, identification of the parathyroid glands should be confirmed histologically by frozen section examination. In all cases of subtotal or total parathyroidectomy with autotransplantation, parathyroid tissue must be cryopreserved for future autotransplantation if the initial transplants are not functional.\r\n \r\nDirected parathyroidectomy\r\n\r\n\r\nIn many respects, the operative technique is similar to that described above for a complete parathyroid exploration. Differences are noted below.\r\n\r\n\r\nAdequate imaging of the abnormal gland prior to surgery is essential. In addition, arrangements for intraoperative measurement of PTH should be confirmed. A line for sampling of peripheral venous blood should be established. Often the distal saphenous vein provides the most convenient access.\r\n\r\n\r\nSome surgeons modify the location of the incision based on the preoperative location of the adenoma. This author prefers a small incision (ie, ~2 cm) in the standard location for a collar incision. This incision can be readily extended should a complete exploration prove necessary.\r\n\r\n\r\nA baseline PTH level is drawn immediately prior to skin incision. Following identification and dissection of the adenoma, a preexcision level is drawn. Manipulation of the gland occasionally causes significant increases in the PTH level. Following excision of the gland, PTH levels are drawn at 5 minutes and 10 minutes postexcision. Criteria for adequate excision are either: a 50% drop in PTH from the baseline level to the 10-minute post-excision level or a 50% drop in PTH from the preexcision level at 10 minutes and a postexcision level below the baseline level.\r\n\r\n\r\nThe incision may be closed while the last PTH levels are being processed, but the patient should remain under anesthesia and the sterile field maintained until the PTH assay results are known.\r\n \r\nEctopic parathyroid glands\r\n\r\n\r\nOccasionally, all parathyroid glands cannot be identified. In such instances, the usual locations are reexamined first because most parathyroid glands are located in typical areas. If parathyroid glands are not identified in those locations, then a systematic search is performed, taking into consideration the path of descent of superior and inferior parathyroid glands.\r\n\r\n\r\nInferior glands may be located in the thyrothymic ligament. They may be difficult to identify, especially after division of the inferior thyroid vein, a maneuver that allows the gland to retract into the superior mediastinum. Another location for ectopic inferior parathyroid glands is the thymus. The thymus can be visualized through a transverse cervical incision by retracting the innominate vein dorsally with a sponge-stick while elevating the manubrium anteriorly. Division of the interclavicular ligament improves visualization in the superior mediastinum.\r\n\r\n\r\nSuperior parathyroid glands are usually dorsal to the upper two thirds of the thyroid gland. Occasionally, these glands are adjacent to the superior thyroid vessels. Other locations include the carotid sheath or posterior to the esophagus or pharynx (retroesophageal). Finally, both superior and inferior parathyroid glands may be located aberrantly within the capsule of the thyroid gland. Some surgeons perform a thyroid lobectomy on the side harboring the abnormal gland after an exhaustive search is made in the aforementioned locations. Median sternotomy is rarely required during the initial neck exploration for hyperparathyroidism.\r\n\r\nPostoperative care\r\n\r\n\r\nIf a directed parathyroidectomy is performed successfully, most of these patients may be safely discharged the day of surgery. Some practitioners routinely supplement with oral calcium postoperatively.\r\n\r\n\r\nFor a full parathyroid exploration, calcium levels must be monitored postoperatively every 12 hours until stabilization. The nadir of serum calcium usually occurs 24-72 hours postoperatively. Many patients become hypocalcemic, but few become symptomatic. Reserve treatment for hypocalcemia unless it is severe or the patient becomes symptomatic.\r\n\r\n\r\nHypocalcemia after parathyroid surgery may be due to hungry bone syndrome where calcium and phosphorus are rapidly deposited in the bone. This is characterized by hypoparathyroidism and transient, but occasionally severe, hypocalcemia until the normal glands regain sensitivity.\r\n\r\n\r\nIf hypoparathyroidism persists, oral supplementation with calcium and vitamin D is required. Calcium citrate or calcium carbonate may be started at 2 tablets 4 times per day. Some patients require more or less. Calcitriol is started at 1 mcg/d for 1 day, 0.5 mcg/d for 2 days, and then 0.25 mcg/d thereafter. Patients in whom an autotransplantation is performed require temporary calcium supplementation.\r\n\r\n\r\nIf a recurrent nerve injury is suggested because the patient has developed new hoarseness, immediate laryngoscopy is indicated. If vocal cord paralysis is observed, immediate reoperation may be warranted to repair a transected nerve because a few of these may regain function. Reexploration after 24-48 hours is not generally indicated because the risks of operating in an inflamed field outweigh the relatively low likelihood of a benefit.\r\n\r\n\r\nA potential life-threatening emergency in the postoperative period is the development of an expanding hematoma in the pretracheal space. This complication must be recognized and treated immediately by opening the wound and evacuating the hematoma. If untreated, laryngeal edema may progress rapidly, causing airway obstruction.\r\n\r\n\r\nMost small hematomas do not require treatment. A subplatysmal fluid collection may occasionally form, and these are usually treated adequately with a single aspiration. In a few cases, aspiration may need to be repeated. Rarely, a drain may need to be placed for recurrent fluid collections.\r\nFollow-up\r\n\r\nPatients are seen 1-2 weeks postoperatively, and serum calcium and PTH levels are obtained. PTH levels may be elevated postoperatively in some patients, but if the serum calcium remains within the reference range it does not indicate persistent disease in most patients.\r\n\r\nAfter the immediate postoperative period, follow-up is limited to periodic determinations of serum calcium levels to detect the persistence or recurrence of disease or hypoparathyroidism.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('180', 'HYPERTENSION , ESSENTIAL', '0', 'CLASSIFICATION OF HYPERTENSION:\r\n\r\n1. SYSTOLIC HYPERTENSION WITH WIDE PULSE PRESSURE\r\n\r\n* DECREASED COMPLIANCE OF AORTA( ARTERIOSCLEROSIS)\r\n* INCREASED STROKE VOLUME\r\n- AORTIC REGURGITATION\r\n- THYROTOXICOSIS\r\n- HYPERKINETIC HEART SYNDROME\r\n- FEVER\r\n- ARTERIOVENOUS FISTULA\r\n- PATENT DUCTUS ARTERIOSUS\r\n\r\n2. SYSTOLIC & DIASTOLIC HYPERTENSION\r\n\r\nA. RENAL\r\n- CHRONIC PYELONEPHRITIS\r\n- AC & CHR GLOMERULONEPHRITIS\r\n- POLYCYSTIC RENAL DISEASE\r\n- COLLAGEN DISEASE LIKE POLYARTERITIS NODOSA , SCLERODERMA , SLE\r\n- ANALGESIC NEPHROPATHY\r\n- HEREDITARY NEPHRITIS\r\n- GOUTY NEPHROPATHY\r\n- IRRADIATION NEPHROPATHY\r\n- AMYLOIDOSIS\r\n- RENAL TUBERCULOSIS\r\n- URINARY TRACT OBSTRUCTION ( UNUSUAL )\r\n- HEAVY METAL POISONING ( LEAD, CADMIUM ) \r\n- INTRINSIC PRESSURE FROM TUMOR OR CYSTS\r\n- EXTRINSIC PRESSURE FROM TUMOR, FIBROUS OR MUSCULAR BANDS\r\n- FIBROMUSCULAR DYSPLASIA\r\n- RENOVASCULAR STENOSIS OR RENAL INFARCT\r\n- MOST OTHER SEVERE RENAL DISEASES ( ARTERIOLAR NEPHROSCLEROSIS , DIABETIC NEPHROPATHY ETC.\r\n- RENIN PRODUCING TUMORS\r\n\r\nB. ENDOCRINE \r\n* ORAL CONTRACEPTIVES\r\n* ADRENOCORTICAL HYPERFUNCTION\r\n- CUSHING DISEASE & SYNDROME\r\n- PRIMARY HYPERALDOSTERONISM\r\n- CONGENITAL OR HEREDITARY ADRENOGENITAL SYNDROMES ( 17 ALPHA-HYDROXYLASE & 11 BETA HYDROXYLASE DEFECTS )\r\n- PHEOCHROMOCYTOMA\r\n- MYXEDEMA\r\n- ACROMEGALY\r\n- LIDDLE SYNDROME\r\n- ISOLATED SECRETION OF DEOXYCORTICOSTERONE , CORTICOSTERONE , 18-HYDROXY-DEOXYCORTICOSTERONE\r\nC. NEUROGENIC\r\n- PSYCHOGENIC\r\n- DIENCEPHALIC SYNDROME\r\n- FAMILIAL DYSAUTONOMIA ( RILEY-DAY )\r\n- POLYNEURITIS ( AC PORPHYRIA, LEAD POISONING )\r\n- INCREASED INTRACRANIAL PRESSURE ( ACUTE )\r\n- SPINAL CORD SECTION ( ACUTE )\r\n\r\nD. MISCELLANEOUS\r\n-COARCTATION OF AORTA\r\n- INCREASED INTRAVASCULAR VOLUME ( EXCESSIVE TRANSFUSION, POLYCYTHEMIA VERA)\r\n- POLYARTERITIS NODOSA\r\n- HYPERCALCEMIA\r\n- MEDICATIONS LIKE STEROIDS, CYCLOSPORINE\r\n\r\nE. UNKNOWN ETIOLOGY\r\n- ESSENTIAL HYPERTENSION( > 90% )\r\n- TOXEMIA OF PREGNANCY\r\n- AC INTERMITTENT PORPHYRIA\r\n', 'OTHER TESTS :\r\n* E.C.G.\r\n* RENAL ANGIOGRAPHY\r\n* URINARY CATECHOLAMINES\r\n* URINE CORTISOL LEVELS & DEXAMETHASONE SUPPRESSION TEST\r\n* PLASMA RENIN ACTIVITY &  PLASMA & URINARY ALDOSTERONE LEVELS.\r\n* CAPTOPRIL CHALLANGE TEST- ABNORMAL IN HYPERTENSION', '1', '0', '0', '1', '0', 'Studies have shown that diet and a healthy lifestyle alone or in combination with medical treatment can lower the BP and decrease the symptoms of heart failure and can also reverse LVH.', 'B', '0', '- 0.05 TO 12% MAY HAVE PRIMARY ALDOSTERONISM\r\n- THE RISK OF LVH INCREASES TWO FOLDS BY ASSOCIATED OBESITY.\r\n- CHR. & SEVERE HYPERTENSION CAN CAUSE AORTIC ROOT DILATATION LEADING TO SIGNIFICANT AORTIC REGURGITATION.\r\n- COMMON CARDIAC ARRHYTHMIAS SEEN IN HYPERTENSION ARE ATRIAL FIBRILLATION, VENTRICULAR ECTOPIC & VENTRICULAR TACHYCARDIA.\r\n\r\nMedical Care: The medical care of patients with hypertensive heart disease falls under 2 categories-treatment of the elevated BP and prevention and treatment of hypertensive heart disease. The BP goal should be less than 140/90 mm Hg in patients without diabetes or chronic kidney disease and less than 130/90 mm Hg in those with either of these diseases. Various treatment strategies include dietary modifications, regular aerobic exercise, weight loss, and pharmacotherapy directed toward hypertension, heart failure secondary to diastolic and systolic LV dysfunction, coronary artery disease, and arrhythmias. \r\n\"	Dietary modifications \r\no	 Specific diet recommendations include a diet low in sodium, high in potassium (in patients with normal renal function), rich in fresh fruits and vegetables, low in cholesterol, and low in alcohol consumption. \r\no	A low-sodium diet, alone or in combination with pharmacotherapy, has been shown by numerous studies to reduce BP in patients with hypertension, with a more prominent response in a subset of patients with hypertension-mainly African Americans-with low renin levels. Restriction of sodium in these patients does not lead to compensatory stimulation of the renin-angiotensin system and thus has a potent antihypertensive effect. The recommended daily sodium intake is 50-100 mmol, equivalent to 3-6 g of salt per day, which leads to an average 2-8 mm of Hg reduction in BP. \r\no	In various epidemiological studies, a high-potassium diet has been associated with lowering of the BP. The mechanism of this action is not clear. Intravenous infusion of potassium has been shown to cause vasodilatation, which is believed to be mediated by nitric oxide in the vascular wall. Foods rich in potassium, such as fresh fruit and vegetables, should be recommended for patients with normal renal function. \r\no	A diet rich in fresh fruits and vegetables, known as the DASH diet, has been shown to significantly lower the BP (8-14 mm Hg) in patients with hypertension regardless of them maintaining a constant sodium content in their diet. This diet should be advised in patients with hypertension. \r\no	A low-cholesterol diet is part of secondary prophylaxis in patients with coronary artery disease. It is also a part of the primary prophylaxis of coronary artery disease in patients at high risk for this disease. \r\no	Heavy alcohol consumption has been associated with high BP and an increase in LV mass. Moderation in alcohol consumption is advised; no more than 1-2 drinks per day is recommended.\r\n\"	Regular aerobic exercise \r\no	Regular dynamic isotonic exercise, such as walking, running, swimming, or cycling, has been shown to decrease BP and improve cardiovascular well-being. Regular isotonic exercise has additional favorable cardiovascular effects, including improved endothelial function, peripheral vasodilatation, reduced resting heart rate, improved heart rate variability, and reduced plasma levels of catecholamines. \r\no	Regular 30-minute sessions of aerobic exercise 3-4 times a week should be advised. Average reduction in BP with regular aerobic exercise such as walking at least 30 minutes most days of the week is 4-9 mm of Hg. Isometric and strenuous exercise should be avoided.\r\n\"	Weight reduction \r\no	Obesity has been linked to hypertension and LVH in various epidemiological studies, with as many as 50% of obese patients having some degree of hypertension and as many as 60-70% of patients with hypertension being obese. Abdominal adiposity, clinically measured as waist-to-hip ratio and more accurately assessed by abdominal CT scan, is a more sensitive risk factor for hypertension. Studies have shown that weight reduction is one of the most effective ways to reduce BP. A 5-20 mm Hg BP reduction occurs with each 10 kg of weight loss. \r\no	Gradual weight reduction (1 kg/wk) should be advised. Pharmacological interventions to reduce weight should be used with great caution because diet pills, especially those available over the counter, frequently contain sympathomimetics. These can raise BP, worsen angina or symptoms of heart failure, and exacerbate tendencies for cardiac arrhythmias. \r\n\"	Pharmacotherapy \r\no	Treatment of hypertension and hypertensive heart disease can involve the following classes of antihypertensive medications: thiazide diuretics, beta-blockers and combined alpha- and beta-blockers, calcium channel blockers, ACE inhibitors, angiotensin receptor blockers, and direct vasodilators such as hydralazine. Most patients require 2 or more antihypertensive drugs to achieve the BP goal, and, when the BP is more than 20/10 mm Hg above the goal, consider initiating treatment with 2 drugs, either as separate prescriptions or in fixed-dose combinations. \r\no	Thiazide diuretics are the drugs of first choice in most patients with uncomplicated hypertension, as outlined by the Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure. \r\no	Drugs from other classes can be used in the presence of compelling indications. \r\n\"	Calcium channel blockers are effective for systolic hypertension in elderly patients. \r\n\"	ACE inhibitors are the first choice in patients with diabetes and/or LV dysfunction. \r\n\"	Angiotensin receptor blockers are a reasonable alternative, especially for patients with adverse effects with ACE inhibitors. \r\n\"	Beta-blockers are the drugs of first choice in patients with heart failure due to systolic LV dysfunction, patients with ischemic heart disease with or without a history of myocardial infarction, and in patients with thyrotoxicosis. \r\n\"	Peripheral alpha-channel blockers should be avoided in patients with hypertension in view of recent findings of their adverse effect on cardiovascular morbidity and mortality rates. \r\n\"	Central alpha-antagonists have no evidence-based support and have more adverse effects. \r\no	Intravenous drugs used in patients with a hypertensive emergency include nitroprusside, labetalol, hydralazine, enalapril, and beta-blockers (avoided in patients with acutely decompensated heart failure). \r\n\"	Treatment of LVH \r\no	LVH, a marker of increased risk of cardiovascular morbidity and mortality, should be treated aggressively. Whether regression in LVH leads to improvement in cardiovascular mortality and morbidity rates is not clear, although limited data support this hypothesis. \r\no	All the medications already listed for the treatment of hypertension have been shown to reduce LVH. Limited meta-analysis data suggest a slight advantage to ACE inhibitors.\r\n\"	Treatment of LV diastolic dysfunction \r\no	Certain classes of antihypertensives-ACE inhibitors, beta-blockers, and nondihydropyridine calcium channel blockers-have been shown (although not consistently) to improve echocardiographic parameters in symptomatic and asymptomatic diastolic dysfunction and the symptomatology of heart failure. \r\no	Use diuretics and nitrates with caution in patients with heart failure due to diastolic dysfunction. These drugs may cause severe hypotension by inappropriately decreasing the preload, which is required for adequate LV filling pressures. If diuretics are indicated, delicate titration is necessary. \r\no	Hydralazine has been shown to cause severe hypotension in patients with heart failure due to diastolic dysfunction. \r\no	By increasing the intracellular calcium level, digoxin can worsen LV stiffness. However, a large randomized trial has not shown any increase in mortality rate.\r\n\"	Treatment of LV systolic dysfunction\r\no	Diuretics (predominantly loop diuretics) are used in the treatment of LV systolic dysfunction. \r\no	ACE inhibitors are used for preload and afterload reduction and prevention of pulmonary or systemic congestion. They have been shown to decrease morbidity and mortality rates in patients with heart failure due to systolic dysfunction. The aim should be to use the target dose or the maximum tolerable doses. ACE inhibitors are also indicated in patients with asymptomatic LV dilatation and dysfunction. \r\no	Beta-blockers (cardioselective or mixed alpha and beta), such as carvedilol, metoprolol XL, and bisoprolol, have been shown to improve LV function and decrease rates of mortality and morbidity from heart failure. Recent trials have also shown improvement in outcomes for patients in NYHA class IV heart failure with carvedilol administration. These drugs should be started when the patient has no signs of fluid overload and is in compensated heart failure. Therapy should be initiated with low doses, increasing the dose of the beta-blocker very slowly and closely monitoring the patient for signs of worsening heart failure. \r\no	Low-dose spironolactone has been shown to decrease the rates of morbidity and mortality in patients in NYHA class III or IV heart failure who are already taking ACE inhibitors.\r\n\"	Treatment of cardiac arrhythmias\r\no	Treatment depends upon the specific arrhythmia and the underlying LV function. \r\no	Anticoagulation should be considered in patients with atrial fibrillation.\r\nSurgical Care: Surgical treatment may be necessary for definitive treatment in selected cases of secondary causes for hypertension. \r\nDiet: Specific diet recommendations include a diet low in sodium, high in potassium, rich in fresh fruits and vegetables, low in cholesterol, and low in alcohol intake. \r\nActivity: Regular 30-minute sessions of aerobic exercise 3-4 times a week should be advised. Isometric and strenuous exercise should be avoided. \r\n\r\nDRUG TREATMENT :\r\n\r\n1. THIAZIDES & RELATED DIURETICS :\r\n\r\n- HYDROCHLORTHIAZIDE\r\n- CHLORTHALIDONE\r\n\r\n2. ALPHA / BETA ADRENERGIC BLOCKING DRUGS :\r\n\r\n- CARVEDILOL\r\n\r\n3. BETA ADRENERGIC BLOCKING DRUGS :\r\n\r\n- BISOPROLOL\r\n- ATENOLOL\r\n- METOPROLOL\r\n\r\n4. ACE INHIBITORS :\r\n\r\n- CAPTOPRIL\r\n- FOSINOPRIL\r\n- RAMIPRIL\r\n\r\n5. ANGIOTENSIN II RECEPTOR BLOCKERS :\r\n\r\n- LOSARTAN\r\n- VALSARTAN\r\n- CANDESARTAN\r\n- IRBESARTAN\r\n- EPROSARTAN\r\n- OLMESARTAN\r\n\r\n6. CALCIUM CHANNEL BLOCKERS, NONDIHYDROPYRIDINES :\r\n\r\n- DILTIAZEM\r\n- VERAPAMIL\r\n\r\n7. CALCIUM CHANNEL BLOCKERS, DIHYDROPYRADINES :\r\n\r\n- AMLODIPNE\r\n- FELODIPINE\r\n- NIFEDIPINE\r\n\r\n8. PERIPHERAL VASODILATOR:\r\n\r\n- HYDRALAZINE\r\n\r\n9. ALDOSTERONE ANTAGONIST :\r\n\r\n- SPIRONOLACTONE  \r\n', NULL, NULL, NULL, NULL, '1'),
('185', 'HYPOTHYROIDISM', '0', 'CAUSES :\r\n\r\n1. PRIMARY\r\n\r\nA. AUTOIMMUNE HYPOTHYROIDISM :\r\n- HASHIMOTO THYROIDITIS\r\n- ATROPHIC THYROIDITIS\r\n\r\nB. IATROGENIC \r\n- IODINE-131 TREATMENT\r\n- SUBTOTAL OR TOTAL THYROIDECTOMY\r\n- EXTERNAL RADIATION OF NECK FOR LYMPHOMA OR CANCER\r\n\r\nC. DRUGS :\r\n- IODINE EXCESS\r\n- AMIODARONE\r\n- LITHIUM\r\n- ANTITHYROID DRUGS\r\n- PARA AMINOSALICYLIC ACID\r\n- INTERFERON- ALPHA & OTHER CYTOKINES\r\n- AMINOGLUTETHIMIDE\r\n\r\nD. CONGENITAL HYPOTHYROIDISM \r\n- ABSENT OR ECTOPIC THYROID GLAND\r\n- DYSHORMOGENESIS\r\n- TSH-R MUTATION\r\n\r\nE. IODINE DEFICIENCY\r\n\r\nF. INFILTRATIVE DISORDERS\r\n- AMYLOIDOSIS\r\n- SARCOIDOSIS\r\n- HEMOCHROMATOSIS\r\n-SCLERODERMA\r\n- CYSTENOSIS\r\n- RIEDELS THYROIDITIS\r\n\r\n2. TRANSIENT \r\n\r\n- SILENT THYROIDITIS , INCLUDING POSTPARTUM\r\n- SUBACUTE THYROIDITIS\r\n- WITHDRAWAL OF THYROXINE TREATMENT IN PATIENTS WITH INTACT THYROID\r\n- AFTER I-131 TREATMENT OR SUBTOTAL THYROIDECTOMY FOR GRAVES DISEASE\r\n\r\n3. SECONDARY \r\n\r\nA. HYPOPITUITARISM :\r\n- TUMORS\r\n- PITUITARY SURGERY OR IRRADIATION\r\n- INFILTRATIVE DISORDERS\r\n- SHEEHAN SYNDROME\r\n- TRAUMA\r\n- GENETIC FORMS OF COMBINED PITUITARY HORMONE DEFICIENCIES\r\n\r\nB. ISOLATED TSH DEFICIENCY OR INACTIVITY\r\n\r\nC. BEXAROTENE TREATMENT\r\n\r\nD. HYPOTHALAMIC DISEASE \r\n- TUMORS\r\n- TRAUMA\r\n- INFILTRATIVE DISORDERS\r\n- IDIOPATHIC', 'THYROID ANTIBODIES : \r\n1. THYROID PEROXIDASE ANTIBODIES - POSITIVE IN AUTOIMMUNE HYPOTHYROIDISM\r\n2. THYROGLOBULIN TITRE > 1 : 100 SIGNIFICANT.\r\n3. TBII ( TSH-BINDING INHIBITING IMMUNOGLOBULINS ) - IN 10-20 % PTS.\r\n4. NORMOCYTIC, NORMOCHROMIC ANEMIA, HYPONATREMIA, HYPERCHOLESTEROLEMIA, HYPERTRIGLYCERIDEMIA, ELEVATED CREATINE PHOSPHOKINASE & LDH LEVELS.\r\n5. TRIIODOTHYRONINE( T3 ) RESIN UPTAKE - LOW\r\n6. REVERSE T3 LEVELS  - LOW\r\n* T4 LEVELS ARE PROPORTIONATELY MORE REDUCED THAN T3\r\n* TSH LEVELS - INCREASED', '0', '0', '0', '0', '0', 'RISK FACTORS: Risk increases with increasing age, Autoimmune diseases, Previous postpartum thyroiditis, Previous head or neck irradiation', 'B', '0', '- LOOK FOR OTHER ENDOCRINE PATHOLOGIES\r\n- PROLONGED HYPOTHYROIDISM CAN PRODUCE PITUITARY HYPERPLASIA PRODUCING PSUDOTUMOR.\r\n\r\n\r\nMedical Care\r\nThe treatment goals for hypothyroidism are the reversal of clinical progression and the correction of metabolic derangements as evidenced by normal blood levels of TSH and free T4. Thyroid hormone is administered to supplement or replace endogenous production. In general, hypothyroidism can be adequately treated with a constant daily dose of LT4. \r\n\r\nClinical benefits begin in 3-5 days and level off after 4-6 weeks. Anticipated full replacement doses may be initiated in individuals who are otherwise young and healthy. In elderly patients or those with known ischemic heart disease, treatment should begin with one fourth to one half the expected dose, and the dose should be adjusted in small increments every 4-6 weeks.\r\n\r\nAchieving a TSH level within the reference range may be slowed because of delay of hypothalamic-pituitary axis readaptation. After dose stabilization, patients can be monitored with annual clinical evaluations and TSH monitoring. Patients should be monitored for symptoms and signs of overtreatment, which include tachycardia, palpitations, nervousness, tiredness, headache, increased excitability, sleeplessness, tremors, and possible angina.\r\n\r\nTriiodothyronine (T3): Anecdotally, patients whose symptoms are not well controlled with T4 alone report benefits from combination therapy with T3 and T4. The optimal ratio of T4/T3 to be administered is not known, and, although some studies have shown an improvement in certain psychologic tests using a ratio of 4:1, other randomized trials have not confirmed this.\r\n\r\n\r\nPregnancy\r\n\r\nHypothyroidism in pregnancy is associated with preeclampsia, anemia, postpartum hemorrhage, cardiac ventricular dysfunction, spontaneous abortion, low birthweight, impaired cognitive development, and fetal mortality. Even mild disease may be associated with adverse affects for offspring.\r\n\r\n\r\nIncreased dosage requirements should be anticipated during pregnancy, especially in the first and second trimesters. Recent studies have suggested that patients with hypothyroidism should augment the LT4 dose by 30% at the confirmation of pregnancy, followed by adjustments according to TSH levels. \r\n \r\nSubclinical hypothyroidism\r\n\r\nSignificant controversy persists regarding the treatment of patients with mild hypothyroidism. Some have argued that treatment of these patients improves symptoms, prevents progression to overt hypothyroidism, and may have cardioprotective benefits. Recent reviews by the American Medical Association and US Preventive Services Task Force have found inconclusive evidence to recommend aggressive treatment of patients with TSH levels of 4.5-10 mU/L.\r\n\r\n\r\nFollowing subclinical hypothyroidism and treating on a case by case basis is reasonable.\r\n\r\nSurgical Care\r\nSurgery is indicated for large goiters that compromise tracheoesophageal function; surgery is rarely needed in patients with hypothyroidism and is more common in the treatment of hyperthyroidism.\r\n\r\nConsultations\r\nRefer patients with a nodular thyroid, suspicious thyroid nodules, dysphasia, or inconsistent symptoms to an endocrinologist for consultation. Some patients with thyroiditis can develop hyperthyroidism (or symptoms consistent with hyperthyroidism) before developing hypothyroidism and may benefit from consultation with an endocrinologist. Suspected myxedema coma is a medical emergency with a high risk of mortality that requires initiation of parenteral LT4 and glucocorticoids prior to laboratory confirmation. An urgent endocrinologist consultation should be obtained.\r\n\r\nDiet\r\nNo specific diets are required.\r\n\r\nActivity\r\nPatients who have hypothyroidism have generalized hypotonia and may be at risk for ligamental injury, particularly from excessive force across joints. Thus, patients should exercise caution with certain activities, such as contact sports or heavy physical labor.\r\n\r\nPatients with uncontrolled hypothyroidism may have difficulty maintaining concentration in low-stimulus activities and may have slowed reaction times. Patients should use caution if an activity has a risk of injury (eg, operating presses or heavy equipment, driving).\r\n\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('199', 'IRRITABLE BOWEL SYNDROME', '0', 'DIAGNOSTIC CRITERIA OF IBS :\r\n\r\nABDOMINAL PAIN / DISCONFORT RELIEVED WITH DAEFECATION AND / OR WITH CHANGE IN STOOL FREQUENCY AND / OR \r\nWITH CHANGE IN STOOL CONSISTANCY\r\n + \r\nTWO OR MORE OF THE FOLLOWING AT LEAST 25 % OF THE TIME\r\n\r\n- CHANGE IN STOOL FREQUENCY\r\n- CHANGE IN CONSISTANCY\r\n- DIFFICULT STOOL PASSAGE\r\n- SENSE OF INCOMPLETE EVACUATION\r\n- PRESENCE OF MUCUS IN STOOL\r\n\r\nALL THESE SYMPTOMS MUST BE PRSENT FOR > 3 MTHS\r\n\r\n--------------------------------------------------------------------------\r\nD.D. :\r\n\r\n- ABDOMINAL ANGINA\r\n- ANXIETY DISORDERS\r\n- BACTERIAL OVER GROWTH SYNDROME\r\n- BILIARY COLIC\r\n- BILIARY DISEASE\r\n- CELIAC SPRUE\r\n- CHRONIC MESENTERIC ISCHAEMIA\r\n- COLLAGENOUS & LYMPHOCYTIC COLITIS\r\n- COLON CARCINOMA, ADENOCARCINOMA\r\n- ENDOMETRIOSIS\r\n- FOOD ALLERGIES\r\n- GASTROENTERITIS, BACTERIAL / VIRAL\r\n- GIARDIASIS\r\n- HYPERCALCEMIA\r\n- HYPERTHYROIDISM\r\n- HYPOTHYROIDISM\r\n- INFLAMMATORY BOWEL DISEASE\r\n- MALIGNANT NEOPLASM OF SMALL INTESTINE\r\n- MESENTERIC ARTRY THROMBOSIS\r\n- MESENTERIC VENOUS THROMBOSIS\r\n- PANCREATIC CANCER\r\n- PANCREATITIS, CHRONIC\r\n- PHEOCHROMOCYTOMA\r\n- PORPHYRIA, ACUTE INTERMITTENT\r\n- POST CHOLECYSTECTOMY SYNDROME\r\n- SOMATOSTATINOMAS\r\n- LEAD TOXICITY\r\n- ULCERATIVE COLITIS\r\n- Infectious colitis\r\n- Medication adverse effects\r\n- Secretory diarrhea\r\n- Lactose intolerance\r\n- Fructose intolerance\r\n- VIPoma\r\n- Gastrinoma\r\n\r\n', '\r\n* DIAGNOSIS BY EXCLUSION\r\n* MUCOSAL BIOPSY FROM RECTO-SIGMOID REGION.', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: \r\n\"	Successful management relies on a strong patient-physician relationship.\r\n\"	Reassure the patient that the absence of an organic pathology indicates a normal life expectancy.\r\n\"	Emphasize the expected chronicity of symptoms with periodic exacerbations.\r\n\"	Teach the patient to acknowledge stressors and to use avoidance techniques.\r\nDiet: \r\n\"	Fiber supplementation may improve symptoms of constipation and diarrhea. Individualize the treatment because few patients experience exacerbated bloating and distention with high-fiber diets. Polycarbophil compounds (eg, Citrucel, FiberCon) may produce less flatulence than psyllium compounds (eg, Metamucil).\r\n\"	The data regarding the effectiveness of fiber are controversial because 40-70% of patients improve with placebo.\r\n\"	Judicious water intake in patients who predominantly experience constipation is recommended.\r\n\"	Caffeine avoidance may limit anxiety and symptom exacerbation.\r\n\"	Legume avoidance may decrease abdominal bloating.\r\n\"	Lactose and/or fructose should be limited or avoided in patients with these contributing disorders. Take care to supplement calcium in patients limiting lactose intake.\r\nActivity: No limitation is recommended.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. ANTICHOLENERGIC :\r\n\r\n- DICYCLOMINE\r\n- HYOSCYAMINE\r\n\r\n2. ANTIDIARRHOEAL :\r\n\r\n- DIPHENOXYLATE HYDROCHLORIDE\r\n- LOPERAMIDE\r\n\r\n3. TRICYCLIC ANTIDEPRESSANTS :\r\n\r\n- IMIPRAMINE\r\n- AMITRYPTYLINE\r\n\r\n4. PROKINETICS :\r\n\r\n- CISAPRIDE\r\n- TEGASEROD\r\n- ITOPRIDE\r\n- MOSAPRIDE\r\n\r\n5. SEROTONIN ( 5-HT3 ) RECEPTOR ANTAGONISTS : INHIBITS ACTIVATION OF NONSELECTIVE CATION CHANNELS, WHICH MODULATE THE ENTERIC NERVOUS SYSTEM.\r\n\r\n- ALOSETRON\r\n\r\n6. CHLORIDE CHANNEL ACTIVATOR : THESE AGENTS ENHANCE CHLORIDE-RICH INTESTINAL FLUID SECRETIONS WITHOUT ALTERING SOD & POT CONCENTRATION IN THE SERUM\r\n\r\n- LUBIPROSTONE\r\n\r\n7. BULK FORMING LAXATIVE :\r\n\r\n- METHYL CELLULOSE\r\n- PSYLLIUM', NULL, NULL, NULL, NULL, '1'),
('214', 'MALABSORPTION SYNDROME', '0', 'D.D. :\r\n1. INADEQUATE DIGESTION\r\n- POSTGASTRECTOMY\r\n- DEFICIENCY OR INACTIVATION OF PANCREATIC LIPASE\r\n- EXOCRINE PANCREATIC INSUFFICIENCY\r\n- CRO PANCREATITIS\r\n- PANCREATIC CARCINOMA\r\n- CYSTIC FIBROSIS\r\n- PANCREATIC INSUFFICIENCY- CONGENITAL OR ACQUIRED\r\n- GASTRINOMA - ACID INACTIVATION OF LIPASE\r\n- DRUGS LIKE ORLISTAT\r\n\r\n2. REDUCED INTRADUODENAL BILE ACID CONCENTRATION / IMPAIRED MICELLE FORMATION\r\n-* LIVER DISEASES\r\n- PARENCHYMAL LIVER DISEASE\r\n- CHOLESTATIC LIVER DISEASE\r\n* BACTERIAL OVERGROUTH IN SMALL INTESTINE\r\n- ANATOMIC STASIS LIKE\r\n AFFERENT LOOP STASIS, BLIND LOOP STASIS, STRICTURE , FISTULA\r\n- FUNCTIONAL STASIS LIKE \r\n DIABETES , SCLERODERMA, INTESTINAL PSEUDOOBSTRUCTION\r\n* INTERRUPTED INTEROHEPATIC CIRCULATION OF BILE SALTS\r\n- ILEAL RESECTION\r\n- CROHNS DISEASE\r\n* DRUGS WHICH BIND OR PRECIPITATE BILE SALTS LIKE NEOMYCIN, CHOLESTYRAMINE, CAL CARBONATE\r\n\r\n3. IMPAIRED MUCOSAL ABSORPTION / MUCOSAL LOSS OR DEFECT\r\n* INTESTINAL RESECTION OR BYPASS\r\n* INFLAMMATION, INFILTRATION OR INFECTION\r\n- CROHNS DISEASE\r\n- AMYLOIDOSIS\r\n- SCLERODERMA\r\n- LYMPHOMA\r\n- EOSINOPHILIC ENTERITIS\r\n- MASTOCYTOSIS\r\n- TROPICAL SPRUE\r\n- CELIAC DISEASE\r\n- COLLAGENOUS SPRUE\r\n- WIPPLES DISEASE\r\n- RADIATION ENTERITIS\r\n- FOLATE & VIT B12 DEFICIENCY\r\n- INFECTIONS LIKE SALMONELLA, GIARDIASIS\r\n- GRAFT VS HOST DISEASE\r\n* GENETIC DISEASES\r\n- DISACCHARIDASE DEFICIENCY\r\n- AGAMMAGLOBULINEMIA\r\n- ABETALIPOPROTEINEMIA\r\n- HARTNUP DISEASE\r\n- CYSTINURIA\r\n\r\n4. IMPAIRED NUTRIENT DELIVERY TO AND / OR FROM INTESTINE\r\n* LYMPHATIC OBSTRUCTION\r\n- LYMPHOMA\r\n- LYMPHANGIECTASIA\r\n* CIRCULATORY DISORDERS\r\n- CONGESTIVE HEART FAILURE\r\n- CONSTRICTIVE PERICARDITIS\r\n- MESENTERIC ARTRY ATHEROSCLEROSIS\r\n- VASCULITIS\r\n\r\n5. ENDOCRINE & METABOLIC DISORDERS\r\n- DIABETES\r\n- HYPOPARATHYROIDISM\r\n- ADRENAL INSUFFICIENCY\r\n- HYPERTHYROIDISM\r\n- CARCINOID SYNDROME', 'OTHER TESTS :\r\n* MICROSCOPIC HYPOCHROMIC ANEMIA DUE TO IRON DEFICIENCY OR MACROCYTIC ANEMIA DUE TO FOLIC ACID & VIT B12 DEFICIENCY\r\n* SERUM IRON, FOLATE & VIT B12 LEVELS - LOW\r\n* SERUM PROTEINS, ALBUMIN, ELECTROLYTES - MAY BE LOW\r\n* SERUM ANTIGLIADIN & ANTIENDOMYSIAL ANTIBODIES - POSITIVE IN CELIAC SPRUE\r\n* SERUM IGA - TO RULE OUT IGA DEFICIENCY\r\n* FECAL ELASTASE & CHYMOTRYPSIN ( 2 PROTEASES PRODUCED BY PANCREAS ) PRESENCE CAN DETERMINE BETWEEN PANCREATIC OR INTESTINAL CAUSE OF MALABSORPTION\r\n- STOOL FAT, SERUM ZINC & VIT A TESTS.\r\n* PROTHROMBIN TIME - ABNORMAL DUE TO VIT K MALABSORPTION\r\n- URINE TEST FOR URINARY 5-HIAA TEST.\r\n-  BREATH TESTS LIKE BREATH H-2 AFTER 50 GM LACTOSE, BREATH H-2 AFTER 10 GM LACTULOSE, BREATH CO2 AFTER ( 14C-XYLOSE) , (14 CO2) \r\n- TRIOLEIN ABSORPTION TEST\r\n- SECRETIN TEST\r\n- BENTIROMIDE TEST.', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: Two basic principles underlie the management of patients with malabsorption, (1) the correction of nutritional deficiencies and (2) when possible, the treatment of causative diseases. \r\n\"	Nutritional support\r\no	Supplementing various minerals, such as calcium, magnesium, iron, and vitamins, which may be deficient in malabsorption, is important. \r\no	Caloric and protein replacement also is essential.\r\no	Medium-chain triglycerides can be used as fat substitutes because they do not require micelle formation for absorption and their route of transport is portal rather than lymphatic.\r\no	In severe intestinal disease, such as massive resection and extensive regional enteritis, parenteral nutrition may become necessary.\r\n\"	Treatment of causative diseases\r\no	A gluten-free diet helps correct celiac disease. \r\no	Similarly, a lactose-free diet helps correct lactose intolerance; supplementing the first bite of milk-containing food products with Lactaid also helps. \r\no	Protease and lipase supplements are the treatment for pancreatic insufficiency. \r\no	Antibiotics are the treatment for bacterial overgrowth. \r\no	Corticosteroids and other anti-inflammatory agents help treat regional enteritis.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('243', 'OSTEOPOROSIS', '0', '* MALIGNANCIES - LYMPHOMAS, MULTIPLE MYELOMA, LEUKEMIA, METASTATIES.\r\n* HYPERPARATHYROIDISM\r\n* SENILE OSTEOPOROSIS\r\n* OSTEOMALACIA\r\n* SUBCLINICAL VIT D DEFICIENCY\r\n* PAGETS DISEASE\r\n* CUSHING SYNDROME\r\n* CHRONIC THYROTOXICOSIS\r\n* DRUGS LIKE \r\n- STEROID TREATMENT\r\n-  ANTACIDS HAVING ALUMINIUM\r\n-  HEPARIN AFTER LONG TERM USE\r\n-  ANTICONVULSANTS LIKE PHEYTOIN, BARBITURATES & CARBAMAZEPINE\r\n- CHEMOTHERAPEUTIC AGENTS\r\n* ALCOHOL\r\n* GONADAL DEFICIENCY\r\n* OSTEOGENESIS IMPERFECTA\r\n* CELIAC DISEASE\r\n* IDEOPATHIC HYPERCALCIURIA\r\n* RHEUMATOID ARTHRITIS\r\n* RENAL FAILURE\r\n* MASTOCYTOSIS\r\n* SMOKING\r\n* PROLONGED IMMOBILIZATION\r\n* CALCIUM & VIT D DEFICIENCY\r\n* BETA THALASSEMIA\r\n* IDIOPATHIC', 'OTHER TESTS : \r\n* DUAL ENERGY X-RAY ABSORBTIOMETRY ( DEXA ) - MOST ACCURATE FOR BONE MASS MEASUREMENT\r\n* QUANTITATIVE C.T. SCAN. \r\n* BONE RESORBTION INDICES LIKE URINARY OR SERUM FREE & TOTAL PYRIDINOLINES &  N-TELOPEPTIDE CROSS LINKS - INCREASED.\r\n* OSTEOCALCIN & C- TERMINAL PROCOLLAGEN PEPTIDES - INCREASED\r\n* SERUM VIT D ESTIMATION\r\n* URINE DEOXYPYRIDINOLINE ( DPD )\r\n* BONE DENSITOMETRY - T- SCORE BETWEEN -1 TO -2.5 (OSTEOPENIA)\r\n   IF T- SCORE < - 2.5 ( OSTEOPOROSIS )\r\n* 24 HR URINE CALCIUM & CREATININE', '0', '0', '0', '1', '0', 'DISEASE INFLUENCING FACTORS : DIET, LIFE STYLE, ENVIRONMENT, SMOKING, ALCOHOL, DRUG ABUSE & LACK OF EXERCISE', 'B', '0', 'Medical Care: Osteoporosis is largely asymptomatic until a fracture occurs. Taking steps to identify patients at risk and implementing preventive measures, such as changes in diet and activity levels, are important. \r\nPreventive measures should begin in childhood and adolescence, with adequate calcium intake and exercise. In patients who must take glucocorticoids for other medical conditions, some protective measures can be implemented. These include using the lowest dose possible, using inhaled (rather than oral) forms of glucocorticoids, instituting alternate-day dosing of steroids, and performing muscle-strengthening exercises. \r\nEffective medical therapy is available to help prevent and treat osteoporosis, including gonadal hormone replacement, calcitonin, selective estrogen-receptor modulators, and bisphosphonates. However, these agents reduce bone resorption with little, if any, effect on bone formation. Experimental evidence indicates that slow-release sodium fluoride and low-dose PTH are capable of increasing bone formation and thus preventing bone loss in women who are estrogen deficient. The former has also been used to decrease vertebral fracture rates. These are not yet approved for the treatment of osteoporosis. A newer medication approved by the US Food and Drug Administration (FDA) for the treatment of osteoporosis is an anabolic agent, recombinant human PTH (rhPTH) (1-34), which has been shown to stimulate the formation of new bone. The newest medication to receive FDA approval is ibandronate, a once daily oral bisphosphonate. \r\nSurgical Care: The goals of surgical treatment of fractures are rapid mobilization and return to normal function and activities. \r\nDiet: \r\n\"	Adequate calcium and vitamin D intake are important for persons of any age, particularly in childhood as the bones are maturing. If dietary intake is inadequate, add supplements.\r\n\"	For women who are postmenopausal, men who are older than 50 years, and other persons at risk for osteoporosis, the recommendation is 1500 mg of calcium daily.\r\n\"	For women who are premenopausal and men who are younger than 50 years without osteoporosis risk factors, the recommendation is 1000 mg/d.\r\n\"	Vitamin D intake should be 400-800 IU/d.\r\nActivity: \r\n\"	Weight-bearing exercise has been shown to have a positive effect on BMD, although the exact mechanism is not known. Regular exercise should be encouraged in all patients, including children and adolescents in order to strengthen the skeleton during the maturation process.\r\n\"	Exercise also improves agility and balance, thereby reducing the risk of falls.\r\n\"	Encourage patients to be as active as possible.\r\n\"	Physical therapists can assist in developing exercise regimens, instructing patients in proper techniques, and monitoring progress and consistency.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('264', 'PHEOCHROMOCYTOMA', '0', 'CAUSES\r\n. Catecholamine-producing tumor - \"Rule of 10\" :\r\n. 10% are extra-adrenal\r\n. 10% are multiple or bilateral\r\n. 10% are malignant\r\n. 10% recur after surgical removal\r\n. 10% occur in children\r\n. .10% are familial\r\n. 10% present as adrenal incidentalomas\r\n\r\n--------------------------------------------------------------------------\r\nD.D. :\r\n\r\n* HYPERADRENERGIC ESSENTIAL HYPERTENSION\r\n* AUTONOMIC DYSFUNCTION ( POSTSPINAL CORD INJURY, GUILLAIN-BARRHYPOTHALAMIC DYSFUNCTION )\r\n* CARCINOID\r\n* MENOPAUSAL SYNDROME\r\n* PANIC ATTACKS\r\n* THYROTOXICOSIS\r\n* ALCOHOL WITHDRAWAL\r\n* ABRUPT DRUG WITHDRAWAL; CLONIDINE OR PROPANOLOL\r\n* USE OF COCAINE , MAO INHIBITORS, AMPHETAMINES, SYMPATHOMIMETIC DRUGS\r\n* MIGRAIN OR CLUSTER HEADACHE\r\n* HYPOGLYCEMIA\r\n* PAROXYSMAL TACHYCARDIA\r\n* AC MYOCARDIAL INFARCTION OR ANGINA PECTORIS\r\n* BRAIN TUMOR OR SUBARACHNOID HAEMORRHAGE\r\n* AORTIC DISSECTION\r\n* CARDIOVASCULAR DECONDITIONING\r\n* NEUROBLASTOMA IN A CHILD\r\n* TOXEMIA OF PREGNANCY\r\n* DIENCEPHALIC OR AUTONOMIC EPILEPSY', 'OTHER TESTS : \r\n* 24 HRS URINARY VMA - INCREASED BUT LESS SENSITIVE & SPECIFIC\r\n* 24 HRS URINARY EPINEPHRINE - INCREASED\r\n* 24 HRS URINARY METANEPHRINES - INCREASED\r\n* 24 HRS URINARY FREE CATECHOLAMINES - INCREASED ( FALSE POSITIVE INCREASE IN METHYLDOPA, LEVODOPA, LABETALOL, SYMPATHOMIMETIC AMINES WHICH MAY ELEVATE CATECHOLAMINE EXCRETION UPTO 2 WKS. OTHER CAUSES ARE HYPOGLYCEMIA, STRENUOUS EXERCISE, CNS DISEASE WITH RAISED INTRA CRANIAL PRESSURE, SEVERE HYPOXIA, CLONIDINE WITHDRAWAL.\r\n* PLASMA CATECHOLAMINES - INCREASED WITH DECREASED RESPONSE TO CLONIDINE & GANGLION BLOCKERS\r\n* PHENTOLAMINE TEST - 5 MG BOLUS CAUSES FALL OF 35/25 MM OF B.P.\r\n* GLUCAGON PROVOCATIVE TEST - RISE IN B.P. & CATECHOLAMINE LEVELS\r\n* CAPTOPRIL CHALLANGE TEST - NORMAL\r\n* CLONIDINE SUPPRESSION TEST - FAILURE TO SUPPRESS NOREPINEPHRINE AFTER CLONIDINE ADMINISTRATION IS HIGHLY PREDICTIVE OF PHEOCHROMOCYTOMA\r\n* METAIODOBENZYLGUANIDINE SCAN FOR LOCALISING PHEOCHROMOCYTOMA\r\n* VENA CAVAL SAMPLING FOR CATECHOLAMINES - RARELY INDICATED, OCCASIONALLY USED WHEN TUMOR CAN NOT BE LOCATED WITH OTHER METHODS.\r\n* PLASMA-FREE METANEPHRINES OR URINARY FRACTIONATED METANEPHRINES ( NORMETANEPHRINE & METANEPHRINE ) HAVE THE GREATEST TEST SENSITIVITY & ARE ADEQUATE FOR RULING OUT PHEOCHROMOCYTOMA.\r\n* 123I-METAIODOBENZYLGUANIDINE ( MIBG ) SCAN - IT USES A RADIOISOTOPE THAT LOCALIZES TO ADRENERGIC TISSUE : USEFUL IN LOCALIZING EXTRAADRENAL OR OTHER DIFFICULT TO FIND PHEOCHROMOCYTOMAS\r\n* ARTERIOGRAPHY - RARELY INDICATED NOW\r\n* SELECTIVE ADRENAL VENOUS SAMPLING - RARELY REQUIRED & SHOULD BE RESERVED FOR CENTERS WITH EXPERTISE.\r\nIMAGING\r\n• Computerized abdominal imaging (MRI preferred over CT)\r\n• I-123: I-metaiodobenzylguanidine scan\r\n• In-111: pentetreotide scan', '1', '0', '0', '0', '1', 'APPROXIMATELY 10% ARE INHERITED & ARE FREQUENTLY ASSOCIATED WITH FAMILIAL SYNDROMES.RISK FACTORS: Multiple endocrine neoplasia types II A and B\r\n• Neurofibromatosis, type 1, Von Hippel-Lindau syndrome, Familial paraganglioma', 'B', '0', 'SURGICAL resection of the tumor is the treatment of choice and usually results in cure of the hypertension. Careful treatment with alpha- and beta-blockers is required preoperatively to control blood pressure and prevent intraoperative hypertensive crises.\r\n\r\nStart alpha blockade with phenoxybenzamine 7-10 days preoperatively to allow for expansion of blood volume. \r\n\r\nThe patient should undergo volume expansion with isotonic sodium chloride solution. Encourage liberal salt intake. \r\n\r\nInitiate a beta-blocker only after adequate alpha blockade. If beta blockade is started prematurely, unopposed alpha stimulation could precipitate a hypertensive crisis. \r\n\r\nAdminister the last doses of oral alpha- and beta-blockers on the morning of surgery. \r\n\r\nSurgical Care\r\nBoth an experienced anesthesiologist and an experienced surgeon are crucial to the success of the operation. Surgical mortality rates are less than 2-3% with an experienced anesthesiologist and surgeon.\r\n\r\nUse an arterial line, cardiac monitor, and Swan-Ganz catheter. Administer stress-dose steroids if bilateral resection is planned. \r\n\r\nAn anterior midline abdominal approach was used in the past; however, in current practice, laparoscopic adrenalectomy is the preferred procedure for lesions smaller than 8 cm. If the pheochromocytoma is intra-adrenal, remove the entire adrenal gland. In the case of a malignant pheochromocytoma, resect as much of the tumor as possible. \r\n\r\nPREGNANCY CONSIDERATIONS : VAGINAL DELIVERY IS EXTREMELY DANGEROUS.\r\n\r\nMAGNESIUM SULPHATE MAY BE USED TO CONTROL HYPERTENSIVE EMERGENCIES DURING LABOR & DURING OPERATION OF THE TUMOR IN A PREGNANT PATIENT.\r\n\r\n- 1 ST & 2 ND TRIMESTER : TUMOR SHOULD BE EXCISED AS SOON AS PATIENT HAS BEEN ADEQUATELY PRETREATED WITH ALPHA BLOCKERS\r\n\r\n- 3 RD TRIMESTER : PT SHOULD BE TREATED WITH ALPHA BLOCKERS UNTIL THE FETUS IS VIABLE , AT WHICH TIME BABY SHOULD BE DELIVERED BY CESAREAN SECTION. THE TUMOR MAY BE RESECTED IN THE SAME OPERATION. \r\n\r\nDRUG TREATMENT :\r\n\r\n- * PT CAN BE HYPOVOLEMIC, SODIUM INTAKE MUST BE ADEQUATE TO PREVENT PROFOUND POSTURAL HYPOTENSION, SO GIVE NORMAL SALINE INFUSION.\r\n\r\n- *  BETA BLOCKERS SHOULD BE GIVEN ONLY AFTER PRIOR ADEQUATE ALPHA BLOCKERS TO AVOID HYPERTENSIVE CRISIS. \r\n\r\n1. PHENOXYBENZAMINE\r\n\r\n2. PRAZOSIN, TERAZOSIN & DOXAAZOSIN ( SPECIFIC ALPHA-1 ADRENERGIC BLOCKER )\r\n\r\n3. LABETALOL ( ALPHA & BETA ANTAGONIST )\r\n\r\n4. METYROSINE ( COMPETITIVE INHIBITOR OF TYROSINE HYDROXYLASE, THE RATE LIMITING STEP IN CATECHOLAMINE BIOSYNTHESIS )\r\n\r\n5. CALCIUM CHANNEL BLOCKERS\r\n\r\n6. VARIOUS CHEMOTHERAPEUTIC COMBINATIONS WITH OR WITHOUT RADIATION THERAPY TO TREAT MALIGNANT PHEOCHROMOCYTOMA. ( AFTER AGGRESSIVE SURGICAL RESECTION ).\r\n\r\nALTERNATIVE DRUGS:\r\n• Alpha-adrenergic blocking agents - prazosin (Minipress), terazosin (Hytrin), doxazosin (Cardura)\r\n• Beta-adrenergic blocking agents - nadolol (Corgard), atenolol (Tenormin), metoprolol (Lopressor)\r\n• Combined beta- and alpha-adrenergic blocker - labetalol (Normodyne, TranDate)\r\n• Catecholamine synthesis inhibitor - metyrosine (Demser)\r\n\r\nPATIENT MONITORING\r\n• Daily blood pressure monitoring prior to surgery\r\n• Intra-operative hemodynamic monitoring\r\n• Two weeks postoperatively - 24-h urine for measurement of catecholamines and metanephrines; if normal,\r\nre-check annually, indefinitely\r\n\r\nPOSSIBLE COMPLICATIONS\r\n• Postural hypotension with alpha-adrenergic blockade\r\n• Pulmonary edema with beta-adrenergic blockade\r\n• Intra-operative hypertensive crisis\r\n\r\nEXPECTED COURSE/PROGNOSIS\r\n• The survival rate after removal of a benign pheochromocytoma is nearly that of age- and sex-matched\r\ncontrols\r\n• For malignant pheochromocytoma, the 5-year survival rate is less than 50%\r\n\r\n\r\nFirst and second trimester - surgical resection. Third trimester - cesarean section and removal of the\r\npheochromocytoma in the same operation\r\n', NULL, NULL, NULL, NULL, '1'),
('274', 'PNEUMONIA', '0', 'CAUSATIVE ORGANISMS:\r\n\r\n1. COMMUNITY ACQUIRED\r\n\r\n- MYCOPLASMA PNEUMONIA\r\n- STREPTOCOCCAL PNEUMONIA\r\n- HAEMOPHILUS INFLUENZAE\r\n- CHLAMYDIA PNEUMONIAE\r\n- LEGIONELLA PNEUMOPHILA\r\n- ORAL ANAEROBES\r\n- MORAXELLA CATARRHALIS\r\n- STAPHYLOCOCCUS AUREUS\r\n- NOCARDIA SAPPROPHYTES\r\n- VIRUSES\r\n- FUNGI\r\n- MYCOBACTERIUM TUBERCULOSIS\r\n- CHLAMYDIA PSITTACI\r\n\r\n2. HOSPITAL ACQUIRED\r\n\r\n- ENTERIC AEROBIC GRAM NEGATIVE BACILLI\r\n- PSEUDOMONAS AERUGINOSA\r\n- S. AUREUS\r\n- ORAL ANAEROBES\r\n\r\n3. HIV INFECTION ASSOCIATED\r\n\r\n- PNEUMOCYSTIS CARINII\r\n- M. TUBERCULOSIS\r\n- S. PNEUMONIAE\r\n- H. INFLUENZAE', 'LABORATORY\r\n• CBC - leukocytosis with an immature shift on differential; ESR, CRP\r\n• Chem - hyponatremia (SIADH)\r\n• ABG - hypoxemia\r\n• ABG - hypocapnia initially, then hypercapnia\r\n• Blood culture - positive in 10-20% of adult patients and 7% of pediatric patients with community-acquired pneumonia (partially because many have been pre-treated with antibiotics), 8-20% nosocomial pneumonia\r\nSPECIAL TESTS\r\n• Decubitus CXR to investigate for empyema or parapneumonic effusion\r\n• Gram stain and culture of pleural fluid\r\n• pH of pleural fluid (iced, airless sample sent to blood gas laboratory)\r\n• Urine legionella antigen (in ICU/severe cases)\r\n• Tuberculin skin test (PPD) - for hilar adenopathy or upper lobe involvement\r\nIMAGING\r\n. CXR (with lateral decubitus views if pleural effusion present)\r\n. Lobar or segmental consolidation (air bronchogram)\r\n. Bronchopneumonia\r\n. Interstitial infi ltrate\r\n. Pleural effusion (free-flowing or loculated)\r\n. Ultrasound recommended to check for location and presence of loculations before thoracentesis\r\nDIAGNOSTIC PROCEDURES\r\n. Gram stain and culture of sputum (induced, if necessary)\r\n. Nasotracheal suctioning for culture\r\n. Transtracheal aspirate for culture\r\n. Bronchoscopy with bronchoalveolar lavage or protected telescoping catheter brushing for culture\r\n. Thoracentesis for pleural fl uid studies\r\n. Blood culture, especially if hospitalized - prior to antibiotics', '0', '0', '1', '0', '0', 'RISK FACTORS:Tobacco smoking, Recent/concurrent viral infections, Hospitalization to include mechanical ventilation, antecedent antibiotics, NG tubes, Age extremes, Alcoholism, AIDS or other immunosuppression, Renal failure, Cardiovascular disease', 'B', '0', 'RISK FACTORS\r\n• Tobacco smoking\r\n• Recent/concurrent viral infections\r\n• Hospitalization to include mechanical ventilation, antecedent antibiotics, NG tubes\r\n• Age extremes\r\n• Alcoholism\r\n• AIDS or other immunosuppression\r\n• Renal failure\r\n• Cardiovascular disease\r\n• Functional asplenia\r\n• Chronic obstructive pulmonary disease\r\n• Diabetes mellitus\r\n• Malnutrition\r\n• Malignancy\r\n• Altered level of consciousness or gag (e.g., seizures, stroke, neuromuscular disease, etc.)\r\n• Occupational exposure\r\n• Poorly implemented infection control practices (poor handwashing)\r\n• Postoperative atelectasis\r\n\r\nMedical Care: The initial approach to treating patients with \r\nCAP involves a determination of 3 factors. (1) Should the patient with pneumonia be treated in the hospital or as an outpatient? (2) Does the patient have a serious coexisting illness or is the patient elderly? (3) How severely ill is the patient at the time of the initial evaluation? \r\nOnce these assessments have been made, initial antimicrobial therapy can be selected based on to the recommendations given in Tables 1-7. The choices cover the most common pathogens for a given clinical setting. Evaluating the response to therapy is important. Patients who are not improving with initial empirical antibiotic therapy should be identified and re-examined. \r\n\"	Risk stratification of CAP \r\no	Patients with CAP can be categorized into 1 of 4 groups based on information collected at the time of the initial evaluation. \r\no	The risk factors for stratification include the need for hospitalization, the severity of illness, the presence of coexisting disease, and the patient\'s age. \r\no	Penicillin (penicillin G/amoxicillin) remains the drug of choice for strains that are fully sensitive or have a moderately decreased susceptibility to penicillin, whereas cefotaxime and ceftriaxone are the first-line alternatives in cases with higher levels of resistance. \r\no	The 4 major categories not only speculate the microbial etiology but also predict ultimate prognosis and outcome. These categories are (1) CAP occurring in patients aged 60 years or younger who have no evidence of comorbidity and who can be treated in an outpatient setting, (2) CAP occurring in patients with evidence of comorbidity and/or who are aged 60 years or older who can be treated in an outpatient setting, (3) CAP requiring hospitalization but not admission to an ICU, and (4) severe CAP requiring ICU care.\r\n\"	Nosocomial pneumonia \r\no	Nosocomial pneumonia remains a prevalent hospital-acquired infection. The gaps in knowledge and controversies regarding diagnosis, treatment, and prevention of nosocomial pneumonia continue. The initial empiric therapy of nosocomial pneumonia in immunocompetent patients is directed at the core organisms. In immunocompromised hosts, the additional bacteria are targeted and therapy is modified based on the results of microbiologic investigations. \r\no	Modifications to the empirical antibiotic therapy may be necessary after assessment of 3 factors; these are (1) the severity illness in the patient, (2) the presence of any conditions that can lead to infection with specific pathogens, and (3) the length of time the patient has been hospitalized before the development of nosocomial pneumonia. \r\no	Following these determinations, patients are categorized into 1 of 3 groups because a different microbiologic spectrum is suggested in each group. These groups are (1) patients without unusual risk factors who present with mild-to-moderate nosocomial pneumonia any time during hospitalization or present with severe nosocomial pneumonia at early onset, (2) patients with risk factors who present with mild-to-moderate nosocomial pneumonia occurring any time during hospitalization, and (3) patients with severe nosocomial pneumonia either of early onset with specific risk factors or of late onset without risk factors. \r\no	Patients belonging to risk group 1 usually are infected with E coli or S aureus; Klebsiella, Proteus, Serratia, or Haemophilus, species; or streptococci. Patients in risk group 2 have infection with the previous organisms, but anaerobes, S aureus, Legionella species, and P aeruginosa also may be present. In risk group 3, the core organisms are present and P aeruginosa, Acinetobacter species, and methicillin-resistant S aureus are the additional possibilities.\r\n\"	Definition of severe hospital-acquired pneumonia\r\no	Admission to the ICU is indicated. \r\no	Respiratory failure is defined as the need for mechanical ventilation or the requirement for fraction of inspired oxygen to be greater than 35% in order to maintain oxygen desaturation of greater than 90%. \r\no	Rapid radiographic progression, multilobar pneumonia, or cavitation of a lung infiltrate is present. \r\no	Evidence of severe sepsis with hypotension and/or an organ dysfunction is present. \r\no	Shock state is present, as indicated by a systolic blood pressure of less than 90 mm Hg or a diastolic blood pressure of less than 60 mm Hg. \r\no	Vasopressors are required for more than 4 hours. \r\no	Urine output is less than 20 mL/h, or total urine output is less than 80 mL in 4 hours. \r\no	Acute renal failure is present that requires dialysis.\r\n\"	Empiric therapy for community-acquired bacterial pneumonia - Based on recommendations by the American Thoracic Society (1993) and consensus guidelines by the Canadian Infectious Disease Society/Canadian Thoracic Society (2000) \r\nTable 1. Outpatient Pneumonia Without Comorbidity in Patients Aged 60 Years or Younger* \r\n\r\nOrganisms †\r\nS pneumoniae\r\nM pneumoniae\r\nC pneumoniae\r\nH influenzae\r\nMiscellaneous\r\nLegionella species, S aureus, \r\naerobic gram-negative bacilli\r\n\r\nTherapy\r\n1st choice - Macrolide ‡\r\n2nd choice - Doxycycline\r\n\r\n*Excludes patients at risk for HIV\r\n† In roughly one third to one half of the cases, no etiology was identified. \r\n‡ Erythromycin, clarithromycin, or azithromycin\r\nTable 2. Outpatient Bacterial Pneumonia With Comorbidity in Patients Aged 60 Years or Older* \r\n\r\nOrganisms †\r\nS pneumoniae\r\nH influenzae\r\nAerobic gram-negative bacilli\r\nS aureus\r\nMiscellaneous\r\nM catarrhalis, Legionella species, Mycoplasma \r\n\r\nTherapy\r\nCOPD (no recent antibiotics or oral steroids within past 3 mo)\r\n1st choice - Newer macrolides\r\n2nd choice - Doxycycline\r\n\r\nCOPD (recent antibiotics or oral steroids in past 3 mo)\r\n1st choice - Respiratory fluoroquinolone*\r\n2nd choice - Amoxicillin/clavulanate + macrolide or second-generation cephalosporin + macrolide\r\n\r\nSuspected microaspiration - Oral anaerobes\r\n1st choice -Amoxicillin/clavulanate and/or macrolide or fourth-generation fluoroquinolone (eg, moxifloxacin)\r\n2nd choice - Third-generation fluoroquinolone (eg, levofloxacin plus clindamycin or metronidazole\r\n*Excludes patients at risk for HIV\r\n† In roughly one third to one half of the cases, no etiology was identified.\r\nTable 3. Hospitalized Patients With Community-Acquired Bacterial Pneumonia (admission to medical ward)* \r\nOrganisms †\r\nS pneumoniae\r\nH influenzae\r\nPolymicrobial (including aerobic bacteria)\r\nAerobic gram-negative bacilli\r\nLegionella species\r\nS aureus\r\nC pneumoniae\r\nMiscellaneous\r\nM pneumoniae, M catarrhalis\r\n\r\nTherapy\r\n1st choice - Respiratory fluoroquinolone\r\n2nd choice - Second-generation or third-generation cephalosporin + macrolide\r\n*Excludes patients at risk for HIV\r\n† In roughly one third to one half of the cases, no etiology was identified. \r\nTable 4. Severe Hospitalized Patients With Community-Acquired Bacterial Pneumonia (admission to ICU)* \r\nOrganisms †\r\nS pneumoniae\r\nLegionella species\r\nAerobic gram-negative bacilli\r\nM pneumoniae\r\nMiscellaneous\r\nH influenzae \r\n\r\nTherapy\r\n1st choice - Antipseudomonal fluoroquinolone (eg, ciprofloxacin)\r\nplus antipseudomonal beta-lactam (eg, ceftazidime, piperacillin-\r\ntazobactam, carbapenem) or aminoglycoside (eg, gentamicin, \r\ntobramycin, amikacin)\r\n2nd choice - Triple therapy with antipseudomonal beta-lactam plus\r\naminoglycoside plus macrolide\r\n*Excludes patients at risk for HIV\r\n† In roughly one third to one half of the cases, no etiology was identified. \r\nTable 5. Patients With Mild-to-Moderate Hospital-Acquired Bacterial Pneumonia, No Unusual Risk Factors, and Onset at Any Time; or, Patients With Severe Hospital-Acquired Pneumonia With Early Onset* \r\nCore Organisms	Core Antibiotics\r\nEnteric gram-negative bacilli	Cephalosporin\r\n(Nonpseudomonal) Enterobacter species, E coli	Second-generation or nonpseudomonal third-generation\r\nKlebsiella species	Beta-lactam/beta-lactamase\r\ninhibitor combination\r\nProteus species\r\nS marcescens	If allergic to penicillin, fluoroquinolone or clindamycin + aztreonam\r\nH influenzae	\r\nMethicillin-sensitive S aureus\r\nS pneumoniae	\r\n\r\n\r\n*Excludes patients with immunosuppression\r\nTable 6. Patients With Mild-to-Moderate Hospital-Acquired Bacterial Pneumonia With Risk Factors, Onset at Any Time* \r\nCore Organisms, Plus the Following:	Core Antibiotics, Plus the Following:\r\nAnaerobes\r\n(recent abdominal surgery, witnessed aspiration)	Clindamycin or beta-lactam/beta-lactamase inhibitor (alone)\r\nS aureus (coma, head trauma, diabetes mellitus, renal failure)	+/-vancomycin (until methicillin-resistant S aureus is excluded)\r\nLegionella\r\n(high-dose steroids)	Erythromycin +/- rifampin\r\nP aeruginosa\r\n(prolonged ICU stay, steroids, antibiotics, structural lung disease	Treat as severe hospital-acquired pneumonia (see Table 7)\r\n*Excludes patients with immunosuppression\r\nTable 7. Patients With Severe Hospital-Acquired Bacterial Pneumonia With Risk Factors and Early Onset or Patients With Severe Hospital-Acquired Pneumonia and Late Onset* \r\nCore Organisms, Plus the Following	Therapy\r\nP aeruginosa\r\nAcinetobacter species\r\nConsider methicillin-resistant S aureus	Aminoglycoside or ciprofloxacin plus one of the following:\r\nAntipseudomonal penicillin\r\nBeta-lactam/beta-lactamase \r\ninhibitor\r\nCeftazidime or cefoperazone \r\nImipenem\r\n+/-vancomycin\r\n*Excludes patients with immunosuppression\r\n\"	To determine the impact of initial antimicrobial choice on 30-day mortality rate in patients with CAP due to S pneumoniae, a prospective, observational study was performed. The factors related to mortality were bilateral disease, suspected aspiration, shock, HIV infection, renal failure, and pneumonia severity index (PSI) score class IV versus class I-III and categories V versus categories I-III. The association of beta-lactams plus macrolides was not better than the use of beta-lactams alone. The benefit of adequate initial antimicrobial regimen and 30-day mortality in patients with community-acquired pneumococcal pneumonia was demonstrated for those with a higher PSI score.\r\n\r\nPATIENT MONITORING\r\n. If outpatient therapy, daily assessment of the patients progress, and reassessment of therapy if clinical\r\nworsening or no improvement in 48-72 hours\r\n. CXR take time to clear and may not show clearing, even though patient is improving. Repeat study about\r\n6 weeks after recovery to verify the pneumonia was not caused by an obstructing endobronchial lesion in\r\nselected patients (smokers and older patients).\r\n. Repeating the cultures after treatment has been started is unnecessary unless there has been treatment failure or if treating TB\r\n\r\nPREVENTION/AVOIDANCE\r\n. Reduce risk factors where possible (quit smoking)\r\n. Bedridden and postoperative patients - deep breathing and coughing exercises; prevent aspiration during\r\nnasogastric tube feedings\r\n. Avoid indiscriminate use of antibiotics during minor viral infections\r\n. Annual infl uenza vaccine for high risk individuals\r\n. Polyvalent pneumococcal vaccine\r\n\r\nPOSSIBLE COMPLICATIONS\r\n. Empyema\r\n. Pulmonary abscess\r\n. Superinfections\r\n. Multiple organ dysfunction syndrome (MODS)\r\n. Adult respiratory distress syndrome (ARDS)\r\n. Post-pneumonic atelectasis may occur in 5-10% of children\r\n\r\nEXPECTED COURSE/PROGNOSIS\r\n. Usual course - acute. In otherwise healthy individual, improvement seen and fever resolved in 1-3 days;\r\nsometimes up to 1 week\r\n. Overall attributable mortality is about 5% in community acquired; (.15% if hospitalized and < 1% if not hospitalized) 25-50% in nosocomial\r\n. Poorest prognosis - age extremes, positive blood cultures, low WBC, presence of associated disease,\r\nimmunosuppression respiratory failure, inappropriate antecedent antibiotics, delayed treatment >8 hours\r\n', NULL, NULL, NULL, NULL, '1'),
('282', 'PORPHYRIA', '0', 'AN AUTOSOMAL DOMINANT DISEASE\r\n\r\nCAUSES\r\n. Genetic enzyme deficiencies\r\n. PCT - uroporphyrinogen decarboxylase\r\n. AIP - porphobilinogen deaminase\r\n. PP - ferrochelatase\r\n. VP - protoporphyrinogen oxidase\r\n. HCP - coproporphyrinogen oxidase\r\n. PBD - porphobilinogen synthetase\r\n. CEP - uroporphyrinogen III synthetase (cosynthetase)\r\n. Acquired PCT causes:\r\n. Hepatitis C virus - strong association\r\n. Heavy alcohol use\r\n. Decreased enzyme associated with steroids and hormones\r\n. Specific exposure to poly-halogenated hydrocarbons (e.g., hexachlorobenzene)\r\n. Lead poisoning may alter pathways\r\n. HIV\r\n. Ascorbic acid deficiency?\r\n\r\n\r\n--------------------------------------------------------------------------\r\nDIFFERENTIAL DIAGNOSIS\r\n• Vast and protean\r\n• Pseudoporphyria - rare syndrome, indistinguishable from PCT, due to some NSAIDs (eg, nabumetone and naproxen) and fl utamide', 'OTHER TESTS :\r\n* SERUM & URINARY AMINOLEVULINIC ACID ( ALA ) & PORPHOBILINOGEN ( PBG ) LEVELS - INCREASED DURING ATTACKS\r\n* PORPHYRINES ARE INCREASED IN URINE , STOOL, LIVER & PLASMA\r\n• Urine for porphyrins during acute attack. Urine may be normal at other times.\r\n• Individual enzyme activity in erythrocytes or other body cells/tissues\r\n• Stool for porphyrins in PP, VP, HCP, CEP\r\n• Bile for porphyrin in VP\r\n• Plasma for fl uorescence emission spectroscopy in VP\r\n• Saliva for porphyria in PCT\r\n• Erythrocyte uroporphyrin in CEP\r\n• PP exception - urine unremarkable. Test erythrocyte protoporphyrin.\r\n• Ferritin typically elevated in PCT due to increased iron stores\r\nSPECIAL TESTS Genetic studies when applicable', '1', '1', '0', '0', '1', 'MEASUREMENT OF HMB-SYNTHASE IN RBC, OR BETTER, THE DETECTION OF THE FAMILYS HMB-SYNTHASE MUTATION, WILL DIAGNOSE ASYMPTOMATIC FAMILY MEMBERS. THE PRENATAL DIAGNOSIS OF A FETUS AT RISK CAN BE MADE WITH CULTURED AMNIOTIC CELLS OR CHORIONIC VILLI.', 'B', '0', 'ENVIRONMENTAL TRIGGERS, INFECTION, SURGERY & LOW CALORIC DIET ARE IIMPORTANT IN MANY ATTACKS OF PORPHYRIA. GENETIC CARRIERS WHO AVOID THESE MAY NEVER EXPERIENCE SYMPTOMS.\r\n\r\nRISK FACTORS\r\n• Multiple precipitating factors, especially AIP, VP, HCP\r\n• Drugs (e.g., barbiturates and sulfas in AIP)\r\n• Estrogens, especially oral contraceptives\r\n• Steroids\r\n• Liver disease\r\n• Menstrual cycles\r\n• Infection\r\n• Fasting\r\n• Heavy alcohol use\r\n• Hexachlorobenzene exposure\r\n\r\nMEDICAL TREATMENT :\r\n\r\nMedical Care: \r\n\r\nThe treatment goal for acute attacks of porphyria is to decrease heme synthesis and reduce the production of porphyrin precursors.\r\nHigh doses of glucose (400 g/d) can inhibit heme synthesis and are useful for treatment of mild attacks.\r\nPeople experiencing severe attacks, especially those with severe neurologic symptoms, should be treated with hematin in a dose of 4 mg/kg/d for 4 days.\r\nPain control is best achieved with narcotics. Laxatives and stool softeners should be administered with the narcotics to avert exacerbating existing constipation.\r\nTreat seizures with Neurontin. Most classic antiseizure medicines can lead to acute porphyria attacks.\r\nDiet: \r\n\r\nThe patient should receive a high-carbohydrate diet during the attack. If the patient is unable to eat, intravenous glucose should be administered.\r\nBetween attacks, eating a balanced diet is more important than eating one rich in glucose.\r\n\r\nDRUG TT : I.V. HEME IS MORE EFFECTIVE THAN I.V. GLUCOSE & RESPONSE TO HEME THERAPY IS REDUCED IF DELAYED. 3 - 4 MG OF HEME, IN THE FORM OF HEMATIN, HEME ALBUMIN, HEME ARGINATE MAY BE INFUSED DAILY FOR 4 DAYS\r\n\r\nALTERNATIVE DRUGS\r\n. PCT\r\n. chloroquine 125 mg twice weekly, or hydroxychloroquine 250 mg tid, in conjunction with phlebotomy\r\n. With hepatitis C virus - interferon beneficial for both\r\n. thalidomide being studied\r\n. CEP and PP. In vitro gene therapy has been successful\r\n. AIP\r\n. LHRH analogues being studied\r\n. antioxidants ineffective\r\n. Menstruating women - hematin premenstrual; cycle suppressors, e.g., luteinizing hormone releasing hormone (LHRH) analogues\r\n. Autonomic manifestations - beta blockers\r\n. Other symptoms - treat symptomatically\r\n\r\nPATIENT MONITORING Individualized\r\n\r\nPREVENTION/AVOIDANCE\r\n. Avoid precipitating drugs\r\n. Alcohol\r\n. Barbiturates\r\n. Carbamazepine\r\n. Chlorpropamide\r\n. Danazol\r\n. Ergots\r\n. Estrogens and progestins\r\n. Ethchlorvynol\r\n. Glutethimide\r\n. Griseofulvin\r\n. Mephenytoin\r\n. Meprobamate\r\n. Methotrexate\r\n. Methyprylon\r\n. Metoclopramide\r\n. Phenytoin\r\n. Pyrazolones\r\n. Succinimides\r\n. Sulfonamide antibiotics\r\n. Valproic acid\r\n. Eat an adequate diet with high carbohydrate intake\r\n\r\nPOSSIBLE COMPLICATIONS\r\n. Neurologic:\r\n. Essentially anything\r\n. Includes sensory and motor systems\r\n. Includes autonomic nervous system\r\n. May include seizures\r\n. May lead to quadriplegia and/or respiratory paralysis with death\r\n. Psychiatric:\r\n. Essentially anything\r\n. Psychosis most common\r\n. Visual hallucinations common\r\n. Disorientation frequent\r\n. Chronic depression frequent\r\n. Dermatologic:\r\n. Photosensitivity\r\n. Scrapes, ulcerations, blisters with minimal trauma\r\n. Hyperpigmentation, especially hands and face\r\n. Scarring frequent\r\n. Facial hypertrichosis\r\n. CEP - mutilating, with hemolysis, erythrodontia, splenomegaly\r\n. PP - occasional hepatic disease, including hepatic failure\r\n\r\nEXPECTED COURSE/PROGNOSIS\r\n. In all porphyrias:\r\n. Patients who are asymptomatic or minimally symptomatic\r\n- unaffected longevity\r\n. Patients who are more symptomatic - treatable and do well\r\n. Neurologic complications (e.g., peripheral neuropathy, neurosis or hemiplegia), at times permanent\r\n. In AIP\r\n. Acute attacks have 25% mortality\r\n. Increased risk of hepatocellular carcinoma\r\n. Acquired PCT\r\n. HIV\r\n. Hepatitis C virus\r\n. Hepatic malignancies', NULL, NULL, NULL, NULL, '1'),
('315', 'RENAL FAILURE,CHRONIC', '0', 'CAUSES :\r\n\r\n1 - VASCULAR DISEASES :\r\n\r\n- RENAL ARTRY STENOSIS\r\n- VASCULITIDES\r\n- ATHEROEMBOLI\r\n- HYPERTENSIVE NEPHROSCLEROSIS\r\n- RENAL VEIN THROMBOSIS\r\n\r\n2 - PRIMARY GLOMERULAR DISEASE :\r\n\r\n- MEMBRANOUS NEPHROPATHY\r\n- IMMUNOGLOBULIN A NEPHROPATHY\r\n- FOCAL & SEGMENTAL GLOMERULOSCLEROSIS\r\n- MINIMAL CHANGE DISEASE\r\n- MEMBRANOPROLIFERATIVE GLOMERULONEPHRITIS\r\n- RAPIDLY PROGRESSIVE GLOMERULONEPHRITIS\r\n\r\n3 - SECONDARY GLOMERULAR DISEASE :\r\n\r\n- DIABETES MELLITUS\r\n- SLE\r\n- RHEUMATOID ARTHRITIS\r\n- MIXED CONNECTIVE TISSUE DISEASE\r\n- SCLERODERMA\r\n- GOODPASTURE SYNDROME\r\n- WEGENER GRANULOMATOSIS\r\n- MIXED CRYOGLOBULINEMIA\r\n- POSTINFECTIOUS GLOMERULONEPHRITIS\r\n- ENDOCARDITIS\r\n- HEPATITIS B & C DISEASE\r\n- SYPHILIS\r\n- HIV\r\n- PARASITIC INFECTION\r\n- HEROIN USE\r\n- GOLD\r\n- PENICILLAMINE\r\n- AMYLOIDOSIS\r\n- LIGHT CHAIN DEPOSITION DISEASE\r\n- NEOPLASIA\r\n- THROMBOTIC THROMBOCYTOPENIC PURPURA\r\n- HEMOLYTIC UREMIC SYNDROME\r\n- HENOCH-SCHONLEIN PURPURA\r\n- ALPORT SYNDROME\r\n- REFLUX NEPHROPATHY\r\n\r\n4. TUBULOINTERSTITIAL DISEASE :\r\n\r\n- DRUGS : SULPHA, ALLOPURINOL\r\n- INFECTIONS : VIRAL, BACTERIAL, PARASITIC\r\n- SJOGREN SYNDROME\r\n- CHRONIC HYPOKALEMIA\r\n- CHR. HYPERCALCEMIA\r\n- SARCOIDOSIS\r\n- MULTIPLE MYELOMA CAST NEPHROPATHY\r\n- HEAVY METALS\r\n- RADIATION NEPHRITIS\r\n- POLYCYSTIC KIDNEYS\r\n- CYSTINOSIS\r\n\r\n5. URINARY TRACT OBSTRUCTION :\r\n\r\n- UROLETHIASIS\r\n- BPH\r\n- TUMORS\r\n- RETROPERITONEAL FIBROSIS\r\n- URETHRAL STRICTURE\r\n- NEUROGENIC BLADDER', 'OTHER TESTS -\r\n* SERUM SODIUM - MAY BE HIGH OR LOW\r\n* SERUM POTASSIUM - HIGH OR NORMAL\r\n* PARATHYROID HORMONE LEVELS - HIGH IN CHR RENAL FAILURE\r\n* SERUM CREATININE - HIGH\r\n* BLOOD UREA & BUN, SERUM URIC ACID, CREATINE KINASE( CPK ) LEVELS - HIGH\r\n* SERUM PHOSPHATES - HIGH\r\n* SERUM CALCIUM & SERUM CALCITRIOL LEVELS - LOW\r\n* X-RAY - GENERALISED OSTEOPOROSIS', '0', '0', '0', '1', '0', 'DISEASE INFLUENCING FACTORS : DIET, LIFE STYLE, ENVIRONMENT, SMOAKING, ALCOHOL, DRUG ABUSE & LACK OF EXERCISE', 'B', '5', 'ASSOCIATED WITH SEVERAL BONE DISEASES : \r\nOSTEITIS FIBROSA CYSTICA, MIXED RENAL OSTEODYSTROPHY, RICKETS, OSTEOMALACIA\r\n\r\nMedical Care: Medical care of the patients with CKD should focus on the following: \r\n\"	Delaying or halting progression of CKD\r\no	Treatment of the underlying condition if possible \r\no	Aggressive blood pressure control to target values per current guidelines \r\no	Use of ACE inhibitors as tolerated, with close monitoring for renal deterioration and for hyperkalemia (avoid in advanced renal failure, bilateral renal artery stenosis [RAS], RAS in a solitary kidney) \r\no	Aggressive glycemic control per the American Diabetes Association (ADA) recommendations; target HbA1C <7.0% \r\no	Protein restriction - Controversial \r\no	Treatment of hyperlipidemia to target levels per current guidelines \r\no	Avoidance of nephrotoxins - IV radiocontrast, nonsteroidal anti-inflammatory agents, aminoglycosides\r\n\"	Treating pathologic manifestations of CKD, including the following:\r\no	Anemia with erythropoietin \r\no	Hyperphosphatemia with dietary phosphate binders and dietary phosphate restriction \r\no	Hypocalcemia with calcium supplements +/- calcitriol \r\no	Hyperparathyroidism with calcitriol or vitamin D analogs \r\no	Volume overload with loop diuretics or ultrafiltration \r\no	Metabolic acidosis with oral alkali supplementation \r\no	Uremic manifestations with chronic renal replacement therapy (hemodialysis, peritoneal dialysis, or renal transplantation): Indications include severe metabolic acidosis, hyperkalemia, pericarditis, encephalopathy, intractable volume overload, failure to thrive and malnutrition, peripheral neuropathy, intractable gastrointestinal symptoms, and GFR less than 10 mL/min. \r\no	Cardiovascular complications\r\n\"	Timely planning for chronic renal replacement therapy\r\no	Early education regarding natural disease progression, different dialytic modalities, renal transplantation, patient option to refuse or discontinue chronic dialysis \r\no	Timely placement of permanent vascular access (arrange for surgical creation of primary arteriovenous fistula, if possible, and preferably at least 6 months in advance of anticipated date of dialysis) \r\no	Timely elective peritoneal dialysis catheter insertion \r\no	Timely referral for renal transplantation\r\nDiet: \r\n\"	Protein restriction early in CKD as a means to delay a decline in GFR is controversial; however, as the patient approaches CKD stage 5, this is recommended to delay the onset of uremic symptoms. Patients with CKD who already are predisposed to becoming malnourished are at higher risk for malnutrition with overly aggressive protein restriction. Malnutrition is a well-established predictor of increased morbidity and mortality in the ESRD population and must be avoided if possible.\r\n\"	Phosphate restriction starting early in CKD\r\n\"	Potassium restriction\r\n\"	Sodium and water restriction as needed to avoid volume overload\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('317', 'RENAL STONE', '0', 'CAUSE OF RENAL STONES :\r\n\r\n- HYPERCALCIURIA - IDIOPATHIC & OTHERWISE\r\n- PRIMARY HYPERPARATHYROIDISM\r\n- HYPEROXALURIA\r\n- HYPERURICOSURIA\r\n- HYPOCITRATURIA\r\n- HYPOMAGNESURIA\r\n- INFECTION STONES\r\n- GOUTY DIATHESIS\r\n- RENAL TUBULAR ACIDOSIS\r\n- CYSTINURIA\r\n- NANOBACTERIA\r\n- IDIOPATHIC\r\n- RARELY FROM XANTHINE, TRIAMTERENE, MONOSODIUM URATE, EPHEDRINE, GUAIFENESIN, INDINAVIR\r\n\r\n--------------------------------------------------------------------------\r\nCALCIUM STONE - 80% OF ALL STONES\r\n\r\nOTHER CAUSES OF HYPERCALCIURIA :\r\n\r\n- EXCESSIVE DIETARY VIT D\r\n- EXCESSIVE CALCIUM & ALKALI INTAKE\r\n- SARCOIDOSIS\r\n- CUSHING SYNDROME\r\n- HYPERTHYROIDISM\r\n- PAGETS DISEASE\r\n- IMMOBILIZATION\r\n\r\n\r\nCAUSES OF NORMOCALCIURIC CALCIUM NEPHROLITHIASIS :\r\n\r\n- HYPOCITRATURIA ( 50% )\r\n- HYPERURICOSURIA ( 25% )\r\n- HYPEROXALURIA ( 10% )\r\n- URINARY STASIS ( 5% )\r\n', '* EXCRETION UROGRAPHY\r\n* 24 HRS URINE CALCIUM, URATES &  PHOSPHATES ESTIMATION\r\n* ANALYSIS OF ANY STONE PASSED\r\n* RANDOM URINE FOR CA/CR RATIO\r\n* NON-CONTRAST-ENHANCED HELICAL CT SCANNING - MOST SENSITIVE, SPECIFIC & ACCURATE PROCEDURE FOR RENAL STONES', '0', '0', '0', '0', '0', '', 'B', '0', '* - URIC ACID STONES VIRTUALLY NEVER DEVELOP UNLESS URINARY PH IS < 5.5. CYSTINE STONE MORE LIKELY IN ACIDIC URINE, CAL PHOSPHATE & STRUVATE STONE ONLY IN ALKALINE URINE, CAL OXLATE IN EITHER URINE PH.\r\n\r\n* - SUBSTANCES THAT INCREASE CHANCES OF STONE FORMATION : GRAPE JUICE ( BY 30-50% ), VIT C, HIGH ANIMAL PROTEIN INTAKE, HIGH CALCIUM & SODIUM INTAKE\r\n\r\n* - ORANGE JUICE PREVENTS STONE FORMATION\r\n\r\n* Systemic illnesses that may increase the risk for kidney stone formation or otherwise affect the clinical course include primary hyperparathyroidism, renal tubular acidosis, cystinuria, gout, diabetes mellitus, inflammatory bowel disease, renal insufficiency, sarcoidosis, and medullary sponge kidney.\r\n\r\nAnatomic abnormalities or surgery of the urinary tract that may predispose to or complicate stone formation are presence of horseshoe kidney, previous urinary diversion, obstruction of the ureteropelvic junction, solitary kidney, previous renal or ureteral surgery, previous kidney disease, history of urinary tract infection and/or pyelonephritis, family history of urolithiasis, and previous stone formation.\r\n\r\n* A complete drug history is crucial because many medications predispose to urolithiasis. These include carbonic anhydrase inhibitors (topirimate), ephedrine, guaifenesin, calcium with vitamin D, triamterene, indinavir, or sulfadiazine.\r\nIndications for urgent intervention include presence of infection with urinary tract obstruction, often indicated by fever, urosepsis, intractable pain and/or vomiting, impending acute renal failure, obstruction in a solitary or transplanted kidney, and bilateral obstructing stones. Acute obstruction must be treated urgently, for once a stone passes into the ureter, obstruction may cause reduced glomerular filtration rate and renal blood flow.\r\n\r\nIn a randomized controlled trial, ureteral catheters, ureteral stents, and percutaneous nephrostomy tubes were equally effective for urinary tract decompression. Pending bladder and renal pelvic urine culture and sensitivity, broad spectrum antibiotics should be prescribed initially.\r\n\r\nParenteral narcotics have traditionally been prescribed for acute renal colic, but nonsteroidal anti-inflammatory drugs (NSAIDs), such as ketorolac and diclofenac, are also effective. NSAIDs should be avoided in patients with poor renal function or a history of gastrointestinal bleeding.\r\n\r\nDetailed metabolic evaluation should be postponed until after the acute stone event has resolved. Factors suggesting a metabolic cause include family history of urolithiasis; bilateral stone disease; presence of inflammatory bowel disease, chronic diarrhea, or malabsorption; history of bariatric surgery; medical conditions associated with urolithiasis, such as primary hyperparathyroidism, gout, or renal tubular acidosis; nephrocalcinosis; osteoporosis or pathologic skeletal fractures; pediatric urolithiasis; and stones formed from cystine, uric acid, or calcium phosphate.\r\n\r\nWhen a comprehensive metabolic evaluation is indicated, it should include analysis of stone composition, cystine screen, and two 24-hour urine collections for volume, pH, calcium, oxalate, citrate, uric acid, phosphate, sodium, potassium, magnesium, ammonium, chloride, sulfate, and creatinine. Blood tests should include serum calcium, bicarbonate, creatinine, chloride, potassium, magnesium, phosphate, uric acid, and blood urea nitrogen. Cystinuric patients should undergo this evaluation plus 24-hour measurement of cystine, and hypercalcemic patients should also have measurement of intact parathyroid hormone and 1,25 dihydroxyvitamin D.\r\n\r\nA relatively recent treatment is medical expulsive therapy or use of drugs to facilitate spontaneous passage of ureteral calculi. These may include calcium channel blockers (nifedipine), steroids, and alpha-adrenergic blockers.\r\n\r\n\"The rationale for using alpha blockers is based on the presence of large numbers of alpha-1 adrenoceptors in the distal ureter,\" the authors conclude. \"These blockers inhibit basal ureteral tone and peristaltic frequency and decrease the intensity of ureteral contractions.\"\r\n\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('367', 'TUBERCULOSIS', '0', '', '* PCR FOR MYCOBACTERIUM TUBERCULOSIS OF THE DISEASED SPECIMEN.\r\n* AMLIFIED MYCOBACTERIUM TUBERCULOSIS DIRECT TEST PERFORMED ON RESPIRATORY SPECIMENS AS WELL AS  NON-RESPIRATORY SPECIMENS LIKE - GEN-PROBE &  AMPLICOR\r\n* TB RNA DETECTION BY TMA METHOD - IS IMPROVED PCR WHICH DETECTS LIVE BACILLI ONLY & 93% SENSITIVE & 99.1% SPECIFIC.\r\n* TB DNA DETECTION BY REAL TIME PCR : SPECIFIC FOR MYCOBACTERIUM TUBERCULOSIS WHICH GAURANTEE NO FALSE NEGATIVITY DUE TO INTERNAL CONTROL.\r\n* MYCOBACTERIUM DIFFERENTIATION BY TMA SYSTEM : IT DIFFERENTIATES MYCOBACTERIUM TUBERCULOSIS BACTERIA FROM OTHER MYCOBACTERIUM SPECICIES & IS IMPROVED PCR TEST.\r\n* TB GOLD TEST : IT DETECTS INTERFERON GAMMA PRODUCED BY SENSITIZED T4 CELLS & IS HIGHLY SENSITIVE (90%) & SPECIFIC ( 98%). UNAFFECTED BY BCG VACCINATION & NTM INFECTION.\r\nT SPOT-TB TEST : LIKE TB GOLD TEST IS HIGHLY SPECIFIC & SENSITIVE, BASED ON RD1 ANTIGENS.', '0', '0', '0', '0', '0', NULL, 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('368', 'TYPHOID FEVER', '0', '', 'WIDAL TEST - MAY BECOME POSITIVE AFTER 4-7 DAYS OF FEVER.\r\n* STOOL CULTURE - BECOMES POSITIVE AFTER 2ND WEEK.\r\n* BLOOD CULTURE - BECOMES POSITIVE AFTER FIRST WEEK\r\n* LATEX AGGLUTINATION TEST FOR ANTIBODIES TO VI ANTIGEN - BECOMES POSITIVE AFTER 3 - 5 DAYS.\r\n* RELATIVE LYMPHOCYTOSIS & LEUKOPENIA SEEN\r\n* POSITIVE WIDAL TEST IN T-0 & T-H > 1/160 OR RISING TITER IN TWO BLOOD SAMPLES TAKEN ON DIFFERENT DATES\r\n* BONE MARROW CULTURE - HIGHLY SENSITIVE ( > 90% ) DESPITE 5 DAYS OF ANTIBIOTIC THERAPY\r\n* CULTURE OF INTESTINAL SECRETIONS ( > 90% ) POSITIVE', '0', '0', '0', '0', '0', NULL, 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('388', 'AMYLOIDOSIS, AA ( INFLAMMATORY )', '0', 'CAUSES :\r\n\r\n1. CHR. INFECTIOUS DISEASES :\r\n\r\n- TUBERCULOSIS\r\n- LEPROSY\r\n- BRONCHIACTESIS\r\n- CHR. OSTEOMYELITIS\r\n- CHR. PYELONEPHRITIS\r\n\r\n2. CHR. NONINFECTIOUS DISEASES :\r\n\r\n- RHEUMATOID ARTHRITIS\r\n- INFLAMMATORY BOWEL DISEASE\r\n- BEHCET SYNDROME\r\n- REITER DISEASE\r\n- ANKYLOSING SPONDYLITIS\r\n- PSORIATIC ARTHRITIS\r\n- CHR. JUVENILE ARTHRITIS\r\n- SLE\r\n- POLYMYOSITIS\r\n- POLYMYALGIA RHEUMATICA\r\n- GOUT\r\n- PSEUDOGOUT\r\n- NONINFLAMMATORY SARCOIDOSIS', 'OTHER TESTS - \r\n* CONGO RED STAINING OF BIOPSY PRODUCES APPLE-GREEN BIREFRINGENCE UNDER POLARIZED LIGHT\r\n* ELECTRON MICROSCOPY - CHARACTERISTIC FIBRILLAR PATTERN OF AMYLOID DEPOSITS \r\n* PROTEIN OR DNA STUDIES - MUTANT PROTEIN IDENTIFICATION , IMMUNOCYTOCHEMISTRY, IMMUNOFLUORESCENT OR IMMUNOPEROXIDASE STAINS WITH SPECIFIC ANTISERA.\r\n* PROTEINURIA\r\n* ECG SHOWS LOW VOLTAGE COMPLEXES WITH ATRIOVENTRICULAR OR INTRAVENTRICULAR CONDUCTION ABNORMALITIES.\r\n* ECHOCARDIOGRAPHY - DIFFUSE THICKENING OF VENTRICULAR WALLS WITH HYPOKINESIA & REDUCED CAVITY SIZE & A DIFFUSE HYPERREFRACTIVE GRANULAR SPARKLING APPEARANCE OF WALLS. *  CARDIAC CATHETERIZATION WITH ENDOMYOCARDIAL BIOPSY IN CASES OF CARDIAC DISEASE IS GOLD STANDARD\r\n* AVOID IVP - BECAUSE DYE EXPOSURE MAY LEAD TO ACUTE RENAL FAILURE\r\n* RADIOLABELLED P- COMPONENT GAMMA SCANNING - TO DEMONSTRATE THE TOTAL BODY BURDEN OF AMYLOID & ITS DISAPPEARANCE AFTE SUCCESSFUL TREATMENT IS DIAGNOSTIC\r\n* X-RAY CHEST - MAY SHOW CARDIOMEGALY, PLEURAL EFFUSION & PULMONARY CONGESTION', '0', '0', '0', '0', '0', '', 'B', '0', 'SERUM AMYLOID A ( SAA ) PROTEIN, PRODUCED PREDOMINANTLY BY HEPATOCYTES IS DEPOSITED IN THE EXTRACELLULAR TISSUES CAUSING AMYLOIDOSIS.\r\n\r\n\r\nMedical Care: At present, the major therapeutic strategy is treatment of the primary inflammatory disease in order to reduce the circulating levels of the amyloid precursor protein SAA. Intensive treatment that lowers SAA levels to less than 10 mg/L may halt disease progression and induce a slow progressive recovery of renal function. Accounts exist of the disappearance of the amyloid deposits associated with tuberculosis or chronically infected burns with appropriate treatment of the infection. Similarly, case reports exist of the disappearance of amyloid deposition associated with chronic inflammatory bowel disease after resection of the affected section of bowel. \r\nData from a randomized prospective series of patients with juvenile chronic arthritis who were treated with chlorambucil or cyclophosphamide show that the occurrence of amyloidosis is markedly reduced (Ahlmen, 1987). The tradeoff for the aggressive use of alkylating agents is an increased incidence of leukemia. Treatment with tumor necrosis factor-  inhibitors and interleukin-1 inhibitors have recently proved effective in controlling the progression of renal amyloid in patients with inflammatory arthritides and hereditary periodic fevers. The application of these agents possibly will achieve similar therapeutic effects without the additional risk, thus lowering the incidence of amyloidosis without increasing mortality. \r\n\"	The use of colchicine (0.6 mg tid) by patients with FMF has been shown to reduce or eliminate the febrile episodes and to prevent the appearance of renal amyloidosis. The mechanism of action is not clear, though the elimination of AA amyloid deposition is likely to be mediated through the suppression of the inflammatory response and SAA production, rather than having a primary effect on amyloidogenesis.\r\no	Based on observations of people with FMF and mice with experimental AA amyloidosis, individual patients with the nephrotic syndrome secondary to renal AA amyloidosis in the course of inflammatory bowel disease, ankylosing spondylitis, and psoriatic arthritis were treated with colchicine and had clinical pictures consistent with the resolution of the nephrotic syndrome.\r\no	While none of these reports contained follow-up renal biopsies, the clinical information supports the conclusion; however, many unreported instances in which colchicine has been used unsuccessfully in similar circumstances also are likely to exist. The only attempt at a randomized prospective trial of colchicine has been carried out in AL disease, and it showed no effect on that process.\r\n\"	The following are new approaches to the treatment of AA amyloidosis that are currently undergoing clinical trials: \r\no	A low-molecular-weight sulfonated molecule has been developed that interferes with fibril formation and deposition of amyloid by inhibiting interaction of SAA with glycosaminoglycans. In experimentally induced murine AA amyloidosis, this drug (NC-503) has been shown to reduce the amount of amyloid deposits. \r\no	Dimerization of human SAP molecules in vivo with a palindromic compound (CPHPC) triggers very rapid clearance of the complexed protein by the liver, depleting SAP from the circulation within a few hours of drug administration. \r\no	Anti-IL-6R therapy appears promising for the treatment of AA amyloidosis (Mihara, 2004). \r\no	A case report exists of severe protein-losing enteropathy with intractable diarrhea due to systemic AA successfully treated with corticosteroids and octreotide (Fushimi, 2005). \r\no	A single patient with AA amyloidosis secondary to Hodgkin disease was administered 4\'-iodo-4\'deoxydoxorubicin as antitumor therapy (see the treatment section in Amyloidosis, Immunoglobulin-Related); this patient has been reported to show a reduction in proteinuria and the liver amyloid burden on biopsy. The response was not complete and the resolution on liver biopsy may have been the result of sampling differentially infiltrated portions of tissue; nonetheless, the result is potentially exciting. \r\no	A more experimentally and theoretically based approach uses the observation that anionic sulphonates interfere with the deposition of AA fibrils in a murine model of inflammatory amyloidosis. One of these compounds is in clinical trials, the results of which should be available over the next 2 years. Little or no toxicity was shown in the preclinical testing.\r\n\"	In patients with AA amyloidosis who were treated before 1990, the major cause of death was renal failure, generally accounting for 35-70% of mortality, with infection responsible for an additional 10-20%. The mean survival was 2-4 years, with the degree of renal insufficiency present at the time of diagnosis correlating with longevity. In a series of patients with AA amyloidosis presenting from 1985-1999, the median survival was 53 months, and the median renal survival (time alive and independent of renal replacement) was 18 months (Joss, 2000). Because of the increased availability of renal replacement, renal failure was the cause of death in only 12.5% of people, and infection became dominant (42%). Nonetheless, the results of dialysis in patients with renal amyloid and an underlying inflammatory disease are worse than the results in those undergoing dialysis for other chronic renal diseases.\r\nSurgical Care: Renal transplantation is an option in these patients, with some successes reported; however, data suggest that patients who have amyloidosis do not have as favorable a prognosis as patients transplanted for other forms of renal failure. Nonetheless, results have been improving, and transplantation is a reasonable option, particularly if the primary inflammatory disease has been treated successfully. \r\nDiet: No specific dietary recommendations for patients with amyloid disease exist. \r\n\"	Patients with chronic renal failure should be managed by a nutritionist who has experience with such patients, maintaining appropriate levels of sodium and protein intake.\r\n\"	Occasionally, patients have significant gastrointestinal symptomatology, and attention should be paid to maintaining caloric intake with minimal gastrointestinal distress.\r\nActivity: Encourage as much activity as the patient can tolerate in order to maintain muscle mass and a positive outlook.\r\n\r\nTREATMENT FOR CARDIAC CONDITION :\r\n\r\n- TT. OF UNDERLYING DISEASE PROCESS LIKE MULTIPLE MYELOMA MAY HELP THE HEART.\r\n- SALT RESTRICTION\r\n- DIGITALIS TOXICITY CAN OCCUR AT MUCH LOWER DOSES BECAUSE IT IS BOUND EXTRACELLULARLY BY AMYLOID FIBRILS.\r\n- DIURETICS CAN HELP. CARE FOR HYPOTENSION\r\n- CALCIUM CHANNEL BLOCKERS BY BINDING TO AMYLOID FIBRILS CAN LEAD TO IMPAIRED CARDIAC CONTRACTILITY & HYPOTENSION\r\n- ACE INHIBITORS CAN BE USEFUL, CARE FOR ORTHOSTATIC HYPOTENSION\r\n- INTRAVENOUS MELPHALAN IS USED TO TREAT PRIMARY AMYLOIDOSIS AS WELL AS THE ASSOCIATED CARDIOMYOPATHY\r\n', NULL, NULL, NULL, NULL, '1'),
('393', 'ACHALASIA CARDIA', '0', 'D.D. - \r\n* DIFFUSE ESOPHAGEAL SPASM\r\n* CHAGAS DISEASE', 'OTHER TESTS - \r\n* MECHOLYL TEST\r\n* CHOLECYSTOKININ (CCK) TEST.\r\n* X-RAY ABDOMEN - ABSENT GASTRIC GAS BUBBLE\r\n* BARIUM SWALLOW - NORMAL SEQUENTIAL PARISTALSIS IS REPLACED BY UNCOORDINATED SIMULTANEOUS CONTRACTIONS.', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: The goal of therapy for achalasia is to relieve symptoms by eliminating the outflow resistance caused by the hypertensive and nonrelaxing LES. Once the obstruction is relieved, the food bolus can travel through the aperistaltic body of the esophagus by gravity. \r\n\"	Calcium channel blockers and nitrates are used to decrease LES pressure.\r\no	Approximately 10% of patients benefit from this treatment. \r\no	This treatment is used primarily in elderly patients who have contraindications to either pneumatic dilatation or surgery.\r\n\"	Endoscopic treatment includes an intrasphincteric injection of botulinum toxin to block the release of acetylcholine at the level of the LES, thereby restoring the balance between excitatory and inhibitory neurotransmitters. \r\no	This treatment has limited value. Only 30% of patient\'s treated endoscopically still have relief of dysphagia 1 year after treatment. \r\no	This treatment can cause an inflammatory reaction at the level of the gastroesophageal junction, making a subsequent myotomy very difficult. \r\no	Use this treatment in elderly patients who are poor candidates for dilatation or surgery.\r\n\"	Pneumatic dilatation performed by a qualified gastroenterologist is the recommended treatment in those sporadic cases in which surgery is not appropriate.\r\no	A balloon is inflated at the level of the gastroesophageal junction to blindly rupture the muscle fibers while leaving the mucosa intact. \r\no	The success rate is 70-80%, and the perforation rate is approximately 5%. \r\no	If a perforation occurs, emergency surgery is needed to close the perforation and perform a myotomy. \r\no	As many as 50% of patients may require more than 1 dilatation. \r\no	The incidence of abnormal gastroesophageal reflux after the procedure is approximately 25%.\r\n\"	A laparoscopic Heller myotomy is considered by many to be the appropriate primary treatment of patients with achalasia (see Surgical Care). A Heller myotomy and a partial fundoplication performed from the chest (thoracoscopic) have a high incidence of gastroesophageal reflux.\r\n\r\nSurgical Care: Because of excellent results, a short hospital stay, and a fast recovery time, the primary treatment is considered by many to be a laparoscopic Heller myotomy and partial fundoplication. In the author\'s experience and in the experience of many authors, this treatment provides a fine balance in relieving symptoms of dysphagia by performing the myotomy and in preventing gastroesophageal reflux by adding a partial wrap. A prospective randomized study from Vanderbilt University has recently shown that a Heller myotomy plus a partial fundoplication was superior to a Heller myotomy alone in regard to the incidence of postoperative reflux. The same authors of this study have also shown that in patients with achalasia, adding a partial fundoplication not only is more effective in preventing postoperative reflux but also is more cost-effective at a time horizon of 10 years. \r\nHowever, the use of preoperative endoscopic therapy remains common but has resulted in intraoperative complications (eg, esophageal perforation) and postoperative complications and in a high failure rate. \r\n\"	Minimally invasive surgery for achalasia is carried out under general anesthesia with the use of 5 trocars. A controlled division of the muscle fibers (myotomy) of the lower esophagus (5 cm) and the proximal stomach (1.5 cm) is carried out, followed by a partial fundoplication to prevent reflux.\r\n\"	Patients remain hospitalized for 24-48 hours and return to regular activities in about 2 weeks.\r\n\"	The operation relieves symptoms in 85-95% of patients, and the incidence of postoperative reflux is 10-15%.\r\n\"	For patients in whom surgery fails, they may be treated with an endoscopic dilatation first. If this fails, a second operation (extending the previous myotomy onto the anterior gastric wall) can be attempted once the cause of failure has been identified with imaging studies. The last resort is to surgically remove the esophagus (ie, esophagectomy).\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('394', 'ACHLORHYDRIA', '0', 'ASSOCIATED WITH :\r\n* VIT B12 DEFICIENCY OR PERNICIOUS ANEMIA\r\n* CANCER STOMACH\r\n- ATROPHIC GASTRITIS\r\n- AUTOIMMUNE THYROIDITIS ASSOCIATED WITH AUTOIMMUNE GASTRITIS\r\n- H-PYLORI INFECTION\r\n- MUCOLIPIDOSIS TYPE-IV\r\n- LONG-TERM TREATMENT WITH PPI\r\n', 'OTHER TESTS:\r\n* FASTING GASTRIN LEVELS ARE RAISED - > 500 - 1000 PG/ML\r\n* GASTRIC ACID ANALYSIS - NORMAL FASTING GASTRIC PH IS 2.1 IN MEN & 2.7 IN WOMEN, IN ACHLORHYDRIA IT IS 7.6 & IN HYPOCHLORHYDRIA, 7.4\r\n* SERUM PEPSINOGEN A LEVELS - EXTREMELY LOW LEVELS -  < 17 MCG/L \r\n* BARIUM STUDY TO RULE OUT GASTRIC CANCER', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: Achlorhydria resulting from long-term PPI use may be treated by dose reduction or withdrawal of the PPI. \r\n\"	Achlorhydria associated with H pylori infection may respond to H pylori eradication therapy, although resumption of gastric acid secretion may only be partial.\r\n\"	In autoimmune diseases (eg, pernicious anemia), acid secretion cannot be restored after destruction of the gastric secretory mucosa.\r\n', NULL, NULL, NULL, NULL, '1'),
('455', 'DENGUE FEVER', '0', '', 'OTHER TESTS :\r\n* COMPLETE BLOOD COUNT - LEUKPPENIA , THROMBOCYTOPENIA.\r\n* IGM ELISA - POSITIVE FROM DAY 5 TO 21 \r\n* PAIRED SEROLOGY DURING RECOVERY PHASE\r\n* ANTIGEN DETECTION ELISA\r\n* RT-PCR ( REVERSE TRANSCRIPTION POLYMERASE CHAIN REACTION)\r\n* VIRUS ISOLATION FROM BLOOD BY MOSQUITO INOCULATION OR MOSQUITO CELL CULTURE.\r\n* IGG ANTIBODIES - POSITIVE FROM DAY 6 TO 30+\r\n* DENGUE NS1 ANTIGEN - THE ANTIGEN IS DETECTED ON THE VERY FIRST DAY OF SYMPTOMS & CAN BE DETECTED UNTIL DAY 9.', '0', '0', '1', '0', '0', 'SPREADS BY MOSQUITO ( A. AEGYPTI ) BITE. INCUBATION PERIOD 2 - 7 DAYS. GIVES TRANSIENT HETEROTYPIC PROTECTION FOR FEW WEEKS ONLY.', 'B', '0', 'HAS FOUR STRAINS, HAEMORRHAGIC FEVER OR DENGUE SHOCK SYNDROME USUALLY OCCUR DURING SECOND INFECTION BY THE VIRUS.\r\nTT : SUPPORTIVE & PALTELET TRANSFUSION IF PLATELETS ARE LOW.', NULL, NULL, NULL, NULL, '1'),
('458', 'ASPERGILLOSIS', '0', '', 'OTHER TESTS :\r\n* X-RAY CHEST - RECURRENT TRANSIENT RADIOGRAPHIC ABNORMALITY IN FORM OF DIFFUSE PULMONARY INFILTRATES & LOBAR OR SEGMENTAL PUL. COLLAPSE. IN ADVANCED CASES PERMANENT BRONCHIACTETIC CHANGES ( TRAM LINE , RING & GLOVED-FINGER SHADOWS ) PREDOMINANTLY IN UPPER LOBES.\r\n* GALACTOMANNAN ASSAY ( A MAJOR COMPONENT OF ASPERGILLUS CELL WALL ) - IN BRONCHOALVEOLAR LAVAGE IN LUNG DISEASE\r\n* PERIPHERAL BLOOD - EOSINOPHELIA\r\n* POSITIVE SKIN TEST TO AN EXTRACT OF A. FUMIGATUS\r\n* SERUM PRECIPITATING ANTIBODIES TO A. FUMIGATUS\r\n* SERUM IGE LEVELS - ELEVATED\r\n* SPUTUM - FUNGAL HYPHAE OF A. FUMIGATUS\r\n* POSITIVE SEROLOGY FOR ASPERGILLUS ( IGG OR IGE )\r\n* HISTOPATHOLOGY & SILVER STAINING IN INVASIVE ASPERGILLOSIS\r\n* INTRADERMAL SKIN TEST WITH ASPERGILLUS ANTIGEN', '0', '0', '1', '0', '0', '', 'B', '0', 'PRIMARILY AFFECTS LUNGS CAUSING 4 MAIN SYNDROMES :\r\n1. ALLERGIC BRONCHOPULMONARY ASPERGILLOSIS\r\n2. CHR. NECROTIZING ASPERGILLUS PNEUMONIA\r\n3. ASPERGILLOMA\r\n4. INVASIVE ASPERGILLOSIS  &\r\n5. SYSTEMIC SPREAD IN SEVERELY IMMUNOCOMPROMIZED PATIENTS\r\n\r\nMedical Care: The treatment of invasive aspergillosis and chronic necrotizing aspergillosis differs significantly from the treatment of ABPA and aspergilloma. \r\n\"	Invasive aspergillosis\r\no	This is often rapidly progressive and has a high mortality rate; therefore, preventive therapy and rapid institution of therapy in patients in whom invasive aspergillosis is suggested may be lifesaving. Prophylactic antifungal therapy and the use of laminar air flow (LAF) or high-efficiency particulate air (HEPA) filtration of patient rooms in patients who receive bone marrow transplant and other high-risk patients may prevent invasive aspergillosis. In patients with solid organ transplant, especially lung, in whom Aspergillus is cultured from sputum without evidence of pneumonia (colonization), inhaled amphotericin B may be administered. \r\no	When high-risk patients develop a compatible clinical picture, empiric treatment for aspergillosis should be started as diagnostic testing is undertaken. Voriconazole is now considered the drug of choice for invasive aspergillosis because of better tolerance and improved survival with its use when compared with amphotericin. Amphotericin B or amphotericin B lipid formulations may be considered as empiric therapy in critically ill patients if the clinical picture could be compatible with mucormycosis, as voriconazole is ineffective for mucor. Caspofungin has also been approved for treatment of invasive aspergillosis in patients who are unable to tolerate or are resistant to other therapies.Initial combination therapy is usually not indicated and should generally be reserved for treatment failures. \r\no	If possible, the level of immunosuppression should be decreased. For example, patients who are neutropenic may receive growth factors (ie, granulocyte colony-stimulating factor, granulocyte-macrophage colony-stimulating factor), and patients with certain types of transplant, in which transplanted organ dysfunction will not be life threatening (eg, renal transplant), may have immunosuppressive medications, including corticosteroids, reduced or discontinued. \r\no	Combination antifungal therapy sometimes may be used for patients whose disease progresses on a single drug. Concomitant therapy with azole antifungals and amphotericin is controversial because the azole antifungals decrease amphotericin-binding sites and may therefore diminish its effectiveness. Be alert to the possibility of diminished effectiveness of amphotericin in any patient who has received prior treatment with an azole antifungal, including voriconazole, itraconazole, fluconazole, or ketoconazole. Newer antifungal azoles are under study (eg, ravuconazole) and may be available for compassionate use in patients in whom other therapies have failed. Posaconazole, a new triazole, was recently approved by the US Food and Drug Administration (FDA).\r\n\"	Aspergilloma\r\no	Treatment is considered when patients become symptomatic, usually with hemoptysis. Surgical resection is curative but may not be possible in patients with limited pulmonary function. Oral itraconazole may provide partial or complete resolution of aspergillomas in 60% of patients. Successful intracavitary treatment, using CT-guided percutaneously placed catheters to instill amphotericin alone or in combination with other drugs, including acetylcysteine and aminocaproic acid, has been reported in small numbers of patients. \r\no	Bronchial artery embolization may be used for life-threatening hemoptysis in patients thought to have insufficient pulmonary reserve to tolerate surgery or in patients with recurrent hemoptysis (eg, patients with cystic fibrosis in whom hemoptysis may be related to underlying bronchiectasis with or without aspergilloma). Bronchial artery embolization requires a skilled and experienced radiologist because localizing the abnormal vessel(s) may be challenging. Because the anterior spinal arteries may originate from the bronchial vessels, serious neurologic complications, although rare, may occur.\r\n\"	Allergic bronchopulmonary aspergillosis \r\no	This is a hypersensitivity reaction that requires treatment with oral corticosteroids. Inhaled steroids are not effective. \r\no	It may be beneficial to add oral itraconazole to steroids in patients with recurrent or chronic ABPA. This may allow more rapid resolution of infiltrates and symptoms, facilitating steroid tapering or lowering the needed maintenance corticosteroid dosage. \r\no	Patients who have associated allergic fungal sinusitis benefit from surgical resection of obstructing nasal polyps and inspissated mucus in addition to corticosteroid therapy. Nasal washes with amphotericin have also been used. \r\n\"	Chronic necrotizing Aspergillus pneumonia \r\no	Treatment consists of therapy with voriconazole, or in some cases itraconazole (if expense is an issue), caspofungin, or amphotericin B or amphotericin lipid formulation. A prolonged course of therapy to radiographic resolution is needed. In addition, reduction or elimination of immunosuppression should be attempted, if possible. \r\no	Surgical resection may be considered when localized disease fails to respond to antifungal therapy.\r\nSurgical Care: \r\n\"	Invasive aspergillosis and chronic necrotizing aspergillosis\r\no	Surgical resection is a consideration for localized disease that has failed to respond to prolonged antifungal therapy.\r\no	Aspergillomas may occasionally form in areas of necrotizing pneumonia. These necrotic areas may bleed, sometimes massively, necessitating consideration of surgical resection.\r\no	Patients may be high-risk surgical candidates because of underlying disease, coagulopathy, or thrombocytopenia and limited pulmonary reserve.\r\n\"	Aspergilloma\r\no	Surgical resection may be considered for massive hemoptysis if pulmonary function is sufficient enough for this sort of intervention. Assessment of operative risk necessitates obtaining pulmonary function studies, arterial blood gas determinations, and, possibly, split lung function studies (eg, quantitative perfusion lung scanning). Because aspergilloma occurs in cavitary areas, the affected lung may not be functional.\r\no	Surgical resection may be difficult because of scarring, pleural adhesion, and the presence of abnormal vasculature.\r\n\"	Allergic bronchopulmonary aspergillosis\r\no	Areas of mucoid impaction may have a masslike appearance and are sometimes resected as an undiagnosed lung mass; however, steroid therapy and oral itraconazole therapy are preferred.\r\no	Allergic fungal sinusitis usually requires endoscopic sinus surgery to improve drainage.\r\n.\r\nDRUG TREATMENT :\r\n\r\n1. AMPHOTERICIN B\r\n2. ITRACONAZOLE\r\n3. CASPOFUNGIN\r\n4. VORICONAZOLE\r\n5. POSACONAZOLE\r\n\r\nSTEROIDS IN ALLERGIC REACTIONS :\r\n\r\n1. PREDNISOLONE\r\n', NULL, NULL, NULL, NULL, '1'),
('471', 'BASAL CELL CARCINOMA', '0', 'D.D. :\r\n* EPITHRLIOMA\r\n* ULCERATED SEBACEOUS CYST\r\n* MOLLUSCUM SEBACEUM ( CONTAGIOSUM)\r\n* PRIMARY SYPHILITIC SORE\r\n* SEBORRHOEIC WART\r\n* LUPUS VULGARIS\r\n* VACCINIA\r\n* ANTHRAX\r\n\r\n--------------------------------------------------------------------------\r\nCAUSES :\r\n\r\n- SUN EXPOSURE\r\n- EXPOSURE TO ARTIFICIAL ULTRA VIOLET LIGHT\r\n- IONIZING RADIATION EXPOSURE\r\n- ARSENIC EXPOSURE THROUGH INGESTION\r\n- IMMUNOSUPPRESSION\r\n- XERODERMA PIGMENTOSUM\r\n- NEVOID BCC SYNDROME\r\n- BAZEX SYNDROME\r\n- H/O PREVIOUS NONMELANOMA SKIN CANCER\r\n', '', '0', '0', '0', '0', '0', 'RISK FACTORS: Chronic sun exposure, Light complexion, Tendency to sunburn, Male sex although increasing risk in women due to lifestyle changes e.g., suntan parlors, etc., Family history of skin cancer', 'B', '0', 'TYPES OF BCC : NODULAR, CYSTIC, PIGMENTED, MORPHEAFORM ( SCLEROSING ) & SUPERFICIAL\r\n\r\nBasal Cell Carcinoma of the Skin \r\nThe traditional methods of treatment involve the use of cryosurgery, radiation therapy, electrodesiccation and curettage, and simple excision. Each of these methods is useful in specific clinical situations. Depending on case selection, these methods have cure rates ranging from 85% to 95%.\r\nMohs micrographic surgery has the highest 5-year cure rates for surgical treatment of both primary (96%) and recurrent (90%) tumors. This method uses microscopic control to evaluate the extent of tumor invasion. \r\nTreatment options: \r\n1.	Mohs micrographic surgery. Although this method is complicated and requires special training, it has the highest cure rate of all surgical treatments because the tumor is microscopically delineated until it is completely removed. While other treatment methods for recurrent basal cell carcinoma have failure rates of about 50%, cure rates have been reported at 96% when treated by Mohs micrographic surgery. In addition, its use is indicated for the treatment of primary basal cell carcinomas when they occur at sites known to have a high initial-treatment failure rate with traditional methods (e.g., periorbital area, nasolabial fold, nose-cheek angle, posterior cheek sulcus, pinna, ear canal, forehead, scalp, or tumors arising in a scar). Mohs micrographic surgery is also indicated for: \r\n\"	tumors with poorly defined clinical borders; \r\n\"	tumors with diameters >2 cm; \r\n\"	tumors with histopathologic features showing morpheaform or sclerotic patterns; and \r\n\"	tumors arising in regions where maximum preservation of uninvolved tissue is desirable such as the eyelid, nose, finger, and genitalia. \r\n2.	Simple excision with frozen or permanent sectioning for margin evaluation. This traditional surgical treatment usually relies on surgical margins ranging from 3 mm to 10 mm, depending on the diameter of the tumor.\r\nTumor recurrence is not uncommon because only a small fraction of the total tumor margin is examined pathologically. Recurrence rate for primary tumors >1.5 cm in diameter is at least 12% within 5 years; if the primary tumor measures >3 cm, the 5-year recurrence rate is 23.1%. Primary tumors of the ears, eyes, scalp, and nose have recurrence rates ranging from 12.9% to 25%. \r\n3.	Electrodesiccation and curettage. This method is the most widely employed method for removing primary basal cell carcinomas. Although it is a quick method for destroying the tumor, adequacy of treatment cannot be assessed immediately since the surgeon cannot visually detect the depth of microscopic tumor invasion. \r\nTumors with diameters ranging from 2 mm to 5 mm have a 15% recurrence rate after treatment with electrodesiccation and curettage. When tumors >3 cm are treated with electrodesiccation and curettage, a 50% recurrence rate should be expected within 5 years. \r\n4.	Cryosurgery. Cryosurgery may be considered for patients with small, clinically well-defined primary tumors. It is especially useful for debilitated patients with medical conditions that preclude other types of surgery. \r\nAbsolute contraindications for cryosurgery include abnormal cold tolerance, cryoglobulinemia, cryofibrinogenemia, Raynaud\'s disease (only for treatment of lesions on hands and feet), and platelet deficiency disorders. Morphea or sclerosing basal cell carcinoma should not be treated by cryosurgery. Relative contraindications to cryosurgery include tumors of the scalp, ala nasi, nasolabial fold, tragus, postauricular sulcus, free eyelid margin, upper lip vermillion border, and lower legs. Caution should also be used before treating nodular ulcerative neoplasia >3 cm, carcinomas fixed to the underlying bone or cartilage, tumors situated on the lateral margins of the fingers and at the ulnar fossa of the elbow, or recurrent carcinomas following surgical excision. Significant morbidity is associated with the use of cryosurgery. \r\nEdema is common following treatment, especially around the periorbital region, temple, and forehead. Treated tumors usually exude necrotic material after which an eschar forms and persists for about 4 weeks. Permanent pigment loss at the treatment site is unavoidable. Atrophy and hypertrophic scarring have been reported as well as instances of motor and sensory neuropathy. \r\n5.	Radiation therapy. Radiation therapy is a logical treatment choice, particularly for patients with primary lesions requiring difficult or extensive surgery (e.g., eyelids, nose, or ears). It eliminates the need for skin grafting when surgery would result in an extensive defect. Cosmetic results are generally good to excellent with a small amount of hypopigmentation or telangiectasia in the treatment port. Radiation therapy can also be used for lesions that recur after a primary surgical approach.\r\nRadiation therapy is contraindicated for patients with xeroderma pigmentosum, epidermodysplasia verruciformis, or the basal cell nevus syndrome because it may induce more tumors in the treatment area. \r\n6.	Carbon dioxide laser. This method is most frequently applied to the superficial type of basal cell carcinoma. It may be considered when a bleeding diathesis is present, since bleeding is unusual when this laser is used.\r\n7.	Topical fluorouracil (5-FU). This method may be helpful in the management of selected patients with superficial basal cell carcinomas. Careful and prolonged follow-up is required, since deep follicular portions of the tumor may escape treatment and result in future tumor recurrence. \r\n8.	Interferon alfa. Several early studies have shown variable responses of basal cell carcinoma to intralesional interferon alfa. Further reports are awaited until this treatment may be recommended for routine clinical practice. \r\n9.	Photodynamic therapy. Photodynamic therapy with photosensitizers may be effective treatment for patients with superficial epithelial skin tumors.\r\nFollow-up: \r\n\"	Following treatment for basal cell carcinoma, patients should be clinically examined every 6 months for 5 years. Thereafter, patients should be examined for recurrent tumors or new primary tumors at yearly intervals. Of the patients who develop a basal cell carcinoma, 36% will develop a second primary basal cell carcinoma within the next 5 years. Early diagnosis and treatment of recurrent basal cell carcinomas or another primary basal cell carcinoma is desirable since the treatment of the disease in its earliest stages results in less patient morbidity. \r\n\r\nPATIENT MONITORING:  Every month for 3 months, then twice yearly for 5 years, yearly thereafter\r\n\r\nPREVENTION/AVOIDANCE:\r\n• Sunscreens\r\n• Hats, long-sleeve shirts\r\n• Avoid tanning and sunburn, especially during childhood\r\n\r\nPOSSIBLE COMPLICATIONS:\r\n• Local recurrence and spread. Usually recurrences will appear within 5 years.\r\n• Metastasis (rare)\r\n\r\nEXPECTED COURSE/PROGNOSIS :\r\n• Proper treatment yields 90-95% cure\r\n• Most recurrences happen within 5 years\r\n• Development of new basal cell carcinomas. 36% of patients will develop a new lesion within 5 years.', NULL, NULL, NULL, NULL, '1'),
('477', 'BERIBERI', '0', 'CAUSES :\r\n\r\n1. LACK OF THIAMINE INTAKE :\r\n\r\n- DIET CONTAINING MAINLY MILLED RICE WHICH CONTAINS THIAMINASES\r\n- ALCOHOL STATE\r\n- STARVATION STATE\r\n\r\n2. INCREASED CONSUMPTION STATES:\r\n\r\n- DIETS HIGH IN CARBOHYDRATE OR SATURATED FAT INTAKE\r\n- PREGNANCY\r\n- HYPERTHYROIDISM\r\n- LACTATION\r\n- FEVER\r\n- INCREASED PHYSICAL EXERCISE\r\n\r\n3. INCREASED DEPLETION :\r\n\r\n- CHR INTESTINAL DISEASE\r\n- ALCOHOLISM\r\n- MALNUTRITION\r\n- FOLATE DEFICIENCY : CAUSES INDIRECT THIAMINE DEFICIENCY BECAUSE THIAMINE IS PRESENT BUT CANT BE ACTIVATED\r\n\r\n\r\n--------------------------------------------------------------------------\r\n\r\nD.D. :\r\n\r\n- ALCOHOLIC FATTY LIVER\r\n- ALCOHOLIC HEPATITIS\r\n- ALCOHOLIC KETOACIDOSIS\r\n- ALCOHOLISM\r\n- ANEMIA\r\n- ANOREXIA NERVOSA\r\n- CALIFORNIA ENCEPHALITIS\r\n- CAMPYLOBACTER INFECTIONS\r\n- CARDIOGENIC SHOCK\r\n- CARDIOMYOPATHY : ALCOHOLIC, COCAINE, DIABETIC HEART DISEASE, DILATED, HYPERTROPHIC, PERIPARTUM, RESTRICTIVE\r\n- CHOLERA\r\n- CIRRHOSIS\r\n- DELIRIUM\r\n- DELIRIUM TREMENS\r\n- DELUSIONAL DISORDER\r\n- DEMENTIA\r\n- DEPRESSION\r\n- DIABETIC KETOACIDOSIS\r\n- ENCEPHALOPATHY : DIALYSIS, HEAPTIC, HYPERTENSIVE, UREMIC\r\n- ENTEROBACTER INFECTION\r\n- FOLIC ACID DEFICIENCY\r\n- GOITER\r\n- HYPERTHYROIDISM\r\n- HEPATIC FAILURE\r\n- ILEUS\r\n- IRRITABLE BOWEL SYNDROME\r\n- METABOLIC ACIDOSIS\r\n- MYOCARDITIS\r\n- NERVE ENTRAPMENT SYNDROME\r\n- POLYMYOSITIS\r\n- SCHIZOPHRENIFORM DISORDER\r\n- SCURVY\r\n- SUB ACUTE THYROIDITIS\r\n- TRIGEMINAL NEURALGIA\r\n- VASCULAR DEMENTIA\r\n- VIRAL ARTHRITIS\r\n- WERNICKE-KORSAKOFF ENCEPHALOPATHY', 'OTHER TESTS :\r\n* REPLACING THIAMINE AS AN INITIAL TEST ( CLINICAL TRAIL ) IS BEST\r\n* BLOOD THIAMINE, PYRUVATE, ALPHA-KETOGLUTARATE, LACTATE & GLYOXYLATE LEVELS & URINARY EXCRETION OF THIAMINE & ITS METABOLITES LIKE METHYLGLYOXAL- LOW \r\n* FUNCTIONAL ENZYMATIC ASSAY OF TRANSKETOLASE ACTIVITY MEASURED BEFORE & AFTER THE ADDITION OF THIAMINE PYROPHOSPHATE. A > 15% STIMULATION BY THE ADDITION OF THIAMINE PYROPHOSPHATE ( AN ACTIVITY COEFFICIENT OF 1.25) IS ABNORMAL.\r\n* SERUM OR BLOOD THIAMINE OR PHOSPHORYLATED ESTERS OF THIAMINE CAN BE MEASURED BY HIGH PERFORMANCE LIQUID CHROMATOGRAPHY\r\n* URINARY LEVELS OF THIAMINE < 27 UG / GM OF CREATININE PER DAY IS ABNORMAL. DURING THIS TEST PT. SHOULD NOT BE ON DIURETICS, WHICH INCREASES THIAMINE EXCRETION.', '0', '0', '0', '0', '0', '', 'B', '0', '* - THREE TYPES ARE RECOGNISED : 1. DRY BERIBERI, 2. WET BERIBERI & 3. ACUTE FULMINANT CARDIOVASCULAR BERIBERI OR SHOSHIN BERIBERI\r\n\r\nIn suspected cases, prompt administration of parenteral thiamine is indicated. The recommended dose is 50 mg intramuscularly for several days. The duration of therapy depends on the symptoms, and therapy is indicated until all symptoms have disappeared. Maintenance is recommended at 2.5-5 mg per day orally, unless a malabsorption syndrome is suspected.\r\nSupport for other cardiac function is necessary in cases of wet beriberi because lack of cardiac function support leads to low output cardiac failure when the thiamine deficiency is corrected.\r\nThiamine, even at high concentrations, is not toxic in a person with normal renal function. No cases of thiamine toxicity have been reported from its use at the dosages indicated even in patients in critical condition.\r\nDiet\r\n\"	Thiamine-containing foods include all vegetables and the outer layer of grains. Thiamine is not present in fats or highly refined sugars and is present sparingly in cassava. Factors in the diet that decrease absorption are the presence of foods containing thiaminases, such as milled rice, shrimp, mussels, clams, fresh fish, and raw animal tissues. \r\n\"	\r\n\"	Cassava is a staple in many developing countries and has been used in a variety of high-energy diets. Although it contains thiamine (0.05-0.225 mg of thiamine per 100 g of cassava, depending on the crop), the high carbohydrate load of a diet rich in cassava actually consumes more thiamine than it offers the body and can result in thiamine deficiency from the same mechanism as administering dextrose to a person with limited supplies of the vitamin. \r\nActivity\r\nThe level of activity and high energy consumption states (eg, hyperthyroidism, pregnancy, lactation, severe disease) increase the daily requirements of thiamine.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('491', 'PAGET DISEASE', '0', 'COMMON SITES FOR BONE CHANGES :\r\n\r\nPELVIS, HIP, SPINE, SKULL, TIBIA & HUMERUS\r\n\r\nD.D. :\r\n\r\n- METASTATIC BONE DISEASE', 'OTHER TESTS - \r\n* TC-99M DIPHOSPHONATE BONE SCAN- MOST SENSITIVE BUT LESS SPECIFIC\r\n* S. ALK. PHOSPHATASE - MARKEDLY ELEVATED IN ACTIVE DISEASE\r\n* X-RAY FINDINGS - EARLY CASE - ADVANCING WEDGE SHAPED RESORPTION FRONT AT EITHER END OF LONG TUBULAR BONES. IN SKULL, LARGE CIRCUMSCRIBED OSTEOLYTIC LESIONS.\r\n IN LATE STAGES - THE BONES BECOME SCLEROTIC, ENLARGED & DEMONSTRATE BOWING DEFORMITIES, PSEUDO OR COMPLETE FRACTURES, SKULL SHOWS THICKENING OF CALVARIUM 7 PATCHY INCREASE IN BONE DENSITY GIVING SKULL COTTON WOOL APEARANCE. LATER ON MARKED SCLEROSIS OF BONES OCCUR.\r\n* BONE BIOPSY - DIAGNOSTIC\r\n* SERUM CALCIUM & PHOSPHORUS - NORMAL UNLESS THE PATIENT IS IMMOBILE\r\n* SERUM BONE SPECIFIC ALK. PHOSPHATASE - MORE SENSITIVE MARKER OF BONE FORMATION\r\n* URINARY PYRIDINIUM COLLAGEN CROSS LINKS( PYRIDINOLINE ) - INCREASED (BETTER INDICATOR OF INCREASED BONE RESORPTION THAN URINARY HYDROXYPROLINE )\r\n* URINARY HYDROXYPROLINE - INCREASED\r\n* ECG - MAY SHOW AV CONDUCTION DEFECT OR BUNDLE BRANCH BLOCK', '0', '0', '0', '0', '0', '', 'B', '0', '* IS THE SECOND MOST COMMON BONE DISORDER IN ELDERLY AFTER OSTEOPOROSIS.\r\n\r\nPREVALENT DISORDERS : ARTHRITIS, FRACTURES, PRIMARY HYPERPARATHYROIDISM, OSTEOPOROSIS, THYROID DISEASE, RENAL STONE & MALIGNANT SARCOMA IN PAGETIC BONE.\r\n\r\nMedical Care: \r\n\"	The short-term objective of treatment is to control disease activity. The long-term objectives of treatment are to minimize or prevent disease progression and to decrease complications from the disease, if possible.\r\n\"	Indications for treatment include complications of Paget disease, including bone pain, progressive skeletal deformity, high-output congestive heart failure, hypercalcemia, compression of spinal cord and nerve roots, bone compression of the eighth cranial or optic nerve, recurrent renal calculi due to hypercalciuria, or fractures. When Paget disease occurs around a joint, treatment is often administered in an attempt to prevent development of osteoarthritis. Also, young patients and those with high levels of BSAP are often treated to avoid future complications.\r\n\"	Medical therapy for Paget disease should include bisphosphonate treatment with serial monitoring of bone markers. Bone markers should be rechecked 2-3 months following bisphosphonate treatment.\r\n\"	Because of the increased risk of malignancy, patients should be monitored indefinitely.\r\n\"	Nonsteroidal anti-inflammatory drugs and acetaminophen may be effective for pain management.\r\n\"	Orthotic devices, including canes and walkers, may be useful for patients with Paget disease that involves the lower limbs who have gait abnormalities. \r\n\"	Chemotherapy, radiation, or both may be used to treat neoplasms arising from pagetic bone.\r\nSurgical Care: \r\n\"	Indications for surgery are bony deformity, pathologic fractures, nerve compression, and degenerative arthritis, particularly of the hip or knee.\r\n\"	Total hip replacement and tibial osteotomy are effective for relieving pain and restoring mobility. Pharmacological therapy, including bisphosphonates, should be used preoperatively to try to reduce disease activity in order to prevent severe blood loss during surgery.\r\n\"	After surgery, bone healing may be prolonged, and lengthy rehabilitation may be necessary.\r\n\"	Amputation may also be necessary in the presence of a malignant transformation.\r\n\"	Decompressive laminectomies may be necessary if medical therapy cannot induce recovery in those with neurological sequelae from spinal cord compression.\r\nDiet: \r\n\"	No specific dietary modifications are necessary in patients with Paget disease. However, in patients with Paget disease who are receiving bisphosphonate therapy, ensure adequate intake of calcium and vitamin D.\r\nActivity: \r\n\"	No specific adjustments in physical activity levels are necessary in patients with Paget disease. If secondary osteoarthritis occurs in the knee, quadriceps-strengthening exercises may be helpful. If bone pain occurs with weight bearing or if gait abnormalities are present, individualized adjustment in physical activity regimens may be necessary.\r\n\r\n\r\nDRUG TREATMENT :\r\n\r\n1. BISPHOSPHONATES : TO REDUCE EXCESS BONE TURNOVER\r\n\r\n2. CALCITONIN', NULL, NULL, NULL, NULL, '1'),
('502', 'BUDD-CHIARI SYNDROME', '0', 'CAUSES :\r\n-   THROMBOSIS OF HEPATIC VEINS, OFTEN IN THE SETTING OF POLYCYTHEMIA VERA, MYELOPROLIFERATIVE SYNDROMES, PAROXYSMAL NOCTURNAL HEMOGLOBINURIA\r\n- ANTIPHOSPHOLIPID ANTIBODY SYNDROME\r\n- ESSENTIAL THROMBOCYTOSIS\r\n-  ORAL CONTRACEPTIVES OR OTHER HYPERCOAGULABLE STATES.\r\n-   INVASION OF INFERIOR VENA CAVA BY TUMOR SUCH AS RENAL CELL OR HEPATOCELLULAR CARCINOMA, LEIMYOSARCOMA, ADRENAL CARCINOMA, WILMS TUMOR, RT ATRIAL MYXOMA\r\n-   IDEOPATHIC MEMBRANOUS OBSTRUCTION OF INF VENA CAVA\r\n-   HEPATIC IRRADIATION\r\n-  TT WITH CERTAIN ANTINEOPLASTICS OR INGESTION OF PYRROLIDIZINE ALKALOIDS PRESENT IN CERTAIN HERBAL TEAS ( BUSH TEA DISEASE) CAN CAUSE VENOCLUSIVE DISEASAE AFFECTING SUBLOBULAR BRANCHES OF HEPATIC VEINS & HEPATIC VENULES\r\n- PREGNANCY\r\n- CHR. INFLAMMATORY DISEASES\r\n- CLOTTING DISORDERS\r\n- INFECTIONS LIKE\r\n* BEHCET DISEASE\r\n* INFLAMMATORY BOWEL DISEASE\r\n* SARCOIDOSIS\r\n* SLE\r\n* SJOGREN SYNDROME\r\n* MIXED CONNECTIVE TISSUE DISORDERS\r\n- INHERITED THROMBOTIC DIATHESIS LIKE\r\n* PROTEIN C DEFICIENCY\r\n* PROTEIN S DEFICIENCY\r\n* ANTITHROMBIN III DEFICIENCY\r\n* FACTOR V LEIDEN DEFICIENCY\r\n- MISCELLANEOUS LIKE\r\n* ALPHA 1-ANTITRYPSIN DEFICIENCY\r\n* TRAUMA\r\n* DACARBAZINE\r\n* URETHANE\r\n- IDIOPATHIC', 'OTHER TESTS :\r\n* ASCITIC FLUID EXAMINATION : PROTEIN CONC>2 GM/DL, WBC < 500\r\n* HEPATIC VENOGRAPHY OR LIVER BIOPSY SHOWING CENTRILOBULAR CONGESTION & SINUSOIDAL DILATATION IN THE ABSENCE OF RT. SIDED HEART FAILURE ESTABLISHES DIAGNOSIS\r\n* COLOR FLOW DOPPLER ULTRA SOUND : SENSITIVITY & SPECIFICITY 85 - 90%\r\n* MRI - SENSITIVITY & SPECIFICITY 85 - 90%', '0', '0', '0', '0', '0', '', 'B', '6', '* FOUR DIFFERENT FORMS SEEN - ACUTE, SUBACUTE, CHRONIC & FULMINANT FORM\r\n\r\nMedical Care: Medical therapy can be instituted for short-term, symptomatic benefit. Medical therapy alone is associated with a high 2-year mortality rate (80-85%). \r\n\"	Management of ascites.\r\n\"	Anticoagulation\r\n\"	Antithrombolytic therapy: This has been used in a few cases. Agents include streptokinase, urokinase, recombinant tissue plasminogen activator, and other modalities.\r\n\"	Angioplasty: This can help relieve obstruction caused by membranous webs.\r\nSurgical Care: Offer decompression of the hepatic vasculature if portal hypertension is the cause of the symptoms. Either surgery or a transjugular intrahepatic portosystemic shunt procedure can be performed. \r\nOffer liver transplantation if decompensated liver cirrhosis is present.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. ANTICOAGULANTS\r\n\r\n- WARFARIN\r\n\r\n2. FIBRINOLYTIC AGENTS :\r\n\r\n- STREPTOKINASE\r\n- UROKINASE\r\n- ALTEPLASE', NULL, NULL, NULL, NULL, '1'),
('590', 'GLUCAGONOMA', '0', 'CAUSES OF HIGH SERUM GLUCAGON :\r\n\r\n1 - BENIGN OR MALIGNANT TUMOR OF ALPHA CELLS OF PANCREAS\r\n\r\n2. CAUSES IN WHICH LOSS OF NORMAL RESTRAINING INFLUENCE OF INSULIN ON ALPHA CELL FUNCTION OCCUR LIKE IN RELATIVE OR ABSOLUTE INSULIN DEFICIENCY\r\n\r\n3. DIABETES MELLITUS & ACUTE DIABETIC COMPLICATIONS EG. KETOACIDOSIS, HYPEROSMOLAR HYPERGLYCEMIC STATE\r\n\r\n4. OBESITY - EXAGGERATED GLUCAGON RESPONSE TO PROTEIN MEAL & INCREASED ARGININE LEVELS\r\n\r\n5. PANCREATITIS\r\n\r\n6. TRAUMA\r\n\r\n7. BURN\r\n\r\n8. INFECTION & SEPSIS\r\n\r\n9. MYOCARDIAL INFARCTION\r\n\r\n10. INCREASED CORTISOL LEVELS \r\n\r\n11. INCREASED CATECHOLAMINE OR GROWTH HORMONE LEVELS\r\n\r\n12. RENAL FAILURE\r\n\r\n13. HEPATIC CIRRHOSIS\r\n\r\nD.D. :\r\n\r\n- DIABETES MELLITUS\r\n- CIRRHOSIS\r\n- PARANEOPLASTIC SYNDROMES\r\n- ACRODERMATITIS ENTEROPATHICA\r\n- BACTEREMIA\r\n- ESSENTIAL FATTY ACID DEFICIENCY\r\n- PSORIASIS\r\n- PELLAGRA\r\n- HERPETIC DERMATITIS\r\n- RENAL FAILURE\r\n- ZINC DEFICIENCY\r\n- USE OF ORAL CONTRACEPTIVES OR DANAZOL\r\n- HEPATIC FAILURE', 'OTHER TESTS :\r\n* PLASMA GLUCAGON LEVELS - HIGH ( > 500 PG / ML )\r\n* ULTRA SOUND ABDOMEN, CT ABDOMEN, CELIAC ANGIOGRAPHY, AORTOGRAPHY ARE FREQUENTLY INSENSITIVE & MAY LOCALIZE ABOUT 60% OF GASTRINOMAS.\r\n* ENDOSCOPIC ULTRA SOUND OR INTRAOPERATIVE ULTRA SOUND\r\n* TRANSHEPATIC PORTAL VENOUS SAMPLE MAY LOCALIZE OCCULT TUMORS.\r\n* BLOOD SUGAR & GTT TO ESTABLISH PRESENCE OF DIABETES\r\n* CBC TO ESTABLISH ANEMIA\r\n* SOME CASES MAY BE PART OF MEN 1 SYNDROME SO CHECK - FASTING SERUM INSULIN, GLUCAGON, PROLACTIN, CALCIUM & VIP LEVELS\r\n* TO STUDT NUTRITIONAL STATUS - SERUM LEVELS OF AMINO ACIDS, ZINC & ESSENTIAL FATTY ACIDS\r\n* LFT - TO DETERMINE HEPATIC METASTASIS', '0', '0', '0', '0', '0', '', 'B', '0', 'A RARE NONENDOCRINE TUMOR FROM ALPHA-2 CELLS OF PANCREATS WITH HIGH RATE OF THROMBOEMBOLIC PHENOMENON. NECROLYTIC MIGRATING ERYTHEMA IS THE MOST CHARACTERISTIC CLINICAL SIGN.\r\n\r\nMedical Care\r\nCurrently, active drugs used to treat glucagonoma do not exist, although some drugs can cause partial regression of a neoplastic mass or improvements in the symptoms of NME.\r\n\"	In the literature, good results are obtained with doxorubicin and streptozotocin (5-fluorouracil [5-FU] and streptozotocin) via selective damage of islets cells. \r\n\"	\r\n\"	Long-acting octreotide, analogous to human somatostatin, causes NME symptom regression in some patients and not in other patients. \r\n\"	\r\n\"	Remission of glucagonoma through treatment with dacarbazine is described in a single patient. \r\n\r\nSurgical Care\r\nOnce a glucagonoma is identified, optimal management is surgical resection, which is the only curative therapy.\r\n\"	In some patients, removal of the tumor may reverse symptoms. \r\n\"	\r\n\"	Patients with liver metastases and severe symptoms caused by tumor bulk or hormone-release syndromes may benefit from procedures that reduce hepatic arterial blood flow to metastases, including hepatic arterial occlusion with embolization or with chemoembolization that causes a necrosis of the metastases without damaging the healthy hepatic parenchyma, which is supplied from the portal circulation. This treatment may also be combined with systemic chemotherapy in selected patients. \r\n\"	\r\n\"	Beyond neoplasm removal, resect healthy surrounding parenchyma and locoregional lymph nodes, which can occasionally be metastatic or, more rarely, the primary site of the tumor. \r\n\"	\r\n\"	Several authors have reported clinical palliation of symptoms from surgical debulking of the tumor. \r\nDiet\r\nIn patients with glucagonoma, providing a supplemental protein supply in order to furnish amino acids is useful. This can be administrated intravenously in the more severe cases. Essential fatty acids (ie, administering olive oil), zinc, vitamins, and minerals are also helpful.\r\nActivity\r\nMild exercise is usually not harmful in patients with glucagonoma.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. ANTISECRETORY AGENTS :\r\n\r\n- OCTREOTIDE\r\n\r\n2. ANTINEOPLASTIC AGENTS :\r\n\r\n- DOXORUBICIN\r\n- FLUOROURACIL ( 5-FLUOROURACIL ) \r\n- STREPTOZOCIN\r\n- DACARBAZINE', NULL, NULL, NULL, NULL, '1'),
('591', 'G6PD DEFICIENCY DISEASE', '0', 'DRUGS TO BE AVOIDED :\r\n\r\n- ANTIMALARIALS : CHLOROQUIN, AMODIOQUIN, BULAQUIN, PRIMAQUIN\r\n- DAPSONE\r\n- SULPHONAMIDES\r\n- ANTIMONY\r\n- QUINOLONES\r\n- FURAZOLIDONE, NITROFURANTOIN, NALIDIXIC ACID\r\n- PHENAZONE\r\n- ASPIRIN, ACETAMINOPHAN, SALICYLATES\r\n- CHLORAMPHENICOL\r\n- PHENAZOPYRIDINE\r\n- VIT K', 'OTHER TESTS :\r\n* MEASURE THE ACTUAL ENZYME ACTIVITY OF G6PD RATHER THAN THE AMOUNT OF G-6-PD PROTEIN.\r\n* LIVER FUNCTION TESTS - SLIGHTLY RAISED SGOT, SGPT( 37 - 150 ) & SALK PHOSPHATASE( 140-660 ).\r\n* CBC - LOW HAEMOGLOBULIN VALUES, HEINZ BODIES SEEN ON THE FIRST DAY OF HAEMOLYSIS, FEW SPHEROCYTES\r\n* PLASMA LACTATE LEVELS - INCREASED ( LACTIC ACIDOSIS )\r\n* PLASMA BICARBONATE LEVELS - LOW\r\n* BLOOD SUGAR LEVELS - DECREASED\r\n* SERUM URIC ACID, SERUM LIPIDS ( TRIGLYCERIDES, CHOLESTROL, PHOSPHOLIPIDS ) - ELEVATED\r\n* VLDL , LDL , APOLIPROTEINS B , C & E - INCREASED\r\n* APOLIPROTEINS A & D - NORMAL OR REDUCED\r\n* S. CREATININE LEVELS - NORMAL UNTIL RENAL FUNCTION POOR\r\n* URINE PROTEINS - ABNORMALITY RANGES FROM MICROALBUMINURIA TO FRANK PROTEINURIA.\r\n* BLEEDING TIME - PROLONGED DUE TO IMPAIRED PLATELET AGGREGATION / ADHESION.\r\n* ADMINISTRATION OF GLUCAGON OR EPINEPHRINE CAUSES LITTLE OR NO RISE IN BLOOD GLUCOSE BUT INCREASES LACTATE LEVELS SIGNIFICANTLY.\r\n* CHARACTERISTICS OF INTRAVASCULAR HAEMOLYSIS IS USUALLY PRESENT LIKE - HAEMOGLOBINEMIA, METHAEMALBUMINEMIA, HAEMOGLOBINURIA, AHAPTOGLOBINEMIA & LATER HAEMOSIDERINURIA.\r\n* SERUM ALPHA-FETOPROTEIN - A TUMOR MARKER FOR HEPATOCELLULAR CARCINOMA SHOULD BE CHECKED & FOLLOWED UP IN PATIENTS WITH HEPATIC ADENOMAS.\r\n* ULTRA SOUND ABDOMEN - SHOW INCREASED ECHOGENICITY, ADENOMAS IN LIVER &  RENAL STONE OR NEPHROCALCINOSIS.\r\n* CT SCAN & MRI WITH CONTRAST - MORE SENSITIVE IN DIAGNOSING MALIGNANT CHANGES IN ADENOMAS.\r\n* BONE AGE - ASSESSMENT SHOULD BE PERFORMED FOR A  BASELINE VALUE & THEN PERIODICALLY CHECKED TILL PUBERTY END\r\n* BONE AGE IS DELAYED. LATER ON BONE DENSITY IS ALSO TO BE CHECKED REGULARLY\r\n* GENETIC TESTING - FOR FAMILY SCREENING\r\n* LIVER BIOPSY FOR CONFIRMATION OF DIAGNOSIS & TO EXCLUDE MALIGNANT TRANSFORMATION IN ADENOMAS.', '1', '1', '0', '0', '1', 'HENA OR MEHANDI APPLIED OVER HEAD OR HANDS MAY CAUSE HAEMOLYSIS.\r\nGET FAMILY MEMBERS FOR GENETIC SCREENING', 'M', '0', 'FEMALES GENERALLY CARRIERS, ASYMPTOMATIC. RARELY THOSE HAVING HIGH PROPORTION OF DEFICIENT CELLS DISPLAY SYMPTOMS\r\n* NAPHTHALENE BALL INGESTION MAY CAUSE SEVERE HAEMOLYSIS\r\n* METABOLIC ACIDOSIS MAY CAUSE HAEMOLYSIS\r\n* VIRAL & BACTERIAL INFECTION MAY TRIGGER HAEMOLYSIS\r\n\r\n\"	Hyperlipidemia \r\no	Patients with GSD type Ia typically have very high serum triglyceride levels with modest elevations of total cholesterol and low-density lipoprotein cholesterol and low levels of high-density lipoprotein cholesterol. \r\no	The etiology of this dyslipidemia is thought to be increased hepatic lipogenesis. However, some evidence also indicates that the cause is decreased triglyceride clearance due to diminished hepatic lipoprotein lipase activity. \r\no	Although this lipid profile is considered atherogenic in the general population, patients with GSD type Ia may not have the same risk. Nevertheless, myocardial infarction at a young age or acute pancreatitis warrants attention. \r\no	Compliance with appropriate dietary therapy is the first line of treatment. \r\no	The recommended diet is comprised of 15-20% fats, equally distributed among saturated and nonsaturated, and daily cholesterol intake of less than 200 mg/d. \r\no	This improves the hypertriglyceridemia in most patients and may decrease the total cholesterol level by 18-25%. \r\n\"	Persistent hyperlipidemia \r\no	If hyperlipidemia persists despite maximal dietary measures, initiating a trial of drug therapy is reasonable. \r\no	Reports suggest that fibrates and niacin may decrease triglyceride levels by up to 30%, but this effect may not be sustained long-term. \r\no	Additionally, the use of fish oil supplements (eicosapentaenoic acid, 10 g/1.73 m2/d) has been shown to lower triglyceride levels by an average of 49% when used for a 3-month period. \r\no	Statins and bile acid sequestrant resins are probably contraindicated because they may exacerbate the hypertriglyceridemia. \r\no	An obvious need exists for more long-term studies of drug therapy in this setting. \r\n\"	\r\n\"	Hepatic adenomas \r\no	Single or multiple hepatic adenomas are observed in up to 80% of patients. \r\no	Although they have been seen in patients as young as 3 years, they usually appear during the second or third decade. \r\no	These adenomas bear a remarkable similarity to pharmacologic estrogen-induced hepatic adenomas, and several hypotheses exist about their development mechanism. Mitochondrial B-oxidation of fatty acids is thought to be inhibited by excess malonyl coenzyme A (due to G-6-phosphatase deficiency), which decreases carnitine palmitoyltransferase I and increases extramitochondrial fatty acid oxidation. This process may be significant in oncogenesis. \r\no	Given the pathophysiologic similarity to estrogen-induced hepatic adenomas, affected patients should use oral contraceptive pills with caution or not at all. \r\n\"	\r\n\"	Hepatic adenoma prevention and treatment \r\no	Evidence about using strict dietary control of glucose, lipids, and lactate to prevent adenoma formation and promote regression is conflicting. Reports indicate that many cases may not respond to dietary therapy. \r\no	Monitor hepatic adenomas with biannual or yearly ultrasound examinations. Serum alpha-fetoprotein values should also be measured serially as a potential marker of malignant transformation, which may occur in 11% of adenomas. \r\no	Adenomas may cause symptoms such as pain or vomiting. An acute onset of pain may indicate hemorrhage into the tumor capsule. \r\no	Adenomas that show signs of growth, hemorrhage, necrosis, calcification, or elevated alpha-fetoprotein levels should be referred for definitive diagnosis (ie, via biopsy or resection). \r\no	Once the determination has been made that aggressive therapy is warranted for symptom control, hemorrhage control, or to exclude malignancy, a decision must be made between localized resection or orthotopic liver transplant. A liver transplant has the added benefit of correcting the underlying metabolic defect, but it also means a lifetime of immunosuppression and its associated risks. However, either way, patients require life-long medical therapy. \r\no	Patients must be informed of the potential risks and benefits of each therapy so that they can make the most appropriate decision. \r\n\"	Renal disease \r\no	Renal disease associated with G-6-phosphatase deficiency was previously thought to manifest mainly as renal enlargement upon ultrasound examination or hematuria from uric acid stones. However, the initial change in affected patients has been shown to be hyperfiltration, which is a nephropathy similar to diabetes. \r\no	This increase in the glomerular filtration rate is not observed at birth, but it is present in up to 50% of patients by age 1 year. \r\no	After several years, progressive proteinuria can be observed that sometimes develops into the nephrotic range. This may be found in up to 70% of patients older than 10 years. \r\no	Along with the proteinuria, a progressive decline in creatinine clearance and the onset of hypertension may occur. \r\no	Eventually, dialysis-dependent renal failure occurs approximately 12 years after the first appearance of proteinuria. \r\no	Most deaths from renal failure occur in older patients who did not receive aggressive dietary management from birth or who did not comply with therapy. \r\no	Although several theories have been suggested, the exact mechanism of the hyperfiltration is unknown. \r\n\"	\r\n\"	Renal disease management \r\no	Proper methods to manage associated renal disease are still quite uncertain. \r\no	Probably the most important factor for preventing renal deterioration is patient compliance with a dietary therapy that maintains euglycemia and reduces hyperlipidemia and counterregulatory hormone excess. \r\no	Controlling hyperuricemia helps prevent uric acid stones and uric acid nephropathy. \r\no	If hypertension develops, it should be aggressively controlled to delay the progression of renal damage. \r\no	The main question remains whether angiotensin-converting enzyme inhibitors decrease hyperfiltration and proteinuria and delay the progression or appearance of overt renal failure, as is observed in diabetes. \r\no	A reduction in proteinuria has been observed in a few patients treated on an experimental basis, but no formal trials have been published to answer this question. In the absence of any contraindications, it is probably a reasonable choice in the presence of hypertension. \r\n\"	\r\n\"	Hyperuricemia \r\no	Debate exists regarding when to initiate therapy to treat hyperuricemia. \r\no	Most clinicians begin when an affected patient has an episode of acute gouty arthritis, uric acid nephrolithiasis, or gouty tophi. However, initiating therapy in asymptomatic patients who have serum urate levels greater than 420 µmol/L (7 mg/dL) also may be reasonable. \r\no	Treatment usually consists of a dietary review to ensure compliance and 100-300 mg allopurinol daily. Allopurinol should never be started during an acute attack of gout because it may exacerbate the arthritis. \r\no	Any patient with hyperuricemia should maintain appropriate body weight and limit ethanol consumption. \r\n\"	\r\n\"	Metabolic bone disease \r\no	Osteopenia and osteoporosis are being increasingly identified in patients with G-6-phosphatase deficiency, but the exact mechanism has not been identified. \r\no	One possible cause is poor dietary calcium intake and increased urinary calcium excretion without a concomitant rise in 25-vitamin D, parathyroid hormone, or skeletal alkaline phosphatase. This represents an inappropriate response to a negative calcium balance. \r\no	Compared to age-matched controls, bone mineral content and bone densitometry may be reduced, even in patients as young as 3 years. \r\no	No clinical trials have been performed on the management of osteoporosis in this population, but it would seem prudent to ensure that the prescribed diet contains adequate calcium and vitamin D. Hopefully, future trials will address the question of antiresorptive therapy such as bisphosphonates. \r\nSurgical Care\r\n\"	Gastrostomy feeding tube \r\n\"	\r\no	Placement facilitates overnight, continuous drip feedings. \r\no	Feeding tubes are usually placed shortly after diagnosis, but some clinicians delay placement until age 6-12 months if the diagnosis is made at birth. \r\no	Pay careful attention to ensure a healthy insertion site, and treat any infection early. \r\n\"	Liver resection and transplantation \r\n\"	\r\no	Symptomatic hepatic adenomas or possible malignant mass transformation may require resection or liver transplant. \r\no	On occasion, liver transplantation has been advocated when maximal dietary therapy fails to give metabolic control and normal growth. This is controversial because of the life-long risks incurred by immunosuppression. \r\no	Available data indicate that patients with GSD type Ia who received a liver transplant have normal metabolic balance, which allows catch-up growth and improves quality of life. \r\no	Evidence indicates that renal disease (focal segmental glomerulosclerosis) is not prevented or corrected by liver transplantation. \r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('639', 'HYPERCALCEMIA', '0', 'CAUSES :\r\n\r\n1. PARATHYROID RELATED\r\n\r\nA. PRIMARY HYPERPARATHYROIDISM\r\n- SOLITARY ADENOMAS\r\n- GLAND HYPERPLASIA\r\n- CANCER OF PARATHYROID GLAND\r\n- MULTIPLE  ENDOCRINE NEOPLASIA\r\n\r\nB. LITHIUM THERAPY\r\nC. FAMILIAL HYPOCALCIURIC HYPERCALCEMIA\r\n\r\n2. MALIGNANCY RELATED\r\n\r\n- SOLID TUMOR WITH METASTASES ( BREAST, MULTIPLE MYELOMA, LYMPHOMAS ) ASSOCIATED WITH LOCAL OSTEOLYTIC HYPERCALCEMIA\r\n- SOLID TUMOR WITH HUMORAL MEDIATION OF HYPERCALCEMIA ( SQUAMOUS CELL CARCINOMA OF LUNG,  HEAD, NECK, EOSOPHAGUS & ADENOCARCINOMA OF BREAST, KIDNEY, BLADDER, PANCREAS & OVARY )\r\n- HEMATOLOGIC MALIGNANCIES ( MULTIPLE MYELOMA , LYMPHOMA , LEUKEMIA )\r\n\r\n3. VITAMIN D RELATED \r\n- VITAMIN D INTOXICATION\r\n- HIGH 1,25 ( OH )2D ; SARCOIDOSIS & OTHER GRANULOMATOUS DISEASES\r\n- IDIOPATHIC HYPERCALCEMIA OF INFANCY\r\n\r\n4. ASSOCIATED WITH HIGH BONE TURNOVER\r\n- HYPERTHYROIDISM\r\n- IMMOBILIZATION\r\n- THIAZIDES\r\n- VIT A INTOXICATION\r\n\r\n5. ASSOCIATED WITH RENAL FAILURE\r\n- SEVERE SECONDARY HYPERPARATHYROIDISM\r\n- ALUMINUM INTOXICATION\r\n- MILK ALKALI SYNDROME', '* FRACTIONAL EXCRETION OF CALCIUM - DECREASED ( <1% ) IN FAMILIAL HYPOCALCIURIC HYPERCALCEMIA & INCREASED ( >2% ) IN PRIMARY HYPERPARATHYROIDISM\r\n* SERUM PTH LEVELS - SUPPRESSED IN HYPERCALCEMIA OF MALIGNANCY & HIGH IN HYPERPARATHYROIDISM\r\n* SERUM PTH RELATED PEPTIDE ( PTHRP ) - ALWAYS HIGH IN HYPERCALCEMIA OF MALIGNANCY\r\n* SERUM & URINE PROTEIN ELECTOPHORESIS, BONE SCAN & SOME TIMES BONE BIOPSY TO EXCLUDE LYMPHOMAS, LEUKEMIA ETC.\r\n* SERUM CALCIUM - INCREASED\r\n* SERUM PHOSPHATE - USUALLY LOW BUT MAY BE NORMAL, ESPECIALLY IF RENAL FAILURE HAS DEVELOPED\r\n* URINE CALCIUM - INCREASED\r\n* VIT D ASSAY OR 25-HYDROXYVITAMIN D LEVELS - TO EXCLUDE VIT D DEFICIENCY. LEVELS SHOULD BE > 20 NG / ML\r\n\r\n', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: Treatment depends on the severity of symptoms and the underlying cause. \r\n\"	Volume expansion and saline diuresis\r\no	Volume depletion results from uncontrolled symptoms leading to decreased intake and enhanced renal sodium loss. This tends to exacerbate or perpetuate the hypercalcemia by increasing Na+ reabsorption in the thick ascending limb of the loop of Henle (TALH). Thus, appropriate volume repletion with isotonic sodium chloride solution is an effective short-term treatment for hypercalcemia. \r\no	Once volume is restored, simultaneous administration of loop diuretics blocks Na+ and calcium reabsorption in the TALH. \r\no	Replacing ongoing sodium, potassium, chloride, and magnesium losses is important if prolonged sodium chloride and loop diuretic therapy is contemplated.\r\n\"	Mobilization \r\no	Immobilization aggravates hypercalcemia. \r\no	Whenever possible, weightbearing mobilization should be encouraged.\r\n\"	Reduction of gastrointestinal calcium absorption \r\no	Reduction of dietary calcium and vitamin D intake is effective for treating hypercalcemia due to increased intestinal calcium absorption (eg, in idiopathic infantile hypercalcemia, ie, Williams syndrome). \r\no	In vitamin D toxicity or extrarenal synthesis of 1,25(OH) D3 (eg, in sarcoidosis), prednisone may help reduce plasma calcium levels by reducing intestinal calcium absorption. \r\no	Oral phosphate also can be used to form insoluble calcium phosphate in the gut.\r\n\"	Inhibition of bone resorption \r\no	Bisphosphonates inhibit osteoclastic bone resorption and are effective in the treatment of hypercalcemia due to conditions causing increased bone resorption and malignancy-related hypercalcemia. \r\no	Pamidronate and etidronate can be given intravenously, while risedronate and alendronate may be effective as oral therapy. \r\no	Calcitonin can be given intramuscularly or subcutaneously, but it becomes less effective after several days of use. \r\no	Mithramycin blocks osteoclastic function and can be given for severe malignancy-related hypercalcemia. It has significant hepatic, renal, and marrow toxicity.\r\n\"	Dialysis: Peritoneal or hemodialysis against calcium-free or lower calcium concentration dialysate solution is highly effective in lowering plasma calcium levels.\r\nSurgical Care: Surgical care is directed toward reversing the underlying cause of hypercalcemia or repairing the orthopedic damage. \r\n\"	Prolonged hypercalcemia due to hyperparathyroidism may warrant surgical neck exploration and removal of one or more parathyroid glands. This is particularly appropriate if evidence of nephrolithiasis, osteoporosis, reduction of renal function, neuromuscular symptoms, or radiographic bone disease is present.\r\n\"	Hypercalcemia due to malignancy, especially if due to a tumor that is producing PTHrP, may require surgical resection of the tumor.\r\n\"	Orthopedic complications of prolonged hypercalcemia (eg, osteoporosis), complications of Paget disease, or complications of bony metastases may require orthopedic or neurosurgical intervention.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('695', 'MYOCARDIAL INFARCTION', '0', 'D.D. :\r\n* ANGINA PECTORIS\r\n* PERICARDITIS\r\n* DISSECTING AORTIC ANEURYSM\r\n* MASSIVE PULMONARY EMBOLISM\r\n* AC. PANCREATITIS\r\n* AC CHOLECYSTITIS\r\n* PRECORDIAL CATCH\r\n* AC ANXIETY\r\n* TRACHEITIS\r\n* MYCOPLASMA PNEUMONIA\r\n* PERICARDIAL FAT NECROSIS\r\n* ESOPAHGITIS\r\n* DA COSTA SYNDROME\r\n* PEPTIC ULCER\r\n* TIETZE SYNDROME', '* TLC & ESR, CPK - MB , SGOT - RAISED\r\n* E.C.G. - RAISED ST SEGMENT ( > 1 MM ) IN TWO CONTIGUOUS LEADS OR RECENT LBBB PATTERN SEEN IN STEMI ( ST-SEGMENT ELEVATED M.I. ) & ST DEPRESSION OR T-WAVE INVERSION IN UNSTABLE ANGINA OR NSTEMI ( NON ST-SEGMENT ELEVATION M.I. ) \r\n* TROPONIN - I & T TEST - POSITIVE\r\n* ECHOCARDIOGRAPHY - HYPOKINESIA IN THE AFFECTED SEGMENT\r\n* MUGA TEST - POOR PERFUSION IN THE AFFECTED AREA.\r\n* URINE MYOGLOBULIN LEVELS - RISE WITHIN 1-4 HRS. HIGHLY SENSITIVE BUT NOT SPECIFIC\r\n* BNP ( BRAIN NATRIURETIC PEPTIDE ) - IS AN INDEPENDENT PREDICTOR OF MORTALITY IN NSTEMI.', '1', '0', '0', '1', '0', 'DISEASE INFLUENCING FACTORS : DIET, LIFE STYLE, ENVIRONMENT, SMOAKING, ALCOHOL, DRUG ABUSE & LACK OF EXERCISE, POSITIVE FAMILY HISTORY, HYPERTENSION, DIABETES MELLITUS & CHR RENAL DISEASE', 'B', '0', 'Medical Care: Initial therapy for acute MI is directed toward restoration of perfusion in order to salvage as much of the jeopardized myocardium as possible. This may be accomplished through medical or mechanical means, such as angioplasty or coronary artery bypass grafting. \r\nFurther treatment is based on (1) restoration of the balance between the oxygen supply and demand to prevent further ischemia, (2) pain relief, and (3) prevention and treatment of any complications that may arise. \r\n\"	Thrombolytic therapy has been shown to improve survival rates in patients with acute MI if administered in a timely fashion in the appropriate group of patients. If PCI capability is not available or will cause a delay greater than 90 minutes, then the optimal approach is to administer thrombolytics within 12 hours of onset of symptoms in patients with ST-segment elevation greater than 0.1 mV in 2 or more contiguous ECG leads, new left bundle-branch block (LBBB), or anterior ST depression consistent with posterior infarction. Tissue plasminogen activator (t-PA) is superior to streptokinase in achieving a higher rate of coronary artery patency; however, the key to efficacy lies in the speed of the delivery of therapy. Recent trials show a high patency rate if a IIb/IIIa receptor antagonist is combined with a half dose of a thrombolytic agent as the initial reperfusion strategy. The reduced dose of a thrombolytic agent combined with a potent platelet inhibitor may prove to be the preferred method for medical\r\nreperfusion. Larger clinical trials are pending. \r\n\"	Aspirin and/or antiplatelet therapy\r\no	Aspirin has been shown to decrease mortality and re-infarction rates after MI. Administer aspirin immediately, which the patient should chew if possible upon presentation. Continue aspirin indefinitely unless an obvious contraindication, such as a bleeding tendency or an allergy, is present. Clopidogrel may be used as an alternative in cases of a resistance or allergy to aspirin. Recent data from the CLARITY trial (CLopidogrel as Adjunctive ReperfusIon Therapy Thrombolysis in Myocardial Infarction [TIMI] 28) suggest that adding clopidogrel to this regimen is safe and effective. The clopidogrel dose used was 300 mg.\r\no	Administer a platelet glycoprotein (GP) IIb/IIIa-receptor antagonist, in addition to acetylsalicylic acid and unfractionated heparin (UFH), to patients with continuing ischemia or with other high-risk features and to patients in whom a percutaneous coronary intervention (PCI) is planned. Eptifibatide and tirofiban are approved for this use. Abciximab also can be used for 12-24 hours in patients with unstable angina or NSTEMI in whom a PCI is planned within the next 24 hours.\r\n\"	Beta-blockers reduce the rates of reinfarction and recurrent ischemia and possibly reduce the mortality rate if administered within 12 hours after MI. Administer routinely to all patients with MI unless a contraindication is present. \r\n\"	Heparin (and other anticoagulant agents) has an established role as an adjunctive agent in patients receiving t-PA but not with streptokinase. Heparin is also indicated in patients undergoing primary angioplasty. Little data exist with regard to efficacy in patients not receiving thrombolytic therapy in the setting of acute MI. Low-molecular-weight heparins (LMWHs) have been shown to be superior to UFHs in patients with unstable angina or NSTEMI.\r\n\"	Nitrates have no apparent impact on mortality rate in patients with ischemic syndromes. Their utility is in symptomatic relief and preload reduction. Administer to all patients with acute MI within the first 48 hours of presentation, unless contraindicated (ie, in RV infarction).\r\n\"	ACE inhibitors reduce mortality rates after MI. Administer ACE inhibitors as soon as possible as long as the patient has no contraindications and remains in stable condition. ACE inhibitors have the greatest benefit in patients with ventricular dysfunction. Continue ACE inhibitors indefinitely after MI. Angiotensin-receptor blockers may be used as an alternative in patients who develop adverse effects, such as a persistent cough, although initial trials need to be confirmed.\r\nSurgical Care: \r\n\"	Percutaneous coronary intervention\r\no	PCI is the treatment of choice in most patients with STEMI, assuming a door to needle time of less than 90 minutes. PCI provides greater coronary patency (>96% thrombolysis in myocardial infarction [TIMI] 3 flow), lower risk of bleeding, and instant knowledge about the extent of the underlying disease. Studies have shown that primary PCI has a mortality benefit over thrombolytic therapy. \r\no	The choice of primary PCI should be individualized to each institution and to the patient\'s presentation and timing. \r\no	The widespread use of stenting and adjunctive IIb/IIIa therapy are improving the results of primary PCI. A recently published trial showed that, in patients with acute MI, coronary stenting and abciximab lead to a greater degree of myocardial salvage and a better clinical outcome than fibrinolysis with thrombolytic therapy. Improvement of long- and short-term outcomes, however, depends highly on the speed with which reperfusion is achieved.\r\no	Primary PCI is also the treatment of choice in patients with cardiogenic shock, patients in whom thrombolysis failed, and those with high risk of bleeding or contraindications to thrombolytic therapy.\r\no	Only an experienced operator should perform primary PTCA, and PTCA should be performed only where the appropriate facilities are available. Operators should have at least 75 cases per year, while the center should perform at least 200 cases per year as per the recommendations of the ACC.\r\n\"	Emergent or urgent coronary artery graft bypass surgery is indicated in patients in whom angioplasty fails and in patients who develop mechanical complications such as a VSD, LV, or papillary muscle rupture.\r\nDiet: \r\n\"	Initially, keep the patient on nothing by mouth (NPO) until his or her condition has been stabilized and treated. Following initial therapy and admission, a dietitian should instruct the patient regarding appropriate diet, as recommended by the AHA.\r\n\"	A low-salt, low-fat, and low-cholesterol diet is generally recommended.\r\nActivity: \r\n\"	Confine patients to bed rest to minimize oxygen consumption until reperfusion and initial therapy are complete. This usually lasts about 24-48 hours; after that, the patient\'s activity may be accelerated slowly as tolerated and as the clinical situation allows.\r\n\"	Initiate cardiac rehabilitation prior to discharge.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. SALICYLATES :\r\n\r\n- ASPIRIN\r\n\r\n2. VASODILATORS :\r\n\r\n- NITROGLYCERIN\r\n\r\n3. ANALGESICS :\r\n\r\n- MORPHINE SULPHATE\r\n\r\n4. ANTICOAGULANTS :\r\n\r\n- HEPARINE\r\n- LOW MOLECULAR WEIGHT HEPARIN : ENOXAPARIN\r\n\r\n5. THROMBOLYTICS :\r\n\r\n- ALTEPLASE\r\n- STREPTOKINASE\r\n- RETEPLASE\r\n- ANISTREPLASE\r\n\r\n6. BETA BLOCKERS :\r\n\r\n- METOPROLOL\r\n- ESMOLOL\r\n\r\n7. ACE INHIBITORS :\r\n\r\n- CAPTOPRIL\r\n\r\n8. PLATELET AGGREGATION INHIBITORS :\r\n\r\n- ABCIXIMAB\r\n- TIROFIBAN\r\n- EPTIFIBATIDE\r\n\r\n\r\nPROGNOSIS :\r\n\r\nPTS WITH REDUCED LV FUNCTION ( EF < .30 ) AT LEAST 1 MTHFOLOWING ACUTE MI, OR WHO HAVE HEMODYNAMICALLY SIGNIFICANT VENTRICULAR ARRHYTHMIAS MORE TAHN 2 DAYS AFTER M.I. , HAVE INDICATION FOR IMPLANTABLE CARDIOVERTER-DEFIBRILLATOR ( ICD ) DUE TO HIGH RISK OF SUDDEN CARDIAC DEATH FROM MALIGNANT VENTRICULAR ARRHYTHMIAS.\r\n\r\nCOMPLICATIONS :\r\n\r\n- VENTRICULAR SEPTAL RUPTURE\r\n- MITRAL REGURGITATION\r\n- CARDIAC RUPTURE\r\n- PSEUDOANEURYSM\r\n- CARDIOGENIC SHOCK\r\n- RV FAILURE FOLLOWING INFERIOR WALL INFACTION\r\n- VENTRICULAR ANEURYSM\r\n- ARRHYTHMIAS\r\n- PERICARDITIS\r\n\r\nALTERNATIVE DRUGS\r\n. Thrombolytics\r\n. Tenecteplase or reteplase\r\n. Beta-blockers for acute arrhythmia\r\n. Atenolol 5 mg IV over 5 minutes. Follow with a second dose 10 minutes later. Follow with 50 mg po in 10 minutes after the 2nd IV dose. Then q12h for at least 7 days\r\n\r\nPATIENT MONITORING\r\n• Determined by needs of patient\r\n• Early intervention if any one of the following: recurrent chest pain, CHF, hemodynamic instability, sustained\r\nV-tach, PCI within 6 months, prior CABG\r\n\r\nPREVENTION/AVOIDANCE\r\n• Avoid risk factors\r\n• Aspirin 81 mg/day may be helpful\r\n• Clopidogrel 75 mg day\r\n\r\nPOSSIBLE COMPLICATIONS\r\n• Congestive heart failure\r\n• Cardiogenic shock\r\n• Myocardial rupture\r\n• Left ventricular aneurysm\r\n• Left ventricular thrombus and peripheral embolism\r\n• Deep venous thrombosis and pulmonary embolism\r\n• Pericarditis\r\n• Dysrhythmias\r\n• Mitral regurgitation\r\n• Ventricular septal defect\r\n• Dressler’s syndrome\r\n• Cardiac arrest\r\n• Death', NULL, NULL, NULL, NULL, '1'),
('718', 'PANCREATITIS , ACUTE', '0', 'D.D. :\r\n\r\n- CHOLANGITIS\r\n- CHOLECYSTITIS\r\n- CHOLEDOCHOLITHIASIS\r\n- CHOLELETHIASIS\r\n- COLON CANCER, ADENOCARCINOMA\r\n- COLONIC OBSTRUCTION\r\n- DUODENAL OBSTRUCTION\r\n- GASTRIC CANCER\r\n- GASTRIC ULCER\r\n- IRRITABLE BOWEL SYNDROME\r\n- MYOCARDIAL INFACTION\r\n- PANCREATIC CANCER\r\n- PANCREATITIS, CHRONIC\r\n- PNEUMONIA, BACTERIAL\r\n- PNEUMONIA, COMMUNITY ACQUIRED\r\n\r\n--------------------------------------------------------------------------\r\n\r\nCAUSES :\r\n\r\n- BILIARY TRACT DISEASES & BILIARY MICROLITHIASIS ( 40% )\r\n- ALCOHOL ( 35% )\r\n- POST ERCP\r\n- TRAUMA\r\n- DRUGS DEFINITELY ASSOCIATED LIKE AZATHIOPRINE, SULPHONAMIDES, SULINDAC, TETRACYCLINE, VALPROIC ACID, DIDANOSINE, METHYLDOPA, ESTROGENS, FUROSEMIDE, 6-MERCAPTOPURINE, PENTAMIDINE, 5-AMINOSALICYLIC ACID COMPDS., CORTICOSTEROIDS & OCTREOTIDE\r\n\r\n- DRUGS PROBABLY ASSOCIATED LIKE CHLOROTHIAZIDE, HYDROCHLOROTHIAZIDE, METHANDIENONE, METRONIDAZOLE, NITROFURANTOIN, PHENFORMIN, PIROXICAM, PROCAINAMIDE, COLASPASE, CHLORTHALIDONE, COMBINATION CANCER CHEMOTHERAPY DRUGS, CIMETIDINE, CISPLATIN, CYTOSINE ARABINOSIDE, DIPHENOXILATE, ETHACRYNIC ACID\r\n\r\n- INFECTIONS LIKE VIRAL, BACTERIAL & ASCARIASIS, AIDS\r\n- HEREDITARY PANCREATITIS\r\n- HYPERCALCEMIA\r\n- DEVELOPMENTAL ANOMALY OF PANCREAS\r\n- HYPERTRIGLYCERIDEMIA\r\n- TUMORS\r\n- TOXINS LIKE ORGANOPHOSPHOROUS COMPDS, SCRPION BITE\r\n- POSTOPERATIVE\r\n- VASCULAR ANOMALIES', 'OTHER TESTS - \r\n* SERUM ISOAMYLASE, SERUM LIPASE & SERUM TRYPSIN INCREASED.\r\nURINARY ( AMYLASE / CREATININE CLEARANCE ) INCREASED.\r\n* RADIONUCLEOTIDE SCANNING\r\n* LEUKOCYTOSIS & HYPERGLYCEMIA, HYPOCALCEMIA ( 25% ) , HYPERBILIRUBINEMIA ( 10% ), LFT TRASIENTLY INCREASAED. MARKED INCREASE LDH LEVELS SHOW POOR PROGNOSIS.\r\n* HYPERTRIGLYCERIDEMIA - 15 - 20%\r\n* LFT - TO RULE OUT GALL BLADDER ASSOCIATED PANCREATITIS - SGPT > 150 SUGGESTS GALL STONE PANCREATITIS & MORE FULMINANT DISEASE COURSE \r\n* C-REACTIVE PROTEIN - HIGHER LEVELS SHOW POOR PROGNOSIS WITH PROPENSITY TOWARDS ORGAN FAILURE\r\nIMAGING\r\n. Acute pancreatitis\r\n. Plain film of abdomen - signs of ileus\r\n. Chest x-ray - pleural effusion\r\n. Ultrasound/CT scan of abdomen/MRI\r\n. Endoscopic retrograde cholangiopancreatography (ERCP)\r\nDIAGNOSTIC PROCEDURES\r\n. Acute pancreatitis\r\n. CT guided aspiration of necrotic areas\r\n. ERCP for common duct stone removal', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: The medical management of mild acute pancreatitis is relatively straightforward. The patient is kept NPO (non per os, ie, nothing by mouth), and intravenous fluid hydration is provided. Analgesics are administered for pain relief. Antibiotics are generally not indicated. If ultrasonograms show evidence of gallstones and if the cause of pancreatitis is believed to be biliary, a cholecystectomy should be performed during the same hospital admission. Feeding should be introduced enterally as the patient\'s anorexia and pain resolves. \r\nIn contrast, patients with severe acute pancreatitis require intensive care. Within hours to days, a number of complications (eg, shock, pulmonary failure, renal failure, gastrointestinal bleeding, multiorgan system failure) may develop. The goals of medical management are to provide aggressive supportive care, decrease inflammation, limit infection or superinfection, and identify and treat complications as appropriate. \r\n\"	Fluids: Patients are kept NPO and require intravenous hydration. Especially in the early phase of the illness, aggressive fluid resuscitation is critically important. This cannot be overemphasized. There is no universal consensus showing a definitive advantage of one type of fluid over another type. Resuscitation should be enough to maintain hemodynamic stability, which is usually an initial several liter fluid bolus followed by 250-500 cc/h continuous infusion. Careful attention should be paid to signs of overhydration, such as pulmonary edema causing hypoxia.\r\n\"	Antibiotics \r\no	Antibiotics, usually drugs of the imipenem class, should be used in any case of pancreatitis complicated by infected pancreatic necrosis. They should not be given routinely for fevers, especially early in the disease course, as this symptom is almost universally secondary to the inflammatory response and not an infectious process. \r\no	Several controlled trials have evaluated the role of empiric antibiotics in patients with severe acute necrotizing pancreatitis for infectious prophylaxis. Antibiotics should not be used as prophylaxis in patients with mild pancreatitis. \r\no	One such trial evaluated the role of imipenem/cilastatin initiated at admission to prevent infected pancreatic necrosis. This drug combination penetrates the pancreatic parenchyma and reduces the risk of intra-abdominal infection. This showed some benefit in preventing infectious complications. Unfortunately, fungal superinfection tends to develop later in the clinical course, although this risk is probably overinflated. \r\no	A randomized trial failed to show any benefit of ciprofloxacin and metronidazole in preventing infectious complications, and thus this drug combination is not routinely used for prophylaxis in this disease. \r\no	The bottom line is that antibiotic prophylaxis in severe pancreatitis is controversial. If one does decide to use antibiotic prophylaxis in patients admitted with severe acute pancreatitis, they should be placed on drugs of the imipenem class.\r\n\"	ERCP: If the imaging and laboratory study findings are consistent with severe acute gallstone pancreatitis that is not responding to supportive therapy or with ascending cholangitis with worsening signs and symptoms of obstruction, early ERCP with sphincterotomy and stone extraction is indicated.\r\n\"	Nutrition \r\no	Early initiation of enteral nutritional supplementation and maintenance of a positive nitrogen balance is important in patients with severe pancreatitis. \r\no	Theoretical considerations regarding the ability of the enterocyte to maintain a barrier against bacterial translocation favor nasojejunal feedings. Thus, in all patients admitted to the ICU, nasojejunal feedings should be attempted beginning at admission. For patients with mild acute pancreatitis, nasojejunal feedings can be avoided unless patients are unable to tolerate oral intake for over 1 week. \r\no	Depending on the situation, TPN, which has been shown to reduce mortality rates, may be necessary. However, TPN should generally be reserved as a second-line therapy behind enteral feeding.\r\n\"	Emerging treatments \r\no	Although the role cytokines play in systemic inflammatory response syndrome appears important, a recent large clinical trial of lexipafant, a platelet-activating factor antagonist, has shown no benefit in patients with severe acute pancreatitis. \r\no	Because multiple pathways are involved in the inflammatory response, further research is needed in order to define which cytokine or combination of cytokines should be targeted to ameliorate the complications of acute pancreatitis.\r\n\"	Clinical vigilance \r\no	In the following weeks (to months) after presentation, the physician\'s attention shifts to developing signs of intra-abdominal infection, pancreatic pseudocyst, intra-abdominal hemorrhage, colon perforation, obstruction or fistulization, and multiorgan system failure. \r\no	The clinician cannot rely on clinical grounds alone to differentiate infected and sterile pancreatic necrosis. When clinical signs of infection or a systemic inflammatory response is present in the setting of necrotizing pancreatitis, CT-guided needle aspiration is indicated.\r\nSurgical Care: Surgical intervention, whether by minimally invasive or conventional open techniques, is indicated when an anatomical complication amenable to a mechanical solution is present. Depending on the situation and local expertise, this may require the talents of an interventional radiologist, interventional endoscopist, and/or surgeon (alone or in combination). \r\n\"	Pancreatic duct disruption: Damage to the pancreatic ductal system may allow pancreatic juice to leak from the gland. The sudden development of hypocalcemia or a rapid increase in retroperitoneal fluid on CT scan is suggestive of this condition.\r\no	When imaging studies contain corroborating data, the condition is initially managed by percutaneous placement of a drainage tube into the fluid collection under the guidance of ultrasonography or CT scanning. Fluid amylase or lipase levels in the ten thousands strongly suggest the presence of a ductal disruption.\r\no	In the appropriate clinical setting, endoscopic retrograde pancreatography confirms the diagnosis and provides a treatment option. Transpapillary stent placement or, preferably, placement of a 6F nasopancreatic tube attached to an external bulb suction device can successfully treat leaks by removing the sphincter tone and changing the dynamics of fluid flow in favor of ductal healing. Occasionally, leaks are associated with downstream stenoses that are also amenable to endoscopic treatment techniques.\r\no	Refractory cases may require surgery. If the persistent leak is present in the tail of the gland, a distal pancreatectomy is preferred. If the leak is in the head of the gland, a Whipple procedure is the operation of choice.\r\n\"	Pseudocysts: By definition, peripancreatic fluid collections persisting for more than 4 weeks are termed acute pseudocysts. Pseudocysts lack an epithelial layer and, thus, are not considered true cysts. In addition, the term cyst is also a misnomer, as most of these collections are filled with necrotic debris and not fluid. A more descriptive term for these collections may be organized necrosis. Most of these can be followed clinically. When pseudocysts are symptomatic (ie, associated with pain, bleeding, or infection) or are larger than 7 cm and are rapidly expanding in an acutely ill patient, intervention is indicated. The following therapeutic approaches may be implemented, depending on anatomical relationships and the duration of the natural history of the complication.\r\no	Percutaneous aspiration: In selected patients with very large fluid collections, percutaneous aspiration of pancreatic pseudocysts is a reasonable approach. Even though treatment failures are common when the pseudocyst communicates with the pancreatic ductal system, percutaneous drainage serves as a temporizing measure that may later lead to successful endoscopic or surgical intervention. Often, an infected pseudocyst (which by definition is regarded as a pancreatic abscess) can be successfully managed by percutaneous drainage.\r\no	Endoscopic techniques: Pseudocysts may be managed endoscopically by transpapillary or transmural techniques. Transpapillary drainage requires the main pancreatic duct to communicate with the pseudocyst cavity, ideally in the head or body of the gland. The proximal end of the stent is placed into the cyst cavity, and the stent should be smaller than the diameter of the pancreatic duct. The technical success rate is 83%, with a complication rate of 12%. Generally, however, pancreatic stents are difficult to monitor, prone to obstruction, and associated with an increased risk of infection and ductal injury. \r\no	Some noncommunicating pseudocysts may be amenable to transmural enterocystostomy. Technical success requires a mature cyst that bulges into the foregut, and the distance from the lumen to the cyst cavity should be less than 1 cm. The success rate is 85%, with a complication rate of 17%. The transduodenal approach is associated with fewer complications and recurrences than the transgastric approach.\r\no	Surgical cyst-enterostomy: Based on prospective data from the 1970s, surgery is recommended for persistent, large (>7 cm), pancreatic pseudocysts because complications developed in 41% of patients, 13% of whom died. Internal pseudocyst enteric anastomosis became the standard of care, with an operative mortality rate of 3-5%. Recently, this dogma has been challenged by 2 retrospective studies in which patients with smaller asymptomatic pseudocysts (ie, <5 cm) rarely developed complications (<10%).\r\n\"	Infected pancreatic necrosis: Surgery is recommended when large areas of the pancreas are necrotic and percutaneous CT-guided aspiration demonstrates infection based on a positive Gram stain result. Antibiotic therapy alone is not sufficient to achieve a cure. Aggressive surgical debridement and drainage is necessary to remove dead tissue and to clear the infection.\r\n\"	Pancreatic abscesses: Pancreatic abscesses generally occur late in the course of pancreatitis. Many of these respond to percutaneous catheter drainage and antibiotics. Those that do not respond require surgical debridement and drainage.\r\nConsultations: The most effective and soundly based treatment plan for any disorder is one aimed at the mechanism responsible for the development of the disorder. With that axiom in mind, treatment of the patient must address the underlying cause of pancreatitis. \r\n\"	Treatment of patients with alcohol-induced pancreatitis should go beyond the physical manifestations of this disease and address the underlying psychological addiction to alcohol. Simply telling patients they must stop drinking alcohol is not satisfactory. Successful treatment often requires the involvement and expertise of a chemical dependency counselor. The author favors in-hospital consultation with all patients admitted with alcoholic pancreatitis.\r\n\"	Patients with hypertriglyceridemic- or hypercalcemic-induced pancreatitis require consultation with an endocrinologist. Rarely, such patients require surgical intervention for treatment of hyperparathyroidism or control of hyperlipidemia refractory to medical therapy.\r\n\"	It is optimal for patients admitted with gallstone pancreatitis to have a cholecystectomy prior to discharge and not, for example, scheduled for a later date as an outpatient. Patients discharged with gallstone pancreatitis without a cholecystectomy are at high risk for recurrent bouts of pancreatitis. \r\n\"	Patients with gallstones or microlithiasis revealed on imaging studies should have a surgical consultation for gallbladder removal. Because microlithiasis is the most common cause of idiopathic pancreatitis, a patient with recurrent idiopathic pancreatitis should undergo cholecystectomy before procedures associated with a higher risk of complications (eg, ERCP) are performed.\r\n\"	Patients with medication-induced acute pancreatitis may benefit from clinical pharmacology consultation during their hospitalization to maximize their therapeutic regimen.\r\nDiet: General guidelines for nutritional support of patients with acute pancreatitis include the following: \r\n\"	In patients with mild uncomplicated pancreatitis, no benefit is observed from nutritional support, and the energy (caloric) intake received with intravenous dextrose 5% in water (D5W) suffices. Oral feedings should be initiated once the patient\'s pain and anorexia resolve.\r\n\"	In patients with moderate-to-severe pancreatitis, begin nutritional support early in the course of management, as soon as stabilization of fluid and hemodynamic parameters permits. Optimally, nasojejunal feedings with a low-fat formulation should be initiated at admission. The success of nasogastric tube feedings has also recently been compared to nasojejunal feedings in one randomized study. The study showed equivalent outcomes for patients with severe pancreatitis fed with nasogastric feedings compared with nasojejunal feedings. \r\n\"	However, TPN may be required in patients who are unable to maintain their caloric needs with enteral nutrition or because adequate jejunal access cannot be maintained. TPN should include fat emulsions in amounts sufficient to prevent essential fatty acid deficiency. \r\n\"	If surgery is required for diagnosis or complications of the disease, place a feeding jejunostomy at the time of the operation. Use a low-fat formula.\r\n\"	Begin oral feedings once abdominal pain has resolved and the patient regains appetite. The diet should be low in fat and protein. A recent prospective, randomized study showed that initiating feeding with a low-fat solid diet was as well tolerated as initiating feeding with a clear liquid diet, but it did not result in a shorter length of stay.\r\n\r\nDRUG TREATMENT :\r\n\r\n1. ANALGESICS :\r\n\r\n- ACETAMINOPHEN\r\n- ACETAMINOPHEN WITH PROPOXYPHENE\r\n- TRAMADOL\r\n- MEPERIDINE\r\n\r\n2. ANTIBIOTICS :\r\n\r\n- IMIPENEM & CILASTATIN OR ANY OTHER UNIVERSALLY SAFE ANTIBIOTIC', NULL, NULL, NULL, NULL, '1'),
('767', 'ARTHRITIS, RHEUMATOID', '0', 'CAUSES:  Antibody-complement complex results in intra-articular infl ammation.\r\n\r\n--------------------------------------------------------------------------\r\nDIFFERENTIAL DIAGNOSIS:\r\n* Sjögren syndrome \r\n* sarcoidosis\r\n* gout\r\n* polymyositis,\r\n* erosive osteoarthritis\r\n* seronegative polyarthritis\r\n* vasculitis\r\n*  pseudogout\r\n*  inflammatory bowel disease\r\n* hypersensitivity reactions\r\n* Reiter syndrome\r\n* Behçet syndrome\r\n* psoriatic arthritis\r\n* systemic lupus erythematosus\r\n* Lyme disease\r\n* scleroderma\r\n* chronic infection\r\n* occult malignancy\r\n* Early wrist symptoms not likely in Osteoarthritis.', 'BLOOD : NORMOCYTIC, NORMOCHROMIC ANEMIA, LEUCOCYTOSIS / LEUKOPENIA, RAISED ESR, EOSINOPHELIA ( IN SEVERE CASE).\r\n* R.A. FACTOR : IGM ANTIBODIES AGAINST FC PORTION OF IGG - RAISED \r\n* CERULOPLASMIN, C- REACTIVE PROTEIN - INCREASED\r\n* TC-99 BIPHOSPHONATE BONE SCAN\r\n* MRI.\r\n* RADIOLOGY : SOFT TISSUE SWELLING & JOINT EFFUSION, SYMMETRICAL INVOLVEMENT, JUXTA ARTICULAR OSTEOPENIA, DESTRUCTION OF ARTICULAR CARTILAGE & BONE.\r\nSYNOVIAL FLUID : WBC > 2000/ CU MM , 75 % POLY ( INFLAMMATORY ARTH.), DECREASED C-3, C-4 LEVELS.\r\n* ANTI-CYCLIC CITRULLINATED PEPTIDE ( ANTI-CCP ) - POSITIVE: FOUND IN RELATION TO JOINT INVOLVEMENT WITH RADIOLOGICAL DAMAGE IN EARLY RHEUMATOID ARTHRITIS. THE TEST IS SUPERIOR TO OTHER AVAILABLE TESTS.', '0', '0', '0', '0', '0', '', 'B', '0', 'Medical Care: Optimal care of patients with RA requires an integrated approach of pharmacologic and nonpharmacologic therapies. \r\n\"	Nonpharmacologic\r\no	Education is important in helping patients to understand their disease and to learn how to cope with its consequences. \r\no	Physiotherapy and physical therapy are initiated to help improve and sustain range of motion, increase muscle strength, and reduce pain. \r\no	Occupational therapy is initiated (1) to help patients to use joints and tendons efficiently without stressing these structures, (2) to help patients decrease tension on the joints through the use of specially designed splints, and (3) to help patients to cope with daily life through the use of adaptations to the patients\' environment and the use of different aids. \r\no	Orthopedic measures include reconstructive and replacement-type surgical measures.\r\n\"	Pharmacologic\r\no	The most important measure to successfully treat RA is the use of DMARDs. DMARDs can retard or prevent disease progression and, thus, joint destruction and subsequent loss of function. \r\no	Successful DMARD therapy may eliminate the need for other anti-inflammatory or analgesic medications. \r\no	Until the full action of DMARDs takes effect, anti-inflammatory or analgesic medications may be required as bridging therapy to reduce pain and swelling. \r\no	DMARDs can be classified into xenobiotic and biologic agents. \r\no	Xenobiotic agents \r\n\"	The xenobiotic DMARDs, ie, gold salts (eg, aurothiomalate, auranofin, others), D-penicillamine, chloroquine and hydroxychloroquine, sulfasalazine (SSZ), methotrexate (MTX), azathioprine, and cyclosporin A, have been widely used to treat RA; some have been used for decades. \r\n\"	MTX and SSZ are the most active compounds in terms of frequency of remissions and time to onset of action and provide the best risk-benefit ratios. MTX alone or in combination with other agents has become the standard of care for moderate-to-severe RA. \r\n\"	Interest in the use of minocycline has recently been increasing because of its capacity to act as a DMARD. \r\n\"	Leflunomide is the most recent addition to the xenobiotics and has an activity similar to that of SSZ and MTX. \r\n\"	SSZ is dosed up to 2-4 g/d, while MTX is administered up to 25 mg once a week (PO, IV, IM, or SC). Both SSZ and MTX are started at low dosages and are increased to full dosages within approximately 4-6 weeks. Monitoring of CBC counts and liver enzymes is important because of the drugs\' hematologic and hepatic toxicities. Approximately 1% of patients develop agranulocytosis to SSZ or pneumonitis to MTX. Leflunomide is usually initiated with a loading dose of 100 mg/d for 3 days and is then continued at 20 mg/d. CBC counts and liver enzymes also must be monitored. Most of these drugs have been shown to improve signs and symptoms (as well as quality of life) and to significantly retard radiographic progression of RA. \r\n\"	Combination therapy appears to be helpful in patients whose RA insufficiently or completely fails to respond to monotherapy with a DMARD. Several compounds have been successfully combined without unexpected added risks; these usually include MTX as one of the drugs, ie, MTX plus cyclosporine A, MTX plus SSZ plus an antimalarial, MTX plus leflunomide, or MTX plus biologics. In general, the same precautions are needed as with the single compounds, although liver and bone marrow toxicity may be increased if compounds affecting these organs are combined. \r\n\"	The most important and most common adverse events relate to liver and bone marrow toxicity (MTX, SSZ, leflunomide, azathioprine, gold compounds, D-penicillamine), renal toxicity (cyclosporine A, parenteral gold salts, D-penicillamine), pneumonitis (MTX), allergic skin reactions (gold compounds, SSZ), autoimmunity (D-penicillamine, SSZ, minocycline) and infections (azathioprine, cyclosporine A). Antimalarials may cause ocular toxicity. Nevertheless, these drugs, when used with appropriate clinical and laboratory control monitoring, are usually tolerated well. Adverse events typically become more rare after the first 2-3 months. Most adverse events are reversible with cessation of the drugs or with reduction of the doses. \r\n\"	In clinical trials, 30-70% of patients using DMARDs, either alone or in combination therapy, achieve partial responses according to the American College of Rheumatology\'s disease activity score. Predicting which patients will not respond is impossible. In clinical practice, attempting to reduce disease activity as much as possible by (1) increasing the dose of medication (eg, MTX), (2) switching to other DMARDs in those who do not respond or in those with responses regarded as insufficient, or (3) initiating combination therapy is important. Because patients may require 2-3 months to achieve a full response to DMARDs, decisions regarding changes in medication are often delayed until that time. \r\no	Biologic agents \r\n\"	The recognition of TNF-alpha and IL-1 as central proinflammatory cytokines has led to the development of agents that block these cytokines or their effects. The TNF blockers include etanercept, infliximab, and adalimumab. Etanercept, a bivalent p75-TNF receptor linked to the Fc portion of human IgG, is administered at 25 mg SC twice weekly or 50 mg SC weekly, with or without concomitant MTX. Infliximab, a chimeric monoclonal antibody against TNF-alpha, is administered at doses of 3 mg/kg IV at weeks 0, 2, and 6 and then every 4-8 weeks, usually with MTX. Adalimumab, a recombinant human IgG1 monoclonal antibody specific for human TNF monoclonal antibody, is administered 40 mg SC every 2 weeks. \r\n\"	These agents are expensive. Consensus statements do not recommend their use until at least one xenobiotic DMARD, usually MTX, has been administered without sufficient success. In clinical trials, up to 70% of patients achieve significant responses, but remissions are not usually observed. \r\n\"	These agents bind TNF and thus prevent its interaction with its receptors; infliximab binds to cells that express membrane TNF, while etanercept binds lymphotoxin (formerly termed TNF-beta) in addition to soluble TNF-alpha. Failure to respond to one TNF blocker does not preclude response to another. As with xenobiotics, the decision to continue or stop biologic agents can often be made within 3 months after initiation of therapy. \r\n\"	Adverse effects associated with the biologic agents include the generation of antibodies against these compounds, emergence of antinuclear antibodies, occasional drug-induced lupuslike syndromes, and infections (including tuberculosis). Rarely, demyelinating disorders and bone marrow suppression may occur. Acute and chronic infections, demyelinating disorders, and recent malignancies are contraindications for TNF blockers. Thoroughly searching for latent tuberculosis using chest x-ray films and/or purified protein derivative (PPD) testing is recommended before starting these agents. \r\n\"	Another biologic is anakinra (IL-1 receptor antagonist [IL-1ra]). IL-1ra occupies the IL-1 receptor without triggering it and prevents receptor binding of IL-1. It is given at a dose of 100 mg/d SC. In clinical trials, a significant response was observed in approximately 40% of patients with RA. \r\n\"	Abatacept is a selective costimulation modulator that inhibits T-cell activation by binding to CD80 and CED86, thereby blocking CD28 interaction. CD28 interaction provides a signal needed for full T-cell activation that is implicated in RA pathogenesis. It is dosed according to body weight (vida infra); after initial infusion, repeat on week 2 and week 4, then every 4 weeks following. \r\n\"	In addition to improving signs and symptoms and quality of life, all biologics significantly retard radiographic progression of joint erosions. \r\no	Glucocorticoids \r\n\"	Glucocorticoids are potent anti-inflammatory drugs and are commonly used in patients with RA to bridge the time until DMARDs are effective. \r\n\"	Doses of up to 10 mg of prednisone per day are typically used, but some patients may require higher doses. \r\n\"	Timely dose reductions and cessation are important because of the adverse effects associated with long-term steroid use. \r\no	Nonsteroidal anti-inflammatory drugs \r\n\"	NSAIDs interfere with prostaglandin synthesis through inhibition of the enzyme cyclooxygenase (COX), thus reducing swelling and pain. However, they do not retard joint destruction and, therefore, when used alone, are not sufficient to treat RA. Similar to glucocorticoids, they can be reduced in dose or discontinued with successful DMARD therapy. \r\n\"	Several dozen NSAIDs are available and can be classified into different groups of compounds. Commonly used NSAIDs include ibuprofen, naproxen, ketoprofen, piroxicam, and diclofenac. \r\n\"	In the early 1990s, 2 isoforms of COX were discovered, ie, COX-1 and COX-2. Traditional NSAIDs inhibit both COX-1 and COX-2. \r\n\"	The coxibs (COX-2 inhibitors), a new group of compounds, have recently been developed. These compounds have a significant preference for COX-2 over COX-1. COX-1 has a protective role, particularly in the stomach, while COX-2 is strongly up-regulated during inflammation. \r\n\"	Coxibs, with their selectivity for COX-2, have been shown to be clinically efficacious and are accompanied by significantly reduced GI toxicity, the major adverse event related to the use of nonselective COX inhibitors (ie, NSAIDs). Other adverse effects, such as water retention, hypertension, and abnormal transaminase levels, are observed with both nonselective and COX-2-selective drugs. Whether and to what degree nonaspirin NSAIDs, coxibs, or both have cardiovascular toxicity has not been definitively settled.\r\no	Analgesics \r\n\"	Acetaminophen/paracetamol, tramadol, codeine, opiates, and a variety of other analgesic medications can also be employed to reduce pain. \r\n\"	These agents do not affect swelling or joint destruction. \r\no	Experimental therapies \r\n\"	Despite significant advances over the past decades, RA continues to be an incurable disease. The disease remains active in many patients whose conditions partially or completely fail to respond to DMARDs. Therefore, a vigorous search is underway for new therapeutic agents. \r\n\"	Although not truly experimental because it has been approved for use in RA, an immunoadsorbent column (Prosorba) is used on occasion to treat patients with resistant disease. Weekly exchanges are given for 12 weeks. \r\n\"	New TNF blockers are in clinical trials and include CDP 870, a Fab fragment of a humanized monoclonal antibody; and a pegylated version of the p55 TNF receptor. \r\n\"	Biologics capable of blocking IL-6 or interfering with T-cell/non-T-cell interactions may also be promising. \r\n\"	Xenobiotics directed at molecules involved in transduction of TNF or IL-1-mediated signals could prove helpful. \r\n\"	Inhibition of matrix metalloproteinases, although initially unsuccessful, could prove to be efficacious, as could agents that inhibit activation of osteoclasts. \r\n\"	Apheresis procedures are being investigated. \r\n\"	High-dose immunosuppression combined with autologous stem cell transplantation has been used in study protocols for patients whose conditions are resistant to other therapies.\r\no	Early therapy \r\n\"	Many studies have revealed that early treatment of RA (ie, within 3-12 mo of onset) with DMARDs can not only more efficiently retard disease progression than later treatment, but also may induce more remissions. Thus, early therapy with DMARDs has become the standard of care. \r\n\"	Importantly, note that patients with early forms of arthritis should be evaluated by, and if necessary, referred to physicians who are experienced in the diagnosis and treatment of this disease.\r\nSurgical Care: Cervical spine involvement usually affects C1-C2 and may potentially cause serious neurological consequences. Patients who are to undergo intubation or procedures that may involve manipulation of the neck should have careful evaluation of the cervical spine. \r\nPatients with RA often need multiple operations over time (eg, synovectomy, tendon corrections, joint replacements). \r\n', NULL, NULL, NULL, NULL, '1'),
('776', 'SARCOIDOSIS', '0', '* HEERFORDT- WALDENSTROM SYNDROME\r\n* LYMPHOMA\r\n* TUBERCULOSIS\r\n* FUNGAL INFECTION - BRUCELLOSIS, COCCIDIOMYCOSIS\r\n* BRONCHOGENIC CARCINOMA', '* BLOOD - LYMPHOCYTES, EOSINOPHILS, ESR, GLOBULIN - INCREASED\r\n* SERUM  ACE LEVELS - INCREASED.\r\n* CHEST X-RAY - B/L HILAR LYMPHADENOPATHY + DIFFUSE PARENCHYMAL CHANGES, PARATRACHEAL LYMPH NODES, RETICULO-NODULAR INFILTRATES.\r\n* C.T. THORAX  - GROUND GLASS APPEARANCE\r\n* PUL. FUNCTION TEST - VOLUME, DIFFUSING CAPACITY -  REDUCED, FEV1 / FVC - NORMAL\r\n* GA- 67 LUNG SCAN - ABNORMAL\r\n* BRONCHO- ALVEOLAR LAVAGE - INCREASED HELPER - T CELLS\r\n* KVEIM- SILLRBACH SKIN TEST - POSITIVE\r\n* 24- HR. URINE CALCIUM -  RAISED\r\n* LUNG BIOPSY OR BIOPSY OF EXTRANEURAL AFFECTED TISSUE OR BRAIN LESION/ MENINGES IF BRAIN IS INVOLVED\r\n* CSF ANGIOTENSIN CONVERTING ENZYME LEVELS - ELEVATED IF MENINGES ARE INVOLVED', '0', '0', '0', '0', '0', 'RISK FACTORS : CHR USE OF STEROID MAY INCREASE THE RATE OF VANTRICULAR ANEURYSM. VENTRICULAR ANEURYSMS INCREASE THE RISK OF VENTRICULAR TACHYCARDIA', 'B', '0', 'PRESENTATION OF DISEASE DEPENDS ON THE ORGAN INVOLVED :\r\n\r\n* - PULMONARY\r\n* - DERMATOLOGICAL\r\n* - CARDIAC : PACE MAKER, HEART FAILURE MEDICINES, DEFIBRILLATOR, ANTIARRHYTHMIC MEDICINES, ACCORDING TO PRESENTATION.\r\n* - OCULAR\r\n* - NEUROLOGICAL\r\n\r\n\r\nTT FOR RESTRICTIVE LUNG INVOLVEMENT :\r\nMedical Care: Few reliable studies on disease indications and optimal treatment exist. Most patients (>75%) require only symptomatic therapy (nonsteroidal anti-inflammatory drugs). Approximately 10% of patients need treatment for extrapulmonary disease, while 15% of patients require treatment for persistent pulmonary disease. \r\n\"	Corticosteroids are the mainstay of therapy. \r\no	Generally, prednisone given daily and then tapered over a 6-month course is adequate for pulmonary disease. Earlier recommendation suggested an initial dose of 1 mg/kg/d of prednisone; however, more recent expert opinions endorse a lower dose (eg 40 mg/d), which is tapered to every other day long-term therapy over several weeks. Most patients who require long-term steroids can be treated using 10-15 mg of prednisone every other day. \r\no	Recent data suggest that corticosteroid use may be associated with increased relapse rates. \r\no	High-dose inhaled corticosteroids may be an option, but conclusive data are lacking. \r\n\"	Noncorticosteroid agents are being used more frequently. \r\no	Methotrexate has been a successful alternative to prednisone and is a steroid-sparing agent. \r\no	Hydroxychloroquine may be used for cutaneous lesions, hypercalcemia, neurological sarcoidosis, and bone lesions. \r\no	Other alternatives include cyclosporine, pentoxifylline, and azathioprine. \r\n\"	Infliximab and thalidomide have been used for refractory sarcoidosis, particularly for cutaneous disease. Infliximab appears to be an effective treatment for patients with systemic manifestations such as lupus pernio, uveitis, hepatic sarcoidosis, and neurosarcoidosis. \r\n\"	Tetracyclines have shown promise for the treatment of cutaneous sarcoidosis.\r\n\"	For pulmonary disease, asymptomatic PFT and/or CXR abnormalities are not an indication for treatment. In patients with minimal symptoms, serial reevaluation is prudent. Significant respiratory symptoms associated with PFT and CXR abnormalities likely require therapy. For such patients, treatment is indicated if objective evidence of recent deterioration in lung function exists. Corticosteroids can result in small improvements in the functional vital capacity, and in radiographic appearance in patients with more severe stage II and III disease. \r\n\"	One recent study demonstrated an approach that may minimize the use of corticosteroids without harming the patient. This is accomplished by withholding therapy unless the patient shows at least a 15% decline in one spirometric measure associated with increasing symptoms or, if asymptomatic, withholding therapy unless the patient shows worsening PFTs and a change in CXR.\r\n\"	For extrapulmonary sarcoidosis involving such critical organs as the heart, liver, eyes, kidneys or central nervous system, corticosteroid therapy is indicated.\r\n\"	Topical corticosteroids are effective for ocular disease.\r\n\"	Inhaled corticosteroids are occasionally used, in particular in patients with endobronchial disease.\r\nSurgical Care: For patients with advanced sarcoid-induced pulmonary fibrosis, lung transplantation remains the only hope for long-term survival. \r\n\"	Lung transplantation is a viable option for patients with stage IV sarcoidosis. Transplantation in such patients should be strongly considered when the forced vital capacity (FVC) falls below 50% predicted and/or the forced expiratory volume in 1 second (FEV1) falls below 40% predicted.\r\n', NULL, NULL, NULL, NULL, '1'),
('787', 'SJOGRENS SYNDROME', '0', 'D.D. :\r\n\r\n* HIV INFECTION\r\n* SARCOIDOSIS\r\n* AMYLOIDOSIS, IMMUNOGLOBULIN RELATED\r\n* PACREATITIS, CHRONIC\r\n* POLYMYOSITIS\r\n* RHEUMATOID ARTHRITIS\r\n* SALIVARY GLAND TUMORS, MAJOR, BENIGN\r\n* SALIVARY GLAND TUMORS, MINOR, BENIGN\r\n* SARCOIDOSIS\r\n* SLE\r\n* TUBERCULOSIS', 'OTHER TESTS :\r\n* AUTOANTIBODIES : RO / SSA , LA / SSB. ASSOCIATION WITH HLA-DR3 & DRW 52.\r\n* RHEUMATOID FACTOR +\r\n* SIALOGRAPHY, SIALOMETRY, SCINTIGRAPHY, LABIAL SALIVARY GLAND BIOPSY\r\n* SCHIRMERS- I TEST\r\n* TEAR BREAK UP TIME\r\n* TEAR LYSOZYME CONTENT\r\n* SLIT LAMP EXAM. AFTER ROSE BENGAL STAINING\r\n* ESR - RAISED\r\n* NORMOCYTIC NORMOCHROMIC ANEMIA', '0', '0', '0', '0', '0', '', 'B', '0', 'EVALUATE THE PATIENT FOR DISORDERS ASSOCIATED WITH SJOGREN SYNDROME LIKE:\r\n- ACQUIRED IMMUNODEFICIENCY SYNDROME\r\n- RHEUMATOID ARTHRITIS\r\n- SLE\r\n- SCLERODERMA\r\n- POLYMYOSITIS\r\n- PRIMARY BILIARY CIRHOSIS\r\n- THYROIDITIS\r\n- CHRONIC ACTIVE HEPATITIS\r\n- MIXED CRYOGLOBULINEMIA\r\n\r\n\r\nMedical Care: \r\n\"	Dry eyes\r\no	Artificial tears should be applied liberally. \r\n\"	Patients may need to apply artificial tears more often if they enter an environment with low humidity (ie, air conditioning, airplanes). \r\n\"	Artificial tears with hydroxymethylcellulose or dextran are more viscous and can last longer before reapplication is needed. Encourage patients to try various preparations to determine what works best for them. \r\n\"	If artificial tears burn when they are instilled, the preservative in the artificial tears is likely irritating the eye. If artificial tears are used more often than every 4 hours, patients should use a preservative-free preparation to avoid eye irritation from the preservatives. \r\n\"	If patients wake up in the morning with severe matting in the eyes, then they should use a more viscous preparation, such as Lacri-Lube, at night. While the more viscous preparations can be applied less often, they can make patients\' vision filmy. Therefore, they are best used at night. \r\n\"	The more viscous preparations can occasionally lead to blepharitis, which can exacerbate sicca symptoms.\r\no	Temporary plugging of the lacrimal puncta can increase the amount of tears that remain in the eyes. Electrocautery and other techniques can be used for permanent punctal occlusion. \r\no	Patients should avoid medications with anticholinergic and antihistamine effects. \r\no	The use of humidifiers may help. If living in an area with hard water, using distilled water is best. \r\no	Glasses fitted with moisture shields can decrease evaporation.\r\n\"	Dry mouth \r\no	Patients can liberally drink sips of water and take bottled water with them on trips. They can also place a glass of water at their bedside for nighttime use as needed. \r\no	Sugar-free lemon drops can also be used as needed to stimulate salivary secretion. \r\no	Artificial saliva can be used as needed, although patient tolerance is variable. Preparations include Salivart, Saliment, Saliva Substitute, MouthKote, and Xero-Lube. \r\no	Patients should be seen regularly by a dentist, who might advise fluoride treatments. Toothpaste without detergents can reduce mouth irritation in patients with SS. Brands include Biotene toothpaste, Biotene mouth rinse, Dental Care toothpaste, and Oral Balance gel. \r\no	Patients should avoid medications with anticholinergic and antihistamine effects. \r\no	Watch for and treat oral candidiasis and angular cheilitis with topical antifungal agents, such as nystatin troches. Oral fluconazole may be needed occasionally. Patients also need to be sure to disinfect their dentures. \r\no	Sinusitis and sinus blockade should be treated because these problems may contribute to mouth breathing. Emphasize the use of isotonic sodium chloride solution nasal sprays to avoid using antihistamines. \r\no	Use of humidifiers may help. For patients living in an area with hard water, using distilled water is best. \r\no	Pilocarpine or cevimeline tablets are options. Some small studies suggest that interferon alfa may be a useful therapy in the future. \r\n\"	Skin and vaginal dryness \r\no	Patients should use skin creams, such as Eucerin, or skin lotions, such as Lubriderm, to help with dry skin. \r\no	Patients should use vaginal lubricants, such as Replens, for vaginal dryness. Vaginal estrogen creams can be considered in postmenopausal women. Watch for and treat vaginal yeast infections.\r\n\"	Arthralgias and arthritis \r\no	Acetaminophen or nonsteroidal anti-inflammatory drugs (NSAIDs) can be taken for arthralgias. \r\no	Consider hydroxychloroquine if NSAIDs are not sufficient for the synovitis occasionally associated with primary SS. This medication, however, does not relieve sicca symptoms. \r\no	Patients with RA associated with SS likely require other disease-modifying agents.\r\n\"	Other \r\no	In patients with major organ involvement, such as lymphocytic interstitial lung disease, consider therapy with steroids and immunosuppressive agents, such as cyclophosphamide. \r\no	While cyclophosphamide and similar agents may be helpful to treat serious manifestations of SS or disorders associated with SS, clinicians should understand that these agents are also associated with the development of lymphomas.\r\n\"	Anticoagulation: Long-term anticoagulation may be needed in those patients with vascular thrombosis related to antiphospholipid antibody syndrome.\r\nSurgical Care: \r\n\"	Perform a minor salivary gland biopsy for diagnostic purposes.\r\n\"	Perform a biopsy on the parotid gland if malignancy is suggested.\r\n\"	Perform a biopsy on an enlarged lymph node to help rule out pseudolymphoma or lymphoma.\r\n\"	Occlusion of the lacrimal puncta can be corrected surgically. Electrocautery and other techniques can be used for permanent punctal occlusion.\r\n\"	During surgery, the anesthesiologist should use as little anticholinergic medications as possible and use humidified oxygen to help avoid inspissation of pulmonary secretions. Good postoperative respiratory therapy should also be provided. Patients are at higher risk for corneal abrasions, so ocular lubricants should be considered.\r\nActivity: Encourage patients to be active. \r\n', NULL, NULL, NULL, NULL, '1'),
('798', 'SQUAMOUS CELL CARCINOMA', '0', 'CAUSES :\r\n• Exact mechanism not established, epidemiologic and experimental evidence suggests the following as causative agents\r\n• Sunlight (solar radiation)\r\n• Radiation exposure\r\n• Inorganic arsenic exposure\r\n• Exposure to coal tar, other oil and tar derivatives\r\n• Immunosuppression by medications or disease\r\n\r\n\r\n--------------------------------------------------------------------------\r\nDIFFERENTIAL DIAGNOSIS - Keratoacanthoma\r\n- basal cell carcinoma\r\n- actinic keratosis\r\n- malignant melanoma', '', '0', '0', '0', '0', '0', 'RISK FACTORS : - ULTRA VIOLET RAYS, IMMUNOSUPPRESSION, EXPOSURE TO IONIZING RADIATION OR CHEMICAL CARCINOGENS, INFECTION WITH HUMAN PAPILLOMAVIRUS', 'B', '0', 'Squamous Cell Carcinoma of the Skin \r\nLocalized squamous cell carcinoma of the skin is a highly curable disease. The traditional methods of treatment involve the use of cryosurgery, radiation therapy, electrodesiccation and curettage, and simple excision. Each of these methods may be useful in specific clinical situations.\r\nOf all treatment methods available, Mohs micrographic surgery has the highest 5-year cure rate for both primary and recurrent tumors. This method uses microscopic control to evaluate the extent of tumor invasion. Lymphadenectomy is indicated when regional lymph nodes are involved. \r\nTreatment options: \r\n1.	Mohs micrographic surgery. Although this method is complicated and requires special training, it has the highest cure rate of all surgical treatments because the tumor is microscopically delineated until it is completely removed. It is indicated for the treatment of: \r\n\"	primary squamous cell carcinomas when they occur at sites known to have a high initial treatment failure rate following traditional methods; \r\n\"	primary tumors with poorly defined clinical borders, primary tumors with diameters >2 cm; or \r\n\"	primary tumors arising in regions where the maximum preservation of uninvolved tissue is desirable such as the face, head, and genitalia. \r\nMohs micrographic surgery should be used for squamous cell carcinomas that show perineural invasion since tumor transit along nerves may extend many centimeters away from the primary or recurrent tumor site. Recurrent squamous cell carcinomas can also be treated with this technique. \r\n2.	Simple excision with frozen or permanent sectioning for margin evaluation. This traditional surgical treatment usually relies on surgical margins ranging from 3 mm to 10 mm, depending on the diameter of the original tumor. Tumor recurrence is not uncommon because only a small fraction of the total tumor margin is examined pathologically. \r\n3.	Electrodesiccation and curettage. This is a quick method for destroying the tumor, but the adequacy of treatment cannot be assessed immediately since the surgeon cannot visually detect the depth of microscopic tumor invasion. It should be reserved for very small primary tumors since this disease has metastatic potential. \r\n4.	Cryosurgery. Cryosurgery is used for patients with clinically well-defined in situ tumors. It is especially useful for debilitated patients with medical conditions that preclude other types of surgery. \r\nAbsolute contraindications for cryosurgery include abnormal cold tolerance, cryoglobulinemia, cryofibrinogenemia, Raynaud\'s disease, and platelet deficiency disorders. Relative contraindications to cryosurgery include tumors of the scalp, ala nasi, nasolabial fold, tragus, postauricular sulcus, free eyelid margin, upper lip vermillion border, and lower legs. Caution should also be used before treating nodular ulcerative neoplasia >3 cm, carcinomas fixed to the underlying bone or cartilage, tumors situated on the lateral margins of the fingers and at the ulnar fossa of the elbow, or recurrent carcinomas following surgical excision. Significant morbidity is associated with the use of cryosurgery. \r\nEdema is common following treatment, especially around the periorbital region, temple, and forehead. Treated tumors usually exude necrotic material after which an eschar forms and persists for about 4 weeks. Permanent pigment loss at the treatment site is unavoidable. Atrophy and hypertrophic scarring have been reported as well as instances of motor and sensory neuropathy. \r\n\r\n5.	Radiation therapy. Radiation therapy is a logical treatment choice, particularly for patients with primary lesions requiring difficult or extensive surgery (e.g., eyelids, nose, or ears). It eliminates the need for skin grafting when surgery would result in an extensive defect. Cosmetic results are generally good to excellent with a small amount of hypopigmentation or telangiectasia in the treatment port. Radiation therapy can also be utilized for lesions that recur after a primary surgical approach. \r\nRadiation therapy is contraindicated for patients with xeroderma pigmentosum, epidermodysplasia verruciformis, or the basal cell nevus syndrome because it may induce more tumors in the treatment area. \r\n\r\n6.	Topical fluorouracil (5-FU). This method may be helpful in the management of selected in situ squamous cell carcinomas (Bowen\'s disease). Careful and prolonged follow-up is required since deep follicular portions of the tumor may escape treatment and result in future tumor recurrence. \r\n7.	Carbon dioxide laser. This method may be helpful in the management of selected squamous cell carcinoma in situ. It may be considered when a bleeding diathesis is present, since bleeding is unusual when this laser is used. \r\n8.	Interferon alfa. Clinical trials are ongoing to treat squamous cell carcinoma with intralesional interferon alfa. The results should be available in several years. One report shows the combination of interferon alfa and retinoids is effective treatment for squamous cell carcinoma. \r\nFollow-up: \r\n\"	Since squamous cell carcinomas have definite metastatic potential, patients should be re-examined every 3 months for the first several years and then followed indefinitely at 6-month intervals.\r\n\r\nPREVENTION/AVOIDANCE:\r\n• Sun-avoidance measures - sunscreens, hats, etc.\r\n• Avoid contact with known carcinogenic compounds\r\n\r\nPOSSIBLE COMPLICATIONS:\r\n• Recurrence locally\r\n• Metastatic disease\r\n\r\nEXPECTED COURSE/PROGNOSIS:\r\n• About 90-95% cure rate with appropriate treatment\r\n• Lesion equal to or greater than 2 cm more prone to recur\r\n• Head and neck lesions have better prognosis', NULL, NULL, NULL, NULL, '1'),
('808', 'SYSTEMIC LUPUS ERYTHEMATOSUS', '0', 'D.D. :\r\n\r\n- ANTIPHOSPHOLIPID SYNDROME\r\n- FIBROMYALGIA\r\n- HEPATITIS C DISEASE\r\n- INFECTIOUS MONONUCLEOSIS\r\n- INFECTIVE ENDOCARDITIS\r\n- LYME DISEASE\r\n- LYMPHOMA, B-CELL\r\n- MIXED CONNECTIVE TISSUE DISEASE\r\n- POLYARTERITIS NODOSA\r\n-PREECLAMPSIA\r\n- RHEUMATIC FEVER\r\n- RHEUMATOID ARTHRITIS\r\n- SCLERODERMA\r\n- SERUM SICKNESS\r\n- THROMBOTIC THROMBOCYTOPENIC PURPURA\r\n- UNDIFFERENTIATED CONNECTIVE TISSUE DISEASE', 'OTHER TESTS :\r\n* ESR, C-REACTIVE PROTEIN - HIGH\r\n* ANA - PRESENT IN ALL \r\n*  ANTI-SMITH ANTIBODIES - PRESENT \r\n* ANTI-DOUBLE STRAND DNA ANTIBODIES - PRESENT & ARE SPECIFIC.\r\n* COMPLIMENT LEVELS ( TOTAL FUNCTIONAL HAEMOLYTIC COMPLIMENTS ( C 3 & C 4 COMPLIMENTS ) - DECREASED\r\n* BLOOD - ANEMIA, LEUKOPENIA, LYMPHOPENIA, THROMBOCYTOPENIA\r\n* URINE - PROTEINURIA, HAEMATURIA, CELLULAR / GRANULAR CAST.\r\n* SERUM CREATININE - EVALUATION IS USEFUL TO MONITOR KIDNEY DISEASE ACTIVITY\r\n* RENAL BIOPSY, SKIN BIOPSY OR LUMBER PUNCTURE\r\n* JOINT X-RAYS, CHEST CT, BRAIN MRI MAY BE NECESSARY', '0', '0', '0', '0', '0', 'CAN CAUSE ANGINA DUE TO MICROVASCULAR ABNORMALITIES.', 'B', '0', 'Medical Care: Care of patients with systemic lupus erythematosus (SLE) depends on disease severity. Periodic follow-up and laboratory testing, including urinalyses, are imperative to detect signs and symptoms of new organ system involvement and to monitor response or adverse reactions to therapies. \r\n\"	CBC count with differential, creatinine, and urinalyses aid in detection of new organ system involvement and in monitoring response to therapies. At least quarterly visits are recommended in most cases.\r\n\"	Fever, skin, musculoskeletal, and serositis represent milder disease manifestations, which may wax and wane with disease activity. These are often controlled with low-potency medications or short steroid courses.\r\n\"	CNS involvement and renal disease must be recognized as more severe disease manifestations and are often treated with more aggressive immunosuppression.\r\n\"	Acute emergencies in SLE include severe neurologic involvement, systemic vasculitis, profound thrombocytopenia with a TTP-like syndrome, rapidly progressive glomerulonephritis, or diffuse alveolar hemorrhage. Rare serious manifestations such as TTP, diffuse alveolar hemorrhage, or profound steroid-refractory thrombocytopenia may require plasma exchange or intravenous immunoglobulin (IVIG), respectively.\r\n\"	Preventative care measures are necessary to minimize the risks of steroid-induced osteoporosis and accelerated atherosclerotic disease.\r\no	The ACR Guidelines for the prevention of glucocorticoid-induced osteoporosis suggest traditional steps and the consideration of prophylactic bisphosphonate therapy. \r\no	Recently, numerous authors have also advocated drafting cardiovascular prevention guidelines that equate SLE as a \"CAD risk-equivalent\" similar to diabetes mellitus. This is based on a 10-year coronary event rate of 13-15% in patients with active SLE compared with a 10-year event rate of 18.8% in patients with known pre-existing coronary heart disease.\r\nDiet: No diet-based treatment of SLE has been proven effective. \r\nActivity: Patients should be reminded that activity may need to be modified as tolerated. Specifically, stress such as physical illness may precipitate SLE flares. Additionally, persons with SLE should wear sunscreen and protective clothing or avoid sun exposure to limit photosensitive rash or disease flares.\r\n\r\nDRUG TREATMENT : Treatment of systemic lupus erythematosus (SLE) is guided by the individual patient\'s manifestations. \r\n\r\nFever, rash, musculoskeletal, and serositis manifestations generally respond to treatment with hydroxychloroquine and NSAIDS. Low-to-moderate dose steroids are necessary for acute flares. \r\n\r\nCNS involvement and renal disease constitute more serious disease and often require high-dose steroids and other immunosuppression agents such as cyclophosphamide, azathioprine, or mycophenolate. \r\n\r\nTraditionally, class IV diffuse proliferative lupus nephritis has been treated with aggressive cyclophosphamide induction therapy. \r\n\r\nNewer lupus nephritis literature has shown that mycophenolate is a safe maintenance agent and is potentially an induction agent, although long-term comparative studies with cyclophosphamide are necessary. \r\n\r\nGiven the safety profile, some small series have supported the use of mycophenolate and corticosteroids for membranous nephritis. \r\n\r\nNew investigations are in progress to look at the role of rituximab and other B-cell targeted therapies in SLE.\r\n\r\n1. NSAIDS :\r\n\r\n- IBUPROFEN\r\n\r\n2. ANTIMALARIALS : The mechanism of action of antimalarials in SLE is unknown, but they do not cause generalized immunosuppression. They are useful to prevent and treat lupus skin rashes, constitutional symptoms, arthralgias, and arthritis. They also help to prevent lupus flares and have been associated with reduced morbidity and mortality in SLE.\r\n\r\n- HYDROXYCHLOROQUINE\r\n\r\n3. IMMUNOSUPPRESSANTS :\r\n\r\n- METHOTREXATE\r\n- CYCLOPHOSPHAMIDE\r\n- AZATHIOPRINE\r\n- MYCOPHENOLATE\r\n\r\n5. CORTICOSTEROIDS :\r\n\r\n- METHYLPREDNISOLONE\r\n- PREDNISONE', NULL, NULL, NULL, NULL, '1'),
('860', 'ARRHYTHMIAS, VENTRICULAR TACHYCARDIA', '0', 'CAUSES :\r\n\r\n- CHRONIC ISCHAEMIC HEART DISEASE\r\n- NONISCHAEMIC CARDIOMYOPATHIES\r\n- METABOLIC DISORDERS\r\n- DRUG TOXICITIES( BIDIRECTIONAL VT IN DIGOXIN) OR QT PROLONGING DRUGS ( TORSADE DE POINTES VT )\r\n- PROLONGED Q-T SYNDROME\r\n- IDIOPATHIC\r\n- SHORT QT SYNDROME\r\n- BRUGADA SYNDROME\r\n- FAMILIAL ADRENERGIC POLYMORPHIC VENTRICULAR TACHYCARDIA\r\n- ELECTROLYTE ABNORMALITIES LIKE HYPOKALEMIA\r\n- BUNDLE BRANCH REENTRY', '* LAB TESTS - NONE EXCEPT TO SEE ELECTROLYTE ABNORMALITY OR DRUG LEVELS\r\n* STRESS MYOCARDIAL PERFUSION STUDY - TO ACCESS ISCHAEMIA\r\n* CORONARY ANGIOGRAPHY & LT. VENTRICULAR ANGIOGRAPHY', '0', '0', '0', '0', '0', 'RISK FACTORS : HYPERLIPIDEMIA, HYPERTENSION, CIGARETTE SMOKING', 'B', '0', 'Medical Care: The acute management strategy depends upon the immediate hemodynamic consequences of the arrhythmia. VT associated with loss of consciousness or hypotension is a medical emergency requiring immediate cardioversion. In a normally sized adult, this is typically accomplished with a 200-to 360-J monophasic shock or a clinically equivalent biphasic energy dose. \r\nWhen the hemodynamic status is stable, the patient is well perfused, and no evidence for coronary ischemia or infarction is present, then a trial of intravenous medication may be considered. If left ventricular function is impaired, amiodarone, then lidocaine, are favored over procainamide because of the latter drug\'s potential for exacerbating congestive heart failure. If medical therapy is unsuccessful, synchronized cardioversion (50-200 J monophasic) following sedation is appropriate. \r\nIf runs of polymorphic VT are observed punctuated by sinus rhythm with QT prolongation, then attempts should be made to correct torsades with magnesium, isoproterenol, and/or pacing. Phenytoin and lidocaine may also help by shortening the QT interval in this setting, but procainamide is contraindicated because of its QT prolonging effects. Efforts should be made to correct hypokalemia and withdraw any chronic medications associated with QT-interval prolongation. \r\nOccasionally, patients present with wide QRS complex tachycardia of unknown mechanism. In the absence of pacing, the differential diagnosis includes VT and aberrantly conducted SVT. If hemodynamic compromise is present or if any doubt exists about the rhythm diagnosis, the safest strategy is to treat the undiagnosed rhythm as VT. If the clinical situation permits, a 12-lead ECG should be obtained prior to conversion of the rhythm. The ECG criteria of Brugada et al (1991) may be useful in differentiating the arrhythmia mechanism. \r\nRarely, patients present with repetitive runs of nonsustained VT, as in Image 3. Prolonged exposure to this (or any other) tachycardia may cause a tachycardia-induced cardiomyopathy, which typically improves with medical or ablative therapy of the VT. \r\nChronic management strategies may include medications, ICD implantation, and catheter-based ablation. Combinations of these therapies are typically used when structural heart disease is present. \r\nBecause VT patients with structurally normal hearts have a low risk of sudden death, ICDs are unnecessary in this setting. These patients are therefore treated with medications or ablation. \r\n\"	Antiarrhythmic drug trials have been disappointing. Placebo-controlled arrhythmia prevention trials often show that antiarrhythmics increase sudden death mortality, particularly with the use of Vaughn Williams Class I antiarrhythmics.\r\n\"	These medications work by slowing propagation and reducing tissue excitability through sodium channel blockade. The class III antiarrhythmics prolong repolarization through potassium channel blockade.\r\n\"	The ESVEM (Electrophysiologic Study Versus Electrocardiographic Monitoring) study of VT/VF patients demonstrated the superiority of sotalol over several type I antiarrhythmic drugs, but the trial did not include a placebo control group. \r\n\"	Amiodarone is a complex antiarrhythmic drug that deserves special mention. It is generally listed as a class III drug but has measurable class I, II, and IV effects. Although the complex kinetics of this drug did not allow inclusion in ESVEM, the Cardiac Arrest in Seattle: Conventional versus Amiodarone Drug Evaluation (CASCADE) trial suggested that amiodarone was superior to conventional antiarrhythmics (a mix of class I drugs) for secondary arrhythmia prophylaxis (ie, prior VT/VF). Based in large part upon the results of ESVEM and CASCADE, current clinical practice favors class III antiarrhythmics.\r\no	Amiodarone has also been studied as primary arrhythmia prophylaxis in the postinfarct setting, but it had no impact on overall mortality rates. \r\no	Unlike class I antiarrhythmics, amiodarone appears to be safe in patients with left ventricular dysfunction.\r\n\"	In the setting of congestive heart failure, the best proven antiarrhythmic drug strategies appear to be the use of angiotensin-converting enzyme (ACE) inhibitors and chronic beta-receptor-blocking agents. \r\n\"	The ICD has changed the face of ventricular arrhythmia management. Like pacemakers, these devices can be implanted transvenously quickly in a low-risk procedure. \r\n\"	Once installed, the ICD can detect ventricular tachyarrhythmias and terminate them with defibrillation shocks or antitachycardia pacing algorithms. These devices can also function as backup pacemakers in patients with bradyarrhythmias. \r\n\"	The advent of transvenous ICD technology triggered several trials comparing the ICD to conventional antiarrhythmic therapies. \r\n\"	In patients with prior VT/VF, ICD therapy was compared to the best available antiarrhythmic drugs, amiodarone, and sotalol. \r\n\"	The Antiarrhythmics Versus Implantable Defibrillators (AVID) study; the Canadian Implantable Defibrillator Study (CIDS); and the Cardiac Arrest Study, Hamburg (CASH) demonstrated better survival in patients randomized to ICD therapy. The survival difference was significant in AVID, of borderline statistical significance in CIDS (P<0.06), and of no statistical difference in CASH. A meta-analysis of the 3 trials suggested a 28% reduction in the relative risk of death related to ICD implantation in this clinical setting (Connolly, 2000). \r\n\"	Primary prevention of sudden death has been a difficult problem for cardiologists due to the difficulties of accurate risk stratification. \r\n\"	The Multicenter UnSustained Tachycardia Trial (MUSTT) and Multicenter Autonomic Defibrillator Implantation Trial (MADIT) studied high-risk patients who had never had VF or sustained VT.\r\no	In these studies, patients with ischemic cardiomyopathy, ejection fractions greater than 35-40%, and nonsustained VT were taken to EPS. \r\no	Patients with inducible sustained VT were randomized between conventional antiarrhythmic therapy and prophylactic ICD implantation. \r\no	In each study, ICD patients had better survival than patients receiving antiarrhythmic drugs.\r\nSurgical Care: In the 1980s, ventricular arrhythmia surgery was explored at several centers, using excision and cryoablation of infarct zones to prevent recurrent VT. The high mortality rates of these procedures and the success of the ICD led to a decline in open surgical procedures for VT. Catheter ablation of VT remains an option for patients with recurrent ICD shocks or non-ICD patients with preserved ventricular function. Ablation is used to treat symptomatic VT, rather than to reduce sudden death risk. \r\n\"	Reentrant VT requires a slow conduction zone, and this is usually located along the border of a scarred zone of myocardium.\r\n\"	The small physical size of the slow conduction zone makes it an ideal target for focal ablation procedures.\r\n\"	Cell disruption can be achieved using radiofrequency energy or cryoablation via transvenous catheters during closed-chest procedures.\r\n\"	Because patients with ischemic VT often have multiple reentrant circuits, ablation is typically used as an adjunct to ICD therapy.\r\n\"	If VT arises from an automatic focus, the focus can be targeted for ablation.\r\n\"	In patients with structurally normal hearts, the most common form of VT arises from the right ventricular outflow tract (RVOT). The typical outflow tract ectopic beat shows a positive QRS axis in the inferior leads. Abnormal or triggered automaticity is the most likely mechanism, and focal ablation is curative in these patients. Ablation cure rates are typically greater than 90% in this setting.\r\n\"	Reentrant tachycardia occasionally arises from the RVOT in patients with right ventricular dysplasia and repaired tetralogy of Fallot patients. The tachycardia mechanism can usually be determined during EPS, and these circuits are commonly amenable to catheter ablation.\r\nDiet: Patients with ischemic VT may benefit from low-cholesterol and/or low-salt diets. Patients with idiopathic VT may notice a reduction in symptoms when stimulants, such as caffeine, are avoided. \r\nActivity: VT may be precipitated by increased sympathetic tone during strenuous physical exertion. One goal of successful VT management is to allow the patient to return to an active lifestyle through medications, ICD implantation, and/or ablation therapy.\r\n\r\nDRUG THERAPY : Intravenous medications are used to suppress acute VT. In the United States, these are limited to amiodarone, lidocaine, procainamide, and a handful of intravenous beta-adrenergic blocking agents (metoprolol, esmolol, propranolol). Bretylium is no longer available. In patients with acute VT or VF, intravenous amiodarone is the drug of choice. Although intravenous lidocaine is effective at suppressing peri-infarction VT, it may increase the overall mortality risk. In the ARREST (Amiodarone in the Out-of-Hospital Resuscitation of Refractory Sustained Ventricular Tachyarrhythmias) study, intravenous amiodarone was superior to placebo in patients with out-of-hospital cardiac arrest. In the ALIVE (Amiodarone versus Lidocaine in Prehospital Refractory Ventricular Fibrillation Evaluation) study, intravenous amiodarone was superior to lidocaine in a similar patient group. \r\nIn patients with idiopathic VT (associated with structurally normal hearts), medications are often avoided entirely through the use of curative catheter-based ablation. \r\nOral medications are used to chronically suppress recurrent VT. As noted earlier in this article, current evidence favors class III antiarrhythmic drugs over class I drugs. No large studies compare the currently available class III drugs, amiodarone, and sotalol. When VT is observed in a patient receiving an antiarrhythmic drug, discrimination must be made between VT recurrence and drug-induced ventricular proarrhythmia. The most common form of proarrhythmia is torsades de pointes (see Torsade de Pointes), associated with QT-interval prolongation, usually due to excessive potassium channel blockade. \r\nIn patients with hemodynamically significant VT/VF, ICD implantation has superseded medication as primary therapy. Because ICDs treat, rather than prevent, ventricular arrhythmias, as many as 50% of ICD patients require therapy with antiarrhythmic drugs to reduce the potential for ICD shocks. Once an ICD has been implanted, adjunctive drug and catheter ablation therapies can be used to reduce the number of ICD discharges.\r\n\r\n1. Antiarrhythmics -- Intravenous administration is used for suppression of acute VT. Agents alter the electrophysiologic mechanisms responsible for arrhythmia. Medications are generally used to prevent recurrence of VT in susceptible patients. \r\nCareful attention must be paid to drug pharmacokinetics due to relatively narrow therapeutic windows involved. \r\nMost antiarrhythmic drugs may actually cause ventricular arrhythmias, and risks generally increase with serum drug levels. \r\n\r\n- LIDOCAINE\r\n- PROCAINAMIDE\r\n- AMIODARONE\r\n- SOTALOL\r\n- MEXILETINE\r\n- ACEBUTOLOL\r\n- ATENOLOL\r\n- METOPROLOL\r\n- FLECAINIDE\r\n- PROPAFENONE\r\n- ANTIDIGOXIN ANTIBODIES IF DIGOXIN TOXIC\r\n- DRUGS TO CORRECT ELECTROLYTE IMBALANCE LIKE POTASIUM FOR HYPOKALEMIA', NULL, NULL, NULL, NULL, '1'),
('864', 'VIRAL FEVER', '0', '', 'OTHER TESTS :\r\n* PERIPHERAL BLOOD TEST - NEAR NORMAL', '0', '0', '0', '0', '0', NULL, 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('888', 'ZOLLINGER-ELLISON SYNDROME ( GASTRINOMA )', '0', 'D.D. : ( CONDITIONS WITH HYPERGASTRINEMIA )\r\n\r\n- GASTRINOMAS\r\n- RETAINED ANTRUM SYNDROME\r\n- H. PYLORI INFECTION\r\n- ANTRAL G CELL HYPERPLASIA / HYPERFUNCTION\r\n- GASTRIC OUTLET OBSTRUCTION\r\n- HYPERCALCEMIA\r\n- ACHLORHYDRIA\r\n- RENAL FAILURE ( RARELY )\r\n- OTHERS LESS COMMON LIKE \r\n* DIABETES \r\n*  RHEUMATOID ARTHRITIS\r\n*  VITILIGO\r\n*  PHEOCHROMOCYTOMA\r\n* USE OF H2 BLOCKERS & PROTON PUMP INHIBITORS', 'OTHER TESTS :\r\n* GASTRIC ACID ANALYSIS- HIGH GASTRIC ACIDITY ( PH < 3.0 )\r\n* FASTING GASTRIN LEVELS , NORMAL < 150 PG/ML , > 150 TO 200 PG / ML ( OR >1000 NG/ L ; 10 TIMES NORMAL ) IS DIAGNOSTIC\r\n* BASAL GASTRIC ACID OUTPUT( HYPERCHLORHYDRIA ) - IN > 80% BAO IS ELEVATED ( 15 MEQ / H ) . \r\n*SECRETIN ( 2 IU/KG OF BODY WT I.V.) STIMULATION TEST - POSITIVE IN > 80% ( >200 NG/L INCREASE IN SERUM GASTRIN LEVEL WITHIN 15 MTS OF IV SECRETIN)\r\n* ULTRA SOUND ABDOMEN, CT ABDOMEN, CELIAC ANGIOGRAPHY, AORTOGRAPHY ARE FREQUENTLY INSENSITIVE & MAY LOCALIZE ABOUT 60% OF GASTRINOMAS.\r\n* ENDOSCOPIC ULTRA SOUND OR INTRAOPERATIVE ULTRA SOUND\r\n* TRANSHEPATIC PORTAL VENOUS SAMPLE MAY LOCALIZE OCCULT TUMORS.\r\n* LOCALIZATION MAY BE DONE BY COMPARISION OF GASTRIN LEVELS IN THE RT. HEPATIC VEIN FOLLOWING SELECTIVE INFUSION OF THE INTRAPANCREATIC ARTRIES WITH SECRETIN.', '1', '0', '0', '0', '0', 'MAY OCCUR AS PART OF AUTOSOMAL DOMINANT FAMILIAL SYNDROME CALLED MEN TYPE 1', 'B', '0', 'Medical Care: \r\n\"	The goals of treatment are medical control of gastric acid hypersecretion and surgical resection of the tumor.\r\no	If the patient is acutely ill, immediate control of gastric acid hypersecretion can be achieved with intravenous proton pump inhibitors. Previously, this was accomplished with histamine 2 (H2) receptor blockers. Intravenous pantoprazole was approved recently by the US Food and Drug Administration. Proton pump inhibitors are superior to H2 blockers for the control of gastric acid hypersecretion.\r\no	Patients who are candidates for surgical resection should be referred for resection of the tumor.\r\no	For patients with metastatic disease, chemotherapy, interferon, and octreotide may be helpful. The response to these agents in most studies has been low. Liver transplantation for hepatic metastasis also has been reported. For patients with a single confined liver metastatic lesion, surgical resection may be attempted.\r\nSurgical Care: \r\n\"	All patients with sporadic ZES without hepatic metastases or medical contraindications to surgery are advised to undergo surgical resection of the tumor because this decreases the risk of developing liver metastases, which can decrease the survival of these patients.\r\n\"	The role and timing of surgical resection in patients with MEN 1 is less clear. An attempt at surgical resection has been recommended if the tumor is larger than 2.5 cm. Cure is rarely achieved by surgical resection in patients with MEN 1; however, it may reduce the risk of subsequent metastatic disease.\r\n\"	Because this is a rare tumor, surgical resection should be attempted only at centers with personnel experienced in treating patients with ZES.\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('891', 'TUBERCULOSIS LUNG', '0', '', 'OTHER TESTS :\r\n* SPUTUM FOR AFB. IF SPUTUM IS NOT COMING OUT THAN BRONCHIAL LAVAGE CAN BE DONE.\r\n* * AMLIFIED MYCOBACTERIUM TUBERCULOSIS DIRECT TEST PERFORMED ON RESPIRATORY SPECIMENS AS WELL AS  NON-RESPIRATORY SPECIMENS LIKE - GEN-PROBE &  AMPLICOR\r\n* TB RNA DETECTION BY TMA METHOD - IS IMPROVED PCR WHICH DETECTS LIVE BACILLI ONLY & 93% SENSITIVE & 99.1% SPECIFIC.\r\n* TB DNA DETECTION BY REAL TIME PCR : SPECIFIC FOR MYCOBACTERIUM TUBERCULOSIS WHICH GAURANTEE NO FALSE NEGATIVITY DUE TO INTERNAL CONTROL.\r\n* MYCOBACTERIUM DIFFERENTIATION BY TMA SYSTEM : IT DIFFERENTIATES MYCOBACTERIUM TUBERCULOSIS BACTERIA FROM OTHER MYCOBACTERIUM SPECICIES & IS IMPROVED PCR TEST.\r\n* TB GOLD TEST : IT DETECTS INTERFERON GAMMA PRODUCED BY SENSITIZED T4 CELLS & IS HIGHLY SENSITIVE (90%) & SPECIFIC ( 98%). UNAFFECTED BY BCG VACCINATION & NTM INFECTION.\r\nT SPOT-TB TEST : LIKE TB GOLD TEST IS HIGHLY SPECIFIC & SENSITIVE, BASED ON RD1 ANTIGENS.', '0', '0', '1', '0', '0', '', 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('913', 'HYPERTENSION , SECONDARY', '0', 'CLASSIFICATION OF HYPERTENSION:\r\n\r\n1. SYSTOLIC HYPERTENSION WITH WIDE PULSE PRESSURE\r\n\r\n* DECREASED COMPLIANCE OF AORTA( ARTERIOSCLEROSIS)\r\n* INCREASED STROKE VOLUME\r\n- AORTIC REGURGITATION\r\n- THYROTOXICOSIS\r\n- HYPERKINETIC HEART SYNDROME\r\n- FEVER\r\n- ARTERIOVENOUS FISTULA\r\n- PATENT DUCTUS ARTERIOSUS\r\n\r\n2. SYSTOLIC & DIASTOLIC HYPERTENSION\r\n\r\nA. RENAL\r\n- CHRONIC PYELONEPHRITIS\r\n- AC & CHR GLOMERULONEPHRITIS\r\n- POLYCYSTIC RENAL DISEASE\r\n- COLLAGEN DISEASE LIKE POLYARTERITIS NODOSA , SCLERODERMA , SLE\r\n- ANALGESIC NEPHROPATHY\r\n- HEREDITARY NEPHRITIS\r\n- GOUTY NEPHROPATHY\r\n- IRRADIATION NEPHROPATHY\r\n- AMYLOIDOSIS\r\n- RENAL TUBERCULOSIS\r\n- URINARY TRACT OBSTRUCTION ( UNUSUAL )\r\n- HEAVY METAL POISONING ( LEAD, CADMIUM ) \r\n- INTRINSIC PRESSURE FROM TUMOR OR CYSTS\r\n- EXTRINSIC PRESSURE FROM TUMOR, FIBROUS OR MUSCULAR BANDS\r\n- FIBROMUSCULAR DYSPLASIA\r\n- RENOVASCULAR STENOSIS OR RENAL INFARCT\r\n- MOST OTHER SEVERE RENAL DISEASES ( ARTERIOLAR NEPHROSCLEROSIS , DIABETIC NEPHROPATHY ETC.\r\n- RENIN PRODUCING TUMORS\r\n\r\nB. ENDOCRINE \r\n* ORAL CONTRACEPTIVES\r\n* ADRENOCORTICAL HYPERFUNCTION\r\n- CUSHING DISEASE & SYNDROME\r\n- PRIMARY HYPERALDOSTERONISM\r\n- CONGENITAL OR HEREDITARY ADRENOGENITAL SYNDROMES ( 17 ALPHA-HYDROXYLASE & 11 BETA HYDROXYLASE DEFECTS )\r\n- PHEOCHROMOCYTOMA\r\n- MYXEDEMA\r\n- ACROMEGALY\r\n- LIDDLE SYNDROME\r\n- ISOLATED SECRETION OF DEOXYCORTICOSTERONE , CORTICOSTERONE , 18-HYDROXY-DEOXYCORTICOSTERONE\r\nC. NEUROGENIC\r\n- PSYCHOGENIC\r\n- DIENCEPHALIC SYNDROME\r\n- FAMILIAL DYSAUTONOMIA ( RILEY-DAY )\r\n- POLYNEURITIS ( AC PORPHYRIA, LEAD POISONING )\r\n- INCREASED INTRACRANIAL PRESSURE ( ACUTE )\r\n- SPINAL CORD SECTION ( ACUTE )\r\n\r\nD. MISCELLANEOUS\r\n-COARCTATION OF AORTA\r\n- INCREASED INTRAVASCULAR VOLUME ( EXCESSIVE TRANSFUSION, POLYCYTHEMIA VERA)\r\n- POLYARTERITIS NODOSA\r\n- HYPERCALCEMIA\r\n- MEDICATIONS LIKE STEROIDS, CYCLOSPORINE\r\n\r\nE. UNKNOWN ETIOLOGY\r\n- ESSENTIAL HYPERTENSION( > 90% )\r\n- TOXEMIA OF PREGNANCY\r\n- AC INTERMITTENT PORPHYRIA\r\n', 'OTHER TESTS :\r\n* 24 HRS URINARY VMA - INCREASED BUT LESS SENSITIVE & SPECIFIC\r\n* 24 HRS URINARY EPINEPHRINE - INCREASED\r\n* 24 HRS URINARY METANEPHRINES - INCREASED\r\n* 24 HRS URINARY FREE CATECHOLAMINES - INCREASED ( FALSE POSITIVE INCREASE IN METHYLDOPA, LEVODOPA, LABETALOL, SYMPATHOMIMETIC AMINES WHICH MAY ELEVATE CATECHOLAMINE EXCRETION UPTO 2 WKS. OTHER CAUSES ARE HYPOGLYCEMIA, STRENUOUS EXERCISE, CNS DISEASE WITH RAISED INTRA CRANIAL PRESSURE, SEVERE HYPOXIA, CLONIDINE WITHDRAWAL.\r\n* PLASMA CATECHOLAMINES - INCREASED WITH DECREASED RESPONSE TO CLONIDINE & GANGLION BLOCKERS\r\n* DEXAMETHASONE TEST - 1 MG OF DEXAMETHASONE AT BED TIME, FOLLOWED BY MEASUREMENT OF PLASMA CORTISOL AT 7 - 10 A.M. IS BEST SCREENING TEST. A URINE CORTISOL LEVEL OF < 2750 NMOL OR SUPPRESSION OF PLASMA CORTISOL TO < 140 NMOL / L RULES OUT CUSHING SYNDROME\r\n* FOR RENOVASCULAR HYPERTENSION - 1. CAPTOPRIL ENHANCED RADIONUCLIDE RENAL SCAN ( PREFERED CHOICE )\r\n2. DUPLEX FLOW STUDY\r\n3. MRI ANGIOGRAPHY\r\n4. SPIRAL CT SCAN, THE MOST SENSITIVE & SPECIFIC GIVES A THREE DIMENSIONAL VIEW BUT NEEDS I.V. CONTRAST AGENT.\r\n5. DEFINITE TEST FOR SURGICALLY CORRECTABLE RENAL DISEASE IS THE COMBINATION OF RENAL ANGIOGRAM & RENAL VEIN RENIN DETERMINATION.', '0', '0', '0', '1', '0', '', 'B', '0', '- THE RISK OF LVH INCREASES TWO FOLDS BY ASSOCIATED OBESITY.\r\n- CHR. & SEVERE HYPERTENSION CAN CAUSE AORTIC ROOT DILATATION LEADING TO SIGNIFICANT AORTIC REGURGITATION.\r\n- COMMON CARDIAC ARRHYTHMIAS SEEN IN HYPERTENSION ARE ATRIAL FIBRILLATION, VENTRICULAR ECTOPIC & VENTRICULAR TACHYCARDIA.\r\n\r\n* - TREATMENT OF PRIMARY CAUSE MAY TREAT IT FOR ALL TIME.\r\nMedical Care: The medical care of patients with hypertensive heart disease falls under 2 categories-treatment of the elevated BP and prevention and treatment of hypertensive heart disease. The BP goal should be less than 140/90 mm Hg in patients without diabetes or chronic kidney disease and less than 130/90 mm Hg in those with either of these diseases. Various treatment strategies include dietary modifications, regular aerobic exercise, weight loss, and pharmacotherapy directed toward hypertension, heart failure secondary to diastolic and systolic LV dysfunction, coronary artery disease, and arrhythmias. \r\n\"	Dietary modifications \r\no	 Specific diet recommendations include a diet low in sodium, high in potassium (in patients with normal renal function), rich in fresh fruits and vegetables, low in cholesterol, and low in alcohol consumption. \r\no	A low-sodium diet, alone or in combination with pharmacotherapy, has been shown by numerous studies to reduce BP in patients with hypertension, with a more prominent response in a subset of patients with hypertension-mainly African Americans-with low renin levels. Restriction of sodium in these patients does not lead to compensatory stimulation of the renin-angiotensin system and thus has a potent antihypertensive effect. The recommended daily sodium intake is 50-100 mmol, equivalent to 3-6 g of salt per day, which leads to an average 2-8 mm of Hg reduction in BP. \r\no	In various epidemiological studies, a high-potassium diet has been associated with lowering of the BP. The mechanism of this action is not clear. Intravenous infusion of potassium has been shown to cause vasodilatation, which is believed to be mediated by nitric oxide in the vascular wall. Foods rich in potassium, such as fresh fruit and vegetables, should be recommended for patients with normal renal function. \r\no	A diet rich in fresh fruits and vegetables, known as the DASH diet, has been shown to significantly lower the BP (8-14 mm Hg) in patients with hypertension regardless of them maintaining a constant sodium content in their diet. This diet should be advised in patients with hypertension. \r\no	A low-cholesterol diet is part of secondary prophylaxis in patients with coronary artery disease. It is also a part of the primary prophylaxis of coronary artery disease in patients at high risk for this disease. \r\no	Heavy alcohol consumption has been associated with high BP and an increase in LV mass. Moderation in alcohol consumption is advised; no more than 1-2 drinks per day is recommended.\r\n\"	Regular aerobic exercise \r\no	Regular dynamic isotonic exercise, such as walking, running, swimming, or cycling, has been shown to decrease BP and improve cardiovascular well-being. Regular isotonic exercise has additional favorable cardiovascular effects, including improved endothelial function, peripheral vasodilatation, reduced resting heart rate, improved heart rate variability, and reduced plasma levels of catecholamines. \r\no	Regular 30-minute sessions of aerobic exercise 3-4 times a week should be advised. Average reduction in BP with regular aerobic exercise such as walking at least 30 minutes most days of the week is 4-9 mm of Hg. Isometric and strenuous exercise should be avoided.\r\n\"	Weight reduction \r\no	Obesity has been linked to hypertension and LVH in various epidemiological studies, with as many as 50% of obese patients having some degree of hypertension and as many as 60-70% of patients with hypertension being obese. Abdominal adiposity, clinically measured as waist-to-hip ratio and more accurately assessed by abdominal CT scan, is a more sensitive risk factor for hypertension. Studies have shown that weight reduction is one of the most effective ways to reduce BP. A 5-20 mm Hg BP reduction occurs with each 10 kg of weight loss. \r\no	Gradual weight reduction (1 kg/wk) should be advised. Pharmacological interventions to reduce weight should be used with great caution because diet pills, especially those available over the counter, frequently contain sympathomimetics. These can raise BP, worsen angina or symptoms of heart failure, and exacerbate tendencies for cardiac arrhythmias. \r\n\"	Pharmacotherapy \r\no	Treatment of hypertension and hypertensive heart disease can involve the following classes of antihypertensive medications: thiazide diuretics, beta-blockers and combined alpha- and beta-blockers, calcium channel blockers, ACE inhibitors, angiotensin receptor blockers, and direct vasodilators such as hydralazine. Most patients require 2 or more antihypertensive drugs to achieve the BP goal, and, when the BP is more than 20/10 mm Hg above the goal, consider initiating treatment with 2 drugs, either as separate prescriptions or in fixed-dose combinations. \r\no	Thiazide diuretics are the drugs of first choice in most patients with uncomplicated hypertension, as outlined by the Joint National Committee on Prevention, Detection, Evaluation, and Treatment of High Blood Pressure. \r\no	Drugs from other classes can be used in the presence of compelling indications. \r\n\"	Calcium channel blockers are effective for systolic hypertension in elderly patients. \r\n\"	ACE inhibitors are the first choice in patients with diabetes and/or LV dysfunction. \r\n\"	Angiotensin receptor blockers are a reasonable alternative, especially for patients with adverse effects with ACE inhibitors. \r\n\"	Beta-blockers are the drugs of first choice in patients with heart failure due to systolic LV dysfunction, patients with ischemic heart disease with or without a history of myocardial infarction, and in patients with thyrotoxicosis. \r\n\"	Peripheral alpha-channel blockers should be avoided in patients with hypertension in view of recent findings of their adverse effect on cardiovascular morbidity and mortality rates. \r\n\"	Central alpha-antagonists have no evidence-based support and have more adverse effects. \r\no	Intravenous drugs used in patients with a hypertensive emergency include nitroprusside, labetalol, hydralazine, enalapril, and beta-blockers (avoided in patients with acutely decompensated heart failure). \r\n\"	Treatment of LVH \r\no	LVH, a marker of increased risk of cardiovascular morbidity and mortality, should be treated aggressively. Whether regression in LVH leads to improvement in cardiovascular mortality and morbidity rates is not clear, although limited data support this hypothesis. \r\no	All the medications already listed for the treatment of hypertension have been shown to reduce LVH. Limited meta-analysis data suggest a slight advantage to ACE inhibitors.\r\n\"	Treatment of LV diastolic dysfunction \r\no	Certain classes of antihypertensives-ACE inhibitors, beta-blockers, and nondihydropyridine calcium channel blockers-have been shown (although not consistently) to improve echocardiographic parameters in symptomatic and asymptomatic diastolic dysfunction and the symptomatology of heart failure. \r\no	Use diuretics and nitrates with caution in patients with heart failure due to diastolic dysfunction. These drugs may cause severe hypotension by inappropriately decreasing the preload, which is required for adequate LV filling pressures. If diuretics are indicated, delicate titration is necessary. \r\no	Hydralazine has been shown to cause severe hypotension in patients with heart failure due to diastolic dysfunction. \r\no	By increasing the intracellular calcium level, digoxin can worsen LV stiffness. However, a large randomized trial has not shown any increase in mortality rate.\r\n\"	Treatment of LV systolic dysfunction\r\no	Diuretics (predominantly loop diuretics) are used in the treatment of LV systolic dysfunction. \r\no	ACE inhibitors are used for preload and afterload reduction and prevention of pulmonary or systemic congestion. They have been shown to decrease morbidity and mortality rates in patients with heart failure due to systolic dysfunction. The aim should be to use the target dose or the maximum tolerable doses. ACE inhibitors are also indicated in patients with asymptomatic LV dilatation and dysfunction. \r\no	Beta-blockers (cardioselective or mixed alpha and beta), such as carvedilol, metoprolol XL, and bisoprolol, have been shown to improve LV function and decrease rates of mortality and morbidity from heart failure. Recent trials have also shown improvement in outcomes for patients in NYHA class IV heart failure with carvedilol administration. These drugs should be started when the patient has no signs of fluid overload and is in compensated heart failure. Therapy should be initiated with low doses, increasing the dose of the beta-blocker very slowly and closely monitoring the patient for signs of worsening heart failure. \r\no	Low-dose spironolactone has been shown to decrease the rates of morbidity and mortality in patients in NYHA class III or IV heart failure who are already taking ACE inhibitors.\r\n\"	Treatment of cardiac arrhythmias\r\no	Treatment depends upon the specific arrhythmia and the underlying LV function. \r\no	Anticoagulation should be considered in patients with atrial fibrillation.\r\nSurgical Care: Surgical treatment may be necessary for definitive treatment in selected cases of secondary causes for hypertension. \r\nDiet: Specific diet recommendations include a diet low in sodium, high in potassium, rich in fresh fruits and vegetables, low in cholesterol, and low in alcohol intake. \r\nActivity: Regular 30-minute sessions of aerobic exercise 3-4 times a week should be advised. Isometric and strenuous exercise should be avoided. \r\n\r\n\r\nDRUG TREATMENT :\r\n\r\n1. THIAZIDES & RELATED DIURETICS :\r\n\r\n- HYDROCHLORTHIAZIDE\r\n- CHLORTHALIDONE\r\n\r\n2. ALPHA / BETA ADRENERGIC BLOCKING DRUGS :\r\n\r\n- CARVEDILOL\r\n\r\n3. BETA ADRENERGIC BLOCKING DRUGS :\r\n\r\n- BISOPROLOL\r\n- ATENOLOL\r\n- METOPROLOL\r\n\r\n4. ACE INHIBITORS :\r\n\r\n- CAPTOPRIL\r\n- FOSINOPRIL\r\n- RAMIPRIL\r\n\r\n5. ANGIOTENSIN II RECEPTOR BLOCKERS :\r\n\r\n- LOSARTAN\r\n- VALSARTAN\r\n- CANDESARTAN\r\n- IRBESARTAN\r\n- EPROSARTAN\r\n- OLMESARTAN\r\n\r\n6. CALCIUM CHANNEL BLOCKERS, NONDIHYDROPYRIDINES :\r\n\r\n- DILTIAZEM\r\n- VERAPAMIL\r\n\r\n7. CALCIUM CHANNEL BLOCKERS, DIHYDROPYRADINES :\r\n\r\n- AMLODIPNE\r\n- FELODIPINE\r\n- NIFEDIPINE\r\n\r\n8. PERIPHERAL VASODILATOR:\r\n\r\n- HYDRALAZINE\r\n\r\n9. ALDOSTERONE ANTAGONIST :\r\n\r\n- SPIRONOLACTONE  \r\n', NULL, NULL, NULL, NULL, '1'),
('915', 'ABDOMINAL PAIN', '0', 'CAUSES OF ABDOMINAL PAIN :\r\n\r\nABDOMINAL PAIN, ACUTE - LOCALIZED\r\n\r\n1. GASTRODUODENAL\r\n\r\n- GASTRIC OR DUODENAL ULCER, PERFORATED\r\n- GASTRIC CARCINOMA, PERFORATED\r\n- GASTRITIS, ACUTE\r\n- IRRITANT POISONS\r\n\r\n2. INTESTINAL\r\n\r\n- SMALL BOWEL OBSTRUCTION\r\n- REGIONAL ILEITIS( CROHNS DISEASE )\r\n- INTUSSUSCEPTION\r\n- SIGMOID VOLVULUS\r\n- ACUTE COLONIC DIVERTICULITIS\r\n- LARGE BOWEL OBSTRUCTION DUE TO NEOPLASM\r\n- STRANGULATED EXTERNAL HERNIA\r\n- AC MESENTERIC OCCLUSION DUE TO ARTERIAL EMBOLISM , THROMBOSIS OR TO VENOUS THROMBOSIS\r\n\r\n3. APPENDIX\r\n\r\n- ACUTE APPENDICITIS\r\n- COLIC DUE TO FAECOLITH\r\n\r\n4. PANCREAS\r\n\r\n- ACUTE PANCREATITIS\r\n- RECURRENT PANCREATITIS\r\n- PANCREATIC TRAUMA\r\n\r\n5. GALL BLADDER & BILE DUCT\r\n\r\n- CALCULUS IN GALL BLADDER OR CBD\r\n- ACUTE CHOLECYSTITIS\r\n- ACUTE CHOLANGITIS\r\n\r\n6. LIVER\r\n\r\n- TRAUMA\r\n- ACUTE HEPATITIS\r\n- MALIGNANT DISEASE PRIMARY OR SECONDARY\r\n- CONGESTIVE CARDIAC FAILURE\r\n\r\n7. SPLEEN \r\n\r\n- TRAUMA\r\n- SPONTANEOUS RUPTURE ( IN MALARIA OR INFECTIOUS MONONUCLEOSIS )\r\n- INFARCTION\r\n\r\n\r\n8. URINARY TRACT\r\n\r\n- RENAL, URETERIC OR VESICLE CALCULUS\r\n- RENAL TRAUMA\r\n- PYELONEPHRITIS\r\n- PYONEPHROSIS\r\n\r\n9. FEMALE GENITALS\r\n\r\n- SALPINGITIS\r\n- PYOSALPINX\r\n- ECTOPIC PREGNANCY\r\n- TORSION OF SUBSEROUS FIBROID\r\n- RED DEGENERATION OF FIBROID\r\n- TWISTED OVARIAN CYST\r\n- RUPTURED OVARIAN CYST\r\n\r\n10. AORTA\r\n\r\n- RUPTURED ANEURYSM\r\n- DISSECTING ANEURYSM\r\n\r\n11. REFERED PAIN FROM OTHER STRUCTURES\r\n\r\n- HERPES ZOSTER\r\n- PAIN DUE TO COMPRESSION OF NERVE ROOTS DUE TO PROLAPSED INTERVERTIBRAL DISC, POTTS SPINE, TRAUMA SPINE OR SECONDARIES\r\n- MYOCARDIAL INFARCTION\r\n- ACUTE PERICARDITIS\r\n- AC DIAPHRAGMATIC PLEURISY', 'OTHER TESTS :\r\n* UPPER GI ENDOSCOPY - CAN DIAGNOSE AC GASTRITIS , PEPTIC ULCERS, CANCER\r\n* ULTRA SOUND WHOLE ABDOMEN - CAN REVEAL GAS UNDER DOME OF DIAPHRAGM IN CASE OF PERFORATION , SECONDARIES IN ABDOMEN IN CASE OF CARCINOMA , PANCREATITIS , INTESTINAL OBSTRUCTION, ANY INTRA ABDOMINAL TUMOUR, INTUSSUSCEPTION, STRANGULATED EXTERNAL HERNIA , APPENDICULAR LUMP, GALL BLADDER PATHOLOGIES, LIVER PATHOLOGIES, SPLEENIC RUPTURE, RENAL PATHOLOGIES, ECTOPIC PREGNANCY, SALPINGITIS, FIBROID, TWISTED OR RUPTURED OVARIAN CYST ETC\r\n* X-RAY ABDOMEN ERECT - GAS UNDER DOME OF DIAPHRAGM IN CASE OF PERFORATION. > 3 FLUID LEVELS IN CASE OF INTESTINAL OBSTRUCTION \r\n* LDH & SERUM AMYLASE - HIGH IN PANCREATITIS\r\n* COLONOSCOPY - LARGE BOWEL TUMOURS , INTUSSUSCEPTION\r\n* ABDOMINAL COLOR DOPPLER - MESENTERIC ARTRY THROMBOSIS , RUPTURED ANEURYSM OR DISSECTING ANEURYSM\r\n* URINE ROUTINE - PYONEPHROSIS , CALCULUS , PYELONEPHRITIS , TRAUMA.\r\nCT SCAN ABDOMEN - CAN DISGNOSE TUMOURS , ANEURYSM , LIVER OR ALL ABDOMINAL PATHOLOGIES.\r\n* ECG - AC MYOCARDIAL INFARCTION IN CASE OF REFERRED PAIN IN ABDOMEN\r\n* LIVER FUNCTION TEST - ABNORMAL IN LIVER DISEASES\r\n* STOOL ROUTINE - OVA / CYST , OCCULT BLOOD IN CASE OF G.I. BLEEDING', '0', '0', '0', '0', '0', '', 'B', '0', 'MEDICAL TREATMENT :\r\n\r\n1. ANTISPASMODICS\r\n\r\n- DICYCLOMINE\r\n- DROTAVERINE\r\n- CAMYLOFIN \r\n- OXYPHENONIUM BROMIDE\r\n- FENPIVERINIUM BROMIDE\r\n\r\n2. SPECIFIC TREATMENT WOULD DEPEND ON THE CAUSE OF ABDOMINAL PAIN', NULL, NULL, NULL, NULL, '1'),
('928', 'BREAST LUMP', '0', 'D.D. :\r\nA. SWELLING OF THE WHOLE BREAST\r\n\r\n1. BILATERAL\r\n\r\n- PREGNANCY\r\n- LACTATION\r\n- ABNORMALITY OF NORMAL DEVELOPMENT & INVOLUTION\r\n- HYPERTROPHY\r\nIN MALES FROM STILBOESTROL ADMINISTRATION\r\n- AC MASTITIS\r\n\r\n2. UNILATERAL\r\n\r\n- FIBRO-ADENOSIS OF THE NEWBORN\r\n- PUBERTY\r\n- UNILATERAL HYPERTROPHY\r\n\r\nB. DISCRETE LUMPS IN BREAST\r\n\r\n1. BENIGN\r\n\r\n- FIBRO-ADENOMA\r\n- SIMPLE CYST\r\n- GALACTOCELE\r\n- LIPOMA\r\n- PLASMA CELL MASTITIS\r\n- FAT NECROSIS ( RARE )\r\n- TUBERCULOSIS ( RARE )\r\n- PHYLLOIDES TUMOR ( RARE )\r\n\r\n2. MALIGNANT\r\n\r\n- CARCINOMA\r\n- SARCOMA ( RARE )\r\n- LYMPHOMA ( RARE )\r\n', '', '0', '0', '0', '0', '0', '', 'B', '0', '* - ADVISED MAMOGRAPHY & FNAC OF THE LUMP\r\n', NULL, NULL, NULL, NULL, '1'),
('1022', 'ACCIDENTAL INJURY', '0', '', '', '0', '0', '0', '0', '0', '', 'B', '0', '', NULL, NULL, NULL, NULL, '1'),
('1060', 'INTERSTITIAL LUNG DISEASE', '0', 'CAUSES :\r\n (LUNG RESPONSE : ALVEOLITIS, INTERSTITIAL INFLAMMATION & FIBROSIS)\r\n\r\n1. KNOWN CAUSES :\r\n\r\n- ASBESTOS\r\n- FUMES , GASES\r\n- DRUGS ( ANTIBIOTICS, AMIODARONE, GOLD) , CHEMOTHERAPY DRUGS LIKE BLEOMYCIN, RADIATION\r\n- ASPIRATION PNEUMONIA\r\n- RESIDUAL OF ADULT RESPIRATORY DISTRESS SYNDROME\r\n\r\n2. UNKNOWN CAUSES :\r\n\r\nA - IDIOPATHIC INTERSTITIAL PNEUMONIAS\r\n\r\n- IDIOPATHIC PULMONARY FIBROSIS ( USUAL INTERSTITIAL PNEUMONIA )\r\n- DESQUAMATIVE INTERSTITIAL PNEUMONIA\r\n- RESPIRATORY BRONCHIOLITIS - ASSOCIATED INTERSTITIAL LUNG DISEASE\r\n- ACUTE INTERSTITIAL PNEUMONIA( DIFFUSE ALVEOLAR DAMAGE )\r\n- CRYPTOGENIC ORGANISING PNEUMONIA ( BRONCHIOLITIS OBLITERANS WITH ORGANISING PNEUMONIA )\r\n- NONSPECIFIC INTERSTITIAL PNEUMONIA\r\n\r\nB.- CONNECTIVE TISSUE DISEASES\r\n\r\n- SYSTEMIC LUPUS ERYTHEMATOSUS\r\n- RHEUMATOID ARTHRITIS\r\n- ANKYLOSING SPONDYLITIS\r\n- SYSTEMIC SCLEROSIS\r\n- SJOGREN SYNDROME\r\n- POLYMYOSITIS-DERMATOMYOSITIS\r\n\r\nC. PULMONARY HAEMORRHAGE SYNDROMES\r\n\r\n- GOODPASTURE SYNDROME\r\n- IDIOPATHIC PULMONARY HAEMOSIDEROSIS\r\n- ISOLATED PULMONARY CAPILLARITIS\r\n\r\nD. PULMONARY ALVEOLAR PROTEINOSIS\r\n\r\nE. LYMPHOCYTIC INFILTRATIVE DISORDERS ( LYMPHOCYTIC INTERSTITIAL PNEUMONITIS ASSOCIATED WITH CONNECTIVE TISSUE DISEASE)\r\n\r\nF. EOSINOPHILIC PNEUMONIAS\r\n\r\nG. LYMPHANGIOLEIOMYOMATOSIS\r\n\r\nH. AMYLOIDOSIS\r\n\r\nI. INHERITED DISEASES\r\n\r\n- TUBEROUS SCLEROSIS\r\n- NEUROFIBROMATOSIS\r\n- NIEMANN-PICK DISEASE\r\n- GAUCHER DISEASE\r\n- HERMANSKY-PUDLAK SYNDROME\r\n\r\nJ. GASTROINTESTINAL OR LIVER DISEASE\r\n\r\n- CROHNS DISEASE\r\n- PRIMARY BILIARY CIRRHOSIS\r\n- CHRONIC ACTIVE HEPATITIS\r\n- ULCERATIVE COLITIS\r\n\r\nH. GRAFT VS. HOST DISEASE \r\n\r\n- BONE MARROW TRANSPLANTATION\r\n- SOLID ORGAN TRANSPLANTATION\r\n\r\n( LUNG RESPONSE : GRANULOMATOUS )\r\n\r\n1. KNOWN CAUSES\r\n\r\n- HYPERSENSITIVITY PNEUMONITIS ( ORGANIC DUST )\r\n- INORGANIC DUST ( BERYLLIUM, SILICA )\r\n\r\n2. UNKNOWN CAUSES \r\n\r\n- SARCOIDOSIS\r\n- LANGERHANS CELL GRANULOMATOSIS ( EOSINOPHILIC GRANULOMA OF LUNG )\r\n- GRANULOMATOUS VASCULITIDES LIKE WEGENER GRANULOMATOSIS , ALLERGIC GRANULOMATOSIS OF CHURG-STRAUSS\r\n- BRONCHOCENTRIC GRANULOMATOSIS\r\n- LYMPHOMATOID GRANULOMATOSIS \r\n\r\n\r\n\r\n', '* SERUM LDH - RAISED ALTHOUGH NON-SPECIFIC\r\n* ANTI-BASEMENT MEMBRANE OR ANTI-NEUTROPHIL CYTOPLASMIC ANTIBODIES - MAY BE POSITIVE IN VASCULITIS\r\n* X-RAY CHEST - BIBASILAR RETICULAR PATTERN OR NODULAR OR MIXED PATTERN OF ALVEOLAR FILLING & INCREASED RETICULAR MARKINGS. HONEYCOMBING PORTENDS POOR PROGNOSIS.\r\n* HIGH RESOLUTION-CONTRAST CT CHEST : DIAGNOSTIC \r\n* LUNG BIOPSY\r\n* TECNITIUM-99 (DTPA ) IS AN INDEX OF PUL EPITHELIAL PERMEABILITY, NORMAL CLEARANCE PREDICTS STABLE DISEASE WHILE RAPID CLEARANCE SHOWS RISK FOR DETERIORATION.\r\n* PULMONARY FUNCTION TEST - RESTRICTIVE DEFECT WITH REDUCED TOTAL LUNG CAPACITY, FUNCTIONAL RESIDUAL CAPACITY & RESIDUAL VOLUME.\r\n* ARTERIAL BLOOD GASES - NORMAL OR REVEAL HYPOXEMIA. CO2 RETENTION SIGNIFIES END STAGE DISEASE.\r\n* CARDIOPULMONARY EXCERCISE TESTING - ABNORMAL . ALSO USEFUL IN ASSESSING THE PROGRESSION OF DISEASE.\r\n* BRONCHOALVEOLAR LAVAGE FOR CELLULAR ANALYSIS IS USEFUL IN DIFFERENTIAL DIAGNOSIS.', '0', '0', '0', '0', '0', '', 'B', '7', 'SYNONYMS OR OTHER RELATED DISEASES UNDER THIS : DIFFUSE PARENCHYMAL LUNG DISEASE, IDIOPATHIC INTERSTITIAL FIBROSIS(IPF), DESQUAMATIC INTERSTITIAL PNEUMONIA(DIP), RESPIRATORY BRONCHIOLITIS INTERSTITIAL LUNG DISEASE(RBILD), ACUTE INTERSTITIAL PNEUMONITIS (AIP), NONSPECIFIC INTERSTITIAL PNEUMONITIS (NSIP), CRYPTOGENIC ORGANISING PNEUMONIA (COP), LYMPHOCYTIC INTERSTITIAL PNEUMONIA (LIP), SARCOIDOSIS, HYPERSENSITIVITY PNEUMONIA (HSP), PULMONARY LANGERHANS CELL HISTIOCYTOSIS (PLCH), LYMPHANGIOLEIOMYOMATOSIS (LAM). \r\n\r\nMedical Care: \r\n\"	Treatment is best determined by the specific diagnosis. Unfortunately, a specific etiology often is not determined. General supportive measures include the following:\r\no	Smoking cessation should be counseled. \r\no	Good pulmonary hygiene is important. \r\no	Supplemental oxygen therapy may be useful for any patients who demonstrate significant hypoxemia (SaO2 <89% or PaO2 <55 mm Hg while breathing room air). \r\no	If inhalational exposures are thought to be the etiology (occupational), removal from exposure is prudent. \r\no	If a toxic medication is suspected, its discontinuation is mandated.\r\no	Respiratory infections should be treated promptly.\r\n\"	Pharmacologic therapy with corticosteroids (eg, prednisone) and/or cytotoxic agents for their potential steroid-sparing effect (eg, cyclophosphamide, azathioprine, or methotrexate) may be indicated for specific diagnoses.\r\n\"	Other immunosuppressive or antifibrotic agents such as colchicine, cyclosporine, and D-penicillamine may have a role in specific cases. Empiric use of these medications without a specific diagnosis should be discouraged because they have significant toxicities.\r\no	Interferon-gamma-1b, pirfenidone, and acetylcysteine have recently been studied for treatment of IPF. Interferon-gamma-1b initially appeared to have a favorable effect. This, however, was not supported in a larger follow-up study. There is some evidence to suggest that pirfenidone and acetylcysteine may have some benefit in IPF. Further investigation is still needed, particularly in other forms of DPLD.\r\nSurgical Care: \r\n\"	Surgery in the form of either thoracoscopic (preferred) or open lung biopsy is indicated to obtain tissue specimens for definitive diagnosis.\r\n\"	More recently, lung transplantation has become a treatment option for selected patients with advanced disease.\r\no	Survival rates worldwide after single lung transplantation are approximately 74% at 1 year, 58% at 3 years, 47% at 5 years, and 24% at 10 years. \r\no	Survival rates are lower for bilateral lung transplantation.\r\no	Following transplantation, patients overall report improved quality of life with better physical, social, and general health functioning.\r\nDiet: \r\n\"	No specific dietary restrictions are warranted for affected patients.\r\n\"	Some suggest that antioxidants have a therapeutic benefit.\r\nActivity: \r\n\"	Encourage exercise and pulmonary rehabilitation because they may improve a patient\'s functional status. However, these activities generally have no effect on disease progression.\r\n\r\n\r\n', NULL, NULL, NULL, NULL, '1'),
('1201', 'MULTIPLE ENDOCRINE NEOPLASIA TYPE 2A', '0', 'MULTIPLE ENDOCRINE NEOPLASIA TYPE 2A COMPRISES : ( SOME TIMES TRANSMITTED AS AUTOSOMAL DOMINANT DISEASE )\r\n\r\n- HYPERPLASIA OR NEOPLASTIC TRANSFORMATION OF THYROID PARAFOLLICULAR CELLS ( MEDULLARY CARCINOMA OF THYROID GLAND) & ADRENAL MEDULLA ( PHEOCHROMOCYTOMA ) , MAY ALSO HAVE PARATHYROID HYPERPLASIA. DOES NOT HAVE PHENOTYPIC ABNORMALITIES OF MUCOSAL NEUROMAS & MARFANOID HABITUS FOUND IN MEN 2B', '* PENTAGASTRIN STIMULATION TEST - TO DIAGNOSE MEDULLARY CARCINOMA OF THYROID GLAND\r\n* 24 HR. URINARY CATECHOLAMINES, VMA & METANEPHRINES LEVELS - MARKEDLY INCREASED, IF PHEOCHROMOCYTOMA PRESENT\r\n* GENETIC SCREENING\r\n* SERUM CALCIUM & PARATHYROID LEVELS\r\n* SERUM CALCITONIN LEVELS - INCREASED IN MEDULLARY CARCINOMA OF THYROID\r\n* 24 HR URINE CALCIUM LEVELS - LOW IN FAMILIAL HYPOCALCIURIC HYPERCALCEMIC SYNDROME \r\n* CT OR MRI FOR IMAGING ADRENALS\r\n* CT OR MRI OR LAPROSCOPY FOR SPREAD OF METASTASIS\r\n* METAIODOBENZYLGUANIDINE SCAN FOR LOCALISING PHEOCHROMOCYTOMA\r\n* FNAC OF THYROID SWELLING\r\n* RADIONUCLIDE SCANNING - TO SEE EXTENT OF METASTASIS\r\n* OCTREO ( SOMATOSTATIN ANALOGUE SCTREOTIDE ) SCAN - PROVIDES WHOLE BODY SCAN FOR SPREAD OF METASTASIS', '1', '0', '0', '0', '1', 'AN AUTOSOMAL DOMINANT DISEASE. GENETIC TESTING & CLINICAL SURVEILLANCE BEGINING IN CHILDHOOD PROVIDE THE OPPORTUNITY TO TREAT FATAL COMPLICATIONS OF THIS DISORDER. PROPHYLACTIC THYROIDECTOMY BY AGE 5 IN CHILDREN WITH \"RET\" MUTATION IS ADVISABLE.', 'B', '0', 'PATIENT AT RISK BE DIAGNOSED WHILE STILL IN THE C- CELL HYPERPLASIA STAGE. TOTAL THYROIDECTOMY PRECLUDES MALIGNANT DEGENERATION & METASTASES. DO PENTAGASTRIN STIMULATION TEST.\r\n\r\nMedical Care\r\nMEN 2A is treated with surgery. Preoperative medical treatment may consist of prostaglandin inhibitors to alleviate diarrhea that may be associated with medullary thyroid cancer.\r\nPreoperatively, prepare patients with pheochromocytomas by treating them with an alpha-blocker for at least 2 weeks, after which consider administration of a beta-blocker. Reports of successful management using a calcium channel blocker rather than an alpha-blocker have been noted. Many practitioners routinely treat patients with a beta-blocker, while others selectively treat patients based on blood pressure control and tachycardia.\r\nPatients presenting with severe hypercalcemia should first be hydrated, after which they should be treated with furosemide. If they remain severely hypercalcemic, consider treatment with calcitonin, mithramycin, glucocorticoids, or bisphosphonates such as pamidronate.\r\nThese patients need urgent parathyroidectomy when calcium levels have been lowered, ideally below 14 mg/dL.\r\nEvaluation for pheochromocytomas is important because these should be removed before other surgical interventions. This can be performed before parathyroidectomy or thyroidectomy under a single general anesthetic if the patient is stable.\r\n\"	Evaluation includes screening for mutations in the RET gene. \r\n\"	\r\n\"	Thyroid hormone supplementation is necessary following total thyroidectomy in carriers of RET mutations or following a diagnosis of MTC. Patients who have been diagnosed with MTC require serial calcitonin (+/- provocative testing) and carcinoembryonic antigen (CEA) testing to assess for persistent or recurrent disease. \r\n\"	\r\n\"	Start annual 24-hour urine collections for catecholamine concentrations to detect pheochromocytoma at the earliest age possible. \r\n\"	\r\n\"	Begin annual testing of serum calcium and PTH levels at age 10 years. \r\nSurgical Care\r\n\"	Medullary thyroid carcinoma \r\n\"	\r\no	The advent of genetic analysis has negated the need for pentagastrin stimulation testing to identify patients with hereditary MTC. Carefully screen patients without a family history for pheochromocytoma and hyperparathyroidism because almost 19% of sporadic cases of MTC are index MEN 2A cases. \r\no	Calcitonin and CEA determinations remain useful serologic tests to identify recurrent disease. With nearly 100% penetrance of MTC in MEN 2A patients, surgical intervention is recommended in all patients who are identified to carry the MEN2A gene. With genetic analysis available, these patients are often found to have an earlier stage of disease, with many patients having only parafollicular C-cell hyperplasia. \r\no	Total thyroidectomy has been recommended for patients as young as age 5 years for MEN 2A if they contain the genetic mutation. In patients with the RET genetic mutation for MEN 2B, total thyroidectomy is recommended in infancy because MTC behaves more aggressively in these patients. \r\no	In contrast to patients who have sporadic cases of MCT with solitary tumors, patients with MEN 2A have bilateral and multifocal disease. \r\no	The extent of surgery is controversial. Total thyroidectomy with central neck dissection is recommended for all patients with proven or probable MTC. The need for either a unilateral or a bilateral modified neck dissection is controversial. The inclusion of a modified neck dissection has been recommended for patients with palpable jugular chain lymphadenopathy. Some surgeons advocate a routine modified neck dissection. Others sample the jugular chain at operation with frozen section, proceeding with dissection only with histologic evidence of metastatic disease. \r\no	Children often do not require a node dissection because their disease is at the hyperplasia stage and has not reached metastatic potential. \r\no	The treatment of persistent or recurrent elevations of calcitonin with random testing or following pentagastrin stimulation has been a clinical dilemma. Some investigators have found calcitonin levels to remain stable for approximately 5 years and have recommended surgical excision only for clinically apparent disease. Others have found that 66% of patients with node-positive disease died secondary to MCT and advocate a more aggressive approach to follow-up care and surgery. \r\no	Patients undergoing prophylactic thyroidectomy do not require lymphadenectomy. \r\n\"	Parathyroid disease \r\n\"	\r\no	Hyperparathyroidism is the least common manifestation of MEN 2A. It usually manifests in patients older than 30 years. Histologically, the parathyroid glands in MEN 2A patients consist of a chief-cell hyperplasia. This hyperplasia is asymmetrical in terms of parathyroid size. To reduce the risk of postoperative hypocalcemia, remove only grossly abnormal parathyroid glands. If all parathyroid glands are enlarged, a subtotal parathyroidectomy is advocated, leaving an approximately 60-mg remnant. Perform a cervical thymectomy because of the increased risk of supernumerary parathyroid glands. \r\no	Persistent or recurrent hyperparathyroidism is unusual and less likely to occur in MEN 2A patients than in MEN 1 patients. \r\n\"	Pheochromocytoma \r\n\"	\r\no	Screen all MEN 2A patients for pheochromocytomas. This screening should consist of a 24-hour urine collection for catecholamines, and metanephrine. Localization studies are not necessary unless biochemical evidence is consistent with pheochromocytoma. \r\no	While all MEN 2A patients may have bilateral adrenal medullary hyperplasia, the tumors may or may not be present bilaterally at the time of initial operation. In this situation, a unilateral adrenalectomy avoids the risk of Addisonian crisis and improves the quality of life by not requiring replacement therapy. Some investigators have advocated bilateral adrenalectomy in all patients. These proponents argue for the risk of malignancy (rare) and the operative complications from subsequent surgeries. The advent of laparoscopic adrenalectomy has substantially decreased the morbidity of adrenalectomy. A subtotal adrenalectomy can be performed to preserve adrenal cortical function, but the risk for recurrence may be increased. \r\no	Remember that one fourth of patients with apparently sporadic pheochromocytoma may be carriers of mutations characteristic of syndromes associated with pheochromocytomas. \r\n\r\nDRUG TREATMENT : PT REQUIRE HORMONE REPLACEMENT THERAPY WHEN TOTAL THYROIDECTOY & BILATERAL ADRENALECTOMY IS DONE OR WHEN THEY HAVE POSTOPERATIVE HYPOPARATHYROIDISM.\r\n\r\n1. THYROID HORMONE :\r\n\r\n- LEVOTHYROXINE\r\n\r\n2. VIT D SUPPLEMENTS :\r\n\r\n- CALCITRIOL\r\n\r\n3. CORTICOSTEROIDS :\r\n\r\n- CORTISONE\r\n\r\n4. MINERALOCORTICOIDS :\r\n\r\n- FLUDROCORTISONE\r\n', NULL, NULL, NULL, NULL, '1'),
('1208', 'HYPOPITUITARISM ( PANHYPOPITUITARISM )', '0', 'THE DISEASE MAY INVOLVE ONE OR MORE PITUITARY HORMONES LIKE \r\nACTH, FSH, LH, GH, PROLACTIN, TSH, ADH\r\n\r\nCAUSES :\r\n\r\nCAUSES IN CHILDREN :\r\n\r\n1. CONGENITAL\r\n\r\n- DEFECTIVE PITUITARY DEVELOPMENT LEADING TO PITUITARY APLASIA\r\n- EMPTY SELLA\r\n- ENCEPHALOCELE\r\n- MIDLINE DEFECTS\r\n- SEPTOOPTIC DYSPLASIA\r\n- GENETIC ABNORMALITIES INCLUDING AUTOSOMAL RECESSIVE, AUTOSOMAL DOMINANT OR SEX LINKED DEFECTS OR A MUTATION OR DELETION IN THE GH GENE OR IN GH-RELEASING HORMONE\r\n\r\n2. ACQUIRED CONDITIONS\r\n\r\n- TUMORS OF HYPOTHALAMIC-PITUITARY REGION\r\n- CRANIAL IRRADIATION\r\n- INFILTRATIVE DISEASES\r\n- TRAUMA\r\n- HYPOXIC INSULT\r\n- IDIOPATHIC\r\n\r\nCAUSES IN ADULTHOOD\r\n\r\n*  > 90% HAVE PITUITARY DISEASE LIKE \r\n- TUMOR LIKE\r\n*  CRANIOPHARYNGIOMA\r\n*  ADENOMA\r\n- SURGERY\r\n- IRRADIATION\r\n- ISCHEMIA OR INFARCTION LIKE\r\n* SHEEHAN SYNDROME\r\n* APOPLEXY\r\n- TRAUMA\r\n-  INFILTRATIVE DISEASES LIKE\r\n* SARCOIDOSIS\r\n* HISTIOCYTOSIS X DISEASE\r\n* HEMOCHROMATOSIS\r\n-  INFECTIONS LIKE\r\n* TUBERCULOSIS\r\n* SYPHILIS\r\n* MENINGITIS\r\n- AUTOIMMUNE \r\n* LYMPHOCYTIC INFILTRATION ( LYMPHOCYTIC HYPOPHYSITIS )\r\n\r\n--------------------------------------------------------------------------\r\n\r\nD.D. :\r\n\r\n- HYPOTHYROIDISM\r\n- KALLMANN SYNDROME & IDIOPATHIC HYPOGONADOTROPIC HYPOGONADISM\r\n- PITUITARY MACROADENOMAS\r\n- PITUITARY MICROADENOMAS\r\n- POLYGLANDULAR AUTOIMMUNE SYNDROME, TYPE I\r\n- POLYGLANDULAR AUTOIMMUNE SYNDROME, TYPE II\r\n- POLYGLANDULAR AUTOIMMUNE SYNDROME, TYPE III', 'INVESTIGATIONS DEPENDING ON THE INDIVIDUAL HORMONAL INVOLVEMENT OR CAUSE\r\n* ACTH & CORTROSYN STIMULATION TEST\r\n* TSH & THYROXINE\r\n* FSH, LH & EITHER ESTRADIOL OR TESTOSTERONE TEST\r\n* PROLACTIN\r\n* GROWTH HORMONE PROVOCATIVE TESTING', '0', '0', '0', '0', '0', 'RISK FACTORS: Trauma, Pregnancy and delivery', 'B', '0', 'Medical Care\r\nMedical care consists of hormone replacement as appropriate and treatment of the underlying cause.\r\n\"	Glucocorticoids are required if the ACTH-adrenal axis is impaired. This is particularly important in sudden collapse due to pituitary apoplexy or acute obstetric hemorrhage with pituitary insufficiency. In such circumstances, do not delay initiation of a possibly life-saving treatment pending a definitive diagnosis. \r\n\"	\r\n\"	Treat secondary hypothyroidism with thyroid hormone replacement. \r\n\"	\r\n\"	Treat gonadotropin deficiency with sex-appropriate hormones. In men, testosterone replacement is used and modified if the patient desires fertility. In women, estrogen replacement is used with or without progesterone as appropriate. \r\n\"	\r\n\"	GH is replaced in children as appropriate. GH is not routinely replaced in adults unless the patient is symptomatic. \r\nSurgical Care\r\nSurgical care depends on the underlying cause and the severity of hypopituitarism.\r\n\"	In pituitary apoplexy, prompt surgical decompression may be life saving if head imaging reveals tumor mass effect. \r\n\"	\r\n\"	Extirpate macroadenomas that do not respond to medical therapy. \r\nDiet\r\nNo special diet is necessary unless dictated by an underlying disease process. Salt use in adrenal insufficiency may be liberalized in special circumstances (eg, excessive diaphoresis).\r\nActivity\r\nNo restrictions are necessary unless dictated by an underlying disease process.\r\n\r\nDRUG TREATMENT : THE GOAL OF TREATMENT IS TO RESTORE TARGET HORMONES TO PHYSIOLOGICAL LEVELS.\r\n\r\n1. CORTICOSTEROIDS ( GLUCOCORTICOIDS ) :\r\n\r\n- HYDROCORTISONE\r\n\r\n2. THYROID HORMONES :\r\n\r\n- LEVOTHYROXINE\r\n\r\n3. GROWTH HORMONE :\r\n\r\n- HUMAN GROWTH HORMNE, SOMATROPIN\r\n\r\n4. SEX HORMONES :\r\n\r\n- TESTOSTERONE\r\n- OESTROGEN, CONJUGATED ( PREMARIN )\r\n', NULL, NULL, NULL, NULL, '1'),
('1221', 'DYSBETALIPOPROTEINEMIA', '0', 'CAUSES :\r\n\r\n1. PRIMARY CAUSE : \r\n\r\n- HOMOGYGOUS FOR APOLIPOPROTEIN E-2\r\n- GENETIC MUTATION IN APOLIPOPROTEIN E GENE OR COMPLETE ABSENCE PF APOLIPOPROTEIN E\r\n\r\n2. SECONDARY CAUSE :\r\n\r\n- OBESITY\r\n- DIABETES MELLITUS\r\n- HYPOTHYROIDISM\r\n- DRUGS INTAKE LIKE PROTEASE INHIBITORS WHICH CAUSE HYPERLIPIDEMIA', '* LIPID PROFILE - VERY HIGH S. CHOLESTROL ( 300-600 MG% ), TRIGLYCERIDES ( 400-1000 MG% )\r\n* LIPOPROTEIN ELECTROPHORESIS, DENSITY-GRADIENT ULTRA CENTRIFUGATION & NUCLEAR MAGNETIC RESONANCE SPECTROSCOPY CAN ALSO MEASURE VLDL & IDL LEVELS\r\n* SCREENING TEST FOR HYPOTHYROIDISM, DIABETES MELLITUS & NEPHROTIC SYNDROME FOR SECONDARY CAUSES.', '1', '1', '0', '0', '1', 'First-degree relatives should be screened for hyperlipidemia and the risks of cardiovascular disease.', 'B', '0', 'A RARE LIPID DISORDER.  Cholesterol levels usually range from 300-600 mg/dL. Triglyceride concentrations usually are greater than 400 mg/dL and may exceed 1000 mg/dL. \r\nAN ASSOCIATED DIABETES MELLITUS, OBESITY, HYPOTHYROIDISM OR ANOTHER LIPID ABNORMALITY LIKE FAMILIAL COMBINED HYPERLIPIDEMIA.\r\nMEDICAL TREATMENT :\r\n\r\n\"	Patients first should be treated for the metabolic condition that is causing or exacerbating their hyperlipidemia.\r\no	If diabetes is present, glucose levels and glycosylated hemoglobin (HbA1c) should be normalized if possible.\r\no	If hypothyroidism is diagnosed, TSH should be normalized.\r\no	Obesity and inactivity should be addressed appropriately.\r\n \r\n\"	A careful history should be obtained to find other modifiable risk factors for atherosclerosis, such as smoking and hypertension, that can be addressed.\r\n\"	First-degree relatives should be screened for hyperlipidemia and the risks of cardiovascular disease.\r\nSurgical Care\r\n\"	Surgical care is not indicated\r\n\r\nDRUG TREATMENT :\r\n\r\n1. HYLIPIDEMIC :\r\n\r\n- GEMFIBROZIL\r\n- FENOFIBRATE\r\n- NIACIN', NULL, NULL, NULL, NULL, '1'),
('1251', 'CHIKUNGUNYA VIRUS INFECTION', '0', '', '* VIRUS ISOLATION : MOST DEFINITIVE TESTS.\r\n* RT-PCR : REVERSE TRANSCRIPTASE- PCR\r\n* SEROLOGICAL DIAGNOSIS : BY DEMONSTRATING A FOURFOLD INCREASE IN CHIK IGG TITER BETWEEN THE ACUTE AND CONVALESCENT PHASE SERA \r\nOR BY DEMONSTRATING IGM ANTIBODIES SPECIFIC FOR CHIK VIRUS BY IMMUNOGLOBULIN M ANTIBODY (IGM) CAPTURE ENZYME-LINKED IMMUNOSORBENT ASSAY (MAC-ELISA)\r\n* PALTELET COUNT - MILDLY DECREASED\r\n* TLC - MAY BE DECREASED SLIGHTLY\r\n* C-REACTIVE PROTEIN & SGOT, SGPT - MAY BE SLIGHTLY RAISED', '0', '0', '1', '0', '0', 'SPREADS BY MOSQUITO ( A. AEGYPTI ) BITE. INCUBATION PERIOD 2 - 3 DAYS.', 'B', '0', 'TT : SYMPTOMATIC ONLY', NULL, NULL, NULL, NULL, '1'),
('1256', 'PREGNANCY', '0', '', '* TRPLE TEST - ( FOR DETECTING DOWN SYNDROME - TRISOMY 21 & EDWARD SYNDROME-TRISOMY 18 & NEURAL TUBE DEFECTS ) : IN DOWN SYNDROME HCG IS HIGH, AFP LOW & LOW URINE E3 OR HIGH FREE HCG & LOW PAPPA WHILE IN EDWARD SYNDROME HCG LOW, AFP LOW & URINE E3 LOW. IN NURAL TUBE DEFECTS - HCG NORMAL, AFP HIGH & NORMAL OR HIGH URINE E3.\r\n\r\n* CONFIRMATION IS DONE BY - CHROMOSOMAL ANALYSIS / CYTOGENETIC STUDY OF AMNIOTIC FLUID & / OR CHORIONIC VILLUS SAMPLING WHICH HAS UPTO 3% RISK OF PREGNANCY LOSS & INTRAUTERINE INFECTIONS.', '0', '0', '0', '0', '0', '', 'F', '0', '* - ALL SHOULD BE SCREENED FOR GONORRHEA & CLAMYDIAL INFECTION. CEFTRIAXONE & AZITHROMYCIN ARE DRUG OF CHOICE\r\n\r\n* ADVICE HB ELECTROPHORESIS IF ANEMIA WITH REDUCED MCV ( <80 CU MM ) & NORMAL IRON STUDY IS SEEN TO EXCLUDE HAEMOGLOBINOPATHIES.\r\n\r\n* TEST FOR G6PD DEFICIENCY IS ALSO INDICATED IF PATIENT IS ANEMIC.\r\n\r\n* - CARDIAC OUTPUT IS INCREASED BY 40% & B.P. OF 140/90 IS CONSIDERED ABNORMALLY HIGH.\r\n\r\n* - RADIOIODINE SHOULD NOT BE USED FOR EITHER FOR SCANNING OR FOR TREATMENT OF THYROID DURING PREGNANCY\r\n\r\n* - PREGNANT WOMEN DEPLETE THEIR GLYCOGEN STORES QUICKLY & SWITCH FROM CARBOHYDRATE TO FAT METABOLISM WITHIN 12 HRS, OFEN BECOMING KETONEMIC\r\n\r\n* - APPROPRIATE LEVELS OF FOLATE IN MOTHER CAN REDUCE CHANCES OF FETAL NEURAL TUBE DEFECTS.\r\n\r\n* - SMOAKING IN PREGNANCY PLACES INFANT AT INCREASED RISK FOR RESPIRATORY INFECTION, RESTRICTIVE AIRWAY DISEASE & SUDDEN INFANT DEATH SYNDROME\r\n\r\n* - MATERNAL THROMBOCYTOPENIA MAY ALSO BE DUE TO CATASTROPHIC OBSTETRIC EVENTS LIKE RETENTION OF DEAD FETUS, SEPSIS, ABRUPTIO PLACENTA, AMNIOTIC FLUID EMBOLISM\r\n\r\n* - RISK OF STROKE INCREASES IN POSTPARTUM PERIOD\r\n\r\n* - ONSET OF A NEW MOVEMENT DISORDER SUGGESTS CHOREA GRAVIDARUM\r\n\r\n* - EXACERBATION OF GALL BLADDER DISEASE IS COMMONLY SEEN\r\n\r\n* - INTRAHEPATIC CHOLESTASIS OF PREGNANCY IS GENERALLY SEEN IN III TRIMESTER WITH PROFOUND PRURITIS & MAY BE ASSOCIATED WITH INCREASED FETAL MORTALITY. URSODIOL IS DRUG OF CHOICE\r\n\r\n* - ACUTE FATTY LIVER OF PREGNANCY - RARE, CHARACTERIZED BY MARKEDLY INCREASED LEVELS OF BILIRUBIN, AMMONIA & HYPOGLYCEMIA. TREATMENT ONLY SUPPORTIVE\r\n\r\n* - HIV INFECTION : EXPOSURE WHICH INCREASES THE RISK OF MOTHER TO CHILD TRANSMISSION, INCLUDE VAGINAL DELIVERY, PRETERM DELIVERY, TRAUMA TO FETAL SKIN, MATERNAL BLEEDING, RECENT INFECTION WITH HIGH MATERNAL VIRAL LOAD, PROLONGED LENGTH OF MEMBRANE RUPTURE & PRESENCE OF OTHER GENITAL TRACT INFECTIONS LIKE HERPES & SYPHILIS. BREAST FEEDING MAY ALSO TRANSMIT INFECTION.\r\n\r\n* - PREGNANCY WITH DIABETES :\r\n\r\n* - INSULIN IS DRUG OF CHOICE AS ORAL HYPOGLYCAEMICS CAN CAUSE MACROSOMIA & OTHER CONGENITAL DEFECTS.\r\n\r\n* - POSTPRANDIAL HYPERGLYCEMIA IS THE STRONGEST RISK FACTOR FOR MACROSOMIA. THEREFORE TIGHT GLUCOSE CONTROL USUALLT REQUIRE SHORT ACTING INSULIN WITH EACH MEAL WITH MID NIGHT SNACK TO AVOID EARLY MORNING HYPOGLYCEMIA.\r\n\r\n* - RECOMMENDED LABORATORY PARAMETERS DURING PREGNANCY :\r\n- Fasting whole blood glucose level less than 95 mg/dL (5.3 mmol/L)\r\n- One-hour postprandial whole blood glucose level of less than 140 mg/dL (7.8 mmol/L)\r\n- GLYCOSULATED HAEMOGLOBIN LEVEL < 7.0%\r\n\r\n* - BECAUSE OF DELAYED PULMONARY MATURATION OF FETUS, EARLY DELIVERY IS AVOIDED.\r\n\r\n* - PREECLAMPSIA COMPLECATES 20% OF PREGNANCIES IN DIABETICS & RISK IS HIGHER( 50% OR MORE) IN ASSOCIATION WITH HYPERTENSION OR RENAL DISEASE, CESAREAN SECTION ( ~30% ), POLYHYDRAMNIOS (~ 20% )\r\n\r\n* - INSULIN REQUIREMENT REDUCES IN FIRST TRIMESTER DUE TO INCREASED INSULIN SENTIVITY BUT REQUIREMENT IS INCREASED IN 2 & 3 TRIMSTER DUE TO INSULIN RESISTANCE.\r\n\r\n* - IF BREAST FEEDING IS DONE IN THE POSTPARTUM PERIOD, THEN CONTINUE WITH THE INSULIN THERAPY AS ORAL HYPOGLYCEMICS CROSS TO BREAST MILK.\r\n\r\n* - INCIDENCE OF NEONATAL COMPLICATIONS RANGE FROM 12 - 28% IN GDM MOTHERS INFANTS.\r\n\r\n* - 25% OF WOMEN WITH TYPE-1 DIABETES DEVELOP POSTPARTUM THYROID DYSFUNCTION, SO ROUTINE SCREENING SHOULD BE DONE', NULL, NULL, NULL, NULL, '1'),
('1258', 'DIABETES MELLITUS, GESTATIONAL', '0', 'CRITERIA FOR POSITIVE 100 GM OGTT IN GESTATIONAL DIABETES :\r\n\r\nFASTING GLUCOSE - 95 MG %\r\n1-HR GLUCOSE        - 180 MG%\r\n2- HR GLUCOSE       - 155 MG%\r\n3- HR GLUCOSE       - 140 MG%\r\n\r\n\r\nETIOLOGIC CLASSIFICATION OF DIABETES\r\n\r\n1. TYPE- I DIABETES ( BETA- CELL DESTRUCTION, USUALLY LEADING TO ABSOLUTE INSULIN DEFICIENCY )\r\n* IMMUNE MEDIATED\r\n* IDIOPATHIC\r\n\r\n2. TYPE - II DIABETES ( MAY RANGE FROM PREDOMINANTLY INSULIN RESISTANCE WITH RELATIVE INSULIN DEFICIENCY TO A PREDOMINANTLY INSULIN SECRETORY DEFECT WITH INSULIN RESISTANCE )\r\n\r\n3. OTHER SPECIFIC TYPES OF DIABETES\r\n\r\nA. GENETIC DEFECTS OF BETA-CELL FUNCTION CHARACTERISED BY MUTATIONS IN :\r\n\r\n* HEPATOCYTE NUCLEAR TRANSCRIPTION FACTOR ( HNF ) 4 ALPHA ( MODY 1 )\r\n* GLUCOKINASE ( MODY 2 )\r\n* HNF- 1ALPHA ( MODY 3 )\r\n* INSULIN PROMOTER FACTOR ( IPF ) 1 ( MODY 4 )\r\n* HNF-1 BETA ( MODY 5 )\r\n* MITOCHONDRIAL DNA\r\n* PROINSULIN OR INSULIN CONVERSION\r\n\r\nB. GENETIC DEFECTS IN INSULIN ACTION\r\n\r\n* TYPE I INSULIN RESISTANCE\r\n* LEPRECHAUNISM\r\n* RABSON-MENDENHALL SYNDROME\r\n* LIPOATROPHIC DIABETES\r\n\r\nC. DISEASES OF EXOCRINE PANCREAS --\r\n\r\n- PANCREATITIS\r\n- PANCREATECTOMY\r\n- NEOPLASIA\r\n- CYSTIC FIBROSIS\r\n- HEMOCHROMATOSIS\r\n- FIBROCALCULOUS PANCREATOPATHY\r\n\r\nD. ENDOCRINOPATHIES \r\n\r\n- ACROMEGALY\r\n- CUSHING SYNDROME\r\n- GLUCAGONOMA\r\n- PHEOCHROMOCYTOMA\r\n- HYPERTHYROIDISM\r\n- SOMATOSTATINOMA\r\n- ALDOSTERONOMA\r\n\r\nE. DRUGS OR CHEMICAL INDUCED \r\n\r\n-VACOR, PENTAMIDINE , NICOTINIC ACID, GLUCOCORTICOIDS, THYROID HORMONES, DIAZOXIDE, BETA-ADRENERGIC AGONISTS, THIAZIDES, PHENYTOIN, ALPHA INTERFERON, PROTEASE INHIBITORS, CLOZAPINE, BETA BLOCKERS\r\n\r\nF. INFECTIONS \r\n\r\n- CONGENITAL RUBELLA\r\n- CYTOMEGALOVIRUS\r\n- COXSACKIE\r\n\r\nG. UNCOMMON FORMS OF IMMUNE MEDIATED DIABETES \r\n\r\n- STIFF MAN SYNDROME\r\n- ANTI-INSULIN RECEPTOR ANTIBODIES\r\n\r\nH. OTHER GENETIC SYNDROMES SOMETIMES ASSOCIATED WITH DIABETES\r\n\r\n- DOWN SYNDROME\r\n- KLINEFELTER SYNDROME\r\n- TURNER SYNDROME\r\n- WOLFRAMS SYNDROME\r\n- FRIEDREICHS ATAXIA\r\n- HUNTINGTONS CHOREA\r\n- LAURENCE-MOON BIEDL SYNDROME\r\n- MYOTONIC DYSTROPHY\r\n- PORPHYRIA\r\n- PRADER-WILLI SYNDROME\r\n\r\nI. GESTATIONAL DIABETES MELLITUS\r\n\r\n( MODY - MATURITY ONSET DIABETES OF YOUNG )', '', '1', '0', '0', '1', '0', 'DISEASE INFLUENCING FACTORS : DIET, LIFE STYLE, ENVIRONMENT, SMOAKING, ALCOHOL, DRUG ABUSE & LACK OF EXERCISE. THERE IS 50% RISK OF DEVELOPING TYPE-2 DIABETES WITH IN 5-10 YRS. REGULAR POSTPARTUM FOLLOW UPS ARE IMPORTANT.', 'F', '0', '* - INSULIN IS DRUG OF CHOICE AS ORAL HYPOGLYCAEMICS CAN CAUSE MACROSOMIA & OTHER CONGENITAL DEFECTS.\r\n\r\n* - POSTPRANDIAL HYPERGLYCEMIA IS THE STRONGEST RISK FACTOR FOR MACROSOMIA. THEREFORE TIGHT GLUCOSE CONTROL USUALLY REQUIRE SHORT ACTING INSULIN WITH EACH MEAL WITH MID NIGHT SNACK TO AVOID EARLY MORNING HYPOGLYCEMIA.\r\n\r\n* - RECOMMENDED LABORATORY PARAMETERS DURING PREGNANCY :\r\n- Fasting whole blood glucose level less than 95 mg/dL (5.3 mmol/L)\r\n- One-hour postprandial whole blood glucose level of less than 140 mg/dL (7.8 mmol/L)\r\n- GLYCOSULATED HAEMOGLOBIN LEVEL < 7.0%\r\n\r\n* - BECAUSE OF DELAYED PULMONARY MATURATION OF FETUS, EARLY DELIVERY IS AVOIDED.\r\n\r\n* - PREECLAMPSIA COMPLECATES 20% OF PREGNANCIES IN DIABETICS & RISK IS HIGHER( 50% OR MORE) IN ASSOCIATION WITH HYPERTENSION OR RENAL DISEASE, CESAREAN SECTION ( ~30% ), POLYHYDRAMNIOS (~ 20% )\r\n\r\n* - APPROPRIATE LEVELS OF FOLATE IN MOTHER CAN REDUCE CHANCES OF FETAL NEURAL TUBE DEFECTS.\r\n\r\n* - INSULIN REQUIREMENT REDUCES IN FIRST TRIMESTER DUE TO INCREASED INSULIN SENTIVITY BUT REQUIREMENT IS INCREASED IN 2 & 3 TRIMSTER DUE TO INSULIN RESISTANCE.\r\n\r\n* - IF BREAST FEEDING IS DONE IN THE POSTPARTUM PERIOD, THEN CONTINUE WITH THE INSULIN THERAPY AS ORAL HYPOGLYCEMICS CROSS TO BREAST MILK.\r\n\r\n* - INCIDENCE OF NEONATAL COMPLICATIONS RANGE FROM 12 - 28% IN GDM MOTHERS INFANTS.', NULL, NULL, NULL, NULL, '1'),
('1262', 'HEPATITIS-C DISEASE', '0', 'D.D. :\r\n\r\n- ALCOHOLIC HEPATITIS\r\n- AUTOIMMUNE HEPATITIS\r\n- BILE DUCT STRICTURES\r\n- BILIARY OBSTRUCTION\r\n- BUDD-CHIARI SYNDROME\r\n- CHOLANGITIS\r\n- HEPATITIS-B DISEASE\r\n- HEPATITIS-C DISEASE\r\n- HEPATITIS-D DISEASE\r\n- HEPATITIS-E DISEASE\r\n- HYPERBILIRUBINEMIA, CONJUGATED\r\n- ISONIAZID HEPATOTOXICITY\r\n- INFECTIOUS MONONUCLEOSIS\r\n-PRIMARY & SECONDARY HEPATIC MALIGNANCY\r\n- ISCHAEMIC HEPATITIS\r\n- DRUG INDUCED HEPATITIS\r\n- WILSON DISEASE\r\n- RHEUMATIC & SKIN MANIFESTATIONS MAY SUGGEST IMMUNOLOGICAL DISORDER\r\n\r\n\r\n--------------------------------------------------------------------------\r\nCAUSES: Hepatitis C virus\r\n', '* ANTI-HCV SEROLOGY INVOLVING ENZYME IMMUNOASSAY ( EIA )- 97% SPECIFIC\r\n* MOST RECENT THIRD GENERATION EIA - DETECTS ANTIBODIES AGAINST CORE PROTEIN & NONSTRUCTURAL PROTEINS 3,4 & 5 & IS POSITIVE AFTER 8 WEEKS OF INFECTION.\r\n* RECOMBINANT IMMUNOBLOT ASSAY - IS DONE TO CONFIRM HCV INFECTION\r\n* HCV-RNA , QUALITATIVE ASSAY \r\n* SCREEN THE PATIENT FOR CO-INFECTION WITH HIV & HEPATITIS B VIRUS DISEASE\r\n* SERUM THYROTROPIN LEVEL - ABNORMAL IF THYROID IS INVOLVED\r\n*   A positive immunoblot assay result followed by 2 or more instances of undetectable HCV RNA suggests HCV infection has resolved. A positive anti-HCV immunoassay result followed by a negative immunoblot assay result represents a false-positive immunoassay, and no further testing is required\r\n• Marked elevation of AST/ALT (acute hepatitis,\r\nparticularly ALT, 400-several thousand U/L); HCV may have normal ALT; AST/ALT ratio =>1 associated with cirrhosis in chronic HCV\r\n• Mild elevation of alkaline phosphatase\r\n• Bilirubin from normal to markedly elevated; with elevation, conjugated and unconjugated fractions usually increased\r\n\r\nPositive serum markers in hepatitis C\r\nStatus               Marker\r\n----------------------------------------\r\nA, C                Anti-HCV ELISA III or RIBA HCV RNA: (qual. & quan.)\r\n                      Genotypes I-IV\r\n---------------------------\r\nInfection status:\r\nA=acute\r\nC=chronic\r\n• For severe hepatitis, measure PT and PTT, albumin, electrolytes, glucose and CBC\r\n• Persistence > 6 months indicates probable chronic liver disease\r\n• Acute, ongoing HCV, confi rm by other markers, RIBA, HCV-RNA (for chronic HCV); >viral counts, genotypes 1, 2, 3 & 4\r\n• In early acute HCV infection, anti-HCV may be negative; may need retest in 3-6 weeks\r\n• HCV-RNA becomes positive early in acute cases\r\n• HCV genotypes may be useful. Genotypes with favorable prognosis - 2a, 2b, 3a; less favorable 1a, 1b\r\nSPECIAL TESTS Liver biopsy usually needed for determining type and extent of liver injury in persistent disease and to exclude other diseases. Also, usually necessary prior to start of antiviral treatment such as interferon-alfa.\r\nIMAGING : Usually helpful. Ultrasound may demonstrate ascites or exclude obstruction. Helpful when cancer is suspected. CT with IV contrast and MRI in\r\nselected cases. Early cirrhosis usually not detected by imaging studies - need liver biopsy.', '0', '0', '1', '0', '0', 'COMMUNICABLE THROUGH BLOOD PRODUCTS,NEEDLE PRICKS, SCRATCH, SEXUAL CONTACT & SOME TIMES MATERNAL-FETAL TRANSMISSION, NOT BY ORAL ROUTE.', 'B', '6', 'RISK FACTORS\r\n• Health care workers/other occupational risks\r\n• HCV transmitted through blood or its products; in 40%, mode unknown\r\n• Hemodialysis\r\n• Recipients of blood and/or blood products (esp. prior to 1992)\r\n• IV drug users 60-70% of new infections\r\n• Sexually active homosexual males (much more likely with hepatitis B than with C)\r\n• Household exposure\r\n• Intimate exposure\r\n• Positive needlestick\r\n• Transplanted organs\r\n• Snorting cocaine\r\n• Recent body piercing; tattoos less likely, role controversial\r\n• HIV positivity increases risk of hepatitis C or C virus infection in coinfected patients\r\n• Perinatal transmission of neonate of hepatitis B infected mother rare with HCV unless HIV positive\r\n\r\nMedical Care: The goals of treatment of chronic HCV infection are to (1) achieve sustained eradication of HCV (ie, sustained virological response [SVR]), defined as the persistent absence of HCV RNA in serum 6 months or more after completing antiviral treatment and (2) prevent progression to cirrhosis, HCC, and decompensated liver disease requiring LT. \r\nAt week 12 of treatment, the patient should be evaluated for an early virological response by repeating the quantitative HCV RNA and IFN-associated thyroid dysfunction screening. If the HCV RNA level is undetectable or if a greater than 2-log-fold reduction in HCV RNA level is present, therapy should be continued because, according to Fried et al in 2002, up to 65% of patients go on to develop an SVR. Conversely, if an early virological response is not present, treatment should be stopped because the chance of developing a sustained response of HCV eradication is less than 3%. Poynard et al reported in 1998 that the one exception is in the context of clinical trials or treatment of recurrent HCV infection in liver transplant recipients; improved fibrosis scores have been reported in patients in whom the virus has not been eradicated, thus identifying a subgroup of patients who may benefit from maintenance therapy. \r\nThe HCV RNA level should be rechecked 6 months after the completion of treatment, and, if detectable, the patient has relapsed and should be considered for an alternative treatment. If HCV RNA is undetectable and test results remain negative, the patient has developed an SVR. \r\nAntiviral therapy for chronic hepatitis C is currently recommended for patients with elevated serum ALT levels who (1) are older than 18 years; (2) have positive findings for HCV antibody and serum HCV RNA; (3) have liver biopsy findings consistent with a diagnosis of chronic hepatitis, although a biopsy is not essential; and (4) have no contraindications for treatment. \r\nThe treatment of hepatitis C has evolved over the years. The early pivotal studies of IFN monotherapy, IFN in which polyethylene glycol (PEG) molecules are added (ie, PEG-IFN) monotherapy, and combination therapy with ribavirin (with either IFN or PEG-IFN) are described first, after which therapy for special patient groups will be discussed. Additionally, the impact of IFN on the development of HCC will be briefly discussed. \r\nIFN therapy with and without ribavirin\r\nAlthough the short courses of standard IFN monotherapy first introduced in the 1980s by Hoofnagle et al (1986), Davis et al (1989), and Di Bisceglie et al (1989) led to sustained improvement in liver disease and loss of virus in less than 10% of patients, these therapies were the first to cure chronic viral hepatitis. A major advance in the treatment of chronic hepatitis C was the addition of the oral nucleoside analogue ribavirin to the IFN regimen. As reported in the landmark 1998 studies by McHutchison et al and Poynard et al, IFN alfa-2b and ribavirin combination therapy for 6-12 months resulted in sustained eradication rates of 30-40%. However, patients with HCV genotype 1 who were treated for 12 months had a much less favorable response to therapy with IFN and ribavirin compared with patients infected with genotypes 2 and 3, in whom a 6-month course of therapy was sufficient. \r\nIFN monotherapy appears to play a role in the treatment of acute HCV infection. In 2001, Jaeckel et al reported that treatment with IFN alfa-2b prevented chronic infection in 98% of a group of 44 German patients with acute hepatitis C. In this study, patients received 5 million U/d of IFN alfa-2b subcutaneously for 4 weeks and then 3 times per week for another 20 weeks; the IFN alfa-2b was well tolerated in all patients but one. Because spontaneous resolution is common, no definitive timing of therapy can be recommended; although waiting 2-4 months after the onset of illness seems reasonable. \r\nThe 2 most frequently used recombinant IFN preparations in clinical trials are IFN alfa-2b (Intron-A; Schering-Plough, Kenilworth, NJ) and IFN alfa-2a (Roferon; Hoffmann-La Roche, Basel, Switzerland), which differ from each other by only a single amino acid residue. IFN alfacon-1 (Infergens; Amgen, Thousand Oaks, Calif), or consensus IFN, is a genetically engineered compound synthesized by combining the most common amino acid sequences from all 12 naturally occurring IFNs. It has greater cytokine-induction, antiviral, antiproliferative, natural killer cell, and gene-induction activities than both IFN alfa-2a and IFN alfa-2b on an equal-mass basis. However, initial studies of the recommended consensus IFN dose of 9 mcg in IFN-naive patients with chronic hepatitis C, such as that by Tong et al from 1997, have resulted in viral response rates similar to those of standard IFN-alfa monotherapy. \r\nPEG-IFN monotherapy\r\nRecent developments in IFN technology have led to the development of long-lasting IFNs in which PEG molecules are added to IFN. These new PEG-IFNs have better sustained absorption, a slower rate of clearance, and a longer half-life than those of unmodified IFN. They permit more convenient once-weekly dosing. The FDA has approved PEG-IFNs for the treatment of chronic hepatitis C. \r\nThe 2 PEG-IFN preparations currently available are (1) PEG-Intron (Schering-Plough), which consists of IFN alfa-2b attached to a single 12-kd PEG chain and is metabolized predominantly by the liver, and (2) Pegasys (Hoffmann-La Roche), which consists of IFN alfa-2a attached to a 40-kd branched PEG molecule. Note that pegylated alfa-2b is excreted by the kidneys. \r\nSeveral reports have documented the improved SVR with PEG-IFN monotherapy. In a 2000 randomized study of patients with chronic hepatitis C, Zeuzem et al found that PEG-IFN alfa-2a at 180 mcg subcutaneously administered once per week was associated with a higher rate of virologic response than IFN alfa-2a at 6 million U subcutaneously administered 3 times per week for 12 weeks followed by 3 million U 3 times per week for 36 weeks. Findings were 69% versus 28% (P = .001) at week 48 of therapy and 39% versus 19% (P = .001) at week 72 of therapy. Drug discontinuation in these treatment-naive patients and the frequencies of dose reduction were similar in the 2 treatment groups. \r\nIn 2000, Heathcote and colleagues reported on the use of PEG-IFN alfa-2a in a controlled trial of subjects with cirrhosis. The SVR rate was 30% after 48 weeks of therapy with 180 mcg, compared with 8% for patients treated with standard IFN alfa. Adverse effects did not significantly increase with the pegylated product. \r\nPEG-IFN therapy with ribavirin \r\nAs previously described with IFN alfa monotherapy, the addition of ribavirin to PEG-IFN has heralded a new era in the treatment of chronic HCV, resulting in 3 landmark trials: Manns et al from 2001, Fried et al from 2002, and Hadziyannis et al from 2004. \r\nIn 2001, Manns et al compared PEG-IFN alfa-2b plus ribavirin with IFN alfa-2b plus ribavirin in 1530 subjects with chronic hepatitis C. Subjects were randomly assigned to 3 groups as follows: (1) IFN alfa-2b at 3 million U subcutaneously 3 times per week plus ribavirin at 1000-1200 mg/d orally, (2) PEG-IFN alfa-2b at 1.5 mcg/kg/wk plus ribavirin at 800 mg/d, and (3) PEG-IFN alfa-2b at 1.5 mcg/kg/wk for 4 weeks and then 0.5 mcg/kg/wk plus ribavirin at 1000-1200 mg/d for 48 weeks. \r\nThe SVR rate was significantly higher in the higher-dose PEG-IFN group (274 [54%] of 511 subjects) than in the lower-dose PEG-IFN (244 [47%] of 514 subjects; P = .01) or IFN (235 [47%] of 505 subjects; P = .01) groups. Among patients with HCV genotype 1 infection, the corresponding SVR rates were 42% (145 of 348 patients), 34% (118 of 349 patients), and 33% (114 of 343 patients). The rates for patients with genotype 2 and 3 infections were approximately 80% for all treatment groups. Adverse-effect profiles were similar among the treatment groups. Secondary analyses identified body weight and HCV RNA viral load less than 1 million copies per milliliter as important predictors of SVR. When the dose was optimized for the patient\'s body weight, with a dose of more than 10.6 mg/kg of ribavirin daily, the SVR with IFN regimens was 61% for all genotypes, 48% for genotype 1, and 88% for genotypes 2 and 3. \r\nIn 2002, Fried at al compared the efficacy and safety of PEG-IFN alfa-2a plus ribavirin to IFN alfa-2b plus ribavirin and PEG-IFN alfa-2a monotherapy in a multicenter, randomized, controlled trial. A total of 1121 subjects were randomly assigned to treatment and received at least one dose of study medication, consisting of 180 mcg of PEG-IFN alfa-2a once weekly plus daily ribavirin (1000 or 1200 mg, depending on body weight), weekly PEG-IFN alfa-2a plus daily placebo, or 3 million U of IFN alfa-2b thrice weekly plus daily ribavirin for 48 weeks. \r\nThis study showed that a significantly higher proportion of subjects who received PEG-IFN alfa-2a plus ribavirin had an SVR compared with subjects who received IFN alfa-2b plus ribavirin (56% vs 44%, P <.001) or PEG-IFN alfa-2a alone (56% vs 29%, P <.001). The SVR rates for patients with HCV genotype 1 were 46%, 36%, and 21%, respectively, for the 3 regimens. Among patients with HCV genotype 1 and high baseline levels of HCV RNA, the SVR rates were 41%, 33%, and 13%, respectively. The overall safety profiles of the 3 treatment regimens were similar; the prevalence of influenzalike symptoms and depression was lower in the groups receiving PEG-IFN alfa-2a than in the group receiving IFN alfa-2b plus ribavirin. Overall, once-weekly PEG-IFN alfa-2a plus ribavirin was tolerated as well as IFN alfa-2b plus ribavirin and produced significant improvements in the SVR rate compared with IFN alfa-2b plus ribavirin or PEG-IFN alfa-2a alone. \r\nIn 2004, Hadziyannis et al reported the efficacy and safety of 24 or 48 weeks of treatment with PEG-IFN alpha-2a plus a low or standard dose of ribavirin in a randomized, double-blinded trial. The 1311 subjects were randomized to PEG-IFN alfa-2a at 180 mcg/wk for 24 or 48 weeks plus a low dose (800 mg/d) or standard weight-based dose (1000 or 1200 mg/d) of ribavirin. An SVR was defined as undetectable HCV RNA at the end of treatment and during 12-24 weeks of follow-up. \r\nTheir study showed that in subjects infected with HCV genotype 1, 48 weeks of treatment was statistically superior to 24 weeks and that standard-dose ribavirin was statistically superior to low-dose ribavirin. In subjects with HCV genotype 1, absolute differences in SVR rates between 48 and 24 weeks of treatment were 11.2% (95% confidence interval [CI], 3.6-18.9%) and 11.9% (CI, 4.7-18.9%), respectively, between standard- and low-dose ribavirin. SVR rates for PEG-IFN alfa-2a and standard-dose ribavirin for 48 weeks were 63% (CI, 59-68%) overall and 52% (CI, 46-58%) in subjects with HCV genotype 1. In subjects with HCV genotypes 2 or 3, the SVR rates in the 4 treatment groups were not statistically significantly different. \r\nIn conclusion, treatment with PEG-IFN alfa-2a and ribavirin may be individualized by genotype. Patients with HCV genotype 1 require treatment for 48 weeks and a standard dose of ribavirin; those with HCV genotype 2 or 3 seem to be adequately treated with a low dose of ribavirin for 24 weeks. \r\nCurrently, no studies have compared PEG-IFN alfa-2b plus ribavirin versus PEG-IFN alfa-2a plus ribavirin. According to the 2002 US National Institutes of Health consensus statement on the management of hepatitis C, standard of care for the treatment of hepatitis C is PEG-IFN with ribavirin for 48 weeks in patients with genotype 1 and is 24 weeks for patients with genotype 2 or 3. \r\nAdverse effects are common with IFN and ribavirin combination therapy, with approximately 75% of patients experiencing one or more of the following: \r\n\"	Interferon - Hematological complications (ie, neutropenia, thrombocytopenia), neuropsychiatric complications (ie, memory and concentration disturbances, visual disturbances, headaches, depression, irritability), flulike symptoms, metabolic complications (ie, hypothyroidism, hyperthyroidism, low-grade fever), gastrointestinal complications (ie, nausea, vomiting, weight loss), dermatological complications (ie, alopecia), and pulmonary complications (ie, interstitial fibrosis) \r\n\"	Ribavirin - Hematological complications (ie, hemolytic anemia), reproductive complications (ie, birth defects), and metabolic complications (ie, gout)\r\nGrowth factors such as granulocyte-stimulating factor and erythropoietin are frequently used to counteract the adverse hematological effects of IFN and ribavirin, respectively. Despite the encouraging results reported by Afdhal et al in 2004 and Van Thiel et al in 1995, cost-effectiveness data supporting their routine use as a means of avoiding IFN and ribavirin dose reductions are insufficient. \r\nIn patients who are at risk of depression or who develop depression during treatment, any antidepressant is better than none. Because available evidence suggests that all antidepressants will have an effect, Schaefer et al reported in 2002 that treatment must be individualized on the basis of adverse effect profile, drug-to-drug interactions, and general considerations (eg, speed of onset, efficacy). \r\nSpecial patient groups\r\nHIV-HCV co-infection \r\nOf persons infected with HIV, 30-50% are co-infected with HCV. Co-infection with HIV both accelerates the clinical progression of hepatitis C and increases the risk of perinatal HCV transmission from 5% (range, 3-8%) to 17% (range, 7-36%). Two 2004 studies have supported the use of PEG-IFN alfa-2a plus ribavirin for HIV patients with chronic HCV infection. \r\nIn the first, Torriani et al randomized 868 subjects with HIV and HCV co-infection (who had not previously been treated with IFN or ribavirin) to receive 1 of 3 regimens: (1) PEG-IFN alfa-2a (180 mcg/wk) plus ribavirin (800 mg/d), (2) PEG-IFN alfa-2a plus placebo, or (3) IFN alfa-2a (3 million IU 3 times/wk) plus ribavirin. Subjects were treated for 48 weeks and followed for an additional 24 weeks. The primary endpoint was an SVR (defined as a serum HCV RNA level <50 IU/mL at the end of 72-wk follow-up). \r\nTheir study showed the overall SVR rate was significantly higher among the recipients of PEG-IFN alfa-2a plus ribavirin than among those assigned to IFN alfa-2a plus ribavirin (40% vs 12%, P <.001) or PEG-IFN alfa-2a plus placebo (40% vs 20%, P <.001). Among subjects infected with HCV genotype 1, the SVR rates were 29% with PEG-IFN alfa-2a plus ribavirin, 14% with PEG-IFN alfa-2a plus placebo, and 7% with IFN alfa-2a plus ribavirin. The corresponding rates among subjects infected with HCV genotype 2 or 3 were 62%, 36%, and 20%. \r\nNeutropenia and thrombocytopenia were more common among subjects treated with regimens that contained PEG-IFN alfa-2a, and anemia was more common among subjects treated with regimens containing ribavirin. In conclusion, among patients co-infected with HIV and HCV, the combination of PEG-IFN alfa-2a plus ribavirin is significantly more effective than either IFN alfa-2a plus ribavirin or PEG-IFN alfa-2a monotherapy. \r\nFor the second, Chung et al conducted a multicenter, randomized trial of patients co-infected with HIV and HCV. Sixty-six subjects were randomly assigned to receive 180 mcg of PEG-IFN alfa-2a weekly for 48 weeks, and 67 subjects were assigned to receive 6 million IU of IFN alfa-2a 3 times weekly for 12 weeks, followed by 3 million IU 3 times weekly for 36 weeks. Both groups received ribavirin according to a dose-escalation schedule. This study showed treatment with PEG-IFN and ribavirin was associated with a significantly higher SVR rate (an HCV RNA level <60 IU/mL 24 wk after completion of therapy) than treatment with IFN and ribavirin (27% vs 12%, P = .03). In the group given PEG-IFN and ribavirin, only 7 (14%) of 51 subjects with HCV genotype 1 infection had an SVR, compared with 11 (73%) of 15 subjects with an HCV genotype other than 1 (P <.001). \r\nAn important finding from the study was histologic improvement in 35% of subjects with no virologic response who underwent liver biopsy, suggesting that the effects of IFN and ribavirin on hepatic histology may be independent of its antiviral activity. In conclusion, in persons co-infected with HIV and HCV, the combination of PEG-IFN and ribavirin is superior to the combination of IFN and ribavirin in the treatment of chronic hepatitis C. These regimens may provide clinical benefit, even in the absence of virologic clearance. \r\nNo trials have compared PEG-IFN alfa-2a plus ribavirin with PEG-IFN alfa-2b plus ribavirin in patients with chronic hepatitis C and HIV infection. However, in a 2004 Spanish, open-label, randomized study comparing PEG-IFN alfa-2b plus ribavirin with IFN alfa-2b plus ribavirin, Laguno and colleagues reported SVRs were significantly better with the pegylated combination (44% vs 21%). \r\nHCV-HBV co-infection \r\nThis form of co-infection, in the absence of HIV infection, is relatively uncommon in the United States, and optimal treatment regimens have not been established. However, 2 important studies are worth mentioning. \r\nIn 2001, Villa et al reported that 9 million U of standard IFN thrice weekly for 3 months could clear HCV in 31% of patients. \r\nIn 2003, Liu et al used standard IFN and ribavirin and discovered that sustained HCV eradication was achieved at rates comparable with patients with HCV alone and, interestingly, up to 21% of their patients lost the hepatitis B surface antigen. Given the increasing efficacy of PEG-IFN over standard IFN, these investigators are currently conducting a multicenter study using PEG-IFN and ribavirin on this group of co-infected patients. \r\nAfrican Americans and ethnic minorities \r\nSeveral small studies have reported a lower response rate to IFN alfa among black patients with chronic hepatitis C infection than among white patients. The increased prevalence of infection with HCV genotype 1, which is associated with a lower response rate than other genotypes, has been suggested as the cause. \r\nMuir et al treated 100 black patients and 100 non-Hispanic white patients with chronic hepatitis C with PEG-IFN alfa-2b and ribavirin for 48 weeks. Enrollment was controlled so the 2 groups had similar proportions of patients with genotype 1 infection. The primary endpoint was an SVR, defined as a negative test result for serum HCV RNA 6 months after the completion of therapy. In both cohorts, 98% of subjects had genotype 1 infection. The SVR rate was higher among non-Hispanic white subjects than among black subjects (52% vs 19%, P <.001). The black subjects also had significantly lower rates of virologic response at 12 weeks and at the end of treatment. \r\nMultivariate analyses examining sociodemographic and clinical characteristics found that black race was the only variable significantly associated with the difference in response rates. In conclusion, black patients with chronic hepatitis C have a lower rate of response to treatment with PEG-IFN alfa-2b and ribavirin than non-Hispanic white patients, a difference that is not explained by differences in the viral genotype. \r\nHepburn et al recently analyzed data from 661 patients from 2 multicenter trials to determine predictors of successful viral eradication and the role of ethnicity. After performing multiple logistic regression analyses adjusted for factors known to impact outcome (eg, genotype), the authors reported that Asians were more likely to respond to treatment, whereas Hispanics and African Americans were less likely, in comparison to whites. \r\nEnd-stage renal disease \r\nHCV is prevalent in patients with end-stage renal disease and can also be an important cause of renal failure. Treatment of HCV infection in patients with end-stage renal disease is problematic because ribavirin is contraindicated and IFN monotherapy is not as effective as combination therapy. IFN doses also frequently have to be reduced. Before undergoing kidney transplantation, patients are frequently referred for consideration of HCV treatment and liver-kidney transplantation in the event of having silent-but-advanced liver disease. Under these circumstances, liver biopsies are frequently performed to stage the degree of fibrosis, and, if cirrhosis is present and the patient is asymptomatic, he or she is frequently considered for combined liver-kidney transplantation. However, because IFN is contraindicated after kidney or kidney-liver transplantation, attempting to eradicate HCV in such patients prior to organ transplantation is recommended. \r\nFabrizi et al evaluated the efficacy of IFN monotherapy in dialysis patients with chronic hepatitis C by performing a systematic review of the literature with a meta-analysis of clinical trials. The primary outcome was an SVR, and the secondary outcome was the dropout rate. The authors identified 14 clinical trials (269 unique patients); 2 were controlled studies. The mean overall estimates for the SVR and dropout rates were 37% (95% CI, 28-48) and 17% (95% CI, 10-28), respectively. The most frequent adverse effects requiring interruption of treatment were flulike symptoms (17%), neurological symptoms (21%), and gastrointestinal symptoms (18%). The overall weighted estimate for SVR in patients with HCV genotype 1 was 30.6% (95% CI, 20.9-48). In the subgroup of clinical trials (n = 5) with standard IFN administration (3 million U thrice weekly, subcutaneous route, 24-wk treatment), the overall mean estimate of SVR was 39% (95% CI, 25-56). The studies were heterogeneous with regard to SVR and dropout rate. \r\nIn conclusion, tolerance to initial IFN monotherapy was lower in dialysis patients than in nonuremic patients with chronic hepatitis C. However, more than one third of hemodialysis patients with chronic hepatitis C have been successfully treated with IFN. A longer duration of IFN monotherapy does not appear to have a beneficial effect on the response rate. Further studies are warranted to define the optimal antiviral regimen for chronic hepatitis C in patients on dialysis. \r\nOrgan transplantation \r\nIFN is contraindicated for HCV treatment after organ transplantation because of its high risk of precipitating rejection, in part due to up-regulation of the HLA system by IFN. However, allograft rejection is uncommon in liver transplant recipients with recurrent HCV infection who are treated with IFN-based therapies. As noted by Forman et al in 2002, recurrent HCV infection is universal after LT, can lead to cirrhosis in 30% of patients within 5 years, and is emerging as the most common cause of retransplantation in the United States. \r\nSince 1996, several pilot studies have been conducted to evaluate IFN-based therapies for recurrent HCV infection. One of the most important of these was reported by Samuel et al in 2003, who randomized subjects to receive either no treatment or therapy with IFN alfa-2b (3 million U 3 times/wk) plus 1000-1200 mg/d of ribavirin for 1 year. Subjects were followed for 6 months after the end of treatment. The primary endpoint was loss of HCV RNA 6 months after the end of treatment. \r\nFifty-two subjects were randomized to receive either treatment (n = 28) or placebo (n = 24). Sixteen subjects were withdrawn from the study; 12 (43%) were from the treatment group (mainly for anemia [7 patients]) and 4 (17%) were from the control group. In the treated group, serum HCV RNA was undetectable in 9 patients (32%) at the end of treatment and in 6 (21.4%) at the end of the follow-up period, whereas no patient in the control group lost HCV RNA at any point (P = .036 at the end of follow-up). However, no significant histologic improvement was noted. \r\nOverall, the combination of IFN alfa-2b plus ribavirin induced an SVR in 21% of transplant recipients with recurrent hepatitis C. However, 43% discontinued therapy because of adverse events (primarily severe anemia). Despite the low rates of sustained viral eradication in these patients, as reported by Samuel and other investigators, Narayanan Menon et al identified a subgroup of patients who demonstrated improved fibrosis scores despite failure to eradicate the virus. This suggests that some patients may benefit from maintenance therapy and emphasizes the benefit of performing pretreatment and posttreatment biopsies in this group of patients. \r\nTwo 2003 pilot studies, by Mukherjee et al and Rodriguez-Luna et al, reported on the use of PEG-IFN alfa-2b and ribavirin in these patients, and sustained eradication rates were less than 30%. Currently, no evaluations of PEG-IFN alfa-2b and ribavirin for recurrent HCV infection or randomized studies using PEG-IFN and ribavirin have been reported in this cohort of patients. \r\nHepatitis C treatment in patients with normal liver enzyme levels \r\nThe treatment for these patients remains controversial because previous studies have demonstrated that they frequently have mild liver disease, do not tolerate therapy, or can develop new elevations in liver chemistry parameters after initiating treatment. \r\nIn 2003, Hui et al reported that ALT levels and histology findings are not well correlated and patients can have advanced fibrosis or cirrhosis in the presence of normal liver enzyme levels. In 2004, Jacobson et al reported that sustained HCV eradication rates in their patients with HCV infection and normal ALT values were comparable to patients with elevated liver enzyme levels. However, the authors used both high- (5 million U) and low-dose (3 million U) IFN with ribavirin in their study and only 1 patient had cirrhosis. The role of prior alcohol use on liver injury was not investigated, although all patients abstained from alcohol for at least 12 months. \r\nFuture trials will most likely evaluate PEG-IFN with ribavirin in this cohort of patients and, hopefully, will adjust for confounders such as alcohol use. \r\nTreatment of decompensated cirrhotic patients awaiting LT \r\nThe aim of treating decompensated cirrhotic patients is to achieve sustained viral eradication prior to LT in an attempt to prevent recurrent HCV infection. However, this intervention is not recommended outside clinical trials because, as reported by Crippin et al in 2002, the risks of treatment can outweigh the benefits. In 2004, Everson reported that although viral titers may decrease during treatment and possibly diminish the severity of recurrent HCV infection, complications and successful eradication are less likely in patients with more advanced liver disease. \r\nHCV treatment in patients actively engaging in alcohol and injection drug use \r\nIn 1998, Wiley et al reported that because of the strong association between alcohol use and rapid liver fibrosis, hepatoma, and deleterious effects on treatment response, complete alcohol abstinence is recommended during treatment. \r\nAs reported by Strader et al in 2004, the practice guidelines of the American Association for the Study of Liver Diseases recommend that HCV treatment should not be withheld from persons who use illicit drugs or are on a methadone maintenance program, provided they are willing to maintain close monitoring, including practicing contraception. The complexity of HCV treatment in these patients is aided by a multidisciplinary team approach composed of physicians and drug abuse and psychiatric counselors. \r\nEffect of IFN on HCC recurrence \r\nIn 2002, Hayashi and Kasahara noted that exposure to IFN, irrespective of HCV eradication status, was associated with a reduced incidence of HCC. An important randomized study by Kubo et al, first conducted in 1996 with follow-up in 2002, also demonstrated that the administration of IFN to patients undergoing liver resection for HCC was associated with reduced tumor recurrence and improved survival. Although IFN may have a role in reducing the incidence of HCC, which subgroup of HCV patients are most likely to benefit remains unclear. \r\nSurgical Care: Consultation with a surgeon may be necessary for patients in whom hepatic resection for HCC or LT is being considered. \r\nDiet: No special diet is recommended unless a patient has developed decompensated cirrhosis.\r\n\r\nCombination therapy with PEG-IFN alfa and the nucleoside analog ribavirin is the current standard of care in patients infected with HCV. Patients with HCV genotype 1 have a much less favorable response to therapy and are treated for 12 mo, compared with patients infected with genotypes 2 and 3, in whom a 6-mo course of therapy is sufficient. If viremia is present after 6 mo, additional therapy has a negligible incremental benefit, and treatment should be stopped in all patients regardless of the viral genotype. With HIV co-infection, all patients with a response to therapy at the end of 6 mo should receive an additional 6 mo of combination therapy regardless of the genotype. Patients with acute HCV infection should be treated for 6 mo.\r\n\r\nPATIENT EDUCATION\r\no Avoid sharing razors, tooth brushes and nail clippers\r\no Wash and cover cuts and bruises\r\no Proper use and disposal of needles\r\no Proper hygiene, particularly food handlers\r\no Sexual transmission low, but does occur\r\n\r\nDRUG(S) OF CHOICE\r\no Acute hepatitis C: Antiviral therapy is highly effective for acute infections. Interferon-alfa 5 mg SC or IM daily for HCV-RNA for 4 weeks followed by 3 times per week for 20 weeks.\r\no Chronic hepatitis C: pegylated interferon + ribavirin\r\n? Pegylated interferon-alpha 2b 1.5 mcg/kg/week\r\n? Pegylated interferon-alpha 2a 180 mcg/week\r\n? Ribavirin 800-1200 mg po bid in combination with pegylated interferon\r\n\r\nContraindications: Interferon: platelet count < 50,000. Mouse immunoglobulin, egg protein or neomycin allergy. Corticosteroids may add to morbidity/increased mortality.\r\n\r\nPrecautions:\r\no Other disorders of coagulation, myelosuppression, seizures, depression (esp suicide ideation), pregnancy,\r\nfertile age group, lactation\r\no Ribavirin may induce hemolytic anemia (hemoglobin 2 gm/dL below pretreatment) is common. Avoid in\r\npregnancy.\r\no Increased serum triglycerides may occur during IFN therapy; may cause abnormal ALT. Measure HCV-RNA\r\nto assess response in such patients.\r\no Psychiatric evaluation may be prudent prior to IFN treatment\r\n\r\nPATIENT MONITORING\r\no Serial measurement of serum AST/ALT\r\no Appropriate serum viral markers useful for evaluation of recovery or progression\r\no Liver biopsies in chronic disease; in acute cases if diagnosis remains in doubt\r\no Monitor for metabolic complications\r\no WBC, platelets with interferon-alfa therapy\r\no Lower viral load, genotypes 2 and 3 and absence of cirrhosis are predictors of favorable therapeutic response.\r\nUndetectable HCV-RNA (quantitative serum HCV-RNA) at 12 weeks is associated with sustained response.\r\nPersistently positive HCV-RNA at 24 weeks indicates lack of response; prolonged course is unlikely to be\r\nbeneficial.\r\no Monitor for hepatic decompensation (ascites, hepatic encephalopathy, spontaneous bacterial peritonitis, etc) in cirrhotics\r\no Goal of therapy is eradication of hepatitis C virus; HCVRNA test should become persistently undetectable\r\no Early virologic response is defi ned as =2 log decrease in HCV-RNA level after 12 weeks of treatment\r\no In patients with cirrhosis the risk of hepatic cellular carcinoma is high (20% life-time risk). Monitor for\r\nhypervascular lesions by imaging (ultrasound, helical CT) every 6 months.\r\n\r\nPREVENTION/AVOIDANCE\r\no No specifi cs on prevention/avoidance\r\no Maximum infectivity 2 weeks before jaundice\r\n\r\nPOSSIBLE COMPLICATIONS\r\no Acute or subacute necrosis, chronic hepatitis, hepatic failure\r\no Primary liver cancer risk\r\no HCV-associated cirrhosis: 1-3% per year, lifetime risk 20%. Cirrhosis patients need surveillance for hepatocellular carcinoma.\r\n\r\nEXPECTED COURSE/PROGNOSIS\r\no Severity of hepatic encephalopathy best predictor of poor survival in hepatic failure\r\no In HCV, regardless of severity:\r\n? >80% progress to chronic hepatitis\r\n? 20-50% to cirrhosis, and some, liver failure\r\n? Typically slow progression 10-30 years\r\n? May progress to HCC, but IFN may decrease HCC risk\r\n? Associated with type II AI\r\n? Chronic HCV unlikely to clear HCV-RNA spontaneously\r\n? HCV after needlestick, usually sustained IFN response\r\n? Final phase HCV rare cause of fulminant hepatic failure\r\no Alcohol increases severity of chronic HCV\r\n\r\nOthers: Alcohol abuse a major factor for chronic liver disease from HCV. Measure viral biochemical markers\r\nin patients with alcoholic liver disease (especially anti-HCV).\r\n', NULL, NULL, NULL, NULL, '1'),
('1263', 'VIRAL DISEASE', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '0', NULL, NULL, '0', '34014006', 'Viral disease', '1');
