INSERT INTO `investigation_old` (`Code`, `Name`, `Template`, `General`, `Description`, `ResultType`, `mUnit`, `NormalNumFrom`, `NormalNumTo`, `NormalPositive`, `NormalYes`, `Amount`, `Remarks`, `SpecimenReq`, `Container`, `Qty`, `CutOff`, `ReportingTime`, `LastUpdateOn`, `LastUpdateID`) VALUES
('11', 'BLOOD SUGAR ( FASTING )', '0', '0', 'GLUCOSE IS FORMED FROM CARBOHYDRATE DIGESTION & CONVERSION OF GLYCOGEN TO GLUCOSE BY THE LIVER. THE TWO HORMONES THAT DIRECTLY REGULATE BLOOD GLUCOSE LEVELS ARE GLUCAGON & INSULIN. GLUCAGON ACCELERATES GLYCOGEN BREAKDOWN IN THE LIVER & CAUSES THE BLOOD GLUCOSE LEVELS TO RISE. INSULIN INCREAES CELL MEMBRANE PERMEABILITY TO GLUCOSE, TRANSPORT GLUCOSE INTO CELLS, STIMULATES GLYCOGEN FORMATION, & REDUCE BLOOD GLUCOSE LEVELS.0', '1', 'MG %', '75', '110', '0', '0', '0', 'INCREASED : DIABETES MALLITUS, CUSHING SYNDROME, AC. EMOTIONAL OR STRESS SITUATION, PHEOCHROMOCYTOMA, ACROMEGALY, GIGANTISM, PITUITARY ADENOMA, HEMOCHROMATOSIS, PANCREATITIS, GLUCAGONOMA, ADVANCED LIVER DISEASE, CHR. RENAL DISEASE, WERNICKES ENCEPHALOPATHY.\r\n\r\nDECREASED : PANCREATIC ISLET CELL CARCINOMA, EXTRAPANCREATIC STOMACH TUMORS, ADDISON DISEASE, , HYPOPITUITARISM, HYPOTHYROIDISM, ACTH DEFICIENCY, STARVATION,LIVER DAMAGE ( ALCOHOLISM, ARSENIC POISONING, CHLOROFORM POISONING), PREMATURE INFANTS, ENZYME DEFICIENCY DISEASES ( GALACTOSEMIA, INHERITED MAPLE SYRUP DISEASE, VON GIERKES SYNDROME), INSULIN OVERDOSE, REACTIVE HYPOGLYCEMIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('14', 'TOTAL LEUCOCYTE COUNT', '0', '1', 'THE ENDOCRINE SYSTEM IS AN IMPORTANT REGULATOR OF THE NUMBER OF LEUKOCYTES IN THE BLOOD. HORMONES AFFECT THE PRODUCTION OF LEUKOCYTES IN THE BLOOD FORMING ORGANS, THEIR STORAGE & RELEASE FROM THE TISSUE & THEIR DISINTEGRATION. A LOCAL INFLAMMATORY PROCESS EXERTS A DEFINITE CHEMICAL EFFECT ON THE MOBILIZATION OF LEUKOCYTES. THE LIFE SPAN OF LEUKOCYTES VARIES FROM 13 - 20 DAYS. LEUKOCYTES FIGHT INFECTION & PRODUCE, TRANSPORT & DISTRIBUTE ANTIBODIES AS PART OF THE IMMUNE RESPONSE TO A FOREIGN SUBSTANCE ( ANTIGEN ).\r\nTHE WBC SERVE A USEFUL GUIDE TO THE SEVERITY OF THE DISEASE PROCESS.', '1', 'cells / cu mm', '3200', '10000', '0', '0', '0', 'Increased : Leukemoid reaction, acute inflammation, hodgkin\'s disease, pregnancy, liver disease, TRAUMA OR SURGERY, MALIGNANT NEOPLASM, TOXINS, UREMIA, DRUGS LIKE ETHER, CHLOROFORM, QUININE, ADRENALINE.\r\n\r\nDECREASED : VIRAL INFECTIONS, HYPERSPLENISM, OVERWHELMING BACTERIAL INFECTIONS, BONE MARROW DEPRESSION, APLASTIC ANAEMIA ETC.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('15', 'HAEMOGLOBIN ( MALE )', '0', '1', 'HB, THE MAIN COMPONENT OF RBC SERVES AS THE VEHICLE FOR THE TRANSPORTATION OF OXYGEN & CARBONDIOXIDE. IT IS COMPOSED OF AMINO ACIDS THAT FORM A SINGLE PROTEIN CALLED GLOBIN & A COMPOUND CALLED HAEM, WHICH CONTAINS IRON ATOMS & RED PIGMENT PORPHYRIN. IT IS THE IRON PIGMENT THAT COMBINES READILY WITH OXYGEN & GIVES BLOOD ITS CHARACTERISTIC RED COLOR. THE OXYGEN COMBINING CAPACITY OF THE BLOOD IS DIRECTLY PROPORTIONAL TO THE HB CONCENTRATION RATHER THAN TO THE RBC BECAUSE SOME RBCS CONTAIN MORE HB THAN OTHERS.', '1', 'GM / L', '14', '18', '0', '0', '0', 'INCREASED : POLYCYTHEMIA VERA, CHRONIC BRONCHITIS WITH EMPHYSEMA\r\nDECREASED : ANAEMIA\r\n\r\nNORMAL VALUES :\r\n0 - 2 WKS : 14.5 - 24.5 GM / ML\r\n2 - 8 WKS : 12.5 - 20.5 \r\n2 - 6 MTHS : 10.7 - 17.3\r\n6 MTHS  - 1 YR : 9.9 - 14.5 \r\n1 - 6 YRS : 9.5 - 14.1 \r\n6 - 16 YRS : 10.3 - 14.9\r\n16 - 18 YRS : 11.1 - 15.7', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('16', 'DIFF. LEUCOCYTE COUNT', '0', '1', 'THE DIFFERENTIAL COUNT IS EXPRESSED AS A PERCENTAGE OF TOTAL NUMBER OF LEUKOCUTES. THE DIFFERENTIAL COUNT ALONE HAS LIMITED VALUE; IT MUST ALWAYS BE INTERPRETED IN RELATION TO TOTAL WBC COUNT.', '1', '%', '1', '98', '0', '0', '0', '.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('17', 'ABSOLUTE EOSINOPHIL COUNT', '0', '0', 'EOSINOPHILS CAPABLE OF PHAGOCYTOSIS, INGEST ANTIGEN-ANTIBODY COMPLEXES & BECOME ACTIVE IN THE LATER STAGES OF INFECTION. EOSINOPHILS RESPOND TO ALLERGIC AND PARASITIC DISEASES. EOSINOPHIL GRANULES CONTAIN HISTAMINE( 1/3 OF ALL HISTAMINE IN THE BODY). \r\nTHIS TEST IS USED TO DIAGNOSE ALLERGIC INFECTIONS, ASSESS SEVERITY OF INFESTATIONS WITH WORMS AND OTHER PARASITES & MONITOR RESPONSE TO THEM.', '1', 'cells / cu mm', '0', '450', '0', '0', '0', 'INCREASED - ALLERGIES, HAY FEVER, ASTHMA, PARASITIC DISEASES, SOME ENDOCRINE DISORDERS LIKE ADDISONS DISEASE, HYPOPITUITARISM, HODGKINS DISEASE, MYELOPROLIFERATIVE DISORDERS, CHR. MYELOID LEUKEMIA, POLYCYTHEMIA VERA, CHR. SKIN DISEASES LIKE PAMPHIGUS, ECZEMA, DERMATITIS HERPATIFORMIS, SYSTEMIC EOSINOPHELIA, SCARLET FEVER, CHOREA, CONVALSCENT STAGE OF OTHER INFECTIONS, FAMILIAL EOSINOPHELIA, HYPEREOSINOPHELIC SYNDROME, POLYARTERITIS NODOSA, SLE, CONNECTIVE TISSUE DISORDERS, ULCERATIVE COLITIS, CROHNS DISEASE, ALLERGIC DRUG REACTIONS, LOFFLERS SYNDROME, INSECT BITES & IDIOPATHIC.\r\nREDUCED IN : IS USUALLY CAUSED BY AN INCREASED ADRENAL STEROID PRODUCTION THAT ACCOMPANIES MOST CONDITIONS OF BODILY STRESS & IS ASSOCIATED WITH - CUSHING SYNDROME, AC. BACTERIAL INFECTIONS & USE OF CERTAIN DRUGS SUCH AS ACTH, EPINEPHRINE, THYROXINE, PROSTAGLANDINS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('22', 'ESR ( MALE - WESTERGREN METHOD)', '0', '0', 'SEDIMENTATION OCCURS WHEN ERYTHROCYTES CLUMP TOGATHER IN A COLUMN LIKE MANNER. THESE CHANGES ARE RELATED TO ALTERATION IN PLASMA PROTEINS. NORMALLY ERYTHROCYTES SETTLE SLOWLY BECAUSE NORMAL RBCS DO NOT FORM ROULEAUX.\r\nTHE ESR IS THE RATE AT WHICH ERYTHROCYTES SETTLE OUT OF ANTICOAGULATED BLOOD IN 1 HR. THIS TEST IS BASED ON THE FACT THAT INFLAMMATORY & NECROTIC PROCESSES CAUSE AN ALTERATION IN BLOOD PROTEINS, RESULTING IN AGGREGATION OF RBCS, WHICH MAKE THEM HEAVIER & MORE LIKELY TO FALL. ESR IS NOT DIAGNOSTIC OF ANY PARTICULAR DISEASE BUT RATHER IS AN INDICATION THAT A DISEASE PROCESS IS GOING ON IN THE BODY. IT IS ALSO USEFUL IN MONITORING THE PROGRESSION OF THE INFLAMMATORY DISEASE.', '1', 'mm / hr', '0', '15', '0', '0', '0', 'Increased : Any type of infection, inflammation, rheumataic fever, endocarditis, neoplasm, AMI.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('27', 'BLEEDING TIME', '0', '0', 'BLEEDING TIME MEASURES THE PRIMARY PHASE OF HAEMOSTASIS; THE INTERACTION OF PLATELETS WITH THE BLOOD VESSEL WALL & THE FORMATION OF A HEMOSTATIC PLUG. BLEEDING IS THE BEST SINGLE SCREENING TEST FOR PLATELET FUNCTION DISORDERS & IS ONE OF THE PRIMARY SCREENING TEST FOR COAGULATION DISORDERS.\r\nTHIS TEST IS OF VALUE IN DETECTING VASCULAR ABNORMALITIES & PLATELET ABNORMALITIES OF DEFICIENCIES. IT IS NOT RECOMMENDED FOR ROUTINE PRESURGICAL WORKUP.\r\nTHE TEST IS DONE BY AN AUTOMATED SCALPELWHICH CONTROLS THE DEPTH & LENGTH OF INCISION ( USUALLY 1 MM DEEP & 9 MM LONG ) & A SPHYGMOMANOMETER INFLATED TO 40 MM HG DISTENDS THE CAPILLARY BED OF FOREARM UNIFORMLY. AFTER MAKING THE CUT BY SCALPEL TIME IS NOTED TILL BLEEDING STOPS.', '1', 'minutes', '3', '10', '0', '0', '0', 'Inceased : Thrombocytopenia (DIC, TTP, ITP), von Willebrant\'s disease, defective platelet function (NSAIDs such as aspirin), ABNORMALITIES IN THE WALLS OF SMALL BLOOD VESSELS, VASCULAR DISEASE, ADVANCED RENAL FAILURE, SEVERE LIVER DISEASE,LEUKEMIA, OTHER MYELOPROLIFERATIVE DISEASE,SCURVY.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('28', 'CLOTTING TIME', '0', '0', '.', '4', '', '0', '0', '0', '0', '0', 'Increased : Heparin therapy, plasma-clotting factor deficiency (except Factors VII and XIII). (Note : This is not a sensitive test and so is therefore not considered a good screening test.)', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('29', 'PROTHROMBIN TIME', '0', '0', 'PROTHROMBIN IS A PROTEIN PRODUCED BY LIVER FOR CLOTTING OF BLOOD. DURING THE CLOTTING PROCESS PROTHROMBIN IS CONVERTED TO THROMBIN. THE PROTHROMBIN CONTENT OF THE BLOOD IS REDUCED IN PATIENTS WITH LIVER DISEASE.\r\nTHE PT IS ONE OF THE FOUR MOST IMPORTANT SCREENING TESTS USED IN DIAGNOSING COAGULATION DEFECTS. IT DIRECTLY MEASURES A POTENTIAL DEFECT IN STAGE II OF THE CLOTTING MECHANISM ( EXTRINSIC COAGULATION SYSTEM ) THROUGH ANALYSIS OF THE CLOTTING ABILITY OF FIVE PLASMA COAGULATION FACTORS ( PROTHROMBIN, FIBRINOGEN , FACTOR V, FACTOR VII & FACTOR X ). IN ADDITION TO SCREENING FOR DEFICIENCY OF PROTHROMBIN, THE PT IS USED TO EVALUATE DISFIBRINOGENEMIA, EVALUATE THE HEPARIN EFFECT & COUMARIN EFFECT, LIVER FAILURE & VITAMIN K DEFICIENCY.', '1', 'seconds', '11', '13', '0', '0', '0', 'Increased : Drugs (sodium warfarin [Coumadin]), vitamin K deficiency, fat malabsorption, liver disease, prolonged use of a tourniquet before drawing a blood sample, DIC, DEFICIENCY OF FACTOR II ( PROTHROMBIN), V, VII, OR FACTOR X, HAEMORRHAGIC DISEASE OF NEWBORN, LIVER DISEASE, ALCOHOLIC HEPATITIS, BILIARY OBSTRUCTION, ZOLLINGER-ELLISON SYNDROME, HYPOFIBRNIGENEMIA, DYSFIBRINOGENEMIA, LUPUS ANTICOAGULANT ( CIRCULATING ANTICOAGULANTS).\r\n\r\nCONDITIONS THAT DO NOT AFFECT THE PT INCLUDE :\r\n\r\nPOLYCYTHEMIA VERA , TANNIN DISEASE , CHRISTMAS DISEASE , HEMOPHILIA A , VON WILLEBRAND DISEASE , PLATELET DISORDERS ( IDIOPATHIC THROMBOCYTOPENIC PURPURA )\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('44', 'BLOOD UREA', '0', '0', 'UREA FORMS IN THE LIVER & ALONG WITH CO2, CONSTITUTES THE FINAL PRODUCT OF PROTEIN METABOLISM. \r\nTHE TEST FOR BUN, WHICH MEASURES THE NITROGEN PORTION OF UREA, IS USED AS AN INDEX OF GLOMERULAR FUNCTION IN THE PRODUCTION & EXCRETION OF UREA. RAPID PROTEIN CATABOLISM & IMPAIRMENT OF KIDNEY FUNCTION WILL RESULT IN INCREASE BUN LEVELS. IN CHRONIC RENAL DISEASE, THE BUN LEVEL CORRELATES BETTER WITH SYMPTOMS OF UREMIA THAN DOES THE SERUM CREATININE.\r\n', '1', 'MG %', '20', '40', '0', '0', '0', 'Increased : Renal failure (including drug-induced from aminoglycosides, NSAIDs), pre-renal azotemia (decreased renal perfusion secondary to CHF, shock, volume depletion), POSTRENAL (obstruction), GI bleeding, stress, drugs (especially aminoglycosides), HIGH PROTEIN DIET.\r\n\r\nDecreased : Starvation, liver failure (hepatitis, drugs), pregnanay, infancy, nephrotic syndrome, overhydration.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('45', 'SERUM CREATININE', '0', '0', 'CREATININE IS A SUBSTANCE THAT IN HEALTH IS EASILY EXCRETED BY THE KIDNEYS. IT IS THE BY PRODUCT OF MUSCLE ENERGY METABOLISM AND IS PRODUCED AT A CONSTANT RATE ACCORDING TO THE MUSCLE MASS OF THE INDIVIDUAL. ENDOGENOUS CREATININE PRODUCTION IS CONSTANT AS LONG AS THE MUSCLE MASS IS CONSTANT. \r\nDISORDERS OF KIDNEY FUNCTION PREVENT MAXIMUM EXCRETION OF CREATININE WHICH BECOMES HIGH IN THE BLOOD.', '1', 'MG %', '0', '1.2', '0', '0', '0', 'INCREASED : RENAL FAILURE (PRERENAL, RENAL, OR POSTRENAL OBSTRUCTION OR MEDICATION-INDUCED [AMINOGLYCOSIDES, NSAIDS, OTHERS]), GIGANTISM, ACROMEGALY, INGESTION OF ROASTED MEAT, FALSE-POSITIVE WITH DKA, HYPERTHYROIDISM\r\n\r\nDECREASED : PREGNANCY, DECREASED MUSCLE MASS IN DISEASES CHARACTERIZED BY MUSCLE WASTING, SEVERE LIVER DISEASE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('46', 'SERUM URIC ACID', '0', '0', 'URIC ACID IS FORMED FROM THE BREAKDOWN OF NUCLEONIC ACID & IS AN END PRODUCT OF PURINE METABOLISM. ELEVATED LEVELS INDICATE HIGHER RISK OF CHD.', '1', 'mg / ml', '3.4', '6.8', '0', '0', '0', 'INCREASED : GOUT, RENAL FAILURE, DESTRUCTION OF MASSIVE AMOUNTS OF NUCLEOPROTEINS (LEUKEMIA, ANEMIA, CHEMOTHERAPY, TOXEMIA OF PREGNANCY), DRUGS (ESPECIALLY DIURETICS), LACTIC ACIDOSIS, HYPOTHYROIDISM, PCKD, PARATHYROID DISEASES, ETHANOL CONSUMPTION, DOWN SYNDROME, LEAD POISONING, STARVATION, WEIGHT LOSS DIET, DIABETIC KETOACIDOSIS, LIVER DISEASE, HYPERLIPIDEMIA, HEMOLYTIC ANEMIA, SICKLE CELL ANEMIA, PSORIASIS, GLYCOGEN STORAGE DISEASE, OBESITY, SARCOIDOSIS, IDIOPATHIC & DRUGS LIKE MOST DIURETICS, CATECHOLAMINES, ETHAMBUTOL, PYRAZINAMIDE, SALICYLATES, LARGE DOSES OF NICOTINIC ACID. \r\n\r\nDECREASED : URICOSURIC DRUGS (SALICYLATES, PROBENECID, ALLOPURINOL), WILSON\'S DISEASE, FANCONI\'S SYNDROME, XANTHINURIA, SOME MALIGNANCIES LIKE HODGKINS DISEASE, MULTIPLE MYELOMA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('47', 'SERUM BILIRUBIN TOTAL', '0', '0', 'BILIRUBIN RESULTS FROM THE BREAKDOWN OF HAEMOGLOBULIN IN THE RBC & IS A BYPRODUCT OF HAEMOLYSIS. IT IS PRODUCED BY THE RETICULOENDOTHELIAL SYSTEM, REMOVED FROM THE SYSTEM BY LIVER, WHICH EXCRETES IT INTO THE BILE. A RISE IN THE SERUM LEVELS OCCUR WHEN THERE IS AN EXCESSIVE DESTRUCTION OF RED CELLS OR WHEN THE LIVER IS UNABLE TO EXCRETE THE NORMAL AMOUNTS OF BILIRUBIN PRODUCED.\r\nTHERE ARE TWO FORMS OF BILIRUBIN; DIRECT ( CONJUGATED), WHICH CIRCULATES FREELY IN THE BODY UNTIL IT REACHES THE LIVER WHERE IT IS CONJUGATED WITH GLUCORONIDE TRANSFERASE & THEN EXCRETED INTO THE BILE & INDIRECT( UNCONJUGATED) WHICH IS PROTEIN BOUND.\r\nTHE MEASUREMENT OF BILIRUBIN ALLOWS EVALUATION OF LIVER FUNCTION & HAEMOLYTIC ANEMIAS.', '1', 'MG / L', '0.3', '1', '0', '0', '0', 'INCREASED TOTAL : HEPATIC DAMAGE (HEPATITIS, TOXINS, CIRRHOSIS), BILIARY OBSTRUCTION (STONE OR TUMOR), HEMOLYSIS LIKE IN HEMOLYTIC ANEMIA, SICKLE CELL DISEASE, HEMOLYTIC DISEASE OF NEW BORN, PERNICIOUS ANEMIA OR A TRANFUSION REACTION, IN CASES OF ABNORMAL BILIRUBIN METABOLISM LIKE IN GILBERT DISEASE, ROTORS DISEASE, DUBIN-JOHNSON DISEASE, CRIGER-NAJJAR DISEASE,  FASTING, DRUGS LIKE ANTIPSYCHOTIC DRUGS, SEX HORMONES & MANY OTHER.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('49', 'SERUM PROTEIN TOTAL', '0', '0', 'SERUM PROTEINS REPRESENT IMMUNOGLOBULINS, CARRIER PROTEINS & OTHER CLASSES OF PROTEINS. THIS TEST CAN DIAGNOSE OR EVALUATE NEPHROTIC SYNDROME, LIVER DISEASE, NUTRITIONAL STATES & OSMOTIC PRESSURES IN EDEMATOUS AND MALNOURISHED PATIENT.', '1', 'GM %', '6', '8', '0', '0', '0', 'INCREASED : MULTIPLE MYELOMA, WALDENSTROM\'S MACROGLOBULINEMIA, BENIGN MONOCLONAL GAMMOPATHY OF INDETERMINATE SIGNIFICANCE, LYMPHOMA, CHRONIC INFLAMMATORY DISEASE, SARCOIDOSIS, VIRAL ILLNESSES, TROPICAL DISEASE, COLLAGEN DISORDERS LIKE SLE & RHEUMATOID ARTHRITIS, CHRONIC INFECTIONS, IN DEHYDRATION & HAEMOCONCENTRATION BECAUSE OF FLUID LOSS.\r\n\r\nDECREASED : MALNUTRITION, INFLAMMATORY BOWEL DISEASE, HODGKIN\'S DISEASE, LEUKEMIAS, ANY CAUSE OF DECREASED ALBUMIN, SEVERE LIVER DISEASE, ALCOHOLISM, RENAL DISEASE, NEPHROTIC SYNDROME, CROHNS DISEASE, ULCERATIVE COLITIS, SEVERE SKIN DISEASE OR BURN, HEART FAILURE, HYPOTHYROIDISM, PROLONGED IMMOBILIZATION, PREGNANCY\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('50', 'SERUM ALBUMIN', '0', '0', 'ALBUMINS PRIMARY FUNCTION IS THE MAINTENACE OF COLLOIDAL OSMOTIC PRESSURE IN THE VASCULAR & EXTRAVASCULAR SPACES. ALBUMIN IS A SOURCE OF NUTRITION & ALSO A PART OF A COMPLEX BUFFER SYTEM. IT DECREAES IN RESPONSE TO ACUTE INFLAMMATORY INFECTIOUS PROCESSES\r\nALBUMIN IS USED TO EVALUATENUTRITIONAL STATUS, ALBUMIN LOSS IN ACUTE ILLNESS, LIVER DISEASE & RENAL DISEASE WITH PROTEINURIA, HAEMORRHAGE, BURNS, EXUDATES OR LEAKS IN THE G.I. TRACT & OTHER CHRONIC DISEASES.', '1', 'GM %', '3.5', '4.8', '0', '0', '0', 'INCREASED : DEHYDRATION, HAEMOCONCENTRATION.\r\n\r\nDECREASED : MALNUTRITION, MALABSORPTION, OVERHYDRATION, NEPHROTIC SYNDROME, THYROTOXICOSIS, CUSHING DISEASE, FAMILIAL HYPOPROTEINEMIA, CHF, MULTIPLE MYELOMA, HODGKIN\'S DISEASE, LEUKEMIA, METASTATIC CANCER, PROTEIN-LOSING ENTEROPATHIES, CHRONIC GLOMERULONEPHRITIS, ALCOHOLIC CIRRHOSIS, CHR. LIVER DISEASES, INFLAMMATORY BOWEL DISEASE COLLAGEN-VASCULAR DISEASES, HYPERTHYRODISM, LATE PREGNANCY ( DUE TO HAEMODILUTION).', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('51', 'SGOT ( AST )', '0', '0', 'SGOT OR AST IS AN ENZYME PRESENT IN TISSUES OF HIGH METABOLIC ACTIVITY, DECREASING CONC. OF AST ARE FOUND IN THE HEART, LIVER, SKELETAL MUSLES, KIDNEY, BRAIN, PANCREAS, SPLEEN & LUNGS. THE ENZYME IS RELEASED INTO THE BLOOD FOLLOWING THE INJURY TO THE TISSUES. FOLLOWING ANY SEVERE INJURY THE BLOOD AST LEVEL WILL RISE IN 12 HRS AND REMAIN ELEVATED FOR ABOUT5 DAYS.', '1', 'U / L', '0', '35', '0', '0', '0', 'INCREASED : ACUTE MYOCARDIAL INFARCTION, LIVER DISEASE, REYE\'S SYNDROME, MUSCLE TRAUMA AND INJECTION, PANCREATITIS, INTESTINAL INJURY OR SURGERY, FACTITIOUS INCREASE (ERYTHROMYCIN, OPIATES), BURNS, CARDIAC CATHETERIZATION, BRAIN DAMAGE, RENAL INFARCTION & DRUG INDUCED\r\n\r\nDECREASED : BERIBERI (VITAMIN B6 DEFICIENCY), SEVERE DIABETES WITH KETOACIDOSIS, LIVER DISEASE, CHRONIC HEMODIALYSIS & PREGNANCY', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('52', 'SGPT ( ALT )', '0', '0', 'AMINOTRANSFERASE ( ALT ) OR GPT IS AN ENZYME WHICH IS FOUND IN HIGH CONCENTRATION IN LIVER & RELATIVELY LOW CONC. IN HEART, MUSCLE & KIDNEYS.\r\nTHE TEST IS PRIMARILY DONE TO DIAGNOSE LIVER DISEASE & TO MONITOR COURSE OF TREATMENT FOR HEPATITIS. ALT IS MORE SENSITIVE IN THE DETECTION OF LIVER DISEASE THAN IN BILIARY OBSTRUCTION. ALT ALSO DIFFERENTIATES BETWEEN HAEMOLYTIC JAUNDICE & JAUNDICE DUE TO LIVER DISEASE.', '1', 'U / L', '0', '35', '0', '0', '0', 'INCREASED : LIVER DISEASE, LIVER METASTASIS, BILIARY OBSTRUCTION, PANCREATITIS, LIVER CONGESTION (ALT IS MORE ELEVATED THAN AST, AST ELEVATED MORE THAN ALT IN ALCOHOLIC HEPATITIS.), VIRAL, INFECTIOUS OR TOXIC HEPATITIS,INFECTIOUS MONONUCLEOSIS, PANCREATITIS, MYOCARDIAL INFARCTION, HEART FAILURE, POLYMYOSITIS, MYOPATHIES, SEVERE BURNS, SEVERE SHOCK, TRAUMA TO STRIATED MUSCLES, PARACETAMOL OVERDOSE OR DRUG INDUCED.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('53', 'SERUM ALKALINE PHOSPHATASE', '0', '0', 'ALKALINE PHOSPHATASE IS AN ENZYME ORIGINATING MAINLY IN THE BONES, LIVER & PLACENTA WITH SOME ACTIVITY IN THE KIDNEY & INTESTINES.\r\nALKALINE PHOSPHATASE IS USED AS INDEX OF LIVER & BONE DISEASES. IN BONE DISEASE, THE ENZYME LEVEL RISES IN PROPORTION TO NEW BONE CELL PRODUCTION RESULTING FROM OSTEOBLASTIC ACTIVITY & THE DEPOSIT OF CALCIUM IN THE BONES. IN LIVER DISEASE, THE BLOOD LEVEL RISES WHEN EXCRETION OF THIS ENZYME IS IMPAIRED AS A RESULT OF OBSTRUCTION IN THE BILIARY TRACT.', '1', 'u / l', '25', '100', '0', '0', '0', 'INCREASED : INCREASED CALCIUM DEPOSITION IN BONE (HYPERPARATHYROIDISM), PAGET\'S DISEASE, OSTEOBLASTIC BONE TUMORS (METASTATIC OR OSTEOGENIC SARCOMA), INFILTRATIVE BONE DISORDERS, OSTEOMALACIA, RHEUMATOID ARTHRITIS, RICKETS, PREGNANCY, CHILDHOOD, HEALING FRACTURE, LIVER DISEASE SUCH AS BILIARY OBSTRUCTION (MASSES, DRUG THERAPY), INTRAHEPATIC CHOLESTASIS, CHRONIC INFLAMMATORY BOWEL DISEASE, HYPERTHYRODISM.\r\nCHILDREN & ADOLESCENTS TYPICALLY HAVE HIGHER BLOOD ALP LEVELS AS THEIR BONES ARE STILL GROWING.\r\n\r\nDECREASED : MALNUTRITION, EXCESS VITAMIN D INGESTION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('55', 'SERUM AMYLASE', '0', '0', 'AMYLASE CHANGES STARCH TO SUGAR & IS PRODUCED BY SALIVARY GLANDS & PANCREAS; MUCH LOWER ACTIVITIES ARE PRESENT IN THE OVARIES, INTESTINES & SKELETAL MUSCLES.\r\nAMYLASE & LIPASE TESTS ARE DONE TO DIAGNOSE & MONITOR TREATMENT OF ACUTE PANCREATITIS & TO DIFFERENTIATE PANCREATITIS FROM OTHER ACUTE ABDOMINAL CONDITIONS.', '1', 'U / L', '60', '180', '0', '0', '0', 'Increased : Acute pancreatitis, pancreatic duct obstruction (stones, stricture, tumor, sphincter spasm secondary to drugs), pancreatic pseudocyst or abscess, alcohol ingestion, mumps, parotiditis, renal disease, macroamylasemia, cholecystitis, peptic ulcers, intestinal obstruction, mesenteric thrombosis, after surgery, INFARCTION, DIABETIC KETOACIDOSIS.\r\n\r\nDecreased : Pancreatic destruction (pancreatitis, cystic fibrosis), liver damage (hepatitis, cirrhosis), normal newborns in the first year of life.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('56', 'SERUM LIPASE', '0', '0', 'IT IS A GLYCOPROTEIN THAT IN THE PRESENCE OF BILE SALTS & COLIPASE, CHANGES FATS TO FATTY ACIDS & GLYCEROL. PANCREAS IS THE MAJOR SOURCE OF THIS ENZYME. LIPASE APPEARS IN THE BLOOD FOLLOWING PANCREATIC DAMAGE AT THE SAME TIME AS AMYLASE APPEAR BUT REMAINS ELEVATED MUCH LONGER THAN AMYLASE ( 7-10 DAYS).\r\nAMYLASE & LIPASE TESTS ARE DONE TO DIAGNOSE & MONITOR TREATMENT OF ACUTE PANCREATITIS & TO DIFFERENTIATE PANCREATITIS FROM OTHER ACUTE ABDOMINAL CONDITIONS.', '1', 'u / l', '10', '140', '0', '0', '0', 'Increased : Acute or chronic pancreatitis, pseudo-cyst, pancreatic duct obstruction (stone, stricture, tumor, drug-induced spasm), fat embolus syndrome, renal failure, dialysis (usually normal in mumps) gastric malignancy, intestinal perforation, diabetes (usually in DKA only), CHOLECYSTITIS, STRAGULATED OR INFARCTED BOWEL, PERITONITIS, PRIMARY BILIARY CIRRHOSIS, CHRONIC RENAL FAILURE', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('57', 'SERUM CALCIUM', '0', '0', 'INCREASED : HYPERPARATHYROIDISM, VIT D EXCESS, SARCOIDOSIS, MULTIPLE MYELOMA, MALIGNANCY, USE OF THIAZIDE DIURETICS\r\nDECREASED : HYPOPARATHYROIDISM, VIT D DEFICIENCY, RENAL FAILURE, MAGNESIUM DEFICIENCY, HYPOALBUMINURIA', '1', 'MG / L', '9', '10.5', '0', '0', '0', 'Increased : (Note : Levels > 12 mg/dL [2.99 mmol/L] may lead to coma and death) Primary hyperparathyroidism, PTH-secreting tumors, vitamin D excess, metastatic bone tumors, osteoporosis, immobilization, milk-alkali syndrome, Paget\'s disease, idiopathic hypercalcemia of infants, infantile hypophosphatasia, thiazide diuretics, chronic renal failure, sacroidosis, multiple myeloma.\r\n\r\nDecreased : (Note Levels <7mg/dL [<1.75 mmol/L] May lead to tetany and death.) Hypoparathyroidism (surgical, idiopathic), pseudo-hypoparathyroidosm, insufficient vitamin-D, calcium and phosphorus ingestion (pregnancy, osteomalacia, rickets), hypomagnesemia, renal tubular acidosis, hypoalbuminemia (cachexia, nephrotic syndrome, CF), chronic renal failure (phosphate retention), acute pancreatitis, factitious decrease because of low protein and albumin.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('59', 'SERUM CHOLESTEROL', '0', '0', 'IT EVALUATES RISK FOR ATHEROSCLEROSIS & IS IMPORTANT SCREENING TEST FOR HEART DISEASE. CHOLESTROL DETERMINATION IS ALSO FREQUENTLY A PART OF THYROID FUNCTION, LIVER FUNCTION, RENAL FUNCTION & DIABETES MALLITUS STUDIES. IT IS ALSO USED TO MONITOR EFFECTIVENESS OF DIET, MEDICATION, LIFESTYLE CHANGES & STRESS MANAGEMENT.', '1', 'MG / L', '150', '240', '0', '0', '0', 'Increased : Idiopathic hypercholesterolemia, biliary obstruction, nephrosis, hypothyroidism, pancreatic disease (diabetes), pregnancy, oral contraceptives, hyperlipoproteinemia (types Iib, III, V), HEPATOCELLULAR DISEASE, BILIARY CIRHOSIS, CHR. RENAL FAILURE, ALCOHOLISM, POORLY CONTROLED DIABETES MALLITUS, HIGH CHOLESTROL DIET, OBESITY.\r\n\r\nDecreased : Liver disease (hepatitis, etc), hyperthyroidism, malnutrition (cancer, starvation), chronic anemias, steroid therapy, HYPO-ALPHA-lipoproteinemias, AMI, MENTAL RETARDATION, CHRONIC OBSTRUCTIVE LUNG DISEASE, SEVERE BURN , INFECTIONS.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('64', 'SERUM LIPIDS TOTAL', '0', '0', 'LIPOPROTEIN MEASUREMENTS ARE DIAGNOSTIC INDICATORS FOR HYPERLIPIDEMIA & HYPOLIPIDEMIA. LIPIDS ARE FATTY SUBSTANCES MADE UP OF CHOLESTROL, CHOLESTROL ESTERS, TRIGLYCERIDES, NONESTERIZED FATTY ACIDS & PHOSPHOLIPIDS. A LIPID PROFILE USUALLY INCLUDES CHOLESTROL, TRIGLYCERIDES, LDL & HDL LEVELS.', '1', 'mg / ml', '175', '550', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('65', 'SERUM SODIUM', '0', '0', 'IT IS ONE OF VERY IMPORTANT ELECTROLYTES OF THE BODY WHICH IS ALTERED IN MANY BODY CONDITIONS AND DISEASES.', '1', 'MEQ / L', '135', '145', '0', '0', '0', 'Increased : Associated with low total body sodium (glycosuria, mannitol, or lactulose use urea, excess sweating), normal total body sodium (diabetes insipidus [central and nephrogenic], respiratory losses, and sweating), and increased total body sodium (administration of hypertonic sodium bicarbonate, Cushing\'s syndrome, hyperaldosteronism).\r\n\r\nDecreased : Associated with excess total body sodium and water (nephrotic syndrome, CHF, cirrhosis, renal failure), excess body water (SAIDH, hypothyroidism, adrenal insufficiency), decreased total body water and sodium (diuretic use, renal tubular acidosis, use of mannitol or urea, mineralocorticoid deficiency, vomiting, diarrhea, pancreatitis), and psuedo-hyponatremia (hyperlipidemia, hyperglycemia, and multiple myeloma).\r\nINCREASED : DIABETES INSIPIDUS, DEHYDRATION, HYPERALDOSTERONISM\r\nDECREASED : C.H.F., CIRRHOSIS, USE OF DIURETICS, ADRENAL INSUFFICIENCY, COMPULSIVE WATER DRINKING, INAPPROPRIATE SECRETION OF ADH, OVERHYDRATION', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('66', 'SERUM POTASSIUM', '0', '0', 'IT IS ONE OF THE VERY IMPORTANT ELECTROLYTE OF THE BODY & IS ALTERED IN MANY BODY CONDITIONS AND DISEASES.', '1', 'MEQ / L', '3.3', '5.4', '0', '0', '0', 'INCREASED : RENAL FAILURE, USE OF POTASSIUM SPARING DIURETICS & ACETYLCHOLINESTERASE INHIBITORS, ADRENAL INSUFFICIENCY, ACIDOSIS\r\nDECREASED : DIARRHOEA, VOMITING, DIURETICS, STEROIDS, NEPHROTIC SYNDROME, DIABETES, CUSHING DISEASE, EXCESSIVE RENIN SEC', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('67', 'SERUM CHLORIDE', '0', '0', 'INCREASED : RENAL FAILURE, RENAL TUBULAR ACIDOSIS\r\nDECREASED : VOMITING, PYLORIC STENOSIS, OVER TREATMENT WITH DIURETICS', '1', 'MEQ / L', '98', '106', '0', '0', '0', 'Increased :  Diarrhoea, renal tubular acidosis, mineralocorticoid deficiency, hyperalimentation, medication (acetazolamide, ammonium chloride)\r\n\r\nDecreased : Vomiting, diabetes mellitus with ketoacidosis, mineralocorticoid excess, renal disease with sodium loss.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('68', 'CPK ( MALE )', '0', '0', 'CREATINE PHOSPHOKINASE ( CK / CPK ) IS AN ENZYME FOUND IN HIGHER CONCENTRATIONS IN THE HEART & SKELETAL MUSCLES & IN MUCH SMALLER AMOUNT IN BRAIN TISSUE. BECAUSE CK EXISTS IN RELATIVELY FEW ORGANS, THIS TEST IS USED AS A SPECIFIC INDEX OF INJURY TO MYOCARDIUM & MUSCLE.\r\nCPK CAN BE DEVIDED INTO THREE ISOENZYMES; MM OR CK3, BB OR CK1 & MB OR CK2. CK-MM IS THE ISOENZYME THAT CONSTITUTES ALMOST ALL THE CIRCULATORY ENZYMES IN HEALTHY PERSONS. SKELETAL MUSCLE CONTAINS PRIMARILY MM; CARDIAC MUSCLE CONTAINS PRIMARILY MM & MB; AND BRAIN TISSUE, G.I. SYSTEM & GENITOURINARY TRACT CONTAIN PRIMARILY BB. NORMAL CK LEVELS ARE VIRTUALLY 100% MM ISOENZYMES. A SLIGHT INCREASE IN TOTAL CPK LEVEL IF REFLECTED FROM ELEVATED BB , IS FROM BRAIN INJURY.CPK ISOENZYME STUDIES HELP DISTINGUISH WHETHER THE CPK ORIGINATED FROM HEART ( MB ) OR FROM SKELETAL MUSCLE ( MM ).\r\nNEWER TESTS, SUCH AS CK ISOFORMS, ALLOW FOR EARLIER DETECTION OF M.I. THAN IS POSSIBLE WITH CK-MB.', '1', 'U / L', '25', '90', '0', '0', '0', 'Increased : Muscle damage )AMI, myocarditis, muscular dystrophy, muscle trauma [including injections], after surgery), brain infarction, defibrillation, cardiac catheterization and surgery, rhabdomyolysis, polymyositis, hypothyroidism.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('69', 'CPK (MB)', '0', '0', 'CREATINE PHOSPHOKINASE ( CK / CPK ) IS AN ENZYME FOUND IN HIGHER CONCENTRATIONS IN THE HEART & SKELETAL MUSCLES & IN MUCH SMALLER AMOUNT IN BRAIN TISSUE. BECAUSE CK EXISTS IN RELATIVELY FEW ORGANS, THIS TEST IS USED AS A SPECIFIC INDEX OF INJURY TO MYOCARDIUM & MUSCLE.\r\nCPK CAN BE DEVIDED INTO THREE ISOENZYMES; MM OR CK3, BB OR CK1 & MB OR CK2. CK-MM IS THE ISOENZYME THAT CONSTITUTES ALMOST ALL THE CIRCULATORY ENZYMES IN HEALTHY PERSONS. SKELETAL MUSCLE CONTAINS PRIMARILY MM; CARDIAC MUSCLE CONTAINS PRIMARILY MM & MB; AND BRAIN TISSUE, G.I. SYSTEM & GENITOURINARY TRACT CONTAIN PRIMARILY BB. NORMAL CK LEVELS ARE VIRTUALLY 100% MM ISOENZYMES. A SLIGHT INCREASE IN TOTAL CPK LEVEL IF REFLECTED FROM ELEVATED BB , IS FROM BRAIN INJURY.CPK ISOENZYME STUDIES HELP DISTINGUISH WHETHER THE CPK ORIGINATED FROM HEART ( MB ) OR FROM SKELETAL MUSCLE ( MM ).\r\nNEWER TESTS, SUCH AS CK ISOFORMS, ALLOW FOR EARLIER DETECTION OF M.I. THAN IS POSSIBLE WITH CK-MB. IT RISES IN 4-6 HRS, PEAK IN 12 - 24 HRS & LASTS FOR 4 -5 DAYS.', '1', 'MICRO GM / L', '0', '7', '0', '0', '0', 'INCREASED : MYOCARDIAL INFARCTION', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('70', 'SERUM L.D.H.', '0', '0', 'IT IS AN INTRACELLULAR ENZYME WHICH IS WIDELY DISTRIBUTED IN THE TISSUES, PARTICULARLY IN KIDNEYS, HEART, SKELETAL MUSCLES, BRAIN, LIVER & LUNGS.INCREASE IN THE VALUE USUALLY MEANS CELLULAR DEATH & LEKAGE OF THE ENZYME FROM THE CELLS.\r\nALTHOUGH IT IS NON SPECIFIC BUT IT IS USEFUL IN CONFIRMING MYOCARDIAL OR PULMONARY INFARCTION WHEN VIEWED IN RELATION TO OTHER TEST FINDINGS.', '1', 'u / l', '140', '280', '0', '0', '0', 'INCREASED : AC. M.I., PUL. INFARCTION, CHF, CIRRHOSIS LIVER, ALCOHOLISM, AC. VIRAL HEPATITIS, MALIGMNANT NEOPLASMS, LEUKEMIA, LYMPHOMAS, HYPOTHYROIDISM, LUNG IDSEASES, SKELETAL MUSCLE DISEASES, MUSCULAR DAMAGE, MYOPATHIES, MEGALOBLASTIC & PERNICIOUS ANEMIA, HEMOLYTIC ANEMIA, SICKLE CELL ANEMIA, DELIRIUM TREMENS, SEIZURES, SHOCK, HYPOXIA, HYPOTENSION, HYPERTHERMIA, RENAL INFARCTS, CNS DISEASES, AC. PANCREATITIS, FRACTURES & OTHER TRAUMA INCLUDING HEAD, INTESTINAL OBSTRUCTION.\r\n\r\nDECREASED : DECREASED LDH LEVELS ARE ASSOCIATED WITH GOOD RESPONSE TO CANCER THERAPY.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('73', 'CREATININE CLEARENCE TEST', '0', '0', 'CREATININE IS A SUBSTANCE THAT IN HEALTH IS EASILY EXCRETED BY THE KIDNEYS. IT IS THE BY PRODUCT OF MUSCLE ENERGY METABOLISM AND IS PRODUCED AT A CONSTANT RATE ACCORDING TO THE MUSCLE MASS OF THE INDIVIDUAL. ENDOGENOUS CREATININE PRODUCTION IS CONSTANT AS LONG AS THE MUSCLE MASS IS CONSTANT. \r\nDISORDERS OF KIDNEY FUNCTION PREVENT MAXIMUM EXCRETION OF CREATININE WHICH BECOMES HIGH IN THE BLOOD. BECAUSE ALL CREATININE FILTERED BY THE KIDNEYS IN A GIVEN TIME INTERVAL IS EXCRETED INTO THE URINE, CREATININE LEVELS ARE EQUIVALENT TO THE GLOMERULAR FILTRATION RATE ( GFR ).\r\nCCT IS PART OF MOST BATTERIES OF QUANITATIVE URINE TESTS. CREATININE CLEARANCE IS MEASURED TOGATHER WITH OTHER URINARY COMPONENTS IN ORDER TO INTERPRET THE OVERALL EXCRETION RATE OF THE VARIOUS URINARY COMPONENTS.\r\nCREATININE CLEARANCE TEST IS A SPECIFIC MEASUREMENT OF KIDNEY FUNCTION, PRIMARILY GLOMERULAR FILTRATION. IT MEASURES THE RATE AT WHICH THE KIDNEYS CLEAR CREATININE FROM THE BLOOD.', '1', 'mg / kg / 24 hrs', '14', '26', '0', '0', '0', 'INCREASED : STATE OF HIGH CARDIAC OUTPUT, PREGNANCY, BURNS, CARBON MONOXIDE POISONING.\r\n\r\nDECREASED : IT IS FOUND IN ANY CONDITION WHICH DECREASES RENAL BLOOD FLOW LIKE - IMPAIRED KIDNEY FUNCTIONS, INTRINSIC RENAL DISEASE, GLOMERULONEPHRITIS, PYELONEPHRITIS, NEPHROTIC SYNDROME, AC. TUBULAR DYSFUNCTION, AMYLOIDOSIS, INTERSTITIAL NEPHRITIS, SHOCK, HAEMORRHAGE, DEHYDRATION, CHR. OBSTRUCTIVE LUNG DISEASE, CHF.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('74', 'GLUCOSE TOLERANCE TEST ( II - 30 MTS )', '0', '0', 'IN HEALTHY INDIVIDUALS THE INSULIN RESPONSE TO A LARGE ORAL GLUCOSE DOSE IS ALMOST IMMIDIATE. IT PEAKS IN 30 MTS TO 60 MTS & RETURNS TO NORMAL LIMITS WITHIN 3 HRS WHEN SUFFICIENT INSULIN IS PRESENT OT METABOLISE THE GLUCOSE INGESTED. THE TEST SHOULD BE PERFORMED ACCORDING TO THE WHO GUIDELINES USING GLUCOSE LOAD CONTAINING THE EQUIVALENT OF 75 - 100 GMS OF ANHYDROUS GLUCOSE DISSOLVED IN WATER OR OTHER SOLUTION.', '1', 'mg %', '110', '170', '0', '0', '0', 'Increased : Diabetes mellitus, Cushing\'s acromegaly, increased epinephrine (injection, pheochromocytoma, stress, burns, etc), acute pancreatitis, ACTH administration, spurious increase caused by drawing blood from a site above an IV line containing dextrose, elderly patients, pancreatic glucagonoma, drugs (glucocorticoids, some diuretics).\r\n\r\nDecreased : Pancreatic disorders (pancreatitis, islet cell tumors), extrapancreatic tumors (carcinoma of the adrenals, stomach), hepatic disease (hepatitis, cirrhosis, tumors), endocrine disorders (early diabetes, hypothyroidism, hypopituitarism), functional disorders (after gastrectomy), pediatric problems (prematurity, infant of a diabetic mother, ketotic hypoglycemia, enzyme diseases), exogenous insulin, oral hypoglycemic agents, malnutrition, sepsis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('75', 'SERUM MAGNESIUM', '0', '0', 'MAGNESIUM IN THE BODY IS CONCENTRATED IN BONES, MUSCLE, WITHIN THE CELLS ITSELF & IN THE SERUM. IT IS REQUIRED FOR THE USE OF ADENOSINE TRIPHOSPHATE ( ADP ) AS A SOURCE OF ENERGY. IT IS THEREFORE NECESSARY FOR THE ACTION OF NUMEROUS ENZYME SYSTEMS SUCH AS CARBOHYDRATE METABOLISM, PROTEIN SYNTHESIS, NUCLEIC ACID SYNTHESIS & CONTRACTION OF MUSCLE TISSUE.\r\nMAGNESIUM & CALCIUM ARE INTIMATELY LINKED IN THEIR BODY FUNCTIONS & DEFICIENCY OF EITHER ONE HAS A SIGNIFICANT EFFECT ON THE METABOLISM OF THE OTHER. MAGNESIUM MEASUREMENT IS USED TO EVALUATE RENAL FUNCTION, ELECTROLYTE STATUS & EVALUATE MAGNESIUM METABOLISM.', '1', 'mg / ml', '1.8', '2.6', '0', '0', '0', 'Increased : Renal failure, hypothyroidism, magnesium-containing antacids, Addison\'s disease, diabetic coma, severe dehydration, lithium intoxication.\r\n\r\nDecreased : malabsorption, steatorrhea, alcoholism and cirrhosis, hyperthyroidism, aldosteronism, diuretics, acute pancreatitis, hyperparathyroidism, hyperalimenation, NG suctioning, chronic dialysis, renal tubular acidosis, drugs (cisplatin, amphotericin B, aminoglycosides0, hungry bone syndrome, hypophosphatemia, intracellular shifts with respiratory or metabolic acidosis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('77', 'SERUM IRON ( MALE )', '0', '0', 'TOTAL IRON BINDING CAPACITY ( TIBC ) CORELATES WITH SERUM TRANSFERRIN, BUT THE RELATION IS NOT LINEAR. A SERUM IRON TEST WITHOUT A TIBC AND TRASNSFERRIN DETERMINATION HAS VERY LIMITED VALUE EXCEPT IN CASES OF IRON POISONING. TRANSFERRIN SATURATION IS A BETTER INDEX OF IRON SATURATION; IT IS EVALUATED AS FOLLOWS :\r\nTRANSFERRIN SATURATION % = S. IRON * 100 / TIBC\r\n THE COMBINED RESULTS OF TRANSFERRIN, IRON & TIBC TESTS ARE HELPFUL IN THE DIFFERENTIAL DIAGNOSIS OF ANEMIA, IN THE ASSESSMENT OF IRON DEFIICIENCY ANEMIA & IN THE EVALUATION OF THALASSEMIA, SIDEROBLASTIC ANEMIA & HEMOCHROMATOSIS.', '1', 'mcg / ml', '65', '175', '0', '0', '0', 'Increased : hemochromatosis, hemosiderosis caused by excessive iron intake, excess destruction or decreased production of erythrocytes, liver necrosis, HEMOLYTIC ANEMIA, ESPECIALLY THALASSEMIA, PERNICIOUS ANEMIA IN RELAPSE; IRON OVERLOAD SYNDROME, MULTIPLE TRANSFUSIONS, INAPPROPRIATE IRON THERAPY, VIT B6 DEFICIENCY, LEAD POISONING, AC. LEUKEMIA, NEPHRITIS.\r\n\r\nDecreased : Iron deficiency anemia, nephrosis (loss of iron-binding proteins), normochromic anemia of chronic diseases and infections, ACUTE & CHRONIC BLOOD LOSS, LATE PREGNANCY.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('81', 'RA FACTOR', '0', '0', 'THE BLOOD OF MANY PERSONS WITH RA CONTAIN A MACROGLOBULIN TYPE ANTIBODY CALLED RHEUMATOID FACTOR. EVIDENCE INDICATES THAT RHEUMATOID FACTORS ARE ANTI-GAMMA-GLOBULIN ANTIBODIES. RF IS SOMETIMES FOUND IN BLOOD SERUM FROM PATIENTS WITH OTHER DISEASES, ALTHOUGH RF INCIDENCE AND VALUES ARE HIGHER IN PATIENTS WITH RA.\r\nTHIS TEST IS USEFUL IN DIAGNOSING RA. IT MEASURES RFS ( ANTIBODIES DIRECTED AGAINST THE FC FRAGMENT OF IGG). THESES ARE USUALLY IGM ABTIBODIES, BUT THEY MAY ALSO BE IGG OR IGA.', '1', 'u / ml', '0', '20', '0', '0', '0', 'Increased : Collagen-vascular diseases (RA, SLE, scleroderma, polyarteritis nodosa others), infections (TB, syphilis, viral hepatitis), chronic inflammation, SBE, some lung diseases, MI.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('84', 'C-REACTIVE PROTEIN', '0', '0', 'DURING AN INFLAMMATORY PROCESS, THIS ABNORMAL PROTEIN APPEARS IN THE BLOOD. THIS PROTEIN IS VERTUALLY ABSENT FROM THE BLOOD OF HEALTHY PERSONS. CRP IS ONE OF THE MOST SENSITIVE ACUTE PHASE REACTANTS. LEVELS OF CRP CAN INCREASE DRAMATICALLY ( 100 FOLDS OR MORE ) AFTER TRAUMA, BACTERIAL INFECTION, INFLAMMATION, SURGERY OR NEOPLASTIC PROLIFERATION.\r\nMEASUREMENT OF CRP HAS BEEN USED HISTORICALLY TO ASSESS ACTIVITY OF INFLAMMATORY DISEASE, TO DETECT INFECTIONS AFTER SURGERY, TO DETECT TRANSPLANT REJECTION & TO MONITOR THESE INFLAMMATORY PROCESSES. IT IS SEEN HIGH JUST PRIOR TO ACUTE MYOCARDIAL INFARCTION & IS TAKEN AS INDICATOR OF IMPENDING INFARCTION.', '1', 'mg / ml', '0', '0.8', '0', '0', '0', 'Increased: Bacterial infections, inflammatory conditions (acute rheumatic fever, acute R.A. MI, transplant rejection, embolus, inflammatory bowel disease), last half of pregnancy, oral contraceptives, some malignancies.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('85', 'ANTI-NUCLEAR ANTIBODY TEST', '0', '0', 'MEASUREMENT OF ANA IN THE SERUM IS THE MOST COMMONLY PERFORMED SCREENING TEST FOR AUTOANTIBODIES IN PATIENTS SUSPECTED OF HAVING SYSTEMIC RHEUMATIC DISEAESE( SRD ) ESPECIALLY IF THE TITER IS > 1:160. SRD IS ALSO CALLED AS CONNECTIVE TISSUE OR COLLAGEN DISEASES , WHICH ARE SLE, MIXED CONNECTIVE TISSUE DISEASE, DRUG INDUCED LUPUS LIKE SYNDROME ( PROCAINAMIDE, HYDRALAZINE, ISONIAZID ETC ), SJOGREN SYNDROME, SCLERODERMA, CREST SYNDROME ( CALCINOSIS, RAYNAUDS PHENOMENON, EOSOPHAGEAL DYSFUNCTION, SCLERODACTYLY & TELANGIECTASIA ), RHEUMATOID ARTHRITIS, POLYMYOSITIS, DERMATOMYOSITIS.', '2', '', '0', '0', '2', '0', '0', 'LOW TITRES ARE PRESENT IN ELDERLY, DRUGS LIKE PROCAINAMIDE, PHENYTOIN, ETHOSUXIMIDE, PRIMIDONE, METHYL DOPA, PENICILLAMINE, CARBAMAZEPINE, THIAZIDE DIURETICS, GRISEOFULVIN, CHLORPROMAZINE, ISONIAZID, QUINIDINE, GOLD SALTS, MINOCYCLINE & HYDRALAZINE. VIRAL ILLNESSES & SOME CHRONIC INFECTIONS MAY CAUSE POSITIVE RESULTS LIKE SLE, RHEUMATOID ARTHRITIS, MIXED CONNECTIVE TISSUE DISORDERS,, SJOGRENS SYNDROME, NECROTISING VASCULITIS, TUBERCULOSIS, CHR. ACTIVE HEPATITIS, SABE, HIV INFECTION, TYPE I DIABETES MALLITUS, MULTIPLE SCLEROSIS, PULMONARY FIBROSIS, SILICON GEL IMPLANTS, PREGNANCY.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('87', 'SERUM IGA', '0', '0', 'FIVE CLASSES OF IMMUNOGLOBULINS - IGA, IGG, IGM, IGD, IGE, HAVE BEEN ISOLATED. IMMUNOGLOBULINS FUNCTION TO NEUTRALIZE TOXIC SUBSTANCES, SUPPORT PHAGOCYTOSIS, DESTROY MICRO-ORGANISM FUNCTIONS.\r\nIGA TAKES TWO FORMS; SERUM & SECRETORY. SERUM IGA IS PRESENT IN BLOOD SERUM; SECRETORY IGA IS PRESENT IN SALIVA, TEARS, COLOSTRUM & BRONCHIAL, GASTROINTESTINAL & GENITOURINARY SECRETIONS, WHERE IT CAN PROTECT AGAINST MICROORGANISM INVASION. IGA ACCOUNTS FOR 10 - 15% OF TOTAL IMMUNOGLUBULINS.', '1', 'mg / ml', '60', '400', '0', '0', '0', 'INCREASED : CHR. NONALCOHOLIC LIVER DISEASES ESPECIALLY PRIMARY BILIARY CIRRHOSIS, OBSTRUCTIVE JAUNDICE, EXERCISE, ALCOHOLISM, SUBACUTE & CHRONIC INFECTIONS.\r\n\r\nDECREAES : ATAXIA TELANGIECTASIA, CHR. SINOPULMONARY DISEASE,CONGENITAL DEFICIT, LATE PREGNANCY, PROLONGED EXPOSURE TO BENZENE IMMUNOSUPPRESSIVE THERAPY, ABSTINENCE FROM ALCOHOL AFTER A PERIOD OF 1 YR., DRUGS & DEXTRIN & PROTEIN LOSING GASTROENTEROPATHIES.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('90', 'WIDAL TEST', '1', '0', 'DONE TO RULE OUT OR DIAGNOSE TYPHOID OR PARATYPHOID FEVER. IT GENERALLY BECOMES POSITIVE FROM 5 - 7 DAYS OF THE FEVER. THE TITRE MORE THAN 1/160 IN THE ABSENCE OF RECENT IMMUNIZATION IS DIAGNOSTIC & IT MAY REMAIN HIGH EVEN AFTER 2-6 MTHS OF SUCCESSFUL TREATMENT. TITRE BECOMES PROGRESSIVELY HIGH IN CASE OF NON TREATMENT OR UNSUCCESSFUL TREATMENT.', '4', '', '0', '0', '0', '0', '0', 'IN ENTERIC FEVER SPECIFIC AGGLUTININS ARE USUALLY DETECTABLE AFTER AT LEAST 7 DAYS OF FEVER.\r\nSERA FROM NORMAL INDIVIDUALS MAY SHOW AGGLUTINATION IN TITER OF 1:80. TITER OF 1:160 OR MORE ARE SPECIFIC.\r\nA SINGLE POSITIVE RESULT HAS LESS SIGNIFICANCE THAN A RISING AGGLUTININ TITER.\r\nA RISE IN THE TITER OF ALL THREE \"H\" AGGLUTININ IS RESULT OF TAB VACCINATION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('91', 'MONTOUX TEST', '1', '0', 'IT IS A TYPE OF ANTIGEN-ANTIBODY REACTION TO DIAGNOSE THE PRESENCE OF ANTIBODIES AGAINST TUBERCULAR BACILLI IN THE BODY. AN INDURATION OF MORE THAN 10 MM AFTER 72 HRS OF TUBERCULIN TEST WITH .1 ML OF 5 T.U. PPD SIGNIFIES POSITIVE REACTION BUT POSITIVE REACTION DOES NOT NECESSARILY SIGNIFY THE PRESENCE OF ACTIVE TUBERCULOSIS. FURTHER DIAGNOSTIC TESTS SHOULD BE DONE BEFORE DISNOSIS OF TUBERCULOSIS IS MADE.', '2', '', '0', '0', '2', '0', '0', 'DOUBTFUL REACTION : INDURATION MEASURING BETWEEN 5 & 9 MM\r\n\r\nNEGATIVE REACTION : INDURATION OF LESS THAN 5 MM.THIS INDICATES LACK OF HYPERSENSTIVITY TO TUBERCULOPROTEIN & TUBERCULAR INFECTION IS HIEGHLY UNLIKELY. \r\nIT SHOULD BE NOTED THAT REACTIVITY TO TUBERCULIN MAY BE DEPRESSED OR SUPPRESSED FOR AS LONG AS FOUR WEEKS BY VIRAL INFECTION, LIVE VIRUS VACCINES OR BY THE ADMINISTRATION OF CORTICOSTEROIDS. MALNUTRITION MAY ALSO HAVE THE SIMILAR EFFECTS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('94', 'IGG MYCOBACTERIUM TUBERCULOSIS', '0', '0', 'IT IS A FORM OF IMMUNOGLOBULIN THAT OCCUR LATE IN AN INFECTIOUS PROCESS.\r\nTHIS TEST IS DONE & IS POSITIVE ONLY WHEN THE TUBERCULOSIS IS THERE IN THE BODY FOR SOME TIME & LATENT PULMONARY OR EXTRA PULMONARY INFECTION', '2', '', '0', '0', '2', '0', '0', 'AFFECTED BY PRIOR BCG VACCINATION, EXPOSURE TO NONTUBERCULAR MYCOBACTERIA.\r\nANTIBODIES MAY NOT DEVELOP IN ANERGIC PATIENTS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('95', 'IGM MYCOBACTERIUM TUBERCULOSIS', '0', '0', 'IGM IS A FORM OF IMMUNOGLOBULIN WHICH OCCURS EARLY IN AN INFECTIOUS PROCESS.\r\nTHIS TEST IS DONE TO ASCERTAIN A RECENTLY ACQUIRED  TUBERCULAR INFECTION OF THE BODY & LATENT PULMONARY OR EXTRA PULMONARY INFECTION', '2', '', '0', '0', '2', '0', '0', 'AFFECTED BY PRIOR BCG VACCINATION, EXPOSURE TO NONTUBERCULAR MYCOBACTERIA.\r\nANTIBODIES MAY NOT DEVELOP IN ANERGIC PATIENTS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('98', 'THYROGLOBULIN', '0', '0', 'THE TEST IS HELPFUL IN THE DIFFERENTIAL DIAGNOSIS OF HYPERTHYROIDISM & IN MONITORING THE COURSE OF DIFFERENTIATED OR METASTATIC THYROID CANCER. NOT USEFUL IN THE DIAGNOSIS OF THYROID CANCER. LEVELS DECREASE FOLLOWING SUCCESSFUL INITIAL TREATMENT & IN RECURRENCE OF METASTASIS, THE LEVELS WILL RISE AGAIN. LACK OF SENSTIVITY & SPECIFICITY LIMITS THE VALUE OF THIS TEST.', '1', 'ng / ml', '3', '42', '0', '0', '0', 'Increased : Differentiated thyroid carcinomas (papillary, follicular), Graves disease, nontoxic goiter( BENIGN ADENOMA), SUCACUTE THYROIDITIS, OCCURRENCE OF METASTASIS AFTER INITIAL TREATMENT( THYROID CANCER).\r\nDecreased : Hypothyroidism, TREATMENT WITH testosterone, steroids, phenytoin, THYROTOXICOSIS FACTITIA, INFANTS WITH GOITROUS HYPOTHYROIDISM.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('100', 'DENGU SEROLOGY (IGG & IGM)', '0', '0', 'DENGUE SPECIFIC IGM ANTIBODIES IS COMMONLY USED METHOD FOR DETECTING AN ACTIVE PRIMARY DENGUE INFECTION. IGM ANTIBODIES ARE TYPICALLY PRODUCED AT DETECTABLE LEVELS BY DAY 5 AFTER THE ONSET OF FEVER OR SYMPTOMS.\r\nIN SECONDARY DENGUE INFECTIONS, IGG ANTIBODIES ARE PRODUCED AT VERY HIGH LEVELS. SOME MAY PRODUCE DETECTABLE LEVELS AT DAY 3 AFTER ONSET OF FEVER BUT IDEAL WINDOW FOR DETECTION IS DAY 6 ONWARDS.', '2', '', '0', '0', '2', '0', '0', '.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('101', 'ACTH STIMULATION TEST', '0', '0', 'THIS DETECTS ADRENAL INSUFFUCIENCY AFTER CORTROSYN ADMINISTRATION. CORTROSYN IS A SYNTHETIC SUBUNIT OF ACTH THAT EXIBITS THE FULL CORTICOSTEROID-STIMULATING EFFECTS OF ACTH IN HEALTHY PERSONS. FAILURE TO RESPOND IS AN INDICATION OF ADRENAL INSUFFUCUENCY. THIS SCREENING TEST IS LESS TIME CONSUMING AND CAN BE DONE ON AN OUTPATIENT BASIS.', '1', 'nmol / l', '0', '552', '0', '0', '0', 'Increased : Addison\'s disease (primary adrenal hypofunction), ectopic ACTH production (small [oat] cell lung carcinoma, pancreatic islet cell tumors, thymic tumors, renal cell carcinoma, bronchial carcinoid), Cushing\'s disease (pituitary adenoma), congenital adrenal hyperplasia (adrenogenital syndrome). \r\nDecreased : Adrenal adenoma or carcinoma, nodular adrenal hyperplasia, pituitary insufficiency, corticosteroid use.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('103', 'STOOL ROUTINE', '1', '1', 'ROUTINE STOOL EXAMINATION IS DONE FOR DETECTING ANY KIND OF PARASITIC INFESTATION, FOR EVIDENCE OF ANY BLOOD LOSS FROM THE GUT OR MALABSORPTION STUDY.', '4', '', '0', '0', '0', '0', '0', '.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('105', 'STOOL FOR OCCULT BLOOD', '0', '0', 'AN AVERAGE HEALTHY PERSON PASSES UPTO 2.0 ML OF BLOOD PER 150 GMS OF STOOL. \r\nNORMALLY ITS VALUE IS NEGATIVE IN THE STOOL.', '2', '', '0', '0', '2', '0', '0', 'Positive : Any GI tract ulcerated lesion (ulcer, carcinoma, polyp, diverticulosis, inflammatory bowel disease), hemorrhoids, telangiectasias, drugs that cuase GI irritation (eg, NSAIDs) swallowed blood, ingestion of rare red meat, certain foods (horseradish, turnips) (vitamin C [>500 mg/d], antacids may result in false-negative test).', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('106', 'URINE PREGNANCY TEST', '0', '0', 'IN THIS URINARY HCG LEVELS ARE MEASURED WHICH IS PRODUCED BY VERY YOUNG PLACENTAL TROPHOBLAST. THE TEST BECOMES POSITIVE AFTER 5 - 7 DAYS OF CONCEPTION & BECOMES NEGATIVE AFTER 3 - 4 DAYS OF DELIVERY.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('107', 'URINE ROUTINE', '1', '1', 'IN URINE ROUTINE EXAMINATION WE DETERMINE FOLLOWING PROPERTIES : COLOR, ODOR, TURBIDITY, SPECIFIC GRAVITY, PH, GLUCOSE, KETONES, PROTEIN, BILIRUBIN, UROBILINOGEN, NITRITE, BLOOD, LEUKOCYTES  & OTHER CONSTITUENTS IN THE MICROSCOPIC EXAMINATION.\r\nVOLUME - NORMAL URINE OUTPUT - 600 ML - 2500 ML\r\nSPECIFIC GRAVITY - IT IS THE MEASUREMENT OF KIDNEYS ABILITY TO CONCENTRATE URINE.\r\nURINE PH - THE PH IS AN INDICATOR OF THE RENAL TUBULES ABILITY TO MAINTAIN NORMAL HYDROGEN ION CONCENTRATION IN THE PLASMA & EXTRACELLULAR FLUID.KIDNEYS MAINTAIN ACID-BASE BALANCE PRIMARILY THROUGH RESORPTION OF SODIUM & TUBULAR SECRETION OF HYDROGEN & AMONIUM IONS.\r\nBLOOD IN URINE - MAY BE DUE TO RENAL OR GENITO-URINARY DISEASE LIKE UTI, NEPHRITIS, LUPUS NEPHRITIS, URINARY TRACT OR RENAL TUMOURS, CALCULI,MALIGNANT HYPERTENSION, GLOMERULONEPHRITIS, PYELONEPHRITIS, TRAUMA, POLYCYSTIC KIDNEY DISEASE, LEUKEMIA, THROMBOCYTOPENIA & STRENUOUS EXERCISE.\r\nURINE ALBUMIN - IT CAN BE AN IMPORTANT INDICATOR OF RENAL DISEASE. NORMALLY THERE IS NO PROTEIN OR ONLY TRACE OF PROTEIN IN THE URINE. \r\nURINE GLUCOSE - GLUCOSE IS PRESENT IN GLOMERULAR FILTRATE & IS REABSORBED BY THE PROXIMAL CONVOLUTED TUBULES. THE BLOOD LEVEL AT WHICH TUBULAR RESORPTION STOPS IS TERMED, RENAL THRESHOLD WHICH FOR GLUCOSE IS 160-180 MG/ML. IF THE BLOOD GLUCOSE LEVELS EXCEED RESORPTION CAPACITY OF THE TUBULES, GLUCOSE WILL APPEAR IN THE URINE.\r\nKETONE BODIES - KETONES RESULT FROM THE METABOLISM OF FATTY ACIDS & FAT.WHEN CARBOHYDRATE METABOLISM IS ALTERED, AN EXCESSIVE AMOUNT OF KETONES ARE FORMED. \r\nURINE WBC - NORMALLY NO WBCS ARE PRESENT IN THE URINE.\r\nURINE BILIRUBIN - ELEVATED AMOUNTS APPEAR WHEN NORMAL DEGRADATION CYCLE IS DISRUPTED BY OBSTRUCTION OF THE BILE DUCT OR WHEN THE INTEGRITY OF LIVER IS DAMAGED. AN EARLY SIGN OF HEPATO-BILIARY DYSFUNCTION.\r\nURINE CAST - ITS PRESENCE INDICATES RENAL DISEASE\r\nWHEATHER IT IS GRANULAR, HYALINE, RBC OR WBC CAST.\r\nURINE CRYSTALS - SOME CRYSTALS ARE PRESENT IN THE URINE NORMALLY & QUANTITY MAY DEPEND ON URINE PH AND DIET.\r\nOTHER URINE FINDINGS - URINE SHREDS WHICH CONSIST OF MUCUS, PUS & EPITHELIAL CELLS. OTHER SUSTANCES MAY BE YEAST, TRICHOMONAS, SPERMATOZOA, VEGETABLE FIBRES, PARASITES & MEAT FIBRES.\r\n', '4', '', '0', '0', '0', '0', '0', 'VOLUME INCREASED - DIABETIC KETOACIDOSIS, DIABETES MALLITUS, DIABETES INCIPIDUS, RENAL TUBULAR NECROSIS, NEUROTIC DISEASE.\r\nVOLUME DECREASED - GLOMERULONEPHRITIS, RENAL ISCHAEMIA, DEHYDRATION, OBSTRUCTIVE PATHOLOGY, CARDIAC INSUFFICIENCY.\r\nSPECIFIC GRAVITY - INCREASED IN DIABETES MALLITUS, NEPHROSIS, DEHYDRATION, INCREASED SECRETION OF ADH, CHF, TOXAEMIA OF PREGNANCY.\r\nDECREASED - NEPHROTIC SYNDROME, CHRONIC RENAL FAILURE, DIABETES INSIPIDUS, GLOMERULONEPHRITIS, PHELONEPHRITIS.\r\nURINE PH - INCREASED > 7 :- UTI CAUSED BY UREA SPLITTING BACTERIA( PROTEUS & PSEUDOMONAS ), RENAL TUBULAR ACIDOSIS, CHRONIC RENAL FAILURE, METABOLIC ACIDOSIS, RESPIRATORY ALKALOSIS INVOLVING HYPERVENTILATION & POTASSIUM DEPLETION.\r\nPH REDUCED < 7 :- METABOLIC ACIDOSIS, DIABETIC KETOSIS, DIARRHOEA, STARVATION, UREMIA, UTI CAUSED BY E.COLI, RESPIRATORY ACIDOSIS, RENAL TUBERCULOSIS, PYREXIA.\r\nURINE PROTEIN - PRESENT IN GLOMERULONEPHRITIS, SLE, MALIGNANT HYPERTENSION, AMYLOIDOSIS, DIABETES MALLITUS, NEPHROTIC SYNDROME, POLYCYSTIC KIDNEY DISEASE, WILSON DISEASE, FANCONI SYNDROME ETC, ETC.\r\nURINE SUGAR - PRESENT IN DIABETES, ENDOCRINE DISORDERS, PANCREASE & LIVER DISEASES, BRAIN INJURY, STROKE.\r\nURINE KETONE BODIES - INCREASED IN DIABETES & FASTING, GLYCOGEN STORAGE DISEASE, HIGH-FAT DIETS, PROLONGED VOMITINGS & DIARROHEA, FEVER, PREGNANCY, HYPERTHYROIDISM.\r\nURINE WBC - PRESENT IN INFECTION.\r\nURINE BILIRUBIN - RAISED IN LIVER DISEASES & HEPATITIS, BILIARY TRACT DISEASES, SEPTICEMIA, HYPERTHYROIDISM.\r\nURINE CAST :- PRESENT IN GLOMERULONEPHRITIS, RENAL TUBULAR DISEASE, PYELONEPHRITIS, AC. BACTERIAL ENDOCARDITIS, GOODPASTURE SYNDROME, MALIGNANT HYPERTENSION.\r\nURINE CRYSTALS - ITS PRESENCE MAY INDICATE CHANCES OF URINARY CALCULUS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('112', 'URINE ALBUMIN( 24 HRS ) FOR MALE', '0', '0', 'IF MORE THAN TRACE OF ALBUMIN IS FOUND PERSISTENTLY, A QUANTITATIVE 24-HR EVALUATION OF PROTEIN EXCRETION IS NECESSARY.', '1', 'mg / ml', '1', '14', '0', '0', '0', 'INCREASED IN DIABETICS IN DIABETIC NEPHROPATHY, HYPERTENSION, GENERAKISED VASCULAR DISEASE & PREECLAMPSIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('113', 'URINE FOR MICROALBUMIN', '0', '0', 'MICROALBUMINURIA IS AN INCREASE IN URINARY ALBUMIN THAT IS BELOW THE DETECTABLE RANGE OF THE STANDARD PROTEIN DIPSTICK TEST. IT IS NOT A DIFFERENT FORM OF ALBUMIN. MICROALBUMINURIA OCCURS LONG BEFORE CLINICAL PROTEINURIA BECOMES EVIDENT.\r\nTHIS TEST HAS BECOME STANDARD FOR THE SCREENING, MONITORING & DETECTION OF DETERIORATING RENAL FUNCTION IN DIABETIC PATIENTS.', '1', 'mg / day', '0', '30', '0', '0', '0', 'INCREASED IN DIABETICS IN DIABETIC NEPHROPATHY, HYPERTENSION, GENERAKISED VASCULAR DISEASE & PREECLAMPSIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('117', 'T3', '0', '0', 'IT IS THE TEST OF CHOICE IN THE DIAGNOSIS OF T3 THYROTOXICOSIS. IT IS NOT THE SAME AS THE T3 UPTAKE TEST THAT MEASURES THE UNSATURATED TBG IN SERUM. IT CAN ALSO BE VERY USEFUL IN THE DIAGNOSIS OF HYPERTHYROIDISM.', '1', 'ng / ml', '80', '200', '0', '0', '0', 'Increased : Hyperthyroidism, T3 thyrotoxicosis, pregnancy, exogenous T4, any cause of increased TBG, such as oral estrogen or pregnancy, ACUTE THYROIDITIS, EARLY THYROID FAILURE, IODINE DEFICIENCY GOITER.\r\n\r\nDecreased : Hypothyroidism and erthyroid sick state, any cause of decreased TBG, STARVATION & STATE OF NUTRITION SUBACUTE NONTHYROID ILLNESS ( 70% ).\r\n\r\nREFERENCE RANGE :\r\n\r\nAGE                BOYS                  GIRLS\r\n1-7 DAYS      210 - 578              238 -534\r\n8-15 DAYS    98 - 377                 83 - 372\r\n1-3 YRS         126 - 253             138 - 217 \r\n4-6 YRS         112 - 236              148 - 261\r\n7-8 YRS         125 - 260              143 - 270\r\n9-10 YRS       114- 220                109 - 202\r\n11 YRS          141 - 220               132 - 255\r\n12 YR S         139 - 262               146 - 219\r\n13 YRS          134 - 262               132 - 239\r\n14 YRS          128 - 220               117 - 213\r\n15 YRS          112 - 224               105 - 198\r\n16 YRS          115 - 219               107 - 199\r\n17 YRS          76 - 164                 78 - 188  \r\n18-19 YRS     79 - 152                 52 - 139', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('118', 'T4', '0', '0', 'TOTAL T4 LEVEL IS A GOOD INDEX OF THYROID FUNCTION WHEN THE TBG IS NORMAL. THE INCREASE IN TBG LEVELS NORMALLY SEEN IN PREGNANCY & WITH OESTROGEN THERAPY INCREAES TOTAL T4 LEVELS. THE DECREASE OF TBG LEVELS IN PERSONS RECEIVING ANABOLIC STEROIDS, IN CHRONIC LIVER DISEASE & IN NEPHROSIS DECREASES THE TOTAL T4 LEVELS.\r\nTHIS TEST IS COMMONLY DONE TO RULE OUT HYPOTHYROIDISM, HYPERTHYROIDISM & AS GUIDE TO DRUG TREATMENT IN HYPO OR HYPERTHYROIDISM.', '1', 'nmol / l', '5.4', '11.5', '0', '0', '0', 'Increased : Hyperthyroidism, exogenous thyroid hormone, estrogens, pregnancy, severe illness, euthyroid sick syndrome, ACUTE THYROIDITIS, HEPATITIS, LIVER DISEASE, LYMPHOMA.\r\n\r\nDecreased : Hypothyroidism, euthyroid sick syndrome, any cause of decreased TBG, HYPOPROTEINEMIA, NEPHROTIC SYNDROME, TREATMENT WITH TRIIODOTHYRONINE.\r\n\r\nREFERENCE RANGE :\r\n\r\nAGE              BOYS                    GIRLS\r\n1-7 DAYS      7.7 - 61                   4.8 -67   \r\n8-15 DAYS    21 - 66                 13.6 - 83\r\n1-3 YRS         4.8 - 10.6             6.5 - 13.3 \r\n4-6 YRS          6.2 - 11.7              7.8 - 12.6\r\n7-8 YRS         6.3 - 14.0              7.6 - 12.4\r\n9-10 YRS       4.7- 15.6                5.8 - 14.3\r\n11 YRS          6.3 - 11.1               06.2 - 12.5\r\n12 YR S         7.2 - 10.9               6.5 - 9.0\r\n13 YRS          5.1 - 10.2               5.2 - 9.5\r\n14 YRS          6.2 - 9.6               6.8 - 11.1\r\n15 YRS          5.1 - 9.9               5.7 - 9.5\r\n16 YRS          5.5 - 9.6              5.7 - 9.5\r\n17 YRS          4.6 - 9.8               6.2 - 8.7  \r\n18-19 YRS     4.7 - 9.2                4.8 - 9.0', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('119', 'TSH', '0', '0', 'IT IS THE SINGLE MOST SENSITIVE TEST FOR PRIMARY HYPOTHYROIDISM. TSH IS PRODUCED BY PITUTARY GLAND & ITS RELEASE IS STIMULATED BY THYROTROPIN RELEASING HORMONE FROM THE HYPOTHALAMUS & NEGATIVE FEEDBACK BY SERUM T3 & T4 LEVELS.', '1', 'm iu / ml', '0.4', '4.2', '0', '0', '0', 'Increased : Hypothyroidism, THYROTROPIN PRODUCING TUMOURS( ECTOPIC TSH SECRETION FROM LUNG , BREAST TUMOURS), HASHIMOTO THYROIDITIS, THYROTOXICOSIS DUE TO PITUTARY TUMOR, HYPOTHYROID PATIENTS RECEIVING INSUFFICIENT THYROID REPLACEMENT HORMONE OR THYROID HORMONE RESISTANCE, TSH ANTIBODIES, ASSAY ARTIFACTS, TSH SECRETING PITIUTARY TUMOR.\r\n\r\nDecreased : Hyperthyroidism. Less than 1% of hypothyroidism is from pituitary or hypothalamic disease resulting in a decreased TSH. SECONDARY & TERTIARY HYPOTHYROIDISM, TREATED GRAVES DISEASE, EUTHYROID SICK DISEASE, OVERPLACEMENT OF THYROID HORMONE IN THE TREATMENT OF HYPOTHYROIDISM, 1ST TRIMESTER OF PREGNANCY ( DUE TO HCG SECRETION ), IN RESPONSE TO CERTAIN MEDICINES ( HIGH DOSES OF GLUCO - CORTICOIDS OR DOPAMINE ).\r\nPREGNANCY :\r\nNORMAL VALUE -  0.20 - 3.50 \r\nCHILDREN :\r\nMIDGESTATION FETUS           0.70 - 11.0\r\nLBW CORD SERUM                  1.30 - 20.0\r\nTERM INFANTS                         1.30 - 19.0\r\n3 DAYS OLD                               1.10 - 17.0\r\n10 WEEKS OLD                          0.60 - 10.0\r\n14 MTHS OLD                             0.40 - 7.0\r\n5 YRS OLD                                  0.40 - 6.0', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('125', 'SERUM TESTOSTERONE ( TOTAL ) FOR MALE', '0', '0', 'TESTOSTERONE EXISTS IN SERUM AS BOTH UNBOUND( FREE ) FRACTION & BOUND FRACTION TO ALBUMIN. \r\nTESTOSTERONE MEASUREMENTS IN MEN ASSESS HYPOGONADISM, PITUTARY GONADOTROPIN FUNCTION, IMPOTENCY & CRYPTORCHIDISM. IN WOMEN THIS IS USEFUL IN DETECTING OVARIAN TUMORS & HIRSUTISM. THIS TEST MAY BE PART OF A FERTILITY WORKUP IN ASSOCIATION WITH CHRONIC ANOVULATION CAUSED BY POLYCYSTIC OVARY SYNDROME.', '1', 'ng / dl', '270', '1070', '0', '0', '0', 'Increased : Adrenogenital syndrome, HYPERTHYROIDISM, SYNDROME OF ANDROGEN RESISTANCE, QADRENAL TUMORS, PRECOCIOUS PUBERTY & ADRENAL HYPERPLASIA IN BOYS.\r\novarian stromal hyperthecosis, polycystic ovaries, menopause, ovarian tumors.\r\n\r\nDecreased : Some cause of impotence, hypogonadism, hypopituitarism, Klinefelter\'s syndrome,ORCHIDECTOMY, CIRRHOSIS LIVER, DOWN SYNDROME, DELAYED PUBERTY.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('127', 'SERUM CORTISOL ( 8.00 A.M. )', '0', '0', 'CORTISOL ( HYDROCORTISONE ) IS A GLUCOCORTICOID OF ADRENAL CORTEX & AFFECTS METABOLISM OF PROTEINS, CARBOHYDRATES & LIPIDS. CORTISOL STIMULATES GLUCOGENESIS BY THE LIVER, INHIBITS THE EFFECT OF INSULIN & DECREASES THE RATE OF GLUCOSE USE BY THE CELLS. IN HEALTH, THE SECRETION RATE OF CORTISOL IS HIGHER IN THE EARLY MORNING & LOWER IN THE EVENING. THIS VARIATION IS LOST IN PATIENTS WITH CUSHING SYNDROME & IN PERSONS UNDER STRESS.\r\nTHIS TEST EVALUATES ADRENAL HORMONE FUNCTION. SUPPRESSION & STIMULATION TEST CAN ALSO BE DONE. CORTISOL SUPPRESSION TEST ( DEXAMETHASONE ) SCREENS FOR CUSHING SYNDROME & IDENTIFIES DEPRESSED PERSONS WHO ARE LIKELY TO RESPOND TO ANTIDEPRESSANTS OR SHOCK THERAPY. IT IS BASED ON THE FACT THAT ACTH PRODUCTION IS SUPPRESSED IN HEALTHY PERSONS AFTER A LOW DOSE OF DEXAMETHASONE BUT NOT IN PERSONS WITH CUSHING SYNDROME OR IN SOME DEPRESSED PERSONS.', '1', 'nmol / l', '138', '635', '0', '0', '0', 'Increased : Adrenal adenoma, adrenal carcinoma, Cushing\'s disease, nonpituitary ACTH-producing tumor, steroid therapy, oral contraceptives, HYPERTHYROIDISM, STRESS (TRAUMA, SURGERY), CARCINOMA ( EXTREEM ELEVATION IN THE MORNING & NO VARIATION IN THE EVENING), OBESITY.\r\n\r\nDecreased : Primary adrenal insufficiency (Addison\'s disease), congenital adrenal hyperplasia, Waterhouse-Friderichsen syndrome, ACTH deficiency, HYPOTHYROIDISM ( HYPOPITUITARISM).\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('130', 'URINE CULTURE TEST', '1', '0', 'CULTURE TEST HELPS IN ISOLATING THE OFFENDING AGENT AS WELL AS IN TREATING THE DISEASE BY FINDING OUT THE MOST SUITABLE DRUG AFTER SENSTIVITY TEST RESULTS.\r\nTHIS TEST CAN BE PERFORMED ON ANY BODY FLUID OR DISCHARGE TO KNOW THE OFFENDING AGENT & THE DRUGS TO WHICH IT IS SENSITIVE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('132', 'FNAC', '1', '0', 'FINE NEEDLE ASPIRATION CYTOLOGY ( FNAC ) IS USEFUL IN CASES WHERE BIOSY IS NEEDED TO CONFIRM THE DIAGNOSIS. IT IS MINIMAL INVASIVE TECHNIQUE TO TAKE OUT TISSUE SAMPLE FROM THE DISEASED AREA WHICH CAN BE SEEN UNDER MICROSCOPE AFTER STAINING FOR HISTOPATHOLOGY.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('137', 'X-RAY CHEST P.A. VIEW( NORMAL )', '1', '0', 'DONE TO SEE ANY LUNG DISEASE OR INJURY OR ANY CHEST WALL INJURY OR BONE DISEASE. CHEST X-RAY IS DONE TO EVALUATE CARDIAC SIZE & CARDIAC DISEASES ALSO.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('139', 'X-RAY ABDOMEN A.P. VIEW FOR KUB', '1', '0', 'DONE TO SEE FOR ANY RENAL STONE OR ANY STONE IN THE KIDNEYS, URETERS OR URINARY BLADDER REGION.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('144', 'X-RAY PELVIS A . P. VIEW', '1', '0', 'DONE TO SEE BONE INJURY OR DISEASE', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('147', 'X-RAY CHEST APICOGRAM', '1', '0', 'DONE TO SEE ANY LUNG DISEASE ENVOLVING APICES.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('149', 'X-RAY BARIUM SWALLOW', '1', '0', 'DONE TO DIAGNOSE HIATUS HERNIA, EOSOPHAGITIS, EOSOPHAGEAL TUMOURS OR ACHALASIA CARDIA LIKE EOSOPHAGEAL ABNORMALITIES.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('150', 'X-RAY BARIUM FOLLOW THROUGH', '1', '0', 'DONE TO DIAGNOSE OBSTRUCTIVE, INFLAMMATORY OR STRUCTURAL PATHOLOGY OF INTESTINES.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('151', 'X-RAY BARIUM UPPER G.I.', '1', '0', 'DONE TO SEE FOR ANY UPPER G.I. DISORDERS LIKE EOSOPHAGITIS, EOSOPHAGEAL TUMOURS, GASTRIC ULCERS, GASTRITIS, PYLORIC STENOSIS, GASTRIC TUMOURS ETC, ETC.', '4', '', '0', '0', '0', '0', '0', 'WITH THE ADVENT OF MORE SOFISTICATED INVESTIGATIONS LIKE ENDOSCOPY IT IS LOOSING ITS VALUE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('153', 'X-RAY CHEST LAT. VIEW', '1', '0', 'DONE TO SEE ANY LUNG DISEASE OR INJURY OR ANY CHEST WALL INJURY OR BONE DISEASE. CHEST X-RAY IS DONE TO EVALUATE CARDIAC SIZE & CARDIAC DISEASES ALSO.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('154', 'X-RAY ABDOMEN ERECT VIEW', '1', '0', 'DONE TO DIAGNOSE INTESTINAL PERFORATION OR OBSTRUCTION.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('157', 'X-RAY HAND A.P. & OBLIQUE VIEW', '1', '0', 'DONE TO SEE ANY BONY INJURY OR DISEASE', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('159', 'X-RAY I.V.P.', '1', '0', 'DONE TO SEE KIDNEY FUNCTION , ANY OBSTRUCTIVE RENAL PATHOLOGY OR ANY SPACE OCCUPYING OR ERODING LESION.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('161', 'X-RAY LEG A.P. & LAT. VIEW', '1', '0', 'DONE TO SEE LEG BONE INJURY OR DISEASE', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('162', 'X-RAY LUMBO-SACRAL SPINE A.P. & LAT. VIEW', '1', '0', 'DONE TO SEE VERTIBRAL DISEASE OR INJURY', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('165', 'X-RAY SKULL A.P. & LAT. VIEW', '1', '0', 'DONE TO VIEW SKULL BONE INJURY OR DISEASE AS WELL AS TO SEE PITUTARY FOSSA OR SELLA TURSICA', '4', '', '0', '0', '0', '0', '0', 'WITH THE ADVENT OF C.T. SCAN & M.R.I. TO DIAGNOSE INTRA CRANIAL PATHOLOGY , PLAIN X-RAY SKULL HAS LOST ITS IMPORTANCE FOR THESE INDICATIONS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('169', 'X-RAY THORACO-LUMBER SPINE A.P. & LAT. VIEW', '1', '0', 'DONE TO VIEW VERTIBRAL INJURY OR DISEASE', '4', '', '0', '0', '0', '0', '220', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('170', 'X-RAY LUMBER SPINE A.P. & LAT. VIEW', '1', '0', 'DONE TO SEE VERTIBRAL DISEASE OR INJURY', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('174', 'ULTRA SOUND WHOLE ABDOMEN - FEMALE', '1', '0', 'IT IS NONINVASIVE TECHNIQUE TO DIAGNOSE INTRAABDOMINAL PATHOLOGIES. IT IS QUITE SENSITIVE AND SAFE DURING EARLY PREGNANCY ALSO.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('175', 'ULTRA SOUND WHOLE ABDOMEN - MALE', '1', '0', 'IT IS NONINVASIVE TECHNIQUE TO DIAGNOSE INTRAABDOMINAL PATHOLOGIES.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('176', 'ULTRA SOUND K.U.B.', '1', '0', 'IT IS A NONINVASIVE INVESTIGATION WHICH CAN HELP TO EVALUATE INTRA-ABDOMINAL CONDITIONS RELATED TO KIDNEYS, URETERS AND URINARY BLADDER', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('177', 'ULTRA SOUND OBSTETRICS', '1', '0', 'THE ULTRASOUND HAS BECOME A VERY IMPORTANT TOOL TO DIAGNOSE ANY POSSIBILITY OF CONGENITAL PHYSICAL DEFORMITY IN THE FETUS , CEPHALOPELVIC DISPROPORTION, HYDROAMNIOS, MULTIPLE PREGNANCIES OR OTHER ABNORMALITIES IN THE PREGNANT WOMEN.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('179', 'STRESS MYOCARDIAL PERFUSION SCAN', '1', '0', 'MYOCARDIAL PERFUSION STATUS CAN BE KNOWN DURING STRESS BY THIS TEST.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('183', 'MUGA ( MULTIGATED ACQUISITION IMAGING ) STRESS', '1', '0', 'THE PRIMARY PURPOSE OF THIS TEST IS TO PROVIDE AN EJECTION FRACTION DURING CARDIAC CYCLE. ONCE INJECTED THE DISTRIBUTION OF RADIOLABELED RBC IS IMAGED BY SYNCHRONIZATION OF THE RECORDING OF CARDIAC IMAGES WITH THE ECG. THIS TECHNIQUE PROVIDES A MEANS OF OBTAINING INFORMATION ABOUT CARDIAC OUTPUT, END-SYSTOLIC VOLUME, END-DIASTOLIC VOLUME, EJECTION FRACTION, EJECTION VELOCITY & REGIONAL WALL MOTIONS OF THE VENTRICLES. THIS PROCEDURE MAY ALSO BE PERFORMED AS STRESS TEST. MUGA SCANS ARE NOT OFTEN PERFORMED ON CHILDREN.', '4', '', '0', '0', '0', '0', '0', 'INDICATIONS : CHF, CHANGES IN VENTRICULAR FUNCTION DUE TO INFARCTION, PERSISTENT ARRHYTHMIAS FROM POOR VENTRICULAR FUNCTION, REGURGITATION DUE TO VALVULAR DISEASE, VENTRICULAR ANEURYSM FORMATION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('186', 'CAPTOPRIL INTERVENTION RENOGRAM', '1', '0', 'RENOGRAM IS PERFORMED TO STUDY THE FUNCTION OF KIDNEYS & TO DETECT RENAL PARENCHYMAL OR VASCULAR DISEASE OR DEFECTS IN EXCRETION.\r\nTEST IS DONE IN CHILDREN SAFELY BECAUSE OF NONTOXIC NATURE OF THE RADIOPHARMACEUTICALS IN COMPARISION TO CONTRAST MEDIUMS. PROCEDURE IS DONE TO EVALUATE HYDRONEPHROSIS, OBSTRUCTION, REDUCED RENAL FUNCTION, RENAL TRAUMA, UTI & POST RENAL TRANSPLANTATION.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('187', 'RENAL DMSA SCAN', '1', '0', 'A RADIOTRACER( TECHNITIUM ) IS INJECTED INTO THE VEIN & RENAL SCAN IS TAKEN BY GAMMA CAMERA WHICH GIVES INFORMATION ABOUT THE SIZE, POSITION & SHAPE OF KIDNEYS & WHETHER THERE ARE SCARS IN THE KIDNEYS FROM A PREVIOUS INFECTIONS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('189', 'BONE SCAN', '1', '0', 'FOR FINDING OUT BONY METASTASIS OR BONE TUMOURS', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('192', 'MRI CARDIAC WITH CINE MRI', '1', '0', 'USED TO SEE CARDIAC FUNCTION AND ABNORMALITIES', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('195', 'RENAL DOPPLER', '1', '0', 'TO SEE FOR RENAL ARTRY STENOSIS OR OTHER VESSELS ABNORMALITIES. IT PROVIDES A COLOR CODED DEPICTION OF SELECTED BLOOD FLOW PARAMETERS', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('198', 'COLOR DOPPLER ABDOMINAL', '1', '0', 'A PHENOMENON THAT ACCOMPANIES MOVEMENT, THE DOPPLER EFFECT, CAN BE COMBINED WITH DIAGNOSTIC ULTRA SOUND IMAGING TO PRODUCE DUPLEX SCANS. DUPLEX SCANS PROVIDE ANATOMIC VISUALIZATION OF BLOOD VESSELS & A GRAPHIC REPRESENTATION OF BLOOD FLOW CHARACTERISTICS. FLOW DIRECTION, VELOCITY & THE PRESENCE OF FLOW DISTURBANCES CAN RADILY BE ASSESSED.', '4', '', '0', '0', '0', '0', '0', 'USED TO DIAGNOSE PORTAL HYPERTENSION, AORTA AND OTHER LARGE VESSELS PATENCY OR ABNORMALITIES.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('205', 'ALPHA FETOPROTEIN ( ADULT )', '0', '0', 'ALPHA-FETOPROTEIN IS A GLYCOPROTEIN PRODUCED BY FETAL LIVER, YOLK SAC & INTESTINAL EPITHELIUM. DISAPPEARS FROM BLOOD SOON AFTER BIRTH & IS NOT PRESENT IN HEALTHY INDIVIDUALS. ( < 5.8 IU / ML ). \r\nIT DIAGNOSE & MONITOR AFP TUMORS, FOLLOW UP FOR THERAPY OF TESTICULAR, OVARIAN & PRIMARY LIVER TUMORS. IT IS USED WITH HCG.', '1', 'iu / mL', '0', '30', '0', '0', '0', 'Increased : Hepatoma (hepatocellular carcinoma), testicular tomor (embryonal carcinoma, malignant teratoma), neural tube defects (in mother\'s serum [spina bifida, anencephaly, myelomeningocele], fetal death, multiple gestations, ataxia-telagiectasia, some cases of benign hepatic diseases (alcoholic cirrhosis, hepatitis, necrosis). YOLK SAC OVARIAN TUMORS, TERATOCARCINOMA, GASTRIC, PANCREATIC, COLONIC, BREAST, RENAL, LUNG CANCERS. OTHER NON CANCEROUS DISEASES ARE G.I. TUMORS, PRIMARY BILIARY CIRRHOSIS, PARTIAL HEPATECTOMY, WISKOTT-ALDRICH SYNDROME, MULTIPLE PREGNANCIES & ABORTION.\r\n\r\nDecreased : Trisomy 21 (Down syndrome) in maternal serum\r\n\r\nTABLE SHOWING CORELATION OF MEAN SERUM & AMNIOTIC FLUID AFP & GESTATIONAL AGE\r\n\r\nGESTATION IN WKS      MEAN SERUM AFP        AMNIO. AFP\r\n\r\n5-11                                      6.00\r\n12                                        15.20   \r\n13                                         19.10\r\n14                                          28.60\r\n15                                          34.00                                   15.20\r\n16                                          39.30                                   12.80 \r\n17                                          44.50                                    10.00\r\n18                                          52.00                                      9.30\r\n19                                          62.20                                       6.80\r\n20                                          69.60                                       5.90\r\n21                                          81.60\r\n22 - 30                                   126.20\r\n31 - 40                                   152.00', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('207', 'ANGIOTENSIN CONVERTING ENZYME', '0', '0', 'ANGIOTENSIN I IS PRODUCED BY THE ACTION OF RENIN ON ANGIOTENSINOGEN. ANGIOTENSIN I-CONVERTING ENZYME ( ACE ) CATALIZES THE CONVERSION OF ANGIOTENSIN I TO THE VASOACTIVE PEPTIDE ANGIOTENSIN II. ANGIOTENSIN I IS CONCENTRATED IN THE PROXIMAL TUBULES.\r\nTHIS TEST IS USED PRIMARILY TO EVALUATE THE SEVERITY & ACTIVITY OF SARCOIDOSIS.SERIAL DETERMINATIONS MAY BE HELPFUL IN FOLLOWING THE CLINICAL COURSE OF THE DISEASE WITH STEROID TREATMENT. IT IS ALSO USED IN THE INVESTIGATION OF GAUCHER DISEASE.', '1', 'U / L', '8', '53', '0', '0', '0', 'INCREASED : SARCOIDOSIS, GAUCHER DISEASE, LEPROSY, AC & CHR BRONCHITIS, CONNECTIVE TISSUE DISORDERS, AMYLOIDOSIS, PULMONARY FIBROSIS, FUNGAL DISEASES & HISTOPLASMOSIS, UNTREATED HYPERTHYROIDISM, DIABETES MALLITUS, PSORIASIS, PREMATURE INFANTS WITH RESPIRATORY DISTRESS SYNDROME.\r\n\r\nDECREASED : FOLLOWING PREDNISOLONE TREATMENT OF SARCOIDOSIS, ADVANCED LUNG NEOPLASMS, STARVATION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('211', 'BLOOD SUGAR ( AFTER MEALS )', '0', '0', 'GLUCOSE IS FORMED FROM CARBOHYDRATE DIGESTION & CONVERSION OF GLYCOGEN TO GLUCOSE BY THE LIVER. THE TWO HORMONES THAT DIRECTLY REGULATE BLOOD GLUCOSE LEVELS ARE GLUCAGON & INSULIN. GLUCAGON ACCELERATES GLYCOGEN BREAKDOWN IN THE LIVER & CAUSES THE BLOOD GLUCOSE LEVELS TO RISE. INSULIN INCREAES CELL MEMBRANE PERMEABILITY TO GLUCOSE, TRANSPORT GLUCOSE INTO CELLS, STIMULATES GLYCOGEN FORMATION, & REDUCE BLOOD GLUCOSE LEVELS.', '1', 'MG %', '100', '136', '0', '0', '0', 'INCREASED : DIABETES MALLITUS, CUSHING SYNDROME, AC. EMOTIONAL OR STRESS SITUATION, PHEOCHROMOCYTOMA, ACROMEGALY, GIGANTISM, PITUITARY ADENOMA, HEMOCHROMATOSIS, PANCREATITIS, GLUCAGONOMA, ADVANCED LIVER DISEASE, CHR. RENAL DISEASE, WERNICKES ENCEPHALOPATHY.\r\n\r\nDECREASED : PANCREATIC ISLET CELL CARCINOMA, EXTRAPANCREATIC STOMACH TUMORS, ADDISON DISEASE, , HYPOPITUITARISM, HYPOTHYROIDISM, ACTH DEFICIENCY, STARVATION,LIVER DAMAGE ( ALCOHOLISM, ARSENIC POISONING, CHLOROFORM POISONING), PREMATURE INFANTS, ENZYME DEFICIENCY DISEASES ( GALACTOSEMIA, INHERITED MAPLE SYRUP DISEASE, VON GIERKES SYNDROME), INSULIN OVERDOSE, REACTIVE HYPOGLYCEMIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('213', 'BLOOD CULTURE', '1', '0', 'BLOOD CULTURE IS DONE IN INFECTIOUS DISEASES TO FIND OUT THE OFFENDING ORGANISM PRESENT IN THE BODY.', '4', '', '0', '0', '0', '0', '0', 'RESULT OF CULTURE DEPENDS ON MANY FACTORS LIKE PRIOR USE OF ANTIBIOTICS, TIME OF SAMPLE COLLECTION & CULTURE MEDIUM USED FOR GROWING ORGANISM.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('214', 'STOOL CULTURE', '1', '0', 'STOOL CULTURE IS DONE TO FIND OUT THE OFFENDING ORGANISM PRESENT IN THE GUT.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('215', 'LATEX AGGLUTINATION TEST FOR ANTIBODY TO VI ANTIGEN', '0', '0', 'IT IS MORE SPECIFIC & SENSITIVE THAN WIDAL TEST ( SENSTIVITY >95% ) WITH VERY LOW RATES OF FALSE NEGATIVITY', '2', '', '0', '0', '1', '0', '0', 'POSITIVE - TYPHOID FEVER', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('218', 'ANTI-THYROGLOBULIN ANTIBODIES', '0', '0', 'ANTI-THYROGLOBULIN ANTIBODIES ARE DIRECTED AGAINST THE GLYCOPROTEIN THYROGLOBULIN LOCATED IN THE THYROID FOLLICLES', '2', '', '0', '0', '2', '0', '0', 'INCREASED : HASHIMOTO THYROIDITIS, GRAVES DISEASE, THYROID CARCINOMA, IDIOPATHIC MYXEDEMA, PERNICIOUS ANAEMIA, SLE, R. ARTHRITIS, SJOGREN SYNDROME, SUBACUTE THYROIDITIS, NON TOXIC NODULAR GOITER.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('236', 'SERUM IRON ( FEMALE )', '0', '0', 'TOTAL IRON BINDING CAPACITY ( TIBC ) CORELATES WITH SERUM TRANSFERRIN, BUT THE RELATION IS NOT LINEAR. A SERUM IRON TEST WITHOUT A TIBC AND TRASNSFERRIN DETERMINATION HAS VERY LIMITED VALUE EXCEPT IN CASES OF IRON POISONING. TRANSFERRIN SATURATION IS A BETTER INDEX OF IRON SATURATION; IT IS EVALUATED AS FOLLOWS :\r\nTRANSFERRIN SATURATION % = S. IRON * 100 / TIBC\r\n THE COMBINED RESULTS OF TRANSFERRIN, IRON & TIBC TESTS ARE HELPFUL IN THE DIFFERENTIAL DIAGNOSIS OF ANEMIA, IN THE ASSESSMENT OF IRON DEFIICIENCY ANEMIA & IN THE EVALUATION OF THALASSEMIA, SIDEROBLASTIC ANEMIA & HEMOCHROMATOSIS.', '1', 'mcg / ml', '50', '170', '0', '0', '0', 'Increased : hemochromatosis, hemosiderosis caused by excessive iron intake, excess destruction or decreased production of erythrocytes, liver necrosis, HEMOLYTIC ANEMIA, ESPECIALLY THALASSEMIA, PERNICIOUS ANEMIA IN RELAPSE; IRON OVERLOAD SYNDROME, MULTIPLE TRANSFUSIONS, INAPPROPRIATE IRON THERAPY, VIT B6 DEFICIENCY, LEAD POISONING, AC. LEUKEMIA, NEPHRITIS.\r\n\r\nDecreased : Iron deficiency anemia, nephrosis (loss of iron-binding proteins), normochromic anemia of chronic diseases and infections, ACUTE & CHRONIC BLOOD LOSS, LATE PREGNANCY.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('247', 'SERUM CORTISOL ( 4.00 P.M. )', '0', '0', 'CORTISOL ( HYDROCORTISONE ) IS A GLUCOCORTICOID OF ADRENAL CORTEX & AFFECTS METABOLISM OF PROTEINS, CARBOHYDRATES & LIPIDS. CORTISOL STIMULATES GLUCOGENESIS BY THE LIVER, INHIBITS THE EFFECT OF INSULIN & DECREASES THE RATE OF GLUCOSE USE BY THE CELLS. IN HEALTH, THE SECRETION RATE OF CORTISOL IS HIGHER IN THE EARLY MORNING & LOWER IN THE EVENING. THIS VARIATION IS LOST IN PATIENTS WITH CUSHING SYNDROME & IN PERSONS UNDER STRESS.\r\nTHIS TEST EVALUATES ADRENAL HORMONE FUNCTION. SUPPRESSION & STIMULATION TEST CAN ALSO BE DONE. CORTISOL SUPPRESSION TEST ( DEXAMETHASONE ) SCREENS FOR CUSHING SYNDROME & IDENTIFIES DEPRESSED PERSONS WHO ARE LIKELY TO RESPOND TO ANTIDEPRESSANTS OR SHOCK THERAPY. IT IS BASED ON THE FACT THAT ACTH PRODUCTION IS SUPPRESSED IN HEALTHY PERSONS AFTER A LOW DOSE OF DEXAMETHASONE BUT NOT IN PERSONS WITH CUSHING SYNDROME OR IN SOME DEPRESSED PERSONS.', '1', 'nmol / l', '83', '441', '0', '0', '0', 'Increased : Adrenal adenoma, adrenal carcinoma, Cushing\'s disease, nonpituitary ACTH-producing tumor, steroid therapy, oral contraceptives, HYPERTHYROIDISM, STRESS (TRAUMA, SURGERY), CARCINOMA ( EXTREEM ELEVATION IN THE MORNING & NO VARIATION IN THE EVENING), OBESITY.\r\n\r\nDecreased : Primary adrenal insufficiency (Addison\'s disease), congenital adrenal hyperplasia, Waterhouse-Friderichsen syndrome, ACTH deficiency, HYPOTHYROIDISM ( HYPOPITUITARISM).\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('248', 'BUN', '0', '0', 'UREA FORMS IN THE LIVER & ALONG WITH CO2, CONSTITUTES THE FINAL PRODUCT OF PROTEIN METABOLISM. \r\nTHE TEST FOR BUN, WHICH MEASURES THE NITROGEN PORTION OF UREA, IS USED AS AN INDEX OF GLOMERULAR FUNCTION IN THE PRODUCTION & EXCRETION OF UREA. RAPID PROTEIN CATABOLISM & IMPAIRMENT OF KIDNEY FUNCTION WILL RESULT IN INCREASE BUN LEVELS. IN CHRONIC RENAL DISEASE, THE BUN LEVEL CORRELATES BETTER WITH SYMPTOMS OF UREMIA THAN DOES THE SERUM CREATININE.\r\n', '1', 'mg / ml', '6', '20', '0', '0', '0', 'INCREASED : RENAL FAILURE (INCLUDING DRUG-INDUCED FROM AMINOGLYCOSIDES, NSAIDS), PRE-RENAL AZOTEMIA (DECREASED RENAL PERFUSION SECONDARY TO CHF, SHOCK, VOLUME DEPLETION), POSTRENAL (OBSTRUCTION), GI BLEEDING, STRESS, DRUGS (ESPECIALLY AMINOGLYCOSIDES), HIGH PROTEIN DIET.\r\n\r\nDECREASED : STARVATION, LIVER FAILURE (HEPATITIS, DRUGS), LATE PREGNANAY, INFANCY, NEPHROTIC SYNDROME, OVERHYDRATION, MALABSORPTION, ACROMEGALY & HIGH CARBOHYDRATE/LOW PROTEIN DIET.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('250', 'LH ( FEMALE - FOLLICULAR PHASE )', '0', '0', 'LH & FSH ARE GLYCOPROTEIN PITUITARY HORMONES PRODUCED & STORED IN THE ANTERIOR PITUITARY. LH ACTS ON LEYDIG CELLS OF GONADS.\r\nTHIS TEST MEASURES THE GONADOTROPHIC HORMONE LH AND MAY HELP DETERMINE WHETHER A GONADAL DEFICIENCY IS OF PRIMARY ORIGIN OR IS DUE TO INSUFFICIENT STIMULATION BY THE PITUITARY HORMONES. MEASURING THE LEVELS OF FSH & LH IS OF VALUE IN STUDING CHILDREN WITH ENDOCRINE PROBLEMS RELATED TO PRECOCIOUS PUBERTY. \r\nIN THE CASE OF ANOVULATORY FERTILITY PROBLEM, THE PRESENCE OR ABSENCE OF THE MIDCYCLE PEAK CAN BE ESTABLISHED THROUGH A SERIES OF DAILY BLOOD SAMPLES.', '1', 'iu / l', '1.37', '9.9', '0', '0', '0', 'Increased : (Hypergonadotropic >40 IU/L) postmenopausal, surgical or radiation castration, ovarian or testicular failure, polycystic ovaries, COMPLETE TESTICULAR FEMINIZATION SYNDROME.\r\n\r\nDecreased : (Hypogonadotropic < 40 IU/L prepubertal) hypothalamic and pituitary dysfunction, kallmann\'s syndrome, LHRH analogue therapy.\r\n\r\nCHILDREN - 0.00 TO 0.90 IU / L', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('254', 'FSH ( FEMALE - FOLLICULAR PHASE )', '0', '0', 'LH & FSH ARE GLYCOPROTEIN PITUITARY HORMONES PRODUCED & STORED IN THE ANTERIOR PITUITARY. FSH ACTS ON GRANULOSA CELLS OF THE OVARY & SERLOTI CELLS OF THE TESTIS. NORMALLY FSH INCREASES OCCUR AT EARLIER STAGES OF PUBERTY, 2-4 YRS BEFORE LH REACHES COMPARABLE LEVELS.\r\nTHIS TEST MEASURES THE GONADOTROPHIC HORMONE LH AND MAY HELP DETERMINE WHETHER A GONADAL DEFICIENCY IS OF PRIMARY ORIGIN OR IS DUE TO INSUFFICIENT STIMULATION BY THE PITUITARY HORMONES. MEASURING THE LEVELS OF FSH & LH IS OF VALUE IN STUDING CHILDREN WITH ENDOCRINE PROBLEMS RELATED TO PRECOCIOUS PUBERTY. \r\nIN THE CASE OF ANOVULATORY FERTILITY PROBLEM, THE PRESENCE OR ABSENCE OF THE MIDCYCLE PEAK CAN BE ESTABLISHED THROUGH A SERIES OF DAILY BLOOD SAMPLES.', '1', 'iu / l', '1.68', '15', '0', '0', '0', 'Increased : (hypergonadotropic > 40 IU/L) postmenopausal, surgical castration, gonadal failure, gonadotropin-secreting pituitary adenoma, TURNER SYNDROME( OVARIAN DYSGENESIS), HYPOPITUITARISM,SHEEHANS SYNDROME, PRECOCIOUS PUBERTY, KLINEFELTER SYNDROME, ALCOHOLISM, MWNOPAUSAL & MENSTRUAL DISORDERS, HYPOGONADISM, COMPLETE TESTICULAR FEMINIZATION SYNDROME( END ORGAN RESISTANCE TO ANDROGENS DUE TO ANDROGEN RECEPTOR DEFECTS), CONGENITAL ABSENCE OF TESTICLES, 46XY/XO, 47XYY KARYOTYPES, MUTATION IN FSH RECEPTOR GENE IN MEN, CRYPTORCHIDISM, DISORDERS OF ANDROGEN BIOSYNTHESIS, SERTOLI- CELL-ONLY SYNDROME, MYOTONIC DYSTROPHY, INFECTIONS LIKE MUMPS, RADIATION, ANTINEOPLASTIC AGENTS, CHEMICALS LIKE DIBROMODICHLOROPROPANE, GLUCOCORTICOIDS, KETOCONAZOLE, SURAMIN, TRAUMA, TORTION TESTIS, CHR SYSTEMIC DISEASES LIKE CIRRHOSIS, CHR RENAL FAILURE, AIDS, AUTOIMMUNE DAMAGE DUE TO ANTISPERM ANTIBODIES, IDIOPATHIC, GONADOTROPH ADENOMAS\r\n\r\nDecreased : (Hypogonadotropic < 5 IU/L) prepubertal, hypothalamic and pituitary dysfunction, pregnancy, FEMINIZING & MASCULANIZING OVARIAN TUMORS WHEN FSH PRODUCTION IS INHIBITED BECAUSE OF INCREASED OESTROGEN SECRETION, KALLMANN SYNDROME, PITUITARY LH OR FSH DEFICIENCY, NEOPLASM OF TESTES OR ADRENAL GLANDS THAT INFLUENCE SECRETION OF OESTROGENS OR ANDROGENS, POLYCYSTIC OVARIAN DISEASE, HEMOCHROMATOSIS, ANOREXIA, ISOLATED IDIOPATHIC HYPOGONADOTROPIC HYPOGONADISM.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('261', 'GLUCOSE TOLERANCE TEST ( III - 60 MTS )', '0', '0', 'IN HEALTHY INDIVIDUALS THE INSULIN RESPONSE TO A LARGE ORAL GLUCOSE DOSE IS ALMOST IMMIDIATE. IT PEAKS IN 30 MTS TO 60 MTS & RETURNS TO NORMAL LIMITS WITHIN 3 HRS WHEN SUFFICIENT INSULIN IS PRESENT OT METABOLISE THE GLUCOSE INGESTED. THE TEST SHOULD BE PERFORMED ACCORDING TO THE WHO GUIDELINES USING GLUCOSE LOAD CONTAINING THE EQUIVALENT OF 75 - 100 GMS OF ANHYDROUS GLUCOSE DISSOLVED IN WATER OR OTHER SOLUTION.', '1', 'mg %', '70', '184', '0', '0', '0', 'Increased : Diabetes mellitus, Cushing\'s acromegaly, increased epinephrine (injection, pheochromocytoma, stress, burns, etc), acute pancreatitis, ACTH administration, spurious increase caused by drawing blood from a site above an IV line containing dextrose, elderly patients, pancreatic glucagonoma, drugs (glucocorticoids, some diuretics).\r\n\r\nDecreased : Pancreatic disorders (pancreatitis, islet cell tumors), extrapancreatic tumors (carcinoma of the adrenals, stomach), hepatic disease (hepatitis, cirrhosis, tumors), endocrine disorders (early diabetes, hypothyroidism, hypopituitarism), functional disorders (after gastrectomy), pediatric problems (prematurity, infant of a diabetic mother, ketotic hypoglycemia, enzyme diseases), exogenous insulin, oral hypoglycemic agents, malnutrition, sepsis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('262', 'GLUCOSE TOLERANCE TEST ( IV - 90 MTS )', '0', '0', 'IN HEALTHY INDIVIDUALS THE INSULIN RESPONSE TO A LARGE ORAL GLUCOSE DOSE IS ALMOST IMMIDIATE. IT PEAKS IN 30 MTS TO 60 MTS & RETURNS TO NORMAL LIMITS WITHIN 3 HRS WHEN SUFFICIENT INSULIN IS PRESENT OT METABOLISE THE GLUCOSE INGESTED. THE TEST SHOULD BE PERFORMED ACCORDING TO THE WHO GUIDELINES USING GLUCOSE LOAD CONTAINING THE EQUIVALENT OF 75 - 100 GMS OF ANHYDROUS GLUCOSE DISSOLVED IN WATER OR OTHER SOLUTION.', '1', 'mg %', '70', '200', '0', '0', '0', 'Increased : Diabetes mellitus, Cushing\'s acromegaly, increased epinephrine (injection, pheochromocytoma, stress, burns, etc), acute pancreatitis, ACTH administration, spurious increase caused by drawing blood from a site above an IV line containing dextrose, elderly patients, pancreatic glucagonoma, drugs (glucocorticoids, some diuretics).\r\n\r\nDecreased : Pancreatic disorders (pancreatitis, islet cell tumors), extrapancreatic tumors (carcinoma of the adrenals, stomach), hepatic disease (hepatitis, cirrhosis, tumors), endocrine disorders (early diabetes, hypothyroidism, hypopituitarism), functional disorders (after gastrectomy), pediatric problems (prematurity, infant of a diabetic mother, ketotic hypoglycemia, enzyme diseases), exogenous insulin, oral hypoglycemic agents, malnutrition, sepsis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('263', 'GLUCOSE TOLERANCE TEST ( V - 120 MTS )', '0', '0', 'IN HEALTHY INDIVIDUALS THE INSULIN RESPONSE TO A LARGE ORAL GLUCOSE DOSE IS ALMOST IMMIDIATE. IT PEAKS IN 30 MTS TO 60 MTS & RETURNS TO NORMAL LIMITS WITHIN 3 HRS WHEN SUFFICIENT INSULIN IS PRESENT OT METABOLISE THE GLUCOSE INGESTED. THE TEST SHOULD BE PERFORMED ACCORDING TO THE WHO GUIDELINES USING GLUCOSE LOAD CONTAINING THE EQUIVALENT OF 75 - 100 GMS OF ANHYDROUS GLUCOSE DISSOLVED IN WATER OR OTHER SOLUTION.', '1', 'mg %', '70', '138', '0', '0', '0', 'Increased : Diabetes mellitus, Cushing\'s acromegaly, increased epinephrine (injection, pheochromocytoma, stress, burns, etc), acute pancreatitis, ACTH administration, spurious increase caused by drawing blood from a site above an IV line containing dextrose, elderly patients, pancreatic glucagonoma, drugs (glucocorticoids, some diuretics).\r\n\r\nDecreased : Pancreatic disorders (pancreatitis, islet cell tumors), extrapancreatic tumors (carcinoma of the adrenals, stomach), hepatic disease (hepatitis, cirrhosis, tumors), endocrine disorders (early diabetes, hypothyroidism, hypopituitarism), functional disorders (after gastrectomy), pediatric problems (prematurity, infant of a diabetic mother, ketotic hypoglycemia, enzyme diseases), exogenous insulin, oral hypoglycemic agents, malnutrition, sepsis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('264', 'GLUCOSE TOLERANCE TEST ( I - FASTING )', '0', '0', 'IN HEALTHY INDIVIDUALS THE INSULIN RESPONSE TO A LARGE ORAL GLUCOSE DOSE IS ALMOST IMMIDIATE. IT PEAKS IN 30 MTS TO 60 MTS & RETURNS TO NORMAL LIMITS WITHIN 3 HRS WHEN SUFFICIENT INSULIN IS PRESENT OT METABOLISE THE GLUCOSE INGESTED. THE TEST SHOULD BE PERFORMED ACCORDING TO THE WHO GUIDELINES USING GLUCOSE LOAD CONTAINING THE EQUIVALENT OF 75 - 100 GMS OF ANHYDROUS GLUCOSE DISSOLVED IN WATER OR OTHER SOLUTION.', '1', 'mg %', '70', '110', '0', '0', '0', 'Increased : Diabetes mellitus, Cushing\'s acromegaly, increased epinephrine (injection, pheochromocytoma, stress, burns, etc), acute pancreatitis, ACTH administration, spurious increase caused by drawing blood from a site above an IV line containing dextrose, elderly patients, pancreatic glucagonoma, drugs (glucocorticoids, some diuretics).\r\n\r\nDecreased : Pancreatic disorders (pancreatitis, islet cell tumors), extrapancreatic tumors (carcinoma of the adrenals, stomach), hepatic disease (hepatitis, cirrhosis, tumors), endocrine disorders (early diabetes, hypothyroidism, hypopituitarism), functional disorders (after gastrectomy), pediatric problems (prematurity, infant of a diabetic mother, ketotic hypoglycemia, enzyme diseases), exogenous insulin, oral hypoglycemic agents, malnutrition, sepsis.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('265', 'G6PD ( QUANTITATIVE - CHILDREN )', '0', '0', 'G6PD IS A SEX LINKED DISORDER. THE MAJOR VARIANTS OCCUR IN SPECIFIC ETHNIC GROUPS. WITH SOME VARIANTS THERE IS CHRONIC LIFELONG HAEMOLYSIS, BUT MORE COMMONLY THE CONDITION IS ASYMPTOMATIC & RESULTS ONLY IN SUSCEPTIBILITY TO ACUTE HAEMOLYTIC EPISODES, WHICH MAY TRIGGERED BY CERTAIN DRUGS, INGESTION OF FAVA BEANS, OR VIRAL OR BACTERIAL INFECTIONS. G6PD HAEMOLYSIS IS ASSOCIATED WITH FORMATION OF HEINZ BODIES IN PERIPHERAL RBCS.', '1', 'u / gm hb', '6.4', '15.6', '0', '0', '0', 'INCREASED : UNTREATED MEGALOBLASTIC ANEMIA, THROMBOCYTOPENIC PURPURA, HYPERTHYROIDISM, VIRAL HEPATITIS.\r\n\r\nDECREASED : G6PD DEFICIENCY ( CAUSES HAEMOLYTIC EPISODES AFTER EXPOSURE TO CERTAIN DRUGS & FAVA BEANS ), CONGENITAL NONSPHEROCYTIC ANEMIA, NONIMMUNOLOGIC HAEMOLYTIC DISEASE OF THE NEWBORN ( ASIAN & MEDITERRANEAN ).', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('267', 'CT SCAN HEAD', '1', '0', 'C.T. OR COMPUTERIZED TOMOGRAPHY IS UNIQUE BECAUSE IT CAN PRODUCE CROSS SECTIONAL IMAGES OF ANATOMIC STRUCTURES WITHOUT SUPERIMPOSING TISSUES ON EACH OTHER. ADDITIONALLY, CT CAN DISCERN THE DIFFERENT CHARACTERISTICS OF TISSUE STRUCTURES WITHIN SOLID ORGANS. AGENTS MAY BE USED FOR DELINEATION OF BLOOD VESSELS, THE OPACIFICATION OF CERTAIN TISSUE ( KIDNEYS ), DEMONSTRATION OF BOWEL, & BLOOD FLOW PATTERNS. THIS MEANS A CT SCAN CAN DEMONSTRATE MINOR DIFFERENCES IN DENSITY & COMPOSITION IN SHADES OF GREY. A CT SCAN CAN DIFFERENTIATE TUMORS FROM SOFT TISSUES, AIR SPACES FROM CSF & NORMAL BLOOD FROM CLOTTED BLOOD.\r\nC.T. CAN BE PERFORMED ON ANY PART OF THE BODY LIKE : ABDOMEN, PELVIS, SPINE, HEAD, SINUSES, ORBITS, MASTOIDS, INTERNAL AUDITORY CANAL, FACIAL BONES, NECK, CHEST INCLUDING LUNGS, MEDIASTINUM & HEART, JOINTS & SPECIFIC BONES & CT GUIDED BIOPSY.CT CAN BE USED TO DETECT INTERVERTIBRAL DISC DISEASE, HERNIATION & SOFT TISSUE DAMAGE TO LIGAMENTS WITHIN JOINT SPACES.\r\nIN C.T. LIGHTER THE SHADING, THE HIGHER THE DENSITY OF THE TISSUE OR STRUCTURE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('269', 'COMPLETE BLOOD COUNT', '0', '1', 'IT INCLUDES HB, TLC, DLC, ESR, RBC COUNT, PLATELETS COUNT, PCV, MCV, MCH, MCHC AND PERIPHERAL BLOOD SMEAR TEST. TO SEE DETAILS OF INDIVIDUAL TESTS GO TO THE RECORDS OF INDIVIDUAL TESTS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('272', 'ANTI-DOUBLE STRANDED DNA ANTIBODY', '0', '0', 'IT IS ONE OF SUB UNIT OF ANTINUCLEAR ANTIBODIES PRESENT IN THE BODY DURING THE COURSE OF VARIOS DISEASES.', '2', '', '0', '0', '2', '0', '0', 'HIGHLY SPECIFIC FOR SLE ( 60 % ).\r\nASSOCIATED WITH LUPUS NEPHRITIS, LUPUS CNS INVOLVEMENT.\r\nPRESENT IN SJOGRENS SYNDROME ( 5% ), RHEUMATOID ARTHRITIS ( < 5% ) , CHR. ACTIVE HEPATITIS, BILIARY CIRRHOSIS, EPSTEIN BARR VIRUS, CYTOMEGALOVIRUS.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('277', 'ANTI-SMITH ANTIBODY', '0', '0', 'IT IS ONE OF SUB UNIT OF ANTINUCLEAR ANTIBODIES PRESENT IN THE BODY DURING THE COURSE OF VARIOS DISEASES.', '2', '', '0', '0', '2', '0', '0', 'HIGHLY SPECIFIC FOR SLE ( 30 % ).\r\nASSOCIATED WITH LUPUS NEPHRITIS, DRUG INDUCED LUPUS ( < 5% ).\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('278', 'ANTI-RO ANTIBODY', '0', '0', 'IT IS ONE OF SUB UNIT OF ANTINUCLEAR ANTIBODIES PRESENT IN THE BODY DURING THE COURSE OF VARIOS DISEASES.', '2', '', '0', '0', '2', '0', '0', 'POSITIVE IN : SLE (40%) ASSOCIATED WITH PHOTOSENSITIVE SKIN RASH, PULMONARY DISEASE & LYMPHOPENIA.\r\nPOSITIVE IN SJOGRENS SYNDROME ( 75% ), KERATOCONJUNCTIVIS SICCA SYNDROME, RHEUMATOID ARTHRITIS ( 10% ), SYSTEMIC SCLEROSIS ( 5% ), DRUG INDUCED LUPUS ( < 5% ) , MIXED CONNECTIVE TISSUE DISORDERS ( < 5% ).', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('279', 'ANTI-LA ANTIBODY', '0', '0', 'IT IS ONE OF SUB UNIT OF ANTINUCLEAR ANTIBODIES PRESENT IN THE BODY DURING THE COURSE OF VARIOS DISEASES.', '2', '', '0', '0', '2', '0', '0', 'POSITIVE IN : * SJOGRENS SYNDROME ( 40% ) ASSOCIATED WITH SJOGREN OF SECONDARY CAUSE. * SLE ( 15% ) ASSOCIATED WITH LATE ONSET SYSTEMIC LUPUS & NEONATAL LUPUS SYNDROME\r\n* RHEUMATOID ARTHRITIS ( 5% )\r\n* KERATOCONJUNCTIVITIS SICCA SYNDROME\r\n* SYSTEMIC SCLEROSIS ( 1% )\r\n* MIXED CONNECTIVE TISSUE DISORDERS ( < 5% ).', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('284', 'ANTI-NEUTROPHIL CYTOPLASMIC ANTIBODIES', '0', '0', 'IT IS ONE OF SUB UNIT OF ANTINUCLEAR ANTIBODIES PRESENT IN THE BODY DURING THE COURSE OF VARIOS DISEASES.', '2', '', '0', '0', '2', '0', '0', 'THESE ANA ANTIBODIES TEST IS INDICATED IN SMALL VESSEL VASCULITIS & WEGENERS GRANULOMATOSIS. THE ANTIBODIES BIND TO CYTOPLASMIC REGION OF NEUTROPHILS.\r\n* WEGENERS GRANULOMATOSIS - 75 - 98% POSITIVE, SENSTIVITY DROPS TO 30% DURING REMISSION.\r\n* CRESENTRIC GLOMERULONEPHRITIS - MODERATELY ASSOCIATED\r\n* CHURG-STRAUSS VASCULITIS - MODERATELY ASSO.\r\n* WEGENERS GRANULOMATOSIS - WEAKLY ASSO.\r\n* HENOCH-SCHONLEIN PURPURA - POSSIBLY ASSO.\r\n* TEMPORAL ARTERITIS - POSSIBLY ASSO.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('286', 'TROPONIN - T', '0', '0', 'CARDIAC TROPONIN IS UNIQUE TO HEART MUSCLE & IS HIGHLY CONCENTRATED IN CARDIOMYOCYTES. THIS PROTEIN IS RELEASED WITH VERY SMALL AREA OF MYOCARDIAL DAMAGE AS EARLY AS 1-3 HRS AFTER INJURY & LEVELS RETURN TO NORMAL WITHIN 5-7 DAYS. TROPONIN - I REMAINS INCREASED LONGER THAN CPK-MB & IS MORE SPECIFIC.THIS TEST IS POSITIVE IN MYOCARDIAL INFARCTION CASES BUT SPECIFICITY IS LOW AS 22% MAY HAVE UNSTABLE ANGINA OR CHR. RENAL FAILURE.', '1', 'ng / ml', '0', '0.2', '0', '0', '0', 'HIGHLY SENSITIVE FOR DETECTING MYOCARDIAL INFARCTION - 94% SENSITIVE , LEVELS REMAIN ELEVATED FOR DAYS.\r\nDISADVANTAGES : UNABLE TO TIME ACUTE CORONARY EVENT. LESS SPECIFIC THAN TROPONIN - I TEST.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('287', 'TROPONIN - I', '0', '0', 'CARDIAC TROPONIN IS UNIQUE TO HEART MUSCLE & IS HIGHLY CONCENTRATED IN CARDIOMYOCYTES. THIS PROTEIN IS RELEASED WITH VERY SMALL AREA OF MYOCARDIAL DAMAGE AS EARLY AS 1-3 HRS AFTER INJURY & LEVELS RETURN TO NORMAL WITHIN 5-7 DAYS. TROPONIN - I REMAINS INCREASED LONGER THAN CPK-MB & IS MORE SPECIFIC. IT IS LESS SPECIFIC ( 36% HAVE UNSTABLE ANGINA ) BUT MORE SENSITIVE ( 100% ) THAN TROPONIN - T TEST.', '1', 'ng / ml', '0', '0.35', '0', '0', '0', 'VALUE > 1.0 TO 1.2 ARE SUGGESTIVE OF MYOCARDIAL INFARCTION.\r\nTWO NEGATIVE VALUES 6 HRS APART PREDICT LOW LIKELIHOOD OF INFARCTION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('288', 'LDH', '0', '0', 'LACTATE DEHYDROGENASE IS AN INTRACELLULAR ENZYME WHICH IS WIDELY DISTRIBUTED IN THE TISSUES OF BODY, PARTICULARLY IN HEART, KIDNEY, SKELETAL MUSCLE, BRAIN, LIVER & LUNG. INCREAES IN THE VALUE USUALLY INDICATE CELLULAR DEATH & LEAKAGE OF ENZYME FROM THE CELL.\r\nALTHOUGH ELEVATED LEVELS ARE NONSPECIFIC , THIS TEST IS USEFUL IN CONFIRMING MYOCARDIAL OR PULMONARY INFARCT WHEN VIEWED IN RELATION TO OTHER TEST FINDINGS.\r\n IT RISES WITHIN 6-8 HRS , PEAKS IN 24 - 36 HRS & LASTS FOR UPTO 14 DAYS.', '1', 'u / l', '140', '280', '0', '0', '0', 'INCREASED : M.I. ( HIGH LEVELS OCCUR WITHIN 36 - 55 HRS AFTER M.I. & CONTINUE LONGER THAN ELEVATION OF SGOT OR CPK - MB ( 3 - 10 DAYS ).\r\nPUL. INFARCT : INCREASES WITHIN 24 HRS. THE PATTERN OF NORMAL SGOT & ELEVATED LDH THAT LEVELS OFF 1-2 DAYS AFTER AN EPISODE OF CHEST PAIN IS INDICATIVE OF PUL. INFARCTTION.\r\nOTHER CONDITIONS : CHF, LIVER DISEASE, MALIGNANT NEOPLASMS, CANCER, LEUKEMIA, LYMPHOMA, HYPOTHYROIDISM, LUNG DISEASES, SKELETAL MUSCLE DISEASES ( MUSCULAR DYSTROPHY, MUSCLE INJURY ), MEGALOBLASTIC & PERNICIOUS ANEMIA, HEMOLYTIC ANEMIA, SICKLE CELL ANEMIA, DELIRIUM TREMENS, SEIZURES, SHOCK, HYPOTENSION, HYPOXIA, HYPERTHERMIA, RENAL INFARCT, CNS DISEASES, AC. PANCREATITIS, FRACTURES & OTHER TRAUMA INCLUDING HEAD, INTESTINAL OBSTRUCTION, CARDIAC SURGERY, PROSTHETIC VALVE, HEPATITIS.\r\n\r\nDECREASE : DECREASE IN LEVELS ARE ASSOCIATED WITH A GOOD RESPONSE TO CANCER THERAPY.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('291', 'ECHOCARDIOGRAPHY', '1', '0', 'THIS NONINVASIVE TECHNIQUE FOR EXAMINING THE HEART CAN PROVIDE INFORMATION ABOUT ITS POSITION & SIZE, MOVEMENTS OF THE VALVES & CHAMBERS & VELOCITY OF BLOOD FLOW.', '4', '', '0', '0', '0', '0', '0', 'DONE IN CASES OF : \r\nVALVULAR HEART DISEASE, CARDIOMYOPATHIES, EVIDENCE OF CORONARY ARTRY DISEASE, PERICARDIAL DISEASE, ENDOCARDITIS, CARDIAC NEOPLASM, INTRACARDIAC THROMBI, PROSTHETIC VALVE FUNCTION & CONGENITAL HEART DISEASE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('295', 'ECG', '0', '0', 'AN ECG RECORDS THE ELECTRICAL IMPULSES THAT STIMULATE THE HEART TO CONTRACT. IT ALSO RECORDS DYSFUNCTIONS THAT INFLUENCE THE CONDUCTION ABILITY OF THE MYOCARDIUM.\r\nIT IS HELPFUL IN DIAGNOSING & MONITORING THE ORIGINS OF PATHOLOGIC RHYTHMS, MYOCRDIAL ISCHAEMIA, MYOCARDIAL INFARCTION, HYPERTRPHY, CONDUCTION ABNORMALITIES & PERICARDITIS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('296', 'HOLTER MONITORING', '1', '0', 'IT IS CONTINUOUS ECG RECORDING OF CARDIAC RHYTHM, UNUSUAL CARDIAC EVENTS & PATIENTS ACTIVITY. THESE TRACINGS ARE USED TO RECORD ONSET & TERMINATION OF RHYTHM DISTURBANCES & TO DIAGNOSE THE CAUSE OF DIZZINESS, PALPITATION, FAINTING ( SYNCOPE ) , UNEXPLAINED FATIGUE', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('299', 'URINE VMA', '0', '0', 'THE PRINCIPAL SUBSTANCES FORMED BY THE ADRENAL MEDULLA AND EXCRETED IN THE URINE ARE VMA, EPINEPHRINE, NOREPINEPHRINE, METANEPHRINE & NORMETANEPHRINE. THESE SUBSTANCES CONTAIN A CATECHOL NUCLEUS TOGATHER WITH AN AMINE GROUP & THEREFORE ARE REFERRED AS CATECHOLAMINES. MOST OF THESE HORMONES ARE CHANGED INTO METABOLITES, THE PRINCIPAL ONE BEING 3- METHOXY 4- HYDROXYMANDELIC ACID, KNOWN AS VANILLYLMANDELIC ACID OR VMA.\r\nVMA IS THE PRIMARY URINARY METABOLITE OF THE CATCHOLAMINE GROUP. IT HAS A URINE CONCENTRATION 10 TO 100 TIMES GREATER THAN THE CONCENTRATION OF OTHER AMINES. \r\nVMA TEST IS DONE TO DIAGNOSE PHEOCHROMOCYTOMA AND THE TEST IS MOST VALUABLE WHEN URINE SPECIMEN IS COLLECTED DURING A HYPERTENSIVE EPISODE. A 24 HRS URINE SAMPLE IS COLLECTED.\r\n', '1', 'mg / 24 hrs', '0', '9', '0', '0', '0', 'INCREASED : PHEOCHROMOCYTOMA, NEUROBLASTOMA, GANGLIONEUROMA, GANGLIOBLASTOMA & CARCINOID TUMORS.\r\n\r\nINCREASED CATECHOLAMINES : PHEOCHROMOCYTOMA, NEUROBLASTOMA, GANGLIOBLASTOMA, MYOCARDIAL INFARCTION ( ACUTE ), HYPOTHYROIDISM, DIABETIC ACIDOSIS, LONG TERM NAMIC-DEPRESSIVE PSYCHOSIS.\r\n\r\nDECREASED : DIABETIC NEUROPATHY, PARKINSON\'S DISEASE.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('300', 'URINE CATECHOLAMINES TOTAL', '0', '0', 'THE PRINCIPAL SUBSTANCES FORMED BY THE ADRENAL MEDULLA AND EXCRETED IN THE URINE ARE VMA, EPINEPHRINE, NOREPINEPHRINE, METANEPHRINE & NORMETANEPHRINE. THESE SUBSTANCES CONTAIN A CATECHOL NUCLEUS TOGATHER WITH AN AMINE GROUP & THEREFORE ARE REFERRED AS CATECHOLAMINES. MOST OF THESE HORMONES ARE CHANGED INTO METABOLITES, THE PRINCIPAL ONE BEING 3- METHOXY 4- HYDROXYMANDELIC ACID, KNOWN AS VANILLYLMANDELIC ACID OR VMA.\r\nVMA IS THE PRIMARY URINARY METABOLITE OF THE CATCHOLAMINE GROUP. IT HAS A URINE CONCENTRATION 10 TO 100 TIMES GREATER THAN THE CONCENTRATION OF OTHER AMINES\r\n', '1', 'micro gm / day', '100', '150', '0', '0', '0', 'INCREASED : PHEOCHROMOCYTOMA, NEUROBLASTOMA, GANGLIONEUROMA, GANGLIOBLASTOMA & CARCINOID TUMORS.\r\n\r\nINCREASED CATECHOLAMINES : PHEOCHROMOCYTOMA, NEUROBLASTOMA, GANGLIOBLASTOMA, MYOCARDIAL INFARCTION ( ACUTE ), HYPOTHYROIDISM, DIABETIC ACIDOSIS, LONG TERM NAMIC-DEPRESSIVE PSYCHOSIS.\r\n\r\nDECREASED : DIABETIC NEUROPATHY, PARKINSON\'S DISEASE.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('301', 'CSF EXAMINATION', '1', '0', 'CSF IS A CLEAR, COLORLESS FLUID FORMED WITHIN THE CAVITIES IE. VENTRICLES OF THE BRAIN. THE CHOROID PLEXUS PRODUCES ABOUT 70% OF THE CSF BY ULTRAFILTRATION & SECRETION. THE EPENDYMAL LINING OF THE VENTRICLE & CEREBRAL SUBARACHNOID SPACE PRODUCE THE REMAINING PART OF THE CSF. APPROXIMATELY 500 ML OF THE CSF IS FORMED DAILY, ALTHOUGH ONLY 90 - 150 ML IS PRESENT IN THE SYSTEM AT ANY TIME. REABSORPTION OF CSF TAKES PLACE BY ARACHNOID VILLI. MOST CSF CONSTITUENTS ARE PRESENT IN THE SAME OF LOWER CONCENTRATION AS IN THE BLOOD PLASMA, EXCEPT FOR CHLORIDE CONC. WHICH ARE USUALLY HIGHER.\r\nCSF EXAMINATION IS DONE IN FOLLOWING CONDITIONS : BRAIN INFECTION, MENINGITIS, BRAIN TUMORS, SUBARACHNOID HAEMORRHAGE, AUTOIMMUNE DISEASES LIKE MULTIPLE SCLEROSIS.\r\n', '4', '', '0', '0', '0', '0', '0', 'CSF CELL COUNT - ADULT  0-5 / CU MM\r\nNEWBORN - 0-30\r\nCHILDREN - 0-15 / CU MM\r\nPROTEIN - 15 - 40 MG / ML\r\nGLUCOSE - 40- 80\r\nCHLORIDE - \r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('303', 'CORTISOL SUPPRESSION TEST ( DEXAMETHASONE SUPPRESS', '0', '0', 'THIS TEST HELPS TO DIFFERENTIATE CAUSES OF ELEVATED CORTISOL LEVELS. CORTISOL < 15 MCG / ML IS INDICATION OF ADRENAL CORTISOL INSUFFICIENCY.', '1', 'micro gm / ml', '0', '5', '0', '0', '0', 'SUPPRESSION OCCURS IN : CUSHING SYNDROME( > 10 MCG / ML ) & ENDOGENOUS DEPRESSION ( 50% CASES ).\r\nNO SUPPRESSION IN : ADRENAL ADENOMA, CARCINOMA, ACTOPIC ACTH- PRODUCING TUMORS.\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('305', 'PARATHYROID HORMONE ASSAY', '0', '0', 'PARATHORMONE ( PTH ), A POLYPEPTIDE HORMONE PRODUCED IN THE PARATHYROID GLAND, IS ONE OF THE MAJOR FACTORS IN THE REGULATION OF CALCIUM METABOLISM & CONCENTRATION IN THE EXTRACELLULAR FLUID. THREE MOLECULAR FORMS OF PTH EXIST : INTACT ( ALSO CALLED NATIVE OR GLANDULAR HORMONE) ; MULTIPLE N-TERMINAL FRAGMENTS ; & C- TERMINAL FRAGMENTS.\r\nTHIS TEST STUDIES ALTERED CALCIUM METABOLISM, ESTABLISHES A DIAGNOSIS OF HYPERPARATHYROIDISM, & DISTINGUISHES NONPARATHYROID FROM PARATHYROID CAUSES OF HYPERCALCEMIA.\r\nPTH & N-TERMINAL LEVELS AARE USUALLY DECREASED WHEN HYPERCALCEMIA IS DUE TO NEOPLASTIC SECRETIONS ( PROSTAGLANDINS ). CREATININE LEVEL IS DETERMINED CONCURRENTLY WITH ALL PTH ASSAYS TO DETERMINE KIDNEY FUNCTION & FOR MEANINGFUL INTERPRETATION OF RESULTS.\r\n', '1', 'pg / ml', '8', '65', '0', '0', '0', 'OLD AGE -   40 - 50 PG / ML\r\n\r\nINCREASED PTH LEVELS :  PRIMARY HYPERPARATHYROIDISM, PSEUDOHYPERPARATHYROIDISM WHEN THERE IS A PRIMARY DEFECT IN RENAL TUBULAR RESPONSIVENESS TO PTH ( SEC. HYPERPARATHYROIDISM ), HEREDITARY VIT D DEPENDENCY, ZOLLINGER- ELLISON SYNDROME, SPINAL CORD INJURY, PREGNANCY.\r\n\r\nDECREASED : HYPOPARATHYROIDISM, NONPARATHYROID HYPERCALCEMIA, SEC. HYPOPARATHYROIDISM, MAGNESIUM DEFICIENCY, SARCOIDOSIS, HYPERTHYROIDISM, DIGEORGE\'S SYNDROME.\r\n\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('309', 'BONE DENSITOMETRY', '0', '0', 'BONE DENSITOMETRY ENABLES THE CLINICIAN TO OBTAIN A DIANOSIS OF OSTEOPOROSIS OR OSTEOPENIA, OFTEN BEFORE FRACTURES OCCUR, BY MEASURING BONE MINERAL DENSITY.', '1', 'sd', '0', '1', '0', '0', '0', 'NORMAL - T SCORE : < 1.0 SD BELOW NORMAL ( > -1.0 )\r\nOSTEOPENIA : 1.0 - 2.5 SD BELOW NORMAL ( -1.0 TO - 2.5 )\r\nOSTEOPOROSIS : > 2.5 SD BELOW NORMAL ( < - 2.5 )', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('311', 'PET ( POSITRON EMMISION TOMOGRAPHY ) IMAGING TUMOR', '1', '0', 'PET IMAGING INVOLVESTHE COMBINED USE OF POSITRON-EMITTING RADIONUCLIDES AND EMISSION CT. PET TECHNOLOGY GENERATES HIGH RESOLUTION IMAGES OF BODY FUNCTION & METABOLISM. PET USES RADIOPHARMACEUTICALS THAT ARE BASIC ELEMENTS OF BIOLOGIC SUBSTANCES LIKE CARBON-11, NITROGEN-13, OXYGEN-15 & FLUORINE-18. THESE RADIONUCLIDES USED IN PET IMAGING HAVE VERY SHORT HALF LIFE ( 2 MTS TO 2 HRS. ). IN THIS WAY NORMAL & ABNORMAL BIOLOGIC FUNCTION OF CELLS AND ORGAN CAN BE DETERMINED. IT PRODUCES IMAGES OF MOLECULAR LEVEL PHYSIOLOGIC FUNCTION, INCLUDING GLUCOSE METABOLISM, OXYGEN UTILIZATION, BLOOD FLOW & TISSUE PERFUSION. THE RADIOPHARMACEUTICAL DOSE IS INJECTED WHICH EMITS RADIOACTIVITY IN THE FORM OF POSITRON, WHICH ARE DETECTED & TRANSFORMED INTO A VISUAL DISPLAY BY COMPUTER.\r\nPET IMAGING IS USED FOR SEVERAL PURPOSES. NEOPLASTIC CELLS, INFECTION & VIABLE MYOCARDIUM\r\n ARE HYPERMETABOLIC & APPEAR TO HAVE AFFINITY THAT RESULTS IN HIGH CONTRAST OF THE RADIONUCLIDES IN THE AREA.\r\nPET IMAGING IS USEFUL IN ONCOLOGY, NEUROLOGY & CARDIOLOGY. HOWEVER THE TECHNIQUE IS APPLICABLE TO ALL PARTS OF THE BODY FOR DIAGNOSIS, DISEASE STAGING & MONITORING THERAPY. UNLIKE MRI OR CT , PET PROVIDES PHYSIOLOGIC, ANATOMIC & BIOCHEMICAL DATA.\r\nIN ONCOLOGY, PET HAS PROVED USEFUL IN SEVERAL AREAS, INCLUDING THE DIAGNOSIS OF PULMONARY NODULES, THE DIFERENTIATION OF PANCREATIC CANCER FROM MASS FORMING PANCREATITIS, & THE DIAGNOSIS OF BREAST CANCER IN SELECTED CASES OF MAMMOGRAPHY & BIOPSY FAILURE. PET IMAGING IS USED FOR THE INITIAL PREOPERATIVE STAGING OF CANCER INVOLVING THE LUNGS, LIVER, COLON, BREAST. HEAD & NECK AS WELL AS IN MELANOMA & LYMPHOMAS. STAGING, DETECTION OF RECURRENCE & RESPONSE TO THERAPY ALSO CAN BE DETERMINED.\r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('318', 'BREAST CANCER GENE MARKER', '0', '0', 'BRCA-1, BRCA-2 & ATAXIA TELANGIECTASIA GENE ON CHROMOSOME 11 CONFER 5 FOLD INCREASED RISK OF BREAST CANCER IN THE INDIVIDUAL.\r\nINDICATED IN WOMEN DIAGNOSED WITH EARLY ONSET BREAST CANCER, OVARIAN CANCER, WITH FAMILY PADIGREE SUGGESTING INCREASED RISK OF BREAST CANCER & OVARIAN CANCERS OR WITH FAMILY HISTORY OF KNOWN BRCA-1 OR BRCA-2 CARRIERS.', '2', '', '0', '0', '2', '0', '0', 'BREAST CANCER - 85 - 90 % LIFE TIME RISK\r\nOVARIAN CANCER - 40 - 60 % IN BRCA-1 \r\n - 15 - 20 % IN BRCA-2 LIFE TIME RISK', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('320', 'SERUM FOLATE', '0', '0', '.', '1', 'n gm / ml', '2', '10', '0', '0', '0', 'DECREASED : POOR FOLATE INTAKE OR FOLATE MALABSORPTION, VIT B12 DEFICIENCY, ALCOHOLISM, MEDICINES LIKE METHOTREXATE, TRIMETHOPRIM, PHENYTOIN, ORAL CONTRACEPTIVES, AZULFIDINE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('324', 'SERUM PHOSPHORUS', '0', '0', '.', '1', 'mg / ml', '2.5', '5', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('326', 'TREADMILL STRESS TEST ( TMT )', '0', '0', 'Exercise cardiac stress testing (ECST) is the most widely used cardiac stress test. The patient exercises on a treadmill according to a standardized protocol, with progressive increases in the speed and elevation of the treadmill (typically changing at three minute intervals). During the ECST, the patient\'s electrocardiogram (EKG), heart rate, heart rhythm, and blood pressure are continuously monitored. If a coronary arterial blockage results in decreased blood flow to a part of the heart during exercise, certain changes may be observed in the EKG, as well as in the response of the heart rate and blood pressure. \r\n\r\nThe accuracy of the ECST in predicting significant CAD is variable, depending in part on the \"pre-test likelihood\" of CAD (also known as Bayes\' theorem). In a patient at high risk for CAD (e.g.: advanced age, multiple coronary risk factors), an abnormal ECST is very predictive of the presence of CAD (over 90% accurate). However, a relatively normal ECST may not reflect the absence of significant disease in a patient with the same risk factors. Conversely, in a low- risk patient, a normal ECST is very predictive of the absence of significant CAD (over 90% accurate), but an abnormal test may not reflect the true presence of CAD (so-called \"false-positive ECST\"). The ECST may either miss the presence of significant CAD, or be a false-positive test, due to a variety of cardiac circumstances, which may include: \r\n\r\nAn abnormal EKG at rest, which may be due to abnormal serum electrolytes, abnormal cardiac electrical conduction, or certain medications, such as digitalis; \r\nHeart conditions not related to CAD, such as mitral valve prolapse or hypertrophy (increased size) of the heart; or \r\nAn inadequate increase in the heart rate and/or blood pressure during exercise.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('327', 'RADIONUCLEIDE STRESS TEST', '1', '0', 'Radionucleide stress testing involves injecting a radioactive isotope (typically thallium or cardiolyte) into the patient\'s vein after which an image of the patient\'s heart becomes visible with a special camera. The radioactive isotopes are absorbed by the normal heart muscle. Nuclear images are obtained in the resting condition, and again immediately following exercise. The two sets of images are then compared. During exercise, if a blockage in a coronary artery results in diminished blood flow to a part of the cardiac muscle, this region of the heart will appear as a relative \"cold spot\" on the nuclear scan. This cold spot is not visible on the images that are taken while the patient is at rest (when coronary flow is adequate). Radionucleide stress testing, while more time-consuming and expensive than a simple ECST, greatly enhances the accuracy in diagnosing CAD. \r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('328', 'STRESS ECHOCARDIOGRAPHY', '1', '0', 'Another supplement to the routine ECST is stress echocardiography. During stress echocardiography, the sound waves of ultrasound are used to produce images of the heart at rest and at the peak of exercise. In a heart with normal blood supply, all segments of the left ventricle (the major pumping chamber of the heart) exhibit enhanced contractions of the heart muscle during peak exercise. Conversely, in the setting of CAD, if a segment of the left ventricle does not receive optimal blood flow during exercise, that segment will demonstrate reduced contractions of heart muscle relative to the rest of the heart on the exercise echocardiogram. Stress echocardiography is very useful in enhancing the interpretation of the ECST, and can be used to exclude the presence of significant CAD in patients suspected of having a \"false-positive\" ECST. \r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('330', 'CORONARY ANGIOGRAPHY', '1', '0', 'During a coronary angiogram, a small catheter (a thin hollow tube with a diameter of 2-3 mm) is inserted through the skin into an artery in either the groin or the arm. Guided with the assistance of a fluoroscope (a special x-ray viewing instrument), the catheter is then advanced to the opening of the coronary arteries, the blood vessels supplying blood to the heart. Next, a small amount of radiographic contrast (a solution containing iodine, which is easily visualized with x-ray images) is injected into each coronary artery. The images that are produced are called the angiogram. \r\n\r\nAngiographic images accurately reveal the extent and severity of all coronary arterial blockages. Coronary angiography is performed with the use of local anesthesia and intravenous sedation, and is generally not terribly uncomfortable. The procedure takes approximately 20-30 minutes. After the procedure, the catheter is removed and the artery in the leg or arm is either sutured, \"sealed,\" or treated with manual compression to prevent bleeding. There is a small risk of serious complications from coronary angiography, as it is an \"invasive\" test, but in the hands of experienced physicians, this risk is quite small (well below one per cent). In appropriate patients, the therapeutic information learned from the angiogram is far more valuable than the relatively small risk of the procedure. For patients with severe angina or myocardial infarction, or those who have markedly abnormal noninvasive tests for CAD, the angiogram also helps the doctor select the optimal treatment, which may include medications, balloon angioplasty, coronary stenting, atherectomy (\"roto-rooter\"), or coronary bypass surgery. The coronary angiogram is the only test which allows the precise quantification of the extent and severity of CAD to optimally make these treatment decisions. \r\n\r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('333', 'ANTI-THYROID PEROXIDASE ANTIBODIES TEST(TPO)', '0', '0', 'A test done to detect autoantibodies directed against thyroid peroxidase (TPO), an enzyme in the thyroid gland that is very important to the production of thyroid hormones. TPO is found in thyroid follicle cells where it catalyzes the iodination of T4 and T3 in the biosynthesis of thyroid hormones. \r\nAutoantibodies to thyroid peroxidase (abbreviated TPOAb) are produced by the body itself. TPOAb can attack the thyroid and damage thyroid function. These antibodies are present in a high proportion (70% to 90%) of people with chronic thyroiditis. These antibodies are also present in lesser numbers of people with other thyroid diseases. Other autoimmune disorders such as Sjögren syndrome, lupus, rheumatoid arthritis, and pernicious anemia are sometimes positive for TPOAb. Small numbers (around 3%) of people may have TPOAb show no evidence of disease. The chance of having TPOAb is greater in females and increases with age. \r\n\r\n', '2', '', '0', '0', '2', '0', '0', 'PRESENT : CHRONIC THYROIDITIS ( 70 - 90 % ), SJOGREN SYNDROME, LUPUS, RHEUMATOID ARTHRITIS, PERNICIOUS ANEMIA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('335', 'ENDOSCOPY UPPER G.I.', '1', '0', 'It is a procedure that enables the examiner (usually a Gastroenterologist) to examine your esophagus (swallowing tube), stomach, and duodenum (first portion of small bowel) using a thin flexible tube that can be looked through or seen on a TV monitor. \r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('338', 'ESOPHAGEAL MANOMETRY', '1', '0', 'Esophageal manometry is a procedure for determining how well the muscle of the esophagus works when diseases of the muscle are suspected.\r\n\r\nWhen is esophageal manometry used?\r\n\r\nEsophageal manometry is used primarily in three situations. The first is to evaluate the cause of reflux (regurgitation) of stomach acid and contents back into the esophagus (gastroesophageal reflux disease or GERD). The second is to determine the cause of problems with swallowing food. The third is when there is chest pain that may be coming from the esophagus.\r\nAt the start of the esophageal manometry procedure, one nostril is anesthetized with a numbing lubricant. A flexible plastic tube approximately one-eighth inch in diameter is then passed through the anesthetized nostril, down the back of the throat, and into the esophagus as the patient swallows. Once inside the esophagus, the tube allows the pressures generated by the esophageal muscle to be measured when the muscle is at rest and during swallows. The procedure takes 20 to 30 minutes.\r\n\r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('339', 'SIGMOIDOSCOPY', '1', '0', 'Flexible sigmoidoscopy is a procedure enabling your doctor to examine the rectum and the lower colon. The instrument is a flexible tube 60 cm. long that is about the thickness of your finger and it is gently inserted into the anus and advanced slowly into the rectum and then the lower colon. It is an accurate and simple method for investigating rectal bleeding, change in bowel habits, rectal symptoms such as pain, diarrhea, etc. It is also a part of colon screening and surveillance for polyps and cancer prevention.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('343', 'MAMMOGRAM', '1', '0', 'A mammogram is an x-ray test that produces an image of the inner breast tissue on film. This technique, called mammography, is used to visualize normal and abnormal structures within the breasts. Mammography, therefore, can help in identifying cysts, calcifications, and tumors within the breast. It is currently the most effective way to detect early breast cancer. Breast self- examination (BSE) on a monthly basis and examination by a doctor are still important, but physical examinations typically find breast cancers when they are much larger than those detected by mammography. While mammography can discover a small cancer in a curable stage it not foolproof. Ten to fifteen percent of breast cancers are not identified by mammography and these cancers are found by physical examination. It is essential for a woman to perform monthly BSE and have a breast examination by her doctor in addition to the mammogram in order to most effectively screen for breast cancer. \r\nThe American Cancer Society and the American College of Surgeons currently recommend that a woman obtain her first baseline mammogram between the ages of 35 to 40. Between the ages of 40 to 50 a mammogram should be done every other year. After the age of 50, a mammogram should be repeated yearly. Women who are at high risk for developing breast cancer may need to obtain mammograms earlier than these recommendations and at more frequent intervals.\r\n\r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('345', 'PCR', '1', '0', 'PCR (Polymerase Chain Reaction) is a key technique in molecular genetics that permits the analysis of any short sequence of DNA (or RNA) without having to clone it. PCR is used to reproduce (amplify) selected sections of DNA. Previously, amplifying was done in bacteria, and took weeks. But now, with PCR done in test tubes, it takes only a few hours. PCR is highly efficient so that untold numbers of copies can be made of the DNA. What is more, PCR uses the same molecules that nature uses for copying DNA: \r\nTwo \"primers\" that flag the beginning and end of the DNA stretch to be copied; \r\nAn enzyme called polymerase that walks along the segment of DNA, reading its code and assembling a copy; and \r\nA pile of DNA building blocks that the polymerase needs to make that copy. \r\nThree major steps are involved in a PCR. These three steps are repeated for 30 or 40 cycles. The cycles are done on an automated cycler, which rapidly heats and cools the test tubes containing the reaction mixture. Each step -- denatauration (alteration of structure), annealing (joining), and extension -- takes place at a different temperature: \r\n\r\nDenaturation: At 94°C, the double-stranded DNA melts and opens into single-stranded DNA. \r\nAnnealing: At 54°C, hydrogen bonds form and break between the single-stranded \"primer\" and the single-stranded \"template.\" (The template provides the pattern to be copied.) The more stable bonds last longer and on that little length of double-stranded DNA (the joined primer and template), the polymerase attaches and starts copying the template. \r\nExtension: At 72°C, the polymerase works best. As a result, the attraction, created by the hydrogen bonds, of the primers to the template is stronger than the forces breaking these attractions. The upshot is that bases complementary to the template are coupled to the primer.\r\nTo do PCR, the original DNA that one wishes to copy need not be pure or abundant. It can be pure but it also can be a minute part of a mixture of materials. So, PCR has found widespread and innumerable uses -- to diagnose genetic diseases, do DNA fingerprinting, find bacteria and viruses, study human evolution, clone the DNA of an Egyptian mummy, etc.. Accordingly, PCR has become an essential tool for biologists, DNA forensics labs, and many other laboratories that study genetic material.\r\n\r\n', '4', '', '0', '0', '0', '0', '0', 'PCR CAN BE DONE FOR ANY KIND OF INFECTIVE ORGANISM.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('347', 'PUS CULTURE TEST', '1', '0', 'CULTURE TEST HELPS IN ISOLATING THE OFFENDING AGENT AS WELL AS IN TREATING THE DISEASE BY FINDING OUT THE MOST SUITABLE DRUG AFTER SENSTIVITY TEST RESULTS.\r\nTHIS TEST CAN BE PERFORMED ON ANY BODY FLUID OR DISCHARGE TO KNOW THE OFFENDING AGENT & THE DRUGS TO WHICH IT IS SENSITIVE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('350', 'CT SCAN ABDOMEN', '1', '0', 'C.T. OR COMPUTERIZED TOMOGRAPHY IS UNIQUE BECAUSE IT CAN PRODUCE CROSS SECTIONAL IMAGES OF ANATOMIC STRUCTURES WITHOUT SUPERIMPOSING TISSUES ON EACH OTHER. ADDITIONALLY, CT CAN DISCERN THE DIFFERENT CHARACTERISTICS OF TISSUE STRUCTURES WITHIN SOLID ORGANS. AGENTS MAY BE USED FOR DELINEATION OF BLOOD VESSELS, THE OPACIFICATION OF CERTAIN TISSUE ( KIDNEYS ), DEMONSTRATION OF BOWEL, & BLOOD FLOW PATTERNS. THIS MEANS A CT SCAN CAN DEMONSTRATE MINOR DIFFERENCES IN DENSITY & COMPOSITION IN SHADES OF GREY. A CT SCAN CAN DIFFERENTIATE TUMORS FROM SOFT TISSUES, AIR SPACES FROM CSF & NORMAL BLOOD FROM CLOTTED BLOOD.\r\nC.T. CAN BE PERFORMED ON ANY PART OF THE BODY LIKE : ABDOMEN, PELVIS, SPINE, HEAD, SINUSES, ORBITS, MASTOIDS, INTERNAL AUDITORY CANAL, FACIAL BONES, NECK, CHEST INCLUDING LUNGS, MEDIASTINUM & HEART, JOINTS & SPECIFIC BONES & CT GUIDED BIOPSY.CT CAN BE USED TO DETECT INTERVERTIBRAL DISC DISEASE, HERNIATION & SOFT TISSUE DAMAGE TO LIGAMENTS WITHIN JOINT SPACES.\r\nIN C.T. LIGHTER THE SHADING, THE HIGHER THE DENSITY OF THE TISSUE OR STRUCTURE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('351', 'PULMONARY FUNCTION TEST', '1', '0', 'THERE ARE THREE ASPECTS OF PULMONARY FUNCTIONS : PERFUSION, DIFFUSION & VENTILATION. PERFUSION RELATES TO BLOOD FLOW THROUGH PULMONARY VESSELS; DIFFUSION REFERS TO MOVEMENTS OF OXYGEN & CARBON DIOXIDE ACROSS ALVEOLAR CAPILLARY MEMBRANES; & VENTILATION RELATES TO AIR EXCHANGE BETWEEN ALVEOLAR SPACES & THE ATMOSPHERE.\r\nPULMONARY FUNCTION TESTS DETERMINE THE PRESENCE, NATURE & EXTENT OF PULMONAY DISFUNCTION CAUSED BY OBSTRUCTION, RESTRICTION OR BOTH. PULMONARY FUNCTION STUDIES MAY REVEAL LOCATIONS OF ABNORMALITIES IN THE AIRWAYS, ALVEOLI & PULMONARY VASCULAR BED EARLY IN THE COURSE OF A DISEASE, WHEN THE PHYSICAL EXAMINATION & RADIOLOGICAL STUDIES STILL APEAR NORMAL.\r\nINDICATIONS FOR THE TEST :\r\n* EARLY DETECTION OF PULMONARY OR CARDIOGENIC PULMONARY DISEASE\r\n* DIFFERENTIAL DIAGNOSIS OF DYSPNEA.\r\n* PRESURGICAL ASSESSMENT.\r\n* EVALUATION OF RISK FACTORS FOR OTHER DIAGNOSTIC PROCEDURES.\r\n* DETECTION OF EARLY RESPIRATORY FAILURE.\r\n* MONITORING PROGRESS OF BRONCHOPULMONARY DISEASE.\r\n* PERIODIC EVALUATION OF WORKERS EXPOSED TO MATERIALS HARMFUL TO RESPIRATORY SYSTEM\r\n* EPIDEMIOLOGICAL STUDIES\r\n* MONITORING AFTER PHARMACOLOGICAL OR SURGICAL INTERVENTIONS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('353', 'CT SCAN THORAX', '1', '0', 'C.T. OR COMPUTERIZED TOMOGRAPHY IS UNIQUE BECAUSE IT CAN PRODUCE CROSS SECTIONAL IMAGES OF ANATOMIC STRUCTURES WITHOUT SUPERIMPOSING TISSUES ON EACH OTHER. ADDITIONALLY, CT CAN DISCERN THE DIFFERENT CHARACTERISTICS OF TISSUE STRUCTURES WITHIN SOLID ORGANS. AGENTS MAY BE USED FOR DELINEATION OF BLOOD VESSELS, THE OPACIFICATION OF CERTAIN TISSUE ( KIDNEYS ), DEMONSTRATION OF BOWEL, & BLOOD FLOW PATTERNS. THIS MEANS A CT SCAN CAN DEMONSTRATE MINOR DIFFERENCES IN DENSITY & COMPOSITION IN SHADES OF GREY. A CT SCAN CAN DIFFERENTIATE TUMORS FROM SOFT TISSUES, AIR SPACES FROM CSF & NORMAL BLOOD FROM CLOTTED BLOOD.\r\nC.T. CAN BE PERFORMED ON ANY PART OF THE BODY LIKE : ABDOMEN, PELVIS, SPINE, HEAD, SINUSES, ORBITS, MASTOIDS, INTERNAL AUDITORY CANAL, FACIAL BONES, NECK, CHEST INCLUDING LUNGS, MEDIASTINUM & HEART, JOINTS & SPECIFIC BONES & CT GUIDED BIOPSY.CT CAN BE USED TO DETECT INTERVERTIBRAL DISC DISEASE, HERNIATION & SOFT TISSUE DAMAGE TO LIGAMENTS WITHIN JOINT SPACES.\r\nIN C.T. LIGHTER THE SHADING, THE HIGHER THE DENSITY OF THE TISSUE OR STRUCTURE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('354', 'BRONCHO-ALVEOLAR LAVAGE FOR CYTOLOGY', '1', '0', 'EXFOLIATED CELLS IN BODY TISSUES AND FLUIDS ARE STUDIED TO DETERMINE THE TYPES OF CELLS PRESENT & TO DIAGNOSE MALIGNANT & PREMALIGNANT CONDITIONS. THIS IS ESPECIALLY USEFUL IN DIAGNOSIS OF MALIGNANCY & IS NOW USED ROUTINELY IN THE CYTOLOGIC STUDY OF FEMALE GENITAL TRACT AS WELL AS IN MANY TYPES OF NONGYNAECOLOGICAL SPECIMENS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('355', 'URINE MYOGLOBULIN', '1', '0', '.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('356', 'LIPIDS PROFILE', '1', '0', 'IT IS ESTIMATION OF ALL DIFFERENT KINDS OF BODY FATS WHICH ARE IMPORTANT FOR CARDIO-VASCULAR OR CEREBRO-VASCULAR POINTS OF VIEW. TO SEE VALUES OR IMPORTANCE OF EACH ONE OF THEM GO TO THEIR INDIVIDUAL TEST RECORDS.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('357', 'CARDIAC DOPPLER', '1', '0', 'TO SEE THE FUNCTIONING OF THE HEART, PRESSURE GRADIENTS , VALVULAR FUNCTIONS & OTHER ABNORMALITIES CARDIAC DOPPLER IS RECOMMENDED.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('360', 'MUCOSAL BIOPSY', '1', '0', 'MUCOSAL BIOPSY LIKE ANY OTHER BIOPSY IS DONE TO KNOW THE PATHOPHYSIOLOGY OF THE LOCAL DISEASE. THIS COULD BE FROM GUT, ESOPHAGUS RECTUM ANAL CANAL OR ANY OTHER MUCOSAL AREA.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('361', 'SERUM B12', '0', '0', 'SERUM B12 LEVELS ARE AFFECTED IN MALABSORPTION CASES AS WELL AS IN DIETARY DEFICIENCY STATES LEADING TO MEGALOBLASTIC ANAEMIA.', '1', 'pg / ml', '200', '600', '0', '0', '0', 'DECREASED : MEGALOBLASTIC ANEMIA DUE TO VIT B12 DEFICIENCY, PERNICIOUS ANEMIA, CHR. PANCREATITIS, BLIND LOOP SYNDROME, ILEAL DISEASE, ACHLORHYDRIA, BACTERIAL OVERGROWTH SYNDROME.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('362', 'SERUM CAROTENOIDS', '0', '0', 'THERE ARE OVER 600 CAROTENOIDS INNATURE, & APPROXIMATELY 50 OF THESE CAN METABOLISED TO VIT A. BETA-CAROTENE IS THE MOST PREVALENT CAROTENOID IN THE FOOD SUPPLY THAT HAS PROVITAMIN A ACTIVITY. AFTER ABSORPTION CAROTENOIDS APPEAR IN THE SERUM WHICH CAN BE ESTIMATED NOW.', '1', 'micro gm / ml', '27', '37', '0', '0', '0', 'DECREASED : MALABSORPTION SYNDROME, POOR DIETARY INTAKE OF VEGETABLES.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('363', 'SCHILLING TEST', '0', '0', 'THIS TEST IS PERFORMED TO DETERMINE THE CAUSE FOR COBALAMIN MALABSORPTION. SINCE COBALAMINE ABSORPTION REQUIRES MULTIPLE STEPS, INCLUDING GASTRIC, PANCREATIC & ILEAL PROCESSES, IT CAN ALSO BE USED TO ASSESS THE INTEGRITY OF THESE OTHER ORGANS.THE TEST IS PERFORMED BY ADMINISTERING COBALT-58 LABELED COBALAMIN & COLLECTING URINE FOR 24 HRS & IS DEPENDENT UPON NORMAL RENAL & BLADDER FUNCTION.', '1', '% excretion in 24 hrs', '10', '90', '0', '0', '0', 'ABNORMAL ( < 10% EXCRETION IN 24 HRS ) - PERNICIOUS ANEMIA, CHR. PANCREATITIS, BLIND LOOP SYNDROME, ILEAL DISEASE', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('364', 'URINARY D-XYLOSE TEST', '0', '0', 'THE URINARY D-XYLOSE TEST FOR CARBOHYDRATE ABSORPTION PROVIDES AN ASSESSMENT OF PROXIMAL INTESTINAL MUCOSAL FUNCTION. D-XYLOSE, A PENTOSE IS ABSORBED ALMOST EXCLUSIVELY IN PROXIMAL SMALL INTESTINE. THIS IS USUALLY PERFORMED BY GIVING 25 GMS D-XYLOSE & COLLECTING URINE FOR 5 HRS. AN ABNORMAL TEST ( < 4.5 GM EXCRETION ) PRIMARILY REFLECTS THE PRESENCE OF DUODENAL/ JEJUNAL MUCOSAL DISEASE. THIS TEST CAN ALSO BE ABNORMAL IN PTS WITH BLIND LOOP SYNDROME & AS A FALSE POSITIVE STUDY, IN PTS WITH LARGE COLLECTION OF FLUID IN A THIRD SPACE LIKE ASCITIS, PLEURAL FLUID. THE EASE OF OBTAINING INTESTINAL MUCOSAL BIOPSY & THE FALSE NEGATIVE RATE OF D-XYLOSE TEST HAVE LED TO ITS DIMINISHED USE.', '1', 'gm', '4.5', '20', '0', '0', '0', 'ABNORMAL : MALABSORPTION SYNDROME DUE TO SMALL INTESTINAL PATHOLOGY', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('366', 'STOOL FAT CONTENT 24 HRS', '0', '0', 'IN MALABSORPTION FATS ARE NOT PROPERLY ABSORBED AND BY ESTIMATING 24 HRS STOOL FAT CONTENT WE CAN DIAGNOSE MALABSORPTION SITUATION. ON AN 80-100 GM/ DAY FAT DIET THE NORMAL FECAL FAT IS 2-6 GM / DAY', '1', 'gm / 24 hrs', '0', '6', '0', '0', '0', 'NORMAL - 0 - 6 GM / 24 HRS\r\n\r\nINCREASED : PANCREATIC INSUFFICIENCY, CROHNS DISEASE, CHR PANCREATITIS, SPRUE', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('367', 'COLONOSCOPY', '1', '0', 'COLONOSCOPY IS DONE TO DIAGNOSE PATHOLOGY OF LARGE BOWEL LIKE SPACE OCCUPYING LESIONS INTUSSUSSEPTION, DIVERTICULAE, POLYPS ETC. A FIBRO-OPTIC COLONOSCOPE IS USED.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('369', 'SPUTUM FOR AFB STAINING', '0', '0', 'IT IS DONE TO DIAGNOSE OPENNESS OF THE LUNG TUBERCULOSIS.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('370', 'SPUTUM FOR CULTURE & SENSTIVITY TEST', '1', '0', 'THIS TEST IS DONE TO FIND OUT THE EFFECTIVE ANTIBIOTICS AGAINST THE OFFENDING ORGANISM.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('371', 'BRONCHOSCOPY', '1', '0', 'BRONCHOSCOPY IS DONE FOR DIAGNOSING INTRALUMINAL GROWTHS BY EITHER TAKING BIOPSY OR BRONCHIAL SECRETIONS FOR CELL CYTOLOGY ETC.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('372', 'BRONCHOGRAPHY', '1', '0', 'A RADIO-OPAQUE DYE IS USED FOR BRONCHOGRAPHY. THIS TEST IS DONE TO DIAGNOSE INTRALUMINAL PATHOLOGIES , BRONCHIACTESIS ATELECTESIS ETC.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('373', 'MRI', '1', '0', 'MAGNETIC RESONANCE IMAGING IS A DIAGNOSTIC MODALITY THAT EMPLOYS ASUPERCONDUCTING MAGNET & RADIOFREQUENCY SIGNALS TO CAUSE HYDROGEN NUCLEI TO EMIT THEIR OWN SIGNALS TO CONSTRUCT DETAILED SECTIONAL IMAGES OF BODY. NO IONIZING RADIATION IS USED IN THIS. THE ABILITY OF MAGNETIC RESONANCE TO DISCERN ANATOMY IS MOST CLOSELY LINKED TO THE MOLECULAR NATURE OF TISSUE. SPECIAL TECHNIQUES PRIMARILY BASED ON THE MAGNETIC REACTIONS OF HYDROGEN NUCLEI CAN INFLUENCE THE MRI SIGNALS TO ENHANCE CERTAIN TYPES OF TISSUES ( FAT IS ACCENTUATED IN T-1 WEIGHTED IMAGES, CEREBROSPINAL FLUID & OTHEWR PURE FLUIDS ARE HIGHLIGHTED IN T-2 WEIGHTED IMAGES ). COMPUTER RECONSTRUCTION TECHNIQUES ALLOW IMAGES TO BE PRODUCED IN ANY PLANE AS WELL AS IN THE THREE DIMENTIONAL VIEWS.\r\nINTRAVENOUS MR CONTRAST AGENTS, ALL PRIMARILY CONTAINING WATER SOLUBLE GADOLINIUM COMPLEX OR OTHER METALS SUCH AS MANGANESE & IRON ARE USED IN EVALUATING THE CNS . MR CONTRAST AGENTS HAVE LOWER TOXICITY & FEWER SIDE EFFECTS THAN X-RAY CONTRAST AGENTS. HOWEVER BECAUSE THESE AGENTS ARE PRIMARILY EXCRETED VIA KIDNEYS, RENAL FAILURE IS A CONTRAINDICATION FOR USE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('374', 'CT SCAN', '1', '0', 'C.T. OR COMPUTERIZED TOMOGRAPHY IS UNIQUE BECAUSE IT CAN PRODUCE CROSS SECTIONAL IMAGES OF ANATOMIC STRUCTURES WITHOUT SUPERIMPOSING TISSUES ON EACH OTHER. ADDITIONALLY, CT CAN DISCERN THE DIFFERENT CHARACTERISTICS OF TISSUE STRUCTURES WITHIN SOLID ORGANS. AGENTS MAY BE USED FOR DELINEATION OF BLOOD VESSELS, THE OPACIFICATION OF CERTAIN TISSUE ( KIDNEYS ), DEMONSTRATION OF BOWEL, & BLOOD FLOW PATTERNS. THIS MEANS A CT SCAN CAN DEMONSTRATE MINOR DIFFERENCES IN DENSITY & COMPOSITION IN SHADES OF GREY. A CT SCAN CAN DIFFERENTIATE TUMORS FROM SOFT TISSUES, AIR SPACES FROM CSF & NORMAL BLOOD FROM CLOTTED BLOOD.\r\nC.T. CAN BE PERFORMED ON ANY PART OF THE BODY LIKE : ABDOMEN, PELVIS, SPINE, HEAD, SINUSES, ORBITS, MASTOIDS, INTERNAL AUDITORY CANAL, FACIAL BONES, NECK, CHEST INCLUDING LUNGS, MEDIASTINUM & HEART, JOINTS & SPECIFIC BONES & CT GUIDED BIOPSY.CT CAN BE USED TO DETECT INTERVERTIBRAL DISC DISEASE, HERNIATION & SOFT TISSUE DAMAGE TO LIGAMENTS WITHIN JOINT SPACES.\r\nIN C.T. LIGHTER THE SHADING, THE HIGHER THE DENSITY OF THE TISSUE OR STRUCTURE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('375', 'X-RAY', '1', '0', '.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('379', 'LIVER FUNCTION TEST', '0', '0', '.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('384', 'BIOPSY', '1', '0', 'BY TAKING BIOPSY OF THE DISEASED AREA WE CAN PIN POINT THE DEFINITE PATHOLOGY OR DIAGNOSIS OF THE DISEASE.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('385', 'HEPATITIS - C  DISEASE', '0', '0', 'THIS TEST IS DONE TO DIAGNOSE THE PRESENCE OF HEPATITIS C-VIRUS IN THE BODY.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('386', 'GRAM STAINING', '1', '0', 'GRAM STAINING IS DONE TO IDENTIFY THE CAUSATIVE ORGANISM IN THE SPECIMEN COLLECTED FROM THE LESION OR DISEASED AREA. THE BACTERIAS CAN BE GRAM POSITIVE OR GRAM NEGATIVE ETC, ETC.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('387', 'URINARY 5-HIAA', '0', '0', '5-HIAA IS A METABOLITE OF SEROTONIN WHICH IS INCREASED IN CARCINOID SYNDROME. BOTH URINARY OR PLASMA SEROTONIN METABOLITS CAN BE MEASURED. THE TEST HAS 73% SENSTIVITY & 100% SPECIFICITY.', '1', 'mg / day', '2', '8', '0', '0', '0', 'INCREASED : CARCINOID SYNDROME\r\nFALSE POSITIVE : PATIENTS HAVING HIGH SEROTONIN FOODS LIKE BANANAS, PINEAPPLE, WALNUTS, PECANS, AVOCADOS, HICKORY NUTS OR TAKING CERTAIN MEDICATIONS LIKE COUGH SYRUPS CONTAINING GUAIPHENESIN, ACETAMINOPHEN, SALICYLATES, L-DOPA.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('389', 'MR ANGIOGRAPHY', '1', '0', 'MR ANGIOGRAPHY IS NON INVASIVE HIGHLY SENSITIVE INVESTIGATION FOR DIAGNOSING ARTERIAL STENOSES, PLAQUES ETC.', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('390', 'ELISA TEST', '0', '0', 'ELISA TEST IS ENZYME LINKED IMMUNOSORBENT ASSAY & IS BASED ON ANTIGEN - ANTIBODY REACTIONS. THE COLOR CHANGE INDICATES ENZYME SUBSTRATE REACTION.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('392', 'BLOOD SUGAR ( RANDOM )', '0', '0', 'GLUCOSE IS FORMED FROM CARBOHYDRATE DIGESTION & CONVERSION OF GLYCOGEN TO GLUCOSE BY THE LIVER. THE TWO HORMONES THAT DIRECTLY REGULATE BLOOD GLUCOSE LEVELS ARE GLUCAGON & INSULIN. GLUCAGON ACCELERATES GLYCOGEN BREAKDOWN IN THE LIVER & CAUSES THE BLOOD GLUCOSE LEVELS TO RISE. INSULIN INCREAES CELL MEMBRANE PERMEABILITY TO GLUCOSE, TRANSPORT GLUCOSE INTO CELLS, STIMULATES GLYCOGEN FORMATION, & REDUCE BLOOD GLUCOSE LEVELS.', '1', 'Mg %', '60', '160', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('396', 'GASTRIC ACID ANALYSIS', '0', '0', 'GASTRIC ACID ANALYSIS IS PERFORMED BY PLACING A NASOGASTRIC TUBE IN THE STOMACH & DRAWING SAMPLES AT 15 MTS INTERVAL FOR 1 HR. DURING UNSTIMULATED OR BASAL STATE ( BAQ) , FOLLOWED BY CONTINUED SAMPLING AFTER ADMINISTERING I.V. PENTAGASTRIN ( MAO )MAXIMAL ACID OUTPUT.', '1', 'meq / hr', '0', '4', '0', '0', '0', 'UP TO 90% OF GASTRINOMA PATIENTS MAY HAVE A BAQ OF >=15 MEQ/H ( NORMAL <4 MEQ/H ). UP TO 12% OF PATIENTS WITH COMMON PEPTIC ULCER DISEASE MAY HAVE COMPARABLE LEVELS OF ACID SECRETION. A BAQ/MAO RATIO > 0.6 IS HIGHLY SUGGESTIVE OF ZOLLINGER-ELLISON SYNDROME , BUT A RATIO <0.6 DOESNT EXCLUDE IT.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('412', 'MYOGLOBIN', '0', '0', 'MYOGLOBIN IS THE OXYGEN BINDING PROTEIN OF STRIATED MUSCLE. IT RESEMBLES HB BUT IS UNABLE TO RELEASE OXYGEN EXCEPT AT VERY LOW TWNSION. INJURY TO SKELETAL MUSCLE RESULTS IN RELEASE OF MYOGLOBIN. IT IS NOT SPECIFIC TO HEART MUSCLE. MYOGLOBIN IS NOT TIGHTLY BOUND TO PROTEIN & IS RAPIDLY EXCRETED IN THE URINE.\r\nTHE MYOGLOBIN TEST IS USED AS AN EARLY MARKER OF MUSCLE DAMAGE IN MYOCARDIAL INFARCTION & TO DETECT INJURY, DAMAGE OR NECROSIS TO SKELETAL MUSCLE. SERUM MYOGLOBIN IS FOUND EARLIER THAN CREATINE KINASE ENZYMES IN ACUTE MYOCARDIAL INFARCTION.', '1', 'ng / ml', '5', '70', '0', '0', '0', 'INCREASED : MYOCARDIAL INFARCTION( ELEVATES IN 1-3 HRS AFTER PAIN) , ANGINA WITHOUT INFARCTION, MUSCLE INJURY , POLYMYOSITIS , PROGRESSIVE MUSCULAR DYSTROPHY, MYOSITIS, RHABDOMYOLYSIS, INFLAMMATORY MYOPATHY ( SLE ) , TOXIN EXPOSURE ( NARCOTICS , MALAYAN SEA SNAKE TOXIN ), MALIGNANT HYPERTHERMIA , RENAL FAILURE, ELECTRIC SHOCK, TONIC CLONIC SEIZURES\r\n\r\nDECREASED : CIRCULATING ANTIBODIES TO MYOGLOBIN ( MANY PATIENTS WITH POLYMYOSITIS ) , RHEUMATOID ARTHRITIS, MYASTHENIA GRAVIS', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('417', 'PLATELET AGGREGATION', '1', '0', 'PLATELET AGGREGATION IS USED TO EVALUATE FUNCTIONAL DISORDERS OF THE ADHESION, RELEASE OR AGGREGATION. IT IS RARELY USED TO EVALUATE ACQUIRED BLEEDING DISORDERS.', '4', '', '0', '0', '0', '0', '0', 'NORMAL : FULL PLATELET AGGREGATION IN RESPONSE TO THE FOLLOWING :\r\n- ADENOSINE DIPHOSPHATE \r\n- COLLAGEN\r\n- EPINEPHRINE\r\n- THROMBIN\r\n- RISTOCETIN\r\n\r\nDECREASED RESPONSE IN CONGENITAL DISEASES :\r\n- BERNARD-SOULIER SYNDROME , GLANZMANNS THROMBASTHENIA , STORAGE POOL DISEASES ( CHEDIAK- HIGASHI SYNDROME , GRAY PLATELET DISEASE ) , CYCLOOXYGENASE DEFICIENCY , WISKOTT-ALDRICH SYNDROME , ALBINISM , BETA- THALASSEMIA, MAY - HEGGLIN ANOMALY , VARIOUS CONNECTIVE TISSUE DISORDERS ( EG. MARFAN SYNDROME ) , VON WILLEBRANDS DISEASE\r\n\r\nINCREASED AGGREGATION OCCURS IN PRIMARY & SECONDARY RAYNAUDS SYNDROME\r\n\r\nDECREASED PLATELET AGGREGATION IN ACQUIRED DISEASES :\r\n- UREMIA , ANTIPLATELET ANTIBODIES , CARDIOPULMONARY BYPASS , MYELOPROLIFERATIVE DISORDERS , DYSPROTEINEMIAS (MACROGLOBULINEMIA) , IDIOPATHIC THROMBOCYTOPENIC PURPURA, POLYCYTHEMIA VERA , USE OF DRUGS & ASPIRIN, SOME ANTIBIOTICS , ANTI-INFLAMMATORY DRUGS, PSYCHOTROPIC DRUGS & OTHERS , DIC.\r\n\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('439', 'CT SCAN CONTRAST STUDY', '0', '0', '.', '4', '', '0', '0', '0', '0', '0', '.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('445', 'D-XYLOSE ABSORPTION', '0', '0', 'THE D-XYLOSE TEST IS A DIAGNOSTIC MEASURE FOR EVALUATING MALABSORPTIVE CONDITIONS & INTESTINAL ABSORPTION OF D-XYLOSE, A PENTOSE NOT NORMALLY PRESENT IN THE BLOOD IN SIGNIOFICANT AMOUNTS. IT IS PASSIVELY ABSORBED IN THE PROXIMAL BOWEL, PASSES UNCHANGED IN THE LIVER, AND IS EXCRETED BY THE KIDNEYS.\r\nTHIS TEST DIRECTLY MEASURES INTESTINAL ABSORPTION. WHEN D-XYLOSE IS ADMINISTERED ORALLY, BLOOD & URINE LEVELS ARE CHECKED FOR ABSORPTION RATES.ABSORPTION IS NORMAL IN PANCREATIC INSUFFICIENCY BUT IS IMPAIRED IN INTESTINAL MALABSORPTION. IT IS A RELIABLE INDEX OF FUNCTIONAL INTEGRITY OF THE JEJUNUM IN PEDIATRIC PATIENTS.', '2', '', '0', '0', '2', '0', '0', 'NORMAL BLOOD LEVELS :\r\n1- HR ABSORPTION OF 5 GM DOSE - INFANT: >15 MG / ML\r\n1-HR ABSORPTION OF 5 GM DOSE- CHILD: > 20 MG / ML\r\n2-HR ABSORPTION OF 5 GM DOSE- ADULT : >20 GM / ML \r\n2-HR ABSORPTION OF 25 GM DOSE- ADULT: > 25 GM / ML\r\n\r\nURINE XYLOSE 5 HR REFERENCE RANGE FOR 25 G DOSE:\r\nCHILD : 16% - 33% OF 5 GM DOSE\r\nADULT : > 16 % OF 5 GM \r\nADULT 65 YRS OF AGE OR OLDER : > 14 % OF DOSE\r\n\r\nURINE D-XYLOSE IS DECREASED IN :\r\nINTESTINAL MALABSORPTION, IMPAIRED RENAL FUNCTION, SMALL BOWEL ISCHEMIA , WHIPPLES DISEASE, VIRAL GASTROENTERITIS , BACTERIAL OVERGROWTH IN SMALL INTESTINE.\r\n\r\nD-XYLOSE TEST IS NORMAL IN :\r\nMALABSORPTION DUE TO PANCREATIC INSUFFICIENCY , POSTGASTRECTOMY , MALNUTRITION.\r\n\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('456', 'MYOCARDIAL PERFUSION TEST', '0', '0', 'TC-99 SESTAMIBI , THALLIUM-201 & TC-99 TETROFOSMIN ARE THE RADIOISOTOPES AVAILABLE FOR MYOCARDIAL PERFUSION IMAGING TO DIAGNOSE ISCHAEMIC HEART DISEASE & ALLOW DIFFERENTIATION OF ISCHAEMIA & INFARCTION. THIS TEST REVEALS MYOCARDIAL WALL DEFECTS & HEART PUMP PERFORMANCE DURING INCREASED OXYGEN DEMANDS. THESE SCANS MAY ALSO BE DONE BEFORE & AFTER STREPTOKINASE TREATMENT FOR CORONARY ARTRY THROMBOSIS, AFTER SURGERY FOR GREAT VESSELS TRANSLOCATION & AFTER TRANSPLANT TO DETECT ORGAN REJECTION & MYOCARDIAL VIABILITY. PEDIATRIC INDICATIONS INCLUDE EVALUATION FOR VSD & CONGENITAL HEART DISEASE & POSTSURGICAL EVALUATION OF CONGENITAL HEART DISEASE.\r\nTHALLIUM-201 IS A PHYSIOLOGIC ANALOGUE OF POTASSIUM. THE MYOCARDIAL CELLS EXTRACT POTASSIUM, AS DO OTHER MUSCLE CELLS. THE TC-99 IS TAKEN UPBY THE MYOCARDIUM THROUGH PASSIVE DIFFUSION, FOLLOWED BY ACTIVE UPTAKE WITHIN THE MITOCHONDRIA. UNLIKE THALLIUM, TECNETIUM DOES NOT UNDERGO SIGNIFICANT REDISTRIBUTION. THEREFORE, THERE ARE SOME PROCEDURAL DIFFERENCES. MYOCARDIAL ACTIVITY ALSO DEPENDS ON BLOOD FLOW . CONSEQUENTLY , WHEN THE PATIENT IS INJECTED DURING PEAK EXERCISE, THE NORMAL MYOCARDIUM HAS MUCH GREATER ACTIVITY THAN THE ABNORMAL MYOCARDIUM. COLD SPOTS INDICATE A DECREASE OR ABSENCE OF FLOW.\r\nADMINISTRATION OF DIPYRAMIDOLE OR ADENOSINE IS INDICATED IN ADULTS & CHILDREN WHO ARE UNABLE TO EXERCISE TO ACHIEVE THE DESIRED CARDIAC STRESS LEVELS & MAXIMUM CARDIAC VASODILATION. THIS MEDICATION HAS AN EFFECT SIMILAR TO THAT OF EXERCISE ON THE HEART. PHYSICAL STRESS TESTING MAY BE INITIATED IN CHILDREN BEGINING AT 4 - 5 YRS. CANDIDATES FOR DRUG INDUCED STRESS TESTING ARE THOSE WITH LUNG DISEASE , PERIPHERAL VASCULAR DISEASE WITH CLAUDICATION, AMPUTATION , SPINAL DISEASE OR INJURY, MULTIPLE SCLEROSIS OR MORBID OBESITY. DIPYRAMIDOLE STRESS TESTING IS ALSO VALUABLE AS A SIGNIFICANT PREDICTOR OF CARDIOVASCULAR DEATH , REINFARCTION & RISK FOR POSTOPERATIVE ISCHAEMIA & TO REVALUATE UNSTABLE ANGINA.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('457', 'MYOCARDIAL INFARCTION SCAN ( PYP )', '0', '0', 'TC- 99 PYROPHOSPHATE IS THE RADIOACTIVE IMAGING AGENT USED TO DEMONSTRATE THE GENERAL LOCATION , SIZE & EXTENT OF MYOCARDIAL INFACTION 24 TO 96 HRS AFTER SUSPECTED INFARCTION & AS AN INDICATION OF MYOCARDIAL NECROSIS, TO DIFFERENTIATEBETWEEN OLD & NEW INFARCS. IN SOME INSTANCES THE TEST IS SENSITIVE ENOUGH TO DETECT AN INFARCTION 12 HRS TO 7 DAYS AFTER ITS OCCURRENCE. ACUTE INFARCTION IS ASSOCIATED WITH AN AREA OF INCREASED RADIO ACTIVITY ( HOT SPOT ) ON THE MYOCARDIAL IMAGE. THE TEST IS USEFUL WHEN ECG & ENZYME STUDIES ARE NOT DEFINITE.', '2', '', '0', '0', '2', '0', '0', 'NORMAL DISTRIBUTION OF RADIO ACTIVE MATERIAL IN STERNUM , RIBS & OTHER BONE STRUCTURES . NO MYOCARDIAL UPTAKE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('514', 'ARTERIAL BLOOD GASES TEST', '0', '0', 'Measurements of arterial blood gases ( ABGs ) are obtained to assess adequacy of oxygenation & ventilation, to evaluate acid-base status by measuring the respiratory & nonrespiratory  components, and to monitor effectiveness of therapy. They are also used to monitor critically ill patients, lo establish baseline values in the perioperative and postoperative period, to detect and treat electrolyte imbalances, to titrate appropriate oxygen flow rates, to qualify a patient for use of oxygen at home and in conjunction with pulmonary function testing. Reasons for using arterial rather than venous blood lo measure blood gases include the following:\r\n1.   Arterial blood provides a better way to sample a mixture of blood from various parts of the body.\r\na.  Venous blood from an extremity gives information mostly about that extremity.  The metabolism in the extremity can differ from the metabolism in the body as a whole. This difference is accentuated in the following instances:\r\n( I ) In shock states, when the extremity is cold or underperfused\r\n(2) During local exercise of the extremity, as in opening and closing a list\r\n(3) If the extremity is infected\r\nb.  Blood from a central venous catheter usually is an incomplete mix of venous blood from various parts of the body. For a sample lo be completely mixed, the blood would have to be obtained from the right ventricle or pulmonary artery.\r\n2.  Arterial blood measurements indicate how well the lungs are oxygenating blood.\r\na.  If it is known that the arterial 02 concentration is normal (indicating that the lungs are functioning normally) hut the mixed venous 02 concentration is low. it can he inferred that the heart and circulation are failing.\r\nb.  Oxygen measurements of central venous catheter blood reveal tissue oxygenation hut do not separate contributions of the heart from those of the lungs. If central venous catheter blood has a low 02 concentration, it means either that the lungs have not oxygenated the arterial blood well or that the heart is not circulating the blood effectively. In the latter case, the body tissues must take on more than the normal amount of 0, from each cardiac cycle because the blood is flowing slowly and permits this lo occur: this produces a low venous 02 concentration.\r\n3.  Arterial samples provide information about the ability of the lungs to regulate acid-base balance through retention or release of CO2. Effectiveness of the kidneys in maintaining appropriate bicarbonate levels also can be gauged. The radial artry is usually the site of choice\r\n', '4', '', '0', '0', '0', '0', '0', 'NORMAL VALUES FOR COMMON ARTERIAL BLOOD GASES\r\n       ADULT                                   PEDIATRIC             \r\nPHA - 7.35 - 7.45                            7.32 - 7.42\r\nPACO2 - 35 - 45 MM HG                30 - 40 MM HG\r\nPAO2    - > 80 MM HG                    80 - 100 MM HG\r\nSAO2    - > 94 %\r\nCO2 CONTENT - 45 - 51 VOL%\r\nO2 CONTENT    - 15 - 22 VOL %\r\nBASE EXCESS   - > 2 MEQ / L\r\nBASE DEFICIT    - < -2 MEQ / L\r\nHCO3                  - 22 - 26 MEQ / L', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('535', 'HCV-RNA , QUANTITATIVE', '0', '0', 'THIS TEST CAN FIND GENETIC MATERIAL ( RNA ) UNIQUE TO THE HEPATITIS-C VIRUS. IT CAN BE DETECTED IN THE BLOOD 1-2 WEEKS AFTER EXPOSURE TO THE VIRUS. TWO TYPES OF HCV RNA TESTS ARE AVAILABLE :\r\n* QUALITATIVE TEST\r\n* QUANTITATIVE : THIS TEST IS DONE TO ESTIMATE THE NUMBER OF HCV PARTICLES IN THE BLOOD ( VIRAL LOAD ) & IT MAY PREDICT HOW LIKELY IS THE PATIENT TO RESPOND TO TREATMENT. DURING THE COARSE OF ANTIVIRAL DRUG TREATMENT, IF THE REPEAT TESTS SHOW DECREASING LEVELS OF HVC-RNA IN THE BLOOD, IT CONFIRMS THE EFFECTIVENESS OF ONGOING TREATMENT. A HIGH LEVEL OF VIRAL LOAD IN THE BLOOD MAY MEAN LESS LIKELY HOOD TO RESPOND TO TREATMENT.', '4', '', '0', '0', '0', '0', '0', 'POSITIVE IN HEPATITIS C VIRUS DISEASE : HIGH VIRAL LOAD IS DEFINED AS > 2 MILLION COPIES OF THE VIRUS / ML\r\n\r\n* FALSE NEGATIVE TEST RESULTS ARE ALSO POSIBLE.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('536', 'HCV-RNA , GENOTYPING', '0', '0', 'THIS TEST IS USED MOST OFTEN TO DETERMINE WHETHER ONE HAS AN ACTIVE HEPATITIS-C DISEASE OR NOT. THIS IS IMPORTANT TO KNOW IF YOU ARE CONSIDERING TREATMENT FOR LONG-TERM( CHRONIC ) HEPATITIS C DISEASE. THE TEST ALSO MAY BE DONE TO CONFIRM A POSITIVE RESULT ON AN HCV ANTIBODY TEST ( SUCH AS ENZYME IMMUNOASSAY OR EIA ).', '2', '', '0', '0', '2', '0', '0', '* POSITIVE IN HEPATITIS-C DISEASE\r\n\r\n* IN RARE CASES ANTIBODIES AGAINST HEPATITIS-C VIRUS NEVER DEVELOP, SO TESTING FOR HCV ANTIBODIES CANT ALWAYS BE USED AS DIAGNOSTIC. IN THESE CASES, THE HCV-RNA TEST IS THE ONLY WAY TO TELL WHETHER YOU HAVE AN ACTIVE INFECTION.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('550', 'SERUM CALCITONIN ( THYROCALCITONIN )', '0', '0', '.', '1', 'pg / ml', '0', '19', '0', '0', '0', 'INCREASED : MEDULLARY CARCINOMA OF THYROID, C-CELL HYPERPLASIA, SMALL CELL CARCINOMA OF LUNG, NEWBORNS, PREGNANCY, CHR RENAL INSUFFICIENCY, ZOLLINGER-ELLISON SYNDROME, PERNICIOUS ANEMIA', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('555', 'SERUM BICARBONATE', '0', '0', '.', '1', 'mmol/L', '23', '29', '0', '0', '0', 'INCREASED : COMPENSATION FOR RESPIRATORY ACIDOSIS( EMPHYSEMA ) & METABOLIC ALKALOSIS ( SEVERE VOMITING, PRIMARY ALDOSTERONISM, VOLUME CONTRACTION, BARTTER SYNDROME).\r\n\r\nDECREASED : COMPENSATION FOR RESPIRATORY ALKALOSIS & METABOLIC ACIDOSIS ( STARVATION, DIABETIC KETOACIDOSIS, LACTIC ACIDOSIS, ALCOHOLIC KETOACIDOSIS, TOXINS LIKE METHANOL, ETHYLENE GLYCOL, PARALDEHYDE, THEN SEVERE DIARRHOEA, RENAL FAILURE, DRUGS LIKE SALICYLATES, ACETAZOLAMIDE, DEHYDRATION, ADRENAL INSUFFICIENCY.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('575', 'SESTAMIBI SCAN', '0', '0', 'Sestamibi Scan of the Parathyroid gland is a Nuclear Medicine procedure which is performed to identify hyperparathyroidism (or parathyroid adenoma). Sestamibi is a Nuclear Radiopharmaceutical which is bound to the radioactive isotope Tc99m. Tc99m-Sestamibi is taken up by both the thyroid gland and the parathyroid gland, and is also used in Nuclear Myocardial Perfusion Imaging. \r\nThe general principal in the procedure is that the Tc99m-Sestamibi will absorb at a greater rate in a hyperfunctioning parathyroid gland than in a normal parathyroid gland. By using a Gamma Camera in Nuclear Medicine, the radiologist is able to determine if one of the four parathyroid glands is hyperfunctioning. The hyperfunctioning parathyroid gland will take up more of the Tc99m-Sestamibi, and will show up \'brighter\' than the other glands on the gamma camera pictures. Sometimes this determination must be made three or four hours later when activity taken up by the thyroid gland fades away, while the parathyroid gland retains it\'s activity. \r\n                            By knowing which of the four parathyroid glands is hyperfunctioning, a surgeon is able to remove only the one parathyroid gland that is working too fast, and leave the other 3 glands in place. The remaining 3 glands are able to properly regulate the body even without the missing fourth gland. \r\n', '4', '', '0', '0', '0', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('587', 'TB GOLD TEST', '0', '0', 'A REVOLUTIONARY TEST FOR DIAGNOSIS OF ACTIVE TUBERCULOSIS. CAN DETECT LATENT TUBERCULOSIS ALSO.THE TEST DETECTS INTERFERON GAMMA PRODUCED BY SENSITIZED T4 CELLS. THE TEST USES ESAT-6 & CFP-10 ANTIGENS. HIGHLY SENSITIVE ( 90% ) & SPECIFIC ( 98% ). THE TEST IS UNAFFECTED BY BCG VACCINATION OR NON TUBERCULAR MYCOBACTERIUM INFECTION. SITE SPECIFIC SAMPLE IS NOT MANDATORY & IS BETTER ALTERNATIVE TO BLOOD PCR. SINGLE TEST IS CONCLUSIVE. \r\nIT IS IMPORTANT TO EVALUATE LATENT TUBERCULOSIS IN FOLLOWING CASES :\r\n* IMMUNOCOMPROMISED INDIVIDUALS LIKE HIV POSITIVE, PATIENTS ON CHEMOTHERAPY, IMMUNOSUPPRESSIVE MEDICINES, INCLUDING TNF-? ANTAGONISTS.\r\n* INDIVIDUALS WITH RISK FACTORS FOR TB REACTIVATION LIKE PATIENTS WITH DIABETES, CHR RENAL FAILURE, RENAL DIALYSIS, SILICOSIS, MALNUTRITION.\r\n* INJECTION DRUG USER\r\n* ORGAN TRANSPLANT RECIPIENTS ( BEFORE TRANSPLANT )\r\n* EXPECTANT MTHERS WITH H/O THREATENED ABORTIONS\r\n* STAFF MEMBERS OF TB SURVEILLANCE PROGRAMS, HEALTH CARE WORKERS.', '1', 'IU/ML', '0', '0.35', '0', '0', '0', '0.35 OR ABOVE 0.35 IU/ML IS POSITIVE', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('588', 'TB RNA DETECTION BY TMA METHOD', '0', '0', 'TRANSCRIPTION MEDIATED AMPLIFICATION METHOD IS IMPROVED PCR, WHICH IS THE ONLY US-FDA APPROVED RNA DETECTION SYSTEM. TEST IS SPECIFIC FOR MYCOBACTERIUM TUBERCULOSIS & DETECTS LIVE BACILLI ONLY. IT IS HIGHLY SENSITIVE ( 93.3% ) & SPECIFIC ( 99.1% ).', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('589', 'TB DNA DETECTION BY REAL TIME PCR', '0', '0', 'TEST IS SPECIFIC FOR MYCOBACTERIUM TUBERCULOSIS. THERE IS NO POSSIBILITY OF FALSE POSITIVE RESULTS DUE TO CONTAMINATION. THE TECHNIQUE IS BASED ON HYBRIDIZATION OF AMPLIFIED NUCLEIC ACIDS WITH FLUORESCENT-LABELED PROBES SPANNING DNA REGIONS OF INTEREST AND MONITORED INSIDE THERMAL CYCLERS. THE FLUORESCENT SIGNAL INCREASES IN DIRECT PROPORTION TO THE AMOUNT OF AMPLIFIED PRODUCT IN THE REACTION TUBE. THE SENSITIVITY RANGE FROM 71 - 98% WITH SPECIFICITY CLOSE TO 100%. THE SENSITIVITY OF THE TEST IS AFFECTED BY THE IRREGULAR DISTRIBUTION OF BACILLI IN THE CLINICAL SAMPLES LOWERING INITIAL VOLUME OF DNA PRESENT. THE MAIN ADVANTAGE IS ITS SPEED IN GIVING RESULTS ( 1.5 2 HRS AFTER DNA EXTRACTION) & THE DECREASE IN THE RISK OF CONTAMINATION SINCE BOTH REACTION & DETECTION OCCURS IN A SINGLE TUBE.', '2', '', '0', '0', '2', '0', '0', 'POSITIVE : M. TUBERCULOSIS', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('590', 'AMLICOR MTB TEST', '0', '0', 'THE TEST DIFFERENTIATE BETWEEN MYCOBACTERIUM TUBERCULOSIS & MYCOBACTERIUM SPECIES OTHER THAN TUBERCULOSIS. IT IS AN NUCLEIC ACID AMPLIFICATION TEST WHICH AMPLIFY TARGET NUCLEIC ACID REGIONS THAT UNIQUELY IDENTIFY M. TUBERCULOSIS COMPLEX. BECAUSE NUCLEIC ACID AMPLIFICATION ( NAA ) TESTS CAN BE DIRECTLY USED ON CLINICAL SPECIMENS LIKE SPUTUM THEY ARE ALSO CALLED AS DIRECT AMPLIFICATION TESTS. IT IS A DNA-BASED TEST THAT AMPLIFIES THE 16 S RNA GENE USING GENUS SPECIFIC PRIMERS WITH DETECTION IN A COLORIMETRIC REACTION.', '2', '', '0', '0', '2', '0', '0', 'POSITIVE : M. TUBERCULOSIS', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('591', 'MYCOBACTERIUM DETECTION BY RAPID CULTURE METHOD', '0', '0', 'VERSATRACK METHOD HAS PROVEN TRACK RECORD OF FASTER DETECTION COMPARED TO BACTEC & HAS CONTINUOUS MONITORING SYSTEM WHICH CHECKS GROWTH EVERY 10 MTS. THE METHOD USES MYCOBACTERIA GROWTH INDICATOR TUBE SYSTEM.\r\nTHERE ARE TWO METHODS USED FOR RAPID CULTURE\r\n\r\n1. MYCOBACTERIA GROWTH INDICATOR TUBE METHOD\r\n2. TK MEDIUM\r\nMYCOBACTERIA GROWTH INDICATOR TUBE SYSTEM IS BASED ON A GLASS TUBE CONTAINING A MODIFIED MIDDLEBROOK 7H9 BROTH TOGATHER WITH A FLUORESCENCE QUENCHING-BASED OXYGEN SENSOR EMBEDDED AT THE BOTTOM OF THE TUBE. WHEN INOCULATED WITH M. TUBERCULOSIS, CONSUMPTION OF THE DISSOLVED OXYGEN PRODUCES FLUORESCENCE WHEN ILLUMINATED BY A UV LAMP. IT ALLOWS FOR THE GOOD GROWTH OF MOST OF MYCOBACTERIAL SPECIES.\r\nRECENTLY MGIT SYSTEM HAS BEEN FULLY AUTOMATED WHICH IS A NON-RADIOMETRIC, NONINVASIVE WITH THE TUBES INCUBATED IN A COMPACT SYSTEM THAT READS THEM AUTOMATICALLY.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('599', 'ANTI-CYCLIC CITRULLINATED PEPTIDE ( ANTI-CCP )', '0', '0', 'THESE CYCLIC SYNTHETIC PEPTIDES, NOT RELATED TO FILAGGRIN OR OTHER KNOWN PROTEINS, WHICH ARE SPECIALLY RECOGNISED BY AUTO ANTIBODIES IN THE SERA OF RHEUMATOID PATIENT. THESE ARE ANTI-CCP FOUND IN RELATION TO JOINT INVOLVEMENT WITH RADIOLOGICAL DAMAGE IN EARLY RHEUMATOID ARTHRITIS. THE TEST IS SUPERIOR TO OTHER AVAILABLE TESTS.', '1', 'units/ml', '0', '25', '0', '0', '0', 'NEGATIVE : < 25 UNITS/ML\r\nWEAKLY POSITIVE - 25 - 50 UNITS/ML\r\nPOSITIVE -         >50 UNITS/ML', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('600', 'T SPOT-TB TEST', '0', '0', 'IT IS AN ELISA TEST ( BASED ON RD1 ANTIGENS ) WHICH USES PERIPHERAL BLOOD MONONUCLEAR CELLS AND ENZYME LINKED IMMUNOSPOT TECHNOLOGY. IT IS MUCH MORE SENSITIVE TEST THAN TUBERCULIN SKIN TEST BUT CAN NOT EASILY DISTINGUISH BETWEEN LATENT INFECTION & ACTIVE DISEASE.', '2', '', '0', '0', '2', '0', '0', 'POSITIVE IN ACTIVE & LATENT TUBERCULOSIS.', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('603', 'DENGUE NS1 ANTIGEN', '0', '0', 'DENGUE NS1 ANTIGEN IS A NONSTRUCTURAL PROTEIN THAT IS PRODUCED IN ALL PATIENTS INFECTED BY THE DENGUE VIRUS. IT IS EXPRESSED ON THE SURFACE OF INFECTED CELLS AND SECRETED INTO THE BLOOD STREAM OF THE INDIVIDUAL. IT CERCULATED AT HIGH LEVELS IN THE PATIENTS EXPERIENCING PRIMARY AS WELL AS SECONDARY INFECTIONS DURING THE ENTIRE CLINICAL PAHSE OF INEFCTION & IN THE FIRST FEW DAYS OF CONVALESCENCE.\r\nTHE ANTIGEN IS DETECTABLE ON THE VERY FIRST DAY THAT SYMPTOMS APPEAR AND CAN BE DETECTED UNTIL DAY 9.', '2', '', '0', '0', '2', '0', '0', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
