INSERT INTO `ipd_discharge_master_food` (`id`, `food_short`, `food_desc`, `food_desc_lang`) VALUES
('11', 'DIET AS ADVICE', 'DIET AS ADVICE', NULL),
('12', 'Eat Nutritious diet,Stay away from smoking and alcohol altogether.', 'Eat Nutritious diet,Stay away from smoking and alcohol altogether.', 'पौष्टिक आहार लें, धूम्रपान और शराब से पूरी तरह दूर रहें।'),
('13', 'Use appropriate medicine as Prescribed.', 'Use appropriate medicine as Prescribed.', 'निर्धारित अनुसार उचित दवा का उपयोग करें।'),
('14', 'Hydration', 'Drink at least 8–10 glasses of water daily unless restricted by your doctor.', 'जब तक कि आपके डॉक्टर द्वारा प्रतिबंधित न किया गया हो, प्रतिदिन कम से कम 8-10 गिलास पानी पिएं।'),
('15', 'Balanced Meals', 'Incorporate a mix of carbohydrates, proteins, and healthy fats in every meal.', 'प्रत्येक भोजन में कार्बोहाइड्रेट, प्रोटीन और स्वस्थ वसा का मिश्रण शामिल करें।'),
('16', 'Fruits and Vegetables', 'Consume a variety of fresh fruits and vegetables daily to ensure adequate vitamins and minerals.', 'पर्याप्त विटामिन और खनिज सुनिश्चित करने के लिए प्रतिदिन विभिन्न प्रकार के ताजे फल और सब्जियों का सेवन करें।'),
('17', 'Small, Frequent Meals', 'Eat smaller portions 5–6 times a day instead of three large meals to avoid overburdening the digestive system.', 'पाचन तंत्र पर अधिक बोझ से बचने के लिए तीन बार अधिक भोजन करने के बजाय दिन में 5-6 बार छोटी मात्रा में भोजन करें।'),
('18', 'Avoid Processed Foods', 'Limit intake of sugary, salty, and fried foods. Avoid packaged snacks and beverages high in preservatives.', 'मीठे, नमकीन और तले हुए खाद्य पदार्थों का सेवन सीमित करें। डिब्बाबंद स्नैक्स और ज़्यादा प्रिज़र्वेटिव वाले पेय पदार्थों से बचें।'),
('19', 'Special Considerations', 'If you have specific conditions like diabetes, hypertension, or kidney issues, follow the dietary restrictions advised by your healthcare provider. For post-surgical recovery, include protein-rich foods like eggs, lentils, and dairy products to promote healing.', 'यदि आपको मधुमेह, उच्च रक्तचाप या किडनी संबंधी समस्या जैसी कोई विशेष समस्या है, तो अपने स्वास्थ्य सेवा प्रदाता द्वारा बताए गए आहार प्रतिबंधों का पालन करें। सर्जरी के बाद ठीक होने के लिए, उपचार को बढ़ावा देने के लिए अंडे, दाल और डेयरी उत्पादों जैसे प्रोटीन युक्त खाद्य पदार्थों को शामिल करें।'),
('20', 'Supplements', 'Take any prescribed vitamins or supplements as directed by your doctor.', 'अपने चिकित्सक द्वारा निर्देशित कोई भी निर्धारित विटामिन या पूरक लें।'),
('21', 'Food Safety', 'Ensure all meals are freshly prepared and hygienically cooked. Avoid raw or undercooked foods to reduce the risk of infections.', 'सुनिश्चित करें कि सभी भोजन ताज़ा तैयार किए गए हों और स्वच्छतापूर्वक पकाए गए हों। संक्रमण के जोखिम को कम करने के लिए कच्चे या अधपके खाद्य पदार्थों से बचें।');
