INSERT INTO `ipd_discharge_templates` (`id`, `template_name`, `page_size`, `custom_width_mm`, `custom_height_mm`, `page_margin_top_cm`, `page_margin_bottom_cm`, `page_margin_left_cm`, `page_margin_right_cm`, `margin_header_cm`, `margin_footer_cm`, `header_html`, `footer_html`, `template_css`, `template_html`, `is_default`, `is_audit_only`, `is_abdm`, `watermark_type`, `watermark_text`, `watermark_image`, `watermark_alpha`, `status`, `created_at`, `updated_at`) VALUES
('1', 'Default Discharge Template', 'A4', '210', '297', '5.00', '2.00', '0.80', '0.80', '1.00', '0.50', '<table cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"vertical-align:top; width:120px\"><img src=\"{{H_logo_abs}}\" style=\"width:100px\" /></td>\r\n			<td style=\"text-align:left; vertical-align:top; width:400px\">\r\n			<p>{{H_Name}}</p>\r\n\r\n			<p>{{hospital_address}}<br />\r\n			Phone: {{H_phone_No}}</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', '<table align=\"center\" border=\"0\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">Signature of Consultant</td>\r\n			<td style=\"text-align:center\">Signature of Receiver / Date</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 'body {\r\n    font-family: Verdana, Geneva, Tahoma, sans-serif;font-size: 12px;\r\n}\r\n\r\np {\r\n  line-height: 1.2;\r\npadding: 0px;\r\nmargin-top: 2px;    \r\n  margin-bottom: 5px;  \r\n}\r\n\r\n\r\n/* Default: no borders */\r\ntable {\r\n    border-collapse: collapse;\r\n    border: none !important;\r\nmargin-top: 1px;\r\nfont-size: 12px;\r\npadding: 1px;\r\n}\r\ntable td, table th {\r\n    border: none !important;\r\nmargin-top: 1px;\r\nfont-size: 12px;\r\n}\r\n\r\n/* Section Headings */\r\n.discharge-section-heading {\r\n    margin: 5px 0 8px 0;\r\n    font-size: 14px;\r\n    font-weight: bold;\r\n}\r\n.discharge-title {\r\n    text-align: center;\r\n    margin: 10px 0;\r\n    font-size: 18px;\r\n}\r\n\r\n/* Lists */\r\n.discharge-list { margin: 0 0 10px 20px; }\r\n.discharge-sublist { margin: 4px 0 8px 20px; }\r\n\r\n/* Text */\r\n.discharge-remark { color: #475569; font-style: italic; }\r\n\r\n/* Tables */\r\n.discharge-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    margin: 4px 0 8px 0;\r\n}\r\n.discharge-table th,\r\n.discharge-table td {\r\n    border: 1px solid #ccc !important; /* light gray */\r\nfont-size: 12px;\r\n}\r\n\r\n.discharge-medicine-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    margin-bottom: 5px;\r\nfont-size: 12px;\r\n\r\n}\r\n.discharge-medicine-table th,\r\n.discharge-medicine-table td {\r\n    border: 1px inset #aaa !important; /* slightly darker gray for inset look */\r\nfont-size: 12px;\r\n}\r\n\r\n.discharge-signature-table {\r\n    width: 100%;\r\n    text-align: center;\r\n}\r\n\r\n/* Separators */\r\n.discharge-separator {\r\n    margin: 1px 0;\r\n    padding: 0;\r\n    border-top: 1px solid #000;\r\n}\r\n\r\n', '<p>{{DISCHARGE_STATUS}}</p>\r\n\r\n<table align=\"left\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>Patient Name</td>\r\n			<td>{{PATIENT_NAME}}</td>\r\n			<td>UHID / Patient ID</td>\r\n			<td>{{UHID}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Guardian</td>\r\n			<td>{{GUARDIAN_RELATION}}&nbsp;&nbsp;{{GUARDIAN_NAME}}</td>\r\n			<td>IPD No.</td>\r\n			<td>{{IPD_CODE}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Age / Gender</td>\r\n			<td>{{AGE_GENDER}}</td>\r\n			<td>Admission Date</td>\r\n			<td>{{ADMIT_DATE}}&nbsp;{{ADMISSION_TIME}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Address</td>\r\n			<td>{{PATIENT_ADDRESS}}</td>\r\n			<td>Discharge Date</td>\r\n			<td>{{DISCHARGE_DATE}}&nbsp;{{DISCHARGE_TIME}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Phone No.</td>\r\n			<td>{{PATIENT_PHONE}}</td>\r\n			<td>TPA</td>\r\n			<td>{{INSURANCE_COMPANY}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Department&nbsp;</td>\r\n			<td>{{DEPARTMENT}}</td>\r\n			<td>Doctors</td>\r\n			<td>{{DOCTOR_NAMES}}</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><br />\r\n{{FINAL_DIAGNOSIS}}{{SURGERY}}{{PROCEDURE}}{{PRESENTING_COMPLAINTS}}{{GENERAL_EXAM_ADMISSION}}{{PERSONAL_HISTORY}}{{CLINICAL_INVESTIGATION_REPORTS}}{{COURSE_IN_HOSPITAL}}{{EXAMINATION_ON_DISCHARGE}}{{DISCHARGE_MEDICATIONS}}To Continue the other medication if any systmic condition like hypertension , diabetic etc, as per adivised by treating physician\r\n{{DIETARY_ADVICE}}\r\n{{DISCHARGE_ADVICE}}\r\n{{OTHER_ADVICE}}\r\n{{DISCHARGE_SUMMARY}}{{REVIEW_AFTER}}</p>\r\n\r\n<p>&nbsp;</p>', '1', '0', '1', 'none', 'Confidential', '', '0.10', '1', NULL, NULL),
('4', 'NABH Compliant Discharge Summary', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '<h2 style=\"margin:0 0 10px 0;text-align:center;\">DISCHARGE SUMMARY</h2><table style=\"width:100%;border-collapse:collapse;margin-bottom:10px;\" border=\"1\" cellpadding=\"6\"><tr><td><b>Patient Name</b>: {{PATIENT_NAME}}</td><td><b>UHID</b>: {{UHID}}</td><td><b>IPD No.</b>: {{IPD_CODE}}</td></tr><tr><td><b>Age/Gender</b>: {{AGE_GENDER}}</td><td><b>Date of Admission</b>: {{ADMIT_DATE}}</td><td><b>Date of Discharge</b>: {{DISCHARGE_DATE}}</td></tr><tr><td colspan=\"3\"><b>Prepared On</b>: {{CURRENT_DATE}}</td></tr></table><div style=\"font-size:11px;color:#334155;margin-bottom:10px;\">NABH guidance note: Ensure diagnosis, procedures, clinical course, condition at discharge, medication with dose/duration, follow-up advice, red-flag signs, and emergency contact are documented.</div><div style=\"margin-bottom:10px;\">{{CONTENT}}</div><h4 style=\"margin:12px 0 6px 0;\">Counselling & Handover Confirmation</h4><table style=\"width:100%;border-collapse:collapse;margin-bottom:10px;\" border=\"1\" cellpadding=\"6\"><tr><td style=\"width:32%;\">Medication explained to patient/attendant</td><td style=\"width:8%;\"></td><td style=\"width:60%;\">Remarks:</td></tr><tr><td>Follow-up date and department explained</td><td></td><td>Next Visit: __________________</td></tr><tr><td>Red-flag symptoms explained</td><td></td><td>Emergency Contact: __________________</td></tr><tr><td>Diet and activity instructions explained</td><td></td><td></td></tr></table><table style=\"width:100%;border-collapse:collapse;margin-top:20px;\" border=\"1\" cellpadding=\"10\"><tr><td style=\"width:33%;vertical-align:bottom;\">____________________<br>Consultant Name/Signature</td><td style=\"width:33%;vertical-align:bottom;\">____________________<br>Medical Officer Signature</td><td style=\"width:34%;vertical-align:bottom;\">____________________<br>Patient/Attendant Signature & Date</td></tr></table>', '0', '1', '0', 'none', NULL, NULL, '0.12', '1', NULL, NULL),
('5', 'Discharge Template Sharing', 'A4', '210', '297', '3.00', '0.80', '0.80', '0.80', '0.50', '0.50', '<table cellspacing=\"0\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"vertical-align:top; width:120px\"><img src=\"{{H_logo_abs}}\" style=\"width:100px\" /></td>\r\n			<td style=\"text-align:left; vertical-align:top; width:400px\">\r\n			<p>{{H_Name}}</p>\r\n\r\n			<p>{{hospital_address}}<br />\r\n			Phone: {{H_phone_No}}</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', '<table align=\"center\" border=\"0\" cellpadding=\"1\" cellspacing=\"1\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n			<td style=\"text-align:center\">&nbsp;</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"text-align:center\">Signature of Consultant</td>\r\n			<td style=\"text-align:center\">Signature of Receiver / Date</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n', 'body {\r\n    font-family: Verdana, Geneva, Tahoma, sans-serif;font-size: 12px;\r\n}\r\n\r\np {\r\n  line-height: 1.2;\r\npadding: 0px;\r\nmargin-top: 2px;    \r\n  margin-bottom: 5px;  \r\n}\r\n\r\n\r\n/* Default: no borders */\r\ntable {\r\n    border-collapse: collapse;\r\n    border: none !important;\r\nmargin-top: 1px;\r\nfont-size: 12px;\r\npadding: 1px;\r\n}\r\ntable td, table th {\r\n    border: none !important;\r\nmargin-top: 1px;\r\nfont-size: 12px;\r\n}\r\n\r\n/* Section Headings */\r\n.discharge-section-heading {\r\n    margin: 5px 0 8px 0;\r\n    font-size: 14px;\r\n    font-weight: bold;\r\n}\r\n.discharge-title {\r\n    text-align: center;\r\n    margin: 10px 0;\r\n    font-size: 18px;\r\n}\r\n\r\n/* Lists */\r\n.discharge-list { margin: 0 0 10px 20px; }\r\n.discharge-sublist { margin: 4px 0 8px 20px; }\r\n\r\n/* Text */\r\n.discharge-remark { color: #475569; font-style: italic; }\r\n\r\n/* Tables */\r\n.discharge-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    margin: 4px 0 8px 0;\r\n}\r\n.discharge-table th,\r\n.discharge-table td {\r\n    border: 1px solid #ccc !important; /* light gray */\r\nfont-size: 12px;\r\n}\r\n\r\n.discharge-medicine-table {\r\n    width: 100%;\r\n    border-collapse: collapse;\r\n    margin-bottom: 5px;\r\nfont-size: 12px;\r\n\r\n}\r\n.discharge-medicine-table th,\r\n.discharge-medicine-table td {\r\n    border: 1px inset #aaa !important; /* slightly darker gray for inset look */\r\nfont-size: 12px;\r\n}\r\n\r\n.discharge-signature-table {\r\n    width: 100%;\r\n    text-align: center;\r\n}\r\n\r\n/* Separators */\r\n.discharge-separator {\r\n    margin: 1px 0;\r\n    padding: 0;\r\n    border-top: 1px solid #000;\r\n}\r\n\r\n', '<p>{{DISCHARGE_STATUS}}</p>\r\n\r\n<table align=\"left\" border=\"0\" cellpadding=\"5\" cellspacing=\"5\" style=\"width:100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td>Patient Name</td>\r\n			<td>{{PATIENT_NAME}}</td>\r\n			<td>UHID / Patient ID</td>\r\n			<td>{{UHID}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Guardian</td>\r\n			<td>{{GUARDIAN_RELATION}}&nbsp;&nbsp;{{GUARDIAN_NAME}}</td>\r\n			<td>IPD No.</td>\r\n			<td>{{IPD_CODE}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Age / Gender</td>\r\n			<td>{{AGE_GENDER}}</td>\r\n			<td>Admission Date</td>\r\n			<td>{{ADMIT_DATE}}&nbsp;{{ADMISSION_TIME}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Address</td>\r\n			<td>{{PATIENT_ADDRESS}}</td>\r\n			<td>Discharge Date</td>\r\n			<td>{{DISCHARGE_DATE}}&nbsp;{{DISCHARGE_TIME}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Phone No.</td>\r\n			<td>{{PATIENT_PHONE}}</td>\r\n			<td>TPA</td>\r\n			<td>{{INSURANCE_COMPANY}}</td>\r\n		</tr>\r\n		<tr>\r\n			<td>Department&nbsp;</td>\r\n			<td>{{DEPARTMENT}}</td>\r\n			<td>Doctors</td>\r\n			<td>{{DOCTOR_NAMES}}</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><br />\r\n{{FINAL_DIAGNOSIS}}{{SURGERY}}{{PROCEDURE}}{{PRESENTING_COMPLAINTS}}{{GENERAL_EXAM_ADMISSION}}{{PERSONAL_HISTORY}}{{CLINICAL_INVESTIGATION_REPORTS}}{{COURSE_IN_HOSPITAL}}{{EXAMINATION_ON_DISCHARGE}}{{DISCHARGE_MEDICATIONS}}To Continue the other medication if any systmic condition like hypertension , diabetic etc, as per adivised by treating physician{{DIETARY_ADVICE}}{{DISCHARGE_ADVICE}}{{OTHER_ADVICE}}{{DISCHARGE_SUMMARY}}{{REVIEW_AFTER}}</p>\r\n\r\n<p>&nbsp;</p>', '0', '0', '0', 'none', '', '', '0.12', '1', NULL, NULL),
('6', 'Day Care Discharge Summary', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '{{DAYCARE_HEADER}}<table class=\"discharge-info-table\" border=\"1\" cellpadding=\"6\" style=\"width:100%; border-collapse:collapse; margin-bottom:12px;\"><tr><td><b>Patient Name</b>: {{PATIENT_NAME}}</td><td><b>UHID</b>: {{UHID}}</td><td><b>Day Care No.</b>: {{IPD_CODE}}</td></tr><tr><td><b>Age / Gender</b>: {{AGE_GENDER}}</td><td><b>Guardian</b>: {{GUARDIAN_RELATION}}{{GUARDIAN_NAME}}</td><td><b>Phone</b>: {{PATIENT_MOBILE}}</td></tr><tr><td><b>Admission</b>: {{ADMIT_DATE}}</td><td><b>Discharge</b>: {{DISCHARGE_DATE}}</td><td><b>Attending Doctor</b>: {{DOCTOR_NAMES}}</td></tr></table><div>{{PRESENTING_COMPLAINTS}}</div><div>{{FINAL_DIAGNOSIS}}</div><div>{{PROCEDURE}}</div><div>{{SURGERY}}</div><div>{{PADSS_SCORE}}</div><div>{{COURSE_IN_HOSPITAL}}</div><div>{{DISCHARGE_MEDICATIONS}}</div><div>{{RED_FLAGS_WARNINGS}}</div><div>{{DIETARY_ADVICE}}</div><div>{{REVIEW_AFTER}}</div>', '0', '0', '0', 'none', NULL, NULL, '0.12', '1', '2026-09-21 22:19:40', NULL);
INSERT INTO `ipd_document_templates` (`id`, `form_no`, `template_name`, `page_size`, `custom_width_mm`, `custom_height_mm`, `page_margin_top_cm`, `page_margin_bottom_cm`, `page_margin_left_cm`, `page_margin_right_cm`, `margin_header_cm`, `margin_footer_cm`, `header_html`, `footer_html`, `template_css`, `template_html`, `status`, `created_at`, `updated_at`) VALUES
('1', '1', 'Legacy Face Form (IPD2)', 'A4', '210', '297', '6.00', '0.80', '0.80', '0.80', '0.50', '0.50', '<table style=\"font-size: 14px;width:100%;\" autosize=\"1\" >\n<tr>\n	<td style=\"vertical-align: top;\">\n                <img style=\"width: 75px;vertical-align: top;\" src=\"{{H_logo_abs}}\" />\n        </td>\n        <td style=\"vertical-align: top;text-align:center;\">\n            <p style=\"font-size: 22px;text-align:left;\" >{{HOSPITAL_NAME}}</p>\n            <p  style=\"font-size: 12px;text-align:left;\" >{{HOSPITAL_ADDRESS}}</p>\n        </td>\n        <td style=\"vertical-align: top;;text-align:right;\" >\n        <barcode code=\"{{qr_content}}\" size=\"0.8\" type=\"QR\" error=\"M\" class=\"barcode\" />\n        </td>\n</tr>\n</table>\n	<h3 align=\"center\">BED HEAD TICKET</h3>\n<table  cellspacing=\"5\"  style=\"font-size: 12px;width:100%;border-style: none;\" autosize=\"1\" >	\n<tr>\n      <td style=\"vertical-align: top;\">\n         <b>Patient Information :</b><br/>\n         <strong>Patient Name :</strong>{{PATIENT_NAME}} {{pName}}<br>\n         <b>Age / Gender :</b>{{AGE_GENDER}}<br><br>\n         <b>Phone No : </b>{{phoneno}}\n       </td>\n       <td align=\"Left\" style=\"vertical-align: top;\">\n         <b>UHID :</b> {{UHID}}<br><br>\n         <b>IPD Code :</b> {{IPD_CODE}}<br><br>\n         <b>Insurance :</b> {{INSURANCE_NAME}}<br>\n         <strong>Date And Time of Admission :</strong> {{ADMIT_DATE}}<br/><br/>\n\n         <b>Doctors : </b> : {{DOCTORS}}\n      </td>\n</tr>\n</table>', '', '<style>@page {\n        margin-top: 4.2cm;\n        margin-bottom: 1.2cm;\n        margin-left: 1cm;\n        margin-right: 0.5cm;\n        \n        margin-header:0.5cm;\n        margin-footer:0.5cm;\n        header: html_myHeader;\n        footer: html_myFooter;\n}\n</style>\n', '<h3>सहमति पत्र</h3>\n\n<p>मैं ईलाज कराने का/की इक्छुक हूँ | मैं {{HOSPITAL_NAME}} के चिकित्सक और उनके सहायको को अपना उपचार , परीक्षण, परामर्श, जाँच, औषधि देने , चिकित्सा बेहोशी की दवा लगवाने की स्वीकृति देता हूँ | मुझे मेरी /मेरे मरीज की बीमारी के बारे मे उसके खतरों से जटिलताओं (complications ) से अवगत करा दिया गया है | मुझे ईलाज मे होने वाले खर्च की जानकारी दे दी गई है एवं मै इलाज में आने वाले खर्चो के भुगतान को वहन करने की सहमति प्रदान&nbsp;करता&nbsp;हूँ | मैंने अपनी सभी शंकाओं का निवारण कर लिया है । इस स्वीक्रति पत्र को मैंने ठीक प्रकार से पड़कर स्वयं समझकर हस्ताक्षर के द्वारा अपनी सहमति प्रदान करता / करती हूँ ।</p>\n\n<p>&nbsp;</p>\n\n<table cellspacing=\"0\" style=\"width:100%\">\n	<tbody>\n		<tr>\n			<td>&nbsp;</td>\n			<td>&nbsp;</td>\n			<td><br />\n			<br />\n			<br />\n			<br />\n			<br />\n			<br />\n			हस्ताक्षर / अंगूठा निशान<br />\n			<br />\n			<br />\n			<br />\n			नाम : _______________________________________________<br />\n			<br />\n			<br />\n			मरीज / मरीज से संबंध : _____________________________<br />\n			<br />\n			<br />\n			पता : _______________________________________________<br />\n			<br />\n			<br />\n			<br />\n			फ़ोन नंबर : _________________________________________</td>\n		</tr>\n	</tbody>\n</table>\n\n<p>&nbsp;</p>\n', '1', '2026-03-24 04:22:36', '2026-04-08 10:24:17'),
('2', '3', 'Legacy Self Declaration (IPD2)', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '<div style=\"font-size:12px;line-height:1.35;\">\r\n  <h3 style=\"text-align:center;margin:0 0 10px 0;\">SELF DECLARATION FROM HEALTH INSURANCE CARD HOLDER</h3>\r\n  <h3 style=\"text-align:center;margin:0 0 10px 0;\">मेडिक्लेम बीमा कार्ड धारक द्वारा स्वघोषणा</h3>\r\n\r\n  <table border=\"1\" cellpadding=\"6\" cellspacing=\"0\" style=\"width:100%;border-collapse:collapse;\">\r\n    <tr>\r\n      <td><b>Patient Name:</b> {{PATIENT_NAME}}</td>\r\n      <td><b>UHID:</b> {{UHID}}</td>\r\n      <td><b>IPD:</b> {{IPD_CODE}}</td>\r\n    </tr>\r\n    <tr>\r\n      <td><b>Age/Gender:</b> {{AGE_GENDER}}</td>\r\n      <td><b>Admission:</b> {{ADMIT_DATE}}</td>\r\n      <td><b>Insurance:</b> {{INSURANCE_NAME}}</td>\r\n    </tr>\r\n  </table>\r\n\r\n  <p style=\"margin-top:12px;\">\r\n    मैं __________________________ यह घोषणा करता/करती हूँ कि मरीज {{PATIENT_NAME}} का मेडिक्लेम {{INSURANCE_NAME}} में है,\r\n    और भर्ती दिनांक {{ADMIT_DATE}} को हुई है। मैंने आवश्यक दस्तावेज जमा कर दिए हैं और यदि क्लेम पूर्ण/आंशिक स्वीकृत नहीं होता\r\n    है तो शेष देय राशि का भुगतान स्वयं करूँगा/करूँगी।\r\n  </p>\r\n\r\n  <p>हस्ताक्षर / अंगूठा निशान: __________________________</p>\r\n  <p>नाम: __________________________ &nbsp;&nbsp; मरीज से संबंध: __________________________</p>\r\n  <p>पता: __________________________ &nbsp;&nbsp; फ़ोन नंबर: __________________________</p>\r\n  <p>दिनांक: {{CURRENT_DATE}}</p>\r\n</div>', '1', '2026-03-24 04:22:36', '2026-03-24 04:22:36'),
('3', '5', 'Legacy Admission History & Physical Assessment', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '<div style=\"font-size:11px;line-height:1.3;\">\r\n  <h3 style=\"text-align:center;margin:0 0 8px 0;\">ADMISSION HISTORY AND PHYSICAL ASSESSMENT FORM</h3>\r\n  <p><b>Patient:</b> {{PATIENT_NAME}} &nbsp; <b>Age/Gender:</b> {{AGE_GENDER}} &nbsp; <b>UHID:</b> {{UHID}} &nbsp; <b>IPD:</b> {{IPD_CODE}} &nbsp; <b>Admit Date:</b> {{ADMIT_DATE}}</p>\r\n  <p><b>Diagnosis:</b> ______________________________________________</p>\r\n  <p><b>Time of Patient Arrival:</b> ____________ &nbsp;&nbsp; <b>Time of Doctor Assessment:</b> ____________</p>\r\n  <p><b>Consciousness:</b> [ ] Awake [ ] Alert [ ] In pain [ ] Response to verbal commands [ ] Unresponsive</p>\r\n  <p><b>GCS:</b> E___ V___ M___ &nbsp;&nbsp; <b>Airway/Breathing:</b> [ ] Clear [ ] Noisy [ ] Stridor [ ] Obstruction</p>\r\n  <p><b>Allergic To:</b> ______________________________________________</p>\r\n  <p><b>Present Complaints:</b></p>\r\n  <div style=\"border:1px solid #666;height:52px;\"></div>\r\n\r\n  <p style=\"margin-top:8px;\"><b>Past Medical History:</b></p>\r\n  <table border=\"1\" cellpadding=\"4\" cellspacing=\"0\" style=\"width:100%;border-collapse:collapse;\">\r\n    <tr><td style=\"width:25%;\">Diabetes / Metabolic</td><td style=\"width:25%;\"></td><td style=\"width:25%;\">Jaundice / CLD</td><td style=\"width:25%;\"></td></tr>\r\n    <tr><td>Hypertension / IHD</td><td></td><td>Osteoarthritis</td><td></td></tr>\r\n    <tr><td>Asthma / COPD / TB</td><td></td><td>Tuberculosis</td><td></td></tr>\r\n    <tr><td colspan=\"4\">Others:</td></tr>\r\n  </table>\r\n\r\n  <p><b>Drug History:</b></p>\r\n  <div style=\"border:1px solid #666;height:42px;\"></div>\r\n  <p><b>Past Surgical History:</b></p>\r\n  <div style=\"border:1px solid #666;height:42px;\"></div>\r\n\r\n  <p><b>Declaration:</b> I hereby declare that the facts recorded above are accurate to the best of my knowledge.</p>\r\n  <p>Name of Patient/Relative: ________________________ &nbsp; Signature: ________________________</p>\r\n  <p>Date: {{CURRENT_DATE}}</p>\r\n</div>', '1', '2026-03-24 04:22:36', '2026-03-24 04:22:36'),
('4', '8', 'Legacy Progress Notes and Doctor Order', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '<div style=\"font-size:11px;line-height:1.3;\">\r\n  <h3 style=\"text-align:center;margin:0 0 8px 0;\">PROGRESS NOTES AND DOCTOR\'S ORDER</h3>\r\n  <p><b>Name:</b> {{PATIENT_NAME}} &nbsp; <b>IPD:</b> {{IPD_CODE}} &nbsp; <b>UHID:</b> {{UHID}} &nbsp; <b>Age/Gender:</b> {{AGE_GENDER}}</p>\r\n  <hr>\r\n  <table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" style=\"width:100%;border-collapse:collapse;\">\r\n    <tr>\r\n      <th style=\"width:18%;text-align:center;\">DATE</th>\r\n      <th style=\"text-align:center;\">PROGRESS NOTES AND DOCTOR\'S ORDER</th>\r\n    </tr>\r\n    <tr>\r\n      <td style=\"height:420px;\"></td>\r\n      <td></td>\r\n    </tr>\r\n  </table>\r\n</div>', '1', '2026-03-24 04:22:36', '2026-03-24 04:22:36'),
('5', '9', 'Legacy Oral / Enteral Intake Output Chart', 'A4', '210', '297', '0.80', '0.80', '0.80', '0.80', '0.50', '0.50', NULL, NULL, NULL, '<div style=\"font-size:11px;line-height:1.25;\">\r\n  <h3 style=\"text-align:center;margin:0 0 8px 0;\">ORAL / ENTERAL INTAKE & OUTPUT CHART</h3>\r\n  <p><b>Name:</b> {{PATIENT_NAME}} &nbsp; <b>IPD:</b> {{IPD_CODE}} &nbsp; <b>UHID:</b> {{UHID}} &nbsp; <b>Age/Gender:</b> {{AGE_GENDER}}</p>\r\n  <hr>\r\n  <table border=\"1\" cellpadding=\"4\" cellspacing=\"0\" style=\"width:100%;border-collapse:collapse;\">\r\n    <tr>\r\n      <th style=\"width:6%;\">SR.No.</th>\r\n      <th style=\"width:10%;\">Date</th>\r\n      <th style=\"width:8%;\">Time</th>\r\n      <th style=\"width:17%;\">Description</th>\r\n      <th style=\"width:7%;\">Vol.</th>\r\n      <th style=\"width:7%;\">Vol.</th>\r\n      <th style=\"width:7%;\">Total</th>\r\n      <th style=\"width:7%;\">Urine</th>\r\n      <th style=\"width:7%;\">Stool</th>\r\n      <th style=\"width:7%;\">Other</th>\r\n      <th style=\"width:7%;\">Other</th>\r\n      <th style=\"width:7%;\">Other</th>\r\n      <th style=\"width:7%;\">Total</th>\r\n    </tr>\r\n    <tr><td>1</td><td style=\"height:24px;\"></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n    <tr><td>2</td><td style=\"height:24px;\"></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n    <tr><td>3</td><td style=\"height:24px;\"></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n    <tr><td>4</td><td style=\"height:24px;\"></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n    <tr><td>5</td><td style=\"height:24px;\"></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>\r\n  </table>\r\n</div>', '1', '2026-03-24 04:22:36', '2