INSERT INTO `opd_clinical_templates` (`id`, `doc_id`, `section_key`, `template_name`, `template_text`, `is_active`, `created_at`, `updated_at`) VALUES
('1', '0', 'finding_examinations', 'General OPD Exam - Stable', 'Patient conscious, oriented, cooperative. Vitals stable. No pallor/icterus/cyanosis/clubbing/edema. CVS S1S2 normal, RS clear bilaterally, P/A soft non-tender, CNS NAD.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('2', '0', 'finding_examinations', 'Fever Exam - Mild Viral Pattern', 'Temp mildly elevated, pulse regular, BP stable. Throat mild congestion, chest clear, no focal neurological deficit, no neck rigidity. Hydration fair.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('3', '0', 'finding_examinations', 'GI Symptom Exam - Non Acute', 'Afebrile, hemodynamically stable. Mild epigastric tenderness, no guarding/rigidity, bowel sounds present. No hepatosplenomegaly.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('4', '0', 'diagnosis', 'Acute URI - Uncomplicated', 'Acute upper respiratory tract infection (uncomplicated).', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('5', '0', 'diagnosis', 'Acid Peptic Disorder', 'Acid peptic disease / gastritis without alarm features.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('6', '0', 'diagnosis', 'Acute Febrile Illness', 'Acute febrile illness, likely viral etiology; monitor for warning signs.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('7', '0', 'provisional_diagnosis', 'Provisional - Viral Fever', 'Provisional diagnosis: Viral fever. Differential: early bacterial infection if fever persists >72 hours.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('8', '0', 'provisional_diagnosis', 'Provisional - Dyspepsia', 'Provisional diagnosis: Dyspepsia / gastritis. Differential: GERD, peptic ulcer disease.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('9', '0', 'provisional_diagnosis', 'Provisional - Hypertension Follow-up', 'Provisional diagnosis: Essential hypertension on follow-up; control status to be assessed with home BP chart.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('10', '0', 'prescriber_remarks', 'Standard Safety Net Advice', 'Counseled regarding hydration, medication compliance, and red-flag symptoms. If persistent high fever, breathlessness, chest pain, altered sensorium, or repeated vomiting, report immediately.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('11', '0', 'prescriber_remarks', 'Antibiotic Stewardship Remark', 'Antibiotic use explained with dose, duration, and adherence importance. Do not self-stop medication early. Report adverse effects promptly.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('12', '0', 'prescriber_remarks', 'Chronic Disease Counseling', 'Lifestyle counseling done: diet moderation, salt restriction, regular physical activity, sleep hygiene, and follow-up adherence.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('13', '0', 'advice', 'Fever Home Care Advice', 'Adequate oral fluids, light diet, tepid sponging if required, rest. Maintain temperature chart. Review if fever not improving in 2-3 days or if warning signs appear.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('14', '0', 'advice', 'Gastritis Diet Advice', 'Avoid spicy/oily food, tea/coffee excess, tobacco, and alcohol. Small frequent meals. Early dinner and avoid lying down immediately after meals.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05'),
('15', '0', 'advice', 'Hypertension Follow-up Advice', 'Continue prescribed medicines regularly. Monitor BP at home and maintain log. Low-salt diet, regular walk, stress reduction. Follow-up in 2-4 weeks with BP chart.', '1', '2026-02-22 19:20:05', '2026-02-22 19:20:05');
