, \"timing\": {\"repeat\": {\"period\": 1, \"frequency\": 1, \"periodUnit\": \"d\"}}, \"doseAndRate\": [{\"doseQuantity\": {\"code\": \"mg\", \"unit\": \"mg\", \"value\": 75, \"system\": \"http://unitsofmeasure.org\"}}]}], \"medicationCodeableConcept\": {\"text\": \"Aspirin 75mg (Ecosprin)\", \"coding\": [{\"code\": \"387458008\", \"system\": \"http://snomed.info/sct\", \"display\": \"Aspirin\"}]}}}, {\"fullUrl\": \"urn:uuid:medication-request-ds-03\", \"resource\": {\"id\": \"medication-request-ds-03\", \"meta\": {\"profile\": [\"https://nrces.in/ndhm/fhir/r4/StructureDefinition/MedicationRequest\"]}, \"intent\": \"order\", \"status\": \"active\", \"subject\": {\"reference\": \"urn:uuid:patient-ds-01\"}, \"encounter\": {\"reference\": \"urn:uuid:encounter-ds-01\"}, \"requester\": {\"reference\": \"urn:uuid:practitioner-ds-01\"}, \"authoredOn\": \"2026-03-14T14:00:00+05:30\", \"resourceType\": \"MedicationRequest\", \"dosageInstruction\": [{\"text\": \"Take 1 tablet at bedtime\", \"route\": {\"coding\": [{\"code\": \"26643006\", \"system\": \"http://snomed.info/sct\", \"display\": \"Oral route\"}]}, \"timing\": {\"repeat\": {\"when\": [\"HS\"], \"period\": 1, \"frequency\": 1, \"periodUnit\": \"d\"}}, \"doseAndRate\": [{\"doseQuantity\": {\"code\": \"mg\", \"unit\": \"mg\", \"value\": 40, \"system\": \"http://unitsofmeasure.org\"}}]}], \"medicationCodeableConcept\": {\"text\": \"Atorvastatin 40mg\", \"coding\": [{\"code\": \"376988009\", \"system\": \"http://snomed.info/sct\", \"display\": \"Atorvastatin\"}]}}}, {\"fullUrl\": \"urn:uuid:care-plan-ds-01\", \"resource\": {\"id\": \"care-plan-ds-01\", \"note\": [{\"text\": \"Dietary advice: Low salt (<5g/day), low fat diet. Avoid smoking and alcohol. Take all medications regularly. Report immediately if chest pain, breathlessness, or palpitations recur. Keep follow-up appointments without fail.\"}], \"title\": \"Post-PCI Cardiac Rehabilitation and Follow-Up Plan\", \"author\": {\"reference\": \"urn:uuid:practitioner-ds-01\"}, \"intent\": \"plan\", \"period\": {\"end\": \"2026-09-14\", \"start\": \"2026-03-14\"}, \"status\": \"active\", \"subject\": {\"reference\": \"urn:uuid:patient-ds-01\"}, \"activity\": [{\"detail\": {\"code\": {\"coding\": [{\"code\": \"390906007\", \"system\": \"http://snomed.info/sct\", \"display\": \"Follow-up encounter\"}]}, \"kind\": \"Appointment\", \"status\": \"scheduled\", \"description\": \"First follow-up visit — 1 week post discharge. Wound check, ECG, vitals.\", \"scheduledPeriod\": {\"end\": \"2026-03-21\", \"start\": \"2026-03-21\"}}}, {\"detail\": {\"code\": {\"coding\": [{\"code\": \"390906007\", \"system\": \"http://snomed.info/sct\", \"display\": \"Follow-up encounter\"}]}, \"kind\": \"Appointment\", \"status\": \"scheduled\", \"description\": \"Second follow-up — 1 month post discharge. 2D Echo, lipid profile, CBC.\", \"scheduledPeriod\": {\"end\": \"2026-04-14\", \"start\": \"2026-04-14\"}}}, {\"detail\": {\"code\": {\"coding\": [{\"code\": \"229065009\", \"system\": \"http://snomed.info/sct\", \"display\": \"Exercise therapy\"}]}, \"kind\": \"ServiceRequest\", \"status\": \"scheduled\", \"description\": \"Cardiac rehabilitation program: Start supervised walking 10-15 min daily. Gradually increase to 30-45 min over 6 weeks. Avoid heavy lifting (>5 kg) for 4 weeks.\"}}], \"category\": [{\"coding\": [{\"code\": \"736271009\", \"system\": \"http://snomed.info/sct\", \"display\": \"Outpatient care plan\"}]}], \"encounter\": {\"reference\": \"urn:uuid:encounter-ds-01\"}, \"description\": \"Post-STEMI discharge plan including cardiac rehabilitation, medication compliance, and lifestyle modifications\", \"resourceType\": \"CarePlan\"}}], \"timestamp\": \"2026-03-14T16:00:00+05:30\", \"identifier\": {\"value\": \"f7e8d9c0-b1a2-3456-7890-abcdef012345\", \"system\": \"https://nirmitee.io/bundle-ids\"}, \"resourceType\": \"Bundle\"}', '2026-09-05 02:19:06', '2026-09-05 02:19:06', '2033-09-05', 'ACTIVE'),
