INSERT INTO `radiology_ultrasound_template` (`id`, `template_name`, `keywords`, `title`, `Modality`, `charge_id`, `Findings`, `Impression`, `impression_cat`) VALUES
('1', 'USG LOWER ABDOMEN', NULL, 'USG LOWER ABDOMEN', '1', '12', '<p><strong>BOTH KIDNEYS</strong> are normal in size , shape and position.The corticomedullary diffrentiation is well preserved. No hydronephrosis or calculus or mass lesion seen in the kidneys&nbsp; Ureters show no dilatation in the visualized part.</p>\n\n<p><strong>URINARY BLADDER : </strong>Normal&nbsp; in distention with regular outline and normal wall thickness.No luminal calculus / mass lesion seen Mucosal trabeculations are normal.</p>\n\n<p><strong>Uterus </strong>is normal in size and correspond with the size of nulliparous / multiparous /postmenopausal size of&nbsp; uterus and is anteverted / retroverted .Echopattern and contour of the uterus is normal .Endometrial thickness is&nbsp; &hellip;&hellip;&nbsp; mm</p>\n\n<p>Both adnexa are sonographically normal.No solid or cystic mass lesion /collection noted in the adenexa .Cervix is sonographically normal.No / small amount of free fluid is seen in culdesac.</p>\n\n<p>&nbsp;</p>\n', 'Sonographic  findings suggest : Normal study for abovementioned organs / structures .', '0'),
('2', 'USG WHOLE ABDOMEN-Women', NULL, 'USG WHOLE ABDOMEN', '1', '8', '<p><strong>LIVER :&nbsp;</strong>is normal in size measuring 12 cms&nbsp;&nbsp;and shows homogenous &nbsp;echotexture of parenchyma.No focal lesion is seen.No intrahepatic biliary radicles dilatation is seen.Hepatic veins and IVC are een normally..</p>\n\n<p><strong>GALLBLADDER :&nbsp;</strong>is distended and shows anechoic lumen. No calculus&nbsp;is seen in the lumen of gallbladder.Wallthickness of the gallbladder is normal.</p>\n\n<p><strong>C.B.D</strong>. :is normal in size at porta .No obstructive lesion is seen.fggfhghghjjj</p>\n\n<p><strong>PANCREAS :&nbsp;&nbsp;</strong>is normal in size and shows homogenous echotexture&nbsp;of parenchyma.PD is not dilated.No parenchymal lesion is seen.No pancreatic collection is seen.</p>\n\n<p><strong>SPLEEN :</strong>&nbsp;is normal in size and measuring 11.5 cms and shows homogenous echotexture&nbsp;of parenchyma..No wellformed local lesion is seen.</p>\n\n<p><strong>KIDNEYS : </strong>Both kidneys are normal in size and position.Both shows normal parenchymal echotexture. are normal in size ,The corticomedullary diffrentiation is well preserved. No hydronephrosis is seen.No&nbsp;calculus is seen.Right kidney measures 85 x 35 mm and left kidney measures 96 x 36 mm in size.</p>\n\n<p><strong>BOTH URETERS :</strong>&nbsp; are not dilated.Both UVJ&nbsp; are seen normally..</p>\n\n<p>No retroperitoneal adenopathy is seen.No ascitis is seen.</p>\n\n<p><strong>URINARY BLADDER</strong> : is distended&nbsp;&nbsp;with regular outline and shows&nbsp; anechoic lumen..UB &nbsp;wall thickness is normal..No &nbsp;calculus or&nbsp;mass lesion seen .</p>\n\n<p><strong>UTERUS : </strong>measure&nbsp;&nbsp;6.0&nbsp; cm x 3.0&nbsp; cm&nbsp; x 3.0 cm&nbsp; in size&nbsp;&nbsp;and is anteverted in it&rsquo;s position .Echopattern and contour of the uterus is normal .Endometrial thickness is 9.6 mm.</p>\n\n<p><strong>ADNEXA :</strong> Both adnexa are sonographically normal.No solid or cystic mass lesion or collection noted in the adenexa</p>\n\n<p>Cervix is sonographically normal.No&nbsp; free fluid is seen in culdesac.</p>\n\n<p>&nbsp;</p>\n', 'Sonographic  findings suggest : Normal study for abovementioned organs / structures .', '0'),
('3', 'USG WHOLE ABDOMEN-Men', NULL, 'USG WHOLE ABDOMEN', '1', '8', '<p><strong>LIVER :&nbsp;</strong>is normal in size measuring 12 cms&nbsp;&nbsp;and shows homogenous &nbsp;echotexture of parenchyma.No focal lesion is seen.No intrahepatic biliary radicles dilatation is seen.Hepatic veins and IVC are een normally..</p>\n\n<p><strong>GALLBLADDER :&nbsp;</strong>is distended and shows anechoic lumen. No calculus&nbsp;is seen in the lumen of gallbladder.Wallthickness of the gallbladder is normal.</p>\n\n<p><strong>C.B.D</strong>. :is normal in size at porta .No obstructive lesion is seen.</p>\n\n<p><strong>PANCREAS :&nbsp;&nbsp;</strong>is normal in size and shows homogenous echotexture&nbsp;of parenchyma.PD is not dilated.No parenchymal lesion is seen.No pancreatic collection is seen.</p>\n\n<p><strong>SPLEEN :</strong>&nbsp;is normal in size and measuring 11.5 cms and shows homogenous echotexture&nbsp;of parenchyma..No wellformed local lesion is seen.</p>\n\n<p><strong>KIDNEYS : </strong>Both kidneys are normal in size and position.Both shows normal parenchymal echotexture. are normal in size ,The corticomedullary diffrentiation is well preserved. No hydronephrosis is seen.No&nbsp;calculus is seen.Right kidney measures 85 x 35 mm and left kidney measures 96 x 36 mm in size.</p>\n\n<p><strong>BOTH URETERS :</strong>&nbsp; are not dilated.Both UVJ&nbsp; are seen normally..</p>\n\n<p>No retroperitoneal adenopathy is seen.No ascitis is seen.</p>\n\n<p><strong>URINARY BLADDER</strong> : is distended&nbsp;&nbsp;with regular outline and shows&nbsp; anechoic lumen..UB &nbsp;wall thickness is normal..No &nbsp;calculus or&nbsp;mass lesion seen .</p>\n\n<p><strong>PROSTATE&nbsp; </strong>appears as a soft echogenic region posterior to urinary bladder and caudad to the seminal vesicles.Prostate is normal in size .It&rsquo;s capsule is regular and&nbsp; margins are welldefined .</p>\n\n<p>&nbsp;</p>\n', 'Sonographic findings suggest:Normal study for above mentioned organs / structures.', '0'),
('4', 'W A Female after cholecystectomy', NULL, 'USG WHOLE  ABDOMEN', '1', '8', '<p><strong>LIVER </strong>is normal in size and shape. The general outline is regular and the contour appears normal.The parenchymal echotexture is homogenous and smooth.The biliary radicles and vascular channels appear normal in their caliber.</p>\n\n<p><strong>GALLBLADDER </strong>couldnot be profiled as history of cholicystectomy done about 14 years&nbsp; back is given by patient.</p>\n\n<p><strong>C.B.D.</strong> is normal in it&rsquo;s course and caliber.</p>\n\n<p><strong>PANCREAS &amp; Spleen</strong> are sonographically normal.</p>\n\n<p><strong>BOTH KIDNEYS</strong> are normal in size and position.The corticomedullary diffrentiation is well preserved. No hydronephrosis or calculus or mass lesion seen in the kidneys&nbsp; Ureters show no dilatation in the visualized part.</p>\n\n<p><strong>URINARY BLADDER :</strong> Normal&nbsp; in distention with regular outline and normal wall thickness.No luminal calculus / mass lesion seen Mucosal trabeculations are normal.</p>\n\n<p>No free fluid is seen in the abdomen.</p>\n\n<p><strong>Uterus</strong> is normal in size and measure 6.4 cm x 3.4 cm X 3.2 cm and is anteverted in&nbsp; its&nbsp; position&nbsp;&nbsp; Echopattern&nbsp; and contour of the&nbsp; uterus is normal.Endometrial thickness is 05 mm.</p>\n\n<p>Left adenexa is sonographically normal.No solid or cystic mass seen in adenaxa. Right ovary could not be profiled.</p>\n\n<p>Cervix is sonographically normal.Culdesac&nbsp; is&nbsp; normal . Small amount of&nbsp;&nbsp; free&nbsp; fluid&nbsp; is&nbsp; seen in it.</p>\n', 'Sonographic  findings suggest : USG finding are suggestive of normal study ( cholicystectomy done about 14 years back )\nADVICE : C T Scan  Abdomen for further exploration of the case', '0'),
('5', 'WA MALE APPENDICULAR LUMP', NULL, 'USG WHOLE ABDOMEN', '1', '8', '<p><strong>LIVER :&nbsp;</strong>is normal in size measuring 12 cms&nbsp;&nbsp;and shows homogenous &nbsp;echotexture of parenchyma.No focal lesion is seen.No intrahepatic biliary radicles dilatation is seen.Hepatic veins and IVC are een normally..</p>\n\n<p><strong>GALLBLADDER :&nbsp;</strong>is distended and shows anechoic lumen. No calculus&nbsp;is seen in the lumen of gallbladder.Wallthickness of the gallbladder is normal.</p>\n\n<p><strong>C.B.D</strong>. :is normal in size at porta .No obstructive lesion is seen.</p>\n\n<p><strong>PANCREAS :&nbsp;&nbsp;</strong>is normal in size and shows homogenous echotexture&nbsp;of parenchyma.PD is not dilated.No parenchymal lesion is seen.No pancreatic collection is seen.</p>\n\n<p><strong>SPLEEN :</strong>&nbsp;is normal in size and measuring 11.5 cms and shows homogenous echotexture&nbsp;of parenchyma..No wellformed local lesion is seen.</p>\n\n<p><strong>KIDNEYS : </strong>Both kidneys are normal in size and position.Both shows normal parenchymal echotexture. are normal in size ,The corticomedullary diffrentiation is well preserved. No hydronephrosis is seen.No&nbsp;calculus is seen.Right kidney measures 85 x 35 mm and left kidney measures 96 x 36 mm in size.</p>\n\n<p><strong>BOTH URETERS :</strong>&nbsp; are not dilated.Both UVJ&nbsp; are seen normally..</p>\n\n<p>No retroperitoneal adenopathy is seen.No ascitis is seen.</p>\n\n<p><strong>URINARY BLADDER</strong> : is distended&nbsp;&nbsp;with regular outline and shows&nbsp; anechoic lumen..UB &nbsp;wall thickness is normal..No &nbsp;calculus or&nbsp;mass lesion seen .</p>\n\n<p>Appendicular lump is seen ( size 3.17 cm x 2.97 cm )</p>\n\n<p>&nbsp;</p>\n', 'Sonographic findings suggest: Appendicular Lump', '0'),
('6', 'WAF  after hysterectomy', NULL, 'USG FOR UPPER  ABDOMEN', '1', '13', '<p><strong>LIVER </strong>is normal in size and shape. The general outline is regular and the contour appears normal.The parenchymal echotexture is homogenous and smooth.The biliary radicles and vascular channels appear normal in their caliber.</p>\n\n<p><strong>GALLBLADDER </strong>is normal in size shape and position.Wallthickness of the gallbladder is normal.No calculi is seen in the lumen of gallbladder.</p>\n\n<p><strong>C.B.D.</strong> is normal in it&rsquo;s course and caliber.PANCREAS &amp; spleen are normal in size,shape and echopattern.</p>\n\n<p><strong>BOTH KIDNEYS</strong> are normal in size , shape and position.The corticomedullary diffrentiation is well preserved. No hydronephrosis or calculus or mass lesion seen in the kidneys&nbsp; Ureters show no dilatation in the visualized part.</p>\n\n<p>No free fluid is seen in the abdomen.</p>\n\n<p><strong>Urinary bladder :</strong> Normal&nbsp; in distention with regular outline and normal wall thickness.No luminal calculus / mass lesion is noted . Mucosal trabeculations are normal.</p>\n\n<p>Uterus couldnot be profiled (&nbsp; history of surgical removal of the uterus about 15 years back is given by patient )<br />\n&nbsp;<br />\nNo solid or cystic mass seen in the pelvic region during scanning.</p>\n', 'Sonographic  findings suggest normal study for abovementioned organs / structures.', '0'),
('7', 'WAF Fatty Liver', NULL, 'USG WHOLE  ABDOMEN', '1', '8', '<p><strong>LIVER </strong>is normal in size a.The general outline is regular and the contour appears normal.TEchogenecity of liver is increased .Intrahepatic&nbsp; biliary channels are not dilated..PV and hepatic veins are not dilated..</p>\n\n<p><strong>GALLBLADDER </strong>is normal in size shape and position.Wallthickness of the gallbladder is normal.No calculi is seen in the lumen of gallbladder.</p>\n\n<p><strong>C.B.D.</strong> is normal in it&rsquo;s course and caliber..</p>\n\n<p><strong>PANCREAS &amp; spleen</strong> are normal in size,shape and echopattern.</p>\n\n<p><strong>BOTH KIDNEYS</strong> are normal in size , shape and position.The corticomedullary diffrentiation is well preserved. No hydronephrosis or calculus or mass lesion seen in the kidneys&nbsp; Ureters show no dilatation in the visualized part.</p>\n\n<p><strong>Urinary bladder </strong>:No luminal calculus / mass lesion is noted . Mucosal trabeculations are normal.</p>\n\n<p><strong>Uterus </strong>is normal in size&nbsp; ( 6.8&nbsp; cm x 3.5&nbsp; cm&nbsp; x 3.4 cm ) and is anteverted in it&rsquo;s position .Echopattern and contour of the uterus is normal .Endometrial thickness is 06&nbsp; mm.</p>\n\n<p>Both adnexa are sonographically normal.No solid or cystic mass lesion /collection noted in the adenexa .Cervix is sonographically normal.No&nbsp; free fluid is seen in culdesac.</p>\n\n<p>&nbsp;</p>\n', 'Sonographic  findings suggest : Mild fatty Liver', '0'),
('8', 'missed abortion 6-7 weeks', NULL, 'USG ROUTINE', '1', '0', '<p>On examination uterus is prominent and normally oriented.In the uterine cavity there is evidence of a welldefined gestational sac .Mean gestational sac diameter corresponds to gestational age about 07 weeks 01 day +/- 04 days &nbsp;with no viable embryo or yolk sac in it Minimal amorphic luminal debris is seen.No cardiac activity is traceable.</p>\n\n<p>No adnexal &nbsp;mass lesion /collection or gestation noted.</p>\n\n<p>Culdesac &nbsp;is &nbsp;normal . No &nbsp;free &nbsp;fluid &nbsp;is &nbsp;seen.</p>\n\n<p><br />\n<strong>*NOTE:</strong>It is well documented that on abdominal sonography, the earliest detection of gestational sac can be made at approximately &nbsp;weeks and cardiac activity is seen &nbsp;in an embryo &nbsp;around 6-7 weeks.An absence of yolk sac / embryo in a gestational sac about 12 mm size and / or absence of cardiac activity in embryo beyond 7 weeks is associated with poor outcome/ missed abortion.Also it has &nbsp;been observed that in rare cases above sign of viability may not appear till quite late.So please correlate with clinical findings and other investigation and review after 10-15 days if clinically suggested.&nbsp;</p>\n\n<p><strong>DECLARATION</strong>:- &nbsp;I have neither detected nor disclosed the sex of foetus of pregnant woman to anybody in any manner .<br />\n&nbsp;</p>\n', '<p>U.S.G.findings suggests EARLY GESTATION WITH NO EMBRYO /YOLK SAC - missed abortion .</p>\n', '0'),
('9', 'MISSED ABORTION 9-10 weeks', NULL, 'USG ROUTINE OBS', '1', '3585', '<p>On examination uterus is prominent and normally oriented. A gestational sac is seen in the uterus with a small foetus iin the sac. But no cardiac pulsations or foetal body movements seen during scanning. Estimated gestational age is about &hellip;&hellip;&hellip;&hellip; weeks + - &hellip;&hellip;&hellip;&hellip;. days .</p>\n\n<p>No adnexal &nbsp;mass lesion /collection is noted.Culdesac &nbsp;is &nbsp;normal .</p>\n\n<p><strong>*NOTE:</strong>It is well documented that on abdominal sonography, the earliest detection of gestational sac can be made at approximately &nbsp;5 &ndash; 6 weeks and cardiac activity is seen &nbsp;in an embryo &nbsp;around 6 weeks. Absence of cardiac activity in embryo beyond 6 weeks is associated with poor outcome/ missed abortion.Also it has &nbsp;been observed that in rare cases above sign of viability may not appear till quite late.So please correlate with clinical findings and other investigation and review after 10-15 days if clinically suggested.&nbsp;</p>\n\n<p><strong>DECLARATION</strong>:- &nbsp;I have neither detected nor disclosed the sex of foetus of pregnant woman to anybody in any manner&nbsp;</p>\n', 'U.S.G.findings  suggests - missed abortion .', '0'),
('10', 'Left Renal Stone', NULL, 'Whole Abdomen', '1', '8', '<p><strong>LIVER</strong> is normal in size and shape. The general outline is regular and the contour appears normal.The parenchymal echotexture is homogenous and smooth.The biliary radicles and vascular channels appear normal in their caliber.</p>\n\n<p><strong>GALLBLADDER</strong> is normal in size shape and position.Wallthickness of the gallbladder is normal.No calculi is seen in the lumen of gallbladder.C.B.D. is normal in it&rsquo;s course and caliber.</p>\n\n<p><strong>PANCREAS &amp; spleen</strong> are normal in size,shape and echopattern.</p>\n\n<p><strong>LEFT &nbsp;KIDNEY</strong> is normal in size.Outline of the kidney is welldefined .Two small hyperechoic shadows measuring 4.0 mm &amp; 4.7 &nbsp;mm in their diameter &nbsp;are seen in the left kidney and casting it&rsquo;s &nbsp;distal acoustic shadowing . No hydronephrosis is also seen. Left ureter shows no dilatation in the visualized part</p>\n\n<p><strong>RIGHT KIDNEY</strong> is normal.Outline of the kidney are welldefined .Corticomedullary differentiation is well preserved.No hydronephrosis is seen in right &nbsp;kidney. Right ureter shows no dilatation in its visualized part.</p>\n\n<p><strong>URINARY BLADDER</strong> : Normal &nbsp;in distention with regular outline and normal wall thickness.No hyperechoic shadow is seen in the urinary bladder</p>\n\n<p><strong>NO</strong> &nbsp;free fluid is seen in the abdomen.</p>\n\n<p><br />\n&nbsp;</p>\n', 'Sonographic findings suggest : - Two    small hyperechoic shadows  in the left  kidney which is suggestive of ?? small left renal calculus\n\nADVICE : I.V.P. for confirmation of sonographic findings  ,final diagnosis and further exploration  of the case.\n', '0'),
('11', 'G.A  REPORT  36  WEEKS ', NULL, 'USG ROUTINE OBS', '1', '3585', '<p>*Single live &nbsp;foetus &nbsp;of 36 weeks 00 days +/-07 days ( mean gestational age based on various foetal growth parameters) is seen&nbsp;in longitudinal lie and cephalic presentation at the time of scanning .</p>\n\n<p>*Skull and visualized spine appears normal. No obvious craniospinal anomally is noted at the time of scanning .</p>\n\n<p>*Placenta is seen mainly&nbsp; anterior &amp; fundal with grade II maturity.Internal o.s. is closed . Retroplacental area is clear.The lower edge of the placenta is &nbsp;not reaching &nbsp; upto internal o.s..</p>\n\n<p>*Amniotic fluid is adequate and uniformally distributed&nbsp;( A.F.I. is&nbsp; &nbsp; &nbsp; &nbsp; cm ).Foetal movements noted at the time of scanning are normal.</p>\n\n<p>*Foetal heart rate is 140 &nbsp;beats /&nbsp;minute&nbsp; &nbsp;within normal range and is regular at the time of scanning.</p>\n\n<p>* Cervical length is adequate . Internal O.S.is closed.</p>\n\n<p>EDD (CUA) &nbsp; &nbsp;01-11-2024 &nbsp; &nbsp; &nbsp;EDD (LMP) 27-10-2024 &nbsp; &nbsp; EFW &ndash; 2825 &nbsp;Grams +/- 423 Grams</p>\n\n<p>This &nbsp;is &nbsp;a &nbsp;routine &nbsp;obstetric u / s examination &nbsp;mainly &nbsp;done for estimation of foetal age , general&nbsp;wellbeing, amount of liquor, &nbsp;placenta &nbsp;position &nbsp;etc and not for detailed evaluation of congenital&nbsp;anomalies &nbsp;. All the &nbsp; anomalies &nbsp;may &nbsp;not &nbsp;be &nbsp; appearent &nbsp; during &nbsp; single scanning. U/ S &nbsp;examination &nbsp; does &nbsp; not &nbsp; gurantee &nbsp; a &nbsp; normal &nbsp; baby.</p>\n\n<p>&nbsp;<br />\n<strong>ADVICE &nbsp;:-</strong> &nbsp;USG OBSTETRICS ( 3 D &ndash; 4D ) Level II &nbsp;Scan is recommended to detect the &nbsp;congenital abnormalities and detailed examination of the foetus.<br />\n<u><strong>DECLARATION :</strong></u>-I Dr Virendra Verma have examined this patient Smt Sheetal sonographically for foetal wellbeing &nbsp;I have neither detected nor disclosed the sex of foetus of pregnant woman to anybody in any manner&nbsp;<br />\n&nbsp;</p>\n', 'IMPRESSION : Single live foetus', '0'),
('12', 'BILATERAL URETRIC OBSTRUCTION', '', 'Whole Abdomen', '1', '0', '<p>LIVER is normal in size and shape. Intrahepatic blood vessels and biliary channels appear normal in caliber.No solid or cystic mass seen in the liver.<br />\nGALLBLADDER is normal in size shape and position.Wallthickness of the gallbladder is normal.No calculi is seen in the lumen of gallbladder.C.B.D. is normal in it&rsquo;s course and caliber.PANCREAS &amp; spleen are normal in size,shape and echopattern.<br />\nRIGHT KIDNEY &nbsp;is normal in size, shape and position.Mild hydronephrosis is seen in the right kidney. No calculus seen in right kidney. Mild hydroureter &nbsp;is also seen in the visible part of right ureter.No calculus is seen in the visible part of right ureter.<br />\nLEFT KIDNEY &nbsp;is normal in size, shape and position.Mild hydronephrosis is seen in the left kidney. No calculus is seen in the left kidney. Mild hydroureter &nbsp;is also seen in the visible part of left ureter.No calculus is seen in the visible part of right ureter.<br />\nUrinary bladder is normal.No mass or calculus is seen in the urinary bladder.No free fluid is seen in the abdomen.<br />\nUterus is normal in size and measure 6.4 cm x 3.4 cm x3.1 cm. &nbsp;Echotexture and contour of the uterus is normal and is anteverted &nbsp;in it&rsquo;s position. No focal lesion seen in the uterus .Endometrial thickness is 18 mm.&nbsp;<br />\nBoth adnexa are sonographically normal.No solid or cystic mass lesion /collection noted in the adenexa .Cervix is sonographically normal.Culdesac &nbsp;is &nbsp;normal . &nbsp;N0 &nbsp; free &nbsp;fluid &nbsp;is &nbsp;seen in it.<br />\nIMPRESSION : U.S.G.findings &nbsp; suggest :- Bilateral uretric obstruction &ndash; cause ? uretric calculus<br />\nADVICE : I.V.P &amp; other relevant investigations for confirmation of ultrasonographic findings , cause of the obstruction and further exploration &amp; management of the case .<br />\ns</p>\n', '', '0'),
('17', 'ctscan', NULL, 'ctscan', '4', '3887', '<p>test</p>\n', 'test', '0'),
('18', 'x-ray', NULL, 'test', '3', '2', '<p>test <strong>data</strong></p>\n', '<p><strong>test </strong>data</p>\n', '0'),
('19', '2D ECHO Cardiography', '', '2D and M-Mode Echocardiogram Report', '6', '3902', '<h2>Aortic Valve Level</h2>\n\n<table>\n	<tbody>\n		<tr>\n			<th>Parameter</th>\n			<th>Result</th>\n			<th>Normal</th>\n		</tr>\n		<tr>\n			<td>Aortic Root Diameter</td>\n			<td>&nbsp;</td>\n			<td>20&ndash;37 mm</td>\n		</tr>\n		<tr>\n			<td>Aortic Cusps Separation</td>\n			<td>&nbsp;</td>\n			<td>15&ndash;26 mm</td>\n		</tr>\n		<tr>\n			<td>Left Atrium</td>\n			<td>&nbsp;</td>\n			<td>20&ndash;40 mm</td>\n		</tr>\n	</tbody>\n</table>\n\n<h2>Right Ventricle (RV)</h2>\n\n<table>\n	<tbody>\n		<tr>\n			<th>Parameter</th>\n			<th>Result</th>\n			<th>Normal</th>\n		</tr>\n		<tr>\n			<td>Basal Diameter (A4C)</td>\n			<td>&nbsp;</td>\n			<td>24&ndash;42 mm</td>\n		</tr>\n		<tr>\n			<td>TAPSE</td>\n			<td>&nbsp;</td>\n			<td>&ge;17 mm</td>\n		</tr>\n	</tbody>\n</table>\n\n<h2>Left Ventricle</h2>\n\n<table>\n	<tbody>\n		<tr>\n			<th>Parameter</th>\n			<th>Result</th>\n			<th>Normal</th>\n		</tr>\n		<tr>\n			<td>IVSD</td>\n			<td>&nbsp;</td>\n			<td>6&ndash;11 mm</td>\n		</tr>\n		<tr>\n			<td>LVIDD</td>\n			<td>&nbsp;</td>\n			<td>35&ndash;57 mm</td>\n		</tr>\n		<tr>\n			<td>LVPWD</td>\n			<td>&nbsp;</td>\n			<td>6&ndash;11 mm</td>\n		</tr>\n		<tr>\n			<td>LVIDS</td>\n			<td>&nbsp;</td>\n			<td>25&ndash;41 mm</td>\n		</tr>\n		<tr>\n			<td>Ejection Fraction (Teicholz)</td>\n			<td>&nbsp;</td>\n			<td>&ge;55%</td>\n		</tr>\n	</tbody>\n</table>\n\n<h2>2-Dimensional Echocardiographic Observations</h2>\n\n<ul>\n	<li>Normal L.V. systolic function.</li>\n	<li>No regional wall motion abnormality detected.</li>\n	<li>Cardiac valves are morphologically normal.</li>\n	<li>No echo-dropout detected in IAS and IVS.</li>\n	<li>Cardiac chambers are not dilated.</li>\n	<li>No intracavitary clot/mass detected.</li>\n	<li>No pericardial effusion.</li>\n</ul>\n', '<p>Normal 2D and M-Mode Echocardiography.</p>\n', '0'),
('20', 'X-RAY CHEST PA VIEW (Normal)', 'chest, pa view, lungs, heart, normal, thorax, pulmonary, rib cage', 'X-Ray Chest PA View', '3', '3929', '<p><strong>TRACHEA & MEDIASTINUM :</strong> Trachea is central in position. Mediastinum shows normal configuration with no shift or widening.</p>\n<p><strong>CARDIAC SILHOUETTE :</strong> Heart size is within normal limits. Cardio-thoracic ratio (CTR) is less than 0.5. Aortic knuckle appears unremarkable.</p>\n<p><strong>LUNG PARENCHYMA :</strong> Both lung fields are clear with normal bronchovascular arborization. No focal parenchymal consolidation, mass, cavitation, or active infiltration seen.</p>\n<p><strong>HILAR REGIONS :</strong> Bilateral hilar shadows are normal in size, density, and configuration with no evidence of lymphadenopathy.</p>\n<p><strong>COSTOPHRENIC & CARDIOPHRENIC ANGLES :</strong> Both CP and cardiophrenic angles are acute, clear, and sharp. No evidence of pleural effusion or pleural thickening.</p>\n<p><strong>DIAPHRAGMS :</strong> Both domes of diaphragm are smooth, convex, and normal in position.</p>\n<p><strong>BONES & SOFT TISSUES :</strong> Visualized thoracic rib cage, clavicles, and soft tissues appear unremarkable. No focal bone erosion or fracture identified.</p>', 'Normal study of Chest (PA View). No active cardiopulmonary lesion detected.', '0'),
('21', 'X-RAY CHEST PA VIEW - Pneumonia / Consolidation', 'chest, pneumonia, consolidation, air bronchogram, fever, cough, opacity', 'X-Ray Chest PA View - Pneumonia', '3', '3929', '<p><strong>TRACHEA & MEDIASTINUM :</strong> Trachea is central with no significant mediastinal shift.</p>\n<p><strong>CARDIAC SILHOUETTE :</strong> Cardiac size is within normal limits for age.</p>\n<p><strong>LUNG PARENCHYMA :</strong> Patchy inhomogeneous airspace opacity with air bronchograms noted in the right mid and lower lung zones, suggestive of consolidation. The left lung field appears clear with normal bronchovascular markings.</p>\n<p><strong>COSTOPHRENIC ANGLES :</strong> Mild blunting of the right costophrenic angle noted, likely reactive minimal pleural fluid. The left costophrenic angle is clear and sharp.</p>\n<p><strong>DIAPHRAGMS :</strong> Right dome of diaphragm is partially obscured by the overlying lower lobe opacity. Left dome is smooth and normal in contour.</p>\n<p><strong>BONES & SOFT TISSUES :</strong> Visualized thoracic skeleton and surrounding soft tissues are unremarkable.</p>', 'Features suggestive of Right Middle and Lower Lobe Pneumonia with minimal reactive pleural effusion.\nAdvice: Clinical correlation, sputum examination, and follow-up after antibiotic therapy.', '1'),
('22', 'X-RAY BOTH KNEE JOINTS AP & LATERAL - Osteoarthritis', 'knee, osteoarthritis, joint space narrowing, osteophytes, pain, arthritis', 'X-Ray Both Knee Joints AP and Lateral View', '3', '3931', '<p><strong>JOINT SPACES :</strong> Narrowing of the medial tibiofemoral joint space noted bilaterally (Right > Left). Lateral tibiofemoral joint space is relatively preserved.</p>\n<p><strong>SUBCHONDRAL BONE :</strong> Subchondral sclerosis and flattening noted along the medial tibial plateau bilaterally.</p>\n<p><strong>OSTEOPHYTES :</strong> Marginal osteophytes seen along the femoral and tibial condylar articular margins.</p>\n<p><strong>PATELLOFEMORAL COMPARTMENT :</strong> Patellofemoral joint space shows mild narrowing with small patellar spurs.</p>\n<p><strong>LIGAMENTS & SOFT TISSUES :</strong> Visualized soft tissues around the knee joint appear normal. No radiopaque loose body or chondrocalcinosis seen.</p>\n<p><strong>BONE INTEGRITY :</strong> No fracture, dislocation, or lytic destructive bone lesion identified.</p>', 'Bilateral Knee Osteoarthritis with medial compartment predominance (Grade II-III Kellgren-Lawrence changes).\nAdvice: Clinical correlation and orthopedic consultation.', '1'),
('23', 'X-RAY LS SPINE AP & LATERAL - Lumbar Spondylosis', 'spine, lumbar, ls spine, back pain, spondylosis, osteophytes, disc reduction', 'X-Ray Lumbosacral (LS) Spine AP & Lateral View', '3', '3932', '<p><strong>ALIGNMENT & CURVATURE :</strong> Mild straightening of the normal lumbar lordosis noted, likely due to paravertebral muscle spasm. No spondylolisthesis or scoliosis seen.</p>\n<p><strong>VERTEBRAL BODIES :</strong> Vertebral body heights and bony architecture are maintained. Marginal osteophytic lipping noted along anterior and lateral borders of L3, L4, and L5 vertebrae.</p>\n<p><strong>INTERVERTEBRAL DISC SPACES :</strong> Reduced intervertebral disc spaces noted at L4-L5 and L5-S1 levels with mild vacuum phenomenon / subchondral sclerosis.</p>\n<p><strong>POSTERIOR ELEMENTS :</strong> Pedicles, laminae, and facet joints appear unremarkable. No lytic defect in pars interarticularis.</p>\n<p><strong>SACROILIAC JOINTS :</strong> Both sacroiliac joints are clear with preserved joint spaces.</p>\n<p><strong>PREVERTEBRAL TISSUES :</strong> Pre- and paravertebral soft tissue shadows are within normal limits.</p>', 'Features suggestive of Lumbar Spondylosis with L4-L5 and L5-S1 disc degenerative disease.\nAdvice: MRI Lumbosacral Spine recommended for radicular symptoms or neural canal evaluation.', '1'),
('24', 'X-RAY CERVICAL SPINE AP & LATERAL (Normal / Spondylosis)', 'cervical, neck pain, c-spine, spondylosis, radiculopathy, disc space', 'X-Ray Cervical Spine AP & Lateral View', '3', '3933', '<p><strong>ALIGNMENT :</strong> Normal cervical lordosis is mildly straightened (likely muscle spasm). Atlantoaxial alignment is normal.</p>\n<p><strong>VERTEBRAL BODIES :</strong> Vertebral body heights and densities are preserved. No bone destruction or compression fracture seen.</p>\n<p><strong>DISC SPACES :</strong> Mild reduction of C5-C6 intervertebral disc space noted with small anterior marginal osteophytes. Remaining disc spaces are preserved.</p>\n<p><strong>NEURAL FORAMINA & FACETS :</strong> Neural foramina and facet joints are within normal limits.</p>\n<p><strong>SOFT TISSUES :</strong> Prevertebral soft tissue thickness is normal at all levels.</p>', 'Features suggestive of Mild Cervical Spondylosis at C5-C6 level with muscle spasm.\nAdvice: Clinical correlation.', '1'),
('25', 'X-RAY ABDOMEN ERECT (Plain KUB / Acute Abdomen)', 'abdomen erect, air fluid levels, gas, bowel obstruction, perforation, kub, calculus', 'X-Ray Abdomen Erect (KUB)', '3', '3934', '<p><strong>BOWEL GAS PATTERN :</strong> Normal bowel gas distribution seen throughout small and large intestines. No pathologically dilated bowel loops.</p>\n<p><strong>AIR-FLUID LEVELS :</strong> No step-ladder air-fluid levels seen to suggest dynamic intestinal obstruction.</p>\n<p><strong>SUBDIAPHRAGMATIC AIR :</strong> No free air (crescent of gas) seen beneath either dome of the diaphragm (no pneumoperitoneum).</p>\n<p><strong>URINARY TRACT (KUB) :</strong> No radiopaque shadow or calculus identified along the anatomical course of the kidneys, ureters, or bladder.</p>\n<p><strong>PSOAS & FAT LINES :</strong> Bilateral psoas shadows and properitoneal fat lines are crisp and well preserved.</p>\n<p><strong>SKELETON :</strong> Visualized lumbar spine, pelvis, and rib cage show no gross bony abnormality.</p>', 'Normal Plain X-Ray Abdomen (Erect View). No evidence of bowel obstruction, perforation, or radiopaque calculus.', '0'),
('26', 'X-RAY PNS WATER\'S VIEW - Sinusitis', 'pns, water view, sinuses, maxillary, headache, sinusitis, polyps', 'X-Ray Paranasal Sinuses (PNS - Water\'s View)', '3', '3935', '<p><strong>MAXILLARY SINUSES :</strong> Mucosal thickening and mucosal haziness noted in the bilateral maxillary antra (Right > Left). No distinct air-fluid level or polypoid mass seen.</p>\n<p><strong>FRONTAL & ETHMOID SINUSES :</strong> Frontal and ethmoidal sinuses appear normally pneumatized and aerated.</p>\n<p><strong>NASAL SEPTUM & TURBINATES :</strong> Mild deviation of the nasal septum (DNS) noted towards the left with compensatory hypertrophy of the right inferior turbinate.</p>\n<p><strong>BONY WALLS :</strong> Bony margins of all visualized paranasal sinuses are intact without cortical erosion.</p>', 'Features suggestive of Bilateral Maxillary Sinusitis (Right > Left) with Mild DNS.\nAdvice: ENT correlation.', '1'),
('27', 'NCCT HEAD / BRAIN (Normal)', 'ct head, brain, normal, stroke, trauma, headache, ncct, ventricles', 'Non-Contrast CT (NCCT) Head / Brain', '4', '3937', '<p><strong>TECHNIQUE :</strong> Non-contrast axial CT sections of the brain were obtained from the base of the skull to the vertex without intravenous contrast.</p>\n<p><strong>BRAIN PARENCHYMA :</strong> Both cerebral hemispheres, cerebellum, and brainstem show normal attenuation and preserved grey-white matter differentiation. No focal hypo- or hyperdense lesions noted. No evidence of acute intra-axial or extra-axial hemorrhage.</p>\n<p><strong>VENTRICULAR SYSTEM :</strong> Lateral, third, and fourth ventricles are normal in size, shape, and position for age. No hydrocephalus.</p>\n<p><strong>BASAL CISTERNS & SULCI :</strong> Basal cisterns, cortical sulci, and sylvian fissures are well visualized and symmetrical.</p>\n<p><strong>MIDLINE STRUCTURES :</strong> Midline structures are central; no midline shift or herniation seen.</p>\n<p><strong>SELLA & POSTERIOR FOSSA :</strong> Sella, parasellar regions, and cerebellopontine angles are unremarkable.</p>\n<p><strong>CALVARIUM & ORBITS :</strong> Calvarial bones, skull base, orbits, and visualized paranasal sinuses show no fracture or gross pathology.</p>', 'Normal Non-Contrast CT Scan of the Brain. No acute intracranial hemorrhage, mass lesion, or midline shift.', '0'),
('28', 'NCCT HEAD - Acute Ischemic Infarct', 'ct head, infarct, ischemic stroke, mca, paralysis, weakness, hypodensity', 'NCCT Head - Acute Ischemic Infarct', '4', '3938', '<p><strong>TECHNIQUE :</strong> Non-contrast volumetric CT of the brain performed under acute stroke protocol.</p>\n<p><strong>FOCAL LESION :</strong> Ill-defined, wedgeshaped area of parenchymal hypodensity noted involving the cortex and subcortical white matter of the left / right middle cerebral artery (MCA) territory.</p>\n<p><strong>MASS EFFECT :</strong> Associated local sulcal effacement and mild loss of insular ribbon sign / grey-white differentiation noted. No significant midline shift or compression of lateral ventricle.</p>\n<p><strong>HEMORRHAGE :</strong> No hyperdense area seen to suggest intracranial hemorrhage or hemorrhagic transformation.</p>\n<p><strong>POSTERIOR FOSSA :</strong> Cerebellum, brainstem, and posterior fossa cisterns appear unremarkable.</p>\n<p><strong>BONES & CISTERNS :</strong> Calvarial bones and visualized sinuses are intact.</p>', 'Features suggestive of Acute Non-Hemorrhagic Ischemic Infarct in the Left / Right MCA territory.\nAdvice: Urgent neurological evaluation, MRI Brain with DWI, and MR Angiography.', '1'),
('29', 'HRCT CHEST / THORAX (Normal)', 'hrct chest, thorax, lungs, covid, interstitial, fibrosis, ggo, bronchiectasis', 'High Resolution Computed Tomography (HRCT) Thorax', '4', '3939', '<p><strong>TECHNIQUE :</strong> High-resolution thin-section volumetric CT scan of the thorax was performed from lung apices to diaphragm during full inspiratory breath-hold.</p>\n<p><strong>AIRWAYS :</strong> Trachea and major bronchi are normal in caliber, course, and branching pattern. No endobronchial lesion or bronchiectasis seen.</p>\n<p><strong>LUNG PARENCHYMA :</strong> Both lung fields show normal parenchymal attenuation. No evidence of ground-glass opacities (GGO), consolidation, nodule, mass, or cavitation. Interlobular septa and bronchovascular interstitium are unremarkable. No honeycombing or reticulation.</p>\n<p><strong>PLEURAL SPACES :</strong> Bilateral pleural spaces are clear. No pneumothorax, pleural effusion, or thickening noted.</p>\n<p><strong>MEDIASTINUM & HILA :</strong> Mediastinum and hilar structures are normal. No significant mediastinal, hilar, or axillary lymphadenopathy seen.</p>\n<p><strong>CARDIOVASCULAR :</strong> Heart size, ascending/descending aorta, and pulmonary trunk are within normal limits.</p>\n<p><strong>CHEST WALL & BONES :</strong> Visualized thoracic skeleton, sternum, ribs, and soft tissues of the chest wall appear normal.</p>', 'Normal HRCT Thorax study. No active parenchymal infiltration, interstitial lung disease (ILD), or lymphadenopathy.', '0'),
('30', 'CECT WHOLE ABDOMEN & PELVIS (Normal)', 'cect abdomen, pelvis, liver, kidney, pancreas, spleen, contrast, ct abdomen', 'Contrast Enhanced CT (CECT) Whole Abdomen and Pelvis', '4', '3940', '<p><strong>TECHNIQUE :</strong> Contrast-enhanced helical CT of the whole abdomen and pelvis was acquired after administration of non-ionic IV contrast.</p>\n<p><strong>LIVER :</strong> Normal in size and shape with homogenous parenchymal enhancement. No focal intrahepatic mass, cyst, or abscess. Intrahepatic biliary radicles (IHBR) and common bile duct are normal.</p>\n<p><strong>GALLBLADDER :</strong> Well distended with normal, uniform wall enhancement. No radiopaque calculus or pericholecystic collection seen.</p>\n<p><strong>PANCREAS :</strong> Normal in size, lobulation, and enhancement throughout head, body, and tail. Main pancreatic duct is not dilated. Peripancreatic fat planes are preserved.</p>\n<p><strong>SPLEEN :</strong> Normal in size, configuration, and enhancement. No focal lesion.</p>\n<p><strong>ADRENALS & KIDNEYS :</strong> Bilateral adrenals are normal. Both kidneys are normal in size, shape, and position with prompt symmetrical nephrogram and excretion. Corticomedullary differentiation is preserved. No calculus, hydronephrosis, or mass.</p>\n<p><strong>URINARY BLADDER & PELVIS :</strong> Urinary bladder is well distended with smooth walls. Internal pelvic organs are normal for age.</p>\n<p><strong>GASTROINTESTINAL TRACT :</strong> Stomach and small/large bowel loops show normal caliber, wall thickness, and mucosal enhancement. No bowel obstruction.</p>\n<p><strong>VESSELS & LYMPH NODES :</strong> Abdominal aorta, IVC, and portal vein are patent. No retroperitoneal, mesenteric, or pelvic lymphadenopathy. No ascites.</p>', 'Normal Contrast-Enhanced CT (CECT) of Whole Abdomen and Pelvis. No focal pathology, organomegaly, or lymphadenopathy.', '0'),
('31', 'NCCT KUB - Ureteric / Renal Calculus', 'ncct kub, stone, calculus, kidney stone, ureteric stone, hydronephrosis, colic', 'Non-Contrast CT (NCCT) Kidneys, Ureters, and Bladder (KUB)', '4', '3941', '<p><strong>TECHNIQUE :</strong> Non-contrast helical CT scan of the abdomen and pelvis obtained from top of kidneys to pubic symphysis.</p>\n<p><strong>KIDNEYS :</strong> Both kidneys are normal in size, shape, and anatomical position. Right kidney measures ~... cm and left kidney measures ~... cm. No focal parenchymal mass lesion.</p>\n<p><strong>CALCULUS & HYDRONEPHROSIS :</strong> A dense radiopaque calculus measuring approximately ... mm (CT density ~ ... HU) is noted in the proximal / mid / distal right / left ureter. Associated mild-to-moderate upstream hydroureter and hydronephrosis seen with mild perinephric fat stranding.</p>\n<p><strong>CONTRALATERAL SYSTEM :</strong> Contralateral kidney and ureter are unremarkable without calculus or hydronephrosis.</p>\n<p><strong>URINARY BLADDER :</strong> Moderately distended with uniform contents. No calculus or focal wall thickening seen at the vesicoureteric junctions.</p>\n<p><strong>BONES & SOFT TISSUES :</strong> Visualized lumbosacral skeleton and pelvic bones appear unremarkable.</p>', 'Features suggestive of a ... mm Calculus in the Right / Left Ureter causing mild-to-moderate upstream hydronephrosis and hydroureter.\nAdvice: Urology consultation and management.', '1'),
('32', 'MRI BRAIN (PLAIN STUDY - Normal)', 'mri brain, normal, head, t1, t2, flair, dwi, stroke, seizure, headache', 'MRI Brain (Plain Study)', '2', '3944', '<p><strong>TECHNIQUE :</strong> Multiplanar, multisequence MRI of the brain was performed on high-field system using T1WI, T2WI, FLAIR, Diffusion Weighted Imaging (DWI/ADC), and Gradient Echo (GRE/SWI) sequences.</p>\n<p><strong>CEREBRAL PARENCHYMA :</strong> Both cerebral hemispheres show normal sulcation, gyration, and grey-white matter differentiation. No focal area of altered signal intensity noted in the cerebral cortex, subcortical white matter, or deep grey nuclei.</p>\n<p><strong>DIFFUSION & HEMORRHAGE :</strong> No area of restricted diffusion on DWI/ADC to suggest acute ischemic infarction or cytotoxic edema. No blooming artifact on GRE/SWI sequences to suggest acute or chronic intracranial hemorrhage.</p>\n<p><strong>BRAINSTEM & CEREBELLUM :</strong> Brainstem (midbrain, pons, medulla) and both cerebellar hemispheres appear normal in morphology and signal characteristics.</p>\n<p><strong>VENTRICLES & CISTERNS :</strong> Ventricular system, basal cisterns, and sylvian fissures are normal in size, shape, and configuration for age. Midline structures are central.</p>\n<p><strong>SELLA & CRANIAL NERVES :</strong> Sella, pituitary gland, optic chiasm, and bilateral CP angles are within normal limits.</p>\n<p><strong>CALVARIUM & SINUSES :</strong> Visualized calvarial marrow and paranasal sinuses show normal signal intensity.</p>', 'Normal MRI Brain Study. No evidence of acute ischemia, hemorrhage, mass effect, or demyelinating lesion.', '0'),
('33', 'MRI LUMBOSACRAL (LS) SPINE - Disc Herniation / Sciatica', 'mri spine, ls spine, lumbar, disc bulge, herniation, sciatica, radiculopathy, stenosis', 'MRI Lumbosacral (LS) Spine', '2', '3946', '<p><strong>TECHNIQUE :</strong> Multiplanar MRI of the lumbosacral spine performed in T1W, T2W, and STIR sagittal and axial sequences.</p>\n<p><strong>CURVATURE & ALIGNMENT :</strong> Mild straightening of the normal lumbar lordosis noted, consistent with paravertebral muscle spasm. Vertebral body alignment is preserved without listhesis.</p>\n<p><strong>VERTEBRAL BODIES :</strong> Vertebral body heights are maintained. No acute compression fracture, bone marrow edema, or focal marrow infiltration seen on STIR.</p>\n<p><strong>L4-L5 LEVEL :</strong> Shows diffuse disc bulge with a central/paracentral posterior disc protrusion compromising the anterior epidural space and indenting the thecal sac. Mild narrowing of bilateral neural foramina with abutment of traversing L5 nerve roots.</p>\n<p><strong>L5-S1 LEVEL :</strong> Shows mild diffuse posterior disc bulge with preserved neural exit foramina and no significant canal compromise.</p>\n<p><strong>OTHER DISC LEVELS :</strong> L1-L2, L2-L3, and L3-L4 intervertebral disc spaces and disc hydration are well preserved.</p>\n<p><strong>SPINAL CORD & CAUDA EQUINA :</strong> Conus medullaris ends normally at the L1-L2 level with normal signal intensity. Cauda equina nerve roots are normal in distribution.</p>\n<p><strong>PARASPINAL TISSUES :</strong> Visualized facet joints, posterior elements, and paraspinal soft tissues are unremarkable.</p>', 'Features suggestive of L4-L5 Central/Paracentral Disc Protrusion causing thecal sac indentation and bilateral neural foraminal narrowing with nerve root abutment. Associated Lumbar Spondylodisco-degenerative changes.\nAdvice: Clinical and neurological correlation.', '1'),
('34', 'MRI CERVICAL SPINE - Cervical Spondylosis', 'mri c-spine, cervical, neck pain, disc protrusion, myelopathy, cord compression', 'MRI Cervical Spine', '2', '3947', '<p><strong>TECHNIQUE :</strong> Multiplanar MRI of the cervical spine acquired in sagittal T1WI, T2WI, STIR, and axial T2WI sequences.</p>\n<p><strong>ALIGNMENT :</strong> Straightening of normal cervical lordosis noted, suggestive of muscle spasm. Craniocervical junction is normal.</p>\n<p><strong>VERTEBRAE & MARROW :</strong> Vertebral body heights and alignment are maintained. No evidence of fracture or marrow replacing lesion.</p>\n<p><strong>C5-C6 LEVEL :</strong> Shows posterior disc-osteophyte complex with left paracentral disc herniation indenting the anterior thecal sac and narrowing the left neural foramen with abutment of exiting left C6 nerve root.</p>\n<p><strong>C6-C7 LEVEL :</strong> Shows mild diffuse disc bulge without significant thecal sac indentation.</p>\n<p><strong>CERVICAL CORD :</strong> Cervical spinal cord is normal in caliber throughout its course with uniform signal intensity. No focal T2/STIR hyperintensity to suggest compressive myelopathy, syrinx, or demyelination.</p>\n<p><strong>SOFT TISSUES :</strong> Prevertebral and posterior paraspinal soft tissues are normal.</p>', 'Features suggestive of Cervical Spondylosis with C5-C6 Posterior Disc Herniation causing left neural foraminal narrowing and root impingement.\nNo compressive cervical myelopathy.', '1'),
('35', 'MRI KNEE JOINT - Meniscal & Ligament Assessment', 'mri knee, acl, pcl, meniscus, tear, knee pain, effusion, cartilage, ligament', 'MRI Knee Joint (Right / Left)', '2', '3948', '<p><strong>TECHNIQUE :</strong> Multiplanar MRI of the knee joint was performed using PD, PD-FS, T1WI, and T2-GRE sequences in coronal, sagittal, and axial planes.</p>\n<p><strong>MEDIAL MENISCUS :</strong> Grade II intrameniscal linear hyperintensity seen in the posterior horn of the medial meniscus, not extending to the superior or inferior articular surfaces (suggestive of intrasubstance degeneration without tear).</p>\n<p><strong>LATERAL MENISCUS :</strong> Anterior and posterior horns of the lateral meniscus show normal triangular morphology and uniform low signal intensity. No tear seen.</p>\n<p><strong>CRUCIATE LIGAMENTS :</strong> Anterior Cruciate Ligament (ACL) and Posterior Cruciate Ligament (PCL) show normal course, thickness, and signal intensity. Fibers are continuous and intact.</p>\n<p><strong>COLLATERAL LIGAMENTS :</strong> Medial Collateral Ligament (MCL) and Lateral Collateral Ligament complex (LCL) are intact with normal appearances.</p>\n<p><strong>EXTENSOR MECHANISM :</strong> Quadriceps tendon and patellar tendon show normal signal intensity. Patellofemoral cartilage is preserved.</p>\n<p><strong>JOINT EFFUSION & BONE MARROW :</strong> Mild joint effusion noted in the suprapatellar pouch. No subchondral bone marrow edema or osteochondral defect noted in femoral condyles or tibial plateau.</p>', 'Grade II Degenerative Signal Change in the Posterior Horn of the Medial Meniscus.\nMild knee joint effusion. Intact ACL, PCL, and collateral ligaments.', '1'),
('36', 'MRI WHOLE SPINE SCREENING (Normal)', 'mri whole spine, screening, metastasis, cord, sagittal t2, stir, normal spine', 'MRI Whole Spine Screening', '2', '3949', '<p><strong>TECHNIQUE :</strong> Sagittal T2WI and STIR screening images of the entire spine from craniocervical junction to coccyx.</p>\n<p><strong>CURVATURE & ALIGNMENT :</strong> Normal cervical, thoracic, and lumbar spinal curvatures and vertebral alignment are preserved.</p>\n<p><strong>VERTEBRAL BODIES :</strong> Vertebral body heights and marrow signal intensities are normal across all levels. No focal bone destruction, collapse, or STIR marrow hyperintensity to suggest metastasis or trauma.</p>\n<p><strong>DISC SPACES :</strong> Intervertebral disc heights and signals are generally preserved with early mild degenerative disc dehydration at L4-L5 and L5-S1 levels. No gross disc herniation or spinal canal stenosis.</p>\n<p><strong>SPINAL CORD :</strong> Spinal cord shows normal caliber and signal intensity throughout cervical and thoracic regions. Conus medullaris terminates normally at L1 level.</p>\n<p><strong>PARASPINAL TISSUES :</strong> Pre- and paravertebral soft tissues are unremarkable.</p>', 'Normal MRI Whole Spine Screening study. No focal marrow infiltrative lesion, vertebral collapse, or spinal cord compression.', '0');
