INSERT INTO `settings` (`id`, `class`, `key`, `value`, `type`, `context`, `created_at`, `updated_at`) VALUES
('1', 'Config\\AuthGroups', 'groups', 'a:15:{s:16:\"accounts_officer\";a:2:{s:5:\"title\";s:16:\"Accounts Officer\";s:11:\"description\";s:60:\"Accepts/verifies billing statements and audits bank records.\";}s:5:\"admin\";a:2:{s:5:\"title\";s:5:\"Admin\";s:11:\"description\";s:38:\"Day to day administrators of the site.\";}s:4:\"beta\";a:2:{s:5:\"title\";s:9:\"Beta User\";s:11:\"description\";s:34:\"Has access to beta-level features.\";}s:15:\"billing_cashier\";a:2:{s:5:\"title\";s:15:\"Billing Cashier\";s:11:\"description\";s:44:\"Submits billing cash statements to accounts.\";}s:15:\"department_head\";a:2:{s:5:\"title\";s:15:\"Department Head\";s:11:\"description\";s:46:\"Creates and tracks departmental stock indents.\";}s:9:\"developer\";a:2:{s:5:\"title\";s:9:\"Developer\";s:11:\"description\";s:17:\"Site programmers.\";}s:6:\"doctor\";a:2:{s:5:\"title\";s:6:\"Doctor\";s:11:\"description\";s:80:\"Clinical doctor access to OPD work, diagnosis reports, and immunization records.\";}s:5:\"nurse\";a:2:{s:5:\"title\";s:5:\"Nurse\";s:11:\"description\";s:77:\"In-patient nursing records, bedside care, bed transfers, and nursing charges.\";}s:14:\"pharmacy_admin\";a:2:{s:5:\"title\";s:14:\"Pharmacy Admin\";s:11:\"description\";s:71:\"Full pharmacy controls including old bill edits and discount overrides.\";}s:12:\"stock_issuer\";a:2:{s:5:\"title\";s:12:\"Stock Issuer\";s:11:\"description\";s:72:\"Compatibility role for users who issue stock and receive purchase stock.\";}s:13:\"stock_manager\";a:2:{s:5:\"title\";s:13:\"Stock Manager\";s:11:\"description\";s:50:\"Manages stock masters, approvals, and procurement.\";}s:15:\"stock_requester\";a:2:{s:5:\"title\";s:15:\"Stock Requester\";s:11:\"description\";s:54:\"Compatibility role for users who create stock indents.\";}s:11:\"storekeeper\";a:2:{s:5:\"title\";s:11:\"Storekeeper\";s:11:\"description\";s:53:\"Handles item issuance and stock receiving operations.\";}s:10:\"superadmin\";a:2:{s:5:\"title\";s:11:\"Super Admin\";s