  `police_station` varchar(120) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `police_constable_details` varchar(150) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `brought_by` varchar(120) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `daycare_procedure_name` varchar(255) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `converted_from_type` varchar(20) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `converted_from_code` varchar(50) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `converted_at` datetime DEFAULT NULL,
  `conversion_reason` text COLLATE utf8mb3_unicode_ci,
