  `register_date` date DEFAULT NULL,
  `reg_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `reg_time_bak` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `ipd_status` int DEFAULT '0',
  `case_id` int DEFAULT '0',
  `insert_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `insert_by` int DEFAULT NULL,
  `Discount` decimal(10,2) DEFAULT '0.00',
  `Discount_By` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `Discount_Remark` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `Discount2` decimal(10,2) DEFAULT '0.00',
  `Discount_By2` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `Discount_Remark2` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `Discount3` decimal(10,2) DEFAULT '0.00',
  `Discount_By3` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `Discount_Remark3` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `charge1` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `charge2` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `chargeamount1` decimal(10,2) DEFAULT '0.00',
  `chargeamount2` decimal(10,2) DEFAULT '0.00',
  `charge_by1` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `charge_by2` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_by` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_remark` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `discharge_date` date DEFAULT NULL,
  `discharge_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_time_ampm` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_time_bak` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_balance_remark` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discharge_balance_user` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `charge_amount` decimal(10,2) DEFAULT '0.00',
  `package_charge_amount` decimal(10,2) DEFAULT '0.00',
  `med_amount` decimal(10,2) DEFAULT '0.00',
  `cash_med_amount` decimal(10,2) DEFAULT '0.00',
  `package_med_amount` decimal(10,2) DEFAULT '0.00',
  `med_paid` decimal(10,2) DEFAULT '0.00',
  `gross_amount` decimal(10,2) DEFAULT '0.00',
  `total_paid_amount` decimal(10,2) DEFAULT '0.00',
  `org_amount_recived` decimal(10,2) DEFAULT '0.00',
  `net_amount` decimal(10,2) DEFAULT '0.00',
  `balance_amount` decimal(10,2) DEFAULT '0.00',
  `lock_medical` int DEFAULT '0',
  `lock_remark` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `discarge_patient_status` int DEFAULT '0' COMMENT '0 Admit,1 Improved,2 Lama,3 Referred,4 Satisfactory,5-Expired,6-Admission Cancelled',
  `ipd_times` int DEFAULT '1',
  `issurgery` int DEFAULT '0',
  `surgery_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `surgery_date` date DEFAULT NULL,
  `isdelivery` int DEFAULT '0',
  `no_baby` int DEFAULT '0',
  `delivery_date` date DEFAULT NULL,
  `delivery_time` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `delivery_sex_of_baby` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `delivery_sex_of_baby2` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `delivery_sex_of_baby3` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `correct_dis` int DEFAULT '0',
  `corr_dis_per` int DEFAULT '0',
  `give_dis_per` decimal(10,2) DEFAULT '0.00',
  `log` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci,
  `update_back` int DEFAULT '0',
  `payable_by_tpa` decimal(20,2) DEFAULT '0.00',
  `discount_by_hospital_remark` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discount_by_hospital` decimal(20,2) DEFAULT '0.00',
  `discount_by_hospital_2_remark` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `discount_by_hospital_2` decimal(20,2) DEFAULT '0.00',
  `discount_for_tpa` decimal(20,2) DEFAULT '0.00',
  `balance_discount_after` decimal(20,2) DEFAULT '0.00',
  `refer_by` int DEFAULT NULL COMMENT 'refer_master->id',
  `ipd_create` int DEFAULT '0',
  `ipd_billed_time` datetime DEFAULT NULL,
  `ipd_discharge_ready_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `p_id` (`p_id`),
  KEY `Index_ipd` (`p_id`,`P_mobile1`,`P_mobile2`,`contact_person_Name`,`policy_no`,`ipd_code`,`r_doc_id`,`register_date`,`case_id`,`insert_by`),
  KEY `Discount3` (`Discount3`),
  KEY `Discount2` (`Discount2`),
  KEY `ipd_times` (`ipd_times`),
  KEY `update_back` (`update_back`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

