-- ------------------------------------------------------------
-- Table structure for `ipd_ot_cases`
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `ipd_ot_cases` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `request_no` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
