  `procedure_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `procedure_side` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'not_applicable',
  `priority` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'routine',
  `requested_date` date NOT NULL,
  `requested_time` time DEFAULT NULL,
  `requested_notes` text COLLATE utf8mb4_general_ci,
  `scheduled_start_at` datetime DEFAULT NULL,
  `surgeon_id` int unsigned NOT NULL DEFAULT '0',
  `surgeon_name_snapshot` varchar(180) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `anesthetist_id` int unsigned NOT NULL DEFAULT '0',
  `anesthetist_name_snapshot` varchar(180) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `status` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'requested',
  `call_status` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'not_called',
  `called_at` datetime DEFAULT NULL,
  `called_by` int unsigned NOT NULL DEFAULT '0',
  `confirmed_at` datetime DEFAULT NULL,
  `confirmed_by` int unsigned NOT NULL DEFAULT '0',
  `consent_verified` tinyint(1) NOT NULL DEFAULT '0',
  `site_side_verified` tinyint(1) NOT NULL DEFAULT '0',
  `allergy_verified` tinyint(1) NOT NULL DEFAULT '0',
  `npo_verified` tinyint(1) NOT NULL DEFAULT '0',
  `investigations_verified` tinyint(1) NOT NULL DEFAULT '0',
  `anesthesia_clearance` tinyint(1) NOT NULL DEFAULT '0',
  `blood_availability` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'not_required',
  `who_sign_in` tinyint(1) NOT NULL DEFAULT '0',
  `who_time_out` tinyint(1) NOT NULL DEFAULT '0',
  `who_sign_out` tinyint(1) NOT NULL DEFAULT '0',
  `actual_start_at` datetime DEFAULT NULL,
  `actual_end_at` datetime DEFAULT NULL,
  `lock_version` int unsigned NOT NULL DEFAULT '0',
  `created_by` int unsigned NOT NULL DEFAULT '0',
  `updated_by` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
