  KEY `idx_ipd_ot_queue` (`scheduled_start_at`,`department_id`,`status`),
  KEY `idx_ipd_ot_admission` (`ipd_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------
