  `request_by` int DEFAULT NULL,
  `request_by_name` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT NULL,
  `request_time` datetime DEFAULT NULL,
  `approved_by` int DEFAULT NULL,
  `approved_status` int DEFAULT '0' COMMENT '0 Pending,1 Accept,2 For Revise,3 Decline',
  `approved_log` tinytext CHARACTER SET utf32 COLLATE utf32_unicode_ci,
  `approved_by_name` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT NULL,
  `approved_time` datetime DEFAULT NULL,
  `accept_by` int DEFAULT NULL,
  `accept_by_name` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT NULL,
  `accept_time` datetime DEFAULT NULL,
  `log_text` text CHARACTER SET utf32 COLLATE utf32_unicode_ci,
  PRIMARY KEY (`deliver_id`),
  UNIQUE KEY `indent_code` (`indent_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf32 COLLATE=utf32_unicode_ci ROW_FORMAT=DYNAMIC;

