  `patient_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Walk-in Customer',
  `uhid` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `patient_mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bed_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ward_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `doctor_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_items` int NOT NULL DEFAULT '0',
  `estimated_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `items_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
