CREATE TABLE IF NOT EXISTS `mst_grn_items` (
  `grn_item_id` int unsigned NOT NULL AUTO_INCREMENT,
  `grn_id` int unsigned NOT NULL,
  `po_item_id` int unsigned DEFAULT NULL,
  `item_code` int NOT NULL,
  `item_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `batch_no` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `expiry_date` date NOT NULL,
  `packing` int NOT NULL DEFAULT '1',
  `order_packs` decimal(10,2) NOT NULL DEFAULT '0.00',
  `received_packs` decimal(10,2) NOT NULL DEFAULT '0.00',
  `free_packs` decimal(10,2) NOT NULL DEFAULT '0.00',
  `rejected_packs` decimal(10,2) NOT NULL DEFAULT '0.00',
  `rejection_reason` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `unit_purchase_rate` decimal(10,2) NOT NULL DEFAULT '0.00',
  `gross_amount` decimal(12,2) DEFAULT '0.00',
  `mrp` decimal(10,2) NOT NULL DEFAULT '0.00',
  `selling_unit_rate` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `sch_disc_per` decimal(5,2) DEFAULT '0.00',
  `sch_disc_amt` decimal(10,2) DEFAULT '0.00',
  `taxable_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cgst_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `cgst_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sgst_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `sgst_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `igst_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `igst_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `hsn_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `total_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `rack_no` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shelf_no` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cold_storage` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `purchase_item_id` int DEFAULT NULL,
  PRIMARY KEY (`grn_item_id`),
  KEY `grn_id` (`grn_id`),
  KEY `item_code` (`item_code`),
  KEY `po_item_id` (`po_item_id`),
  KEY `purchase_item_id` (`purchase_item_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

