CREATE TABLE IF NOT EXISTS `mst_grns` (
  `grn_id` int unsigned NOT NULL AUTO_INCREMENT,
  `grn_number` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `store_id` int NOT NULL DEFAULT '1',
