  `challan_no` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `supplier_invoice_no` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `invoice_date` date NOT NULL,
  `grn_date` date NOT NULL,
  `total_received_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_tax_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `cgst_amount` decimal(10,2) DEFAULT '0.00',
  `sgst_amount` decimal(10,2) DEFAULT '0.00',
  `igst_amount` decimal(10,2) DEFAULT '0.00',
  `round_off` decimal(6,2) DEFAULT '0.00',
  `gst_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT 'intra_state',
  `net_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft',
  `purchase_id` int DEFAULT NULL,
  `received_by` int DEFAULT NULL,
  `verified_by` int DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`grn_id`),
  KEY `grn_number` (`grn_number`),
  KEY `po_id` (`po_id`),
  KEY `supplier_id` (`supplier_id`),
  KEY `status` (`status`),
  KEY `purchase_id` (`purchase_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

