  PRIMARY KEY (`purchase_item_id`),
  KEY `idx_purchase` (`purchase_id`),
  KEY `idx_item` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

