  `item_id` int NOT NULL,
  `batch_id` int DEFAULT NULL,
  `requested_qty` int NOT NULL,
  `dispatched_qty` int DEFAULT '0',
  `received_qty` int DEFAULT '0',
  PRIMARY KEY (`transfer_item_id`),
