CREATE TABLE IF NOT EXISTS `opd_appointment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `HCODE` int NOT NULL DEFAULT '0',
  `doc_id` int NOT NULL DEFAULT '0',
  `dept_id` int NOT NULL DEFAULT '0',
  `opd_date` date DEFAULT '0000-00-00',
  `opd_day_slot` int DEFAULT '0',
  `opd_no` int DEFAULT '0',
  `p_id` int DEFAULT '0',
  `last_opd_no` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT '0',
  `pname` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT '0',
  `phone_no` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT '0',
  `update_mehod` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci DEFAULT '0' COMMENT '0 for system,1 for App,2 for call,3 for SMS',
  `update_status` int DEFAULT '0' COMMENT '0 Pending,1 Confirm,2 Cancel',
  `assign_opd_id` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `phone_no` (`phone_no`),
  KEY `opd_date_opd_day_slot_opd_no_p_id` (`opd_date`,`opd_day_slot`,`opd_no`,`p_id`),
  KEY `assign_opd_id` (`assign_opd_id`),
  KEY `HCODE_doc_id` (`HCODE`,`doc_id`),
  KEY `HCODE_dept_id` (`HCODE`,`dept_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf32 COLLATE=utf32_unicode_ci;

