-- ------------------------------------------------------------
-- Table structure for `opd_master`
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `opd_master` (
  `opd_id` int NOT NULL AUTO_INCREMENT,
  `opd_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '0',
  `p_id` int DEFAULT NULL,
  `P_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `opd_book_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `apointment_date` datetime DEFAULT NULL COMMENT 'Appointment date and time',
  `opd_spec_id` int DEFAULT NULL,
  `opd_no` int DEFAULT NULL,
  `doc_id` int DEFAULT NULL,
  `payout_draft_id` int unsigned DEFAULT NULL,
  `payout_calculated_at` datetime DEFAULT NULL,
  `payout_calculated_by` varchar(120) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `doc_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `doc_spec` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `insurance_id` int DEFAULT '0',
  `insurance_case_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT '0',
  `opd_fee_type` int DEFAULT '0',
  `opd_fee_id` int DEFAULT NULL,
  `opd_fee_gross_amount` decimal(10,2) DEFAULT NULL,
  `opd_discount` decimal(10,2) DEFAULT '0.00',
  `opd_disc_remark` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `opd_disc_update_by` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `opd_fee_amount` decimal(10,2) DEFAULT '0.00',
  `opd_fee_amount_1` decimal(10,2) DEFAULT '0.00',
  `opd_fee_desc` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `opd_status` int DEFAULT '1',
  `opd_status_remark` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `payment_status` int DEFAULT '0' COMMENT '0 Pending,1 Confirm',
  `payment_id` int DEFAULT '0',
  `payment_mode` int DEFAULT '0' COMMENT '0 Pending,1 cash , 2 Card,3 ECHS Credit',
  `payment_mode_desc` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT '0',
  `confirm_pay_opd` datetime DEFAULT NULL,
  `prepared_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `prepared_by_id` int DEFAULT NULL,
  `running_opd` int DEFAULT '0',
  `running_opd_id` int DEFAULT '0',
  `last_opdvisit_date` date DEFAULT NULL,
  `no_visit` int DEFAULT '0',
  `online_book` int DEFAULT '0',
  PRIMARY KEY (`opd_id`),
  KEY `p_id` (`p_id`),
  KEY `opd_code` (`opd_code`),
  KEY `ech_clam_id` (`insurance_case_id`),
  KEY `prepared_by` (`prepared_by`),
  KEY `opd_status` (`opd_status`),
  KEY `P_name` (`P_name`),
  KEY `opd_apointment_date_doc` (`opd_id`,`opd_code`,`p_id`,`opd_book_date`,`apointment_date`,`doc_id`,`opd_status`,`insurance_case_id`) USING BTREE,
  KEY `online_book` (`online_book`),
  KEY `opd_id_p_id_apointment_date_insurance_id` (`opd_id`,`p_id`,`apointment_date`,`insurance_id`),
