-- ------------------------------------------------------------
-- Table structure for `opd_snomed_suggestions`
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `opd_snomed_suggestions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `opd_id` int unsigned NOT NULL DEFAULT '0',
  `opd_session_id` int unsigned NOT NULL DEFAULT '0',
  `source_field` varchar(60) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `source_phrase` varchar(500) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `concept_id` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `snomed_term` varchar(500) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `semantic_tag` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `confidence` decimal(5,3) NOT NULL DEFAULT '0.000',
  `status` enum('pending_review','confirmed','rejected','corrected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending_review',
  `corrected_concept_id` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `corrected_term` varchar(500) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `reviewed_by` int DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `opd_session_id_source_field` (`opd_session_id`,`source_field`),
  KEY `status` (`status`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ------------------------------------------------------------
-- Table structure for `opd_visit_list`
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `opd_visit_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `p_id` int NOT NULL DEFAULT '0',
  `p_name` varchar(50) CHARACTER SET utf32 COLLATE utf32_unicode_ci NOT NULL DEFAULT '0',
  `opd_id` int NOT NULL DEFAULT '0',
  `opd_type` int NOT NULL DEFAULT '0',
  `running_opd` int NOT NULL DEFAULT '0',
