  `amount_claim` decimal(10,2) DEFAULT NULL,
  `amount_tds` decimal(10,2) DEFAULT NULL,
  `amount_direct` decimal(10,2) DEFAULT NULL,
  `amount_update_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `amount_payment_info` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
