  KEY `p_id` (`p_id`),
  KEY `insurance_id` (`insurance_id`),
  KEY `p_phone_number` (`p_phone_number`),
  KEY `date_registration` (`date_registration`),
  KEY `case_id_code` (`case_id_code`),
  KEY `insurance_card_name` (`insurance_card_name`),
  KEY `insurance_no` (`insurance_no`),
  KEY `insurance_no_1` (`insurance_no_1`),
  KEY `insurance_no_insurance_no_1` (`insurance_no`,`insurance_no_1`),
  KEY `case_for_ipd` (`ipd_id`),
  KEY `case_type` (`case_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

