-- ------------------------------------------------------------
-- Table structure for `ward_master`
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `ward_master` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ward_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ward_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `department_id` int NOT NULL,
  `nursing_station_id` int DEFAULT NULL,
  `building_id` int DEFAULT NULL,
  `floor_number` int DEFAULT NULL,
  `ward_type` enum('General','Private','Semi-Private','Deluxe','ICU','NICU','PICU','HDU','ICCU','CCU','Emergency','Day Care') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'General',
  `gender_type` enum('male','female','unisex') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'unisex',
  `ward_category` enum('adult','pediatric','maternity','isolation','surgical','medical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'adult',
  `total_capacity` int NOT NULL DEFAULT '0',
  `nurse_station_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `has_oxygen` tinyint(1) DEFAULT '0',
  `has_suction` tinyint(1) DEFAULT '0',
  `has_monitor` tinyint(1) DEFAULT '0',
  `status` enum('active','inactive','under_maintenance') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ward_code` (`ward_code`),
  KEY `idx_dept` (`department_id`),
  KEY `idx_building` (`building_id`),
  KEY `idx_ward_type` (`ward_type`),
  KEY `idx_gender` (`gender_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

